INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P1','Nguyễn Minh (阮明)',22,'Du học sinh Việt Nam mới đến Trung Quốc, học Thương mại quốc tế','Lễ phép, hơi rón rén, tiếng Trung mức trung bình, cẩn thận');
INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P2','Lâm Vũ (林宇)',23,'Bạn cùng phòng người Trung Quốc','Nhiệt tình, thoải mái, hay giúp đỡ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM01','呀','Hỏi/đáp nhẹ nhàng, giảm cảm giác cứng nhắc');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM02','啦','Nhẹ nhõm, vui vẻ, hoặc dứt điểm một việc');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM03','哦','Chỉnh/bổ sung thông tin nhẹ nhàng, không phủ định gắt');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM04','呢','Bổ sung/giải thích, hoặc thể hiện hơi bối rối/băn khoăn');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM05','啊','Hỏi lịch sự hoặc biểu lộ ngạc nhiên nhẹ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM06','哈','Nhắc nhẹ, thân thiện, kéo gần khoảng cách hội thoại');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM07','吧','Đề nghị/xác nhận mang tính dò hỏi, không chắc chắn tuyệt đối');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM08','嘞','Đáp lời sảng khoái, đậm chất khẩu ngữ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM09','嘛','Giọng hiển nhiên, thân mật, xoa dịu');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM10','哎呀','Tự trách/ngại ngùng bất ngờ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM11','咯','Xác nhận nhẹ nhàng, coi như hiển nhiên/dứt khoát, giọng thân mật');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM12','诶','Than nhẹ, nhấn mạnh điều bất tiện/khó xử vừa nói tới');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_A','Gọi lái xe taxi/xe công nghệ là ''thầy'' (师傅) bất kể tuổi','Cách gọi phổ biến, thể hiện sự tôn trọng, không phân biệt tuổi tác. Lặp lại ở các tình huống đi taxi/xe công nghệ.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_B','Ưu tiên thanh toán quét mã; mạng chậm thì chờ, không thúc ép; một số quán chỉ nhận quét mã','Thanh toán điện tử là chủ đạo ở Trung Quốc; tài xế/người bán thường kiên nhẫn chờ khách quét mã, và nhiều cửa hàng nhỏ không nhận tiền mặt.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_C','Ký túc xá quản lý theo quy định thống nhất, không có ngoại lệ','Giờ đóng cửa và quy định khách thăm áp dụng chung cho mọi sinh viên, kể cả sinh viên quốc tế.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_D','Thiết bị công cộng (đèn, máy giặt...) hỏng thì báo quản lý, không tự sửa','Trường/ký túc xá chịu trách nhiệm sửa chữa miễn phí; có thể đổi sang thiết bị khác dùng tạm trong lúc chờ.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_E','Thủ tục hành chính với sinh viên quốc tế cần thêm giấy xác nhận đang học','Chỉ hộ chiếu và visa thường chưa đủ để mở tài khoản ngân hàng hay làm một số thủ tục, cần bổ sung giấy xác nhận đang học.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_F','Thanh toán di động bắt buộc xác thực danh tính thật','Sinh viên nước ngoài dùng hộ chiếu để xác thực, không cần CMND Trung Quốc.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_G','Hồ sơ thiếu giấy tờ thường được cho nộp bổ sung có thời hạn','Chỉ cần thành thật xin lỗi và có kế hoạch bổ sung rõ ràng, không cần quá lo lắng.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_H','Biên phòng/hải quan làm việc theo nguyên tắc trung thực, ngắn gọn','Không cần giải thích dài dòng, chỉ cần trả lời đúng và đủ thông tin được hỏi.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_I','Đi nhầm chiều tàu điện ngầm có thể đổi chiều miễn phí ngay tại sân ga đối diện','Không cần ra cổng mua lại vé, chỉ cần sang sân ga đối diện, việc chuyển tuyến trong nhà ga là miễn phí.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_J','Có thể lịch sự đề nghị lái xe đổi lộ trình khi tắc đường mà không bị phụ thu thêm','Tài xế taxi/xe công nghệ thường chủ động hợp tác khi khách giải thích lý do gấp.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_K','Phí vận chuyển thực tế có thể cao hơn phí dự tính trên app nếu hàng quá cân','Đây là phụ thu hợp lệ theo cân nặng thật, không phải shipper tự ý tính thêm.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_M','Nên chủ động hỏi lại nhân viên nếu nghi ngờ thông tin vừa thay đổi (băng chuyền, cổng ra...)','Không nên tự đoán theo đám đông; thông tin sân bay có thể thay đổi tạm thời so với bảng hiển thị ban đầu.');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT201','S1','Điền tờ khai nhập cảnh trên máy bay','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V201','SIT201','P1','suon_se','ban_chinh_thuc','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','Tiếp viên trên máy bay giữ giọng mềm mỏng, hành khách hỏi thoải mái không cần quá rón rén.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_01','V201','Nguyễn Minh',1,'乘务员您好，我不太会填这个入境登记卡，能麻烦您教教我吗？','chéng wù yuán nín hǎo， wǒ bù tài huì tián zhè ge rù jìng dēng jì kǎ， néng má fán nín jiāo jiāo wǒ ma？','Chào chị tiếp viên, em không rành cách điền tờ khai nhập cảnh này lắm, chị có thể chỉ giúp em được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_02','V201','Tiếp viên',2,'没问题呀，我来跟你说。你护照上的信息照着填就行啦。','méi wèn tí ya， wǒ lái gēn nǐ shuō。 nǐ hù zhào shàng de xìn xī zhào zhe tián jiù xíng la。','Không vấn đề gì đâu, để chị hướng dẫn em nhé. Em cứ nhìn theo thông tin trên hộ chiếu mà điền là được rồi.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_03','V201','Nguyễn Minh',3,'好的，请问“来华事由”这一栏，我填“留学”就可以了吧？','hǎo de， qǐng wèn “lái huá shì yóu” zhè yī lán， wǒ tián “liú xué” jiù kě yǐ le ba？','Dạ vâng, cho em hỏi mục "lý do đến Trung Quốc" thì em điền "du học" là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_04','V201','Tiếp viên',4,'对的，完全没问题。停留时间就写你签证上的时长哦。','duì de， wán quán méi wèn tí。 tíng liú shí jiān jiù xiě nǐ qiān zhèng shàng de shí cháng ó。','Đúng rồi, hoàn toàn không sao cả. Thời gian lưu trú thì em ghi theo đúng thời hạn trên visa của em nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_05','V201','Nguyễn Minh',5,'那籍贯和出生地，直接填越南可以吗？','nà jí guàn hé chū shēng dì， zhí jiē tián yuè nán kě yǐ ma？','Vậy còn mục quê quán với nơi sinh, em điền thẳng là Việt Nam được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_06','V201','Tiếp viên',6,'可以的，不用写太详细，简洁填写就好啦。','kě yǐ de， bù yòng xiě tài xiáng xì， jiǎn jié tián xiě jiù hǎo la。','Được chứ, không cần ghi chi tiết quá đâu, em cứ điền ngắn gọn là ổn rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_07','V201','Nguyễn Minh',7,'太谢谢您了，帮了我大忙！','tài xiè xiè nín le， bāng le wǒ dà máng！','Em cảm ơn chị nhiều lắm ạ, chị giúp em một việc lớn đó!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_08','V201','Tiếp viên',8,'不客气哈，有不懂的随时再问我。','bú kè qì hā， yǒu bù dǒng de suí shí zài wèn wǒ。','Không có gì đâu, có gì chưa hiểu cứ hỏi lại chị bất cứ lúc nào nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT202','S1','Hỏi lối ra sân bay','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V202','SIT202','P1','suon_se','ban_chinh_thuc','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','Nhân viên sân bay chỉ đường thường dùng cách nói dễ hiểu, không dùng thuật ngữ phức tạp.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_01','V202','Nguyễn Minh',1,'您好，麻烦问一下，机场出口是往这边走吗？','nín hǎo， má fán wèn yī xià， jī chǎng chū kǒu shì wǎng zhè biān zǒu ma？','Chào anh/chị, cho tôi hỏi lối ra sân bay là đi hướng này phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_02','V202','Nhân viên',2,'不是哦，这边是转机通道，出口在你的左手边呢。','bú shì ó， zhè biān shì zhuǎn jī tōng dào， chū kǒu zài nǐ de zuǒ shǒu biān ne。','Không phải đâu ạ, bên này là lối đi nối chuyến, cửa ra nằm ở phía tay trái của anh/chị đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_03','V202','Nguyễn Minh',3,'左手边是吗？一直直走就到了吧？','zuǒ shǒu biān shì ma？ yì zhí zhí zǒu jiù dào le ba？','Bên tay trái đúng không ạ? Cứ đi thẳng là tới phải không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_04','V202','Nhân viên',4,'对的，直走到底左转，跟着“国内到达”的牌子走就行啦。','duì de， zhí zǒu dào dǐ zuǒ zhuǎn， gēn zhe “guó nèi dào dá” de pái zi zǒu jiù xíng la。','Đúng vậy, đi thẳng đến cuối rồi rẽ trái, cứ đi theo biển "đến trong nước" là được ạ.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_05','V202','Nguyễn Minh',5,'好的，我明白了，谢谢您！','hǎo de， wǒ míng bái le， xiè xiè nín！','Dạ vâng, tôi hiểu rồi, cảm ơn anh/chị nhé!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_06','V202','Nhân viên',6,'没事的，慢走哈！','méi shì de， màn zǒu hā！','Không có gì đâu ạ, đi cẩn thận nhé!','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT203','S1','Hỏi băng chuyền nhận hành lý','Băng chuyền bị đổi tạm thời so với thông tin ban đầu','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V203','SIT203','P1','twist','chinh_thuc','Băng chuyền bị đổi tạm thời so với thông tin ban đầu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_01','V203','Nguyễn Minh',1,'您好，我想请问一下，国际航班的行李在哪里领取啊？','nín hǎo， wǒ xiǎng qǐng wèn yī xià， guó jì háng bān de xíng lǐ zài nǎ lǐ lǐng qǔ a？','Chào anh/chị, cho tôi hỏi hành lý của chuyến bay quốc tế lấy ở đâu vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_02','V203','Nhân viên',2,'您好，请问你的航班号是多少呢？','nín hǎo， qǐng wèn nǐ de háng bān hào shì duō shǎo ne？','Chào anh/chị, xin hỏi số hiệu chuyến bay của anh/chị là gì ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_03','V203','Nguyễn Minh',3,'是VN520航班，麻烦您查一下。','shì VN520 háng bān， má fán nín chá yī xià。','Là chuyến VN520, phiền anh/chị kiểm tra giúp tôi với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_04','V203','Nhân viên',4,'稍等，这班航班原本在3号转盘，刚刚临时调整到5号转盘了哦。','shāo děng， zhè bān háng bān yuán běn zài 3 hào zhuàn pán， gāng gāng lín shí diào zhěng dào 5 hào zhuàn pán le ó。','Anh/chị chờ chút, chuyến này ban đầu ở băng chuyền số 3, nhưng vừa mới tạm thời chuyển sang băng chuyền số 5 rồi ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_05','V203','Nguyễn Minh',5,'原来是这样，还好我问了，不然就走错啦。','yuán lái shì zhè yàng， hái hǎo wǒ wèn le， bù rán jiù zǒu cuò la。','Thì ra là vậy, may mà tôi hỏi, không thì đã đi nhầm rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_06','V203','Nhân viên',6,'是的，近期偶尔会调整，你直接去5号转盘等候就行。','shì de， jìn qī ǒu ěr huì tiáo zhěng， nǐ zhí jiē qù 5 hào zhuàn pán děng hòu jiù xíng。','Vâng, gần đây thỉnh thoảng có điều chỉnh, anh/chị cứ đến thẳng băng chuyền số 5 chờ là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_07','V203','Nguyễn Minh',7,'好的，非常感谢您！','hǎo de， fēi cháng gǎn xiè nín！','Vâng, cảm ơn anh/chị rất nhiều!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT204','S5','Mua SIM và tư vấn gói cước','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V204','SIT204','P1','twist','tuy_y','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_01','V204','Nguyễn Minh',1,'你好，我是留学生，想办一张流量多的电话卡，有合适的套餐吗？','nǐ hǎo， wǒ shì liú xué shēng， xiǎng bàn yī zhāng liú liàng duō de diàn huà kǎ， yǒu hé shì de tào cān ma？','Chào bạn, mình là du học sinh, muốn đăng ký một cái sim có nhiều data một chút, có gói nào phù hợp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_02','V204','Nhân viên',2,'有的呀，这款学生套餐性价比超高，每月超多流量呢。','yǒu de ya， zhè kuǎn xué shēng tào cān xìng jià bǐ chāo gāo， měi yuè chāo duō liú liàng ne。','Có chứ ạ, gói dành cho sinh viên này giá trị lắm luôn, mỗi tháng data siêu nhiều đó.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_03','V204','Nguyễn Minh',3,'那这个套餐可以直接当场激活吧？','nà zhè ge tào cān kě yǐ zhí jiē dāng chǎng jī huó ba？','Vậy gói này có thể kích hoạt luôn tại chỗ được không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_04','V204','Nhân viên',4,'本来可以的，不过今天系统有点卡，需要等两分钟哦。','běn lái kě yǐ de， bù guò jīn tiān xì tǒng yǒu diǎn kǎ， xū yào děng liǎng fēn zhōng ó。','Bình thường thì được đó, nhưng hôm nay hệ thống hơi bị đơ, phải đợi khoảng hai phút nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_05','V204','Nguyễn Minh',5,'没事的，我可以等，麻烦你啦。','méi shì de， wǒ kě yǐ děng， má fán nǐ la。','Không sao đâu, mình đợi được, phiền bạn giúp nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_06','V204','Nhân viên',6,'不麻烦！马上就好，激活后我帮你调好网络设置哈。','bù má fán！ mǎ shàng jiù hǎo， jī huó hòu wǒ bāng nǐ diào hǎo wǎng luò shè zhì hā。','Không phiền đâu! Xong ngay thôi, kích hoạt xong mình chỉnh luôn cài đặt mạng cho bạn nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_07','V204','Nguyễn Minh',7,'太好了，谢谢你！','tài hǎo le， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nhiều nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT205','S4','Trả lời biên phòng khi nhập cảnh','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V205','SIT205','P1','suon_se','chinh_thuc','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_01','V205','Biên phòng',1,'你好，出示一下护照和签证。来华目的是什么？','nǐ hǎo， chū shì yī xià hù zhào hé qiān zhèng。 lái huá mù dì shì shén me？','Xin chào, xuất trình hộ chiếu và visa. Mục đích đến Trung Quốc là gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_02','V205','Nguyễn Minh',2,'您好，我来中国留学的。','nín hǎo， wǒ lái zhōng guó liú xué de。','Chào anh/chị, tôi đến Trung Quốc để du học ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_03','V205','Biên phòng',3,'在哪所学校就读？什么专业？','zài nǎ suǒ xué xiào jiù dú？ shén me zhuān yè？','Anh/chị học ở trường nào? Chuyên ngành gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_04','V205','Nguyễn Minh',4,'我在省城理工大学，就读国际贸易专业。','wǒ zài shěng chéng lǐ gōng dà xué， jiù dú guó jì mào yì zhuān yè。','Tôi học tại Đại học Bách khoa tỉnh, chuyên ngành Thương mại quốc tế.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_05','V205','Biên phòng',5,'学习时长多久？资金来源是哪里？','xué xí shí cháng duō jiǔ？ zī jīn lái yuán shì nǎ lǐ？','Thời gian học là bao lâu? Nguồn tài chính từ đâu?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_06','V205','Nguyễn Minh',6,'我学习四年，学费和生活费由家里提供。','wǒ xué xí sì nián， xué fèi hé shēng huó fèi yóu jiā lǐ tí gōng。','Tôi học bốn năm, học phí và sinh hoạt phí do gia đình chu cấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_07','V205','Biên phòng',7,'好的，信息核对无误，入境通过。','hǎo de， xìn xī hé duì wú wù， rù jìng tōng guò。','Được rồi, thông tin đối chiếu chính xác, anh/chị được phép nhập cảnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_08','V205','Nguyễn Minh',8,'谢谢工作人员！','xiè xiè gōng zuò rén yuán！','Cảm ơn cán bộ đã hỗ trợ ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT206','S4','Xin biên phòng nói chậm/lặp lại','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V206','SIT206','P1','suon_se','chinh_thuc','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_01','V206','Biên phòng',1,'你本次入境是否携带校外兼职相关材料？','nǐ běn cì rù jìng shì fǒu xié dài xiào wài jiān zhí xiāng guān cái liào？','Lần nhập cảnh này anh/chị có mang theo giấy tờ liên quan đến việc làm thêm ngoài trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_02','V206','Nguyễn Minh',2,'不好意思，我没太听懂您的问题呢。','bù hǎo yì sī， wǒ méi tài tīng dǒng nín de wèn tí ne。','Xin lỗi, tôi chưa nghe rõ câu hỏi của anh/chị lắm ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_03','V206','Biên phòng',3,'没关系，那我放慢语速，再说一遍。','méi guān xì， nà wǒ fàng màn yǔ sù， zài shuō yī biàn。','Không sao, để tôi nói chậm lại và lặp lại một lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_04','V206','Nguyễn Minh',4,'麻烦您了，我的中文听力还不太好。','má fán nín le， wǒ de zhōng wén tīng lì hái bù tài hǎo。','Phiền anh/chị quá, khả năng nghe tiếng Trung của tôi vẫn chưa tốt lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_05','V206','Biên phòng',5,'没事，我问你有没有带校外工作、兼职的证明材料？','méi shì， wǒ wèn nǐ yǒu méi yǒu dài xiào wài gōng zuò、 jiān zhí de zhèng míng cái liào？','Không sao đâu, tôi hỏi là anh/chị có mang giấy tờ chứng minh việc làm thêm, làm việc ngoài trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_06','V206','Nguyễn Minh',6,'没有的，我目前只专注学业，没有准备兼职材料。','méi yǒu de， wǒ mù qián zhǐ zhuān zhù xué yè， méi yǒu zhǔn bèi jiān zhí cái liào。','Không có ạ, hiện tại tôi chỉ tập trung học tập, chưa chuẩn bị giấy tờ làm thêm gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_07','V206','Biên phòng',7,'好的，了解了。','hǎo de， liǎo jiě le。','Được rồi, tôi hiểu rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT207','S4','Khai báo hải quan','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V207','SIT207','P1','suon_se','chinh_thuc','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_01','V207','Hải quan',1,'你好，请问你本次入境有没有需要申报的物品？','nǐ hǎo， qǐng wèn nǐ běn cì rù jìng yǒu méi yǒu xū yào shēn bào de wù pǐn？','Xin chào, xin hỏi lần nhập cảnh này anh/chị có vật phẩm nào cần khai báo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_02','V207','Nguyễn Minh',2,'您好，我没有贵重物品，也没有超额物品，不需要申报的。','nín hǎo， wǒ méi yǒu guì zhòng wù pǐn， yě méi yǒu chāo é wù pǐn， bù xū yào shēn bào de。','Chào anh/chị, tôi không có đồ vật giá trị cao, cũng không có đồ vượt định mức, nên không cần khai báo ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_03','V207','Hải quan',3,'有没有携带大量现金、电子产品或者管制物品？','yǒu méi yǒu xié dài dà liàng xiàn jīn、 diàn zi chǎn pǐn huò zhě guǎn zhì wù pǐn？','Anh/chị có mang theo lượng tiền mặt lớn, thiết bị điện tử hay vật phẩm bị kiểm soát không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_04','V207','Nguyễn Minh',4,'没有的，只带了个人生活用品和少量现金。','méi yǒu de， zhǐ dài le gè rén shēng huó yòng pǐn hé shǎo liàng xiàn jīn。','Không có ạ, tôi chỉ mang đồ dùng sinh hoạt cá nhân và một ít tiền mặt thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_05','V207','Hải quan',5,'好的，确认无申报物品，可以通行了。','hǎo de， què rèn wú shēn bào wù pǐn， kě yǐ tōng xíng le。','Được rồi, xác nhận không có vật phẩm khai báo, anh/chị có thể đi qua.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_06','V207','Nguyễn Minh',6,'好的，谢谢您！','hǎo de， xiè xiè nín！','Vâng, cảm ơn anh/chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT208','S4','Khai báo thuốc mang theo','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V208','SIT208','P1','twist','chinh_thuc','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','Có thể mang theo thuốc tự dùng số lượng nhỏ; thuốc kê đơn nên có đơn thuốc dịch sang tiếng Trung và giữ lại vỏ hộp để thuận tiện khi kiểm tra.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_01','V208','Hải quan',1,'除了生活用品，还有其他需要申报的东西吗？','chú le shēng huó yòng pǐn， hái yǒu qí tā xū yào shēn bào de dōng xī ma？','Ngoài đồ dùng sinh hoạt ra, anh/chị còn có gì khác cần khai báo không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_02','V208','Nguyễn Minh',2,'有的，我随身带了一些常用感冒药和肠胃药，需要申报吧？','yǒu de， wǒ suí shēn dài le yī xiē cháng yòng gǎn mào yào hé cháng wèi yào， xū yào shēn bào ba？','Dạ có, tôi có mang theo một ít thuốc cảm và thuốc dạ dày thường dùng, chắc phải khai báo đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_03','V208','Hải quan',3,'是的，自用药品需要报备，带了多少数量呢？','shì de， zì yòng yào pǐn xū yào bào bèi， dài le duō shǎo shù liàng ne？','Vâng, thuốc tự dùng thì cần khai báo, anh/chị mang theo số lượng bao nhiêu ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04','V208','Nguyễn Minh',4,'都是个人短期自用的，没有大批量携带哦。','dōu shì gè rén duǎn qī zì yòng de， méi yǒu dà pī liàng xié dài ó。','Đều là dùng ngắn hạn cho cá nhân thôi, không mang số lượng lớn đâu ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_05','V208','Hải quan',5,'我看一下，没问题，自用常规药品可以放行，无需登记。','wǒ kàn yī xià， méi wèn tí， zì yòng cháng guī yào pǐn kě yǐ fàng xíng， wú xū dēng jì。','Để tôi kiểm tra, không có vấn đề gì, thuốc thông thường tự dùng thì được phép qua, không cần đăng ký.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_06','V208','Nguyễn Minh',6,'太好了，谢谢您的耐心核对！','tài hǎo le， xiè xiè nín de nài xīn hé duì！','Tuyệt quá, cảm ơn anh/chị đã kiên nhẫn kiểm tra giúp tôi!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_07','V208','Hải quan',7,'不客气，下次尽量保留药品外包装哦。','bú kè qì， xià cì jǐn liàng bǎo liú yào pǐn wài bāo zhuāng ó。','Không có gì, lần sau anh/chị cố gắng giữ lại vỏ hộp thuốc nhé.','AM03');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT209','S1','Báo hành lý hư hỏng','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V209','SIT209','P1','that_bai_nhe','ban_chinh_thuc','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','Hành lý hư hỏng ở sân bay được đăng ký bồi thường miễn phí; cần giữ thẻ hành lý và thẻ lên máy bay, không tự bỏ đi rồi mới báo sau.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_01','V209','Nguyễn Minh',1,'您好，麻烦您，我的行李箱好像被摔坏了。','nín hǎo， má fán nín， wǒ de xíng lǐ xiāng hǎo xiàng bèi shuāi huài le。','Chào chị, phiền chị một chút, va li của tôi hình như bị va đập hỏng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_02','V209','Nhân viên',2,'别着急，我看一下，是箱体破损还是轮子损坏呀？','bié zháo jí， wǒ kàn yī xià， shì xiāng tǐ pò sǔn hái shì lún zi sǔn huài ya？','Anh đừng lo, để tôi xem thử, là vỏ va li bị vỡ hay bánh xe bị hỏng vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_03','V209','Nguyễn Minh',3,'箱体侧面裂开了，里面的东西没坏，但是箱子没法用了。','xiāng tǐ cè miàn liè kāi le， lǐ miàn de dōng xī méi huài， dàn shì xiāng zi méi fǎ yòng le。','Mặt hông va li bị nứt ra, đồ bên trong không sao, nhưng cái va li thì không dùng được nữa rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04','V209','Nhân viên',4,'我明白了，需要登记你的航班信息和行李牌，后续走理赔流程呢。','wǒ míng bái le， xū yào dēng jì nǐ de háng bān xìn xī hé xíng lǐ pái， hòu xù zǒu lǐ péi liú chéng ne。','Tôi hiểu rồi, cần đăng ký thông tin chuyến bay và thẻ hành lý của anh, sau đó sẽ tiến hành quy trình bồi thường.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_05','V209','Nguyễn Minh',5,'好的，我马上提供，大概多久能处理好呀？','hǎo de， wǒ mǎ shàng tí gōng， dà gài duō jiǔ néng chǔ lǐ hǎo ya？','Vâng, tôi cung cấp ngay đây, khoảng bao lâu thì xử lý xong được ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_06','V209','Nhân viên',6,'三个工作日内会有结果，你耐心等待通知就行。','sān gè gōng zuò rì nèi huì yǒu jié guǒ， nǐ nài xīn děng dài tōng zhī jiù xíng。','Trong vòng ba ngày làm việc sẽ có kết quả, anh cứ yên tâm chờ thông báo nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_07','V209','Nguyễn Minh',7,'辛苦您了，谢谢！','xīn kǔ nín le， xiè xiè！','Cảm ơn chị đã vất vả giúp đỡ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT210','S6','Đổi tiền và hỏi tỷ giá','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V210','SIT210','P1','twist','ban_chinh_thuc','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','机场外币兑换汇率略低于市区银行，适合小额应急兑换，大额兑换建议去正规银行；往返双向兑换会产生双重汇兑损耗，尽量按需兑换。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_01','V210','阮明',1,'您好，我刚落地机场，想把随身带的越南盾兑换成人民币。','nín hǎo， wǒ gāng luò dì jī chǎng， xiǎng bǎ suí shēn dài de yuè nán dùn duì huàn chéng rén mín bì。','Chào chị, tôi vừa xuống sân bay, muốn đổi số tiền đồng Việt Nam mang theo sang nhân dân tệ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_02','V210','职员',2,'您好，先跟您确认一下，您清楚机场兑换点和市区银行汇率有差别吗？','nín hǎo， xiān gēn nín què rèn yī xià， nín qīng chǔ jī chǎng duì huàn diǎn hé shì qū yín háng huì lǜ yǒu chā bié ma？','Chào anh, để tôi xác nhận trước với anh, anh có biết tỷ giá đổi ở sân bay và ngân hàng trong thành phố có chênh lệch không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_03','V210','阮明',3,'之前听同学提过一句，但具体差多少我不太了解啊。','zhī qián tīng tóng xué tí guò yī jù， dàn jù tǐ chà duō shǎo wǒ bù tài liǎo jiě a。','Trước đây có nghe bạn học nhắc qua, nhưng chênh lệch cụ thể bao nhiêu thì tôi không rõ lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_04','V210','职员',4,'今日实时汇率牌价就在柜台上方，机场汇率会比市区银行低三个点哦。','jīn rì shí shí huì lǜ pái jià jiù zài guì tái shàng fāng， jī chǎng huì lǜ huì bǐ shì qū yín háng dī sān gè diǎn ó。','Bảng tỷ giá thực tế hôm nay ở ngay phía trên quầy, tỷ giá ở sân bay sẽ thấp hơn ngân hàng trong thành phố khoảng ba điểm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_05','V210','阮明',5,'这样啊，差价还挺明显，那我先兑换一千元人民币应急可以吗？','zhè yàng a， chā jià hái tǐng míng xiǎn， nà wǒ xiān duì huàn yī qiān yuán rén mín bì yìng jí kě yǐ ma？','Ra là vậy, chênh lệch cũng khá rõ đấy, vậy tôi đổi tạm một nghìn tệ để dùng gấp được không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_06','V210','职员',6,'兑换外币有流程要求，需要出示护照登记个人信息哈。','duì huàn wài bì yǒu liú chéng yāo qiú， xū yào chū shì hù zhào dēng jì gè rén xìn xī hā。','Đổi ngoại tệ có quy trình yêu cầu, anh cần xuất trình hộ chiếu để đăng ký thông tin cá nhân nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_07','V210','阮明',7,'没问题，护照我一直随身带着，现在递给您。那手续费是单独收取的吗？','méi wèn tí， hù zhào wǒ yì zhí suí shēn dài zhe， xiàn zài dì gěi nín。 nà shǒu xù fèi shì dān dú shōu qǔ de ma？','Không vấn đề gì, hộ chiếu tôi luôn mang theo bên người, giờ đưa cho chị đây. Vậy phí dịch vụ có tính riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_08','V210','职员',8,'单笔一千元以内的小额兑换免手续费，系统已经直接帮您核算完毕。','dān bǐ yī qiān yuán yǐ nèi de xiǎo é duì huàn miǎn shǒu xù fèi， xì tǒng yǐ jīng zhí jiē bāng nín hé suàn wán bì。','Đổi số tiền nhỏ dưới một nghìn tệ mỗi lần thì được miễn phí dịch vụ, hệ thống đã tính toán xong cho anh rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_09','V210','阮明',9,'我再多问一句，如果剩下没花完的人民币，还能在这里换回越南盾吗？','wǒ zài duō wèn yī jù， rú guǒ shèng xià méi huā wán de rén mín bì， hái néng zài zhè lǐ huàn huí yuè nán dùn ma？','Tôi hỏi thêm một câu nữa, nếu còn dư nhân dân tệ chưa tiêu hết, thì có thể đổi lại thành đồng Việt Nam ở đây không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_10','V210','职员',10,'可以兑换返程外币，但二次兑换会再收取一笔汇兑差价，不太划算。','kě yǐ duì huàn fǎn chéng wài bì， dàn èr cì duì huàn huì zài shōu qǔ yī bǐ huì duì chā jià， bù tài huá suàn。','Có thể đổi ngoại tệ chiều về, nhưng đổi lần hai sẽ tính thêm một khoản chênh lệch tỷ giá nữa, không lời lắm đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_11','V210','阮明',11,'明白了，那我就只换一千元，够用今天打车吃饭就行。','míng bái le， nà wǒ jiù zhǐ huàn yī qiān yuán， gòu yòng jīn tiān dǎ chē chī fàn jiù xíng。','Tôi hiểu rồi, vậy tôi chỉ đổi một nghìn tệ thôi, đủ để dùng đi taxi ăn uống hôm nay là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_12','V210','职员',12,'好，我现在按实时汇率帮您清点现金，稍等片刻。','hǎo， wǒ xiàn zài àn shí shí huì lǜ bāng nín qīng diǎn xiàn jīn， shāo děng piàn kè。','Được, giờ tôi tính theo tỷ giá thực tế và đếm tiền mặt cho anh, chờ một chút nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_13','V210','阮明',13,'辛苦您了，汇率有变动也麻烦您再跟我说一声。','xīn kǔ nín le， huì lǜ yǒu biàn dòng yě má fán nín zài gēn wǒ shuō yī shēng。','Cảm ơn chị vất vả rồi, nếu tỷ giá có thay đổi thì phiền chị báo lại cho tôi với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_14','V210','职员',14,'刚刚已经核对过牌价，短时间不会波动，现金给您收好。','gāng gāng yǐ jīng hé duì guò pái jià， duǎn shí jiān bú huì bō dòng， xiàn jīn gěi nín shōu hǎo。','Vừa nãy đã kiểm tra lại bảng giá rồi, trong thời gian ngắn sẽ không biến động đâu, tiền mặt đây anh cầm cẩn thận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_15','V210','阮明',15,'太感谢您耐心讲解，省去我不少麻烦，那就兑换吧！','tài gǎn xiè nín nài xīn jiǎng jiě， shěng qù wǒ bù shǎo má fán， nà jiù duì huàn ba！','Cảm ơn chị nhiều vì đã kiên nhẫn giải thích, đỡ cho tôi bao nhiêu rắc rối, vậy thì đổi luôn nhé!','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT211','S5','Kết nối WiFi sân bay','Xin mật khẩu wifi, phải xác thực qua số điện thoại','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V211','SIT211','P1','suon_se','tuy_y','Xin mật khẩu wifi, phải xác thực qua số điện thoại',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_01','V211','Nguyễn Minh',1,'你好，请问机场的免费WiFi密码是多少呀？','nǐ hǎo， qǐng wèn jī chǎng de miǎn fèi WiFi mì mǎ shì duō shǎo ya？','Chào bạn, cho mình hỏi mật khẩu WiFi miễn phí của sân bay là gì vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_02','V211','Nhân viên',2,'很简单的，密码是机场全称的首字母加八个八哦。','hěn jiǎn dān de， mì mǎ shì jī chǎng quán chēng de shǒu zì mǔ jiā bā gè bā ó。','Đơn giản lắm, mật khẩu là chữ cái đầu của tên đầy đủ sân bay cộng với tám số 8 nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_03','V211','Nguyễn Minh',3,'我试了一下，怎么连不上呢？','wǒ shì le yī xià， zěn me lián bù shàng ne？','Mình thử rồi mà sao không kết nối được nhỉ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_04','V211','Nhân viên',4,'需要先打开浏览器验证一下，登录之后就能用啦。','xū yào xiān dǎ kāi liú lǎn qì yàn zhèng yī xià， dēng lù zhī hòu jiù néng yòng la。','Cần mở trình duyệt xác thực trước đã, đăng nhập xong là dùng được liền á.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_05','V211','Nguyễn Minh',5,'原来是这样，太感谢你啦！','yuán lái shì zhè yàng， tài gǎn xiè nǐ la！','Thì ra là vậy, cảm ơn bạn nhiều lắm nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_06','V211','Nhân viên',6,'没事哒，有问题再问哈！','méi shì dá， yǒu wèn tí zài wèn hā！','Có gì đâu, có vấn đề gì cứ hỏi tiếp nha!','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT212','S1','Gọi người đón, báo vị trí','Báo cho bạn đến đón biết mình đã tới và đang ở đâu','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V212','SIT212','P1','suon_se','tuy_y','Báo cho bạn đến đón biết mình đã tới và đang ở đâu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_01','V212','Nguyễn Minh',1,'宇哥，我已经到机场啦，顺利入境了！','yǔ gē， wǒ yǐ jīng dào jī chǎng la， shùn lì rù jìng le！','Anh Vũ ơi, em đến sân bay rồi nè, nhập cảnh suôn sẻ luôn!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_02','V212','Đón (Trần Vũ)',2,'太好了！你现在在哪个位置呀？','tài hǎo le！ nǐ xiàn zài zài nǎ ge wèi zhì ya？','Tuyệt quá! Giờ em đang ở chỗ nào vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_03','V212','Nguyễn Minh',3,'我在国内到达出口的问询台旁边呢。','wǒ zài guó nèi dào dá chū kǒu de wèn xún tái páng biān ne。','Em đang ở gần quầy hỏi thông tin ở cửa ra đến trong nước nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_04','V212','Đón (Trần Vũ)',4,'好的，我马上就到，你就在原地等我别乱跑哈。','hǎo de， wǒ mǎ shàng jiù dào， nǐ jiù zài yuán dì děng wǒ bié luàn pǎo hā。','Được rồi, anh tới ngay đây, em cứ đứng yên đó chờ anh, đừng chạy lung tung nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_05','V212','Nguyễn Minh',5,'没问题，我就在这里等你，不着急的。','méi wèn tí， wǒ jiù zài zhè lǐ děng nǐ， bù zháo jí de。','Không sao đâu, em đứng đây chờ anh, không vội đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_06','V212','Đón (Trần Vũ)',6,'五分钟就到，一会儿见！','wǔ fēn zhōng jiù dào， yī huì er jiàn！','Năm phút nữa là tới, lát gặp nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT213','S1','Không thấy người đón, gọi xác nhận','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V213','SIT213','P1','twist','tuy_y','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_01','V213','Nguyễn Minh',1,'宇哥，我已经在出口等了十分钟了，没看到你呀。','yǔ gē， wǒ yǐ jīng zài chū kǒu děng le shí fēn zhōng le， méi kàn dào nǐ ya。','Anh Vũ ơi, em đợi ở cửa ra mười phút rồi mà không thấy anh đâu cả.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_02','V213','Đón (Trần Vũ)',2,'哎呀抱歉！我走错出口了，我在二号出口，你在几号呀？','āi yā bào qiàn！ wǒ zǒu cuò chū kǒu le， wǒ zài èr hào chū kǒu， nǐ zài jǐ hào ya？','Ôi xin lỗi em! Anh đi lộn cửa rồi, anh đang ở cửa số 2, em ở cửa số mấy vậy?','AM10');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03','V213','Nguyễn Minh',3,'我在一号出口，难怪看不到呢。','wǒ zài yī hào chū kǒu， nán guài kàn bú dào ne。','Em ở cửa số 1, thảo nào không thấy nhau.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_04','V213','Đón (Trần Vũ)',4,'太不好意思了！我马上走通道过来，两分钟就到你那边。','tài bù hǎo yì sī le！ wǒ mǎ shàng zǒu tōng dào guò lái， liǎng fēn zhōng jiù dào nǐ nà biān。','Ngại quá đi! Anh chạy qua lối đi ngay đây, hai phút nữa là tới chỗ em thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_05','V213','Nguyễn Minh',5,'没事没事，不着急，我慢慢等你就好啦。','méi shì méi shì， bù zháo jí， wǒ màn màn děng nǐ jiù hǎo la。','Không sao không sao, đừng vội, em từ từ chờ anh là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_06','V213','Đón (Trần Vũ)',6,'辛苦你啦，马上汇合！','xīn kǔ nǐ la， mǎ shàng huì hé！','Vất vả cho em rồi, gặp nhau ngay đây!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT214','S2','Đặt xe công nghệ, xác nhận tài xế','Xác nhận đúng tài xế và biển số trước khi lên xe','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V214','SIT214','P1','suon_se','tuy_y','Xác nhận đúng tài xế và biển số trước khi lên xe',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_01','V214','Tài xế',1,'你好，是尾号3621的乘客吧？我到机场上车点了。','nǐ hǎo， shì wěi hào 3621 de chéng kè ba？ wǒ dào jī chǎng shàng chē diǎn le。','Chào bạn, bạn là khách có số đuôi 3621 phải không? Mình đến điểm đón ở sân bay rồi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_02','V214','Nguyễn Minh',2,'对的是我！麻烦问一下，您的车牌号是多少呀？','duì de shì wǒ！ má fán wèn yī xià， nín de chē pái hào shì duō shǎo ya？','Đúng rồi, là mình đây! Phiền hỏi biển số xe của anh là gì vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_03','V214','Tài xế',3,'车牌是浙A8523K，黑色轿车，很好认的。','chē pái shì zhè A8523K， hēi sè jiào chē， hěn hǎo rèn de。','Biển số là 浙A8523K, xe sedan màu đen, dễ nhận ra lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_04','V214','Nguyễn Minh',4,'好的，我看到您的车了，马上走过去哈。','hǎo de， wǒ kàn dào nín de chē le， mǎ shàng zǒu guò qù hā。','Vâng, em thấy xe anh rồi, em đi qua ngay đây nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_05','V214','Tài xế',5,'不急，慢慢走，注意身边行李就行。','bù jí， màn màn zǒu， zhù yì shēn biān xíng lǐ jiù xíng。','Không vội đâu, cứ từ từ đi, chú ý hành lý bên người là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_06','V214','Nguyễn Minh',6,'好嘞，辛苦您等我一下！','hǎo lei， xīn kǔ nín děng wǒ yī xià！','Dạ được, phiền anh chờ em một chút nhé!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT215','S2','Báo địa chỉ đến cho tài xế','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V215','SIT215','P1','suon_se','tuy_y','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_01','V215','Tài xế',1,'同学，我们现在出发，你去哪里呀？','tóng xué， wǒ men xiàn zài chū fā， nǐ qù nǎ lǐ ya？','Bạn ơi, giờ mình xuất phát nhé, bạn đi đâu vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_02','V215','Nguyễn Minh',2,'师傅您好，麻烦去省城理工大学留学生公寓。','shī fù nín hǎo， má fán qù shěng chéng lǐ gōng dà xué liú xué shēng gōng yù。','Chào bác tài, phiền bác cho cháu đến ký túc xá lưu học sinh trường Đại học Bách khoa tỉnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_03','V215','Tài xế',3,'是新校区那个留学生宿舍吧？','shì xīn xiào qū nà ge liú xué shēng sù shè ba？','Là ký túc xá lưu học sinh ở khu campus mới đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_04','V215','Nguyễn Minh',4,'对的！我第一次去，辛苦您多留意路线呢。','duì de！ wǒ dì yī cì qù， xīn kǔ nín duō liú yì lù xiàn ne。','Đúng rồi ạ! Cháu đi lần đầu, phiền bác để ý đường đi giúp cháu với.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_05','V215','Tài xế',5,'放心吧，这条路我常跑，不会走错的。','fàng xīn ba， zhè tiáo lù wǒ cháng pǎo， bú huì zǒu cuò de。','Yên tâm đi, đoạn đường này bác chạy hoài, không đi lộn đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_06','V215','Nguyễn Minh',6,'那就太好了，谢谢您！','nà jiù tài hǎo le， xiè xiè nín！','Vậy thì tốt quá, cảm ơn bác nhiều!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT216','S2','Thanh toán quét mã sau khi đi taxi','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V216','SIT216','P1','twist','tuy_y','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_01','V216','Tài xế',1,'同学，我们到学校门口啦，车程结束了。','tóng xué， wǒ men dào xué xiào mén kǒu la， chē chéng jié shù le。','Em ơi, tới cổng trường rồi nè, kết thúc chuyến xe rồi nha.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_02','V216','Nguyễn Minh',2,'好的！我想扫码支付，可是手机网络有点慢怎么办？','hǎo de！ wǒ xiǎng sǎo mǎ zhī fù， kě shì shǒu jī wǎng luò yǒu diǎn màn zěn me bàn？','Dạ vâng! Em muốn quét mã thanh toán, nhưng mạng điện thoại hơi chậm thì phải làm sao ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_03','V216','Tài xế',3,'没关系呀，不急，你慢慢加载就行。','méi guān xì ya， bù jí， nǐ màn màn jiā zài jiù xíng。','Không sao đâu, không vội, em cứ từ từ chờ tải xong là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_04','V216','Nguyễn Minh',4,'终于好了，已经支付成功啦，您看一下！','zhōng yú hǎo le， yǐ jīng zhī fù chéng gōng la， nín kàn yī xià！','Cuối cùng cũng được rồi, thanh toán thành công rồi nè, chú xem qua giúp em!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_05','V216','Tài xế',5,'收到了，没问题。路上辛苦了，欢迎下次坐车哈！','shōu dào le， méi wèn tí。 lù shàng xīn kǔ le， huān yíng xià cì zuò chē hā！','Nhận được rồi, không vấn đề gì. Đi đường vất vả rồi, lần sau lại đi xe của chú nhé!','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_06','V216','Nguyễn Minh',6,'谢谢师傅，再见！','xiè xiè shī fù， zài jiàn！','Cảm ơn chú tài xế, chào chú ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT217','S7','Nhận phòng ký túc xá','Xuất trình giấy tờ, nhận phòng và chìa khóa','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V217','SIT217','P1','suon_se','ban_chinh_thuc','Xuất trình giấy tờ, nhận phòng và chìa khóa',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_01','V217','Nguyễn Minh',1,'老师您好，我是新来的留学生，今天来办理宿舍入住。','lǎo shī nín hǎo， wǒ shì xīn lái de liú xué shēng， jīn tiān lái bàn lǐ sù shè rù zhù。','Chào cô ạ, em là du học sinh mới đến, hôm nay em đến làm thủ tục nhận phòng ký túc xá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_02','V217','Tiền sảnh',2,'好的，请出示你的护照和入学通知书哦。','hǎo de， qǐng chū shì nǐ de hù zhào hé rù xué tōng zhī shū ó。','Được rồi, em cho cô xem hộ chiếu và giấy báo nhập học nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_03','V217','Nguyễn Minh',3,'好的，这是我的证件和录取文件，您看一下。','hǎo de， zhè shì wǒ de zhèng jiàn hé lù qǔ wén jiàn， nín kàn yī xià。','Dạ vâng, đây là giấy tờ tùy thân và giấy báo trúng tuyển của em, cô xem giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_04','V217','Tiền sảnh',4,'信息核对无误，这是你的宿舍钥匙和门禁卡。','xìn xī hé duì wú wù， zhè shì nǐ de sù shè yào shi hé mén jìn kǎ。','Thông tin đối chiếu không có sai sót, đây là chìa khóa phòng và thẻ ra vào của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_05','V217','Nguyễn Minh',5,'请问我的宿舍是几楼几号呀？','qǐng wèn wǒ de sù shè shì jǐ lóu jǐ hào ya？','Cho em hỏi phòng của em ở tầng mấy, phòng số mấy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_06','V217','Tiền sảnh',6,'四楼408室，单人留学生宿舍，条件还不错呢。','sì lóu 408 shì， dān rén liú xué shēng sù shè， tiáo jiàn hái bú cuò ne。','Tầng 4 phòng 408, phòng dành cho du học sinh ở một mình, điều kiện cũng khá đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_07','V217','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô nhiều lắm ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT218','S7','Ký hợp đồng ở ký túc xá','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V218','SIT218','P1','suon_se','ban_chinh_thuc','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_01','V218','Tiền sảnh',1,'这是留学生住宿合同，你仔细看一下条款哦。','zhè shì liú xué shēng zhù sù hé tóng， nǐ zǐ xì kàn yī xià tiáo kuǎn ó。','Đây là hợp đồng ở ký túc xá dành cho du học sinh, em xem kỹ các điều khoản nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_02','V218','Nguyễn Minh',2,'好的，请问主要是住宿规定和缴费事项吧？','hǎo de， qǐng wèn zhǔ yào shì zhù sù guī dìng hé jiǎo fèi shì xiàng ba？','Dạ vâng, chủ yếu là quy định về chỗ ở và các khoản đóng phí đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_03','V218','Tiền sảnh',3,'对的，还有作息时间、宿舍安全的相关要求呢。','duì de， hái yǒu zuò xī shí jiān、 sù shè ān quán de xiāng guān yāo qiú ne。','Đúng vậy, còn có cả quy định về giờ giấc sinh hoạt và an toàn trong ký túc xá nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_04','V218','Nguyễn Minh',4,'我看完了，没有疑问，可以签字了吗？','wǒ kàn wán le， méi yǒu yí wèn， kě yǐ qiān zì le ma？','Em xem xong rồi ạ, không có thắc mắc gì, giờ em ký được chưa ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_05','V218','Tiền sảnh',5,'可以的，在这里签上你的中文或英文姓名就行。','kě yǐ de， zài zhè lǐ qiān shàng nǐ de zhōng wén huò yīng wén xìng míng jiù xíng。','Được rồi, em ký tên tiếng Trung hoặc tiếng Anh vào đây là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_06','V218','Nguyễn Minh',6,'好的，我签好了，交给您。','hǎo de， wǒ qiān hǎo le， jiāo gěi nín。','Dạ vâng, em ký xong rồi, gửi lại cô ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_07','V218','Tiền sảnh',7,'手续办完，祝你入住愉快！','shǒu xù bàn wán， zhù nǐ rù zhù yú kuài！','Thủ tục xong rồi, chúc em ở đây vui vẻ nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT219','S7','Hỏi WiFi, phòng giặt, giờ đóng cửa ký túc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V219','SIT219','P1','suon_se','ban_chinh_thuc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_01','V219','Nguyễn Minh',1,'老师您好，我想咨询几个宿舍的相关问题可以吗？','lǎo shī nín hǎo， wǒ xiǎng zī xún jǐ gè sù shè de xiāng guān wèn tí kě yǐ ma？','Chào cô ạ, em muốn hỏi vài vấn đề liên quan đến ký túc xá, được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_02','V219','Tiền sảnh',2,'当然可以，你尽管问哈。','dāng rán kě yǐ， nǐ jǐn guǎn wèn hā。','Đương nhiên được, em cứ hỏi thoải mái nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_03','V219','Nguyễn Minh',3,'请问宿舍WiFi密码是多少？洗衣房在哪个位置啊？','qǐng wèn sù shè WiFi mì mǎ shì duō shǎo？ xǐ yī fáng zài nǎ ge wèi zhì a？','Cho em hỏi mật khẩu WiFi ký túc xá là gì ạ? Phòng giặt đồ ở đâu ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_04','V219','Tiền sảnh',4,'WiFi密码贴在房门背后，洗衣房在二楼楼梯口呢。','WiFi mì mǎ tiē zài fáng mén bèi hòu， xǐ yī fáng zài èr lóu lóu tī kǒu ne。','Mật khẩu WiFi dán ở mặt sau cửa phòng, phòng giặt ở đầu cầu thang tầng 2 nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_05','V219','Nguyễn Minh',5,'那宿舍门禁的开关时间是几点呀？','nà sù shè mén jìn de kāi guān shí jiān shì jǐ diǎn ya？','Vậy cửa ký túc xá mở và đóng lúc mấy giờ ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_06','V219','Tiền sảnh',6,'早上六点开门，晚上十一点关门，记得按时回寝哦。','zǎo shàng liù diǎn kāi mén， wǎn shàng shí yì diǎn guān mén， jì de àn shí huí qǐn ó。','Sáng 6 giờ mở cửa, tối 11 giờ đóng cửa, nhớ về phòng đúng giờ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_07','V219','Nguyễn Minh',7,'好的，我都记住了，谢谢您！','hǎo de， wǒ dōu jì zhù le， xiè xiè nín！','Dạ vâng, em nhớ hết rồi ạ, cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT220','S7','Báo hỏng đèn phòng','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V220','SIT220','P1','that_bai_nhe','tuy_y','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_01','V220','Nguyễn Minh',1,'阿姨您好，我是408宿舍的同学，房间的顶灯不亮了。','ā yí nín hǎo， wǒ shì 408 sù shè de tóng xué， fáng jiān de dǐng dēng bù liàng le。','Cô ơi, em là sinh viên phòng 408, đèn trần trong phòng em không sáng nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_02','V220','Quản lý',2,'是完全不亮，还是一闪一闪的呀？','shì wán quán bù liàng， hái shì yī shǎn yī shǎn de ya？','Là tắt hẳn luôn hay chỉ nhấp nháy vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_03','V220','Nguyễn Minh',3,'完全打不开，应该是坏掉了呢。','wán quán dǎ bù kāi， yīng gāi shì huài diào le ne。','Tắt hẳn luôn ạ, chắc là hỏng rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_04','V220','Quản lý',4,'好的，我帮你登记报修，维修师傅明天上午过来修哈。','hǎo de， wǒ bāng nǐ dēng jì bào xiū， wéi xiū shī fù míng tiān shàng wǔ guò lái xiū hā。','Được rồi, cô ghi nhận báo sửa cho em, thợ sẽ đến sửa vào sáng mai nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_05','V220','Nguyễn Minh',5,'好的，今晚只能先开台灯了，麻烦阿姨啦！','hǎo de， jīn wǎn zhǐ néng xiān kāi tái dēng le， má fán ā yí la！','Dạ vâng, tối nay chắc em phải bật đèn bàn tạm thôi, phiền cô quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_06','V220','Quản lý',6,'没事的，小事而已，明天肯定修好。','méi shì de， xiǎo shì ér yǐ， míng tiān kěn dìng xiū hǎo。','Không sao đâu, chuyện nhỏ thôi mà, mai chắc chắn sửa xong.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT221','S6','Mở tài khoản ngân hàng, lấy số','Lấy số thứ tự và điền đơn mở tài khoản','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V221','SIT221','P1','suon_se','chinh_thuc','Lấy số thứ tự và điền đơn mở tài khoản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_01','V221','Nguyễn Minh',1,'您好，我想办理银行卡开户业务，请问怎么操作？','nín hǎo， wǒ xiǎng bàn lǐ yín háng kǎ kāi hù yè wù， qǐng wèn zěn me cāo zuò？','Chào chị, tôi muốn làm thủ tục mở thẻ ngân hàng, cho hỏi phải làm thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_02','V221','Quản lý sảnh',2,'您好，先在取号机取个排队号，再填写这份开户申请表哦。','nín hǎo， xiān zài qǔ hào jī qǔ gè pái duì hào， zài tián xiě zhè fèn kāi hù shēn qǐng biǎo ó。','Chào anh, anh lấy số thứ tự ở máy lấy số trước, rồi điền vào đơn đăng ký mở tài khoản này ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_03','V221','Nguyễn Minh',3,'好的，表格上的信息我都如实填写就可以吧？','hǎo de， biǎo gé shàng de xìn xī wǒ dōu rú shí tián xiě jiù kě yǐ ba？','Vâng, thông tin trên mẫu đơn tôi điền đúng sự thật là được phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_04','V221','Quản lý sảnh',4,'对的，姓名、证件信息、住址全部填完整就行。','duì de， xìng míng、 zhèng jiàn xìn xī、 zhù zhǐ quán bù tián wán zhěng jiù xíng。','Đúng vậy, họ tên, thông tin giấy tờ, địa chỉ điền đầy đủ là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_05','V221','Nguyễn Minh',5,'表格填好了，号也取到了，接下来等待叫号吗？','biǎo gé tián hǎo le， hào yě qǔ dào le， jiē xià lái děng dài jiào hào ma？','Tôi điền xong rồi, cũng lấy số rồi, tiếp theo là chờ gọi số phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_06','V221','Quản lý sảnh',6,'是的，轮到你的时候直接去柜台办理即可。','shì de， lún dào nǐ de shí hòu zhí jiē qù guì tái bàn lǐ jí kě。','Vâng, đến lượt anh thì cứ ra quầy làm thủ tục là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_07','V221','Nguyễn Minh',7,'好的，谢谢您的指导！','hǎo de， xiè xiè nín de zhǐ dǎo！','Vâng, cảm ơn chị đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT222','S6','Xuất trình giấy tờ mở thẻ ngân hàng','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V222','SIT222','P1','twist','chinh_thuc','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_01','V222','Nhân viên',1,'您好，请问办理什么业务？','nín hǎo， qǐng wèn bàn lǐ shén me yè wù？','Chào anh, anh muốn làm dịch vụ gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_02','V222','Nguyễn Minh',2,'您好，我是留学生，想办理储蓄卡开户。','nín hǎo， wǒ shì liú xué shēng， xiǎng bàn lǐ chǔ xù kǎ kāi hù。','Chào chị, tôi là du học sinh, muốn mở thẻ tiết kiệm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_03','V222','Nhân viên',3,'麻烦出示你的护照、签证和学校在读证明哦。','má fán chū shì nǐ de hù zhào、 qiān zhèng hé xué xiào zài dú zhèng míng ó。','Phiền anh cho xem hộ chiếu, visa và giấy xác nhận đang học tại trường ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_04','V222','Nguyễn Minh',4,'证件都在这里，在读证明我打印的黑白版可以吗？','zhèng jiàn dōu zài zhè lǐ， zài dú zhèng míng wǒ dǎ yìn de hēi bái bǎn kě yǐ ma？','Giấy tờ đều ở đây cả, giấy xác nhận đang học tôi in bản đen trắng có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_05','V222','Nhân viên',5,'可以的，黑白有效，我帮你录入系统信息。','kě yǐ de， hēi bái yǒu xiào， wǒ bāng nǐ lù rù xì tǒng xìn xī。','Được ạ, bản đen trắng vẫn có giá trị, tôi sẽ nhập thông tin vào hệ thống cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_06','V222','Nguyễn Minh',6,'好的，辛苦您了！大概多久能办好呀？','hǎo de， xīn kǔ nín le！ dà gài duō jiǔ néng bàn hǎo ya？','Vâng, chị vất vả rồi! Khoảng bao lâu thì xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_07','V222','Nhân viên',7,'很快的，三分钟就能完成开卡流程。','hěn kuài de， sān fēn zhōng jiù néng wán chéng kāi kǎ liú chéng。','Nhanh thôi ạ, khoảng ba phút là hoàn tất thủ tục mở thẻ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT223','S6','Kích hoạt thẻ ngân hàng mới','Đổi mật khẩu ban đầu để kích hoạt thẻ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V223','SIT223','P1','suon_se','chinh_thuc','Đổi mật khẩu ban đầu để kích hoạt thẻ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_01','V223','Nhân viên',1,'银行卡已经办好了，需要现场激活修改初始密码哦。','yín háng kǎ yǐ jīng bàn hǎo le， xū yào xiàn chǎng jī huó xiū gǎi chū shǐ mì mǎ ó。','Thẻ ngân hàng của anh đã làm xong rồi, cần kích hoạt tại chỗ và đổi mật khẩu ban đầu ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_02','V223','Nguyễn Minh',2,'好的，请问我怎么操作呢？我不太会用机器。','hǎo de， qǐng wèn wǒ zěn me cāo zuò ne？ wǒ bù tài huì yòng jī qì。','Vâng, cho hỏi tôi phải thao tác như thế nào ạ? Tôi không rành dùng máy lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_03','V223','Nhân viên',3,'没关系，我一步步教你，先输入初始密码，再设置新密码。','méi guān xì， wǒ yí bù bù jiāo nǐ， xiān shū rù chū shǐ mì mǎ， zài shè zhì xīn mì mǎ。','Không sao ạ, tôi sẽ hướng dẫn anh từng bước, trước tiên nhập mật khẩu ban đầu, sau đó đặt mật khẩu mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_04','V223','Nguyễn Minh',4,'好，我设置好了，这样就激活成功了吧？','hǎo， wǒ shè zhì hǎo le， zhè yàng jiù jī huó chéng gōng le ba？','Được rồi, tôi đặt xong rồi, vậy là kích hoạt thành công phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_05','V223','Nhân viên',5,'对的，现在可以正常存取款、扫码支付了。','duì de， xiàn zài kě yǐ zhèng cháng cún qǔ kuǎn、 sǎo mǎ zhī fù le。','Đúng vậy, bây giờ anh có thể gửi rút tiền, quét mã thanh toán bình thường rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn chị đã giúp đỡ nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương ơi, tớ muốn đăng ký WeChat Pay, còn phải xác thực danh tính thật đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi, không xác thực thì không quét mã trả tiền hay chuyển khoản được đâu.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy du học sinh dùng hộ chiếu cũng xác thực được à? Tớ không có chứng minh thư đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, làm theo hướng dẫn upload ảnh lên là xong ngay.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi à, tớ thử luôn đây!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Có gì không hiểu cứ gọi tớ, tớ chỉ cho.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ nhé, bạn quét mã thanh toán là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Vâng, em mở mã QR WeChat lên, chị quét cho em nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được đấy, hoặc em quét mã ở quầy thu ngân cũng được nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Em quét xong rồi, thanh toán thành công rồi, chị xem thử đi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi, ổn rồi! Cầm đồ cẩn thận, đi đường bình an nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào thầy/cô, em là sinh viên mới Nguyễn Minh, hôm nay đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp hộ chiếu, visa và giấy báo trúng tuyển giúp cô nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Vâng ạ, đây là toàn bộ giấy tờ của em, mời cô kiểm tra giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ, không thiếu sót gì, để cô hoàn tất đăng ký sinh viên mới cho em nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Cho em hỏi sau đây còn thủ tục báo danh nào khác không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Cơ bản là xong rồi, tiếp theo thông báo đăng ký môn học và khám sức khỏe sẽ gửi chung trong nhóm nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Vâng ạ, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','新生报到材料缺失，多数学校允许限期补交，态度诚恳致歉即可，无需过度紧张；线上截图、电子版打印件大多不具备归档效力，必须纸质复印件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','老师',1,'同学你先坐，我们核对一下新生报到需要提交的全套材料。','tóng xué nǐ xiān zuò， wǒ men hé duì yī xià xīn shēng bào dào xū yào tí jiāo de quán tào cái liào。','Em ngồi xuống đi, thầy kiểm tra lại toàn bộ giấy tờ cần nộp cho thủ tục báo danh sinh viên mới nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','阮明',2,'好的老师，我把手里的文件都拿出来给您核对。','hǎo de lǎo shī， wǒ bǎ shǒu lǐ de wén jiàn dōu ná chū lái gěi nín hé duì。','Vâng thưa thầy, em lấy hết giấy tờ đang cầm ra để thầy kiểm tra ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','老师',3,'毕业证复印件、签证页、体检表都齐了，还差一份疫苗接种证明，你带过来了吗？','bì yè zhèng fù yìn jiàn、 qiān zhèng yè、 tǐ jiǎn biǎo dōu qí le， hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Bản sao bằng tốt nghiệp, trang visa, phiếu khám sức khỏe đều đủ rồi, còn thiếu giấy chứng nhận tiêm vaccine, em có mang theo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','阮明',4,'不好意思老师，出门收拾行李的时候漏掉这份材料，我完全忘记带了，非常抱歉。','bù hǎo yì sī lǎo shī， chū mén shōu shí xíng lǐ de shí hòu lòu diào zhè fèn cái liào， wǒ wán quán wàng jì dài le， fēi cháng bào qiàn。','Em xin lỗi thầy, lúc thu dọn hành lý ra khỏi nhà em bỏ sót giấy này, em quên hẳn không mang theo, em thực sự xin lỗi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','老师',5,'没事的，不用紧张，很多新生都会出现材料遗漏的情况。','méi shì de， bù yòng jǐn zhāng， hěn duō xīn shēng dōu huì chū xiàn cái liào yí lòu de qíng kuàng。','Không sao đâu, đừng căng thẳng, rất nhiều sinh viên mới cũng bị thiếu giấy tờ như vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','阮明',6,'我心里特别着急，怕耽误今天的新生登记流程，影响后续选课住宿。','wǒ xīn lǐ tè bié zháo jí， pà dān wù jīn tiān de xīn shēng dēng jì liú chéng， yǐng xiǎng hòu xù xuǎn kè zhù sù。','Trong lòng em thấy rất lo, sợ làm chậm trễ thủ tục đăng ký sinh viên mới hôm nay, ảnh hưởng đến việc chọn môn và ở ký túc xá sau này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_07','V227','老师',7,'我先跟你说明学校的规定，所有材料必须完整归档，不能长期缺件。','wǒ xiān gēn nǐ shuō míng xué xiào de guī dìng， suǒ yǒu cái liào bì xū wán zhěng guī dàng， bù néng cháng qī quē jiàn。','Trước tiên thầy nói cho em rõ quy định của trường, mọi giấy tờ đều phải nộp đầy đủ để lưu hồ sơ, không được thiếu kéo dài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_08','V227','阮明',8,'那请问我明天补交可以吗？明天补交完整不会影响我的新生报到手续吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ míng tiān bǔ jiāo wán zhěng bú huì yǐng xiǎng wǒ de xīn shēng bào dào shǒu xù ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Ngày mai nộp đủ thì có ảnh hưởng đến thủ tục báo danh sinh viên mới của em không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_09','V227','老师',9,'正常截止时间是今天下午五点，严格来说逾期不予受理，不过可以给你特殊放宽一天。','zhèng cháng jié zhǐ shí jiān shì jīn tiān xià wǔ wǔ diǎn， yán gé lái shuō yú qī bù yǔ shòu lǐ， bù guò kě yǐ gěi nǐ tè shū fàng kuān yī tiān。','Hạn bình thường là năm giờ chiều hôm nay, nói nghiêm túc thì quá hạn sẽ không được tiếp nhận nữa, nhưng thầy có thể châm chước cho em thêm một ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_10','V227','阮明',10,'太感谢老师愿意通融，我明天一早就回家找出证明，复印完整送过来。','tài gǎn xiè lǎo shī yuàn yì tōng róng， wǒ míng tiān yī zǎo jiù huí jiā zhǎo chū zhèng míng， fù yìn wán zhěng sòng guò lái。','Em cảm ơn thầy rất nhiều vì đã thông cảm, sáng sớm mai em sẽ về nhà tìm giấy chứng nhận, photo đầy đủ rồi mang đến ngay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_11','V227','老师',11,'记住一定要带纸质原件复印件，照片截图打印出来是不被认可的。','jì zhù yí dìng yào dài zhǐ zhì yuán jiàn fù yìn jiàn， zhào piān jié tú dǎ yìn chū lái shì bù bèi rèn kě de。','Nhớ là phải mang bản gốc giấy và bản photo nhé, ảnh chụp màn hình in ra thì không được chấp nhận đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_12','V227','阮明',12,'我记下这条要求了，明天一定准备规范的纸质文件。','wǒ jì xià zhè tiáo yāo qiú le， míng tiān yí dìng zhǔn bèi guī fàn de zhǐ zhì wén jiàn。','Em ghi nhớ yêu cầu này rồi, ngày mai em nhất định chuẩn bị đầy đủ giấy tờ đúng chuẩn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_13','V227','老师',13,'行，我先把你现有材料临时存档，等你补齐再统一录入系统。','xíng， wǒ xiān bǎ nǐ xiàn yǒu cái liào lín shí cún dàng， děng nǐ bǔ qí zài tǒng yī lù rù xì tǒng。','Được, thầy tạm lưu hồ sơ hiện có của em, đợi em bổ sung xong thì nhập chung vào hệ thống một thể.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_14','V227','阮明',14,'给老师增添额外工作量实在不好意思，我明天准时送来！','gěi lǎo shī zēng tiān é wài gōng zuò liàng shí zài bù hǎo yì sī， wǒ míng tiān zhǔn shí sòng lái！','Em thấy áy náy quá vì làm phiền thầy thêm việc, ngày mai em sẽ mang đến đúng giờ ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào thầy/cô, em muốn chọn lớp tiếng Trung nhưng nó đã hiện đầy chỗ rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp này hot nên chỗ đã bị đăng ký hết rồi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể chuyển sang lớp ở khung giờ khác được không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học giống hệt nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em đổi trực tiếp sang lớp này được luôn phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác trực tiếp trên hệ thống là được, không cần xin phép thêm gì cả.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, rất vui được làm học trò của cô ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường, em đã quen với cuộc sống ở đây chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang quen dần ạ, em muốn hỏi cô một chút, việc chọn môn của chuyên ngành mình nên chú trọng điểm gì ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì có thể chọn những môn liên quan đến thương mại quốc tế nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Vâng ạ, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải thôi, không cần chọn quá nhiều môn, tránh áp lực quá lớn nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Bạn ơi, qua đây chụp ảnh làm thẻ sinh viên nào.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Vâng ạ, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em chưa rõ lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, để em chỉnh lại chút, thế này được chưa ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Cứ giữ nụ cười, nhìn vào ống kính, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là làm thẻ sinh viên luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ nhập vào hệ thống, một tuần sau là em lấy thẻ được rồi.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào thầy/cô, em là sinh viên mới, muốn làm thẻ thư viện để mượn sách ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em xuất trình thẻ sinh viên là làm miễn phí cho em ngay nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Đây ạ, làm xong thì mỗi lần em được mượn mấy quyển sách vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Du học sinh mỗi lần được mượn mười quyển, thời hạn mượn là ba mươi ngày nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Trung này được chứ ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô quét mã đăng ký cho em, mượn thành công rồi đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em không đăng nhập được email trường, mật khẩu ban đầu nó cứ báo sai.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy hả? Hay em gõ nhầm chữ hoa chữ thường rồi?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Cũng có thể lắm! Em toàn không để ý phân biệt hoa thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ cho, gõ lại đúng hoa thường là đăng nhập được ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Vào được rồi! Giờ muốn đổi mật khẩu thì làm sao ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào phần trung tâm cá nhân mà đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ được, em đổi ngay đây, cảm ơn anh nhiều lắm luôn!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng, em nộp bài trên hệ thống học tập mà cứ bị lỗi mãi không nộp được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là không tải file lên được, hay là trang bị đơ vậy em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ tải mãi không xong, em bấm nộp bài thì chẳng thấy phản hồi gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống bị nghẽn vào buổi tối, hôm nay nhiều bạn cũng gặp tình trạng này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị tính trễ hạn rồi trừ điểm không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, lỗi hệ thống thì sẽ gia hạn nộp bài cho tất cả, mai sáng nộp lại cũng được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','Tuyệt quá, cảm ơn thầy/cô đã báo cho em biết!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào cán bộ, em muốn hỏi về phạm vi chi trả của bảo hiểm y tế sinh viên quốc tế ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Không vấn đề gì, bảo hiểm của trường chủ yếu chi trả chi phí khám ngoại trú và nội trú ở bệnh viện công nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh vặt như cảm cúm, viêm dạ dày ruột cũng được chi trả đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi chi trả, kể cả tai nạn thương tích cũng được bồi thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Cho em hỏi có những khoản nào không được chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả đâu nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn cán bộ đã giải thích tận tình!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào chị, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi thủ tục làm thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự động trước, rồi điền vào tờ thông tin cá nhân này nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Dạ vâng, phần quốc tịch với loại giấy tờ trong tờ khai cứ điền đúng thực tế là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng rồi, thông tin phải điền chính xác hết, tránh để phiếu khám bị sai sót nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền xong tờ khai và lấy số rồi, tiếp theo làm gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Cầm phiếu đi khám lần lượt từng mục là được, quy trình đơn giản lắm nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu em ơi, nói cho biết trước, đường lớn phía trước giờ cao điểm sáng đang tắc kín hết, xe chạy chậm lắm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác tài ơi, sáng nay em có tiết chuyên ngành, còn mười phút nữa là vào học rồi, cứ tắc thế này chắc trễ học mất!','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình, cả ba làn đường lớn đều tắc cứng, khó mà thông nhanh được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không ạ, miễn kịp giờ vào học là được rồi?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Cũng có một con đường nhỏ trong khu dân cư đi vòng được, chỉ có điều xa hơn khoảng hai cây số thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng xa thêm chút cũng được, miễn đừng trễ học là được, phiền bác đi đường vòng giúp em nhé!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng này nhiều người đi bộ với xe điện lắm, không chạy nhanh được đâu, chỉ đi từ từ đều đều thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được cảnh tắc đường dài trên đường lớn là em mãn nguyện rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, tôi đổi làn xuống cầu vượt ngay bây giờ, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Khoảng mấy phút nữa thì tới cổng trường ạ, để em biết mà yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Thuận lợi thì bảy tám phút là tới, còn nhanh hơn đứng chôn chân chờ tới hai mươi phút ấy chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ học rồi bị trừ điểm chuyên cần, cảm ơn bác đã cất công đi vòng giúp em!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, học sinh đi học mới quan trọng, tôi sẽ cố lái êm để không làm chậm trễ em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em cho bác năm sao luôn, thật sự cảm ơn bác nhiều lắm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng ba mươi tám tệ, phiền anh/chị thanh toán giúp em nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Vâng, em trả tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi anh/chị nhé, cửa hàng em giờ không nhận tiền mặt nữa, chỉ nhận quét mã WeChat hoặc Alipay thôi ạ.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Ra vậy à, vậy để em mở điện thoại quét mã ngay đây.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, anh/chị cứ từ từ thao tác, thanh toán xong em xuất hóa đơn liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Thanh toán xong rồi nè, cảm ơn đã nhắc em nhé!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào mà không thấy phản ứng gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô ra xem thử nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Dạ đúng ạ, con thử hai lần rồi vẫn không được, quần áo bỏ vào mà không giặt nổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này đang bị trục trặc tạm thời, con đổi qua dùng cái máy bên cạnh là được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Dạ vâng, vậy máy hỏng chừng nào mới sửa xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai thợ tới kiểm tra sửa, tối nay con cứ dùng tạm máy khác nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi, cảm ơn cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào chị, xin lỗi vì đã làm phiền chị ạ! Hình như em đi nhầm chiều tàu điện ngầm rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo, em định đi đâu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đi khu đô thị đại học, vừa nãy lên tàu bị ngược chiều rồi, giờ không biết đổi chuyến thế nào ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ở ga tiếp theo, sang sân ga đối diện bắt tuyến số hai là đi thẳng tới nơi luôn nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Dạ vâng, vậy em không cần mua vé lại đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi chuyến trong ga là miễn phí hết, em cứ yên tâm lên tàu nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Cảm ơn chị nhiều lắm ạ, chị giúp em một việc lớn thật đó!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì đâu, lần sau nhìn kỹ chiều rồi hãy lên tàu nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, bạn là Nguyễn Minh phải không? Hàng thu hộ của bạn tới rồi nè, là chăn ga với đồ bếp đúng không?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền bạn kiểm tra lại thông tin giúp mình nha! Số điện thoại đuôi 3621 đúng không?','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng rồi đó! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Cước phí tổng cộng là 28 tệ nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Mình thấy trên app dự tính là 22 tệ, sao lại dư ra 6 tệ vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn nặng quá cân đó, phần vượt cân phải bù thêm cước phí, app dự tính không chính xác đâu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, thế thì không sao, mình quét mã trả tiền nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được rồi! Trả xong mình ký nhận cho bạn, đồ đạc còn nguyên vẹn hết, bạn có thể kiểm tra thử.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu, cảm ơn bạn đã vất vả chạy một chuyến nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Em ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Dạ cô ơi, cho con một phần cơm trứng chiên cà chua, cảm ơn cô!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi! Có muốn thêm món kèm không? Rau xanh với khoai tây đều tươi hết.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Dạ thôi ạ! Phiền cô nhất định đừng cho cay nha, con không ăn được cay chút nào luôn.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, cô làm cho con vị thanh đạm.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, cảm ơn cô nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi mà! Sắp xong rồi, con đợi xíu nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Anh Vũ ơi, mấy hôm nay em thấy hơi khó chịu, muốn nói với anh một chuyện.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, khó ở à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là do chưa quen thủy thổ, tối cứ ngủ không ngon, ban ngày lên lớp thì buồn ngủ kinh khủng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay thấy em ít nói hẳn! Vậy em định tính sao đây?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em định chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Dĩ nhiên là được rồi! Em cứ nghỉ ngơi cho khỏe, tối anh nói nhỏ lại, không làm phiền em đâu.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự phiền anh quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì chứ, bạn cùng phòng vốn phải chăm sóc lẫn nhau mà.','AM09');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Chào cô Vương, làm phiền cô rồi ạ! Em muốn hỏi thăm về quy định khách vào trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có bạn định đến ký túc tìm em à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng rồi, mai bạn em muốn đến ký túc tìm em, cần đăng ký thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy tối có thể vào thăm không ạ? Em định hẹn gặp nhau vào buổi tối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Tối thì không được đâu, ký túc xá khóa cửa lúc mười giờ, buổi tối cấm người ngoài vào trường.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Ra là vậy, thế thì em đổi sang ban ngày vậy, cảm ơn cô đã cho em biết ạ!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được rồi, nhớ nhắc bạn em mang giấy tờ tùy thân nha.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi vì đã làm phiền anh nghỉ ngơi, có việc này em cần trao đổi với anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ là hai bên đã hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em thật sự xin lỗi ạ! Chuyến bay nhập cảnh em đi bị hoãn trên diện rộng, giờ hạ cánh bị lùi lại sáu tiếng, hôm nay chắc chắn em không kịp đến rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Hôm nay anh đã dành hẳn buổi chiều ở nhà đợi bàn giao nhà cho em, thay đổi đột xuất thế này đúng là hơi phiền đấy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói sớm nhất cũng phải chiều mai hai giờ em mới tới được trung tâm thành phố.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay bàn giao nhà xong là tối ra ngoài giải quyết việc, giờ lịch trình bị đảo lộn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em lùi lại một ngày nhận phòng được không ạ, chiều mai em sẽ đến đúng giờ, tuyệt đối không trễ nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo quy định thì phòng giữ trong ngày chỉ được bảo lưu đến khuya hôm đó thôi, muốn giữ qua đêm thì phải trả thêm phí bỏ trống nửa ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định mà, miễn là giữ được phòng thì phần phí đó em sẵn sàng đóng bình thường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang, cũng không dễ dàng gì, phí bỏ trống thì anh không thu, nhưng hôm nay anh sẽ không giữ riêng phòng cho em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Em cảm ơn anh rất nhiều vì đã thông cảm và thấu hiểu, việc thay đổi lịch trình đột xuất này gây phiền cho anh nhiều quá, thật sự xin lỗi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo đâu, đi xa khó tránh khỏi có chuyện phát sinh mà, nhưng trước khi đến một tiếng ngày mai nhớ nhắn tin báo anh trước nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo anh giờ em đến trước, để anh tiện về nhà đợi sẵn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy mình hẹn hai giờ chiều mai làm thủ tục nhận phòng nhé, hẹn gặp mai!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này giá bao nhiêu một thùng vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay bên chị đang có chương trình khuyến mãi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy khuyến mãi gì vậy chị, có lời không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng giảm thẳng 20 tệ, khá lời đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế thì em mua hai thùng luôn, bình thường em uống nhiều mà.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được rồi, để chị quét mã cho em, lúc thanh toán sẽ tự động trừ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ được, cảm ơn chị!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, cho con hỏi rau củ quả cân ở đây đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi con, con đặt đồ lên rồi chọn đúng tên rau là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem vậy cô?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem nào, con chọn là cải thảo mà đồ con cầm là rau xanh, chọn nhầm loại rồi kìa.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Ra là vậy, thảo nào cứ không được, để con làm lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, cứ từ từ, dán tem xong là ra máy tự thanh toán được rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Con cảm ơn cô nhiều lắm, không thì con phải loay hoay lâu lắm luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào anh, em có một món hàng bị lỗi chất lượng, muốn đến quầy hậu mãi để đổi trả ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào em, phiền em nói giúp anh đây là món hàng gì, mua ở cửa hàng lúc nào vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Dạ là một ổ bánh mì nguyên cám, em mua chiều tối hôm qua ở khu thực phẩm tươi sống với bánh nướng, sáng nay bóc ra thì đã bị mốc rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền em cho anh xem hóa đơn mua hàng tương ứng, bên anh cần đối chiếu thời gian mua và thông tin lô hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn cất cẩn thận trong ví, đây em đưa anh, em bảo quản ở nhiệt độ thường suốt, có để lâu đâu ạ.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Anh đối chiếu với hồ sơ nhập kho trên hệ thống rồi, xác nhận đúng là do sản phẩm xuất xưởng có vấn đề bảo quản, thật xin lỗi em nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao đâu ạ, em cũng không cố ý làm khó cửa hàng, chỉ lo khách khác lỡ mua phải sản phẩm cùng loại thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Em muốn đổi sản phẩm mới, hay là làm thủ tục hoàn tiền toàn bộ luôn, cả hai phương án đều được hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám chọn lại nữa, làm thủ tục hoàn tiền toàn bộ luôn sẽ hợp lý hơn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, anh thao tác hoàn tiền trên hệ thống ngay đây, tiền sẽ hoàn về đúng phần mềm thanh toán em đã dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Vậy tiền hoàn về mất khoảng bao lâu ạ, có bị chậm trễ gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền thanh toán online là về ngay lập tức, em mở điện thoại lên là thấy số dư thay đổi liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_13','V303','阮明',13,'清楚流程了，给您添麻烦实在不好意思。','qīng chǔ liú chéng le， gěi nín tiān má fán shí zài bù hǎo yì sī。','Em hiểu quy trình rồi ạ, làm phiền anh quá, thật ngại quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_14','V303','店员',14,'是我们商品存在质量瑕疵，本该向您致歉，您慢走。','shì wǒ men shāng pǐn cún zài zhì liàng xiá cī， běn gāi xiàng nín zhì qiàn， nín màn zǒu。','Là do sản phẩm bên anh có lỗi chất lượng, đáng lẽ phải xin lỗi em mới đúng, em đi cẩn thận nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_15','V303','阮明',15,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Dạ vâng, phiền anh nhiều ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Chào chú, con là sinh viên mới, con muốn mua một bộ chăn ga gối cho ký túc xá với cả một cái nồi nấu mini nữa ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có chứ, mấy món này đều là hàng chuyên dùng cho sinh viên, độ dày với công suất đều hợp với ký túc xá hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không chú? Con sợ lạnh lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ ấm để qua mùa đông luôn, chỉ có điều nồi nấu mini cho ký túc xá hôm nay vừa bán hết hàng rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy chừng nào có hàng lại ạ? Con cần gấp lắm.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai là có hàng về liền, mai con qua lấy là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Dạ được, vậy hôm nay con mua trước chăn, gối với ly nước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào dùng tốt vậy chị? Em lần đầu giặt đồ ở ký túc xá đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại chai này là được, mùi nhẹ nhàng, giặt sạch cũng ổn lắm đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Dạ được, vậy máy giặt tự động ở tầng dưới có khó dùng không chị?','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó tí nào đâu, quét mã thanh toán, cho đồ với nước giặt vào là xong à.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Vậy em có cần tự chỉnh thời gian với chế độ giặt không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần đâu, cứ để mặc định chế độ tiêu chuẩn là giặt sạch bong luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Em hiểu rồi, cảm ơn chị nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程；退款不会即时处理，学校后勤固定日期批量结算。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚在宿舍楼自助洗衣房洗衣服，机器运行一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng zài sù shè lóu zì zhù xǐ yī fáng xǐ yī fú， jī qì yùn xíng yí bàn tū rán tíng jī le。','Cô ơi, cháu vừa mới giặt đồ ở phòng giặt tự động của ký túc xá, máy đang chạy nửa chừng thì tự nhiên dừng lại ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'别着急，你先回忆一下，机器停机的时候屏幕有没有弹出提示文字？','bié zháo jí， nǐ xiān huí yì yī xià， jī qì tíng jī de shí hòu píng mù yǒu méi yǒu dàn chū tí shì wén zì？','Cháu đừng lo, cháu thử nhớ lại xem lúc máy dừng thì màn hình có hiện thông báo gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'屏幕显示账户余额不足，自动中断洗涤程序，衣服只洗了一半。','píng mù xiǎn shì zhàng hù yú é bù zú， zì dòng zhōng duàn xǐ dí chéng xù， yī fú zhǐ xǐ le yí bàn。','Màn hình hiện là tài khoản không đủ tiền nên tự động ngắt chương trình giặt, đồ mới giặt được có một nửa thôi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'原来是扣费余额耗尽，这种情况在自助设备使用里十分常见。','yuán lái shì kòu fèi yú é hào jìn， zhè zhǒng qíng kuàng zài zì zhù shè bèi shǐ yòng lǐ shí fēn cháng jiàn。','À thì ra là hết tiền trong tài khoản, trường hợp này với máy tự động thì thường gặp lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'我之前查看余额还有几块钱，以为完全够完整洗完一整轮，没想到中途欠费了。','wǒ zhī qián chá kàn yú é hái yǒu jǐ kuài qián， yǐ wéi wán quán gòu wán zhěng xǐ wán yī zhěng lún， méi xiǎng dào zhōng tú qiàn fèi le。','Trước đó cháu kiểm tra thấy vẫn còn mấy đồng, tưởng đủ để giặt trọn một lượt, ai ngờ giữa chừng lại thiếu tiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'洗衣程序分为洗涤、漂洗、脱水三段，分段扣取费用，余额不够就会中途停机。','xǐ yī chéng xù fēn wéi xǐ dí、 piǎo xǐ、 tuō shuǐ sān duàn， fēn duàn kòu qǔ fèi yòng， yú é bù gòu jiù huì zhōng tú tíng jī。','Chương trình giặt chia làm ba đoạn là giặt, xả và vắt, mỗi đoạn trừ tiền riêng, không đủ tiền là máy dừng giữa chừng liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'那像我这种只洗一半就停机的情况，可以申请退还部分洗衣费用吗？','nà xiàng wǒ zhè zhǒng zhǐ xǐ yí bàn jiù tíng jī de qíng kuàng， kě yǐ shēn qǐng tuì huán bù fèn xǐ yī fèi yòng ma？','Vậy như trường hợp của cháu chỉ giặt được nửa chừng rồi dừng thì có xin hoàn lại một phần tiền giặt được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_08','V306','宿管阿姨',8,'完全可以，后勤处专门有异常扣费退款登记流程，我帮你上报。','wán quán kě yǐ， hòu qín chù zhuān mén yǒu yì cháng kòu fèi tuì kuǎn dēng jì liú chéng， wǒ bāng nǐ shàng bào。','Được chứ, phòng hậu cần có quy trình đăng ký hoàn tiền cho mấy trường hợp trừ tiền bất thường, để cô báo lên giúp cháu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Vậy làm thủ tục hoàn tiền cần in hóa đơn thanh toán giấy, hay chỉ cần gửi ảnh chụp màn hình điện thoại thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in giấy tờ gì đâu, cứ gửi thẳng ảnh chụp lúc thanh toán qua WeChat cho cô là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Ảnh chụp cháu lấy gửi ngay đây ạ, khoảng bao lâu thì tiền hoàn về vậy cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ vào thứ Sáu hàng tuần là xử lý gộp các yêu cầu hoàn tiền, chậm nhất thứ Sáu tuần này tiền sẽ hoàn về đúng chỗ cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Cháu hiểu là phải chờ xử lý gộp rồi ạ, cảm ơn cô đã giúp đăng ký báo lên nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ mà, lần sau giặt đồ nhớ nạp thêm chút tiền vào, để khỏi bị dừng giữa chừng nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ vâng, cảm ơn cô nhiều ạ!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, em lấy một phần bánh kếp ngũ cốc, gói mang đi nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được rồi, em có muốn thêm xúc xích nướng, rau sống mấy thứ đó không?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Thêm một cây xúc xích nướng thôi, cho ít ớt lại nha, em không ăn cay được mấy.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không vấn đề, vị cay nhẹ nha, hai phút là xong à.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Chị làm ơn gói kín kín giúp em nha, em mang về ký túc xá ăn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói cho kín bưng luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn hàng xong, có một số món cần kiêng khem quan trọng muốn ghi chú lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào bạn, bạn cứ nói rõ yêu cầu cụ thể nhé, bên mình sẽ báo ngay cho bếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng đậu phộng khá nặng, đồ ăn tuyệt đối không được cho bất kỳ chế phẩm nào từ đậu phộng vào nhé.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Dạ vâng, bên mình đã ghi chú trọng điểm là kiêng đậu phộng cho đơn của bạn rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây có quán bỏ qua ghi chú, suýt nữa xảy ra chuyện đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Rất xin lỗi vì đã khiến bạn lo lắng, bên mình sẽ dặn riêng bếp kỹ càng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy phiền các bạn để ý giúp thêm nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, cho em hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy chị?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Loại sữa chua để ở nhiệt độ thường này hạn dùng ba tháng, không cần bỏ tủ lạnh đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy mở nắp ra rồi thì để được bao lâu ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, để ở nhiệt độ thường bình thường là được đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, tránh để nắng chiếu trực tiếp vào là được, tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em rõ rồi, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn chút nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, bạn có gì cứ nói thẳng luôn nhé.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Tối nay mình phải ôn thi, phòng các bạn hơi ồn một chút đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn nha, tụi mình không để ý âm lượng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau mười giờ tối thì yên tĩnh một chút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, tụi mình nhỏ tiếng lại ngay, sau này nhất định sẽ chú ý!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thưa thầy con xin lỗi, con vào lớp trễ rồi, con thật sự xin lỗi thầy!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại trễ vậy? Vì lý do gì thế?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Con ra khỏi nhà trễ giờ, lại gặp kẹt xe nên bị lỡ mất thời gian ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải sắp xếp thời gian cho tốt, đừng để trễ nữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Con nhớ rồi ạ, sau này con nhất định sẽ ra khỏi nhà sớm hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, mau vào chỗ ngồi nghe giảng đi, đừng để trễ bài học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Con cảm ơn thầy đã thông cảm ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Chào cố vấn học tập ạ, em muốn xin nghỉ phép chiều nay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được thôi, em nói qua lý do xin nghỉ nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể hoãn lại được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Được rồi, tôi sẽ ghi nhận điểm danh và cho em nghỉ phép.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn cô/thầy, phần bài học bị lỡ em sẽ bổ sung ngay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhớ theo kịp tiến độ, đừng để nợ bài nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi ạ, cảm ơn cô/thầy đã vất vả vì em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Chào thầy/cô ạ, em xin phép chiếm chút thời gian ngoài giờ, em muốn xin gia hạn nộp bài tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói lý do trước đi, quy định lớp học là không được tự ý trì hoãn nộp bài đâu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua em bị đau bụng đột ngột cả ngày, chóng mặt mệt mỏi phải nằm nghỉ, hoàn toàn không còn sức để làm bài ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Việc em không khỏe thì thầy/cô hiểu, ốm là trường hợp đặc biệt hợp lý, nhưng gia hạn thì có thời hạn nghiêm ngặt đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Em vốn định chiều tối nay nộp đúng hạn, nhưng giờ vẫn còn thiếu một nửa nội dung chưa làm xong ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài chỉ được gia hạn tối đa một ngày, không thể kéo dài mãi đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Chỉ gia hạn một ngày là đủ với em rồi ạ, tối nay em sẽ thức khuya làm bài, đảm bảo hoàn thành đầy đủ nội dung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em không khỏe nên thầy/cô châm chước một lần, sau này dù lý do gì cũng phải cố gắng làm đúng hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc nhở của thầy/cô, lần sau em sẽ lên kế hoạch thời gian trước, không để xảy ra chuyện trễ hạn nữa ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp gia hạn phải nộp về văn phòng trước sáu giờ chiều mai, trễ vẫn sẽ bị trừ điểm chuyên cần đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ đặt báo thức để nộp đúng giờ, không để lỡ hạn chót đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi em nộp bài, thầy/cô sẽ chấm ưu tiên, nếu có sai sót sẽ giảng riêng cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em rất cảm ơn thầy/cô đã thông cảm cho tình trạng sức khỏe của em, em nhất định sẽ làm bài nghiêm túc ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho tốt, đừng thức khuya quá mà hại sức khỏe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy/cô ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Nhóm mình vẫn chưa phân công, hôm nay chốt luôn nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được, mình chia việc theo sở trường của từng người, làm vậy sẽ hiệu quả hơn.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Mình giỏi tìm tài liệu với viết nội dung, còn làm PPT cậu ổn không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không vấn đề gì, mình làm PPT khá cứng, cứ để mình lo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy phần thuyết trình cuối cùng trên lớp, hai đứa mình phối hợp với nhau nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được đó, làm xong mình kiểm tra chéo cho nhau, tránh sai sót.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy mỗi đứa bắt tay vào làm phần của mình thôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa thầy/cô, các bạn, em thực sự xin lỗi vì bài thuyết trình lần này của em chuẩn bị chưa đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao, cứ trình bày bình thường thôi, em nói xem vấn đề nằm ở đâu?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Em thu thập tài liệu trước đó chưa kỹ càng, nên nội dung bị thiếu khá nhiều chi tiết ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em đã không chuẩn bị kỹ nội dung từ trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn thẳng vào vấn đề là tốt rồi, lần sau chuẩn bị kỹ càng hơn là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, cảm ơn thầy/cô và các bạn đã thông cảm cho em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Chào thầy/cô ạ, phần kiến thức vừa giảng trên lớp em chưa hiểu lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em chưa hiểu? Để thầy/cô giảng lại cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là cách vận dụng công thức ạ, em vẫn còn hơi mơ hồ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, để thầy/cô tóm tắt lại một lượt, em chú ý nghe nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Dạ vâng, phiền thầy/cô giảng giải giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, đừng ngại nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hoàn toàn rồi ạ, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Chào thầy/cô, em muốn hỏi về quy định phòng thi cho kỳ thi cuối kỳ lần này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Nếu em có gì chưa rõ thì cứ hỏi trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Xin hỏi trong lúc thi em có được mang theo giấy nháp và dụng cụ học tập không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát đầy đủ vật dụng thi thống nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử có cần tháo ra để riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải cất riêng theo quy định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Em đã rõ hết các quy định rồi ạ, cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Chào thầy/cô ạ, em muốn xác nhận lại điểm cuối kỳ môn học của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể là vấn đề gì vậy em?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Em đã hoàn thành đầy đủ bài tập, điểm danh, thi cử bình thường, nhưng hệ thống lại hiện không có điểm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là hệ thống giáo vụ nhập liệu bị trục trặc, xảy ra lỗi dữ liệu rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo là mình lỡ thiếu nộp bài nào đó, trong lòng bất an quá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em yên tâm, thầy/cô sẽ kiểm tra lại hồ sơ thủ công và nhập lại điểm cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn thầy/cô rất nhiều vì đã giúp em xử lý ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道；复核结果统一公示，具备官方效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，今天来找您，是想正式提交本次期末试卷成绩复核申请。','lǎo shī nín hǎo， jīn tiān lái zhǎo nín， shì xiǎng zhèng shì tí jiāo běn cì qī mò shì juàn chéng jì fù hé shēn qǐng。','Chào thầy/cô ạ, hôm nay em đến gặp thầy/cô là để chính thức xin nộp đơn phúc khảo điểm bài thi cuối kỳ lần này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'先坐，我先跟你确认，你清楚学校成绩复核的具体范围和规则吗？','xiān zuò， wǒ xiān gēn nǐ què rèn， nǐ qīng chǔ xué xiào chéng jì fù hé de jù tǐ fàn wéi hé guī zé ma？','Em ngồi xuống đi, thầy/cô hỏi trước, em có nắm rõ phạm vi và quy định phúc khảo điểm của trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'只听说可以核对卷面总分统计，不能重新评判答题内容，细节了解不多。','zhǐ tīng shuō kě yǐ hé duì juàn miàn zǒng fēn tǒng jì， bù néng chóng xīn píng pàn dá tí nèi róng， xì jié liǎo jiě bù duō。','Em chỉ nghe nói là có thể kiểm tra lại tổng điểm bài thi, chứ không được chấm lại nội dung bài làm, chi tiết thì em chưa hiểu rõ lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'没错，复核仅检查每道小题得分相加是否计算错误，不会更改主观题打分。','méi cuò， fù hé jǐn jiǎn chá měi dào xiǎo tí dé fēn xiāng jiā shì fǒu jì suàn cuò wù， bú huì gēng gǎi zhǔ guān tí dǎ fēn。','Đúng vậy, phúc khảo chỉ kiểm tra xem điểm từng câu cộng lại có tính sai hay không, chứ không thay đổi điểm chấm phần tự luận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'我自己对照参考答案预估的分数，和最终系统录入成绩差距很大，心里比较疑惑。','wǒ zì jǐ duì zhào cān kǎo dá àn yù gū de fēn shù， hé zuì zhōng xì tǒng lù rù chéng jì chā jù hěn dà， xīn lǐ bǐ jiào yí huò。','Em tự đối chiếu đáp án tham khảo và ước tính điểm của mình, nhưng chênh lệch khá nhiều so với điểm hệ thống ghi nhận, em thấy khá thắc mắc ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'我理解你的顾虑，我可以协助你向学院教学办提交官方书面复核申请。','wǒ lǐ jiě nǐ de gù lǜ， wǒ kě yǐ xié zhù nǐ xiàng xué yuàn jiào xué bàn tí jiāo guān fāng shū miàn fù hé shēn qǐng。','Thầy/cô hiểu băn khoăn của em, thầy/cô có thể giúp em nộp đơn phúc khảo chính thức bằng văn bản lên văn phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'提交申请的时候，需要附带什么证明材料，填写专用表格吗？','tí jiāo shēn qǐng de shí hòu， xū yào fù dài shén me zhèng míng cái liào， tián xiě zhuān yòng biǎo gé ma？','Khi nộp đơn thì em có cần kèm theo giấy tờ chứng minh gì không ạ, và có phải điền vào mẫu đơn riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_08','V319','老师',8,'我这边给你打印统一的复核申请表，填写姓名、学号、科目和申请理由即可。','wǒ zhè biān gěi nǐ dǎ yìn tǒng yī de fù hé shēn qǐng biǎo， tián xiě xìng míng、 xué hào、 kē mù hé shēn qǐng lǐ yóu jí kě。','Thầy/cô sẽ in cho em mẫu đơn phúc khảo chung, em chỉ cần điền họ tên, mã số sinh viên, môn học và lý do xin phúc khảo là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_09','V319','阮明',9,'请问提交申请表之后，大概多久可以出具最终复核结果呢？','qǐng wèn tí jiāo shēn qǐng biǎo zhī hòu， dà gài duō jiǔ kě yǐ chū jù zuì zhōng fù hé jié guǒ ne？','Xin hỏi sau khi nộp đơn thì khoảng bao lâu sẽ có kết quả phúc khảo cuối cùng ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_10','V319','老师',10,'学院统一收集申请，三个工作日内完成卷面核对并公示修正后的成绩。','xué yuàn tǒng yī shōu jí shēn qǐng， sān gè gōng zuò rì nèi wán chéng juàn miàn hé duì bìng gōng shì xiū zhèng hòu de chéng jì。','Khoa sẽ tập hợp đơn thống nhất, trong vòng ba ngày làm việc sẽ hoàn tất đối chiếu bài thi và công bố điểm đã điều chỉnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_11','V319','阮明',11,'如果复核后分数有调整，系统成绩会同步更新对吧？','rú guǒ fù hé hòu fēn shù yǒu tiáo zhěng， xì tǒng chéng jì huì tóng bù gēng xīn duì ba？','Nếu sau phúc khảo điểm có thay đổi thì điểm trên hệ thống cũng sẽ được cập nhật đồng thời đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_12','V319','老师',12,'是的，核对出计算失误会直接修改教务系统内你的期末分数。','shì de， hé duì chū jì suàn shī wù huì zhí jiē xiū gǎi jiào wù xì tǒng nèi nǐ de qī mò fēn shù。','Đúng vậy, nếu phát hiện tính sai thì sẽ sửa trực tiếp điểm cuối kỳ của em trên hệ thống giáo vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_13','V319','阮明',13,'我现在填写申请表，麻烦老师帮忙转交教学办。','wǒ xiàn zài tián xiě shēn qǐng biǎo， má fán lǎo shī bāng máng zhuǎn jiāo jiào xué bàn。','Vậy giờ em điền đơn luôn, phiền thầy/cô giúp em chuyển lên văn phòng đào tạo ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_14','V319','老师',14,'放心，流程我全程跟进，有结果第一时间通知你。','fàng xīn， liú chéng wǒ quán chéng gēn jìn， yǒu jié guǒ dì yī shí jiān tōng zhī nǐ。','Em yên tâm, thầy/cô sẽ theo sát toàn bộ quy trình, có kết quả sẽ báo cho em ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_15','V319','阮明',15,'辛苦老师费心办理，非常感谢！','xīn kǔ lǎo shī fèi xīn bàn lǐ， fēi cháng gǎn xiè！','Em cảm ơn thầy/cô đã vất vả lo liệu giúp em, em cảm ơn rất nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ, hôm qua tớ xin nghỉ nên bị lỡ buổi học, cậu cho tớ mượn vở ghi chép một chút được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Được chứ, tớ ghi khá chi tiết đó, chỗ nào trọng tâm khó tớ đều đánh dấu hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Hay quá, đúng lúc tớ lại bỏ lỡ đúng phần kiến thức quan trọng nhất luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ từ từ xem, xem xong trả lại tớ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều lắm, chỗ nào không hiểu tớ hỏi lại cậu nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không vấn đề gì, bạn bè với nhau vốn dĩ phải giúp đỡ nhau mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng thật đấy!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào bạn, tôi muốn đặt lịch khám khoa nội hôm nay trên ứng dụng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Chào anh/chị, anh/chị cần đặt số khám thường hay số khám chuyên gia ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Số khám thường là được rồi, tôi chỉ hơi chóng mặt với mệt mỏi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Rất xin lỗi, số khám thường khoa nội hôm nay đã kín hết rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn suất trống không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn khá nhiều suất, tôi có thể hướng dẫn anh/chị đặt lịch.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Được, phiền bạn hướng dẫn tôi thao tác một chút nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào bạn, gần đây tôi hay bị chóng mặt, ngủ không ngon, vậy nên khám khoa nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Với triệu chứng như vậy thì khám khoa thần kinh là phù hợp nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy giúp tôi đăng ký khám thường chiều nay nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được ạ, anh/chị thanh toán bằng bảo hiểm y tế hay tự chi trả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Tôi dùng bảo hiểm y tế sinh viên để thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Đã đăng ký khám thành công cho anh/chị, mời lên phòng khám ở tầng hai chờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Vâng, cảm ơn bạn nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Chào bác sĩ, mấy ngày nay tôi cứ bị chóng mặt và toàn thân mệt mỏi không có sức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Là chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng mới phát, nhất là buổi tối, với lại tôi cũng hay mất ngủ, ngủ không được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Có sốt, buồn nôn hay khó chịu gì khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Không có ạ, chỉ có mỗi hai triệu chứng chóng mặt và mệt mỏi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Tôi cũng nắm được sơ bộ rồi, để tôi khám qua cho bạn một chút nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Vâng, phiền bác sĩ rồi ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Bác sĩ, tôi cần báo trước với bác sĩ về tiền sử dị ứng thuốc của tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Được, cụ thể bạn bị dị ứng với loại thuốc nào?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Tôi bị dị ứng với các loại thuốc thuộc nhóm Penicillin, tuyệt đối không được dùng loại này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Tôi đã ghi nhận rồi, khi kê đơn sẽ tránh hoàn toàn các thuốc gây dị ứng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây phản ứng dị ứng của tôi rất nghiêm trọng, nên tôi đặc biệt cẩn thận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Tôi hiểu, an toàn khi dùng thuốc là ưu tiên hàng đầu, bạn cứ yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Cảm ơn bác sĩ đã tận tâm và cẩn thận!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào chị, đây là đơn thuốc của tôi, phiền chị lấy giúp tôi thuốc với ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Được ạ, anh/chị chờ một chút, tôi kiểm tra lại thông tin thuốc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Không sao, mà mấy loại thuốc này dùng như thế nào vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều là ngày uống ba lần, sau khi ăn uống với nước ấm, tờ hướng dẫn cũng có ghi rõ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Có cần bảo quản lạnh không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần, để nơi nhiệt độ thường, tránh ánh sáng là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Tôi hiểu rồi, cảm ơn dược sĩ nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào bạn, tôi muốn hỏi mấy loại thuốc mà tôi được kê có được bảo hiểm y tế chi trả không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để tôi tra giúp bạn trong danh mục thuốc bảo hiểm y tế nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi, trong đó có hai loại thuốc cơ bản được chi trả, còn một loại thuốc nhập khẩu thì không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, tức là thuốc nhập khẩu phải tự chi trả toàn bộ đúng không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng vậy, thuốc đặc trị nhập khẩu không nằm trong phạm vi chi trả của bảo hiểm y tế.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_06','V326','阮明',6,'我了解了，那麻烦你分开结算吧。','wǒ liǎo jiě le， nà má fán nǐ fēn kāi jié suàn ba。','Tôi hiểu rồi, vậy phiền bạn tính tiền riêng ra giúp tôi nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_07','V326','工作人员',7,'没问题，我帮你区分清楚。','méi wèn tí， wǒ bāng nǐ qū fēn qīng chǔ。','Không vấn đề gì, tôi sẽ tách rõ ràng giúp bạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT327','S109','Đặt lịch tái khám',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V327','SIT327','P1','suon_se','ban_chinh_thuc',NULL,'慢性病、短期病症恢复都需要复诊，携带既往病历是医院常规要求。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_01','V327','阮明',1,'你好，我想预约下周的复诊门诊。','nǐ hǎo， wǒ xiǎng yù yuē xià zhōu de fù zhěn mén zhěn。','Chào bạn, tôi muốn đặt lịch khám tái khám vào tuần sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_02','V327','工作人员',2,'可以的，你想预约周几的时间段？','kě yǐ de， nǐ xiǎng yù yuē zhōu jǐ de shí jiān duàn？','Được ạ, anh/chị muốn đặt vào khung giờ ngày nào trong tuần?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_03','V327','阮明',3,'下周二下午吧，我下午没有课程安排。','xià zhōu èr xià wǔ ba， wǒ xià wǔ méi yǒu kè chéng ān pái。','Chiều thứ Ba tuần sau nhé, chiều đó tôi không có lịch học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_04','V327','工作人员',4,'好的，已经为你预约成功。','hǎo de， yǐ jīng wèi nǐ yù yuē chéng gōng。','Được rồi, tôi đã đặt lịch thành công cho anh/chị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_05','V327','阮明',5,'复诊的时候需要带这次的病历本吗？','fù zhěn de shí hòu xū yào dài zhè cì de bìng lì běn ma？','Lúc tái khám có cần mang theo sổ khám bệnh lần này không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_06','V327','工作人员',6,'需要的，务必携带方便医生对比恢复情况。','xū yào de， wù bì xié dài fāng biàn yī shēng duì bǐ huī fù qíng kuàng。','Cần mang theo ạ, để bác sĩ tiện so sánh tình trạng hồi phục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_07','V327','阮明',7,'好的，我会妥善保管，谢谢你！','hǎo de， wǒ huì tuǒ shàn bǎo guǎn， xiè xiè nǐ！','Vâng, tôi sẽ giữ gìn cẩn thận, cảm ơn bạn nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT328','S109','Xin giấy chứng nhận nghỉ bệnh cho trường',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V328','SIT328','P1','suon_se','chinh_thuc',NULL,'国内高校只认可医院机打正规病假证明，手写证明无效，是统一考勤制度。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_01','V328','阮明',1,'医生您好，我身体不适需要请假，麻烦您开具一张病假证明。','yī shēng nín hǎo， wǒ shēn tǐ bù shì xū yào qǐng jià， má fán nín kāi jù yī zhāng bìng jià zhèng míng。','Chào bác sĩ, tôi cảm thấy không khỏe nên cần xin nghỉ, phiền bác sĩ viết giúp tôi một giấy chứng nhận nghỉ bệnh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_02','V328','医生',2,'没问题，你需要请假休养几天？','méi wèn tí， nǐ xū yào qǐng jià xiū yǎng jǐ tiān？','Không vấn đề gì, em cần nghỉ dưỡng sức mấy ngày?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_03','V328','阮明',3,'我身体比较虚弱，想请假两天调整状态。','wǒ shēn tǐ bǐ jiào xū ruò， xiǎng qǐng jià liǎng tiān tiáo zhěng zhuàng tài。','Tôi thấy trong người khá mệt, muốn xin nghỉ hai ngày để điều chỉnh lại sức khỏe ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_04','V328','医生',4,'可以，我给你开具正规机打病假证明。','kě yǐ， wǒ gěi nǐ kāi jù zhèng guī jī dǎ bìng jià zhèng míng。','Được, tôi sẽ viết cho em một giấy chứng nhận nghỉ bệnh in máy theo đúng quy định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_05','V328','阮明',5,'证明上会标注就诊时间和请假时长对吧？','zhèng míng shàng huì biāo zhù jiù zhěn shí jiān hé qǐng jià shí cháng duì ba？','Trên giấy chứng nhận sẽ ghi rõ thời gian khám và số ngày nghỉ đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_06','V328','医生',6,'是的，信息齐全，学校可以直接认可。','shì de， xìn xī qí quán， xué xiào kě yǐ zhí jiē rèn kě。','Đúng vậy, thông tin đầy đủ, nhà trường có thể chấp nhận trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_07','V328','阮明',7,'太感谢医生了！','tài gǎn xiè yī shēng le！','Tôi cảm ơn bác sĩ rất nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT329','S111','Tự giới thiệu trong buổi sinh hoạt đầu năm',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V329','SIT329','P1','suon_se','ban_chinh_thuc',NULL,'新生自我介绍简洁谦逊即可，"多多指教"是国内年轻人社交最常用的礼貌用语。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_01','V329','阮明',1,'大家好，我是阮明，一名来自越南的留学生，今年22岁。','dà jiā hǎo， wǒ shì ruǎn míng， yī míng lái zì yuè nán de liú xué shēng， jīn nián 22 suì。','Chào mọi người, mình là Nguyễn Minh, một du học sinh đến từ Việt Nam, năm nay 22 tuổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_02','V329','阮明',2,'目前就读于汉语言文学专业，非常开心加入这个集体。','mù qián jiù dú yú hàn yǔ yán wén xué zhuān yè， fēi cháng kāi xīn jiā rù zhè ge jí tǐ。','Hiện mình đang theo học chuyên ngành Ngôn ngữ và Văn học Trung Quốc, rất vui khi được gia nhập tập thể này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_03','V329','阮明',3,'平时我喜欢读书和慢跑，性格比较随和开朗。','píng shí wǒ xǐ huān dú shū hé màn pǎo， xìng gé bǐ jiào suí hé kāi lǎng。','Bình thường mình thích đọc sách và chạy bộ, tính cách khá hòa đồng, cởi mở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_04','V329','阮明',4,'我刚来中国，对这边的学习和生活还在适应中。','wǒ gāng lái zhōng guó， duì zhè biān de xué xí hé shēng huó hái zài shì yìng zhōng。','Mình mới sang Trung Quốc, vẫn đang trong quá trình thích nghi với việc học và cuộc sống ở đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_05','V329','阮明',5,'往后希望可以和各位同学友好相处，互相学习、多多指教。','wǎng hòu xī wàng kě yǐ hé gè wèi tóng xué yǒu hǎo xiāng chǔ， hù xiāng xué xí、 duō duō zhǐ jiào。','Sau này mong được hòa thuận với các bạn, cùng nhau học hỏi, mong mọi người chỉ bảo thêm nhiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_06','V329','辅导员',6,'欢迎阮明加入我们的大家庭！','huān yíng ruǎn míng jiā rù wǒ men de dà jiā tíng！','Chào mừng Nguyễn Minh gia nhập đại gia đình của chúng ta!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_07','V329','阮明',7,'谢谢大家！','xiè xiè dà jiā！','Cảm ơn mọi người!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT330','S111','Hỏi thông tin liên hệ để giữ kết nối',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V330','SIT330','P1','suon_se','tuy_y',NULL,'微信是国内学生唯一主流沟通工具，学习通知、日常交友、小组协作均依托微信完成。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_01','V330','阮明',1,'今天认识你真的太开心了！我们可以加个微信吗？','jīn tiān rèn shí nǐ zhēn de tài kāi xīn le！ wǒ men kě yǐ jiā gè wēi xìn ma？','Hôm nay quen được cậu vui thật đấy! Bọn mình kết bạn Wechat nhé?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_02','V330','林溪',2,'当然可以呀，以后我们就是同班同学了。','dāng rán kě yǐ ya， yǐ hòu wǒ men jiù shì tóng bān tóng xué le。','Đương nhiên được chứ, từ giờ tụi mình là bạn cùng lớp rồi mà.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_03','V330','阮明',3,'太好了，我刚来这边，以后还要多向你请教呢。','tài hǎo le， wǒ gāng lái zhè biān， yǐ hòu hái yào duō xiàng nǐ qǐng jiào ne。','Tuyệt quá, mình mới đến đây thôi, sau này phải nhờ cậu chỉ bảo nhiều đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_04','V330','林溪',4,'不用客气，我们互相帮忙、共同进步。','bù yòng kè qì， wǒ men hù xiāng bāng máng、 gòng tóng jìn bù。','Khỏi khách sáo, tụi mình giúp đỡ nhau, cùng tiến bộ mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_05','V330','阮明',5,'那我扫你的二维码加好友哈。','nà wǒ sǎo nǐ de èr wéi mǎ jiā hǎo yǒu hā。','Vậy mình quét mã QR của cậu để kết bạn nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_06','V330','林溪',6,'好嘞，以后常联系，有空一起学习！','hǎo lei， yǐ hòu cháng lián xì， yǒu kòng yì qǐ xué xí！','Được đó, sau này liên lạc thường xuyên nhé, rảnh thì học chung!','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_07','V330','阮明',7,'太好啦，谢谢你！','tài hǎo la， xiè xiè nǐ！','Tuyệt vời luôn, cảm ơn cậu nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT331','S112','Mời bạn cùng lớp đi ăn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V331','SIT331','P1','suon_se','tuy_y',NULL,'中国大学生下课常结伴去食堂就餐，主动邀约同学吃饭是很常见的社交方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_01','V331','阮明',1,'下课啦，等下要不要一起去食堂吃饭啊？','xià kè la， děng xià yào bù yào yì qǐ qù shí táng chī fàn a？','Tan học rồi nè, lát nữa đi ăn ở căng tin chung không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_02','V331','王浩',2,'可以呀，我正愁一个人吃饭没意思呢。','kě yǐ ya， wǒ zhèng chóu yí gè rén chī fàn méi yì si ne。','Được chứ, mình đang buồn vì ăn một mình chán quá đây.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_03','V331','阮明',3,'食堂今天有米线，听说味道很不错的。','shí táng jīn tiān yǒu mǐ xiàn， tīng shuō wèi dào hěn bú cuò de。','Hôm nay căng tin có món mì gạo đó, nghe nói ngon lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_04','V331','王浩',4,'刚好我也想吃米线，咱们现在就走吧。','gāng hǎo wǒ yě xiǎng chī mǐ xiàn， zán men xiàn zài jiù zǒu ba。','Đúng lúc mình cũng thèm mì gạo, đi luôn bây giờ đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_05','V331','阮明',5,'行，那我收拾一下书本，马上就好。','xíng， nà wǒ shōu shí yī xià shū běn， mǎ shàng jiù hǎo。','Được, để mình dọn sách vở chút xíu thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_06','V331','王浩',6,'没事，我在教室门口等你就行啦。','méi shì， wǒ zài jiào shì mén kǒu děng nǐ jiù xíng la。','Không sao, mình đứng đợi cậu ở cửa lớp là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_07','V331','阮明',7,'太感谢啦，有同学一起吃饭热闹多了。','tài gǎn xiè la， yǒu tóng xué yì qǐ chī fàn rè nào duō le。','Cảm ơn nhiều nha, có bạn ăn cùng vui hơn hẳn.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT332','S112','Từ chối lời mời một cách lịch sự',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V332','SIT332','P1','suon_se','tuy_y',NULL,'拒绝他人邀约时，中国人习惯说明合理理由并主动提出下次赴约，显得有礼貌不扫兴。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_01','V332','林晓',1,'晚上我们宿舍一起去校外吃火锅，你也来吧？','wǎn shàng wǒ men sù shè yì qǐ qù xiào wài chī huǒ guō， nǐ yě lái ba？','Tối nay phòng tụi mình rủ nhau ra ngoài trường ăn lẩu, cậu đi cùng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_02','V332','阮明',2,'真的很谢谢你邀请我，不过我今晚不行呢。','zhēn de hěn xiè xiè nǐ yāo qǐng wǒ， bù guò wǒ jīn wǎn bù xíng ne。','Cảm ơn cậu đã rủ mình nha, nhưng tối nay mình không đi được rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_03','V332','林晓',3,'怎么啦，是有别的安排吗？','zěn me la， shì yǒu bié de ān pái ma？','Sao vậy, có việc gì khác à?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_04','V332','阮明',4,'我要完成一篇汉语作文，明天就得提交的。','wǒ yào wán chéng yī piān hàn yǔ zuò wén， míng tiān jiù dé tí jiāo de。','Mình phải viết xong một bài văn tiếng Trung, mai phải nộp rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_05','V332','林晓',5,'原来是这样，学习要紧，那下次再约吧。','yuán lái shì zhè yàng， xué xí yào jǐn， nà xià cì zài yuē ba。','Ra là vậy, học hành quan trọng hơn, vậy để lần sau hẹn nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_06','V332','阮明',6,'好，下次我一定主动找你们，实在抱歉啦。','hǎo， xià cì wǒ yí dìng zhǔ dòng zhǎo nǐ men， shí zài bào qiàn la。','Được, lần sau nhất định mình sẽ chủ động rủ mọi người, thật ngại quá.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_07','V332','林晓',7,'没关系，学习完早点休息。','méi guān xì， xué xí wán zǎo diǎn xiū xī。','Không sao đâu, học xong nhớ nghỉ ngơi sớm nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT333','S112','Xin lỗi vì đến muộn buổi hẹn',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V333','SIT333','P1','twist','ban_chinh_thuc',NULL,'与人线下见面迟到，中国人会主动诚恳道歉，还会主动提出买单、请客作为补偿。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_01','V333','阮明',1,'实在对不起，我路上堵车，迟到二十分钟了。','shí zài duì bù qǐ， wǒ lù shàng dǔ chē， chí dào èr shí fēn zhōng le。','Thật sự xin lỗi, đường bị kẹt xe nên tôi đến muộn hai mươi phút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_02','V333','陈悦',2,'没事，我也刚到一会儿，不用这么愧疚。','méi shì， wǒ yě gāng dào yī huì er， bù yòng zhè me kuì jiù。','Không sao đâu, tôi cũng vừa đến một chút thôi, đừng áy náy quá vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_03','V333','阮明',3,'都怪我没提前出门，让你在这里干等啊。','dōu guài wǒ méi tí qián chū mén， ràng nǐ zài zhè lǐ gàn děng a。','Tại tôi không xuất phát sớm hơn, để bạn phải ngồi chờ ở đây.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_04','V333','陈悦',4,'还好，这家咖啡店座位挺多，我先点了两杯饮品。','hái hǎo， zhè jiā kā fēi diàn zuò wèi tǐng duō， wǒ xiān diǎn le liǎng bēi yǐn pǐn。','Không sao, quán cà phê này khá nhiều chỗ ngồi, tôi gọi trước hai ly đồ uống rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_05','V333','阮明',5,'太不好意思了，这杯饮品我来付钱吧。','tài bù hǎo yì sī le， zhè bēi yǐn pǐn wǒ lái fù qián ba。','Thật ngại quá, để tôi trả tiền cho hai ly nước này nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_06','V333','陈悦',6,'不用啦，下次见面你请我就可以咯。','bù yòng la， xià cì jiàn miàn nǐ qǐng wǒ jiù kě yǐ gē。','Khỏi cần đâu, lần sau gặp nhau bạn mời tôi là được rồi.','AM11');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_07','V333','阮明',7,'好，下次我一定提前半小时出门，绝不迟到。','hǎo， xià cì wǒ yí dìng tí qián bàn xiǎo shí chū mén， jué bù chí dào。','Được, lần sau tôi nhất định sẽ xuất phát sớm nửa tiếng, tuyệt đối không trễ nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT334','S112','Cảm ơn khi được giúp đỡ đặc biệt',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V334','SIT334','P1','suon_se','ban_chinh_thuc',NULL,'得到他人较大帮助后，中国人常会赠送小零食、小礼物表达谢意，不会只口头道谢。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_01','V334','阮明',1,'班长，这次真的太谢谢你帮我补办签证材料了。','bān zhǎng， zhè cì zhēn de tài xiè xiè nǐ bāng wǒ bǔ bàn qiān zhèng cái liào le。','Lớp trưởng ơi, lần này thật sự cảm ơn bạn đã giúp mình bổ sung giấy tờ visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_02','V334','周宇',2,'小事而已，留学生办理手续本来就麻烦嘛。','xiǎo shì ér yǐ， liú xué shēng bàn lǐ shǒu xù běn lái jiù má fán ma。','Chuyện nhỏ thôi mà, du học sinh làm thủ tục vốn dĩ đã phiền phức rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_03','V334','阮明',3,'要是没有你带路讲解，我肯定跑好多趟。','yào shì méi yǒu nǐ dài lù jiǎng jiě， wǒ kěn dìng pǎo hǎo duō tàng。','Nếu không có bạn dẫn đường và giải thích, chắc mình phải chạy đi chạy lại bao nhiêu lần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_04','V334','周宇',4,'不用放在心上，班里同学互相帮忙是应该的。','bù yòng fàng zài xīn shàng， bān lǐ tóng xué hù xiāng bāng máng shì yīng gāi de。','Đừng để bụng làm gì, các bạn trong lớp giúp đỡ nhau là chuyện nên làm mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_05','V334','阮明',5,'下周我买了家乡小零食，带给你尝尝吧。','xià zhōu wǒ mǎi le jiā xiāng xiǎo líng shí， dài gěi nǐ cháng cháng ba。','Tuần sau mình mua ít đồ ăn vặt quê mình, mang đến cho bạn nếm thử nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_06','V334','周宇',6,'不用这么客气，能帮上忙我也很高兴。','bù yòng zhè me kè qì， néng bāng shàng máng wǒ yě hěn gāo xìng。','Không cần khách sáo vậy đâu, giúp được bạn mình cũng thấy vui.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_07','V334','阮明',7,'一定要收下，不然我心里过意不去呢。','yí dìng yào shōu xià， bù rán wǒ xīn lǐ guò yì bù qù ne。','Bạn nhất định phải nhận, không thì mình áy náy lắm.','AM04');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT335','S113','Hỏi sở thích để tìm điểm chung với bạn mới',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V335','SIT335','P1','suon_se','tuy_y',NULL,'初次认识的年轻人会通过爱好聊天，找到共同兴趣能快速拉近彼此距离。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_01','V335','阮明',1,'课余时间你平时都喜欢做什么呀？','kè yú shí jiān nǐ píng shí dōu xǐ huān zuò shén me ya？','Ngoài giờ học cậu thường thích làm gì thế?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_02','V335','苏雯',2,'我有空就会追剧、出门爬山，你呢？','wǒ yǒu kòng jiù huì zhuī jù、 chū mén pá shān， nǐ ne？','Rảnh thì mình hay xem phim bộ, leo núi, còn cậu thì sao?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_03','V335','阮明',3,'我也很喜欢爬山，只是刚来还不熟悉周边路线。','wǒ yě hěn xǐ huān pá shān， zhǐ shì gāng lái hái bù shú xī zhōu biān lù xiàn。','Mình cũng rất thích leo núi, chỉ là mới đến nên chưa rành đường sá xung quanh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_04','V335','苏雯',4,'学校附近有一座小山，周末可以一起去的。','xué xiào fù jìn yǒu yī zuò xiǎo shān， zhōu mò kě yǐ yì qǐ qù de。','Gần trường có một ngọn núi nhỏ, cuối tuần đi cùng nhau được đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_05','V335','阮明',5,'太棒了，我还担心找不到同好呢。','tài bàng le， wǒ hái dān xīn zhǎo bú dào tóng hào ne。','Tuyệt quá, mình còn lo không tìm được ai hợp sở thích cơ đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_06','V335','苏雯',6,'那我们加个微信，周末约着一起出发吧。','nà wǒ men jiā gè wēi xìn， zhōu mò yuē zhe yì qǐ chū fā ba。','Vậy tụi mình kết bạn Wechat đi, cuối tuần hẹn nhau xuất phát luôn.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_07','V335','阮明',7,'好呀，终于找到一样爱好的朋友啦。','hǎo ya， zhōng yú zhǎo dào yī yàng ài hào de péng yǒu la。','Được đó, cuối cùng cũng tìm được người bạn cùng sở thích rồi.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT336','S114','Đăng ký tham gia câu lạc bộ sinh viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V336','SIT336','P1','twist','ban_chinh_thuc',NULL,'国内高校社团统一在开学招新，多数社团有活动人数限制，需要提前登记报名。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_01','V336','阮明',1,'学姐你好，我想报名加入咱们汉服社团可以吗？','xué jiě nǐ hǎo， wǒ xiǎng bào míng jiā rù zán men hàn fú shè tuán kě yǐ ma？','Chào chị, em muốn đăng ký tham gia câu lạc bộ Hán phục của mình được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_02','V336','学姐',2,'当然可以，先填一张信息登记表哦。','dāng rán kě yǐ， xiān tián yī zhāng xìn xī dēng jì biǎo ó。','Đương nhiên là được, em điền một tờ phiếu đăng ký thông tin trước nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_03','V336','阮明',3,'好的，我平时很喜欢中国传统服饰和文化。','hǎo de， wǒ píng shí hěn xǐ huān zhōng guó chuán tǒng fú shì hé wén huà。','Dạ vâng, em rất thích trang phục và văn hóa truyền thống Trung Quốc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_04','V336','学姐',4,'咱们每周有线下活动，不过本周活动名额满了。','zán men měi zhōu yǒu xiàn xià huó dòng， bù guò běn zhōu huó dòng míng é mǎn le。','Tuần nào bọn chị cũng có hoạt động offline, nhưng tuần này số lượng đã đủ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_05','V336','阮明',5,'啊？那我下周能正常参与活动吗？','a？ nà wǒ xià zhōu néng zhèng cháng cān yù huó dòng ma？','Ơ vậy ạ? Vậy tuần sau em có thể tham gia bình thường không chị?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_06','V336','学姐',6,'没问题，下周名额会重新开放，记得准时来。','méi wèn tí， xià zhōu míng é huì chóng xīn kāi fàng， jì de zhǔn shí lái。','Không vấn đề gì, tuần sau sẽ mở lại suất tham gia, nhớ đến đúng giờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_07','V336','阮明',7,'好，我会记好时间，麻烦学姐啦。','hǎo， wǒ huì jì hǎo shí jiān， má fán xué jiě la。','Dạ vâng, em sẽ ghi nhớ thời gian, phiền chị nhiều rồi ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT337','S112','Giải thích khi hiểu nhầm ý của bạn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V337','SIT337','P1','suon_se','ban_chinh_thuc',NULL,'朋友产生隔阂后，中国人会主动沟通解释，厘清误会后不会一直记在心里。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_01','V337','阮明',1,'昨天那件事你是不是误会我了，我跟你解释一下吧。','zuó tiān nà jiàn shì nǐ shì bú shì wù huì wǒ le， wǒ gēn nǐ jiě shì yī xià ba。','Chuyện hôm qua chắc bạn hiểu lầm mình rồi, để mình giải thích cho bạn nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_02','V337','李然',2,'我昨天确实有点生气，你说说是什么情况。','wǒ zuó tiān què shí yǒu diǎn shēng qì， nǐ shuō shuō shì shén me qíng kuàng。','Hôm qua mình đúng là có hơi giận, bạn kể xem chuyện gì đã xảy ra.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_03','V337','阮明',3,'我不是故意放你鸽子，是老师临时留我补作业呢。','wǒ bú shì gù yì fàng nǐ gē zi， shì lǎo shī lín shí liú wǒ bǔ zuò yè ne。','Mình không cố tình bùng bạn đâu, là do thầy giữ lại bắt bù bài tập đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_04','V337','李然',4,'原来是这样，我还以为你不想跟我出门。','yuán lái shì zhè yàng， wǒ hái yǐ wéi nǐ bù xiǎng gēn wǒ chū mén。','Ra là vậy, mình còn tưởng bạn không muốn đi chơi với mình chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_05','V337','阮明',5,'怎么会，我一直很期待和你逛街的。','zěn me huì， wǒ yì zhí hěn qī dài hé nǐ guàng jiē de。','Sao lại thế được, mình vẫn luôn mong được đi dạo phố cùng bạn mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_06','V337','李然',6,'行，我明白啦，这件事就翻篇不提了。','xíng， wǒ míng bái la， zhè jiàn shì jiù fān piān bù tí le。','Được rồi, mình hiểu rồi, chuyện này coi như bỏ qua, không nhắc lại nữa.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_07','V337','阮明',7,'太好了，下次出门我提前跟你确认时间。','tài hǎo le， xià cì chū mén wǒ tí qián gēn nǐ què rèn shí jiān。','Tuyệt quá, lần sau đi đâu mình sẽ báo trước giờ giấc với bạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT338','S112','Chúc mừng sinh nhật bạn cùng phòng',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V338','SIT338','P1','suon_se','tuy_y',NULL,'大学生宿舍室友常会合伙买蛋糕、礼物一起过生日，是宿舍常见暖心活动。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_01','V338','阮明',1,'张明，生日快乐！快拆开我们准备的蛋糕吧。','zhāng míng， shēng rì kuài lè！ kuài chāi kāi wǒ men zhǔn bèi de dàn gāo ba。','Trương Minh, chúc mừng sinh nhật cậu! Mau mở bánh kem tụi mình chuẩn bị đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_02','V338','张明',2,'哇，你们居然还记得我的生日，太惊喜了。','wa， nǐ men jū rán hái jì de wǒ de shēng rì， tài jīng xǐ le。','Ồ, mọi người vẫn còn nhớ sinh nhật mình, bất ngờ quá đi mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_03','V338','阮明',3,'我们悄悄凑钱买的，还有小礼物送给你呢。','wǒ men qiāo qiāo còu qián mǎi de， hái yǒu xiǎo lǐ wù sòng gěi nǐ ne。','Tụi mình lén góp tiền mua đấy, còn có quà nhỏ tặng cậu nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_04','V338','张明',4,'真的不用这么破费，有你们陪伴就足够啦。','zhēn de bù yòng zhè me pò fèi， yǒu nǐ men péi bàn jiù zú gòu la。','Thật là không cần bày vẽ tốn kém vậy đâu, có mọi người bên cạnh là đủ rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_05','V338','阮明',5,'室友之间不用客气，赶紧许愿吹蜡烛哦。','shì yǒu zhī jiān bù yòng kè qì， gǎn jǐn xǔ yuàn chuī là zhú ó。','Bạn cùng phòng thì khách sáo gì, mau ước nguyện rồi thổi nến đi.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_06','V338','张明',6,'好，我许个愿，希望我们宿舍一直和睦。','hǎo， wǒ xǔ gè yuàn， xī wàng wǒ men sù shè yì zhí hé mù。','Được, mình sẽ ước một điều, mong phòng mình luôn hòa thuận vui vẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_07','V338','阮明',7,'一定会的，咱们切蛋糕一起分享！','yí dìng huì de， zán men qiè dàn gāo yì qǐ fēn xiǎng！','Chắc chắn sẽ vậy mà, cùng cắt bánh chia nhau ăn thôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT339','S112','Hỏi mượn đồ dùng cá nhân từ bạn cùng lớp',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V339','SIT339','P1','twist','tuy_y',NULL,'向他人借私人物品需要主动询问，用完及时归还，很多人会用小饮品、零食答谢对方。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_01','V339','阮明',1,'菲菲，能不能借你的笔记本电脑用半小时啊？','fēi fēi， néng bù néng jiè nǐ de bǐ jì běn diàn nǎo yòng bàn xiǎo shí a？','Phi Phi, cho mình mượn laptop dùng nửa tiếng được không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_02','V339','刘菲',2,'不好意思，我电脑拿去图书馆充电了嘛。','bù hǎo yì sī， wǒ diàn nǎo ná qù tú shū guǎn chōng diàn le ma。','Xin lỗi nha, laptop của mình đem lên thư viện sạc rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_03','V339','阮明',3,'这样啊，那你有多余的U盘借我拷贝文件吗？','zhè yàng a， nà nǐ yǒu duō yú de U pán jiè wǒ kǎo bèi wén jiàn ma？','Vậy à, thế cậu có USB dư cho mình mượn để chép file không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_04','V339','刘菲',4,'这个可以，我包里刚好有一个全新的。','zhè ge kě yǐ， wǒ bāo lǐ gāng hǎo yǒu yí gè quán xīn de。','Cái đó thì được, trong balo mình có đúng một cái mới toanh nè.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_05','V339','阮明',5,'太感谢了，用完我马上还给你，绝不弄丢。','tài gǎn xiè le， yòng wán wǒ mǎ shàng huán gěi nǐ， jué bù nòng diū。','Cảm ơn nhiều lắm, dùng xong mình trả liền, tuyệt đối không làm mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_06','V339','刘菲',6,'没关系，你慢慢用，不用着急归还。','méi guān xì， nǐ màn màn yòng， bù yòng zháo jí guī huán。','Không sao đâu, cứ dùng thoải mái, không cần vội trả đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_07','V339','阮明',7,'好嘞，等下请你喝奶茶作为答谢。','hǎo lei， děng xià qǐng nǐ hē nǎi chá zuò wéi dá xiè。','Được rồi, lát nữa mình mời cậu ly trà sữa để cảm ơn nhé.','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT340','S112','Đề nghị đổi lịch hẹn vì bận đột xuất',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V340','SIT340','P1','suon_se','ban_chinh_thuc',NULL,'临时无法赴约，中国人会第一时间告知对方，主动协商新时间，避免对方空等。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_01','V340','阮明',1,'实在抱歉，我们下午约好逛书店得改时间了。','shí zài bào qiàn， wǒ men xià wǔ yuē hǎo guàng shū diàn dé gǎi shí jiān le。','Thật sự xin lỗi, buổi hẹn đi nhà sách chiều nay mình phải đổi giờ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_02','V340','吴桐',2,'怎么了，是临时有突发事情吗？','zěn me le， shì lín shí yǒu tū fā shì qíng ma？','Sao vậy, có việc đột xuất gì à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_03','V340','阮明',3,'辅导员通知我去办公室提交留学材料呢。','fǔ dǎo yuán tōng zhī wǒ qù bàn gōng shì tí jiāo liú xué cái liào ne。','Cố vấn học tập gọi mình lên văn phòng nộp hồ sơ du học đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_04','V340','吴桐',4,'没事，正事要紧，我们改到明天下午行吗？','méi shì， zhèng shì yào jǐn， wǒ men gǎi dào míng tiān xià wǔ xíng ma？','Không sao, việc quan trọng trước đã, tụi mình dời sang chiều mai được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_05','V340','阮明',5,'明天下午我全天有空，完全没问题的。','míng tiān xià wǔ wǒ quán tiān yǒu kòng， wán quán méi wèn tí de。','Chiều mai mình rảnh cả buổi, hoàn toàn không vấn đề gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_06','V340','吴桐',6,'那就定明天三点，咱们校门口碰面吧。','nà jiù dìng míng tiān sān diǎn， zán men xiào mén kǒu pèng miàn ba。','Vậy hẹn ba giờ chiều mai nhé, tụi mình gặp nhau ở cổng trường.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_07','V340','阮明',7,'好，明天我提前十分钟在门口等你啦。','hǎo， míng tiān wǒ tí qián shí fēn zhōng zài mén kǒu děng nǐ la。','Được, mai mình sẽ đến trước mười phút đợi bạn ở cổng nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT341','S114','Xin nghỉ một buổi sinh hoạt câu lạc bộ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V341','SIT341','P1','suon_se','ban_chinh_thuc',NULL,'学生社团有事无法参与活动，需要提前向负责人报备请假，不能无故缺席。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_01','V341','阮明',1,'学姐，我想跟你请假，本周的社团活动没法参加了。','xué jiě， wǒ xiǎng gēn nǐ qǐng jià， běn zhōu de shè tuán huó dòng méi fǎ cān jiā le。','Chị ơi, em muốn xin phép nghỉ, tuần này em không tham gia sinh hoạt câu lạc bộ được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_02','V341','学姐',2,'可以，你是有什么重要的事情耽误了吗？','kě yǐ， nǐ shì yǒu shén me zhòng yào de shì qíng dān wù le ma？','Được thôi, em có việc gì quan trọng nên bận không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_03','V341','阮明',3,'下周有汉语考试，我需要全天在家复习嘛。','xià zhōu yǒu hàn yǔ kǎo shì， wǒ xū yào quán tiān zài jiā fù xí ma。','Tuần sau em có kỳ thi tiếng Trung, em cần ở nhà ôn bài cả ngày ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_04','V341','学姐',4,'原来是备考，学习优先，我帮你登记请假。','yuán lái shì bèi kǎo， xué xí yōu xiān， wǒ bāng nǐ dēng jì qǐng jià。','Ra là chuẩn bị thi, học hành là trên hết, chị sẽ ghi phép cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_05','V341','阮明',5,'活动的任务我下周会主动补上，不会落下进度。','huó dòng de rèn wù wǒ xià zhōu huì zhǔ dòng bǔ shàng， bú huì là xià jìn dù。','Nhiệm vụ của hoạt động tuần sau em sẽ chủ động bù lại, không để chậm tiến độ đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_06','V341','学姐',6,'不用着急，等你考完试再来参与就行。','bù yòng zháo jí， děng nǐ kǎo wán shì zài lái cān yù jiù xíng。','Không cần vội đâu, đợi em thi xong rồi tham gia lại cũng được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_07','V341','阮明',7,'辛苦学姐体谅我啦，非常感谢。','xīn kǔ xué jiě tǐ liàng wǒ la， fēi cháng gǎn xiè。','Cảm ơn chị đã thông cảm cho em nhiều lắm ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT342','S112','Khen món ăn bạn Trung Quốc nấu, đáp lại khi được khen',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V342','SIT342','P1','suon_se','tuy_y',NULL,'品尝他人亲手做的饭菜，中国人会真诚夸赞，还会互相邀约交换拿手菜。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_01','V342','阮明',1,'你做的番茄炒蛋也太好吃了吧，味道超正宗！','nǐ zuò de fān qié chǎo dàn yě tài hǎo chī le ba， wèi dào chāo zhèng zōng！','Món trứng xào cà chua cậu làm ngon quá trời, đúng vị chuẩn luôn!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_02','V342','小雅',2,'没有啦，就是简单家常菜，你喜欢就多吃点。','méi yǒu la， jiù shì jiǎn dān jiā cháng cài， nǐ xǐ huān jiù duō chī diǎn。','Có gì đâu, chỉ là món nhà đơn giản thôi, cậu thích thì cứ ăn nhiều vào.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_03','V342','阮明',3,'比校外餐馆做得还香，你厨艺也太好了啊。','bǐ xiào wài cān guǎn zuò dé hái xiāng， nǐ chú yì yě tài hǎo le a。','Còn ngon hơn cả quán ăn ngoài trường ấy, tay nghề nấu ăn của cậu đỉnh thật đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_04','V342','小雅',4,'谢谢你夸奖，下次我教你一起做呢。','xiè xiè nǐ kuā jiǎng， xià cì wǒ jiāo nǐ yì qǐ zuò ne。','Cảm ơn cậu khen, lần sau mình chỉ cậu làm cùng nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_05','V342','阮明',5,'那太好了，我还怕自己学不会。','nà tài hǎo le， wǒ hái pà zì jǐ xué bú huì。','Vậy thì tốt quá, mình còn sợ mình học không nổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_06','V342','小雅',6,'不难的，下次你做家乡菜给我尝尝吧。','bù nán de， xià cì nǐ zuò jiā xiāng cài gěi wǒ cháng cháng ba。','Không khó đâu, lần sau cậu nấu món quê cậu cho mình nếm thử nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_07','V342','阮明',7,'没问题，下次我带食材过来，一定露一手！','méi wèn tí， xià cì wǒ dài shí cái guò lái， yí dìng lòu yī shǒu！','Được luôn, lần sau mình mang nguyên liệu tới, nhất định trổ tài cho xem!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT343','S115','Mua điện thoại mới, hỏi thông số',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V343','SIT343','P1','suon_se','tuy_y',NULL,'线下买电子产品，顾客可以自由询问全部参数，对比多款机型，店家不会催促下单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_01','V343','阮明',1,'你好，这款新款手机内存和电池容量是多少啊？','nǐ hǎo， zhè kuǎn xīn kuǎn shǒu jī nèi cún hé diàn chí róng liàng shì duō shǎo a？','Chào anh/chị, mẫu điện thoại mới này bộ nhớ và dung lượng pin bao nhiêu vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_02','V343','销售员',2,'这款手机256G内存，电池续航一整天没问题。','zhè kuǎn shǒu jī 256G nèi cún， diàn chí xù háng yī zhěng tiān méi wèn tí。','Mẫu này bộ nhớ 256G, pin dùng cả ngày thoải mái không lo hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_03','V343','阮明',3,'拍照像素高吗？我平时很喜欢出门拍照呢。','pāi zhào xiàng sù gāo ma？ wǒ píng shí hěn xǐ huān chū mén pāi zhào ne。','Độ phân giải camera có cao không ạ? Em hay đi chụp ảnh lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_04','V343','销售员',4,'后置五千万像素，夜景拍摄效果特别清晰。','hòu zhì wǔ qiān wàn xiàng sù， yè jǐng pāi shè xiào guǒ tè bié qīng xī。','Camera sau 50 triệu điểm ảnh, chụp cảnh đêm cực kỳ nét luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_05','V343','阮明',5,'那处理器运行会不会卡顿，适合学习软件吗？','nà chǔ lǐ qì yùn xíng huì bú huì kǎ dùn， shì hé xué xí ruǎn jiàn ma？','Vậy con chip chạy có bị giật lag không, có phù hợp để học phần mềm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_06','V343','销售员',6,'配置足够流畅运行各类软件，学生用很合适。','pèi zhì zú gòu liú chàng yùn xíng gè lèi ruǎn jiàn， xué shēng yòng hěn hé shì。','Cấu hình đủ mượt để chạy mọi loại phần mềm, học sinh sinh viên dùng rất hợp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_07','V343','阮明',7,'行，那我再对比一下另一款，等下再来找你。','xíng， nà wǒ zài duì bǐ yī xià lìng yī kuǎn， děng xià zài lái zhǎo nǐ。','Vâng, để em so sánh thêm một mẫu khác nữa, lát em quay lại tìm anh/chị.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT344','S115','Mang điện thoại đi sửa màn hình vỡ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V344','SIT344','P1','twist','ban_chinh_thuc',NULL,'手机维修更换配件分原装和平价配件，店家会主动区分报价，配件缺货会告知顾客取机时间。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_01','V344','阮明',1,'师傅，我的手机屏幕摔碎了，能帮忙更换吗？','shī fù， wǒ de shǒu jī píng mù shuāi suì le， néng bāng máng gēng huàn ma？','Anh ơi, màn hình điện thoại em bị vỡ rồi, anh giúp em thay được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_02','V344','维修师傅',2,'可以，先看看型号，原装屏幕价格贵一点哈。','kě yǐ， xiān kàn kàn xíng hào， yuán zhuāng píng mù jià gé guì yì diǎn hā。','Được, để xem model đã, màn hình chính hãng giá hơi cao một chút đó nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_03','V344','阮明',3,'原装的大概多少钱，维修需要等多久呢？','yuán zhuāng de dà gài duō shǎo qián， wéi xiū xū yào děng duō jiǔ ne？','Màn hình chính hãng khoảng bao nhiêu tiền vậy anh, sửa xong phải đợi lâu không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_04','V344','维修师傅',4,'三百五十元，可惜现在店里没有现货屏幕。','sān bǎi wǔ shí yuán， kě xī xiàn zài diàn lǐ méi yǒu xiàn huò píng mù。','Ba trăm năm mươi tệ, tiếc là bên anh hiện không có sẵn màn hình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_05','V344','阮明',5,'啊？那什么时候能到货，我手机每天都要用。','a？ nà shén me shí hòu néng dào huò， wǒ shǒu jī měi tiān dōu yào yòng。','Ơ? Vậy chừng nào có hàng ạ, điện thoại em ngày nào cũng phải dùng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_06','V344','维修师傅',6,'明天中午到货，你明天下午过来取就行。','míng tiān zhōng wǔ dào huò， nǐ míng tiān xià wǔ guò lái qǔ jiù xíng。','Trưa mai hàng về, em chiều mai qua lấy là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_07','V344','阮明',7,'好，我明天准时过来，麻烦师傅预留屏幕。','hǎo， wǒ míng tiān zhǔn shí guò lái， má fán shī fù yù liú píng mù。','Dạ, mai em qua đúng giờ, phiền anh giữ màn hình lại giúp em nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT345','S116','Mua laptop, hỏi bảo hành',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V345','SIT345','P1','suon_se','ban_chinh_thuc',NULL,'国内数码产品均提供全国联保服务，门店会清晰告知保修时长、售后范围。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_01','V345','阮明',1,'这款笔记本适合留学生写论文、做PPT吗？','zhè kuǎn bǐ jì běn shì hé liú xué shēng xiě lùn wén、 zuò PPT ma？','Chiếc laptop này có phù hợp với sinh viên du học để viết luận văn, làm PPT không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_02','V345','导购',2,'完全适配，轻薄便携，性能足够日常学习的。','wán quán shì pèi， qīng bó biàn xié， xìng néng zú gòu rì cháng xué xí de。','Hoàn toàn phù hợp, máy mỏng nhẹ dễ mang theo, cấu hình đủ dùng cho việc học hằng ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_03','V345','阮明',3,'那整机官方保修时长是多久呀？','nà zhěng jī guān fāng bǎo xiū shí cháng shì duō jiǔ ya？','Vậy thời gian bảo hành chính hãng của máy là bao lâu vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, nếu trả thêm phí thì có thể nâng lên ba năm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành, nếu máy lỗi hệ thống thì có được sửa tận nơi miễn phí không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong nội thành thì được sửa tận nơi miễn phí, còn ngoài phạm vi đó thì phải mang ra cửa hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Dạ em hiểu rồi, để em suy nghĩ thêm, lát nữa em quay lại thanh toán nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào chị, em thuê phòng đơn muốn đăng ký lắp mạng internet ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào em, em cho chị xin địa chỉ cụ thể để chị kiểm tra xem khu vực đó có phủ sóng đường truyền không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là khu chung cư gần trường đại học, tòa 3, phòng 502, phiền chị kiểm tra giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Xin lỗi em, cổng mạng khu chung cư của em tuần này đã dùng hết rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy à, vậy đợt cổng mạng tiếp theo mở lại là khi nào vậy chị?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở lại đợt mới, lúc đó chị có thể nhắc em đặt trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Dạ vâng, vậy phiền chị ba ngày sau liên hệ lại giúp em, chị vất vả rồi ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tao mới đổi điện thoại mới nè, chẳng biết chuyển dữ liệu từ máy cũ sang sao luôn á.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản mà, điện thoại có sẵn phần mềm chuyển máy, cứ làm theo từng bước là được thôi mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn, ảnh với file có copy sang đầy đủ hết không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Đầy đủ hết luôn, chỉ cần hai máy kết nối chung một WiFi thôi à.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_05','V347','阮明',5,'我还担心会丢失重要的学习资料。','wǒ hái dān xīn huì diū shī zhòng yào de xué xí zī liào。','Tao vẫn sợ mất mấy tài liệu học quan trọng lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_06','V347','小杨',6,'放心，我上次换机一点资料都没漏掉。','fàng xīn， wǒ shàng cì huàn jī yì diǎn zī liào dōu méi lòu diào。','Yên tâm đi, lần trước tao đổi máy có sót cái gì đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_07','V347','阮明',7,'太谢谢你了，等下我操作有问题再来问你吧。','tài xiè xiè nǐ le， děng xià wǒ cāo zuò yǒu wèn tí zài lái wèn nǐ ba。','Cảm ơn mày nhiều nha, lát nữa làm mà bí thì tao hỏi mày tiếp nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT348','S118','Cài đặt và đăng ký app dịch tiếng Trung',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V348','SIT348','P1','suon_se','tuy_y',NULL,'留学生常用翻译APP辅助学习中文，国内软件支持微信、QQ快捷登录，注册流程简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_01','V348','阮明',1,'有没有好用的翻译软件推荐我下载一下啊？','yǒu méi yǒu hǎo yòng de fān yì ruǎn jiàn tuī jiàn wǒ xià zài yī xià a？','Có app dịch nào xịn thì giới thiệu tao tải về xài với.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_02','V348','小林',2,'这款翻译APP特别适合留学生，离线也能用呢。','zhè kuǎn fān yì APP tè bié shì hé liú xué shēng， lí xiàn yě néng yòng ne。','App dịch này hợp với du học sinh lắm luôn, không có mạng cũng dùng được nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_03','V348','阮明',3,'下载之后注册需要绑定手机号吗？','xià zài zhī hòu zhù cè xū yào bǎng dìng shǒu jī hào ma？','Tải xong đăng ký có cần gắn số điện thoại không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_04','V348','小林',4,'只用微信一键登录就可以，不用额外注册啦。','zhǐ yòng wēi xìn yī jiàn dēng lù jiù kě yǐ， bù yòng é wài zhù cè la。','Chỉ cần đăng nhập bằng WeChat một cái là xong, khỏi cần đăng ký gì thêm luôn.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_05','V348','阮明',5,'还能拍照翻译课本上的汉字，对吗？','hái néng pāi zhào fān yì kè běn shàng de hàn zì， duì ma？','Còn chụp ảnh dịch chữ Hán trong sách giáo khoa được nữa hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_06','V348','小林',6,'没错，拍照翻译准确度很高，日常学习够用。','méi cuò， pāi zhào fān yì zhǔn què dù hěn gāo， rì cháng xué xí gòu yòng。','Đúng rồi đó, chụp ảnh dịch chuẩn lắm, dùng học hằng ngày là quá đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_07','V348','阮明',7,'太好了，我现在就下载安装试试吧。','tài hǎo le， wǒ xiàn zài jiù xià zài ān zhuāng shì shì ba。','Tuyệt quá, để tao tải cài đặt thử liền đây.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào anh, gói cước data của em hôm nay hết hạn rồi, em muốn gia hạn tại chỗ luôn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được, em đưa số thuê bao đây, anh kiểm tra các gói cước giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Bình thường em dùng data nhiều lắm, có gói dành cho sinh viên không giới hạn dung lượng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho sinh viên tháng này ngừng bán rồi, chỉ còn chọn gói thường thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','Ơ, vậy gói thường mỗi tháng bao nhiêu dung lượng, cước tháng bao nhiêu tiền vậy anh?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G data, cước tháng ba mươi chín tệ, giá rất hời đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Được, vậy em đăng ký gia hạn gói thường này luôn ạ.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Anh ơi, WiFi phòng em tự nhiên mất kết nối, phiền anh qua xem giúp em với.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, để anh kiểm tra modem quang với router trước, khả năng cao là dây bị lỏng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng vẫn chạy êm lắm, sáng nay tự nhiên mất mạng luôn ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Anh cắm chặt lại dây, rồi reset router lại là phục hồi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa vậy có phải trả thêm phí dịch vụ không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Trong thời gian bảo hành mạng thì đến tận nơi kiểm tra sửa chữa hoàn toàn miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, anh vất vả giúp em xử lý rồi nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào chị, em muốn chuyển tiền cho bạn học qua app ngân hàng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào em, em cần nhập số thẻ ngân hàng và tên của người nhận để đối chiếu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển tiền có giới hạn hạn mức không chị, em chuyển một lần ba nghìn tệ được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại sinh viên hạn mức chuyển tiền một ngày là năm mươi nghìn tệ, hoàn toàn không vấn đề gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi thì có tin nhắn báo cho cả hai bên không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều nhận được thông báo, tiện đối chiếu lại giao dịch đó em.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Em hiểu quy trình rồi ạ, cảm ơn chị đã giải thích nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào chị, người nhà tôi ở nước ngoài vừa gửi cho tôi một khoản sinh hoạt phí, tôi muốn làm thủ tục kết hối ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Anh vui lòng cho tôi xem hộ chiếu và thẻ ngân hàng, tôi kiểm tra tình trạng tiền ngoại tệ đã về tài khoản chưa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Vâng, giấy tờ đây ạ, khoản này chuyển vào khoảng chiều tối hôm qua.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi anh, khoản chuyển tiền này chưa được thanh toán bù trừ xong nên hôm nay tạm thời chưa rút được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ? Vậy phải đợi đến bao giờ mới đổi được sang nhân dân tệ ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống hoàn tất thanh toán bù trừ rồi, anh quay lại quầy làm thủ tục là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Vâng, sáng mai tôi qua sớm, phiền chị ghi chú giúp tôi nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì vậy, em không rành lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ vào trước, nhập mật khẩu, rồi chọn số tiền muốn rút là xong thôi mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Mỗi ngày rút được tối đa bao nhiêu tiền mặt vậy, có bị giới hạn không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','Hạn mức ATM mỗi ngày là hai mươi triệu, đủ xài sinh hoạt phí thoải mái luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhớ rút thẻ ra liền đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng rồi, để quá lâu không rút thẻ là máy tự nuốt thẻ đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nha, không thì em dễ quên lắm.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Chào chị, tôi bị mất thẻ ngân hàng, tôi cần báo mất và khóa thẻ khẩn cấp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Anh vui lòng cho biết họ tên, bốn số cuối thẻ ngân hàng và số chứng minh nhân dân ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Tôi ghi nhớ đầy đủ hết rồi, giờ tôi đọc cho chị kiểm tra nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm thời đóng băng thẻ của anh rồi, tiền sẽ không bị mất cắp đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau này muốn làm lại thẻ mới thì có phải ra quầy trực tiếp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng, anh mang theo hộ chiếu đến chi nhánh gần nhất là làm lại thẻ được ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn chị nhiều, may mà tôi gọi báo mất kịp thời.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào chị, tôi cần in bảng sao kê giao dịch thẻ ngân hàng khoảng nửa năm gần đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được ạ, anh đưa thẻ ngân hàng và hộ chiếu, tôi tra cứu và in giúp anh nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê như vậy có mất phí gì không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh in sao kê phục vụ mục đích du học thì được miễn phí đó anh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Tuyệt quá, tôi cần nộp cho trường làm chứng từ tài chính.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Tôi sẽ đóng dấu ngân hàng lên đây, trường sẽ chấp nhận trực tiếp không cần thêm gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn chị vất vả rồi, lát tôi lấy sao kê xong là về liền.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào anh, tôi muốn đổi mật khẩu rút tiền của thẻ ngân hàng ở máy tự phục vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Anh cắm thẻ vào, nhập mật khẩu cũ trước, rồi đặt mật khẩu mới sáu chữ số là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Tôi vừa nhập một lần rồi, máy báo hai lần mật khẩu không khớp nhau nè.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Tôi nhìn không rõ màn hình, hai lần gõ số không giống nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao đâu, anh làm lại một lần nữa, để ý kỹ số trên màn hình là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Được, để tôi làm từ từ, lần này chắc chắn để ý màn hình cẩn thận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công rồi, cảm ơn anh đứng bên cạnh hướng dẫn cho em nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Chào chị, nếu tôi chuyển tiền về tài khoản ở Việt Nam thì phí chuyển tính như thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí chuyển gồm hai phần, phí công thủ tục cố định và phí điện tín xuyên biên giới ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì mức phí có thay đổi theo không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Phí áp dụng theo mức cố định, không tăng giảm theo số tiền chuyển đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền về đến tài khoản ngân hàng ở nước ngoài của người nhận ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, nếu trúng ngày lễ thì thời gian thanh toán bù trừ sẽ lùi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi hiểu rõ hết rồi ạ, cảm ơn chị đã giải thích tỉ mỉ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理；商家责任退款自动审核，到账速度更快。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我要反馈一笔线上订单问题，支付扣款成功，至今没有收到包裹。','nǐ hǎo， wǒ yào fǎn kuì yī bǐ xiàn shàng dìng dān wèn tí， zhī fù kòu kuǎn chéng gōng， zhì jīn méi yǒu shōu dào bāo guǒ。','Chào chị, tôi muốn phản ánh một đơn hàng online, tiền đã bị trừ thanh toán thành công nhưng đến giờ vẫn chưa nhận được hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'您好，麻烦先提供一下完整订单编号，我调取后台物流配送记录哈。','nín hǎo， má fán xiān tí gōng yī xià wán zhěng dìng dān biān hào， wǒ diào qǔ hòu tái wù liú pèi sòng jì lù hā。','Chào anh, phiền anh cung cấp giúp mã đơn hàng đầy đủ, tôi tra lại thông tin vận chuyển ở hệ thống hậu đài nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单编号我复制在这里发给你，物流页面从下单当天一直显示待揽收状态呢。','dìng dān biān hào wǒ fù zhì zài zhè lǐ fā gěi nǐ， wù liú yè miàn cóng xià dān dàng tiān yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng tôi sao chép gửi chị đây, trang theo dõi vận chuyển từ lúc đặt hàng đến giờ vẫn báo trạng thái chờ lấy hàng.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'我调取仓库发货台账核对，查到是仓库工作人员漏打包商品，实在非常抱歉。','wǒ diào qǔ cāng kù fā huò tái zhàng hé duì， chá dào shì cāng kù gōng zuò rén yuán lòu dǎ bāo shāng pǐn， shí zài fēi cháng bào qiàn。','Tôi kiểm tra sổ sách xuất kho thì phát hiện là nhân viên kho đóng gói thiếu sót hàng của anh, thực sự rất xin lỗi anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'我下单已经七天，一直等待收货，耽误了我的使用计划，心里挺着急的。','wǒ xià dān yǐ jīng qī tiān， yì zhí děng dài shōu huò， dān wù le wǒ de shǐ yòng jì huà， xīn lǐ tǐng zháo jí de。','Tôi đặt hàng đã bảy ngày rồi, cứ chờ mãi mà chưa có hàng, ảnh hưởng đến kế hoạch sử dụng của tôi, trong lòng khá sốt ruột.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'针对漏发问题平台提供两种解决方案，您可以自由选择，没有强制要求。','zhēn duì lòu fā wèn tí píng tái tí gōng liǎng zhǒng jiě jué fāng àn， nín kě yǐ zì yóu xuǎn zé， méi yǒu qiáng zhì yāo qiú。','Đối với trường hợp thiếu hàng, bên nền tảng đưa ra hai phương án giải quyết, anh có thể tự chọn, không bắt buộc gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'那现在第一种方案补发商品、第二种全额退款，两种分别需要等待多久？','nà xiàn zài dì yī zhǒng fāng àn bǔ fā shāng pǐn、 dì èr zhǒng quán é tuì kuǎn， liǎng zhǒng fēn bié xū yào děng dài duō jiǔ？','Vậy phương án một là gửi bù hàng, phương án hai là hoàn tiền toàn bộ, mỗi cái phải đợi bao lâu vậy chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_08','V358','客服',8,'选择补发需要重新排单发货，仓库备货需要再等三天；退款申请提交当日原路返还资金。','xuǎn zé bǔ fā xū yào chóng xīn pái dān fā huò， cāng kù bèi huò xū yào zài děng sān tiān； tuì kuǎn shēn qǐng tí jiāo dāng rì yuán lù fǎn huán zī jīn。','Nếu chọn gửi bù thì phải sắp lịch giao hàng lại, kho chuẩn bị hàng cần thêm ba ngày; còn hoàn tiền thì nộp đơn ngày nào là tiền về theo đường cũ ngay ngày đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_09','V358','阮明',9,'我急需这件商品使用，不想再额外等待三天补发货品。','wǒ jí xū zhè jiàn shāng pǐn shǐ yòng， bù xiǎng zài é wài děng dài sān tiān bǔ fā huò pǐn。','Tôi đang cần dùng món hàng này gấp, không muốn đợi thêm ba ngày để nhận hàng bù nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_10','V358','客服',10,'我明白您的需求，那我直接为您提交全额退款售后申请。','wǒ míng bái nín de xū qiú， nà wǒ zhí jiē wèi nín tí jiāo quán é tuì kuǎn shòu hòu shēn qǐng。','Tôi hiểu nhu cầu của anh rồi, vậy tôi sẽ nộp đơn hoàn tiền toàn bộ cho anh luôn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_11','V358','阮明',11,'退款审核会不会需要人工排队，延迟好几天到账？','tuì kuǎn shěn hé huì bú huì xū yào rén gōng pái duì， yán chí hǎo jǐ tiān dào zhàng？','Việc duyệt hoàn tiền có phải xếp hàng xử lý thủ công không, có bị chậm về tài khoản mấy ngày không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_12','V358','客服',12,'漏发属于商家全责，退款自动审核，几分钟内就能完成资金返还。','lòu fā shǔ yú shāng jiā quán zé， tuì kuǎn zì dòng shěn hé， jǐ fēn zhōng nèi jiù néng wán chéng zī jīn fǎn huán。','Trường hợp thiếu hàng là lỗi hoàn toàn của người bán, hoàn tiền được duyệt tự động, chỉ vài phút là tiền về lại tài khoản thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_13','V358','阮明',13,'那就直接办理全额退款吧，我不想继续等待补发货物了。','nà jiù zhí jiē bàn lǐ quán é tuì kuǎn ba， wǒ bù xiǎng jì xù děng dài bǔ fā huò wù le。','Vậy làm hoàn tiền toàn bộ luôn đi, tôi không muốn đợi gửi bù hàng nữa.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_14','V358','客服',14,'申请已提交，您留意支付软件的到账通知即可。','shēn qǐng yǐ tí jiāo， nín liú yì zhī fù ruǎn jiàn de dào zhàng tōng zhī jí kě。','Đơn đã được nộp rồi, anh chú ý thông báo tiền về trên ứng dụng thanh toán là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_15','V358','阮明',15,'好，感谢快速处理我的售后投诉。','hǎo， gǎn xiè kuài sù chǔ lǐ wǒ de shòu hòu tóu sù。','Vâng, cảm ơn chị xử lý khiếu nại của tôi nhanh chóng.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chào chú, cháu muốn đến phố đi bộ trung tâm thành phố thì đón xe buýt tuyến nào ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra khỏi cửa rẽ phải, đến trạm bắt tuyến 12, điểm cuối chính là trung tâm thành phố luôn đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Đi một chuyến mất khoảng bao lâu vậy chú, có hay bị kẹt xe không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt xe thì bốn mươi phút, vào giờ tan tầm thì sẽ chậm hơn một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt có hỗ trợ quét mã trên điện thoại để lên xe, không cần làm thẻ cứng đúng không chú?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi, mở mã lên xe ra rồi quét là lên xe được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cảm ơn chú chỉ đường nha, giờ cháu ra trạm chờ xe luôn đây.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự động này nạp tiền vào thẻ tàu điện thế nào vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Bạn đặt thẻ lên vùng cảm ứng trước, rồi chọn số tiền cần nạp và quét mã thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Tôi quét mã thanh toán xong rồi mà máy báo nạp tiền thất bại nè.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại đã bị trừ tiền, nhưng số dư trong thẻ lại không tăng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Đừng lo, hệ thống bị chậm thôi, khoảng năm phút nữa kiểm tra lại số dư là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Thì ra là do hệ thống bị đơ, để lát nữa tôi xem lại số dư vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, không thì tôi chẳng biết làm sao luôn đó.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, tôi quét mã mở khóa xe đạp công cộng sao cứ báo mở khóa thất bại hoài vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Bạn xem thử bluetooth điện thoại đã bật chưa, đi xe là phải bật bluetooth đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth mở rồi mà, màn hình cứ hiện xe bị hỏng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là xe đó có vấn đề rồi, bạn bấm nút đổi xe khác là được ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Thì ra là vậy, tôi cứ tưởng tài khoản mình có vấn đề chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Ngoài đường có nhiều xe dự phòng lắm, đổi qua xe khác là mở khóa được liền à.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn bạn nhắc tôi nhiều lắm, không thì tôi phải đứng đây lâu lắm rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào anh, tôi muốn thuê một chiếc xe máy điện, chỉ dùng nửa ngày thôi có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Không vấn đề gì, nửa ngày ba mươi tệ, cần thế chấp hộ chiếu của anh để đăng ký nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Tôi đi xe ra khu du lịch ngoại ô, pin đi về có đủ dùng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy đi được năm mươi cây số, đi gần thế này thì thoải mái đủ dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ giữa đường hết pin thì cửa hàng có thiết bị sạc dự phòng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có sạc di động, anh có thể mang theo bên người để phòng khi cần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Được rồi, vậy giờ tôi đăng ký thuê xe luôn, phiền anh giúp giùm nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào bạn, tôi muốn dùng máy tự động mua một vé tàu cao tốc đi thành phố kế bên vào cuối tuần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Anh đặt hộ chiếu vào vùng đọc thẻ trước, rồi nhập ga đến là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn xong chuyến tàu rồi, nhưng hệ thống báo giấy tờ người nước ngoài không xác thực trực tuyến được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này anh phải ra quầy nhân viên, họ sẽ nhập thông tin thủ công cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy nhân viên có đông người xếp hàng không, chắc phải đợi lâu lắm không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Bây giờ không đông lắm đâu, khoảng mười phút là mua xong vé thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Được rồi, tôi ra quầy nhân viên ngay đây, cảm ơn bạn đã hướng dẫn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi có mua vé tàu cao tốc sáng mai, giờ muốn đổi sang chuyến buổi chiều ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Anh cho tôi xin hộ chiếu dùng để mua vé, để tôi kiểm tra vé còn trống giúp anh nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé như vậy có phải trả thêm phí gì không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ tàu chạy thì đổi vé lần đầu miễn phí, đổi lần thứ hai mới tính phí đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều vẫn còn chỗ trống đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Vẫn còn ghế hạng hai, để tôi đổi thông tin chuyến tàu cho anh luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị nhiều, thay đổi lịch trình đột xuất thế này thật ngại quá.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Bác tài ơi phiền bác chạy nhanh giùm chút, tôi khó chịu trong người cần đến bệnh viện gấp ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Yên tâm đi, tôi sẽ tránh mấy đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Xuống ngay cổng chính bệnh viện, không cần vào tầng hầm để xe được không bác?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Không vấn đề gì, khu vực đón trả khách tạm thời ở cổng chính có thể dừng ngắn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Tôi chóng mặt dữ lắm, phiền bác chạy êm êm chút nha.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, có gì khó chịu cứ nói với tôi bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn bác đã thông cảm cho tôi nhiều lắm, tới nơi tôi thanh toán ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào anh, cho tôi hỏi tuyến xe buýt số 18 tối nay chuyến cuối chạy lúc mấy giờ vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín giờ rưỡi, nhưng hôm nay tuyến điều chỉnh tạm thời nên chín giờ là hết chuyến rồi đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào chuyển xe khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể chuyển sang đi tàu điện ngầm, chuyến cuối của tàu điện phải mười một giờ mới ngừng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ ra ga tàu điện thì mất khoảng mấy phút vậy ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Khoảng bảy tám phút thôi, cứ đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_07','V366','阮明',7,'好，那我提前出发去坐地铁，多谢告知。','hǎo， nà wǒ tí qián chū fā qù zuò dì tiě， duō xiè gào zhī。','Dạ được, vậy tôi đi sớm để kịp bắt tàu điện, cảm ơn anh đã chỉ giúp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT367','S121','Hỏi lối ra gần nhất tới địa điểm cần đến',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V367','SIT367','P1','suon_se','tuy_y',NULL,'大型商场划分专门网约车上下客出口，普通主干道禁止车辆临时停靠，避免拥堵。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_01','V367','阮明',1,'师傅，我想打车，最近的商场出口往哪边走呢？','shī fù， wǒ xiǎng dǎ chē， zuì jìn de shāng chǎng chū kǒu wǎng nǎ biān zǒu ne？','Anh ơi, tôi muốn bắt taxi, lối ra gần nhất của trung tâm thương mại đi hướng nào vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_02','V367','安保人员',2,'直走到中庭右转，一号门就是打车专用出口哦。','zhí zǒu dào zhōng tíng yòu zhuǎn， yī hào mén jiù shì dǎ chē zhuān yòng chū kǒu ó。','Đi thẳng tới sảnh giữa rồi rẽ phải, cửa số 1 là lối ra chuyên dùng để bắt taxi đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_03','V367','阮明',3,'一号门外面有专门的等候区域吧？','yī hào mén wài miàn yǒu zhuān mén de děng hòu qū yù ba？','Ngoài cửa số 1 có khu vực chờ riêng đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_04','V367','安保人员',4,'有的，路边不能随便停车，只能在指定区域等车。','yǒu de， lù biān bù néng suí biàn tíng chē， zhǐ néng zài zhǐ dìng qū yù děng chē。','Có chứ, ngoài đường không được đậu xe tùy tiện, chỉ được chờ xe ở khu vực chỉ định thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_05','V367','阮明',5,'我拎了不少东西，这条路线没有台阶对吗？','wǒ līn le bù shǎo dōng xī， zhè tiáo lù xiàn méi yǒu tái jiē duì ma？','Tôi xách khá nhiều đồ, đoạn đường này không có bậc thang đúng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_06','V367','安保人员',6,'全程平坦通道，推行李箱、拎重物都方便。','quán chéng píng tǎn tōng dào， tuī xíng lǐ xiāng、 līn zhòng wù dōu fāng biàn。','Cả đoạn đường đều bằng phẳng, kéo vali hay xách đồ nặng đều thoải mái.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_07','V367','阮明',7,'清楚了，麻烦你指路啦。','qīng chǔ le， má fán nǐ zhǐ lù la。','Rõ rồi, phiền anh chỉ đường giùm nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT368','S123','Trả xe thuê trễ giờ, hỏi phụ phí',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V368','SIT368','P1','twist','ban_chinh_thuc',NULL,'共享电单车设置固定免费时长，超时产生溢价费用，平台优惠券一般仅抵扣基础租赁费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_01','V368','阮明',1,'你好，我租的共享电车超时半小时，要补多少钱？','nǐ hǎo， wǒ zū de gòng xiǎng diàn chē chāo shí bàn xiǎo shí， yào bǔ duō shǎo qián？','Chào chị, xe điện tôi thuê bị quá giờ nửa tiếng, phải bù thêm bao nhiêu tiền vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_02','V368','运维员',2,'基础时长两小时，超出后每半小时加收五元哈。','jī chǔ shí cháng liǎng xiǎo shí， chāo chū hòu měi bàn xiǎo shí jiā shōu wǔ yuán hā。','Thời gian cơ bản là hai tiếng, quá giờ thì cứ mỗi nửa tiếng tính thêm năm tệ nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_03','V368','阮明',3,'页面提示有超时罚款，不能直接抵扣优惠券嘛？','yè miàn tí shì yǒu chāo shí fá kuǎn， bù néng zhí jiē dǐ kòu yōu huì quàn ma？','Trên màn hình báo phạt quá giờ, không dùng mã giảm giá để trừ trực tiếp được à?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_04','V368','运维员',4,'超时产生的额外费用不支持优惠券抵扣的。','chāo shí chǎn shēng de é wài fèi yòng bù zhī chí yōu huì quàn dǐ kòu de。','Phí phát sinh do quá giờ thì không áp dụng mã giảm giá được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_05','V368','阮明',5,'原来是这样，那我直接微信扫码支付就行？','yuán lái shì zhè yàng， nà wǒ zhí jiē wēi xìn sǎo mǎ zhī fù jiù xíng？','Ra là vậy, thế tôi quét mã QR trên Wechat thanh toán trực tiếp luôn là được đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_06','V368','运维员',6,'对，站点二维码扫码就能结清所有费用。','duì， zhàn diǎn èr wéi mǎ sǎo mǎ jiù néng jié qīng suǒ yǒu fèi yòng。','Đúng rồi, quét mã QR ở trạm là thanh toán hết mọi khoản luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_07','V368','阮明',7,'好，我马上付款，下次一定看好还车时限。','hǎo， wǒ mǎ shàng fù kuǎn， xià cì yí dìng kàn hǎo hái chē shí xiàn。','Được, tôi thanh toán ngay đây, lần sau nhất định phải để ý giờ trả xe.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT369','S126','Báo mất hộ chiếu với cảnh sát',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V369','SIT369','P1','suon_se','chinh_thuc',NULL,'外籍人士丢失护照必须先到派出所开具遗失报案回执，再前往出入境大厅办理临时通行证明，后续可凭回执到本国驻华大使馆补办正式护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_01','V369','阮明',1,'警官您好，我有紧急情况，今天出门逛街把本人护照弄丢了，前来派出所报案。','jǐng guān nín hǎo， wǒ yǒu jǐn jí qíng kuàng， jīn tiān chū mén guàng jiē bǎ běn rén hù zhào nòng diū le， qián lái pài chū suǒ bào àn。','Chào công an, tôi có chuyện gấp, hôm nay đi dạo phố bị mất hộ chiếu của mình, đến đồn báo án ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_02','V369','民警',2,'你先平复一下情绪，我们一步步核对信息，先告诉我你的基础个人信息。','nǐ xiān píng fù yī xià qíng xù， wǒ men yí bù bù hé duì xìn xī， xiān gào sù wǒ nǐ de jī chǔ gè rén xìn xī。','Bạn bình tĩnh lại đã, chúng ta sẽ đối chiếu thông tin từng bước một, trước tiên cho tôi biết thông tin cá nhân cơ bản của bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_03','V369','阮明',3,'我叫阮明，二十二岁越南留学生，在本市高校就读汉语言专业。','wǒ jiào ruǎn míng， èr shí èr suì yuè nán liú xué shēng， zài běn shì gāo xiào jiù dú hàn yǔ yán zhuān yè。','Tôi tên Nguyễn Minh, hai mươi hai tuổi, du học sinh Việt Nam, đang học ngành Hán ngữ tại trường đại học ở thành phố này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_04','V369','民警',4,'接下来详细描述今天完整出行路线，从出门到发现遗失护照的全过程。','jiē xià lái xiáng xì miáo shù jīn tiān wán zhěng chū xíng lù xiàn， cóng chū mén dào fā xiàn yí shī hù zhào de quán guò chéng。','Tiếp theo hãy mô tả chi tiết toàn bộ hành trình hôm nay, từ lúc ra khỏi nhà cho đến khi phát hiện mất hộ chiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_05','V369','阮明',5,'中午十二点从学校宿舍出发，先去街边小吃店吃饭，下午两点抵达中心商业街。','zhōng wǔ shí èr diǎn cóng xué xiào sù shè chū fā， xiān qù jiē biān xiǎo chī diàn chī fàn， xià wǔ liǎng diǎn dǐ dá zhōng xīn shāng yè jiē。','Mười hai giờ trưa tôi xuất phát từ ký túc xá, trước tiên ghé quán ăn vặt ven đường ăn cơm, hai giờ chiều đến khu phố thương mại trung tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_06','V369','民警',6,'商业街范围很大，精确回忆遗失护照的时间段和具体店铺名称吧。','shāng yè jiē fàn wéi hěn dà， jīng què huí yì yí shī hù zhào de shí jiān duàn hé jù tǐ diàn pù míng chēng ba。','Khu phố thương mại rộng lắm, cố nhớ chính xác thời điểm mất hộ chiếu và tên cửa hàng cụ thể nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_07','V369','阮明',7,'下午三点左右，在商业街二楼文具店结账付款，走出店铺口袋就空了，护照不见了呢。','xià wǔ sān diǎn zuǒ yòu， zài shāng yè jiē èr lóu wén jù diàn jié zhàng fù kuǎn， zǒu chū diàn pù kǒu dài jiù kōng le， hù zhào bú jiàn le ne。','Khoảng ba giờ chiều, tôi thanh toán ở tiệm văn phòng phẩm tầng hai khu phố thương mại, ra khỏi tiệm là túi trống rỗng, hộ chiếu biến mất luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_08','V369','民警',8,'遗失之后你有没有原路返回店铺寻找，或者向店内店员求助查看监控？','yí shī zhī hòu nǐ yǒu méi yǒu yuán lù fǎn huí diàn pù xún zhǎo， huò zhě xiàng diàn nèi diàn yuán qiú zhù chá kàn jiān kòng？','Sau khi phát hiện mất, bạn có quay lại tiệm tìm hay nhờ nhân viên xem camera giám sát không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_09','V369','阮明',9,'我返回文具店询问店员，他们柜台没有捡到护照，商铺监控只能由派出所出具证明才能调取。','wǒ fǎn huí wén jù diàn xún wèn diàn yuán， tā men guì tái méi yǒu jiǎn dào hù zhào， shāng pù jiān kòng zhǐ néng yóu pài chū suǒ chū jù zhèng míng cái néng diào qǔ。','Tôi có quay lại tiệm văn phòng phẩm hỏi nhân viên, quầy họ không nhặt được hộ chiếu, còn camera của cửa hàng thì phải có giấy xác nhận của công an mới trích xuất được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_10','V369','民警',10,'我现在为你制作一份标准遗失报案记录，需要你填写国籍、护照编号、在校信息。','wǒ xiàn zài wèi nǐ zhì zuò yī fèn biāo zhǔn yí shī bào àn jì lù， xū yào nǐ tián xiě guó jí、 hù zhào biān hào、 zài xiào xìn xī。','Bây giờ tôi lập biên bản báo mất theo mẫu chuẩn cho bạn, cần bạn điền quốc tịch, số hộ chiếu, thông tin trường học.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_11','V369','阮明',11,'我手机里存了护照复印件照片，可以直接对照填写表格上的全部信息。','wǒ shǒu jī lǐ cún le hù zhào fù yìn jiàn zhào piān， kě yǐ zhí jiē duì zhào tián xiě biǎo gé shàng de quán bù xìn xī。','Trong điện thoại tôi có lưu ảnh chụp bản sao hộ chiếu, có thể đối chiếu để điền đầy đủ thông tin vào biểu mẫu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_12','V369','民警',12,'笔录填写完毕核对无误后签字，我打印报案回执交给你保管。','bǐ lù tián xiě wán bì hé duì wú wù hòu qiān zì， wǒ dǎ yìn bào àn huí zhí jiāo gěi nǐ bǎo guǎn。','Điền xong biên bản, đối chiếu không sai thì ký tên, tôi in phiếu tiếp nhận báo án giao cho bạn giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_13','V369','阮明',13,'做完这份遗失笔录，拿着纸质回执就能直接去出入境大厅办理临时通行证件吗？','zuò wán zhè fèn yí shī bǐ lù， ná zhe zhǐ zhì huí zhí jiù néng zhí jiē qù chū rù jìng dà tīng bàn lǐ lín shí tōng xíng zhèng jiàn ma？','Làm xong biên bản này, cầm phiếu tiếp nhận giấy là có thể đến thẳng sảnh xuất nhập cảnh làm giấy tờ tạm thời được luôn phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_14','V369','民警',14,'是的，这份派出所开具的报案回执是外籍人员补办证件必需的官方材料。','shì de， zhè fèn pài chū suǒ kāi jù de bào àn huí zhí shì wài jí rén yuán bǔ bàn zhèng jiàn bì xū de guān fāng cái liào。','Đúng vậy, phiếu tiếp nhận báo án do đồn công an cấp này là giấy tờ chính thức bắt buộc để người nước ngoài làm lại giấy tờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_15','V369','阮明',15,'给警官增添办案工作量实在不好意思，辛苦您帮忙登记备案。','gěi jǐng guān zēng tiān bàn àn gōng zuò liàng shí zài bù hǎo yì sī， xīn kǔ nín bāng máng dēng jì bèi àn。','Làm phiền công an thêm việc thế này thật ngại quá, cảm ơn anh đã vất vả ghi nhận giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_16','V369','民警',16,'保护外籍留学生证件安全是我们的工作，后续补办遇到问题可以再来咨询。','bǎo hù wài jí liú xué shēng zhèng jiàn ān quán shì wǒ men de gōng zuò， hòu xù bǔ bàn yù dào wèn tí kě yǐ zài lái zī xún。','Bảo vệ an toàn giấy tờ cho du học sinh nước ngoài là công việc của chúng tôi mà, sau này làm lại giấy tờ có vướng mắc gì cứ đến hỏi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_17','V369','阮明',17,'太感谢警官耐心登记信息！','tài gǎn xiè jǐng guān nài xīn dēng jì xìn xī！','Cảm ơn anh công an rất nhiều vì đã kiên nhẫn ghi nhận thông tin!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT370','S126','Báo mất ví tiền nơi công cộng',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V370','SIT370','P1','twist','ban_chinh_thuc',NULL,'商场、餐厅等公共场所设有失物招领处，捡到私人物品大多会统一送至前台保管；领取失物需要核对专属标识确认归属。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_01','V370','阮明',1,'你好，我刚才在商场三楼餐饮区用餐，离开后发现黑色钱包丢失，想申请广播寻物。','nǐ hǎo， wǒ gāng cái zài shāng chǎng sān lóu cān yǐn qū yòng cān， lí kāi hòu fā xiàn hēi sè qián bāo diū shī， xiǎng shēn qǐng guǎng bō xún wù。','Chào chị, tôi vừa ăn ở khu ẩm thực tầng ba trung tâm thương mại, ra khỏi đó thì phát hiện mất ví đen, muốn nhờ phát loa tìm giúp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_02','V370','客服',2,'您好，先跟您确认，丢失的钱包里面包含哪些重要物品，方便广播描述特征哦。','nín hǎo， xiān gēn nín què rèn， diū shī de qián bāo lǐ miàn bāo hán nǎ xiē zhòng yào wù pǐn， fāng biàn guǎng bō miáo shù tè zhēng ó。','Chào anh, để tôi xác nhận trước, trong ví bị mất có những vật quan trọng gì, để tiện mô tả đặc điểm khi phát loa nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03','V370','阮明',3,'里面有人民币现金、国内储蓄卡、留学生校园卡，全部对我非常重要。','lǐ miàn yǒu rén mín bì xiàn jīn、 guó nèi chǔ xù kǎ、 liú xué shēng xiào yuán kǎ， quán bù duì wǒ fēi cháng zhòng yào。','Bên trong có tiền mặt nhân dân tệ, thẻ ngân hàng trong nước, thẻ sinh viên du học, tất cả đều rất quan trọng với tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_04','V370','客服',4,'我现在立刻播放全场寻物广播，麻烦完整描述钱包外观细节，提高捡到者识别概率。','wǒ xiàn zài lì kè bō fàng quán chǎng xún wù guǎng bō， má fán wán zhěng miáo shù qián bāo wài guān xì jié， tí gāo jiǎn dào zhě shí bié gài lǜ。','Tôi phát loa tìm đồ ngay cho toàn khu bây giờ, phiền anh mô tả đầy đủ đặc điểm bên ngoài của ví, để tăng khả năng người nhặt được nhận ra.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_05','V370','阮明',5,'纯黑色短款皮质钱包，侧面有一道浅色划痕，里面放着越南留学生专属校园卡。','chún hēi sè duǎn kuǎn pí zhì qián bāo， cè miàn yǒu yī dào qiǎn sè huà hén， lǐ miàn fàng zhe yuè nán liú xué shēng zhuān shǔ xiào yuán kǎ。','Ví da màu đen tuyền kiểu ngắn, mặt bên có một vết xước màu nhạt, bên trong có thẻ sinh viên du học riêng của Việt Nam.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_06','V370','客服',6,'刚好半小时前商场保洁阿姨打扫餐厅，捡到一个黑色钱包送到前台保管，我拿给你核对嘛。','gāng hǎo bàn xiǎo shí qián shāng chǎng bǎo jié ā yí dǎ sǎo cān tīng， jiǎn dào yí gè hēi sè qián bāo sòng dào qián tái bǎo guǎn， wǒ ná gěi nǐ hé duì ma。','Vừa hay nửa tiếng trước cô lao công dọn ở khu ẩm thực có nhặt được một cái ví đen mang đến quầy lễ tân giữ, để tôi lấy cho anh đối chiếu nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_07','V370','阮明',7,'真的吗？里面一定会有印有越南国旗标识的留学生校园卡对吧？','zhēn de ma？ lǐ miàn yí dìng huì yǒu yìn yǒu yuè nán guó qí biāo shí de liú xué shēng xiào yuán kǎ duì ba？','Thật vậy sao? Bên trong chắc chắn có thẻ sinh viên du học in cờ Việt Nam đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_08','V370','客服',8,'没错，钱包内确实有这张校园卡，你当面清点里面所有物品确认齐全再拿走。','méi cuò， qián bāo nèi què shí yǒu zhè zhāng xiào yuán kǎ， nǐ dāng miàn qīng diǎn lǐ miàn suǒ yǒu wù pǐn què rèn qí quán zài ná zǒu。','Đúng vậy, trong ví đúng là có tấm thẻ sinh viên này, anh kiểm đếm trực tiếp toàn bộ đồ bên trong xem đủ chưa rồi hãy lấy đi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_09','V370','阮明',9,'现金、银行卡、校园卡全部完好，一样东西都没有缺少，太幸运了。','xiàn jīn、 yín háng kǎ、 xiào yuán kǎ quán bù wán hǎo， yī yàng dōng xī dōu méi yǒu quē shǎo， tài xìng yùn le。','Tiền mặt, thẻ ngân hàng, thẻ sinh viên đều còn nguyên vẹn, không thiếu món nào cả, may mắn quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_10','V370','客服',10,'商场所有拾获私人物品都会统一送至前台失物招领处登记保管。','shāng chǎng suǒ yǒu shí huò sī rén wù pǐn dōu huì tǒng yī sòng zhì qián tái shī wù zhāo lǐng chù dēng jì bǎo guǎn。','Mọi món đồ nhặt được của khách trong trung tâm thương mại đều được đưa về quầy tiếp nhận đồ thất lạc để ghi nhận và giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_11','V370','阮明',11,'还好保洁阿姨细心捡到上交，不然补办银行卡、证件要耗费大量时间。','hái hǎo bǎo jié ā yí xì xīn jiǎn dào shàng jiāo， bù rán bǔ bàn yín háng kǎ、 zhèng jiàn yào hào fèi dà liàng shí jiān。','May mà cô lao công tinh ý nhặt được rồi nộp lại, không thì làm lại thẻ ngân hàng, giấy tờ tốn thời gian lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_12','V370','客服',12,'下次出门贵重物品尽量贴身放好，避免遗失。','xià cì chū mén guì zhòng wù pǐn jǐn liàng tiē shēn fàng hǎo， bì miǎn yí shī。','Lần sau ra ngoài đồ giá trị nên mang sát người, tránh bị mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_13','V370','阮明',13,'我记住了，非常感谢你们帮忙妥善保管我的钱包。','wǒ jì zhù le， fēi cháng gǎn xiè nǐ men bāng máng tuǒ shàn bǎo guǎn wǒ de qián bāo。','Tôi ghi nhớ rồi, cảm ơn mọi người đã giúp giữ ví cẩn thận cho tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_14','V370','客服',14,'不用客气，这是我们商场该做的。','bù yòng kè qì， zhè shì wǒ men shāng chǎng gāi zuò de。','Không có gì đâu, đây là việc chúng tôi nên làm mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_15','V370','阮明',15,'麻烦各位工作人员了！','má fán gè wèi gōng zuò rén yuán le！','Cảm ơn các anh chị nhân viên nhiều nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT371','S126','Báo mất điện thoại, xin khóa SIM từ xa',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V371','SIT371','P1','suon_se','chinh_thuc',NULL,'手机丢失后可致电运营商紧急挂失SIM卡，补办卡片可保留原有手机号，不会更换号码；首次挂失补卡大多免除工本费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_01','V371','阮明',1,'您好，紧急求助，我的手机外出遗失，需要立刻远程锁定本人电话SIM卡。','nín hǎo， jǐn jí qiú zhù， wǒ de shǒu jī wài chū yí shī， xū yào lì kè yuǎn chéng suǒ dìng běn rén diàn huà SIM kǎ。','Chào chị, tôi cần hỗ trợ gấp, điện thoại tôi mang ra ngoài bị mất, cần khóa SIM từ xa ngay lập tức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_02','V371','客服',2,'您好，为完成挂失锁卡操作，需要核实实名登记的全部身份信息，请您配合。','nín hǎo， wèi wán chéng guà shī suǒ kǎ cāo zuò， xū yào hé shí shí míng dēng jì de quán bù shēn fèn xìn xī， qǐng nín pèi hé。','Chào anh, để hoàn tất thao tác báo mất khóa SIM, cần xác minh toàn bộ thông tin danh tính đăng ký thật, mong anh phối hợp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_03','V371','阮明',3,'我清楚实名核验流程，您需要什么信息我全部如实报给您核对。','wǒ qīng chǔ shí míng hé yàn liú chéng， nín xū yào shén me xìn xī wǒ quán bù rú shí bào gěi nín hé duì。','Tôi hiểu quy trình xác minh danh tính rồi, chị cần thông tin gì tôi sẽ khai báo đầy đủ, trung thực để chị đối chiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_04','V371','客服',4,'依次提供遗失手机号、实名登记姓名、本人护照完整编号吧。','yī cì tí gōng yí shī shǒu jī hào、 shí míng dēng jì xìng míng、 běn rén hù zhào wán zhěng biān hào ba。','Anh cung cấp lần lượt số điện thoại bị mất, tên đăng ký danh tính thật, số hộ chiếu đầy đủ của mình nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_05','V371','阮明',5,'手机号、姓名、护照号码我全部记录在备忘录，现在逐条念给您。','shǒu jī hào、 xìng míng、 hù zhào hào mǎ wǒ quán bù jì lù zài bèi wàng lù， xiàn zài zhú tiáo niàn gěi nín。','Số điện thoại, tên, số hộ chiếu tôi đều ghi lại trong ghi chú điện thoại, để tôi đọc từng mục cho chị nghe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_06','V371','客服',6,'信息核验全部匹配，系统已经完成紧急挂失锁卡，他人无法使用你的号码呢。','xìn xī hé yàn quán bù pǐ pèi， xì tǒng yǐ jīng wán chéng jǐn jí guà shī suǒ kǎ， tā rén wú fǎ shǐ yòng nǐ de hào mǎ ne。','Thông tin đối chiếu khớp hết rồi, hệ thống đã hoàn tất khóa SIM khẩn cấp, người khác không dùng được số của anh nữa đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_07','V371','阮明',7,'锁卡之后手机里绑定的支付软件、社交账号就不会被盗刷盗用了对吗？','suǒ kǎ zhī hòu shǒu jī lǐ bǎng dìng de zhī fù ruǎn jiàn、 shè jiāo zhàng hào jiù bú huì bèi dào shuā dào yòng le duì ma？','Khóa SIM rồi thì các ứng dụng thanh toán, tài khoản mạng xã hội gắn với điện thoại sẽ không bị đánh cắp, lợi dụng nữa đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_08','V371','客服',8,'SIM卡锁定后无法接收验证码，能最大程度保护你的账户、资金安全。','SIM kǎ suǒ dìng hòu wú fǎ jiē shōu yàn zhèng mǎ， néng zuì dà chéng dù bǎo hù nǐ de zhàng hù、 zī jīn ān quán。','Sau khi khóa SIM thì không nhận được mã xác nhận nữa, sẽ bảo vệ tài khoản và tiền của anh ở mức tối đa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_09','V371','阮明',9,'挂失锁卡只是临时冻结，后续补办新卡还能保留原来的手机号码吗？','guà shī suǒ kǎ zhǐ shì lín shí dòng jié， hòu xù bǔ bàn xīn kǎ hái néng bǎo liú yuán lái de shǒu jī hào mǎ ma？','Báo mất khóa SIM chỉ là đóng băng tạm thời, sau này làm lại thẻ mới có giữ được số điện thoại cũ không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_10','V371','客服',10,'完全可以，携带本人护照前往线下任意营业厅就能补办同号SIM卡。','wán quán kě yǐ， xié dài běn rén hù zhào qián wǎng xiàn xià rèn yì yíng yè tīng jiù néng bǔ bàn tóng hào SIM kǎ。','Hoàn toàn được, anh mang hộ chiếu của mình đến bất kỳ điểm giao dịch nào là làm lại được SIM giữ nguyên số.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_11','V371','阮明',11,'补办卡片需要额外支付工本费，还是免费办理？','bǔ bàn kǎ piàn xū yào é wài zhī fù gōng běn fèi， hái shì miǎn fèi bàn lǐ？','Làm lại thẻ có phải trả thêm phí làm thẻ không, hay là miễn phí?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_12','V371','客服',12,'首次挂失补卡免收工本费，一年内多次补卡才会收取卡片费用。','shǒu cì guà shī bǔ kǎ miǎn shōu gōng běn fèi， yī nián nèi duō cì bǔ kǎ cái huì shōu qǔ kǎ piàn fèi yòng。','Lần đầu báo mất làm lại thẻ thì miễn phí, trong một năm làm lại nhiều lần mới bị tính phí thẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_13','V371','阮明',13,'清楚全部规则了，太感谢您第一时间帮我冻结手机号。','qīng chǔ quán bù guī zé le， tài gǎn xiè nín dì yī shí jiān bāng wǒ dòng jié shǒu jī hào。','Tôi hiểu hết quy định rồi, cảm ơn chị rất nhiều vì đã giúp tôi khóa số điện thoại kịp thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_14','V371','客服',14,'后续补办有任何疑问，随时拨打官方客服热线咨询。','hòu xù bǔ bàn yǒu rèn hé yí wèn， suí shí bō dǎ guān fāng kè fú rè xiàn zī xún。','Sau này làm lại thẻ có thắc mắc gì thì cứ gọi tổng đài chăm sóc khách hàng chính thức để hỏi nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_15','V371','阮明',15,'多亏及时挂失，避免财产受损，十分感谢！','duō kuī jí shí guà shī， bì miǎn cái chǎn shòu sǔn， shí fēn gǎn xiè！','May mà báo mất kịp thời, tránh bị thiệt hại tài sản, cảm ơn chị rất nhiều!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆；伤者骨折、出血不可随意挪动，防止二次伤害。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好，这里发生人员摔倒受伤事故，情况紧急，麻烦尽快派遣救护车过来啊！','nín hǎo， zhè lǐ fā shēng rén yuán shuāi dǎo shòu shāng shì gù， qíng kuàng jǐn jí， má fán jǐn kuài pài qiǎn jiù hù chē guò lái a！','Alo, ở đây có người bị té ngã chấn thương, tình hình khẩn cấp, làm ơn điều xe cứu thương đến gấp giúp với!','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'请先保持冷静，不要慌乱，分步骤告知我精准地址与伤者详细状况吧。','qǐng xiān bǎo chí lěng jìng， bú yào huāng luàn， fēn bù zhòu gào zhī wǒ jīng zhǔn dì zhǐ yǔ shāng zhě xiáng xì zhuàng kuàng ba。','Anh giữ bình tĩnh trước đã, đừng hoảng, cho tôi biết theo từng bước địa chỉ chính xác và tình trạng cụ thể của người bị thương nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'事发地点在大学南门沿街小吃街，伤者下楼梯摔倒，腿部大面积出血，暂时无法自主站立呢。','shì fā dì diǎn zài dà xué nán mén yán jiē xiǎo chī jiē， shāng zhě xià lóu tī shuāi dǎo， tuǐ bù dà miàn jī chū xiě， zàn shí wú fǎ zì zhǔ zhàn lì ne。','Địa điểm xảy ra là ở phố ăn vặt ngay cổng nam trường đại học, người bị thương té ngã khi xuống cầu thang, chân chảy máu nhiều, tạm thời không tự đứng dậy được.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'现场千万不要随意挪动、拖拽伤者，避免造成二次骨骼损伤，医护人员十分钟内抵达现场。','xiàn chǎng qiān wàn bú yào suí yì nuó dòng、 tuō zhuāi shāng zhě， bì miǎn zào chéng èr cì gǔ gé sǔn shāng， yī hù rén yuán shí fēn zhōng nèi dǐ dá xiàn chǎng。','Tuyệt đối không được tự ý di chuyển, kéo lê người bị thương, tránh gây tổn thương xương lần hai, nhân viên y tế sẽ có mặt trong mười phút nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'我会守在路口显眼位置等候救护车，指引医护车辆快速找到事发点位。','wǒ huì shǒu zài lù kǒu xiǎn yǎn wèi zhì děng hòu jiù hù chē， zhǐ yǐn yī hù chē liàng kuài sù zhǎo dào shì fā diǎn wèi。','Tôi sẽ đứng ở vị trí dễ thấy ở đầu đường chờ xe cứu thương, chỉ đường cho xe y tế nhanh chóng tìm đến hiện trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'全程保持通话畅通，如果伤者出血量变大、意识模糊，立刻同步告知我。','quán chéng bǎo chí tōng huà chàng tōng， rú guǒ shāng zhě chū xiě liàng biàn dà、 yì shí mó hú， lì kè tóng bù gào zhī wǒ。','Anh giữ máy liên tục nhé, nếu người bị thương chảy máu nhiều hơn hoặc mê man thì báo ngay cho tôi biết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'我随身带纸巾按压伤口止血，暂时没有出现意识不清的情况。','wǒ suí shēn dài zhǐ jīn àn yā shāng kǒu zhǐ xuè， zàn shí méi yǒu chū xiàn yì shí bù qīng de qíng kuàng。','Tôi có mang khăn giấy bên người để ấn cầm máu vết thương, hiện tại chưa có tình trạng mê man.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_08','V372','接线员',8,'医护抵达前持续按压出血部位，减少血液流失。','yī hù dǐ dá qián chí xù àn yā chū xiě bù wèi， jiǎn shǎo xuè yè liú shī。','Trước khi nhân viên y tế đến thì cứ ấn liên tục vào chỗ chảy máu, để giảm mất máu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_09','V372','阮明',9,'我会严格按照您的指引简单处理伤口，不擅自移动伤者。','wǒ huì yán gé àn zhào nín de zhǐ yǐn jiǎn dān chǔ lǐ shāng kǒu， bù shàn zì yí dòng shāng zhě。','Tôi sẽ làm đúng theo hướng dẫn của chị để sơ cứu vết thương đơn giản, không tự ý di chuyển người bị thương.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_10','V372','接线员',10,'救护车已经驶出医院，距离现场还有三分钟路程。','jiù hù chē yǐ jīng shǐ chū yī yuàn， jù lí xiàn chǎng hái yǒu sān fēn zhōng lù chéng。','Xe cứu thương đã xuất phát từ bệnh viện rồi, còn cách hiện trường khoảng ba phút nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_11','V372','阮明',11,'我现在站在校门口马路边挥手示意车辆。','wǒ xiàn zài zhàn zài xiào mén kǒu mǎ lù biān huī shǒu shì yì chē liàng。','Tôi đang đứng ở lề đường trước cổng trường vẫy tay ra hiệu cho xe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_12','V372','接线员',12,'辛苦你现场协助看护伤者，医护马上抵达。','xīn kǔ nǐ xiàn chǎng xié zhù kān hù shāng zhě， yī hù mǎ shàng dǐ dá。','Anh vất vả rồi, cứ hỗ trợ trông chừng người bị thương tại chỗ, nhân viên y tế sắp đến ngay đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_13','V372','阮明',13,'好的，我全程在这里等候，辛苦你们火速赶来！','hǎo de， wǒ quán chéng zài zhè lǐ děng hòu， xīn kǔ nǐ men huǒ sù gǎn lái！','Vâng, tôi sẽ đợi ở đây suốt, mọi người vất vả rồi, mong đến thật nhanh!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖；国内宿舍厨房明令禁止无人看管明火，无人值守属于违规行为。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，紧急跟您汇报，宿舍楼公共厨房炒锅起火，我已经第一时间关闭燃气总阀。','sù guǎn lǎo shī， jǐn jí gēn nín huì bào， sù shè lóu gōng gòng chú fáng chǎo guō qǐ huǒ， wǒ yǐ jīng dì yī shí jiān guān bì rán qì zǒng fá。','Cô quản lý ơi, con báo gấp với cô, chảo đang chiên ở bếp chung ký túc xá bị bắt lửa, con đã tắt van gas tổng ngay rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',2,'你先远离起火厨具，我先确认一件事，有没有直接用水浇灭锅里的火源嘛？','nǐ xiān yuǎn lí qǐ huǒ chú jù， wǒ xiān què rèn yī jiàn shì， yǒu méi yǒu zhí jiē yòng shuǐ jiāo miè guō lǐ de huǒ yuán ma？','Con tránh xa cái bếp đang cháy ra trước đã, cô hỏi con một chuyện, con có dùng nước dội thẳng vào lửa trong chảo không vậy?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',3,'我之前上过宿舍安全培训，牢记油锅起火不能浇水，立刻拿锅盖完整盖住锅体隔绝氧气灭火。','wǒ zhī qián shàng guò sù shè ān quán péi xùn， láo jì yóu guō qǐ huǒ bù néng jiāo shuǐ， lì kè ná guō gài wán zhěng gài zhù guō tǐ gé jué yǎng qì miè huǒ。','Con từng học tập huấn an toàn ký túc xá rồi, nhớ kỹ là lửa dầu không được dội nước, con lấy nắp vung đậy kín chảo luôn để ngăn oxy dập lửa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',4,'还好你掌握正确灭火方法，没有盲目泼水引发火势扩散，我现在携带灭火器赶往厨房。','hái hǎo nǐ zhǎng wò zhèng què miè huǒ fāng fǎ， méi yǒu máng mù pō shuǐ yǐn fā huǒ shì kuò sàn， wǒ xiàn zài xié dài miè huǒ qì gǎn wǎng chú fáng。','May mà con biết cách dập lửa đúng, không dội nước bừa làm lửa lan rộng, giờ cô mang bình chữa cháy chạy đến bếp đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',5,'明火已经完全熄灭，只是墙面瓷砖被烟火轻微熏黑，没有蔓延到周边厨具、橱柜对吧？','míng huǒ yǐ jīng wán quán xī miè， zhǐ shì qiáng miàn cí zhuān bèi yān huǒ qīng wēi xūn hēi， méi yǒu màn yán dào zhōu biān chú jù、 chú guì duì ba？','Lửa đã tắt hoàn toàn rồi ạ, chỉ có gạch tường bị ám khói hơi đen thôi, không lan sang các dụng cụ nấu, tủ bếp xung quanh đúng không cô?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',6,'只要没有引燃橱柜、纸巾等易燃物品，就不算重大火情，仅轻微安全隐患。','zhǐ yào méi yǒu yǐn rán chú guì、 zhǐ jīn děng yì rán wù pǐn， jiù bù suàn zhòng dà huǒ qíng， jǐn qīng wēi ān quán yǐn huàn。','Miễn là không bén lửa vào tủ bếp, khăn giấy hay đồ dễ cháy khác thì không tính là hỏa hoạn lớn đâu, chỉ là ẩn họa nhỏ về an toàn thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',7,'这次起火是我熬汤忘记看管，离开几分钟汤水烧干才引燃锅底，是我的疏忽。','zhè cì qǐ huǒ shì wǒ áo tāng wàng jì kān guǎn， lí kāi jǐ fēn zhōng tāng shuǐ shāo gàn cái yǐn rán guō dǐ， shì wǒ de shū hū。','Lần này cháy là do con nấu súp mà quên trông, đi ra ngoài mấy phút nước cạn khô mới bén cháy đáy nồi, là lỗi của con sơ suất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_08','V373','宿管老师',8,'宿舍公共厨房明确规定明火烹饪必须有人全程看管，无人值守极易引发火灾。','sù shè gōng gòng chú fáng míng què guī dìng míng huǒ pēng rèn bì xū yǒu rén quán chéng kān guǎn， wú rén zhí shǒu jí yì yǐn fā huǒ zāi。','Bếp chung ký túc xá quy định rõ là nấu bằng lửa phải có người trông suốt, không ai canh chừng rất dễ gây hỏa hoạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_09','V373','阮明',9,'我深刻记住这条安全规定，之后做饭绝不擅自离开灶台半步。','wǒ shēn kè jì zhù zhè tiáo ān quán guī dìng， zhī hòu zuò fàn jué bù shàn zì lí kāi zào tái bàn bù。','Con ghi nhớ kỹ quy định an toàn này rồi, sau này nấu ăn tuyệt đối không rời khỏi bếp dù chỉ một bước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_10','V373','宿管老师',10,'我到现场检查残留隐患，确认无复燃风险之后再通知大家使用厨房。','wǒ dào xiàn chǎng jiǎn chá cán liú yǐn huàn， què rèn wú fù rán fēng xiǎn zhī hòu zài tōng zhī dà jiā shǐ yòng chú fáng。','Cô đến hiện trường kiểm tra xem còn ẩn họa gì không, xác nhận không còn nguy cơ cháy lại rồi mới báo mọi người dùng bếp tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_11','V373','阮明',11,'需要我留在厨房配合您清点厨具、说明起火全过程吗？','xū yào wǒ liú zài chú fáng pèi hé nín qīng diǎn chú jù、 shuō míng qǐ huǒ quán guò chéng ma？','Cô cần con ở lại bếp phối hợp kiểm kê dụng cụ nấu, kể lại toàn bộ quá trình cháy không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_12','V373','宿管老师',12,'你可以在值班室等候，检查完毕我会跟你说明后续注意事项。','nǐ kě yǐ zài zhí bān shì děng hòu， jiǎn chá wán bì wǒ huì gēn nǐ shuō míng hòu xù zhù yì shì xiàng。','Con cứ đợi ở phòng trực, kiểm tra xong cô sẽ nói cho con biết những điều cần chú ý tiếp theo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_13','V373','阮明',13,'给老师带来安全巡查的额外工作，实在抱歉。','gěi lǎo shī dài lái ān quán xún chá de é wài gōng zuò， shí zài bào qiàn。','Làm cô phải đi kiểm tra an toàn thêm việc thế này, con thật sự xin lỗi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_14','V373','宿管老师',14,'吸取教训就好，安全第一不用过度自责。','xī qǔ jiào xùn jiù hǎo， ān quán dì yī bù yòng guò dù zì zé。','Rút kinh nghiệm là được rồi, an toàn là trên hết, con không cần tự trách quá đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_15','V373','阮明',15,'我之后做饭一定时刻留意火源，不会再出现这种情况。','wǒ zhī hòu zuò fàn yí dìng shí kè liú yì huǒ yuán， bú huì zài chū xiàn zhè zhǒng qíng kuàng。','Sau này con nấu ăn nhất định lúc nào cũng để ý lửa, sẽ không để xảy ra chuyện như thế này nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场；外籍当事人护照可作为辅助身份凭证上传备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好，城市主干道十字路口发生两车轻微剐蹭，事故双方均无人员受伤。','nín hǎo， chéng shì zhǔ gàn dào shí zì lù kǒu fā shēng liǎng chē qīng wēi guǎ cèng， shì gù shuāng fāng jūn wú rén yuán shòu shāng。','Chào anh, ở ngã tư trục đường chính thành phố có hai xe va quẹt nhẹ, cả hai bên đều không có ai bị thương.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'先做好两件事，第一双方车辆挪至路边非机动车道，第二多角度拍摄完整现场照片留存证据吧。','xiān zuò hǎo liǎng jiàn shì， dì yī shuāng fāng chē liàng nuó zhì lù biān fēi jī dòng chē dào， dì èr duō jiǎo dù pāi shè wán zhěng xiàn chǎng zhào piān liú cún zhèng jù ba。','Trước tiên làm hai việc này nhé: một là dời cả hai xe vào làn xe không động cơ ven đường, hai là chụp ảnh hiện trường đầy đủ nhiều góc độ để lưu bằng chứng.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'我们已经共同把车辆停靠在不阻碍主路通行的非机动车道，前后、侧面、碰撞位置都拍好了多角度现场照片呢。','wǒ men yǐ jīng gòng tóng bǎ chē liàng tíng kào zài bù zǔ ài zhǔ lù tōng xíng de fēi jī dòng chē dào， qián hòu、 cè miàn、 pèng zhuàng wèi zhì dōu pāi hǎo le duō jiǎo dù xiàn chǎng zhào piān ne。','Chúng tôi đã cùng nhau đưa xe vào làn xe không động cơ không cản trở đường chính rồi, đã chụp đủ ảnh trước sau, bên hông, vị trí va chạm từ nhiều góc độ rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','接线员',4,'无人员伤亡、仅轻微车身剐蹭的小型事故，可通过交管线上平台快速定责，不需要交警线下现场出警。','wú rén yuán shāng wáng、 jǐn qīng wēi chē shēn guǎ cèng de xiǎo xíng shì gù， kě tōng guò jiāo guǎn xiàn shàng píng tái kuài sù dìng zé， bù xū yào jiāo jǐng xiàn xià xiàn chǎng chū jǐng。','Tai nạn nhỏ không ai thương vong, chỉ va quẹt thân xe nhẹ thì có thể xác định trách nhiệm nhanh qua nền tảng trực tuyến của công an giao thông, không cần cảnh sát đến hiện trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'线上平台处理事故，需要上传哪些证件照片，外籍留学生的护照可以作为有效证件使用吗？','xiàn shàng píng tái chǔ lǐ shì gù， xū yào shàng chuán nǎ xiē zhèng jiàn zhào piān， wài jí liú xué shēng de hù zhào kě yǐ zuò wéi yǒu xiào zhèng jiàn shǐ yòng ma？','Xử lý qua nền tảng online cần tải lên ảnh giấy tờ gì, hộ chiếu của du học sinh nước ngoài dùng làm giấy tờ hợp lệ được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','接线员',6,'需要上传机动车行驶证、驾驶员驾驶证，外加当事人护照照片，全部拍照上传系统即可。','xū yào shàng chuán jī dòng chē xíng shǐ zhèng、 jià shǐ yuán jià shǐ zhèng， wài jiā dāng shì rén hù zhào zhào piān， quán bù pāi zhào shàng chuán xì tǒng jí kě。','Cần tải lên giấy đăng ký xe, bằng lái xe của người điều khiển, thêm ảnh hộ chiếu của đương sự nữa, chụp ảnh và tải hết lên hệ thống là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'定责完成之后，理赔流程也是直接在线上操作，不用前往交警大队线下办理？','dìng zé wán chéng zhī hòu， lǐ péi liú chéng yě shì zhí jiē zài xiàn shàng cāo zuò， bù yòng qián wǎng jiāo jǐng dà duì xiàn xià bàn lǐ？','Xác định trách nhiệm xong thì quy trình bồi thường cũng làm trực tuyến luôn, không cần đến đội cảnh sát giao thông làm trực tiếp đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_08','V374','接线员',8,'全责方保险公司线上对接理赔，全程线上办结，省去线下跑腿时间。','quán zé fāng bǎo xiǎn gōng sī xiàn shàng duì jiē lǐ péi， quán chéng xiàn shàng bàn jié， shěng qù xiàn xià pǎo tuǐ shí jiān。','Bên chịu toàn bộ trách nhiệm thì công ty bảo hiểm kết nối bồi thường trực tuyến, xử lý xong hết trên mạng, đỡ mất thời gian đi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_09','V374','阮明',9,'我现在和对方车主整理全部证件照片，马上上传交管小程序。','wǒ xiàn zài hé duì fāng chē zhǔ zhěng lǐ quán bù zhèng jiàn zhào piān， mǎ shàng shàng chuán jiāo guǎn xiǎo chéng xù。','Giờ tôi và chủ xe kia đang sắp xếp hết ảnh giấy tờ, sẽ tải lên app công an giao thông ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_10','V374','接线员',10,'上传完成等待系统自动分配交警线上审核，半小时内出具责任认定书。','shàng chuán wán chéng děng dài xì tǒng zì dòng fēn pèi jiāo jǐng xiàn shàng shěn hé， bàn xiǎo shí nèi chū jù zé rèn rèn dìng shū。','Tải lên xong thì đợi hệ thống tự động phân cho cảnh sát duyệt online, trong nửa tiếng sẽ có biên bản xác định trách nhiệm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_11','V374','阮明',11,'清楚完整线上处理流程，不用耽误双方过多时间。','qīng chǔ wán zhěng xiàn shàng chǔ lǐ liú chéng， bù yòng dān wù shuāng fāng guò duō shí jiān。','Tôi hiểu rõ hết quy trình xử lý online rồi, không làm mất nhiều thời gian của cả hai bên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_12','V374','接线员',12,'后续理赔有纠纷，可再次拨打交警热线咨询。','hòu xù lǐ péi yǒu jiū fēn， kě zài cì bō dǎ jiāo jǐng rè xiàn zī xún。','Sau này bồi thường có tranh chấp gì thì cứ gọi lại đường dây nóng cảnh sát giao thông để hỏi nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_13','V374','阮明',13,'感谢您清晰告知线上快速处理流程！','gǎn xiè nín qīng xī gào zhī xiàn shàng kuài sù chǔ lǐ liú chéng！','Cảm ơn anh đã nói rõ quy trình xử lý online nhanh gọn như vậy!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程；完整聊天、转账截图是关键办案证据，不可删除。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我遭到网络虚假客服诱导转账，资金已经成功转入对方陌生账户，前来求助拦截。','nín hǎo， wǒ zāo dào wǎng luò xū jiǎ kè fú yòu dǎo zhuǎn zhàng， zī jīn yǐ jīng chéng gōng zhuǎn rù duì fāng mò shēng zhàng hù， qián lái qiú zhù lán jié。','Chào chị, tôi bị nhân viên chăm sóc khách hàng giả mạo trên mạng dụ chuyển tiền, tiền đã chuyển thành công vào tài khoản lạ của đối phương rồi, đến nhờ hỗ trợ chặn lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',2,'请立刻提供三项关键信息，对方收款账号、精确转账时间、完整转账金额哈。','qǐng lì kè tí gōng sān xiàng guān jiàn xìn xī， duì fāng shōu kuǎn zhàng hào、 jīng què zhuǎn zhàng shí jiān、 wán zhěng zhuǎn zhàng jīn é hā。','Anh cung cấp ngay ba thông tin quan trọng này: số tài khoản nhận tiền của đối phương, thời gian chuyển khoản chính xác, số tiền chuyển khoản đầy đủ nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',3,'我刚刚完成转账立刻察觉对方是骗子，想要操作转账撤回功能却系统提示失败嘛。','wǒ gāng gāng wán chéng zhuǎn zhàng lì kè chá jué duì fāng shì piàn zi， xiǎng yào cāo zuò zhuǎn zhàng chè huí gōng néng què xì tǒng tí shì shī bài ma。','Tôi vừa chuyển khoản xong là phát hiện ngay đối phương là lừa đảo, muốn thao tác thu hồi chuyển khoản thì hệ thống lại báo thất bại.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',4,'资金一旦成功转入私人第三方账户，无法由用户自主撤回，我现在紧急提交账户冻结指令。','zī jīn yí dàn chéng gōng zhuǎn rù sī rén dì sān fāng zhàng hù， wú fǎ yóu yòng hù zì zhǔ chè huí， wǒ xiàn zài jǐn jí tí jiāo zhàng hù dòng jié zhǐ lìng。','Một khi tiền đã chuyển thành công vào tài khoản bên thứ ba của cá nhân thì người dùng không tự thu hồi được, giờ tôi gửi lệnh khẩn cấp phong tỏa tài khoản đó ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',5,'账户冻结之后，我转出的资金还有机会拦截追回，避免全部损失吗？','zhàng hù dòng jié zhī hòu， wǒ zhuǎn chū de zī jīn hái yǒu jī huì lán jié zhuī huí， bì miǎn quán bù sǔn shī ma？','Sau khi phong tỏa tài khoản thì số tiền tôi chuyển ra có cơ hội được chặn lại thu hồi, tránh bị mất trắng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',6,'冻结对方账户可以锁住未被转出的资金，后续需要你到辖区派出所完成报案笔录留存证据。','dòng jié duì fāng zhàng hù kě yǐ suǒ zhù wèi bèi zhuǎn chū de zī jīn， hòu xù xū yào nǐ dào xiá qū pài chū suǒ wán chéng bào àn bǐ lù liú cún zhèng jù。','Phong tỏa tài khoản đối phương thì khóa được phần tiền chưa bị chuyển đi tiếp, sau đó anh cần đến đồn công an nơi cư trú làm biên bản báo án để lưu bằng chứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',7,'请问报案的派出所地址在哪里，办理笔录需要携带什么证件？','qǐng wèn bào àn de pài chū suǒ dì zhǐ zài nǎ lǐ， bàn lǐ bǐ lù xū yào xié dài shén me zhèng jiàn？','Cho hỏi đồn công an để báo án ở đâu ạ, làm biên bản cần mang theo giấy tờ gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_08','V375','反诈客服',8,'携带本人护照前往就近辖区派出所，工作人员会同步对接反诈中心留存线索。','xié dài běn rén hù zhào qián wǎng jiù jìn xiá qū pài chū suǒ， gōng zuò rén yuán huì tóng bù duì jiē fǎn zhà zhōng xīn liú cún xiàn suǒ。','Anh mang hộ chiếu của mình đến đồn công an gần nhất, nhân viên sẽ đồng thời kết nối với trung tâm chống lừa đảo để lưu manh mối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_09','V375','阮明',9,'笔录做完提交线索，警方会持续跟进追查诈骗账户吗？','bǐ lù zuò wán tí jiāo xiàn suǒ， jǐng fāng huì chí xù gēn jìn zhuī chá zhà piàn zhàng hù ma？','Làm biên bản xong nộp manh mối rồi, công an có tiếp tục truy tìm tài khoản lừa đảo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_10','V375','反诈客服',10,'警方会登记全部涉案线索，持续追踪资金流向，尽力挽回群众损失。','jǐng fāng huì dēng jì quán bù shè àn xiàn suǒ， chí xù zhuī zōng zī jīn liú xiàng， jìn lì wǎn huí qún zhòng sǔn shī。','Công an sẽ ghi nhận toàn bộ manh mối liên quan, tiếp tục truy vết dòng tiền, cố gắng hết sức thu hồi thiệt hại cho người dân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_11','V375','阮明',11,'我现在记下派出所地址，立刻动身前往线下登记报案。','wǒ xiàn zài jì xià pài chū suǒ dì zhǐ， lì kè dòng shēn qián wǎng xiàn xià dēng jì bào àn。','Giờ tôi ghi lại địa chỉ đồn công an, lên đường đến đăng ký báo án trực tiếp ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_12','V375','反诈客服',12,'路上保管好转账截图、聊天记录等全部证据，不要删除。','lù shàng bǎo guǎn hǎo zhuǎn zhàng jié tú、 liáo tiān jì lù děng quán bù zhèng jù， bú yào shān chú。','Trên đường đi nhớ giữ kỹ ảnh chụp chuyển khoản, lịch sử trò chuyện và mọi bằng chứng khác, đừng xóa đi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_13','V375','阮明',13,'所有聊天、转账记录我都完整保存，不会丢失。','suǒ yǒu liáo tiān、 zhuǎn zhàng jì lù wǒ dōu wán zhěng bǎo cún， bú huì diū shī。','Toàn bộ tin nhắn, lịch sử chuyển khoản tôi đều lưu đầy đủ, sẽ không bị mất đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_14','V375','反诈客服',14,'后续案件进展派出所会同步通知你。','hòu xù àn jiàn jìn zhǎn pài chū suǒ huì tóng bù tōng zhī nǐ。','Tiến triển vụ việc sau này đồn công an sẽ thông báo cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_15','V375','阮明',15,'感谢紧急冻结对方账户，降低我的财产损失！','gǎn xiè jǐn jí dòng jié duì fāng zhàng hù， jiàng dī wǒ de cái chǎn sǔn shī！','Cảm ơn chị đã phong tỏa tài khoản đối phương kịp thời, giảm bớt thiệt hại tài sản cho tôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为撬动、暴力损坏门锁，则需自行支付配件与工时费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'物业您好，我租住公寓的入户门锁出现故障，钥匙插入锁孔完全转动不开，无法进门。','wù yè nín hǎo， wǒ zū zhù gōng yù de rù hù mén suǒ chū xiàn gù zhàng， yào shi chā rù suǒ kǒng wán quán zhuǎn dòng bù kāi， wú fǎ jìn mén。','Chào ban quản lý, khóa cửa căn hộ tôi thuê bị hỏng, tra chìa vào ổ khóa không xoay được, không vào phòng được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'先跟我确认，你尝试转动钥匙的时候，有没有暴力掰扯、大力敲击门锁？','xiān gēn wǒ què rèn， nǐ cháng shì zhuǎn dòng yào shi de shí hòu， yǒu méi yǒu bào lì bāi chě、 dà lì qiāo jī mén suǒ？','Anh xác nhận giúp tôi, lúc anh xoay chìa khóa có bẻ mạnh hay đập mạnh vào ổ khóa không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'我只是平稳插入钥匙左右轻转，没有用力掰动锁芯，不存在人为破坏的情况。','wǒ zhǐ shì píng wěn chā rù yào shi zuǒ yòu qīng zhuǎn， méi yǒu yòng lì bāi dòng suǒ xīn， bù cún zài rén wéi pò huài de qíng kuàng。','Tôi chỉ tra chìa vào nhẹ nhàng rồi xoay hai bên thôi, không hề dùng lực bẻ lõi khóa, không có chuyện tôi làm hỏng đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'你先到楼下单元门禁处等候，我携带全套维修工具，十分钟之内抵达楼栋哦。','nǐ xiān dào lóu xià dān yuán mén jìn chù děng hòu， wǒ xié dài quán tào wéi xiū gōng jù， shí fēn zhōng zhī nèi dǐ dá lóu dòng ó。','Anh xuống chỗ cửa an ninh của tòa nhà đợi nhé, tôi mang đầy đủ dụng cụ sửa chữa, trong vòng mười phút sẽ tới nơi.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'锁芯内部完全卡死，我尝试家里三把备用钥匙，全部都没办法转动开门呢。','suǒ xīn nèi bù wán quán kǎ sǐ， wǒ cháng shì jiā lǐ sān bǎ bèi yòng yào shi， quán bù dōu méi bàn fǎ zhuǎn dòng kāi mén ne。','Lõi khóa bị kẹt cứng hoàn toàn bên trong, tôi thử cả ba chìa dự phòng ở nhà rồi, không cái nào xoay mở được cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'大概率是锁芯内部金属零件老化断裂，这种自然老化故障需要直接更换整套门锁。','dà gài lǜ shì suǒ xīn nèi bù jīn shǔ líng jiàn lǎo huà duàn liè， zhè zhǒng zì rán lǎo huà gù zhàng xū yào zhí jiē gēng huàn zhěng tào mén suǒ。','Nhiều khả năng là bộ phận kim loại bên trong lõi khóa bị lão hóa gãy rồi, hỏng do lão hóa tự nhiên kiểu này thì phải thay nguyên bộ khóa mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'更换整套门锁产生的配件费、人工费，是由我租房住户自行承担吗？','gēng huàn zhěng tào mén suǒ chǎn shēng de pèi jiàn fèi、 rén gōng fèi， shì yóu wǒ zū fáng zhù hù zì xíng chéng dān ma？','Chi phí phụ kiện và tiền công thay nguyên bộ khóa, có phải người thuê như tôi tự chịu không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_08','V376','维修专员',8,'区分损坏原因，房屋设施自然老化损坏由物业全额免费上门维修；租客人为损坏才需要自费支付配件工时费。','qū fēn sǔn huài yuán yīn， fáng wū shè shī zì rán lǎo huà sǔn huài yóu wù yè quán é miǎn fèi shàng mén wéi xiū； zū kè rén wéi sǔn huài cái xū yào zì fèi zhī fù pèi jiàn gōng shí fèi。','Còn tùy nguyên nhân hư hỏng, nếu do thiết bị nhà tự lão hóa thì bên quản lý sẽ đến sửa miễn phí hoàn toàn; chỉ khi khách thuê làm hỏng thì mới phải tự trả tiền phụ kiện với công thợ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_09','V376','阮明',9,'全程轻柔试钥匙，没有磕碰、撬动门锁，属于自然老化故障对吧？','quán chéng qīng róu shì yào shi， méi yǒu kē pèng、 qiào dòng mén suǒ， shǔ yú zì rán lǎo huà gù zhàng duì ba？','Suốt lúc thử chìa tôi làm rất nhẹ nhàng, không va đập, không cạy phá gì cả, vậy là thuộc trường hợp lão hóa tự nhiên đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_10','V376','维修专员',10,'抵达现场查看锁体磨损情况后判定，自然老化无需你支付任何费用。','dǐ dá xiàn chǎng chá kàn suǒ tǐ mó sǔn qíng kuàng hòu pàn dìng， zì rán lǎo huà wú xū nǐ zhī fù rèn hé fèi yòng。','Để tôi đến xem tình trạng mài mòn của khóa rồi mới xác định được, nếu đúng là lão hóa tự nhiên thì anh không phải trả đồng nào cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_11','V376','阮明',11,'我在楼下门禁处安静等候，麻烦您尽快过来检修门锁。','wǒ zài lóu xià mén jìn chù ān jìng děng hòu， má fán nín jǐn kuài guò lái jiǎn xiū mén suǒ。','Tôi đang đợi yên ở chỗ cửa an ninh dưới nhà, phiền anh qua kiểm tra sửa khóa sớm giúp tôi với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_12','V376','维修专员',12,'马上出发，到楼下我给你打电话。','mǎ shàng chū fā， dào lóu xià wǒ gěi nǐ dǎ diàn huà。','Tôi xuất phát ngay đây, xuống tới nơi tôi gọi điện cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_13','V376','阮明',13,'辛苦专员专程上门处理故障，耽误您工作时间实在不好意思。','xīn kǔ zhuān yuán zhuān chéng shàng mén chǔ lǐ gù zhàng， dān wù nín gōng zuò shí jiān shí zài bù hǎo yì sī。','Cảm ơn anh vất vả đến tận nơi xử lý sự cố, làm phiền thời gian làm việc của anh thật ngại quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_14','V376','维修专员',14,'房屋维修是物业本职工作，不用客气。','fáng wū wéi xiū shì wù yè běn zhí gōng zuò， bù yòng kè qì。','Sửa chữa nhà cửa là công việc của bên quản lý mà, anh đừng khách sáo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_15','V376','阮明',15,'十分感谢，我在这里等您！','shí fēn gǎn xiè， wǒ zài zhè lǐ děng nín！','Cảm ơn anh nhiều lắm, tôi đợi anh ở đây nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照；现场自助拍照符合涉外证件标准，无需提前线下照相馆拍摄。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，本人越南护照不慎遗失，前来大厅申请临时出入境通行证明。','nín hǎo， běn rén yuè nán hù zhào bù shèn yí shī， qián lái dà tīng shēn qǐng lín shí chū rù jìng tōng xíng zhèng míng。','Xin chào, tôi làm mất hộ chiếu Việt Nam nên đến quầy xin cấp giấy thông hành xuất nhập cảnh tạm thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'办理临时通行证明需要两份核心材料，派出所开具的遗失报案回执、标准一寸白底证件照片吧。','bàn lǐ lín shí tōng xíng zhèng míng xū yào liǎng fèn hé xīn cái liào， pài chū suǒ kāi jù de yí shī bào àn huí zhí、 biāo zhǔn yī cùn bái dǐ zhèng jiàn zhào piān ba。','Làm giấy thông hành tạm thời cần hai loại giấy tờ chính: biên nhận trình báo mất do công an phường cấp, và ảnh thẻ chuẩn nền trắng cỡ một tấc ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'派出所出具的遗失回执我已经随身携带，但是出门匆忙，没有提前准备一寸白底证件照嘛。','pài chū suǒ chū jù de yí shī huí zhí wǒ yǐ jīng suí shēn xié dài， dàn shì chū mén cōng máng， méi yǒu tí qián zhǔn bèi yī cùn bái dǐ zhèng jiàn zhào ma。','Biên nhận trình báo mất của công an tôi mang theo rồi, nhưng vì ra ngoài vội quá nên chưa chuẩn bị sẵn ảnh nền trắng cỡ một tấc ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',4,'大厅大厅入口设有自助拍照机，专门办理涉外证件拍摄，一套照片收费二十元。','dà tīng dà tīng rù kǒu shè yǒu zì zhù pāi zhào jī， zhuān mén bàn lǐ shè wài zhèng jiàn pāi shè， yī tào zhào piān shōu fèi èr shí yuán。','Ở lối vào sảnh có máy chụp ảnh tự động, chuyên chụp ảnh dùng cho giấy tờ liên quan đến người nước ngoài, một bộ ảnh giá hai mươi tệ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',5,'现场拍摄完证件照片，当天递交全部材料就能直接拿到临时通行证件吗？','xiàn chǎng pāi shè wán zhèng jiàn zhào piān， dàng tiān dì jiāo quán bù cái liào jiù néng zhí jiē ná dào lín shí tōng xíng zhèng jiàn ma？','Chụp ảnh xong tại chỗ, nộp đủ hồ sơ trong ngày là có thể nhận giấy thông hành tạm thời luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',6,'只要回执、照片、护照信息全部材料齐全，窗口当场办结出证，无需等候。','zhǐ yào huí zhí、 zhào piān、 hù zhào xìn xī quán bù cái liào qí quán， chuāng kǒu dāng chǎng bàn jié chū zhèng， wú xū děng hòu。','Chỉ cần đủ biên nhận, ảnh, thông tin hộ chiếu là đủ hồ sơ, quầy sẽ giải quyết xong ngay tại chỗ, không phải chờ đợi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',7,'这份临时通行证明有效期多长时间，能用来回国补办正式护照吗？','zhè fèn lín shí tōng xíng zhèng míng yǒu xiào qī duō zhǎng shí jiān， néng yòng lái huí guó bǔ bàn zhèng shì hù zhào ma？','Giấy thông hành tạm thời này có thời hạn bao lâu, có dùng để về nước làm lại hộ chiếu chính thức được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_08','V377','工作人员',8,'临时证明有效期三十天，可用于搭乘国际航班出境，也能前往驻华大使馆补办护照。','lín shí zhèng míng yǒu xiào qī sān shí tiān， kě yòng yú dā chéng guó jì háng bān chū jìng， yě néng qián wǎng zhù huá dà shǐ guǎn bǔ bàn hù zhào。','Giấy tạm thời có hiệu lực ba mươi ngày, có thể dùng để lên chuyến bay quốc tế xuất cảnh, cũng có thể đến đại sứ quán tại Trung Quốc để làm lại hộ chiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_09','V377','阮明',9,'那我先去自助拍照机拍摄证件照，拍完立刻返回窗口提交全部材料。','nà wǒ xiān qù zì zhù pāi zhào jī pāi shè zhèng jiàn zhào， pāi wán lì kè fǎn huí chuāng kǒu tí jiāo quán bù cái liào。','Vậy tôi đi chụp ảnh ở máy tự động trước, chụp xong sẽ quay lại quầy nộp đủ hồ sơ ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_10','V377','工作人员',10,'拍照后记得核对人像清晰度，不合格需要重新拍摄。','pāi zhào hòu jì de hé duì rén xiàng qīng xī dù， bù hé gé xū yào chóng xīn pāi shè。','Chụp xong nhớ kiểm tra lại độ rõ nét của ảnh, nếu không đạt thì phải chụp lại đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_11','V377','阮明',11,'我会仔细检查照片标准，不耽误窗口办理流程。','wǒ huì zǐ xì jiǎn chá zhào piàn biāo zhǔn， bù dān wù chuāng kǒu bàn lǐ liú chéng。','Tôi sẽ kiểm tra kỹ tiêu chuẩn ảnh, không để chậm trễ quy trình xử lý ở quầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_12','V377','工作人员',12,'拍完直接到三号窗口递交材料即可。','pāi wán zhí jiē dào sān hào chuāng kǒu dì jiāo cái liào jí kě。','Chụp xong thì đến thẳng quầy số ba nộp hồ sơ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_13','V377','阮明',13,'感谢工作人员清晰告知全部办理步骤！','gǎn xiè gōng zuò rén yuán qīng xī gào zhī quán bù bàn lǐ bù zhòu！','Cảm ơn anh chị đã hướng dẫn rõ ràng đầy đủ các bước làm thủ tục!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助，包含对接家属、证件补办、事故手续协调等服务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好，我是在华就读的越南留学生，途中遭遇严重交通事故，紧急寻求使馆协助。','nín hǎo， wǒ shì zài huá jiù dú de yuè nán liú xué shēng， tú zhōng zāo yù yán zhòng jiāo tōng shì gù， jǐn jí xún qiú shǐ guǎn xié zhù。','Xin chào, tôi là du học sinh Việt Nam đang học tại Trung Quốc, trên đường đi gặp phải tai nạn giao thông nghiêm trọng, khẩn cấp cần đại sứ quán hỗ trợ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'请你先保持冷静，逐条告知我你的完整姓名、就读院校、事故精确详细地点呢。','qǐng nǐ xiān bǎo chí lěng jìng， zhú tiáo gào zhī wǒ nǐ de wán zhěng xìng míng、 jiù dú yuàn xiào、 shì gù jīng què xiáng xì dì diǎn ne。','Bạn giữ bình tĩnh trước đã nhé, cho tôi biết lần lượt họ tên đầy đủ, trường đang theo học, và địa điểm xảy ra tai nạn chính xác nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我叫阮明，本市高校汉语言专业留学生，事故发生在市中心主干道十字路口，交警与救护车已经抵达现场处置。','wǒ jiào ruǎn míng， běn shì gāo xiào hàn yǔ yán zhuān yè liú xué shēng， shì gù fā shēng zài shì zhōng xīn zhǔ gàn dào shí zì lù kǒu， jiāo jǐng yǔ jiù hù chē yǐ jīng dǐ dá xiàn chǎng chǔ zhì。','Tôi tên Nguyễn Minh, du học sinh ngành Hán ngữ tại một trường đại học trong thành phố này, tai nạn xảy ra ở ngã tư đường chính trung tâm thành phố, cảnh sát giao thông và xe cứu thương đã có mặt xử lý rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'我们会第一时间同步联系当地辖区交警大队跟进本次事故完整处置流程，后续协助处理各类手续。','wǒ men huì dì yī shí jiān tóng bù lián xì dāng dì xiá qū jiāo jǐng dà duì gēn jìn běn cì shì gù wán zhěng chǔ zhì liú chéng， hòu xù xié zhù chǔ lǐ gè lèi shǒu xù。','Chúng tôi sẽ liên hệ ngay với đội cảnh sát giao thông khu vực để theo sát toàn bộ quá trình xử lý vụ việc này, sau đó sẽ hỗ trợ bạn làm các thủ tục liên quan.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'后续治疗、证件补办、对接国内家属等全部相关事宜，都能寻求大使馆提供领事协助吧？','hòu xù zhì liáo、 zhèng jiàn bǔ bàn、 duì jiē guó nèi jiā shǔ děng quán bù xiāng guān shì yí， dōu néng xún qiú dà shǐ guǎn tí gōng lǐng shì xié zhù ba？','Những việc sau này như điều trị, làm lại giấy tờ, liên lạc với gia đình ở trong nước, đều có thể nhờ đại sứ quán hỗ trợ lãnh sự đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'是的，所有境外公民在中国遭遇重大人身意外，本国驻华大使馆均会提供全套领事协助服务。','shì de， suǒ yǒu jìng wài gōng mín zài zhōng guó zāo yù zhòng dà rén shēn yì wài， běn guó zhù huá dà shǐ guǎn jūn huì tí gōng quán tào lǐng shì xié zhù fú wù。','Đúng vậy, bất kỳ công dân nước ngoài nào gặp sự cố nghiêm trọng về người tại Trung Quốc, đại sứ quán nước sở tại đều sẽ cung cấp đầy đủ dịch vụ hỗ trợ lãnh sự.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'现在伤者正在接受医护检查，暂时无法确认伤情轻重，有新情况我会再次致电汇报。','xiàn zài shāng zhě zhèng zài jiē shòu yī hù jiǎn chá， zàn shí wú fǎ què rèn shāng qíng qīng zhòng， yǒu xīn qíng kuàng wǒ huì zài cì zhì diàn huì bào。','Hiện tại người bị thương đang được bác sĩ kiểm tra, tạm thời chưa xác định được mức độ nặng nhẹ, có tình hình mới tôi sẽ gọi lại báo cáo ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_08','V378','接线员',8,'记下这条官方联系热线，后续任何手续难题随时来电咨询。','jì xià zhè tiáo guān fāng lián xì rè xiàn， hòu xù rèn hé shǒu xù nán tí suí shí lái diàn zī xún。','Bạn ghi lại số đường dây nóng chính thức này, sau này có vướng mắc thủ tục gì cứ gọi điện hỏi bất cứ lúc nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_09','V378','阮明',9,'我会保存热线号码，有需要第一时间联系使馆工作人员。','wǒ huì bǎo cún rè xiàn hào mǎ， yǒu xū yào dì yī shí jiān lián xì shǐ guǎn gōng zuò rén yuán。','Tôi sẽ lưu lại số đường dây nóng, cần gì sẽ liên hệ ngay với nhân viên đại sứ quán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_10','V378','接线员',10,'祝你平安，有进展及时沟通。','zhù nǐ píng ān， yǒu jìn zhǎn jí shí gōu tōng。','Chúc bạn bình an, có tiến triển gì thì báo lại kịp thời nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_11','V378','阮明',11,'太感谢使馆提供应急协助，缓解我的慌乱。','tài gǎn xiè shǐ guǎn tí gōng yìng jí xié zhù， huǎn jiě wǒ de huāng luàn。','Cảm ơn đại sứ quán rất nhiều vì đã hỗ trợ khẩn cấp, giúp tôi bớt hoảng loạn hẳn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê ơi, tớ muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian, mà không biết trình bày sao cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','Chia làm ba phần thông tin cơ bản, năng lực ngôn ngữ, kinh nghiệm thực tế là được rồi đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm phần visa với giấy phép làm thêm hợp pháp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Nhất định phải viết vào, nhiều chỗ tuyển dụng không rõ quy định làm thêm của du học sinh lắm đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Tớ viết xong một bản nháp rồi, mà phần kinh nghiệm thực tế viết sơ sài quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho tớ, tớ giúp cậu sửa với bổ sung chi tiết cho.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn cậu nhiều lắm, sửa xong là tớ nộp hồ sơ luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào quản lý, em là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Trung thiếu nhi bán thời gian.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, em giới thiệu sơ qua trình độ ngôn ngữ và thời gian rảnh của mình nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Em giao tiếp tiếng Trung hàng ngày khá lưu loát, buổi tối các ngày trong tuần và cả ngày cuối tuần em đều rảnh ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Em có kinh nghiệm gì trong việc tiếp xúc với trẻ nhỏ không, có giỏi tương tác trên lớp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây em từng dẫn dắt các bạn nhỏ trong hoạt động ở trường, em rất thích giao tiếp với trẻ con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Nhìn chung điều kiện của em phù hợp với yêu cầu công việc, trong ba ngày sẽ báo kết quả nhận việc cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Cảm ơn quản lý đã cho em cơ hội phỏng vấn, em sẽ kiên nhẫn chờ tin ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào chị, hợp đồng lao động tạm thời này tôi xem kỹ rồi, có một chỗ muốn xác nhận lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Anh có thắc mắc điều khoản nào thì cứ nói thẳng ra nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi ngày hai mươi hàng tháng trả lương, nhưng không nêu rõ mức phụ cấp làm thêm giờ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Chi tiết lương làm thêm giờ được đính kèm ở trang bổ sung của hợp đồng, để tôi lấy cho anh xem lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký điều khoản bổ sung, hai bên mỗi bên giữ một bản hợp đồng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng vậy, một bản cửa hàng lưu, một bản do anh tự giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi hiểu rõ hết các điều khoản rồi, giờ tôi ký xác nhận.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资；学生备考类请假大多可以协调同事顶替，无需自行补工时。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，有一件事提前跟您沟通，下周三我无法到门店上班。','diàn zhǎng nín hǎo， yǒu yī jiàn shì tí qián gēn nín gōu tōng， xià zhōu sān wǒ wú fǎ dào mén diàn shàng bān。','Chào cửa hàng trưởng, có việc này em muốn báo trước với anh, thứ Tư tuần sau em không thể đến cửa hàng làm việc được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'你先说说是什么原因，门店排班需要提前协调人员顶替岗位吧。','nǐ xiān shuō shuō shì shén me yuán yīn， mén diàn pái bān xū yào tí qián xié tiáo rén yuán dǐng tì gǎng wèi ba。','Em cứ nói lý do xem sao, lịch làm việc của cửa hàng cần sắp xếp người thay ca trước đấy.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'下周三全天进行汉语专业期末考试，从上午八点考到下午五点，全天都无法到岗，实在抱歉呢。','xià zhōu sān quán tiān jìn xíng hàn yǔ zhuān yè qī mò kǎo shì， cóng shàng wǔ bā diǎn kǎo dào xià wǔ wǔ diǎn， quán tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Thứ Tư tuần sau em thi cuối kỳ môn chuyên ngành tiếng Trung cả ngày, từ tám giờ sáng đến năm giờ chiều, cả ngày không thể đi làm được, thật xin lỗi anh ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'学生学业优先是理所应当的，你提前一周告知，我有充足时间调整整体排班。','xué shēng xué yè yōu xiān shì lǐ suǒ yīng dāng de， nǐ tí qián yī zhōu gào zhī， wǒ yǒu chōng zú shí jiān tiáo zhěng zhěng tǐ pái bān。','Việc học của sinh viên phải ưu tiên trước là đúng rồi, em báo trước một tuần thì anh có đủ thời gian điều chỉnh lịch làm chung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'我担心缺一天班次，月度工时达不到门店规定标准，影响当月薪资发放。','wǒ dān xīn quē yī tiān bān cì， yuè dù gōng shí dá bú dào mén diàn guī dìng biāo zhǔn， yǐng xiǎng dàng yuè xīn zī fā fàng。','Em lo là nghỉ một ngày ca thì số giờ công trong tháng không đủ theo quy định của cửa hàng, ảnh hưởng đến lương tháng này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'我会安排其他空闲同事顶替你的全天班次，不用有心理负担。','wǒ huì ān pái qí tā kòng xián tóng shì dǐng tì nǐ de quán tiān bān cì， bù yòng yǒu xīn lǐ fù dān。','Anh sẽ sắp xếp đồng nghiệp khác rảnh thay ca cả ngày cho em, em không cần lo lắng gì đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'考完试之后，我可以主动多上两天晚班，补上本次缺失的工时。','kǎo wán shì zhī hòu， wǒ kě yǐ zhǔ dòng duō shàng liǎng tiān wǎn bān， bǔ shàng běn cì quē shī de gōng shí。','Thi xong em có thể chủ động làm thêm hai ca tối để bù lại giờ công lần này thiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_08','V382','店长',8,'不用刻意额外加班补工时，你后续正常出勤就满足月度最低工时要求。','bù yòng kè yì é wài jiā bān bǔ gōng shí， nǐ hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù zuì dī gōng shí yāo qiú。','Không cần cố tình làm thêm để bù giờ công đâu, sau này em đi làm bình thường là đủ giờ công tối thiểu trong tháng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_09','V382','阮明',9,'太感谢店长体谅学生备考，我会提前一天完成手头所有工作交接。','tài gǎn xiè diàn zhǎng tǐ liàng xué shēng bèi kǎo， wǒ huì tí qián yī tiān wán chéng shǒu tóu suǒ yǒu gōng zuò jiāo jiē。','Cảm ơn anh nhiều lắm vì đã thông cảm cho việc thi cử của em, em sẽ bàn giao xong hết công việc trước một ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_10','V382','店长',10,'交接不用复杂，把当日需要整理的货品清单留在收银台就行。','jiāo jiē bù yòng fù zá， bǎ dāng rì xū yào zhěng lǐ de huò pǐn qīng dān liú zài shōu yín tái jiù xíng。','Bàn giao không cần phức tạp đâu, cứ để danh sách hàng hóa cần sắp xếp trong ngày ở quầy thu ngân là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_11','V382','阮明',11,'考试结束后我会第一时间回门店正常上班，不耽误后续排班。','kǎo shì jié shù hòu wǒ huì dì yī shí jiān huí mén diàn zhèng cháng shàng bān， bù dān wù hòu xù pái bān。','Thi xong em sẽ quay lại cửa hàng đi làm bình thường ngay, không làm chậm trễ lịch làm sau này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_12','V382','店长',12,'专心备考，不用分心担心门店工作。','zhuān xīn bèi kǎo， bù yòng fēn xīn dān xīn mén diàn gōng zuò。','Em cứ tập trung ôn thi đi, đừng phân tâm lo chuyện cửa hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_13','V382','阮明',13,'我一定好好复习，不辜负您的包容。','wǒ yí dìng hǎo hǎo fù xí， bù gū fù nín de bāo róng。','Em nhất định sẽ ôn tập thật tốt, không phụ lòng bao dung của anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_14','V382','店长',14,'有任何考试变动提前跟我说，方便我重新调班。','yǒu rèn hé kǎo shì biàn dòng tí qián gēn wǒ shuō， fāng biàn wǒ chóng xīn diào bān。','Có thay đổi gì về lịch thi thì báo trước cho anh, để anh tiện sắp xếp lại ca.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_15','V382','阮明',15,'多谢店长体谅！','duō xiè diàn zhǎng tǐ liàng！','Cảm ơn cửa hàng trưởng đã thông cảm nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào chị, tôi muốn xác nhận mức lương theo giờ và hình thức trả lương của công việc bán thời gian này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Hai mươi hai tệ một giờ, ngày hai mươi hàng tháng chuyển khoản qua thẻ ngân hàng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ bảo hiểm xã hội hay khoản phí thủ tục nào khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không đóng bảo hiểm xã hội, lương thực nhận không bị trừ khoản nào cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_05','V383','阮明',5,'只能绑定国内银行卡接收工资对吧？','zhǐ néng bǎng dìng guó nèi yín háng kǎ jiē shōu gōng zī duì ba？','Chỉ có thể liên kết thẻ ngân hàng trong nước để nhận lương thôi đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_06','V383','人事专员',6,'是的，境外银行卡无法对接公司财务系统。','shì de， jìng wài yín háng kǎ wú fǎ duì jiē gōng sī cái wù xì tǒng。','Đúng vậy, thẻ ngân hàng nước ngoài không kết nối được với hệ thống tài chính của công ty.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_07','V383','阮明',7,'明白了，我尽快办理专用工资卡。','míng bái le， wǒ jǐn kuài bàn lǐ zhuān yòng gōng zī kǎ。','Tôi hiểu rồi, tôi sẽ làm thẻ lương chuyên dụng sớm nhất có thể.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT384','S127','Hỏi về việc đóng thuế thu nhập làm thêm',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V384','SIT384','P1','twist','chinh_thuc',NULL,'国内劳务报酬设有免税额度，用人单位统一代扣个税，完税证明可用于留学生签证续办。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_01','V384','阮明',1,'您好，留学生兼职获得的收入，需要申报个人所得税吗？','nín hǎo， liú xué shēng jiān zhí huò dé de shōu rù， xū yào shēn bào gè rén suǒ dé shuì ma？','Chào chị, cho em hỏi thu nhập từ việc làm thêm của du học sinh có cần khai thuế thu nhập cá nhân không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_02','V384','财务',2,'月度收入超过八百元，超出部分需要缴纳劳务个税哈。','yuè dù shōu rù chāo guò bā bǎi yuán， chāo chū bù fèn xū yào jiǎo nà láo wù gè shuì hā。','Thu nhập hàng tháng vượt quá tám trăm tệ thì phần vượt phải nộp thuế thu nhập lao động dịch vụ đấy.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_03','V384','阮明',3,'个税会直接从当月工资里扣除，还是我自行申报嘛？','gè shuì huì zhí jiē cóng dàng yuè gōng zī lǐ kòu chú， hái shì wǒ zì xíng shēn bào ma？','Vậy thuế sẽ được trừ thẳng vào lương tháng đó, hay em phải tự kê khai ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_04','V384','财务',4,'公司统一代扣代缴，工资条会标注扣税明细。','gōng sī tǒng yí dài kòu dài jiǎo， gōng zī tiáo huì biāo zhù kòu shuì míng xì。','Công ty sẽ khấu trừ và nộp thay thống nhất, phiếu lương sẽ ghi rõ khoản thuế bị trừ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_05','V384','阮明',5,'年末可以打印全年纳税记录用作签证材料吗？','nián mò kě yǐ dǎ yìn quán nián nà shuì jì lù yòng zuò qiān zhèng cái liào ma？','Cuối năm em có thể xin in bảng ghi nhận nộp thuế cả năm để làm hồ sơ xin visa được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_06','V384','财务',6,'可以，年末我统一打印完整纳税单据交给你。','kě yǐ， nián mò wǒ tǒng yī dǎ yìn wán zhěng nà shuì dān jù jiāo gěi nǐ。','Được, cuối năm chị sẽ in đầy đủ chứng từ nộp thuế cả năm rồi đưa cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_07','V384','阮明',7,'好，相关规则我记下来，感谢细致讲解。','hǎo， xiāng guān guī zé wǒ jì xià lái， gǎn xiè xì zhì jiǎng jiě。','Vâng, những quy định này em sẽ ghi lại, cảm ơn chị đã giải thích cặn kẽ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT385','S128','Mở tài khoản ngân hàng riêng để nhận lương',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V385','SIT385','P1','suon_se','chinh_thuc',NULL,'外籍留学生凭护照、在校证明可办理学生储蓄卡，多数银行学生账户免除年费与小额管理费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_01','V385','阮明',1,'您好，我是在校留学生，想开一张储蓄卡专门接收兼职工资。','nín hǎo， wǒ shì zài xiào liú xué shēng， xiǎng kāi yī zhāng chǔ xù kǎ zhuān mén jiē shōu jiān zhí gōng zī。','Chào anh, em là du học sinh đang theo học, em muốn mở một thẻ tiết kiệm riêng để nhận lương làm thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_02','V385','柜员',2,'请出示你的护照、在校学生证，填写开户申请单吧。','qǐng chū shì nǐ de hù zhào、 zài xiào xué shēng zhèng， tián xiě kāi hù shēn qǐng dān ba。','Em vui lòng xuất trình hộ chiếu, thẻ sinh viên đang học, rồi điền vào đơn mở tài khoản nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_03','V385','阮明',3,'这张卡只用来收工资，平时不存放大额资金可以吗？','zhè zhāng kǎ zhǐ yòng lái shōu gōng zī， píng shí bù cún fàng dà é zī jīn kě yǐ ma？','Thẻ này chỉ dùng để nhận lương thôi, em không để số tiền lớn trong đó thường xuyên thì có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_04','V385','柜员',4,'完全没问题，普通一类储蓄卡支持企业对公转账呢。','wán quán méi wèn tí， pǔ tōng yī lèi chǔ xù kǎ zhī chí qǐ yè duì gōng zhuàn zhàng ne。','Hoàn toàn không vấn đề gì, thẻ tiết kiệm loại một thông thường vẫn nhận được chuyển khoản từ doanh nghiệp mà.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_05','V385','阮明',5,'开户有没有年费、短信通知这类额外收费项目？','kāi hù yǒu méi yǒu nián fèi、 duǎn xìn tōng zhī zhè lèi é wài shōu fèi xiàng mù？','Mở tài khoản có phát sinh phí thường niên, phí báo tin nhắn hay các khoản phụ thu nào khác không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_06','V385','柜员',6,'学生账户免年费，免费开通资金变动短信提醒。','xué shēng zhàng hù miǎn nián fèi， miǎn fèi kāi tōng zī jīn biàn dòng duǎn xìn tí xǐng。','Tài khoản sinh viên được miễn phí thường niên, và được mở miễn phí dịch vụ báo biến động số dư qua tin nhắn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_07','V385','阮明',7,'好，我现在填写单据办理开户手续。','hǎo， wǒ xiàn zài tián xiě dān jù bàn lǐ kāi hù shǒu xù。','Vâng, giờ em điền hồ sơ để làm thủ tục mở tài khoản luôn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT386','S127','Xin nghỉ việc trước thời hạn hợp đồng',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V386','SIT386','P1','twist','ban_chinh_thuc',NULL,'国内临时劳务用工规范要求员工提前三十天申请离职，企业可根据门店人手、员工实际情况适度放宽离职期限；离职必须填写书面申请存档，口头离职不生效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_01','V386','阮明',1,'店长，我今天过来跟您沟通离职事宜，下学期专业课数量大幅增加。','diàn zhǎng， wǒ jīn tiān guò lái gēn nín gōu tōng lí zhí shì yí， xià xué qī zhuān yè kè shù liàng dà fú zēng jiā。','Anh quản lý ơi, hôm nay em qua trao đổi với anh về việc xin nghỉ việc, học kỳ sau số môn chuyên ngành của em tăng nhiều quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_02','V386','店长',2,'我大致了解留学生课程安排，你计划什么时候正式结束兼职工作？','wǒ dà zhì liǎo jiě liú xué shēng kè chéng ān pái， nǐ jì huà shén me shí hòu zhèng shì jié shù jiān zhí gōng zuò？','Anh cũng nắm được lịch học của du học sinh rồi, vậy em dự tính khi nào thì chính thức nghỉ làm thêm?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_03','V386','阮明',3,'原本合同约定做到学期末，我想申请提前半个月办理离职手续。','yuán běn hé tóng yuē dìng zuò dào xué qī mò， wǒ xiǎng shēn qǐng tí qián bàn gè yuè bàn lǐ lí zhí shǒu xù。','Ban đầu hợp đồng ghi làm đến hết học kỳ, giờ em muốn xin nghỉ sớm nửa tháng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_04','V386','店长',4,'门店劳务用工有统一规范，离职需要提前三十天书面提交申请，只提前半个月不符合规定嘛。','mén diàn láo wù yòng gōng yǒu tǒng yī guī fàn， lí zhí xū yào tí qián sān shí tiān shū miàn tí jiāo shēn qǐng， zhǐ tí qián bàn gè yuè bù fú hé guī dìng ma。','Cửa hàng có quy định chung về lao động thời vụ, xin nghỉ phải nộp đơn bằng văn bản trước ba mươi ngày, chỉ báo trước nửa tháng thì không đúng quy định đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_05','V386','阮明',5,'新学期课程表全部排满白天晚上，完全抽不出空余时间兼顾兼职工作。','xīn xué qī kè chéng biǎo quán bù pái mǎn bái tiān wǎn shàng， wán quán chōu bù chū kòng yú shí jiān jiān gù jiān zhí gōng zuò。','Lịch học kỳ mới của em kín cả ngày lẫn tối, thật sự không thể sắp xếp thời gian để làm thêm được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_06','V386','店长',6,'我能理解留学生课业压力大，直接按三十天标准离职时间执行对你压力太大。','wǒ néng lǐ jiě liú xué shēng kè yè yā lì dà， zhí jiē àn sān shí tiān biāo zhǔn lí zhí shí jiān zhí xíng duì nǐ yā lì tài dà。','Anh hiểu áp lực học tập của du học sinh là lớn, nhưng bắt em làm đúng theo tiêu chuẩn ba mươi ngày thì cũng khá căng cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_07','V386','阮明',7,'我这段时间可以全力做好客户对接、货品盘点等全部工作交接。','wǒ zhè duàn shí jiān kě yǐ quán lì zuò hào kè hù duì jiē、 huò pǐn pán diǎn děng quán bù gōng zuò jiāo jiē。','Thời gian này em có thể dồn sức làm tốt việc bàn giao, từ chăm sóc khách hàng đến kiểm kê hàng hóa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_08','V386','店长',8,'结合门店近期人手充足的现状，我向上级人事申请，最多协调缩短到二十天离职周期。','jié hé mén diàn jìn qī rén shǒu chōng zú de xiàn zhuàng， wǒ xiàng shàng jí rén shì shēn qǐng， zuì duō xié tiáo suō duǎn dào èr shí tiān lí zhí zhōu qī。','Xét tình hình cửa hàng dạo này cũng đủ người, anh sẽ xin ý kiến cấp trên bên nhân sự, cố gắng rút ngắn xuống hai mươi ngày cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_09','V386','阮明',9,'二十天的周期我完全可以接受，这段时间我逐项梳理所有工作内容做好交接。','èr shí tiān de zhōu qī wǒ wán quán kě yǐ jiē shòu， zhè duàn shí jiān wǒ zhú xiàng shū lǐ suǒ yǒu gōng zuò nèi róng zuò hǎo jiāo jiē。','Hai mươi ngày thì em hoàn toàn chấp nhận được, thời gian đó em sẽ rà soát từng phần công việc để bàn giao cho đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_10','V386','店长',10,'今天填写纸质离职申请表，我签字之后统一交给人事部门存档备案。','jīn tiān tián xiě zhǐ zhì lí zhí shēn qǐng biǎo， wǒ qiān zì zhī hòu tǒng yī jiāo gěi rén shì bù mén cún dàng bèi àn。','Hôm nay em điền đơn xin nghỉ bản giấy, anh ký xong sẽ chuyển thống nhất cho phòng nhân sự lưu hồ sơ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_11','V386','阮明',11,'交接清单我每天整理一部分，离职当天完整交给接替岗位的同事。','jiāo jiē qīng dān wǒ měi tiān zhěng lǐ yī bù fèn， lí zhí dàng tiān wán zhěng jiāo gěi jiē tì gǎng wèi de tóng shì。','Danh sách bàn giao em sẽ hoàn thiện dần mỗi ngày, đến ngày nghỉ chính thức sẽ giao đầy đủ cho người tiếp nhận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_12','V386','店长',12,'交接过程中有不清楚的地方随时来办公室找我沟通。','jiāo jiē guò chéng zhōng yǒu bù qīng chǔ de dì fāng suí shí lái bàn gōng shì zhǎo wǒ gōu tōng。','Trong quá trình bàn giao có chỗ nào chưa rõ thì cứ lên văn phòng tìm anh trao đổi bất cứ lúc nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_13','V386','阮明',13,'麻烦店长帮忙审批这份离职申请，这段时间也多谢门店所有人照顾我。','má fán diàn zhǎng bāng máng shěn pī zhè fèn lí zhí shēn qǐng， zhè duàn shí jiān yě duō xiè mén diàn suǒ yǒu rén zhào gù wǒ。','Phiền anh giúp em duyệt đơn xin nghỉ này, thời gian qua cũng cảm ơn mọi người trong cửa hàng đã giúp đỡ em nhiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_14','V386','店长',14,'没事，学业为重，后续有空闲假期也欢迎再来短期兼职。','méi shì， xué yè wèi zhòng， hòu xù yǒu kòng xián jià qī yě huān yíng zài lái duǎn qī jiān zhí。','Không sao đâu, việc học vẫn là quan trọng nhất, sau này có kỳ nghỉ rảnh rỗi thì cứ quay lại làm thêm thời vụ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_15','V386','阮明',15,'十分感谢您通融调整离职周期！','shí fēn gǎn xiè nín tōng róng tiáo zhěng lí zhí zhōu qī！','Em cảm ơn anh rất nhiều vì đã linh động điều chỉnh thời gian nghỉ cho em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT387','S127','Hỏi quy định giờ làm tối đa cho sinh viên quốc tế',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V387','SIT387','P1','suon_se','chinh_thuc',NULL,'中国法律明确规定外籍留学生务工时长，超时务工将影响签证续签，学校会定期核查兼职情况。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_01','V387','阮明',1,'老师您好，我想咨询留学生校内、校外兼职时长限制。','lǎo shī nín hǎo， wǒ xiǎng zī xún liú xué shēng xiào nèi、 xiào wài jiān zhí shí cháng xiàn zhì。','Chào thầy/cô, em muốn hỏi về giới hạn thời gian làm thêm trong và ngoài trường của du học sinh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_02','V387','国际处老师',2,'学期内每周打工总时长不能超过二十小时哦。','xué qī nèi měi zhōu dǎ gōng zǒng shí cháng bù néng chāo guò èr shí xiǎo shí ó。','Trong học kỳ, tổng thời gian làm thêm mỗi tuần không được vượt quá hai mươi giờ đâu.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_03','V387','阮明',3,'寒暑假期间，时长限制会适当放宽一些吗？','hán shǔ jià qī jiān， shí cháng xiàn zhì huì shì dàng fàng kuān yī xiē ma？','Vậy vào kỳ nghỉ hè, nghỉ đông thì giới hạn thời gian có được nới lỏng hơn một chút không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_04','V387','国际处老师',4,'假期每周最多四十小时，超出属于违规务工呢。','jià qī měi zhōu zuì duō sì shí xiǎo shí， chāo chū shǔ yú wéi guī wù gōng ne。','Vào kỳ nghỉ tối đa là bốn mươi giờ mỗi tuần, vượt quá là làm thêm trái quy định đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_05','V387','阮明',5,'超时打工会不会影响我的签证续办审核？','chāo shí dǎ gōng huì bú huì yǐng xiǎng wǒ de qiān zhèng xù bàn shěn hé？','Làm thêm quá giờ có ảnh hưởng đến việc xét gia hạn visa của em không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_06','V387','国际处老师',6,'会有影响，出入境管理局会核查务工时长记录。','huì yǒu yǐng xiǎng， chū rù jìng guǎn lǐ jú huì hé chá wù gōng shí cháng jì lù。','Có ảnh hưởng chứ, cục quản lý xuất nhập cảnh sẽ kiểm tra hồ sơ thời gian làm thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_07','V387','阮明',7,'我清楚规定了，一定会严格控制上班时长。','wǒ qīng chǔ guī dìng le， yí dìng huì yán gé kòng zhì shàng bān shí cháng。','Em hiểu quy định rồi ạ, em nhất định sẽ kiểm soát chặt thời gian làm việc của mình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT388','S127','Trao đổi ca làm việc với đồng nghiệp',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V388','SIT388','P1','twist','tuy_y',NULL,'兼职员工私下换班必须告知主管登记，避免岗位无人值守，产生运营问题。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_01','V388','阮明',1,'小秦，我周四下午有汉语测验，能和你互换班次吗？','xiǎo qín， wǒ zhōu sì xià wǔ yǒu hàn yǔ cè yàn， néng hé nǐ hù huàn bān cì ma？','Tiểu Tần ơi, thứ Năm chiều tớ có bài kiểm tra tiếng Hán, cậu đổi ca với tớ được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_02','V388','小秦',2,'我周四全天有社团活动，那天也没办法上班嘛。','wǒ zhōu sì quán tiān yǒu shè tuán huó dòng， nà tiān yě méi bàn fǎ shàng bān ma。','Thứ Năm cả ngày tớ có hoạt động câu lạc bộ rồi, hôm đó tớ cũng không đi làm được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_03','V388','阮明',3,'原来是这样，那周五的班次你方便和我调换不？','yuán lái shì zhè yàng， nà zhōu wǔ de bān cì nǐ fāng biàn hé wǒ diào huàn bù？','À ra vậy, thế ca thứ Sáu của cậu có tiện đổi cho tớ không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_04','V388','小秦',4,'周五我空闲，我们调换之后跟店长报备一下就行。','zhōu wǔ wǒ kòng xián， wǒ men diào huàn zhī hòu gēn diàn zhǎng bào bèi yī xià jiù xíng。','Thứ Sáu tớ rảnh, đổi xong mình báo với quản lý một tiếng là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_05','V388','阮明',5,'太好了，调换班次需要填写纸质调换申请单吗？','tài hǎo le， diào huàn bān cì xū yào tián xiě zhǐ zhì diào huàn shēn qǐng dān ma？','Tuyệt quá, đổi ca thế này có cần điền đơn xin đổi bản giấy không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_06','V388','小秦',6,'不用，微信跟店长说一声登记备案就可以。','bù yòng， wēi xìn gēn diàn zhǎng shuō yī shēng dēng jì bèi àn jiù kě yǐ。','Không cần đâu, chỉ cần nhắn Wechat báo quản lý ghi nhận lại là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_07','V388','阮明',7,'太谢谢你，解决了我的难题。','tài xiè xiè nǐ， jiě jué le wǒ de nán tí。','Cảm ơn cậu nhiều lắm, gỡ giúp tớ một vấn đề đau đầu luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT389','S127','Báo cáo sự cố trong ca làm với quản lý',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V389','SIT389','P1','suon_se','ban_chinh_thuc',NULL,'服务行业工作中出现客户突发状况，员工第一时间上报主管并留存记录，是标准工作流程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_01','V389','阮明',1,'主管，刚刚上课出现突发情况，我来跟您汇报一下。','zhǔ guǎn， gāng gāng shàng kè chū xiàn tū fā qíng kuàng， wǒ lái gēn nín huì bào yī xià。','Anh quản lý ơi, vừa nãy trong buổi học xảy ra chuyện đột xuất, em xin báo cáo với anh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_02','V389','主管',2,'别着急，慢慢说，课堂上发生什么意外了吧？','bié zháo jí， màn màn shuō， kè táng shàng fā shēng shén me yì wài le ba？','Em đừng vội, cứ từ từ nói, trong lớp có chuyện gì bất ngờ xảy ra vậy?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_03','V389','阮明',3,'一名小朋友身体不舒服，家长临时赶来把孩子接走了呢。','yī míng xiǎo péng yǒu shēn tǐ bù shū fú， jiā zhǎng lín shí gǎn lái bǎ hái zi jiē zǒu le ne。','Có một bé thấy khó chịu trong người, phụ huynh đã đến đón bé về gấp rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_04','V389','主管',4,'孩子有没有出现发烧、呕吐这类严重不适症状？','hái zi yǒu méi yǒu chū xiàn fā shāo、 ǒu tù zhè lèi yán zhòng bù shì zhèng zhuàng？','Bé có biểu hiện sốt, nôn ói hay triệu chứng nào nghiêm trọng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_05','V389','阮明',5,'只是轻微头晕，休息片刻就好转，家长已经带离校区。','zhǐ shì qīng wēi tóu yūn， xiū xī piàn kè jiù hǎo zhuǎn， jiā zhǎng yǐ jīng dài lí xiào qū。','Chỉ hơi chóng mặt nhẹ thôi, nghỉ một lúc là đỡ, phụ huynh đã đưa bé rời khỏi trường rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_06','V389','主管',6,'记录好学生信息，后续跟进询问孩子身体状况。','jì lù hào xué shēng xìn xī， hòu xù gēn jìn xún wèn hái zi shēn tǐ zhuàng kuàng。','Em ghi lại thông tin của học sinh, sau đó nhớ theo dõi hỏi thăm tình hình sức khỏe của bé nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_07','V389','阮明',7,'好，我马上整理情况记录，同步发给您查看。','hǎo， wǒ mǎ shàng zhěng lǐ qíng kuàng jì lù， tóng bù fā gěi nín chá kàn。','Vâng, em sẽ tổng hợp lại tình hình ngay rồi gửi cho anh xem ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT390','S127','Xin thư giới thiệu từ nơi thực tập',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V390','SIT390','P1','twist','chinh_thuc',NULL,'企业开具实习推荐信加盖公章需行政部门审核，私人手写无公章的推荐信不具备官方证明效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_01','V390','阮明',1,'领导您好，我的实习周期即将结束，想申请一份实习推荐信。','lǐng dǎo nín hǎo， wǒ de shí xí zhōu qī jí jiāng jié shù， xiǎng shēn qǐng yī fèn shí xí tuī jiàn xìn。','Chào anh, kỳ thực tập của em sắp kết thúc rồi, em muốn xin một thư giới thiệu thực tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_02','V390','负责人',2,'可以，推荐信用于升学还是后续求职使用呢？','kě yǐ， tuī jiàn xìn yòng yú shēng xué hái shì hòu xù qiú zhí shǐ yòng ne？','Được chứ, thư giới thiệu này em dùng để học tiếp hay để xin việc sau này vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_03','V390','阮明',3,'用于境外深造申请，需要加盖公司官方公章对吧？','yòng yú jìng wài shēn zào shēn qǐng， xū yào jiā gài gōng sī guān fāng gōng zhāng duì ba？','Em dùng để nộp hồ sơ du học nước ngoài, vậy cần đóng dấu chính thức của công ty phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_04','V390','负责人',4,'推荐信内容我可以撰写，但公章需要行政部门统一审批嘛。','tuī jiàn xìn nèi róng wǒ kě yǐ zhuàn xiě， dàn gōng zhāng xū yào xíng zhèng bù mén tǒng yī shěn pī ma。','Nội dung thư giới thiệu anh có thể soạn cho em, nhưng con dấu thì phải qua bộ phận hành chính duyệt thống nhất.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_05','V390','阮明',5,'审批流程大概需要几天，我下周就要提交申请材料。','shěn pī liú chéng dà gài xū yào jǐ tiān， wǒ xià zhōu jiù yào tí jiāo shēn qǐng cái liào。','Quy trình duyệt mất khoảng mấy ngày ạ, tuần sau em phải nộp hồ sơ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_06','V390','负责人',6,'三天内完成审批盖章，到时候我通知你来领取。','sān tiān nèi wán chéng shěn pī gài zhāng， dào shí hòu wǒ tōng zhī nǐ lái lǐng qǔ。','Trong ba ngày sẽ duyệt và đóng dấu xong, lúc đó anh sẽ báo em qua lấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_07','V390','阮明',7,'麻烦领导费心帮忙，非常感谢。','má fán lǐng dǎo fèi xīn bāng máng， fēi cháng gǎn xiè。','Phiền anh giúp đỡ em, em cảm ơn anh rất nhiều ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT391','S129','Xin cấp bảng điểm chính thức',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V391','SIT391','P1','twist','ban_chinh_thuc',NULL,'留学生用于出境、升学的成绩单必须由学校教务盖章，电子版文件不具备官方效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_01','V391','阮明',1,'老师您好，我毕业需要正式成绩单，想申请打印几份。','lǎo shī nín hǎo， wǒ bì yè xū yào zhèng shì chéng jì dān， xiǎng shēn qǐng dǎ yìn jǐ fèn。','Chào thầy/cô, em sắp tốt nghiệp nên cần bảng điểm chính thức, em muốn xin in vài bản ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_02','V391','教务老师',2,'没问题，填好这份申请表，带上你的护照原件哦。','méi wèn tí， tián hǎo zhè fèn shēn qǐng biǎo， dài shàng nǐ de hù zhào yuán jiàn ó。','Không vấn đề gì, em điền vào đơn này, nhớ mang theo hộ chiếu bản gốc nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_03','V391','阮明',3,'申请表我已经填完了，但是护照昨天拿去办签证了嘛。','shēn qǐng biǎo wǒ yǐ jīng tián wán le， dàn shì hù zhào zuó tiān ná qù bàn qiān zhèng le ma。','Đơn thì em điền xong rồi ạ, nhưng hộ chiếu hôm qua em mang đi làm visa mất rồi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_04','V391','教务老师',4,'没有证件不能办理，你改天带护照再来登记吧。','méi yǒu zhèng jiàn bù néng bàn lǐ， nǐ gǎi tiān dài hù zhào zài lái dēng jì ba。','Không có giấy tờ thì không làm được đâu, hôm khác em mang hộ chiếu qua đăng ký lại nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_05','V391','阮明',5,'那我明天一早把护照带过来，当天就能拿到成绩单吗？','nà wǒ míng tiān yī zǎo bǎ hù zhào dài guò lái， dàng tiān jiù néng ná dào chéng jì dān ma？','Vậy sáng mai em mang hộ chiếu qua sớm, ngay hôm đó em có lấy được bảng điểm luôn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_06','V391','教务老师',6,'纸质成绩单当场打印盖章，不用额外等候。','zhǐ zhì chéng jì dān dāng chǎng dǎ yìn gài zhāng， bù yòng é wài děng hòu。','Bảng điểm giấy sẽ in và đóng dấu tại chỗ luôn, không cần chờ đợi thêm gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_07','V391','阮明',7,'好，辛苦老师，我明天准时过来办理。','hǎo， xīn kǔ lǎo shī， wǒ míng tiān zhǔn shí guò lái bàn lǐ。','Vâng, cảm ơn thầy/cô đã vất vả giúp đỡ, mai em sẽ đến đúng giờ để làm ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT392','S129','Xin cấp bằng tốt nghiệp và công chứng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V392','SIT392','P1','suon_se','chinh_thuc',NULL,'外国留学生回国使用国内学历证件，必须办理涉外公证，境外机构才认可学历效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_01','V392','阮明',1,'您好，我课程全部修完，来领取毕业证并申请校内公证。','nín hǎo， wǒ kè chéng quán bù xiū wán， lái lǐng qǔ bì yè zhèng bìng shēn qǐng xiào nèi gōng zhèng。','Chào chị, em đã học xong toàn bộ chương trình, đến để nhận bằng tốt nghiệp và xin công chứng trong trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_02','V392','工作人员',2,'先核对你的全部考勤和缴费记录，没有欠费才能办理呢。','xiān hé duì nǐ de quán bù kǎo qín hé jiǎo fèi jì lù， méi yǒu qiàn fèi cái néng bàn lǐ ne。','Trước tiên chị kiểm tra lại toàn bộ hồ sơ điểm danh và học phí của em, không còn nợ gì thì mới làm được nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_03','V392','阮明',3,'学费、住宿费我都按时交清，没有任何欠费记录。','xué fèi、 zhù sù fèi wǒ dōu àn shí jiāo qīng， méi yǒu rèn hé qiàn fèi jì lù。','Học phí, tiền ký túc xá em đều đóng đúng hạn, không có khoản nào còn nợ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_04','V392','工作人员',4,'毕业证当场发放，公证文件三个工作日后可取。','bì yè zhèng dāng chǎng fā fàng， gōng zhèng wén jiàn sān gè gōng zuò rì hòu kě qǔ。','Bằng tốt nghiệp sẽ cấp ngay tại chỗ, còn văn bản công chứng thì ba ngày làm việc sau em quay lại lấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_05','V392','阮明',5,'公证文件可以多打印两份，方便我带回越南使用吧？','gōng zhèng wén jiàn kě yǐ duō dǎ yìn liǎng fèn， fāng biàn wǒ dài huí yuè nán shǐ yòng ba？','Vậy văn bản công chứng chị in giúp em thêm hai bản nữa được không ạ, để em mang về Việt Nam dùng cho tiện?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_06','V392','工作人员',6,'没问题，每份公证只收取基础工本费。','méi wèn tí， měi fèn gōng zhèng zhǐ shōu qǔ jī chǔ gōng běn fèi。','Không vấn đề gì, mỗi bản công chứng chỉ thu phí làm hồ sơ cơ bản thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_07','V392','阮明',7,'麻烦您帮忙办理，这份材料对我后续深造很重要。','má fán nín bāng máng bàn lǐ， zhè fèn cái liào duì wǒ hòu xù shēn zào hěn zhòng yào。','Phiền chị giúp em làm thủ tục này, hồ sơ này rất quan trọng cho việc học tiếp của em sau này ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT393','S130','Làm thủ tục trả phòng ký túc xá',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V393','SIT393','P1','twist','ban_chinh_thuc',NULL,'高校宿舍退房会逐一清点室内设施，人为造成大面积破损，学校会从住宿押金中扣除维修费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_01','V393','阮明',1,'阿姨，我今天来办宿舍退房，麻烦检查一下房间。','ā yí， wǒ jīn tiān lái bàn sù shè tuì fáng， má fán jiǎn chá yī xià fáng jiān。','Cô ơi, hôm nay em đến làm thủ tục trả phòng ký túc xá, phiền cô kiểm tra giúp phòng em một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_02','V393','宿管阿姨',2,'我看看桌椅、墙面和电器，破损会扣押金哈。','wǒ kàn kàn zhuō yǐ、 qiáng miàn hé diàn qì， pò sǔn huì kòu yā jīn hā。','Cô xem qua bàn ghế, tường và đồ điện, hư hỏng gì là bị trừ tiền cọc đó nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_03','V393','阮明',3,'我平时很爱惜房间，只有书桌边角有一点小划痕嘛。','wǒ píng shí hěn ài xī fáng jiān， zhǐ yǒu shū zhuō biān jiǎo yǒu yì diǎn xiǎo huà hén ma。','Em vẫn giữ gìn phòng cẩn thận lắm, chỉ có góc bàn học bị trầy nhẹ một chút thôi mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_04','V393','宿管阿姨',4,'轻微划痕不影响，不需要扣除押金。','qīng wēi huà hén bù yǐng xiǎng， bù xū yào kòu chú yā jīn。','Vết trầy nhẹ này không ảnh hưởng gì, không cần trừ tiền cọc đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_05','V393','阮明',5,'那我的行李可以暂时放在楼道等同学帮忙搬运吗？','nà wǒ de xíng lǐ kě yǐ zàn shí fàng zài lóu dào děng tóng xué bāng máng bān yùn ma？','Vậy hành lý của em có thể để tạm ngoài hành lang chờ bạn đến phụ khiêng được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_06','V393','宿管阿姨',6,'短时间放置没问题，不要堵塞消防通道就行。','duǎn shí jiān fàng zhì méi wèn tí， bú yào dǔ sè xiāo fáng tōng dào jiù xíng。','Để tạm một lúc thì không sao, chỉ cần đừng chắn lối thoát hiểm là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_07','V393','阮明',7,'太感谢阿姨通融，我收拾完立刻离开宿舍楼。','tài gǎn xiè ā yí tōng róng， wǒ shōu shí wán lì kè lí kāi sù shè lóu。','Em cảm ơn cô đã thông cảm nhiều lắm, em dọn xong là rời khỏi tòa nhà ký túc ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT394','S130','Thanh lý hợp đồng thuê nhà ngoài',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V394','SIT394','P1','suon_se','ban_chinh_thuc',NULL,'提前退租需和房东当面清点房屋物品，确认无损坏、无欠费后，房东才会全额返还租房押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_01','V394','阮明',1,'房东您好，我马上毕业回国，想提前终止租房合同。','fáng dōng nín hǎo， wǒ mǎ shàng bì yè huí guó， xiǎng tí qián zhōng zhǐ zū fáng hé tóng。','Chào chú, em sắp tốt nghiệp về nước rồi nên muốn xin chấm dứt hợp đồng thuê nhà sớm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_02','V394','房东',2,'可以，我们按合同约定清点家具，结清水电杂费吧。','kě yǐ， wǒ men àn hé tóng yuē dìng qīng diǎn jiā jù， jié qīng shuǐ diàn zá fèi ba。','Được, mình kiểm kê đồ đạc theo hợp đồng đã thỏa thuận, rồi thanh toán tiền điện nước còn lại nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_03','V394','阮明',3,'所有家具完好无损，水电费我已经全部缴清了呢。','suǒ yǒu jiā jù wán hǎo wú sǔn， shuǐ diàn fèi wǒ yǐ jīng quán bù jiǎo qīng le ne。','Đồ đạc còn nguyên vẹn hết, tiền điện nước em cũng đã đóng đủ hết rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_04','V394','房东',4,'墙面没有污渍、家电能正常使用，我全额退还押金。','qiáng miàn méi yǒu wū zì、 jiā diàn néng zhèng cháng shǐ yòng， wǒ quán é tuì huán yā jīn。','Tường không có vết bẩn, đồ điện dùng được bình thường, chú trả lại toàn bộ tiền cọc cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_05','V394','阮明',5,'押金可以直接转账到我的银行卡里对吗？','yā jīn kě yǐ zhí jiē zhuǎn zhàng dào wǒ de yín háng kǎ lǐ duì ma？','Vậy tiền cọc có thể chuyển thẳng vào thẻ ngân hàng của em được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_06','V394','房东',6,'没问题，验收完房屋当天就给你转账。','méi wèn tí， yàn shōu wán fáng wū dàng tiān jiù gěi nǐ zhuǎn zhàng。','Không vấn đề gì, kiểm tra nhà xong hôm nay là chuyển khoản cho em luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_07','V394','阮明',7,'辛苦您抽空过来验房，麻烦您多费心。','xīn kǔ nín chōu kòng guò lái yàn fáng， má fán nín duō fèi xīn。','Cảm ơn chú đã dành thời gian đến kiểm tra nhà, phiền chú nhiều rồi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT395','S119','Đóng tài khoản ngân hàng trước khi về nước',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V395','SIT395','P1','twist','chinh_thuc',NULL,'外籍人员长期离境建议注销国内闲置银行卡，避免长期休眠账户产生管理风险。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_01','V395','阮明',1,'您好，我即将回国，想要注销这张留学生储蓄卡。','nín hǎo， wǒ jí jiāng huí guó， xiǎng yào zhù xiāo zhè zhāng liú xué shēng chǔ xù kǎ。','Chào chị, em sắp về nước nên muốn hủy thẻ tiết kiệm dành cho du học sinh này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_02','V395','柜员',2,'先把卡里余额全部取出，再填写销户申请单哦。','xiān bǎ kǎ lǐ yú é quán bù qǔ chū， zài tián xiě xiāo hù shēn qǐng dān ó。','Trước tiên em rút hết số dư trong thẻ ra, rồi điền đơn xin đóng tài khoản nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_03','V395','阮明',3,'我刚刚查询，账户还有十几块零钱没法线上转出嘛。','wǒ gāng gāng chá xún， zhàng hù hái yǒu shí jǐ kuài líng qián méi fǎ xiàn shàng zhuǎn chū ma。','Em vừa kiểm tra, tài khoản còn hơn chục đồng lẻ không chuyển online được mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_04','V395','柜员',4,'小额现金柜台可以直接取出，不影响销户流程。','xiǎo é xiàn jīn guì tái kě yǐ zhí jiē qǔ chū， bù yǐng xiǎng xiāo hù liú chéng。','Số tiền lẻ nhỏ đó có thể rút trực tiếp tại quầy, không ảnh hưởng đến việc đóng tài khoản đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_05','V395','阮明',5,'销户完成后，银行会开具销户证明给我吗？','xiāo hù wán chéng hòu， yín háng huì kāi jù xiāo hù zhèng míng gěi wǒ ma？','Sau khi đóng tài khoản xong, ngân hàng có cấp giấy xác nhận đã đóng tài khoản cho em không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_06','V395','柜员',6,'可以，纸质销户回执会加盖公章交给你留存。','kě yǐ， zhǐ zhì xiāo hù huí zhí huì jiā gài gōng zhāng jiāo gěi nǐ liú cún。','Có chứ, biên nhận đóng tài khoản bản giấy sẽ được đóng dấu và giao cho em giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_07','V395','阮明',7,'好，我现在办理取现，再完成销户手续。','hǎo， wǒ xiàn zài bàn lǐ qǔ xiàn， zài wán chéng xiāo hù shǒu xù。','Vâng, giờ em làm thủ tục rút tiền mặt, xong rồi hoàn tất việc đóng tài khoản luôn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT396','S131','Hủy SIM điện thoại trước khi về nước',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V396','SIT396','P1','suon_se','ban_chinh_thuc',NULL,'留学生离境前务必注销手机卡，若长期欠费停机，会影响本人后续再次办理国内通信业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_01','V396','阮明',1,'你好，我毕业要回国，打算注销名下这张手机电话卡。','nǐ hǎo， wǒ bì yè yào huí guó， dǎ suàn zhù xiāo míng xià zhè zhāng shǒu jī diàn huà kǎ。','Chào anh, em tốt nghiệp sắp về nước nên định hủy sim điện thoại đứng tên em này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_02','V396','客服',2,'出示办卡时的护照，我先查询套餐是否有未结清费用呢。','chū shì bàn kǎ shí de hù zhào， wǒ xiān chá xún tào cān shì fǒu yǒu wèi jié qīng fèi yòng ne。','Em cho anh xem hộ chiếu lúc đăng ký sim, để anh kiểm tra xem gói cước có còn nợ cước gì không nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_03','V396','阮明',3,'上个月话费已经缴完，没有欠费、没有合约捆绑。','shàng gè yuè huà fèi yǐ jīng jiǎo wán， méi yǒu qiàn fèi、 méi yǒu hé yuē kǔn bǎng。','Tháng trước em đã đóng đủ tiền cước rồi, không nợ cước, cũng không ràng buộc hợp đồng gì hết ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_04','V396','客服',4,'那现在就能当场注销，卡里剩余话费可以现金退还。','nà xiàn zài jiù néng dāng chǎng zhù xiāo， kǎ lǐ shèng yú huà fèi kě yǐ xiàn jīn tuì huán。','Vậy giờ hủy luôn tại chỗ được, tiền cước còn dư trong sim có thể hoàn lại tiền mặt cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_05','V396','阮明',5,'注销之后，会不会收到后续短信或者扣费通知吧？','zhù xiāo zhī hòu， huì bú huì shōu dào hòu xù duǎn xìn huò zhě kòu fèi tōng zhī ba？','Sau khi hủy rồi, em có bị nhận tin nhắn hay thông báo trừ tiền gì nữa không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_06','V396','客服',6,'不会，销户后号码直接回收，和你不再有关联。','bú huì， xiāo hù hòu hào mǎ zhí jiē huí shōu， hé nǐ bù zài yǒu guān lián。','Không đâu, hủy xong là số bị thu hồi luôn, không còn liên quan gì đến em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_07','V396','阮明',7,'那就麻烦你帮我办理注销业务了。','nà jiù má fán nǐ bāng wǒ bàn lǐ zhù xiāo yè wù le。','Vậy phiền anh giúp em làm thủ tục hủy sim luôn nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT397','S119','Xin hoàn lại tiền đặt cọc phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V397','SIT397','P1','twist','ban_chinh_thuc',NULL,'学校各类押金退款均留存电子档案，票据丢失可凭本人有效证件核对记录办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_01','V397','阮明',1,'老师您好，我毕业离校，申请退还宿舍住宿押金。','lǎo shī nín hǎo， wǒ bì yè lí xiào， shēn qǐng tuì huán sù shè zhù sù yā jīn。','Chào thầy, em tốt nghiệp rời trường rồi, xin nộp đơn hoàn lại tiền cọc ký túc xá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_02','V397','财务老师',2,'带好退房回执和缴费票据，我登记后走退款流程哈。','dài hǎo tuì fáng huí zhí hé jiǎo fèi piào jù， wǒ dēng jì hòu zǒu tuì kuǎn liú chéng hā。','Em mang theo biên nhận trả phòng và hóa đơn đóng tiền, thầy ghi nhận xong sẽ làm thủ tục hoàn trả nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_03','V397','阮明',3,'退房回执我带来了，但是押金票据不小心弄丢了嘛。','tuì fáng huí zhí wǒ dài lái le， dàn shì yā jīn piào jù bù xiǎo xīn nòng diū le ma。','Biên nhận trả phòng em mang theo rồi, nhưng hóa đơn tiền cọc em lỡ làm mất mất rồi thầy ơi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_04','V397','财务老师',4,'没关系，系统有缴费记录，凭护照也能核对退款。','méi guān xì， xì tǒng yǒu jiǎo fèi jì lù， píng hù zhào yě néng hé duì tuì kuǎn。','Không sao, hệ thống có lưu lại hồ sơ đóng tiền, dùng hộ chiếu cũng đối chiếu được để hoàn trả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_05','V397','阮明',5,'押金是原路退回银行卡，还是现场领取现金？','yā jīn shì yuán lù tuì huí yín háng kǎ， hái shì xiàn chǎng lǐng qǔ xiàn jīn？','Tiền cọc sẽ hoàn về thẻ ngân hàng như lúc đóng, hay em nhận tiền mặt tại chỗ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_06','V397','财务老师',6,'统一银行卡转账，三个工作日内到账。','tǒng yī yín háng kǎ zhuǎn zhàng， sān gè gōng zuò rì nèi dào zhàng。','Thống nhất chuyển khoản qua thẻ ngân hàng, trong vòng ba ngày làm việc là tiền về.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_07','V397','阮明',7,'太感谢老师帮忙核对，省去我不少麻烦。','tài gǎn xiè lǎo shī bāng máng hé duì， shěng qù wǒ bù shǎo má fán。','Em cảm ơn thầy rất nhiều đã giúp đối chiếu hồ sơ, đỡ cho em bao nhiêu phiền phức ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT398','S132','Làm thủ tục ra sân bay về nước',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V398','SIT398','P1','suon_se','ban_chinh_thuc',NULL,'国内国际航班充电宝只能随身携带，严禁放入托运行李，超规行李需要额外支付运费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_01','V398','阮明',1,'您好，我乘坐飞往越南的航班，办理行李托运和值机。','nín hǎo， wǒ chéng zuò fēi wǎng yuè nán de háng bān， bàn lǐ xíng lǐ tuō yùn hé zhí jī。','Chào anh/chị, em đi chuyến bay về Việt Nam, làm thủ tục ký gửi hành lý và check-in ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_02','V398','工作人员',2,'出示你的护照和电子机票，行李不要超重哦。','chū shì nǐ de hù zhào hé diàn zi jī piào， xíng lǐ bú yào chāo zhòng ó。','Em cho xem hộ chiếu và vé điện tử, hành lý đừng để quá cân nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_03','V398','阮明',3,'两件行李箱总重量二十公斤，符合免费托运标准呢。','liǎng jiàn xíng lǐ xiāng zǒng zhòng liàng èr shí gōng jīn， fú hé miǎn fèi tuō yùn biāo zhǔn ne。','Hai vali của em tổng cộng nặng hai mươi ký, đúng tiêu chuẩn ký gửi miễn phí rồi đó ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_04','V398','工作人员',4,'行李贴好标签，登机口在二楼，提前一小时等候登机。','xíng lǐ tiē hǎo biāo qiān， dēng jī kǒu zài èr lóu， tí qián yī xiǎo shí děng hòu dēng jī。','Hành lý dán nhãn xong rồi, cổng lên máy bay ở tầng hai, ra sớm một tiếng để chờ lên máy bay nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_05','V398','阮明',5,'随身包里有电子产品，过安检需要单独拿出来对吧？','suí shēn bāo lǐ yǒu diàn zi chǎn pǐn， guò ān jiǎn xū yào dān dú ná chū lái duì ba？','Trong túi xách tay em có đồ điện tử, qua an ninh phải lấy riêng ra đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_06','V398','工作人员',6,'没错，电脑、充电宝都要单独过机检查。','méi cuò， diàn nǎo、 chōng diàn bǎo dōu yào dān dú guò jī jiǎn chá。','Đúng vậy, máy tính, sạc dự phòng đều phải để riêng để kiểm tra máy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_07','V398','阮明',7,'清楚流程了，辛苦你指引我办理。','qīng chǔ liú chéng le， xīn kǔ nǐ zhǐ yǐn wǒ bàn lǐ。','Em rõ quy trình rồi ạ, cảm ơn anh/chị đã hướng dẫn giúp em làm thủ tục.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT399','S129','Xin giấy xác nhận đã hoàn thành khóa học',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V399','SIT399','P1','suon_se','ban_chinh_thuc',NULL,'海外院校会要求留学生提供课程完成证明，以此核实学生完整完成在校学习。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_01','V399','阮明',1,'老师，我回国升学需要课程完成证明，麻烦帮忙开具。','lǎo shī， wǒ huí guó shēng xué xū yào kè chéng wán chéng zhèng míng， má fán bāng máng kāi jù。','Thầy ơi, em về nước học tiếp lên nên cần giấy xác nhận hoàn thành khóa học, phiền thầy cấp giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_02','V399','教务老师',2,'所有课程、论文全部合格，才能出具这份官方证明吧。','suǒ yǒu kè chéng、 lùn wén quán bù hé gé， cái néng chū jù zhè fèn guān fāng zhèng míng ba。','Tất cả môn học, luận văn đều đạt hết thì mới cấp được giấy xác nhận chính thức này đó.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_03','V399','阮明',3,'我的全部课程考核通过，论文也顺利答辩完成了呢。','wǒ de quán bù kè chéng kǎo hé tōng guò， lùn wén yě shùn lì dá biàn wán chéng le ne。','Tất cả các môn của em đều đạt yêu cầu, luận văn cũng đã bảo vệ thành công rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_04','V399','教务老师',4,'我现在打印两份，加盖学院公章交给你带走。','wǒ xiàn zài dǎ yìn liǎng fèn， jiā gài xué yuàn gōng zhāng jiāo gěi nǐ dài zǒu。','Giờ thầy in hai bản, đóng dấu của khoa rồi giao cho em mang đi nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_05','V399','阮明',5,'证明上面会标注我的在校学习时长和专业信息吗？','zhèng míng shàng miàn huì biāo zhù wǒ de zài xiào xué xí shí cháng hé zhuān yè xìn xī ma？','Giấy xác nhận có ghi rõ thời gian em học tại trường và thông tin chuyên ngành không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_06','V399','教务老师',6,'全部信息完整标注，国外院校完全认可。','quán bù xìn xī wán zhěng biāo zhù， guó wài yuàn xiào wán quán rèn kě。','Đầy đủ thông tin hết, các trường nước ngoài công nhận hoàn toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_07','V399','阮明',7,'太感谢老师，这份证明对我的深造至关重要。','tài gǎn xiè lǎo shī， zhè fèn zhèng míng duì wǒ de shēn zào zhì guān zhòng yào。','Em cảm ơn thầy rất nhiều, giấy xác nhận này rất quan trọng cho việc học tiếp của em ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT400','S133','Nói lời chia tay và cảm ơn thầy cô, bạn bè',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V400','SIT400','P1','suon_se','ban_chinh_thuc',NULL,'学生毕业离校前主动和老师当面道别是尊师礼仪，中国人习惯祝福对方前路顺遂、常保持联络。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_01','V400','阮明',1,'李老师，我下周就要回国了，今天特地来和您道别。','lǐ lǎo shī， wǒ xià zhōu jiù yào huí guó le， jīn tiān tè dì lái hé nín dào bié。','Thầy Lý ơi, tuần sau em về nước rồi, hôm nay em đến đây để chào tạm biệt thầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_02','V400','李老师',2,'时间过得真快，这两年你的汉语进步特别明显啊。','shí jiān guò dé zhēn kuài， zhè liǎng nián nǐ de hàn yǔ jìn bù tè bié míng xiǎn a。','Thời gian trôi nhanh thật đấy, tiếng Trung của em hai năm qua tiến bộ rõ rệt lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_03','V400','阮明',3,'多亏您一直耐心辅导我，我心里特别感激呢。','duō kuī nín yì zhí nài xīn fǔ dǎo wǒ， wǒ xīn lǐ tè bié gǎn jī ne。','Nhờ thầy kiên nhẫn kèm cặp em suốt, em cảm kích lắm đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_04','V400','李老师',4,'以后回国也要坚持练习汉语，有空常联系吧。','yǐ hòu huí guó yě yào jiān chí liàn xí hàn yǔ， yǒu kòng cháng lián xì ba。','Về nước rồi cũng phải chịu khó luyện tiếng Trung tiếp nhé, rảnh thì liên lạc thường xuyên nha.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_05','V400','阮明',5,'我回国会经常给您发消息，也会记得和同学们保持联络。','wǒ huí guó huì jīng cháng gěi nín fā xiāo xī， yě huì jì de hé tóng xué men bǎo chí lián luò。','Về nước em sẽ hay nhắn tin cho thầy, cũng sẽ nhớ giữ liên lạc với các bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_06','V400','李老师',6,'一路平安，祝你回国之后一切顺利。','yí lù píng ān， zhù nǐ huí guó zhī hòu yī qiè shùn lì。','Chúc em thượng lộ bình an, về nước mọi việc suôn sẻ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_07','V400','阮明',7,'谢谢老师两年的照顾，我永远不会忘记这段时光。','xiè xiè lǎo shī liǎng nián de zhào gù， wǒ yǒng yuǎn bú huì wàng jì zhè duàn shí guāng。','Em cảm ơn thầy đã chăm lo cho em suốt hai năm qua, em sẽ không bao giờ quên khoảng thời gian này.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT501','SV1','入境30天内前往国际学院登记备案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V501','SIT501','P1','twist','ban_chinh_thuc',NULL,'外籍留学生入境后必须30日内完成校内住宿登记，超期会影响后续居留许可办理，甚至产生罚款。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_01','V501','阮明',1,'老师您好，我上周刚从越南入境，过来做新生入境登记。','lǎo shī nín hǎo， wǒ shàng zhōu gāng cóng yuè nán rù jìng， guò lái zuò xīn shēng rù jìng dēng jì。','Chào thầy/cô, em vừa nhập cảnh từ Việt Nam tuần trước, em đến đây để làm đăng ký nhập cảnh cho sinh viên mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_02','V501','老师',2,'先把你的护照、入境海关盖章页拿给我核对一下吧。','xiān bǎ nǐ de hù zhào、 rù jìng hǎi guān gài zhāng yè ná gěi wǒ hé duì yī xià ba。','Em đưa hộ chiếu và trang đóng dấu hải quan nhập cảnh cho thầy kiểm tra trước nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_03','V501','阮明',3,'护照在这里，但是我没打印入境盖章页的复印件嘛。','hù zhào zài zhè lǐ， dàn shì wǒ méi dǎ yìn rù jìng gài zhāng yè de fù yìn jiàn ma。','Hộ chiếu đây ạ, nhưng em chưa in bản sao trang đóng dấu nhập cảnh.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_04','V501','老师',4,'登记系统需要留存纸质复印件，楼下打印店可以当场复印。','dēng jì xì tǒng xū yào liú cún zhǐ zhì fù yìn jiàn， lóu xià dǎ yìn diàn kě yǐ dāng chǎng fù yìn。','Hệ thống đăng ký cần lưu bản sao giấy, tiệm photo dưới lầu có thể in ngay tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_05','V501','阮明',5,'那我先下楼复印，回来还需要填写什么登记表格吗？','nà wǒ xiān xià lóu fù yìn， huí lái hái xū yào tián xiě shén me dēng jì biǎo gé ma？','Vậy em xuống photo trước, quay lại còn phải điền thêm mẫu đăng ký nào nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_06','V501','老师',6,'要填入境信息登记表，写明抵达日期、居住宿舍房间号。','yào tián rù jìng xìn xī dēng jì biǎo， xiě míng dǐ dá rì qī、 jū zhù sù shě fáng jiān hào。','Cần điền tờ đăng ký thông tin nhập cảnh, ghi rõ ngày đến và số phòng ký túc xá đang ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_07','V501','阮明',7,'登记完成后，才可以预约出入境办居留许可对吗？','dēng jì wán chéng hòu， cái kě yǐ yù yuē chū rù jìng bàn jū liú xǔ kě duì ma？','Đăng ký xong rồi mới được hẹn lịch làm giấy phép cư trú ở phòng xuất nhập cảnh đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_08','V501','老师',8,'没错，未完成校内登记，出入境大厅不会受理签证申请。','méi cuò， wèi wán chéng xiào nèi dēng jì， chū rù jìng dà tīng bú huì shòu lǐ qiān zhèng shēn qǐng。','Đúng vậy, nếu chưa hoàn tất đăng ký trong trường thì bên xuất nhập cảnh sẽ không tiếp nhận hồ sơ xin visa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_09','V501','阮明',9,'好，我马上复印材料，十分钟回来办理登记。','hǎo， wǒ mǎ shàng fù yìn cái liào， shí fēn zhōng huí lái bàn lǐ dēng jì。','Dạ vâng, em đi photo tài liệu ngay, mười phút nữa em quay lại làm đăng ký.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT502','SV1','提交护照、录取材料申请首次居留许可',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V502','SIT502','P1','suon_se','chinh_thuc',NULL,'首次学生居留许可全套材料缺一不可，缺少任意一项都会直接退回不予受理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_01','V502','阮明',1,'您好，我是新生留学生，来递交首次居留许可申请材料。','nín hǎo， wǒ shì xīn shēng liú xué shēng， lái dì jiāo shǒu cì jū liú xǔ kě shēn qǐng cái liào。','Xin chào, tôi là du học sinh mới, đến để nộp hồ sơ xin cấp giấy phép cư trú lần đầu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_02','V502','工作人员',2,'依次递交护照、录取通知书、体检报告、住宿登记单哦。','yī cì dì jiāo hù zhào、 lù qǔ tōng zhī shū、 tǐ jiǎn bào gào、 zhù sù dēng jì dān ó。','Anh/chị nộp lần lượt hộ chiếu, giấy báo nhập học, giấy khám sức khỏe và giấy đăng ký chỗ ở nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_03','V502','阮明',3,'全部材料都整理齐全，一式两份已经分好。','quán bù cái liào dōu zhěng lǐ qí quán， yī shì liǎng fèn yǐ jīng fēn hǎo。','Toàn bộ hồ sơ đã được sắp xếp đầy đủ, mỗi loại đã chuẩn bị hai bản.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_04','V502','工作人员',4,'我核对一遍，信息匹配无误，给你一张受理回执。','wǒ hé duì yī biàn， xìn xī pǐ pèi wú wù， gěi nǐ yī zhāng shòu lǐ huí zhí。','Tôi kiểm tra lại một lượt, thông tin khớp hết, đây là phiếu biên nhận cho anh/chị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_05','V502','阮明',5,'大概几个工作日能拿到办好的居留贴纸呢？','dà gài jǐ gè gōng zuò rì néng ná dào bàn hǎo de jū liú tiē zhǐ ne？','Khoảng mấy ngày làm việc thì tôi có thể nhận được tem cư trú đã làm xong ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_06','V502','工作人员',6,'标准七个工作日，加急业务三个工作日办结。','biāo zhǔn qī gè gōng zuò rì， jiā jí yè wù sān gè gōng zuò rì bàn jié。','Bình thường là bảy ngày làm việc, làm nhanh thì ba ngày làm việc là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_07','V502','阮明',7,'取件可以凭回执代领，还是必须本人到场？','qǔ jiàn kě yǐ píng huí zhí dài lǐng， hái shì bì xū běn rén dào chǎng？','Khi nhận giấy tờ, tôi có thể nhờ người khác cầm biên nhận đến lấy hộ được không, hay bắt buộc phải đích thân đến?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_08','V502','工作人员',8,'本人携带回执、身份证（护照）才能领取证件。','běn rén xié dài huí zhí、 shēn fèn zhèng （hù zhào） cái néng lǐng qǔ zhèng jiàn。','Phải chính chủ mang theo biên nhận và giấy tờ tùy thân (hộ chiếu) mới được nhận giấy tờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_09','V502','阮明',9,'清楚了，辛苦您受理我的签证材料！','qīng chǔ le， xīn kǔ nín shòu lǐ wǒ de qiān zhèng cái liào！','Tôi rõ rồi, cảm ơn anh/chị đã vất vả tiếp nhận hồ sơ visa của tôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT503','SV1','体检不合格，需要重新预约出入境体检',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V503','SIT503','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生签证专用体检必须在出入境指定医院完成，体检不合格无法提交居留申请，复查需全额自费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_01','V503','阮明',1,'医生，我昨天拿到出入境体检报告，被告知体检不合格。','yī shēng， wǒ zuó tiān ná dào chū rù jìng tǐ jiǎn bào gào， bèi gào zhī tǐ jiǎn bù hé gé。','Bác sĩ ơi, hôm qua em nhận được báo cáo khám sức khỏe xuất nhập cảnh, bị thông báo là không đạt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_02','V503','校医',2,'我看看报告，是肝功能指标临时偏高，无法提交签证使用。','wǒ kàn kàn bào gào， shì gān gōng néng zhǐ biāo lín shí piān gāo， wú fǎ tí jiāo qiān zhèng shǐ yòng。','Để tôi xem báo cáo, chỉ số chức năng gan của em tạm thời cao hơn bình thường, không thể dùng để nộp visa được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_03','V503','阮明',3,'那这种情况只能重新全套体检吗，没有补救办法？','nà zhè zhǒng qíng kuàng zhǐ néng chóng xīn quán tào tǐ jiǎn ma， méi yǒu bǔ jiù bàn fǎ？','Vậy trường hợp này chỉ có cách khám lại toàn bộ thôi ạ, không có cách nào khắc phục sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_04','V503','校医',4,'需要间隔一周清淡饮食后重新预约，只复查异常项目不行嘛。','xū yào jiàn gé yī zhōu qīng dàn yǐn shí hòu chóng xīn yù yuē， zhǐ fù chá yì cháng xiàng mù bù xíng ma。','Em cần ăn uống thanh đạm trong một tuần rồi hẹn khám lại, chứ không thể chỉ khám riêng mục bất thường đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_05','V503','阮明',5,'重新体检还要再交一次全套体检费用对吧？','chóng xīn tǐ jiǎn hái yào zài jiāo yī cì quán tào tǐ jiǎn fèi yòng duì ba？','Khám lại thì em phải đóng lại toàn bộ chi phí khám sức khỏe đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_06','V503','校医',6,'是的，出入境指定体检中心复查需要全额重新缴费。','shì de， chū rù jìng zhǐ dìng tǐ jiǎn zhōng xīn fù chá xū yào quán é chóng xīn jiǎo fèi。','Đúng vậy, khám lại tại trung tâm khám sức khỏe chỉ định của xuất nhập cảnh thì phải đóng lại toàn bộ phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_07','V503','阮明',7,'一周后直接线上预约体检中心就能重新检测吗？','yī zhōu hòu zhí jiē xiàn shàng yù yuē tǐ jiǎn zhōng xīn jiù néng chóng xīn jiǎn cè ma？','Một tuần sau em chỉ cần đặt lịch online với trung tâm khám sức khỏe là có thể khám lại luôn phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_08','V503','校医',8,'线上预约后带旧报告，方便医生对比两次检测数据。','xiàn shàng yù yuē hòu dài jiù bào gào， fāng biàn yī shēng duì bǐ liǎng cì jiǎn cè shù jù。','Đặt lịch online xong thì mang theo báo cáo cũ, để bác sĩ tiện so sánh kết quả hai lần khám.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_09','V503','阮明',9,'我记好时间调整作息，下周再来做全套体检。','wǒ jì hǎo shí jiān tiáo zhěng zuò xī， xià zhōu zài lái zuò quán tào tǐ jiǎn。','Em ghi nhớ thời gian, điều chỉnh sinh hoạt lại, tuần sau em sẽ đến khám tổng quát lại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT504','SV1','忘记携带境外录取通知书原件，无法提交签证材料',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V504','SIT504','P1','that_bai_nhe','chinh_thuc',NULL,'出入境办理居留许可严格核验纸质原件，电子照片、复印件均不具备受理效力，必须线下现场核验。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_01','V504','阮明',1,'您好，我今天过来递交居留许可申请材料。','nín hǎo， wǒ jīn tiān guò lái dì jiāo jū liú xǔ kě shēn qǐng cái liào。','Xin chào, hôm nay tôi đến để nộp hồ sơ xin cấp giấy phép cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_02','V504','工作人员',2,'麻烦出示境外院校发放的纸质录取通知书原件。','má fán chū shì jìng wài yuàn xiào fā fàng de zhǐ zhì lù qǔ tōng zhī shū yuán jiàn。','Phiền anh/chị xuất trình bản gốc giấy báo nhập học do trường ở nước ngoài cấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_03','V504','阮明',3,'糟糕，我只带了复印件，原件放在宿舍忘记带来了啊。','zāo gāo， wǒ zhǐ dài le fù yìn jiàn， yuán jiàn fàng zài sù shè wàng jì dài lái le a。','Chết rồi, tôi chỉ mang theo bản sao thôi, bản gốc để ở ký túc xá quên mang theo mất rồi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_04','V504','工作人员',4,'签证审核必须核验原件，复印件不能单独作为受理材料。','qiān zhèng shěn hé bì xū hé yàn yuán jiàn， fù yìn jiàn bù néng dān dú zuò wéi shòu lǐ cái liào。','Khi xét duyệt visa bắt buộc phải kiểm tra bản gốc, bản sao không thể dùng làm hồ sơ tiếp nhận riêng lẻ được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_05','V504','阮明',5,'手机里存有原件高清照片，能不能先帮我受理后续补交？','shǒu jī lǐ cún yǒu yuán jiàn gāo qīng zhào piān， néng bù néng xiān bāng wǒ shòu lǐ hòu xù bǔ jiāo？','Trong điện thoại tôi có lưu ảnh chụp bản gốc độ nét cao, anh/chị có thể tiếp nhận trước rồi cho tôi bổ sung sau được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_06','V504','工作人员',6,'系统硬性规定，材料不齐无法建档，只能改天带原件再来。','xì tǒng yìng xìng guī dìng， cái liào bù qí wú fǎ jiàn dàng， zhǐ néng gǎi tiān dài yuán jiàn zài lái。','Hệ thống quy định cứng, hồ sơ không đầy đủ thì không thể lập hồ sơ được, chỉ có thể hẹn hôm khác mang bản gốc đến thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_07','V504','阮明',7,'那我明天一早带齐全部原件再来窗口办理可以吗？','nà wǒ míng tiān yī zǎo dài qí quán bù yuán jiàn zài lái chuāng kǒu bàn lǐ kě yǐ ma？','Vậy sáng mai tôi mang đầy đủ bản gốc đến quầy làm thủ tục được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_08','V504','工作人员',8,'明天正常上班，上午人少，建议早点过来排队。','míng tiān zhèng cháng shàng bān， shàng wǔ rén shǎo， jiàn yì zǎo diǎn guò lái pái duì。','Mai làm việc bình thường, buổi sáng ít người, anh/chị nên đến sớm để xếp hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_09','V504','阮明',9,'好的，实在抱歉漏带关键证件，耽误您工作了。','hǎo de， shí zài bào qiàn lòu dài guān jiàn zhèng jiàn， dān wù nín gōng zuò le。','Vâng, thật sự xin lỗi vì đã để thiếu giấy tờ quan trọng, làm phiền công việc của anh/chị.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT505','SV1','咨询留学生居留许可有效时长与入境截止规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V505','SIT505','P1','suon_se','ban_chinh_thuc',NULL,'学生居留许可最长与学制同步，到期断签属于非法滞留，会产生罚款并影响后续再次来华签证。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_01','V505','阮明',1,'警官您好，想咨询留学生居留许可的有效期相关规定。','jǐng guān nín hǎo， xiǎng zī xún liú xué shēng jū liú xǔ kě de yǒu xiào qī xiāng guān guī dìng。','Chào chú công an, tôi muốn hỏi về quy định thời hạn hiệu lực của giấy phép cư trú dành cho du học sinh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_02','V505','辅警',2,'居留时长和你的学制匹配，本科一般一次发放一年哦。','jū liú shí cháng hé nǐ de xué zhì pǐ pèi， běn kē yì bān yī cì fā fàng yī nián ó。','Thời hạn cư trú tương ứng với chương trình học của em, hệ đại học thường thì mỗi lần cấp là một năm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_03','V505','阮明',3,'如果寒暑假短期回国，在居留有效期内往返不受限制吧？','rú guǒ hán shǔ jià duǎn qī huí guó， zài jū liú yǒu xiào qī nèi wǎng fǎn bù shòu xiàn zhì ba？','Nếu về nước ngắn ngày vào dịp nghỉ hè, nghỉ đông thì trong thời hạn cư trú còn hiệu lực, việc đi lại không bị hạn chế đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_04','V505','辅警',4,'有效期内多次出入境无需额外报备，超期滞留会有处罚。','yǒu xiào qī nèi duō cì chū rù jìng wú xū é wài bào bèi， chāo qī zhì liú huì yǒu chǔ fá。','Trong thời hạn hiệu lực thì xuất nhập cảnh nhiều lần không cần báo cáo thêm, nhưng ở lại quá hạn sẽ bị xử phạt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_05','V505','阮明',5,'居留证到期前最晚多久要提交续办申请呢？','jū liú zhèng dào qī qián zuì wǎn duō jiǔ yào tí jiāo xù bàn shēn qǐng ne？','Trước khi thẻ cư trú hết hạn, chậm nhất là bao lâu thì phải nộp đơn xin gia hạn ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_06','V505','辅警',6,'建议提前三十天递交，预留审核时间避免断签。','jiàn yì tí qián sān shí tiān dì jiāo， yù liú shěn hé shí jiān bì miǎn duàn qiān。','Nên nộp trước ba mươi ngày, để dành thời gian xét duyệt, tránh bị gián đoạn visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_07','V505','阮明',7,'入境时签证上标注的最晚入境日期有什么约束？','rù jìng shí qiān zhèng shàng biāo zhù de zuì wǎn rù jìng rì qī yǒu shén me yuē shù？','Ngày nhập cảnh muộn nhất được ghi trên visa lúc nhập cảnh có ràng buộc gì không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_08','V505','辅警',8,'必须在标注日期前入境，逾期签证直接作废失效。','bì xū zài biāo zhù rì qī qián rù jìng， yú qī qiān zhèng zhí jiē zuò fèi shī xiào。','Bắt buộc phải nhập cảnh trước ngày ghi trên đó, visa quá hạn sẽ tự động mất hiệu lực luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_09','V505','阮明',9,'全部规则我记清楚了，非常感谢您细致讲解！','quán bù guī zé wǒ jì qīng chǔ le， fēi cháng gǎn xiè nín xì zhì jiǎng jiě！','Tôi đã nắm rõ hết các quy định rồi, cảm ơn chú đã giải thích cặn kẽ ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT506','SV1','学校统一代办居留签证，补交缺失的白底证件照',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V506','SIT506','P1','twist','tuy_y',NULL,'出入境签证证件照有统一尺寸、底色标准，照相馆会区分普通证件照与涉外签证专用照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_01','V506','老师',1,'阮明，学校统一代办居留签证，还差你的证件照没交。','ruǎn míng， xué xiào tǒng yí dài bàn jū liú qiān zhèng， hái chà nǐ de zhèng jiàn zhào méi jiāo。','Nguyễn Minh này, trường đang làm thủ tục visa cư trú tập trung, còn thiếu ảnh thẻ của em nữa đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_02','V506','阮明',2,'我上周交过一版照片，是尺寸不符合要求嘛？','wǒ shàng zhōu jiāo guò yī bǎn zhào piān， shì chǐ cùn bù fú hé yāo qiú ma？','Tuần trước em nộp một tấm ảnh rồi mà, hay là kích thước không đúng yêu cầu ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_03','V506','老师',3,'普通生活照不行，必须小二寸白底免冠证件照哈。','pǔ tōng shēng huó zhào bù xíng， bì xū xiǎo èr cùn bái dǐ miǎn guān zhèng jiàn zhào hā。','Ảnh chụp đời thường bình thường không được đâu, phải là ảnh thẻ 2x3 nền trắng không đội mũ nón cơ.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_04','V506','阮明',4,'楼下照相馆能拍符合出入境标准的签证照片吗？','lóu xià zhào xiàng guǎn néng pāi fú hé chū rù jìng biāo zhǔn de qiān zhèng zhào piān ma？','Tiệm chụp ảnh dưới lầu có chụp được ảnh visa đúng chuẩn xuất nhập cảnh không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_05','V506','老师',5,'可以，直接跟摄影师说办居留许可用，他知道规格。','kě yǐ， zhí jiē gēn shè yǐng shī shuō bàn jū liú xǔ kě yòng， tā zhī dào guī gé。','Được đó, em cứ nói thẳng với thợ chụp là chụp để làm giấy phép cư trú, họ biết quy cách rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_06','V506','阮明',6,'拍完下午送过来，还需要额外填写补充表格吗？','pāi wán xià wǔ sòng guò lái， hái xū yào é wài tián xiě bǔ chōng biǎo gé ma？','Chụp xong chiều em mang đến, còn phải điền thêm mẫu đơn bổ sung nào không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_07','V506','老师',7,'只交纸质照片就行，其余信息系统里都有存档。','zhǐ jiāo zhǐ zhì zhào piān jiù xíng， qí yú xìn xī xì tǒng lǐ dōu yǒu cún dàng。','Chỉ cần nộp ảnh giấy thôi, thông tin còn lại hệ thống đã lưu sẵn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_08','V506','阮明',8,'好嘞，我现在下楼拍照，很快送过来给您。','hǎo lei， wǒ xiàn zài xià lóu pāi zhào， hěn kuài sòng guò lái gěi nín。','Dạ được, em xuống chụp ảnh ngay đây, lát nữa mang lên cho thầy liền.','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT507','SV1','入境停留超期，前往出入境大厅办理逾期说明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V507','SIT507','P1','twist','chinh_thuc',NULL,'外籍人员在华签证超期属于非法滞留，会根据超期天数罚款，多次逾期会被限制入境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_01','V507','阮明',1,'警官您好，我上次出境旅游延误返程，在境内停留超期五天。','jǐng guān nín hǎo， wǒ shàng cì chū jìng lǚ yóu yán wù fǎn chéng， zài jìng nèi tíng liú chāo qī wǔ tiān。','Chào anh công an, lần trước tôi đi du lịch nước ngoài bị hoãn chuyến về, nên đã ở lại trong nước quá hạn năm ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_02','V507','民警',2,'先说明超期原因，提供机票行程单、学校在读证明吧。','xiān shuō míng chāo qī yuán yīn， tí gōng jī piào xíng chéng dān、 xué xiào zài dú zhèng míng ba。','Trước tiên trình bày lý do quá hạn, cung cấp hành trình vé máy bay và giấy xác nhận đang học tại trường nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_03','V507','阮明',3,'航班大面积延误导致无法按时离境，机票行程单在这里。','háng bān dà miàn jī yán wù dǎo zhì wú fǎ àn shí lí jìng， jī piào xíng chéng dān zài zhè lǐ。','Do chuyến bay bị hoãn trên diện rộng nên không thể xuất cảnh đúng hạn, hành trình vé máy bay đây ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_04','V507','民警',4,'短期超期十五天内可书面说明，超过十五天处罚会加重嘛。','duǎn qī chāo qī shí wǔ tiān nèi kě shū miàn shuō míng， chāo guò shí wǔ tiān chǔ fá huì jiā zhòng ma。','Quá hạn ngắn trong vòng mười lăm ngày thì có thể viết bản tường trình, quá mười lăm ngày thì mức phạt sẽ nặng hơn đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_05','V507','阮明',5,'本次超期会留下不良记录，影响下次续签居留吗？','běn cì chāo qī huì liú xià bù liáng jì lù， yǐng xiǎng xià cì xù qiān jū liú ma？','Lần quá hạn này có để lại tiền án tiền sự gì không, có ảnh hưởng đến việc gia hạn cư trú lần sau không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_06','V507','民警',6,'如实说明客观原因且首次违规，记录不会严重影响续签。','rú shí shuō míng kè guān yuán yīn qiě shǒu cì wéi guī， jì lù bú huì yán zhòng yǐng xiǎng xù qiān。','Nếu trình bày trung thực lý do khách quan và đây là vi phạm lần đầu thì hồ sơ sẽ không ảnh hưởng nghiêm trọng đến việc gia hạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_07','V507','阮明',7,'需要手写书面逾期情况说明，当场签字上交对吗？','xū yào shǒu xiě shū miàn yú qī qíng kuàng shuō míng， dāng chǎng qiān zì shàng jiāo duì ma？','Tôi cần viết tay bản tường trình về việc quá hạn, ký tên nộp ngay tại chỗ đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_08','V507','民警',8,'没错，写完核对信息签字，再缴纳对应逾期罚款即可。','méi cuò， xiě wán hé duì xìn xī qiān zì， zài jiǎo nà duì yìng yú qī fá kuǎn jí kě。','Đúng rồi, viết xong kiểm tra lại thông tin rồi ký tên, sau đó nộp khoản tiền phạt quá hạn tương ứng là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_09','V507','阮明',9,'我马上书写说明，配合完成全部处理流程。','wǒ mǎ shàng shū xiě shuō míng， pèi hé wán chéng quán bù chǔ lǐ liú chéng。','Tôi viết bản tường trình ngay đây, sẽ phối hợp hoàn tất toàn bộ quy trình xử lý.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT508','SV1','咨询单人宿舍住宿登记如何录入居留系统',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V508','SIT508','P1','suon_se','tuy_y',NULL,'所有外籍居住人员必须完成住宿登记，校内宿舍由宿管开具登记证明，校外租房由房东陪同社区备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_01','V508','阮明',1,'阿姨，我住单人宿舍，住宿登记怎么录入签证系统呢？','ā yí， wǒ zhù dān rén sù shè， zhù sù dēng jì zěn me lù rù qiān zhèng xì tǒng ne？','Cô ơi, con ở phòng ký túc xá đơn, đăng ký lưu trú thì nhập vào hệ thống visa như thế nào ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_02','V508','宿管阿姨',2,'我这边给你打印住宿登记单，盖宿舍楼公章就行啦。','wǒ zhè biān gěi nǐ dǎ yìn zhù sù dēng jì dān， gài sù shè lóu gōng zhāng jiù xíng la。','Để cô in cho con tờ đăng ký lưu trú, rồi đóng dấu của tòa ký túc xá là xong nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_03','V508','阮明',3,'多人宿舍和单人宿舍的登记单据格式是一样的吗？','duō rén sù shè hé dān rén sù shè de dēng jì dān jù gé shì shì yī yàng de ma？','Mẫu đăng ký của phòng đơn với phòng nhiều người có giống nhau không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_04','V508','宿管阿姨',4,'单据通用，只需要在房间人数一栏填写单人。','dān jù tōng yòng， zhǐ xū yào zài fáng jiān rén shù yī lán tián xiě dān rén。','Mẫu dùng chung thôi, chỉ cần ghi số người trong phòng là một người là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_05','V508','阮明',5,'拿到登记单直接带去出入境大厅递交签证材料？','ná dào dēng jì dān zhí jiē dài qù chū rù jìng dà tīng dì jiāo qiān zhèng cái liào？','Con cầm tờ đăng ký này đi thẳng lên phòng xuất nhập cảnh nộp hồ sơ visa luôn được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_06','V508','宿管阿姨',6,'对，这份单据是证明你合法住宿的核心材料。','duì， zhè fèn dān jù shì zhèng míng nǐ hé fǎ zhù sù de hé xīn cái liào。','Đúng rồi, đây là giấy tờ cốt lõi để chứng minh con lưu trú hợp pháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_07','V508','阮明',7,'麻烦您打印一份给我，我下午就去办居留申请。','má fán nín dǎ yìn yī fèn gěi wǒ， wǒ xià wǔ jiù qù bàn jū liú shēn qǐng。','Phiền cô in cho con một bản, chiều nay con đi làm thủ tục xin cư trú luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT509','SV2','居留许可快到期，提前咨询续办流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V509','SIT509','P1','suon_se','ban_chinh_thuc',NULL,'居留续签不能使用过期住宿登记、旧流水，所有辅助材料要求近期开具，保证信息实时有效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_01','V509','阮明',1,'老师，我的居留许可还有四十天到期，想咨询续签流程。','lǎo shī， wǒ de jū liú xǔ kě hái yǒu sì shí tiān dào qī， xiǎng zī xún xù qiān liú chéng。','Thầy ơi, giấy phép cư trú của em còn bốn mươi ngày nữa là hết hạn, em muốn hỏi về thủ tục gia hạn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_02','V509','老师',2,'第一步先开在校在读证明，再准备银行存款流水哦。','dì yī bù xiān kāi zài xiào zài dú zhèng míng， zài zhǔn bèi yín háng cún kuǎn liú shuǐ ó。','Bước đầu tiên em xin giấy xác nhận đang học tại trường, sau đó chuẩn bị sao kê tiền gửi ngân hàng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_03','V509','阮明',3,'存款流水有最低金额要求吗，需要存多久的记录？','cún kuǎn liú shuǐ yǒu zuì dī jīn é yāo qiú ma， xū yào cún duō jiǔ de jì lù？','Sao kê tiền gửi có yêu cầu số tiền tối thiểu không thầy, cần lưu bao lâu ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_04','V509','老师',4,'留学生建议提供至少一万元、连续三个月以上流水。','liú xué shēng jiàn yì tí gōng zhì shǎo yī wàn yuán、 lián xù sān gè yuè yǐ shàng liú shuǐ。','Du học sinh nên có tối thiểu một vạn tệ, sao kê liên tục từ ba tháng trở lên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_05','V509','阮明',5,'住宿登记单还要重新打印，上次办签证的旧单据能用吗？','zhù sù dēng jì dān hái yào chóng xīn dǎ yìn， shàng cì bàn qiān zhèng de jiù dān jù néng yòng ma？','Tờ đăng ký lưu trú có cần in lại không thầy, tờ cũ dùng khi làm visa lần trước còn dùng được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_06','V509','老师',6,'续签需要近一个月内新开具的住宿登记证明，旧的失效。','xù qiān xū yào jìn yí gè yuè nèi xīn kāi jù de zhù sù dēng jì zhèng míng， jiù de shī xiào。','Gia hạn thì cần giấy đăng ký lưu trú mới cấp trong vòng một tháng gần đây, tờ cũ hết hiệu lực rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_07','V509','阮明',7,'材料备齐后，线上预约出入境办理号就可以递交？','cái liào bèi qí hòu， xiàn shàng yù yuē chū rù jìng bàn lǐ hào jiù kě yǐ dì jiāo？','Sau khi chuẩn bị đủ giấy tờ, em đặt lịch online lấy số ở phòng xuất nhập cảnh rồi nộp luôn được chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_08','V509','老师',8,'线上预约优先办理，无预约只能现场排队等候。','xiàn shàng yù yuē yōu xiān bàn lǐ， wú yù yuē zhǐ néng xiàn chǎng pái duì děng hòu。','Đặt lịch online được ưu tiên xử lý trước, không đặt lịch thì chỉ có thể xếp hàng tại chỗ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_09','V509','阮明',9,'我会提前整理全部材料，避免临近到期手忙脚乱。','wǒ huì tí qián zhěng lǐ quán bù cái liào， bì miǎn lín jìn dào qī shǒu máng jiǎo luàn。','Em sẽ chuẩn bị sẵn hết giấy tờ từ sớm, tránh gần đến hạn mà cuống lên.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT510','SV2','续签证时银行存款证明余额不足，需重新开流水',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V510','SIT510','P1','that_bai_nhe','chinh_thuc',NULL,'留学生续签居留许可有活期存款最低额度要求，出入境只认可活期账户流水，定期、理财不计入审核余额。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_01','V510','阮明',1,'您好，我递交居留续签材料，麻烦帮忙核对一下。','nín hǎo， wǒ dì jiāo jū liú xù qiān cái liào， má fán bāng máng hé duì yī xià。','Xin chào, tôi nộp hồ sơ gia hạn cư trú, phiền anh/chị kiểm tra giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_02','V510','工作人员',2,'这份银行流水月末余额不足一万元，达不到签证标准。','zhè fèn yín háng liú shuǐ yuè mò yú é bù zú yī wàn yuán， dá bú dào qiān zhèng biāo zhǔn。','Số dư cuối tháng trên sao kê ngân hàng này chưa đủ một vạn tệ, không đạt tiêu chuẩn visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_03','V510','阮明',3,'我卡里有定期存款，能不能把定期存单一起当作资产证明？','wǒ kǎ lǐ yǒu dìng qī cún kuǎn， néng bù néng bǎ dìng qī cún dān yì qǐ dàng zuò zī chǎn zhèng míng？','Tôi có khoản tiền gửi có kỳ hạn, có thể dùng sổ tiết kiệm đó làm chứng minh tài sản cùng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_04','V510','工作人员',4,'系统只认可活期流水实时余额，定期存单不能抵扣要求嘛。','xì tǒng zhǐ rèn kě huó qī liú shuǐ shí shí yú é， dìng qī cún dān bù néng dǐ kòu yāo qiú ma。','Hệ thống chỉ chấp nhận số dư thực tế của tài khoản không kỳ hạn, tiền gửi có kỳ hạn không được tính vào yêu cầu này.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_05','V510','阮明',5,'那我转入资金后，隔天再来打印新流水重新递交可以吗？','nà wǒ zhuǎn rù zī jīn hòu， gé tiān zài lái dǎ yìn xīn liú shuǐ chóng xīn dì jiāo kě yǐ ma？','Vậy sau khi tôi chuyển tiền vào, hôm sau quay lại in sao kê mới rồi nộp lại được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_06','V510','工作人员',6,'可以，资金到账次日打印流水，余额达标再重新取号办理。','kě yǐ， zī jīn dào zhàng cì rì dǎ yìn liú shuǐ， yú é dá biāo zài chóng xīn qǔ hào bàn lǐ。','Được, hôm sau tiền vào tài khoản thì in sao kê, số dư đạt chuẩn rồi lấy số làm lại thủ tục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_07','V510','阮明',7,'今天先把其余材料带回，明天补足资金重新打印流水。','jīn tiān xiān bǎ qí yú cái liào dài huí， míng tiān bǔ zú zī jīn chóng xīn dǎ yìn liú shuǐ。','Hôm nay tôi mang các giấy tờ còn lại về trước, mai bổ sung đủ tiền rồi in lại sao kê.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_08','V510','工作人员',8,'记得流水打印当日不要大额转出资金。','jì de liú shuǐ dǎ yìn dāng rì bú yào dà é zhuǎn chū zī jīn。','Nhớ là ngày in sao kê thì đừng chuyển khoản số tiền lớn ra ngoài nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_09','V510','阮明',9,'明白了，感谢告知存款流水审核标准。','míng bái le， gǎn xiè gào zhī cún kuǎn liú shuǐ shěn hé biāo zhǔn。','Tôi hiểu rồi, cảm ơn đã cho biết tiêu chuẩn xét duyệt sao kê tiền gửi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT511','SV2','在校出勤率不够，学校不给开具签证在读证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V511','SIT511','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内高校对留学生出勤有硬性考核，出勤率不达标学校有权拒开在读证明，无法办理居留续签，严重者会要求限期离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_01','V511','阮明',1,'辅导员您好，我需要在读证明办理居留续签，麻烦帮我开具。','fǔ dǎo yuán nín hǎo， wǒ xū yào zài dú zhèng míng bàn lǐ jū liú xù qiān， má fán bāng wǒ kāi jù。','Chào cô cố vấn, em cần giấy xác nhận đang học để làm thủ tục gia hạn cư trú, phiền cô cấp giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_02','V511','辅导员',2,'系统显示你本学期旷课次数超标，出勤率未达到学校标准。','xì tǒng xiǎn shì nǐ běn xué qī kuàng kè cì shù chāo biāo， chū qín lǜ wèi dá dào xué xiào biāo zhǔn。','Hệ thống hiển thị học kỳ này em nghỉ học vượt quá số buổi cho phép, tỷ lệ chuyên cần chưa đạt chuẩn của trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_03','V511','阮明',3,'前段时间身体不舒服请假缺课，全部有医院病假单留存。','qián duàn shí jiān shēn tǐ bù shū fú qǐng jià quē kè， quán bù yǒu yī yuàn bìng jià dān liú cún。','Thời gian trước em bị ốm nên xin nghỉ học, tất cả đều có giấy nghỉ ốm của bệnh viện lưu lại ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_04','V511','辅导员',4,'病假需要提前报备学院，事后补交单据不计入合规请假记录嘛。','bìng jià xū yào tí qián bào bèi xué yuàn， shì hòu bǔ jiāo dān jù bù jì rù hé guī qǐng jià jì lù ma。','Nghỉ ốm cần báo trước cho khoa, nộp giấy tờ bổ sung sau thì không được tính vào diện nghỉ phép hợp lệ đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_05','V511','阮明',5,'那现在有什么办法可以补全出勤记录，拿到在读证明？','nà xiàn zài yǒu shén me bàn fǎ kě yǐ bǔ quán chū qín jì lù， ná dào zài dú zhèng míng？','Vậy bây giờ có cách nào để bổ sung đủ số buổi chuyên cần, để lấy được giấy xác nhận đang học không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_06','V511','辅导员',6,'接下来一个月全程不缺课，月末核查出勤后才能开具证明。','jiē xià lái yí gè yuè quán chéng bù quē kè， yuè mò hé chá chū qín hòu cái néng kāi jù zhèng míng。','Một tháng tới em không được nghỉ buổi nào, cuối tháng kiểm tra chuyên cần đạt thì mới cấp giấy xác nhận được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_07','V511','阮明',7,'我的签证马上到期，延迟开证明会导致签证断签啊。','wǒ de qiān zhèng mǎ shàng dào qī， yán chí kāi zhèng míng huì dǎo zhì qiān zhèng duàn qiān a。','Visa của em sắp hết hạn rồi, chậm cấp giấy này thì sẽ bị gián đoạn visa mất ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_08','V511','辅导员',8,'我给你开临时情况说明，先去出入境申请短期缓冲受理。','wǒ gěi nǐ kāi lín shí qíng kuàng shuō míng， xiān qù chū rù jìng shēn qǐng duǎn qī huǎn chōng shòu lǐ。','Cô sẽ viết cho em giấy giải trình tình huống tạm thời, em cứ ra phòng xuất nhập cảnh xin xử lý gia hạn tạm thời trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_09','V511','阮明',9,'太感谢您帮忙协调，我之后一定准时上课不缺勤。','tài gǎn xiè nín bāng máng xié tiáo， wǒ zhī hòu yí dìng zhǔn shí shàng kè bù quē qín。','Em cảm ơn cô rất nhiều vì đã giúp em, sau này em nhất định sẽ đi học đúng giờ, không nghỉ nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT512','SV2','咨询寒暑假居留延期是否需要额外材料',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V512','SIT512','P1','suon_se','tuy_y',NULL,'留学生寒暑假留校，续签必须额外提交加盖学院公章的留校申请，证明假期在校学习安排。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_01','V512','阮明',1,'警官，寒暑假不回国，续居留和学期内续签材料一样吗？','jǐng guān， hán shǔ jià bù huí guó， xù jū liú hé xué qī nèi xù qiān cái liào yī yàng ma？','Chú công an ơi, kỳ nghỉ hè đông không về nước thì hồ sơ gia hạn cư trú có giống hồ sơ gia hạn trong học kỳ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_02','V512','辅警',2,'大体材料相同，额外需要一份假期留校申请书哈。','dà tǐ cái liào xiāng tóng， é wài xū yào yī fèn jià qī liú xiào shēn qǐng shū hā。','Về cơ bản giấy tờ giống nhau, chỉ cần thêm một đơn xin ở lại trường trong kỳ nghỉ thôi nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_03','V512','阮明',3,'留校申请书手写就可以，还是必须打印盖章？','liú xiào shēn qǐng shū shǒu xiě jiù kě yǐ， hái shì bì xū dǎ yìn gài zhāng？','Đơn xin ở lại trường viết tay được không, hay bắt buộc phải in ra?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_04','V512','辅警',4,'打印填写后学院国际处盖章，手写无公章无效。','dǎ yìn tián xiě hòu xué yuàn guó jì chù gài zhāng， shǒu xiě wú gōng zhāng wú xiào。','In ra điền xong rồi đem lên phòng quốc tế của trường đóng dấu, viết tay không có con dấu thì không hợp lệ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_05','V512','阮明',5,'假期留校居留有效期也是一年，还是只给到开学？','jià qī liú xiào jū liú yǒu xiào qī yě shì yī nián， hái shì zhǐ gěi dào kāi xué？','Thời hạn cư trú khi ở lại trường dịp nghỉ cũng là một năm, hay chỉ được cấp đến khi khai giảng thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_06','V512','辅警',6,'统一按学制发放一年有效期，不受寒暑假限制。','tǒng yī àn xué zhì fā fàng yī nián yǒu xiào qī， bù shòu hán shǔ jià xiàn zhì。','Cấp thống nhất theo thời gian học là một năm, không bị giới hạn bởi kỳ nghỉ hè đông đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_07','V512','阮明',7,'清楚了，我回去打印申请书找老师盖章。','qīng chǔ le， wǒ huí qù dǎ yìn shēn qǐng shū zhǎo lǎo shī gài zhāng。','Con rõ rồi ạ, con về in đơn rồi nhờ thầy cô đóng dấu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT513','SV2','校外租房居住，房东不配合办理住宿登记单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V513','SIT513','P1','twist','ban_chinh_thuc',NULL,'出租房屋房东有法定义务配合外籍租客完成社区住宿备案，拒不配合社区可依法约谈整改。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_01','V513','阮明',1,'网格员您好，我在外租房办签证需要住宿登记，房东不肯配合。','wǎng gé yuán nín hǎo， wǒ zài wài zū fáng bàn qiān zhèng xū yào zhù sù dēng jì， fáng dōng bù kěn pèi hé。','Chào anh tổ trưởng dân phố, em thuê nhà ở ngoài, cần làm đăng ký lưu trú để làm visa nhưng chủ nhà không chịu hợp tác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_02','V513','网格员',2,'先跟我说一下房东拒绝配合的具体原因是什么呢？','xiān gēn wǒ shuō yī xià fáng dōng jù jué pèi hé de jù tǐ yuán yīn shì shén me ne？','Em nói cho anh nghe cụ thể lý do chủ nhà từ chối hợp tác là gì được không?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_03','V513','阮明',3,'房东说登记要上交房产证复印件，担心信息泄露不愿意提供。','fáng dōng shuō dēng jì yào shàng jiāo fáng chǎn zhèng fù yìn jiàn， dān xīn xìn xī xiè lòu bù yuàn yì tí gōng。','Chủ nhà bảo đăng ký phải nộp bản photo sổ đỏ, sợ lộ thông tin nên không muốn cung cấp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_04','V513','网格员',4,'外籍租客住宿备案是法定要求，房东有义务配合登记嘛。','wài jí zū kè zhù sù bèi àn shì fǎ dìng yāo qiú， fáng dōng yǒu yì wù pèi hé dēng jì ma。','Đăng ký lưu trú cho người thuê nhà nước ngoài là quy định pháp luật bắt buộc, chủ nhà có nghĩa vụ phải hợp tác đăng ký chứ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_05','V513','阮明',5,'如果房东始终拒绝到场备案，我还有别的办理渠道吗？','rú guǒ fáng dōng shǐ zhōng jù jué dào chǎng bèi àn， wǒ hái yǒu bié de bàn lǐ qú dào ma？','Nếu chủ nhà cứ từ chối có mặt làm đăng ký, em còn kênh nào khác để xử lý không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_06','V513','网格员',6,'我上门和房东沟通劝导，沟通无果会下发书面告知单。','wǒ shàng mén hé fáng dōng gōu tōng quàn dǎo， gōu tōng wú guǒ huì xià fā shū miàn gào zhī dān。','Anh sẽ đến tận nơi trao đổi thuyết phục chủ nhà, nếu không đạt được kết quả thì sẽ gửi văn bản thông báo chính thức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_07','V513','阮明',7,'今天您能联系房东上门办理，我现在在出租屋等候。','jīn tiān nín néng lián xì fáng dōng shàng mén bàn lǐ， wǒ xiàn zài zài chū zū wū děng hòu。','Hôm nay anh có thể liên hệ chủ nhà đến làm việc không, giờ em đang ở nhà thuê chờ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_08','V513','网格员',8,'半小时内到房屋现场，携带备案表格、拍照留存房屋信息。','bàn xiǎo shí nèi dào fáng wū xiàn chǎng， xié dài bèi àn biǎo gé、 pāi zhào liú cún fáng wū xìn xī。','Nửa tiếng nữa anh có mặt tại căn nhà, mang theo biểu mẫu đăng ký, chụp ảnh lưu lại thông tin nhà ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_09','V513','阮明',9,'麻烦您出面协调，没有登记单我没法续办居留签证。','má fán nín chū miàn xié tiáo， méi yǒu dēng jì dān wǒ méi fǎ xù bàn jū liú qiān zhèng。','Phiền anh ra mặt giúp em thu xếp, không có tờ đăng ký thì em không thể làm thủ tục gia hạn visa được.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT514','SV2','续居留预约号约满，咨询线下现场取号方案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V514','SIT514','P1','twist','tuy_y',NULL,'出入境线上预约号资源紧张，线下应急号数量有限，仅针对签证续签人群，新办居留不开放线下现场号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_01','V514','阮明',1,'你好，线上预约系统近七天的续签号全部约满了。','nǐ hǎo， xiàn shàng yù yuē xì tǒng jìn qī tiān de xù qiān hào quán bù yuē mǎn le。','Chào bạn, hệ thống đặt lịch online trong bảy ngày tới đã hết số gia hạn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_02','V514','引导员',2,'线上号源每日定时发放抢号，线下保留少量应急现场号哦。','xiàn shàng hào yuán měi rì dìng shí fā fàng qiǎng hào， xiàn xià bǎo liú shǎo liàng yìng jí xiàn chǎng hào ó。','Số online phát theo giờ cố định mỗi ngày, còn có một ít số khẩn cấp tại chỗ dự phòng đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_03','V514','阮明',3,'现场号几点开始发放，需要一早来排队等候吗？','xiàn chǎng hào jǐ diǎn kāi shǐ fā fàng， xū yào yī zǎo lái pái duì děng hòu ma？','Số tại chỗ phát từ mấy giờ vậy, có phải đến xếp hàng từ sáng sớm không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_04','V514','引导员',4,'早上八点大厅开门发放当日现场号，发完即止不追加。','zǎo shàng bā diǎn dà tīng kāi mén fā fàng dāng rì xiàn chǎng hào， fā wán jí zhǐ bù zhuī jiā。','Tám giờ sáng sảnh mở cửa phát số tại chỗ trong ngày, phát hết là ngừng, không phát thêm đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_05','V514','阮明',5,'现场号只受理续签业务，首次办居留不能用现场号对吧？','xiàn chǎng hào zhǐ shòu lǐ xù qiān yè wù， shǒu cì bàn jū liú bù néng yòng xiàn chǎng hào duì ba？','Số tại chỗ chỉ giải quyết nghiệp vụ gia hạn thôi đúng không, làm cư trú lần đầu thì không dùng được số tại chỗ phải không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_06','V514','引导员',6,'没错，首次居留只能线上预约，续签才有应急线下号。','méi cuò， shǒu cì jū liú zhǐ néng xiàn shàng yù yuē， xù qiān cái yǒu yìng jí xiàn xià hào。','Đúng vậy, cư trú lần đầu chỉ đặt lịch online thôi, gia hạn thì mới có số khẩn cấp tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_07','V514','阮明',7,'那我明天七点半过来排队抢当日现场办理号。','nà wǒ míng tiān qī diǎn bàn guò lái pái duì qiǎng dāng rì xiàn chǎng bàn lǐ hào。','Vậy mai bảy giờ rưỡi mình đến xếp hàng giành số xử lý tại chỗ trong ngày.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT515','SV2','签证办理期间护照上交，申请临时出行证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V515','SIT515','P1','suon_se','chinh_thuc',NULL,'护照上交出入境办理签证期间，无法乘坐交通、入住酒店，必须申请临时出行证明作为替代身份证件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_01','V515','阮明',1,'您好，我的护照上交办理居留续签，周末需要短途出行。','nín hǎo， wǒ de hù zhào shàng jiāo bàn lǐ jū liú xù qiān， zhōu mò xū yào duǎn tú chū xíng。','Xin chào, tôi đang nộp hộ chiếu để làm thủ tục gia hạn cư trú, cuối tuần này tôi cần đi công tác ngắn ngày ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_02','V515','工作人员',2,'可以申请《外国人临时出行证明》，有效期七天呢。','kě yǐ shēn qǐng 《 wài guó rén lín shí chū xíng zhèng míng 》， yǒu xiào qī qī tiān ne。','Anh/chị có thể xin cấp Giấy chứng nhận đi lại tạm thời cho người nước ngoài, có hiệu lực trong bảy ngày ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_03','V515','阮明',3,'办理临时出行证明需要额外提交什么纸质材料？','bàn lǐ lín shí chū xíng zhèng míng xū yào é wài tí jiāo shén me zhǐ zhì cái liào？','Làm giấy chứng nhận đi lại tạm thời thì cần nộp thêm giấy tờ giấy gì nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_04','V515','工作人员',4,'递交一张白底证件照，填写出行目的地即可。','dì jiāo yī zhāng bái dǐ zhèng jiàn zhào， tián xiě chū xíng mù dì dì jí kě。','Nộp một ảnh thẻ nền trắng, điền nơi đến là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_05','V515','阮明',5,'这份临时证明可以乘坐高铁、酒店入住正常使用吗？','zhè fèn lín shí zhèng míng kě yǐ chéng zuò gāo tiě、 jiǔ diàn rù zhù zhèng cháng shǐ yòng ma？','Giấy chứng nhận tạm thời này có thể dùng để đi tàu cao tốc, nhận phòng khách sạn bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_06','V515','工作人员',6,'国内交通、住宿全部通用，等同于临时身份证件。','guó nèi jiāo tōng、 zhù sù quán bù tōng yòng， děng tóng yú lín shí shēn fèn zhèng jiàn。','Dùng được cho cả giao thông và lưu trú trong nước, tương đương với giấy tờ tùy thân tạm thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_07','V515','阮明',7,'等下取办好的居留贴纸时，要同步归还临时证明吧？','děng xià qǔ bàn hǎo de jū liú tiē zhǐ shí， yào tóng bù guī huán lín shí zhèng míng ba？','Lát nữa khi lấy tem cư trú đã làm xong, tôi phải trả lại giấy chứng nhận tạm thời cùng lúc luôn phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_08','V515','工作人员',8,'是的，领取护照当日回收临时出行纸质证明。','shì de， lǐng qǔ hù zhào dāng rì huí shōu lín shí chū xíng zhǐ zhì zhèng míng。','Vâng, ngày nhận lại hộ chiếu thì sẽ thu hồi luôn giấy chứng nhận đi lại tạm thời bằng giấy đó ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_09','V515','阮明',9,'麻烦帮我同步办理，周末出行不用滞留市内了。','má fán bāng wǒ tóng bù bàn lǐ， zhōu mò chū xíng bù yòng zhì liú shì nèi le。','Phiền anh/chị xử lý đồng thời giúp tôi, để cuối tuần tôi có thể đi lại mà không phải ở lại trong thành phố ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT516','SV2','中途休学，咨询居留签证暂停与恢复手续',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V516','SIT516','P1','twist','chinh_thuc',NULL,'留学生休学、退学导致学籍失效，学生居留许可自动失效，需在规定缓冲期内离境，滞留会产生行政处罚。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_01','V516','阮明',1,'老师，我身体原因申请休学半年，想了解居留签证处理方式。','lǎo shī， wǒ shēn tǐ yuán yīn shēn qǐng xiū xué bàn nián， xiǎng liǎo jiě jū liú qiān zhèng chǔ lǐ fāng shì。','Thưa thầy/cô, vì lý do sức khỏe em xin nghỉ học nửa năm, em muốn tìm hiểu về cách xử lý visa cư trú ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_02','V516','老师',2,'休学期间学籍暂停，现有居留许可同步失效，需要限期离境。','xiū xué qī jiān xué jí zàn tíng， xiàn yǒu jū liú xǔ kě tóng bù shī xiào， xū yào xiàn qī lí jìng。','Trong thời gian bảo lưu, tư cách học sinh sẽ tạm ngừng, giấy phép cư trú hiện tại cũng đồng thời hết hiệu lực, em phải xuất cảnh trong thời hạn quy định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_03','V516','阮明',3,'不能办理临时居留留在国内休养，必须返回越南吗？','bù néng bàn lǐ lín shí jū liú liú zài guó nèi xiū yǎng， bì xū fǎn huí yuè nán ma？','Vậy không thể xin cư trú tạm thời để ở lại trong nước điều trị, bắt buộc phải về Việt Nam ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_04','V516','老师',4,'休学无有效在校学籍，不符合学生居留审批标准嘛。','xiū xué wú yǒu xiào zài xiào xué jí， bù fú hé xué shēng jū liú shěn pī biāo zhǔn ma。','Bảo lưu học tập nghĩa là không còn tư cách học sinh hợp lệ, nên không đáp ứng tiêu chuẩn xét duyệt cư trú diện học sinh đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_05','V516','阮明',5,'半年后复学返校，重新办居留要从头提交全套材料？','bàn nián hòu fù xué fǎn xiào， chóng xīn bàn jū liú yào cóng tóu tí jiāo quán tào cái liào？','Sau nửa năm quay lại học, khi xin cư trú lại có phải nộp lại toàn bộ hồ sơ từ đầu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_06','V516','老师',6,'复学后凭复学通知书，按新生流程重新申请居留许可。','fù xué hòu píng fù xué tōng zhī shū， àn xīn shēng liú chéng chóng xīn shēn qǐng jū liú xǔ kě。','Khi quay lại học, em dùng giấy thông báo phục học, làm thủ tục xin cư trú lại theo quy trình như học sinh mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_07','V516','阮明',7,'休学手续办完后，给我几天缓冲时间收拾行李离境？','xiū xué shǒu xù bàn wán hòu， gěi wǒ jǐ tiān huǎn chōng shí jiān shōu shí xíng lǐ lí jìng？','Sau khi hoàn tất thủ tục bảo lưu, thầy/cô cho em mấy ngày để thu xếp hành lý rồi xuất cảnh ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_08','V516','老师',8,'休学备案当日起，给予三十天合法停留缓冲期。','xiū xué bèi àn dāng rì qǐ， jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Kể từ ngày đăng ký bảo lưu, em được gia hạn lưu trú hợp pháp thêm ba mươi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_09','V516','阮明',9,'我清楚规则了，会在缓冲期内安排回国休养。','wǒ qīng chǔ guī zé le， huì zài huǎn chōng qī nèi ān pái huí guó xiū yǎng。','Em đã rõ quy định rồi, em sẽ sắp xếp về nước điều trị trong thời gian gia hạn đó.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT517','SV2','短期出境旅游，咨询居留证是否需要备案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V517','SIT517','P1','suon_se','tuy_y',NULL,'持有有效长期学生居留许可，短期出境旅游无需向出入境报备，仅毕业、休学、永久离境才需要注销备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_01','V517','阮明',1,'警官，我下周出境旅游，有效居留证需要提前备案吗？','jǐng guān， wǒ xià zhōu chū jìng lǚ yóu， yǒu xiào jū liú zhèng xū yào tí qián bèi àn ma？','Chào anh công an, tuần sau em đi du lịch nước ngoài, thẻ cư trú còn hiệu lực thì có cần đăng ký trước không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_02','V517','辅警',2,'短期出国旅游不用线下备案，居留有效期内自由往返哈。','duǎn qī chū guó lǚ yóu bù yòng xiàn xià bèi àn， jū liú yǒu xiào qī nèi zì yóu wǎng fǎn hā。','Đi du lịch ngắn ngày thì không cần đăng ký trực tiếp đâu, trong thời hạn cư trú thì cứ tự do đi lại thôi.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_03','V517','阮明',3,'出境的时候只需要同时出示护照和居留贴纸对吧？','chū jìng de shí hòu zhǐ xū yào tóng shí chū shì hù zhào hé jū liú tiē zhǐ duì ba？','Lúc xuất cảnh em chỉ cần xuất trình hộ chiếu và tem cư trú cùng lúc đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_04','V517','辅警',4,'对，两样证件一并交给海关查验即可。','duì， liǎng yàng zhèng jiàn yī bìng jiāo gěi hǎi guān chá yàn jí kě。','Đúng rồi, đưa cả hai giấy tờ cho hải quan kiểm tra là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_05','V517','阮明',5,'如果出境超过一个月，回来签证会不会受影响？','rú guǒ chū jìng chāo guò yí gè yuè， huí lái qiān zhèng huì bú huì shòu yǐng xiǎng？','Nếu em đi quá một tháng, lúc về visa có bị ảnh hưởng gì không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_06','V517','辅警',6,'只要居留没到期，无论出境时长都不影响入境。','zhǐ yào jū liú méi dào qī， wú lùn chū jìng shí cháng dōu bù yǐng xiǎng rù jìng。','Chỉ cần cư trú chưa hết hạn thì dù đi bao lâu cũng không ảnh hưởng đến việc nhập cảnh lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_07','V517','阮明',7,'明白了，不用额外跑大厅办理出境报备。','míng bái le， bù yòng é wài pǎo dà tīng bàn lǐ chū jìng bào bèi。','Em hiểu rồi, vậy không cần chạy lên sảnh làm thủ tục báo xuất cảnh gì thêm ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT518','SV3','护照丢失，派出所开遗失证明用于补办签证',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V518','SIT518','P1','suon_se','chinh_thuc',NULL,'外籍护照遗失必须先到派出所报案获取回执，无回执无法办理临时通行证明、新护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_01','V518','阮明',1,'警官您好，我的越南护照丢失，前来开具遗失报案回执。','jǐng guān nín hǎo， wǒ de yuè nán hù zhào diū shī， qián lái kāi jù yí shī bào àn huí zhí。','Chào anh công an, em bị mất hộ chiếu Việt Nam, em đến xin biên nhận báo mất ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_02','V518','民警',2,'详细说明丢失时间、路线、随身携带的全部物品吧。','xiáng xì shuō míng diū shī shí jiān、 lù xiàn、 suí shēn xié dài de quán bù wù pǐn ba。','Em nói rõ thời gian mất, lộ trình di chuyển và toàn bộ đồ đạc mang theo lúc đó đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_03','V518','阮明',3,'昨天下午商圈逛街，结账后口袋内护照连同钱包一同遗失。','zuó tiān xià wǔ shāng quān guàng jiē， jié zhàng hòu kǒu dài nèi hù zhào lián tóng qián bāo yī tóng yí shī。','Chiều hôm qua em đi dạo khu trung tâm mua sắm, sau khi thanh toán thì hộ chiếu cùng ví bị mất luôn trong túi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_04','V518','民警',4,'我制作遗失笔录，签字后打印两份报案回执给你留存。','wǒ zhì zuò yí shī bǐ lù， qiān zì hòu dǎ yìn liǎng fèn bào àn huí zhí gěi nǐ liú cún。','Anh lập biên bản mất giấy tờ, sau khi em ký thì anh in hai bản biên nhận báo mất để em giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_05','V518','阮明',5,'一份回执去出入境办临时通行，一份去大使馆补办护照对吗？','yī fèn huí zhí qù chū rù jìng bàn lín shí tōng xíng， yī fèn qù dà shǐ guǎn bǔ bàn hù zhào duì ma？','Một bản em mang lên phòng xuất nhập cảnh xin đi lại tạm thời, một bản gửi đại sứ quán xin cấp lại hộ chiếu, đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_06','V518','民警',6,'两份回执用途分开，务必妥善保管不能丢失。','liǎng fèn huí zhí yòng tú fēn kāi， wù bì tuǒ shàn bǎo guǎn bù néng diū shī。','Hai bản dùng cho hai việc khác nhau, em phải cất giữ cẩn thận, không được làm mất nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_07','V518','阮明',7,'没有这份报案回执，无法办理任何补办证件手续吧？','méi yǒu zhè fèn bào àn huí zhí， wú fǎ bàn lǐ rèn hé bǔ bàn zhèng jiàn shǒu xù ba？','Nếu không có biên nhận báo mất này thì không thể làm bất cứ thủ tục cấp lại giấy tờ nào đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_08','V518','民警',8,'没错，使馆与出入境均强制要求派出所遗失证明。','méi cuò， shǐ guǎn yǔ chū rù jìng jūn qiáng zhì yāo qiú pài chū suǒ yí shī zhèng míng。','Đúng vậy, cả đại sứ quán lẫn phòng xuất nhập cảnh đều bắt buộc phải có giấy xác nhận mất từ công an.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_09','V518','阮明',9,'辛苦您登记备案，证件丢失给大家添麻烦了。','xīn kǔ nín dēng jì bèi àn， zhèng jiàn diū shī gěi dà jiā tiān má fán le。','Cảm ơn anh đã ghi nhận giúp em, việc mất giấy tờ làm phiền mọi người quá.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT519','SV3','居留许可贴纸损毁模糊，申请换发居留贴纸',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V519','SIT519','P1','twist','ban_chinh_thuc',NULL,'居留贴纸磨损、撕毁、信息模糊属于证件损毁，必须换发，旧照片超出半年有效期不能用于新证件办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_01','V519','阮明',1,'您好，我护照上的居留贴纸磨损掉色，信息看不清了。','nín hǎo， wǒ hù zhào shàng de jū liú tiē zhǐ mó sǔn diào sè， xìn xī kàn bù qīng le。','Chào anh/chị, tem cư trú trên hộ chiếu của em bị mòn phai màu, không đọc rõ thông tin được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_02','V519','工作人员',2,'贴纸损毁需要换发居留许可，先提交白底证件照哦。','tiē zhǐ sǔn huǐ xū yào huàn fā jū liú xǔ kě， xiān tí jiāo bái dǐ zhèng jiàn zhào ó。','Tem bị hỏng thì phải xin cấp lại giấy phép cư trú, trước tiên em nộp ảnh thẻ nền trắng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_03','V519','阮明',3,'上次办签证的旧照片还有剩余，直接用旧照片可以吗？','shàng cì bàn qiān zhèng de jiù zhào piān hái yǒu shèng yú， zhí jiē yòng jiù zhào piān kě yǐ ma？','Lần trước làm visa em còn dư ảnh cũ, dùng ảnh cũ luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_04','V519','工作人员',4,'换发证件要求近六个月内新拍摄照片，旧照不予受理嘛。','huàn fā zhèng jiàn yāo qiú jìn liù gè yuè nèi xīn pāi shè zhào piān， jiù zhào bù yǔ shòu lǐ ma。','Cấp lại giấy tờ yêu cầu ảnh chụp trong vòng sáu tháng gần đây, ảnh cũ thì không được chấp nhận đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_05','V519','阮明',5,'楼下大厅自助拍照机可以当场拍摄签证专用照片吗？','lóu xià dà tīng zì zhù pāi zhào jī kě yǐ dāng chǎng pāi shè qiān zhèng zhuān yòng zhào piān ma？','Máy chụp ảnh tự động ở sảnh tầng dưới có chụp được ảnh chuyên dùng cho visa ngay tại chỗ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_06','V519','工作人员',6,'可以，拍完直接带纸质照片回来取号办理换发。','kě yǐ， pāi wán zhí jiē dài zhǐ zhì zhào piān huí lái qǔ hào bàn lǐ huàn fā。','Được chứ, chụp xong em cầm ảnh giấy quay lại đây lấy số làm thủ tục cấp lại luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_07','V519','阮明',7,'换发期间护照需要上交，还是可以自行保管？','huàn fā qī jiān hù zhào xū yào shàng jiāo， hái shì kě yǐ zì xíng bǎo guǎn？','Trong thời gian cấp lại, hộ chiếu có phải nộp lại hay em tự giữ được ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_08','V519','工作人员',8,'全程留存护照七个工作日，如需出行办临时证明。','quán chéng liú cún hù zhào qī gè gōng zuò rì， rú xū chū xíng bàn lín shí zhèng míng。','Hộ chiếu sẽ được giữ lại suốt bảy ngày làm việc, nếu cần đi đâu thì làm giấy xác nhận tạm thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_09','V519','阮明',9,'我现在去拍照，回来递交换发居留贴纸的材料。','wǒ xiàn zài qù pāi zhào， huí lái dì jiāo huàn fā jū liú tiē zhǐ de cái liào。','Vậy giờ em đi chụp ảnh, xong quay lại nộp hồ sơ đổi tem cư trú.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT520','SV3','护照补办完成后，重新补办在华居留许可',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V520','SIT520','P1','suon_se','chinh_thuc',NULL,'补办护照后不能直接沿用旧居留，必须同步补办居留贴纸，新旧护照搭配使用仅短期有效，长期必须换发居留。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_01','V520','阮明',1,'您好，我的新护照已经从使馆取回，补办丢失的居留许可。','nín hǎo， wǒ de xīn hù zhào yǐ jīng cóng shǐ guǎn qǔ huí， bǔ bàn diū shī de jū liú xǔ kě。','Chào anh/chị, em vừa lấy hộ chiếu mới từ đại sứ quán về, giờ em xin cấp lại giấy phép cư trú bị mất ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_02','V520','工作人员',2,'递交新护照、派出所遗失回执、在读证明、住宿登记单。','dì jiāo xīn hù zhào、 pài chū suǒ yí shī huí zhí、 zài dú zhèng míng、 zhù sù dēng jì dān。','Em nộp hộ chiếu mới, biên nhận báo mất của công an, giấy xác nhận đang học và phiếu đăng ký lưu trú nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_03','V520','阮明',3,'旧护照上过期的签证页复印件，也需要一并上交核对吗？','jiù hù zhào shàng guò qī de qiān zhèng yè fù yìn jiàn， yě xū yào yī bìng shàng jiāo hé duì ma？','Bản photo trang visa đã hết hạn trên hộ chiếu cũ có cần nộp kèm để đối chiếu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_04','V520','工作人员',4,'是的，复印件留存系统，用于核对原有居留期限。','shì de， fù yìn jiàn liú cún xì tǒng， yòng yú hé duì yuán yǒu jū liú qī xiàn。','Có chứ, bản photo đó sẽ lưu vào hệ thống để đối chiếu thời hạn cư trú trước đây của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_05','V520','阮明',5,'补办居留许可的办理时长和首次办理一样是七个工作日？','bǔ bàn jū liú xǔ kě de bàn lǐ shí cháng hé shǒu cì bàn lǐ yī yàng shì qī gè gōng zuò rì？','Thời gian xử lý cấp lại giấy phép cư trú có giống như lần đầu là bảy ngày làm việc không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_06','V520','工作人员',6,'流程一致，加急通道三个工作日可取证。','liú chéng yí zhì， jiā jí tōng dào sān gè gōng zuò rì kě qǔ zhèng。','Quy trình giống nhau, nhưng nếu đi kênh khẩn thì ba ngày làm việc là lấy được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_07','V520','阮明',7,'补办的居留有效期和原来丢失的证件剩余时长相同吧？','bǔ bàn de jū liú yǒu xiào qī hé yuán lái diū shī de zhèng jiàn shèng yú shí cháng xiāng tóng ba？','Hiệu lực của giấy cư trú cấp lại có bằng đúng thời gian còn lại của giấy tờ bị mất trước đây không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_08','V520','工作人员',8,'完全同步原有到期日期，不会重新计算一年有效期。','wán quán tóng bù yuán yǒu dào qī rì qī， bú huì chóng xīn jì suàn yī nián yǒu xiào qī。','Hoàn toàn khớp với ngày hết hạn cũ, sẽ không tính lại thời hạn một năm mới đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_09','V520','阮明',9,'全部材料齐全，麻烦受理我的补办申请。','quán bù cái liào qí quán， má fán shòu lǐ wǒ de bǔ bàn shēn qǐng。','Hồ sơ em đã đầy đủ cả rồi, phiền anh/chị tiếp nhận giúp em ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT521','SV3','出境紧急情况无证件，申请出入境临时通行纸',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V521','SIT521','P1','twist','chinh_thuc',NULL,'临时出入境通行证明仅限单次出境，不可用于再次入境中国，回国后需在本国驻华使馆补办正式护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_01','V521','阮明',1,'警官，我明天一早航班回国，护照丢失急需临时通行证件。','jǐng guān， wǒ míng tiān yī zǎo háng bān huí guó， hù zhào diū shī jí xū lín shí tōng xíng zhèng jiàn。','Anh công an ơi, sáng mai em có chuyến bay về nước, hộ chiếu bị mất nên em cần gấp giấy đi lại tạm thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_02','V521','民警',2,'先出示派出所遗失回执，我核对你的全部备案信息。','xiān chū shì pài chū suǒ yí shī huí zhí， wǒ hé duì nǐ de quán bù bèi àn xìn xī。','Em đưa biên nhận báo mất của công an trước, anh kiểm tra lại toàn bộ thông tin đăng ký của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_03','V521','阮明',3,'回执随身携带，但是今天自助拍照机已经停止营业了嘛。','huí zhí suí shēn xié dài， dàn shì jīn tiān zì zhù pāi zhào jī yǐ jīng tíng zhǐ yíng yè le ma。','Em mang theo biên nhận rồi, nhưng hôm nay máy chụp ảnh tự động đã ngừng hoạt động mất rồi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_04','V521','民警',4,'紧急出境可免纸质照片，系统调取之前留存的证件照片。','jǐn jí chū jìng kě miǎn zhǐ zhì zhào piān， xì tǒng diào qǔ zhī qián liú cún de zhèng jiàn zhào piān。','Trường hợp xuất cảnh khẩn cấp thì không cần ảnh giấy, hệ thống sẽ lấy ảnh giấy tờ đã lưu trước đó của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_05','V521','阮明',5,'这份临时通行纸只能用于本次出境，不能再次入境国内对吗？','zhè fèn lín shí tōng xíng zhǐ zhǐ néng yòng yú běn cì chū jìng， bù néng zài cì rù jìng guó nèi duì ma？','Giấy đi lại tạm thời này chỉ dùng cho lần xuất cảnh này thôi, không thể dùng để nhập cảnh lại đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_06','V521','民警',6,'单次出境有效，抵达越南后前往使馆办理新护照。','dān cì chū jìng yǒu xiào， dǐ dá yuè nán hòu qián wǎng shǐ guǎn bàn lǐ xīn hù zhào。','Đúng vậy, chỉ có hiệu lực một lần xuất cảnh, sau khi về đến Việt Nam em ra đại sứ quán làm hộ chiếu mới nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_07','V521','阮明',7,'办理完成当场就能领取通行纸质证明，不用等候工作日？','bàn lǐ wán chéng dāng chǎng jiù néng lǐng qǔ tōng xíng zhǐ zhì zhèng míng， bù yòng děng hòu gōng zuò rì？','Làm xong là em nhận được giấy đi lại tạm thời ngay tại chỗ luôn, không phải chờ thêm ngày làm việc nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_08','V521','民警',8,'紧急出境业务当场办结，十分钟打印完成交付本人。','jǐn jí chū jìng yè wù dāng chǎng bàn jié， shí fēn zhōng dǎ yìn wán chéng jiāo fù běn rén。','Nghiệp vụ khẩn cấp xử lý xong ngay tại chỗ, mười phút là in xong giao tận tay em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_09','V521','阮明',9,'太感谢开通紧急通道，不然我明天无法搭乘航班。','tài gǎn xiè kāi tōng jǐn jí tōng dào， bù rán wǒ míng tiān wú fǎ dā chéng háng bān。','Em cảm ơn anh rất nhiều vì đã mở kênh khẩn cấp, không thì mai em không kịp chuyến bay mất.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT522','SV3','居留卡片丢失，线上挂失后线下补办',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V522','SIT522','P1','suon_se','tuy_y',NULL,'外国人居留卡丢失需线上立即挂失，挂失后原卡直接作废，无法恢复使用，只能线下重新制卡。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_01','V522','阮明',1,'你好，我的外国人居留卡片弄丢了，怎么挂失补办？','nǐ hǎo， wǒ de wài guó rén jū liú kǎ piàn nòng diū le， zěn me guà shī bǔ bàn？','Chào bạn, thẻ cư trú người nước ngoài của mình bị mất rồi, làm sao để báo mất và xin cấp lại vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_02','V522','引导员',2,'先在出入境官方小程序线上挂失锁卡，防止他人冒用哦。','xiān zài chū rù jìng guān fāng xiǎo chéng xù xiàn shàng guà shī suǒ kǎ， fáng zhǐ tā rén mào yòng ó。','Trước tiên bạn vào app xuất nhập cảnh chính thức báo mất và khóa thẻ online để tránh bị người khác lợi dụng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_03','V522','阮明',3,'线上挂失完成，再带什么材料线下补办实体卡片？','xiàn shàng guà shī wán chéng， zài dài shén me cái liào xiàn xià bǔ bàn shí tǐ kǎ piàn？','Báo mất online xong rồi, vậy cần mang thêm giấy tờ gì để làm lại thẻ thật trực tiếp vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_04','V522','引导员',4,'白底证件照、护照、在读证明、住宿登记单四样材料。','bái dǐ zhèng jiàn zhào、 hù zhào、 zài dú zhèng míng、 zhù sù dēng jì dān sì yàng cái liào。','Bốn thứ này nhé: ảnh thẻ nền trắng, hộ chiếu, giấy xác nhận đang học, phiếu đăng ký lưu trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_05','V522','阮明',5,'挂失之后如果捡到卡片，还能解除挂失继续使用吗？','guà shī zhī hòu rú guǒ jiǎn dào kǎ piàn， hái néng jiě chú guà shī jì xù shǐ yòng ma？','Sau khi báo mất mà mình tìm lại được thẻ thì có hủy báo mất để dùng tiếp được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_06','V522','引导员',6,'挂失后卡片永久失效，无论找回都必须重新补办。','guà shī hòu kǎ piàn yǒng jiǔ shī xiào， wú lùn zhǎo huí dōu bì xū chóng xīn bǔ bàn。','Sau khi báo mất thì thẻ mất hiệu lực vĩnh viễn luôn, dù có tìm lại được cũng phải làm thẻ mới thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_07','V522','阮明',7,'挂失操作我现在手机完成，之后取号递交补办材料。','guà shī cāo zuò wǒ xiàn zài shǒu jī wán chéng， zhī hòu qǔ hào dì jiāo bǔ bàn cái liào。','Vậy giờ mình thao tác báo mất trên điện thoại xong, rồi lấy số nộp hồ sơ xin cấp lại nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT523','SV3','旧护照签证页剪角，咨询新旧护照联用规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V523','SIT523','P1','twist','ban_chinh_thuc',NULL,'旧护照到期剪角，居留贴纸短期可新旧护照联用，缓冲期三十天，超时无法正常出入境，必须转移居留许可至新护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_01','V523','阮明',1,'警官，我的旧护照到期剪角换新，居留贴纸还在旧护照上。','jǐng guān， wǒ de jiù hù zhào dào qī jiǎn jiǎo huàn xīn， jū liú tiē zhǐ hái zài jiù hù zhào shàng。','Anh công an ơi, hộ chiếu cũ của em hết hạn bị cắt góc đổi mới rồi, nhưng tem cư trú vẫn còn ở hộ chiếu cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_02','V523','辅警',2,'短期出入境可以新旧两本护照一并出示海关查验呢。','duǎn qī chū rù jìng kě yǐ xīn jiù liǎng běn hù zhào yī bìng chū shì hǎi guān chá yàn ne。','Trường hợp xuất nhập cảnh ngắn ngày thì em có thể xuất trình cả hai cuốn hộ chiếu cũ và mới cho hải quan kiểm tra đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_03','V523','阮明',3,'新旧护照联用有时间限制，不能长期一直这样使用吗？','xīn jiù hù zhào lián yòng yǒu shí jiān xiàn zhì， bù néng cháng qī yì zhí zhè yàng shǐ yòng ma？','Việc dùng chung hai hộ chiếu cũ mới có giới hạn thời gian không, hay có thể dùng lâu dài như vậy luôn ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_04','V523','辅警',4,'联用仅允许三十天缓冲期，超期必须转移居留至新护照嘛。','lián yòng jǐn yǔn xǔ sān shí tiān huǎn chōng qī， chāo qī bì xū zhuǎn yí jū liú zhì xīn hù zhào ma。','Chỉ được phép dùng chung trong ba mươi ngày thôi, quá thời hạn thì bắt buộc phải chuyển cư trú sang hộ chiếu mới nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_05','V523','阮明',5,'转移居留贴纸需要单独预约换发业务，还是续签同步办理？','zhuǎn yí jū liú tiē zhǐ xū yào dān dú yù yuē huàn fā yè wù， hái shì xù qiān tóng bù bàn lǐ？','Chuyển tem cư trú thì cần đặt lịch riêng cho việc đổi cấp, hay làm luôn cùng lúc gia hạn visa ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_06','V523','辅警',6,'单独预约居留信息变更业务，无需等到签证到期。','dān dú yù yuē jū liú xìn xī biàn gēng yè wù， wú xū děng dào qiān zhèng dào qī。','Em đặt lịch riêng cho nghiệp vụ thay đổi thông tin cư trú, không cần chờ đến khi visa hết hạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_07','V523','阮明',7,'那我三天内预约窗口，把居留贴纸转移到新护照上。','nà wǒ sān tiān nèi yù yuē chuāng kǒu， bǎ jū liú tiē zhǐ zhuǎn yí dào xīn hù zhào shàng。','Vậy em sẽ đặt lịch trong ba ngày tới, để chuyển tem cư trú sang hộ chiếu mới.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT524','SV4','校内转专业，办理居留许可信息变更',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V524','SIT524','P1','suon_se','ban_chinh_thuc',NULL,'留学生校内转专业、更换学院，必须三十日内到出入境更新居留证件信息，信息不符会被判定证件失效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_01','V524','阮明',1,'您好，我校内转换专业，来办理居留证件信息变更。','nín hǎo， wǒ xiào nèi zhuǎn huàn zhuān yè， lái bàn lǐ jū liú zhèng jiàn xìn xī biàn gēng。','Chào chị, em chuyển chuyên ngành trong trường, muốn làm thủ tục thay đổi thông tin trên thẻ tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_02','V524','工作人员',2,'递交新专业录取调整证明、护照、白底证件照。','dì jiāo xīn zhuān yè lù qǔ tiáo zhěng zhèng míng、 hù zhào、 bái dǐ zhèng jiàn zhào。','Em nộp giấy xác nhận điều chỉnh chuyên ngành mới, hộ chiếu và ảnh thẻ nền trắng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_03','V524','阮明',3,'只是专业变更，居留到期日会不会同步延后调整？','zhǐ shì zhuān yè biàn gēng， jū liú dào qī rì huì bú huì tóng bù yán hòu tiáo zhěng？','Chỉ đổi chuyên ngành thôi, vậy hạn tạm trú có bị lùi lại theo không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_04','V524','工作人员',4,'到期日期不变，仅更新证件上标注的就读专业。','dào qī rì qī bù biàn， jǐn gēng xīn zhèng jiàn shàng biāo zhù de jiù dú zhuān yè。','Ngày hết hạn giữ nguyên, chỉ cập nhật lại chuyên ngành đang học trên thẻ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_05','V524','阮明',5,'变更业务办理时长多久，当天可以取证吗？','biàn gēng yè wù bàn lǐ shí cháng duō jiǔ， dàng tiān kě yǐ qǔ zhèng ma？','Thủ tục thay đổi này mất bao lâu ạ, có lấy thẻ trong ngày được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_06','V524','工作人员',6,'三个工作日办结，不能当场领取变更后的居留卡。','sān gè gōng zuò rì bàn jié， bù néng dāng chǎng lǐng qǔ biàn gēng hòu de jū liú kǎ。','Ba ngày làm việc mới xong, không lấy thẻ tạm trú mới ngay tại chỗ được đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_07','V524','阮明',7,'信息变更不收取额外手续费，只需要提交材料对吧？','xìn xī biàn gēng bù shōu qǔ é wài shǒu xù fèi， zhǐ xū yào tí jiāo cái liào duì ba？','Thay đổi thông tin không mất phí gì thêm, chỉ cần nộp đủ giấy tờ đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_08','V524','工作人员',8,'校内专业变更属于免费业务，无任何工本费。','xiào nèi zhuān yè biàn gēng shǔ yú miǎn fèi yè wù， wú rèn hé gōng běn fèi。','Đổi chuyên ngành trong trường là miễn phí, không phải đóng lệ phí gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_09','V524','阮明',9,'材料全部备好，麻烦受理信息变更申请。','cái liào quán bù bèi hǎo， má fán shòu lǐ xìn xī biàn gēng shēn qǐng。','Em chuẩn bị đủ hết giấy tờ rồi, nhờ chị tiếp nhận hồ sơ thay đổi thông tin giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT525','SV4','从A校转学至另一城市高校，办理居留迁出迁入',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V525','SIT525','P1','twist','chinh_thuc',NULL,'跨城市转学居留无法异地转移，原城市居留注销失效，抵达新城市三十日内必须重新申请本地学生居留许可。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_01','V525','阮明',1,'老师，我转学去另一城市大学，咨询居留迁出流程。','lǎo shī， wǒ zhuǎn xué qù lìng yī chéng shì dà xué， zī xún jū liú qiān chū liú chéng。','Thưa thầy, em chuyển trường sang thành phố khác, muốn hỏi về thủ tục chuyển đi tạm trú ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_02','V525','老师',2,'先开具转学离校证明，再去本地出入境办理居留迁出备案。','xiān kāi jù zhuǎn xué lí xiào zhèng míng， zài qù běn dì chū rù jìng bàn lǐ jū liú qiān chū bèi àn。','Trước tiên em xin giấy xác nhận chuyển trường thôi học, sau đó đến cơ quan xuất nhập cảnh địa phương làm thủ tục đăng ký chuyển đi tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_03','V525','阮明',3,'迁出备案完成，原有居留许可还能继续使用一段时间吗？','qiān chū bèi àn wán chéng， yuán yǒu jū liú xǔ kě hái néng jì xù shǐ yòng yī duàn shí jiān ma？','Sau khi hoàn tất đăng ký chuyển đi, thẻ tạm trú cũ còn dùng được thêm một thời gian nữa không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_04','V525','老师',4,'迁出当日原居留自动失效，抵达新城市必须三十日内重新办居留嘛。','qiān chū dāng rì yuán jū liú zì dòng shī xiào， dǐ dá xīn chéng shì bì xū sān shí rì nèi chóng xīn bàn jū liú ma。','Ngay ngày làm thủ tục chuyển đi, thẻ tạm trú cũ tự động hết hiệu lực, đến thành phố mới bắt buộc phải làm lại tạm trú trong vòng ba mươi ngày đấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_05','V525','阮明',5,'转学途中跨城市出行，没有有效居留可以凭转学证明通行？','zhuǎn xué tú zhōng kuà chéng shì chū xíng， méi yǒu yǒu xiào jū liú kě yǐ píng zhuǎn xué zhèng míng tōng xíng？','Trong lúc di chuyển giữa các thành phố để chuyển trường, không còn tạm trú hợp lệ thì có thể dùng giấy xác nhận chuyển trường để đi lại không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_06','V525','老师',6,'迁出时出入境会开具三十天过渡临时停留证明用于中转。','qiān chū shí chū rù jìng huì kāi jù sān shí tiān guò dù lín shí tíng liú zhèng míng yòng yú zhōng zhuǎn。','Khi làm thủ tục chuyển đi, cơ quan xuất nhập cảnh sẽ cấp giấy tạm lưu trú quá độ ba mươi ngày để em dùng trong lúc di chuyển.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_07','V525','阮明',7,'新学校接收后，全套居留材料要重新提交一遍？','xīn xué xiào jiē shōu hòu， quán tào jū liú cái liào yào chóng xīn tí jiāo yī biàn？','Sau khi trường mới tiếp nhận, toàn bộ hồ sơ tạm trú có phải nộp lại từ đầu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_08','V525','老师',8,'全部材料重新递交，按新生标准办理当地居留许可。','quán bù cái liào chóng xīn dì jiāo， àn xīn shēng biāo zhǔn bàn lǐ dāng dì jū liú xǔ kě。','Nộp lại toàn bộ hồ sơ, làm theo tiêu chuẩn của sinh viên mới để xin tạm trú tại địa phương.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_09','V525','阮明',9,'我先办好离校转学证明，再去大厅做迁出备案。','wǒ xiān bàn hǎo lí xiào zhuǎn xué zhèng míng， zài qù dà tīng zuò qiān chū bèi àn。','Em sẽ xin giấy xác nhận thôi học chuyển trường trước, rồi ra sảnh làm đăng ký chuyển đi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT526','SV4','更换校外租房地址，10日内办理居留地址变更',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V526','SIT526','P1','that_bai_nhe','tuy_y',NULL,'外籍人员更换居住地址法定十日内向社区更新住宿信息，多次逾期备案会影响后续居留续签审核。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_01','V526','阮明',1,'网格员，我刚换出租房，超过十天没办住宿变更登记。','wǎng gé yuán， wǒ gāng huàn chū zū fáng， chāo guò shí tiān méi bàn zhù sù biàn gēng dēng jì。','Anh ơi, em vừa chuyển chỗ trọ, quá mười ngày rồi mà chưa đăng ký thay đổi chỗ ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_02','V526','网格员',2,'外籍人员换居住地址必须十日之内备案，逾期会有警告记录。','wài jí rén yuán huàn jū zhù dì zhǐ bì xū shí rì zhī nèi bèi àn， yú qī huì yǒu jǐng gào jì lù。','Người nước ngoài đổi chỗ ở là phải khai báo trong vòng mười ngày đấy, trễ hạn là bị ghi cảnh cáo à nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_03','V526','阮明',3,'我搬家后忙着上课完全忘记，现在补办还会罚款吗？','wǒ bān jiā hòu máng zhe shàng kè wán quán wàng jì， xiàn zài bǔ bàn hái huì fá kuǎn ma？','Em chuyển nhà xong bận đi học nên quên mất luôn, giờ làm bù có bị phạt tiền không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_04','V526','网格员',4,'首次轻微超期仅书面警告，多次超期才会产生行政处罚嘛。','shǒu cì qīng wēi chāo qī jǐn shū miàn jǐng gào， duō cì chāo qī cái huì chǎn shēng xíng zhèng chǔ fá ma。','Trễ hạn lần đầu mà nhẹ thì chỉ cảnh cáo bằng văn bản thôi, trễ nhiều lần mới bị xử phạt hành chính nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_05','V526','阮明',5,'补办地址变更需要房东带房产证一起来社区备案吗？','bǔ bàn dì zhǐ biàn gēng xū yào fáng dōng dài fáng chǎn zhèng yì qǐ lái shè qū bèi àn ma？','Làm bù thay đổi địa chỉ có cần chủ nhà mang giấy chứng nhận nhà đất đến khai báo cùng không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_06','V526','网格员',6,'需要房东到场签字备案，同步打印新住宿登记单。','xū yào fáng dōng dào chǎng qiān zì bèi àn， tóng bù dǎ yìn xīn zhù sù dēng jì dān。','Cần chủ nhà có mặt ký tên khai báo, rồi in luôn phiếu đăng ký lưu trú mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_07','V526','阮明',7,'我现在联系房东过来社区，立刻补办地址变更登记。','wǒ xiàn zài lián xì fáng dōng guò lái shè qū， lì kè bǔ bàn dì zhǐ biàn gēng dēng jì。','Giờ em liên hệ chủ nhà qua khu phố ngay, làm bù đăng ký thay đổi địa chỉ luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT527','SV4','护照个人信息更新，同步更新居留证件信息',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V527','SIT527','P1','suon_se','chinh_thuc',NULL,'护照姓名、国籍、证件编号等核心信息变动后，必须同步更新居留许可，证件信息不一致会被判定无效证件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_01','V527','阮明',1,'您好，我的新护照姓名拼写更新，同步变更居留卡信息。','nín hǎo， wǒ de xīn hù zhào xìng míng pīn xiě gēng xīn， tóng bù biàn gēng jū liú kǎ xìn xī。','Chào chị, hộ chiếu mới của em có cập nhật lại cách viết tên, em muốn đồng bộ thay đổi thông tin trên thẻ tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_02','V527','工作人员',2,'递交新护照、使馆出具的信息变更说明文件、证件照片。','dì jiāo xīn hù zhào、 shǐ guǎn chū jù de xìn xī biàn gēng shuō míng wén jiàn、 zhèng jiàn zhào piān。','Anh nộp hộ chiếu mới, văn bản xác nhận thay đổi thông tin do đại sứ quán cấp, và ảnh thẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_03','V527','阮明',3,'居留卡信息变更完成，有效期延续原来的到期时间？','jū liú kǎ xìn xī biàn gēng wán chéng， yǒu xiào qī yán xù yuán lái de dào qī shí jiān？','Sau khi thay đổi thông tin trên thẻ tạm trú xong, thời hạn có giữ nguyên như ngày hết hạn cũ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_04','V527','工作人员',4,'有效期不变，仅更新证件上的姓名、护照编号信息。','yǒu xiào qī bù biàn， jǐn gēng xīn zhèng jiàn shàng de xìng míng、 hù zhào biān hào xìn xī。','Thời hạn không đổi, chỉ cập nhật lại tên và số hộ chiếu trên thẻ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_05','V527','阮明',5,'变更完成后出入境、高铁酒店查验不会出现信息不符？','biàn gēng wán chéng hòu chū rù jìng、 gāo tiě jiǔ diàn chá yàn bú huì chū xiàn xìn xī bù fú？','Sau khi thay đổi xong, lúc xuất nhập cảnh hay kiểm tra ở tàu cao tốc, khách sạn có bị lệch thông tin không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_06','V527','工作人员',6,'系统实时同步更新，全国查验终端同步刷新信息。','xì tǒng shí shí tóng bù gēng xīn， quán guó chá yàn zhōng duān tóng bù shuā xīn xìn xī。','Hệ thống cập nhật đồng bộ theo thời gian thực, các trạm kiểm tra trên toàn quốc cũng làm mới thông tin luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_07','V527','阮明',7,'全套材料整理完毕，麻烦受理信息变更业务。','quán tào cái liào zhěng lǐ wán bì， má fán shòu lǐ xìn xī biàn gēng yè wù。','Em chuẩn bị đầy đủ hồ sơ rồi, nhờ chị tiếp nhận thủ tục thay đổi thông tin giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT528','SV5','咨询留学生合法校外实习签证备案流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V528','SIT528','P1','twist','ban_chinh_thuc',NULL,'外籍留学生无备案校外实习属于非法务工，一旦查实会行政处罚，严重者不予续签居留许可。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_01','V528','阮明',1,'老师，我想找校外企业实习，咨询留学生务工备案流程。','lǎo shī， wǒ xiǎng zhǎo xiào wài qǐ yè shí xí， zī xún liú xué shēng wù gōng bèi àn liú chéng。','Thưa thầy, em muốn tìm doanh nghiệp bên ngoài để thực tập, cho em hỏi quy trình đăng ký làm việc cho lưu học sinh với ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_02','V528','老师',2,'校外实习必须企业、学校、学生三方签订实习协议备案。','xiào wài shí xí bì xū qǐ yè、 xué xiào、 xué shēng sān fāng qiān dìng shí xí xié yì bèi àn。','Thực tập ngoài trường bắt buộc phải có thỏa thuận thực tập ba bên giữa doanh nghiệp, nhà trường và sinh viên để đăng ký.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_03','V528','阮明',3,'不提前备案直接去实习，会不会影响我的居留续签呢？','bù tí qián bèi àn zhí jiē qù shí xí， huì bú huì yǐng xiǎng wǒ de jū liú xù qiān ne？','Nếu không đăng ký trước mà đi thực tập luôn, có ảnh hưởng đến việc gia hạn tạm trú của em không thầy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_04','V528','老师',4,'无备案校外务工属于非法就业，查到会罚款并缩短居留期限嘛。','wú bèi àn xiào wài wù gōng shǔ yú fēi fǎ jiù yè， chá dào huì fá kuǎn bìng suō duǎn jū liú qī xiàn ma。','Đi làm ngoài trường mà không đăng ký là làm việc bất hợp pháp đấy, nếu bị phát hiện sẽ bị phạt tiền và rút ngắn thời hạn tạm trú nữa.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_05','V528','阮明',5,'实习备案每个学期只能办理一次，中途更换企业能重新备案吗？','shí xí bèi àn měi gè xué qī zhǐ néng bàn lǐ yī cì， zhōng tú gēng huàn qǐ yè néng chóng xīn bèi àn ma？','Mỗi học kỳ đăng ký thực tập chỉ được một lần thôi à, giữa chừng đổi doanh nghiệp thì có đăng ký lại được không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_06','V528','老师',6,'中途更换实习单位需要注销原有备案，重新提交三方协议。','zhōng tú gēng huàn shí xí dān wèi xū yào zhù xiāo yuán yǒu bèi àn， chóng xīn tí jiāo sān fāng xié yì。','Đổi đơn vị thực tập giữa chừng thì phải hủy đăng ký cũ, rồi nộp lại thỏa thuận ba bên mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_07','V528','阮明',7,'办理备案需要企业提供营业执照复印件加盖公章吧？','bàn lǐ bèi àn xū yào qǐ yè tí gōng yíng yè zhí zhào fù yìn jiàn jiā gài gōng zhāng ba？','Làm đăng ký thì cần doanh nghiệp cung cấp bản sao giấy phép kinh doanh có đóng dấu đúng không thầy?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_08','V528','老师',8,'没错，企业资质文件是实习备案必备核心材料。','méi cuò， qǐ yè zī zhì wén jiàn shì shí xí bèi àn bì bèi hé xīn cái liào。','Đúng rồi, hồ sơ pháp nhân của doanh nghiệp là giấy tờ bắt buộc quan trọng nhất khi đăng ký thực tập.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_09','V528','阮明',9,'我先和实习企业沟通准备资质材料，再来办理备案。','wǒ xiān hé shí xí qǐ yè gōu tōng zhǔn bèi zī zhì cái liào， zài lái bàn lǐ bèi àn。','Em sẽ trao đổi với doanh nghiệp thực tập để chuẩn bị hồ sơ pháp nhân trước, rồi quay lại làm đăng ký.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT529','SV5','办理留学生校内勤工助学务工备案证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V529','SIT529','P1','suon_se','tuy_y',NULL,'留学生校内勤工助学同样有严格时长限制，校内备案仅学院留存，校外实习必须同步向出入境备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_01','V529','阮明',1,'老师，我申请校内图书馆助教兼职，需要办务工备案吗？','lǎo shī， wǒ shēn qǐng xiào nèi tú shū guǎn zhù jiào jiān zhí， xū yào bàn wù gōng bèi àn ma？','Thầy ơi, em xin làm trợ giảng thư viện trong trường theo diện làm thêm, vậy có phải đăng ký lao động không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_02','V529','老师',2,'校内勤工助学也需要开具勤工助学备案单留存系统哦。','xiào nèi qín gōng zhù xué yě xū yào kāi jù qín gōng zhù xué bèi àn dān liú cún xì tǒng ó。','Làm thêm trong trường cũng phải xin phiếu đăng ký lao động bán thời gian để lưu vào hệ thống đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_03','V529','阮明',3,'校内兼职每周务工时长上限还是二十小时对吧？','xiào nèi jiān zhí měi zhōu wù gōng shí cháng shàng xiàn hái shì èr shí xiǎo shí duì ba？','Làm thêm trong trường thì giới hạn hai mươi tiếng mỗi tuần vẫn đúng không thầy?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_04','V529','老师',4,'学期内每周不超二十小时，寒暑假放宽至四十小时。','xué qī nèi měi zhōu bù chāo èr shí xiǎo shí， hán shǔ jià fàng kuān zhì sì shí xiǎo shí。','Trong học kỳ thì không quá hai mươi tiếng một tuần, nghỉ hè nghỉ đông thì được nới lên bốn mươi tiếng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_05','V529','阮明',5,'这份备案单需要带去出入境更新居留证件信息？','zhè fèn bèi àn dān xū yào dài qù chū rù jìng gēng xīn jū liú zhèng jiàn xìn xī？','Phiếu đăng ký này có cần mang đến cơ quan xuất nhập cảnh để cập nhật thông tin trên thẻ tạm trú không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_06','V529','老师',6,'校内兼职无需去出入境，仅学院内部系统备案存档。','xiào nèi jiān zhí wú xū qù chū rù jìng， jǐn xué yuàn nèi bù xì tǒng bèi àn cún dàng。','Làm thêm trong trường thì không cần ra xuất nhập cảnh đâu, chỉ lưu hồ sơ trong hệ thống nội bộ của khoa thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_07','V529','阮明',7,'那我填好勤工助学申请表，麻烦老师盖章备案。','nà wǒ tián hǎo qín gōng zhù xué shēn qǐng biǎo， má fán lǎo shī gài zhāng bèi àn。','Vậy em điền xong đơn đăng ký làm thêm rồi, nhờ thầy đóng dấu xác nhận giúp em nha.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT530','SV5','咨询逾期打工、超时务工对签证续签的影响',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V530','SIT530','P1','twist','chinh_thuc',NULL,'中国法律严格限制外籍留学生务工时长与务工范围，非法就业会直接影响居留续签，甚至限期离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_01','V530','阮明',1,'警官，如果留学生超时打工或者无备案务工，续签居留会怎样？','jǐng guān， rú guǒ liú xué shēng chāo shí dǎ gōng huò zhě wú bèi àn wù gōng， xù qiān jū liú huì zěn yàng？','Thưa anh, nếu lưu học sinh làm thêm quá giờ hoặc làm việc không đăng ký thì việc gia hạn tạm trú sẽ ra sao ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_02','V530','辅警',2,'首次查实非法务工罚款，居留许可缩短有效期半年呢。','shǒu cì chá shí fēi fǎ wù gōng fá kuǎn， jū liú xǔ kě suō duǎn yǒu xiào qī bàn nián ne。','Lần đầu bị phát hiện làm việc trái phép sẽ bị phạt tiền, thẻ tạm trú bị rút ngắn hiệu lực nửa năm đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_03','V530','阮明',3,'多次违规超时务工，会直接拒绝续签学生居留吗？','duō cì wéi guī chāo shí wù gōng， huì zhí jiē jù jué xù qiān xué shēng jū liú ma？','Vi phạm làm thêm quá giờ nhiều lần thì có bị từ chối gia hạn tạm trú luôn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_04','V530','辅警',4,'两次及以上非法务工记录，出入境直接驳回续签申请嘛。','liǎng cì jí yǐ shàng fēi fǎ wù gōng jì lù， chū rù jìng zhí jiē bó huí xù qiān shēn qǐng ma。','Từ hai lần vi phạm làm việc trái phép trở lên, cơ quan xuất nhập cảnh sẽ bác thẳng đơn xin gia hạn.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_05','V530','阮明',5,'寒暑假四十小时上限，如果超过时长也算违规务工？','hán shǔ jià sì shí xiǎo shí shàng xiàn， rú guǒ chāo guò shí cháng yě suàn wéi guī wù gōng？','Mức trần bốn mươi tiếng trong dịp nghỉ hè nghỉ đông, nếu vượt quá thì có tính là làm việc vi phạm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_06','V530','辅警',6,'无论学期还是假期，超出规定时长均判定非法就业。','wú lùn xué qī hái shì jià qī， chāo chū guī dìng shí cháng jūn pàn dìng fēi fǎ jiù yè。','Dù là trong học kỳ hay kỳ nghỉ, vượt quá thời lượng quy định đều bị xem là việc làm bất hợp pháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_07','V530','阮明',7,'合法备案实习，更换单位忘记注销旧备案会有记录吗？','hé fǎ bèi àn shí xí， gēng huàn dān wèi wàng jì zhù xiāo jiù bèi àn huì yǒu jì lù ma？','Đăng ký thực tập hợp pháp rồi, nếu đổi đơn vị mà quên hủy đăng ký cũ thì có bị ghi nhận vi phạm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_08','V530','辅警',8,'旧备案未注销会判定多单位同时务工，同样违规。','jiù bèi àn wèi zhù xiāo huì pàn dìng duō dān wèi tóng shí wù gōng， tóng yàng wéi guī。','Đăng ký cũ chưa hủy sẽ bị coi là làm việc cùng lúc ở nhiều đơn vị, cũng tính là vi phạm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_09','V530','阮明',9,'我会严格遵守务工时长规定，提前办好全部实习备案。','wǒ huì yán gé zūn shǒu wù gōng shí cháng guī dìng， tí qián bàn hǎo quán bù shí xí bèi àn。','Em sẽ tuân thủ nghiêm ngặt quy định về thời lượng làm thêm, chuẩn bị đầy đủ đăng ký thực tập trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT531','SV6','毕业申请短期停留签证（毕业生留华缓冲期）',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V531','SIT531','P1','suon_se','ban_chinh_thuc',NULL,'留学生毕业后可申请最长180天短期停留缓冲签证，该签证禁止任何形式务工、实习，到期必须离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_01','V531','阮明',1,'您好，我顺利完成学业毕业，申请毕业生短期停留签证。','nín hǎo， wǒ shùn lì wán chéng xué yè bì yè， shēn qǐng bì yè shēng duǎn qī tíng liú qiān zhèng。','Chào chị, em đã hoàn thành khóa học tốt nghiệp thuận lợi, em muốn xin visa lưu trú ngắn hạn cho sinh viên mới tốt nghiệp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_02','V531','工作人员',2,'递交毕业证、毕业离校证明、住宿登记单、证件照片。','dì jiāo bì yè zhèng、 bì yè lí xiào zhèng míng、 zhù sù dēng jì dān、 zhèng jiàn zhào piān。','Anh nộp bằng tốt nghiệp, giấy xác nhận thôi học khi tốt nghiệp, phiếu đăng ký lưu trú và ảnh thẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_03','V531','阮明',3,'短期停留签证最长能办理多久，是三十天还是九十天？','duǎn qī tíng liú qiān zhèng zuì zhǎng néng bàn lǐ duō jiǔ， shì sān shí tiān hái shì jiǔ shí tiān？','Visa lưu trú ngắn hạn này tối đa được bao lâu ạ, là ba mươi ngày hay chín mươi ngày?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_04','V531','工作人员',4,'毕业生缓冲居留最长一百八十天，可自由选择时长。','bì yè shēng huǎn chōng jū liú zuì zhǎng yì bǎi bā shí tiān， kě zì yóu xuǎn zé shí cháng。','Thời gian đệm sau tốt nghiệp tối đa là một trăm tám mươi ngày, được tự chọn thời hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_05','V531','阮明',5,'这段短期居留期间，能不能正常办理校外实习备案？','zhè duàn duǎn qī jū liú qī jiān， néng bù néng zhèng cháng bàn lǐ xiào wài shí xí bèi àn？','Trong thời gian lưu trú ngắn hạn này, em có thể đăng ký thực tập bên ngoài trường bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_06','V531','工作人员',6,'毕业短期停留签证禁止务工、实习，仅用于旅游采购。','bì yè duǎn qī tíng liú qiān zhèng jìn zhǐ wù gōng、 shí xí， jǐn yòng yú lǚ yóu cǎi gòu。','Visa ngắn hạn sau tốt nghiệp cấm làm việc, cấm thực tập, chỉ dùng để du lịch hay mua sắm thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_07','V531','阮明',7,'缓冲期到期必须离境，无法再次延期对吗？','huǎn chōng qī dào qī bì xū lí jìng， wú fǎ zài cì yán qī duì ma？','Hết thời gian đệm là bắt buộc phải xuất cảnh, không thể gia hạn thêm lần nữa đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_08','V531','工作人员',8,'无特殊重大事由，毕业短期签证不予二次延期。','wú tè shū zhòng dà shì yóu， bì yè duǎn qī qiān zhèng bù yǔ èr cì yán qī。','Nếu không có lý do đặc biệt quan trọng thì visa ngắn hạn sau tốt nghiệp sẽ không được gia hạn lần hai.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_09','V531','阮明',9,'全部材料备齐，麻烦受理短期停留签证申请。','quán bù cái liào bèi qí， má fán shòu lǐ duǎn qī tíng liú qiān zhèng shēn qǐng。','Em chuẩn bị đầy đủ hồ sơ rồi, nhờ chị tiếp nhận đơn xin visa lưu trú ngắn hạn giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT532','SV6','办理留学回国人员证明，用于境外学历认证',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V532','SIT532','P1','twist','ban_chinh_thuc',NULL,'留学回国人员证明是境外学历认证必备材料，需要完整留存全部在华居留、出入境记录，证件丢失需打印官方流水补充。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_01','V532','阮明',1,'老师，我毕业要办留学回国证明，用来回国做学历认证。','lǎo shī， wǒ bì yè yào bàn liú xué huí guó zhèng míng， yòng lái huí guó zuò xué lì rèn zhèng。','Thầy ơi, em tốt nghiệp rồi cần làm giấy chứng nhận du học sinh về nước, để về nước công nhận bằng cấp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_02','V532','老师',2,'需要提交护照全套签证页复印件、毕业证、毕业离校回执。','xū yào tí jiāo hù zhào quán tào qiān zhèng yè fù yìn jiàn、 bì yè zhèng、 bì yè lí xiào huí zhí。','Cần nộp bản photo toàn bộ trang visa trong hộ chiếu, bằng tốt nghiệp, và giấy biên nhận rời trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_03','V532','阮明',3,'我的旧护照剪角丢失，只有新护照复印件可以提交吗？','wǒ de jiù hù zhào jiǎn jiǎo diū shī， zhǐ yǒu xīn hù zhào fù yìn jiàn kě yǐ tí jiāo ma？','Hộ chiếu cũ của em bị cắt góc và thất lạc rồi, chỉ có bản photo hộ chiếu mới thì có nộp được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_04','V532','老师',4,'缺少完整在华居留记录页面，暂时无法开具回国证明嘛。','quē shǎo wán zhěng zài huá jū liú jì lù yè miàn， zàn shí wú fǎ kāi jù huí guó zhèng míng ma。','Thiếu trang ghi đầy đủ quá trình lưu trú tại Trung Quốc thì tạm thời không thể cấp giấy chứng nhận về nước được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_05','V532','阮明',5,'派出所能打印出入境全部入境出境记录替代旧护照复印件吗？','pài chū suǒ néng dǎ yìn chū rù jìng quán bù rù jìng chū jìng jì lù tì dài jiù hù zhào fù yìn jiàn ma？','Đồn công an có thể in toàn bộ hồ sơ xuất nhập cảnh để thay cho bản photo hộ chiếu cũ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_06','V532','老师',6,'可以，去出入境大厅打印完整出入境流水作为补充材料。','kě yǐ， qù chū rù jìng dà tīng dǎ yìn wán zhěng chū rù jìng liú shuǐ zuò wéi bǔ chōng cái liào。','Được, em ra sảnh xuất nhập cảnh in đầy đủ lịch sử xuất nhập cảnh làm tài liệu bổ sung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_07','V532','阮明',7,'我先去打印出入境记录，补齐材料再来申请回国证明。','wǒ xiān qù dǎ yìn chū rù jìng jì lù， bǔ qí cái liào zài lái shēn qǐng huí guó zhèng míng。','Vậy em đi in hồ sơ xuất nhập cảnh trước, bổ sung đủ giấy tờ rồi quay lại xin giấy chứng nhận về nước ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT533','SV6','退学终止学业，注销有效居留许可限期离境',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V533','SIT533','P1','that_bai_nhe','chinh_thuc',NULL,'退学学籍终止，学生居留许可注销，缓冲期仅用于收拾行李离境，缓冲到期无合法续签渠道，超期属于非法滞留。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_01','V533','阮明',1,'警官，我办理退学手续，前来注销现有的学生居留许可。','jǐng guān， wǒ bàn lǐ tuì xué shǒu xù， qián lái zhù xiāo xiàn yǒu de xué shēng jū liú xǔ kě。','Thưa cán bộ, tôi làm thủ tục thôi học, đến để hủy thẻ cư trú diện học sinh hiện tại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_02','V533','民警',2,'递交退学离校证明，系统注销居留后给予三十天合法停留缓冲期。','dì jiāo tuì xué lí xiào zhèng míng， xì tǒng zhù xiāo jū liú hòu jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Anh nộp giấy xác nhận thôi học rời trường, sau khi hệ thống hủy cư trú sẽ có ba mươi ngày lưu trú hợp pháp để giải quyết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_03','V533','阮明',3,'三十天缓冲期内可以外出旅游，不受出行限制吗？','sān shí tiān huǎn chōng qī nèi kě yǐ wài chū lǚ yóu， bù shòu chū xíng xiàn zhì ma？','Trong ba mươi ngày đó tôi có thể đi du lịch, không bị hạn chế đi lại đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_04','V533','民警',4,'出行不受限，但缓冲到期必须离境，不能申请续签延期。','chū xíng bù shòu xiàn， dàn huǎn chōng dào qī bì xū lí jìng， bù néng shēn qǐng xù qiān yán qī。','Đi lại không bị hạn chế, nhưng hết thời hạn ba mươi ngày bắt buộc phải xuất cảnh, không thể xin gia hạn thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_05','V533','阮明',5,'如果三十天内没有买到回国机票，超期停留会如何处罚？','rú guǒ sān shí tiān nèi méi yǒu mǎi dào huí guó jī piào， chāo qī tíng liú huì rú hé chǔ fá？','Nếu trong ba mươi ngày không mua được vé máy bay về nước thì lưu trú quá hạn sẽ bị xử phạt như thế nào?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_06','V533','民警',6,'退学后无有效学籍，超期一日产生对应罚款，还留下不良入境记录。','tuì xué hòu wú yǒu xiào xué jí， chāo qī yī rì chǎn shēng duì yìng fá kuǎn， hái liú xià bù liáng rù jìng jì lù。','Sau khi thôi học không còn tư cách học sinh hợp lệ, quá hạn một ngày sẽ bị phạt tương ứng, còn để lại hồ sơ nhập cảnh không tốt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_07','V533','阮明',7,'缓冲期内只能单次出境，中途回国后无法再次入境中国？','huǎn chōng qī nèi zhǐ néng dān cì chū jìng， zhōng tú huí guó hòu wú fǎ zài cì rù jìng zhōng guó？','Trong thời gian giải quyết chỉ được xuất cảnh một lần, nếu về nước giữa chừng thì không thể nhập cảnh Trung Quốc lại nữa phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_08','V533','民警',8,'居留注销后签证同步失效，离境后不能再次入境。','jū liú zhù xiāo hòu qiān zhèng tóng bù shī xiào， lí jìng hòu bù néng zài cì rù jìng。','Sau khi hủy cư trú thì visa cũng mất hiệu lực theo, xuất cảnh rồi thì không thể nhập cảnh lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_09','V533','阮明',9,'我会在三十天缓冲期内订购机票按时返回越南。','wǒ huì zài sān shí tiān huǎn chōng qī nèi dìng gòu jī piào àn shí fǎn huí yuè nán。','Tôi sẽ đặt vé máy bay trong ba mươi ngày để về Việt Nam đúng hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT534','SV6','签证到期前彻底回国，咨询居留注销流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V534','SIT534','P1','suon_se','tuy_y',NULL,'留学生永久离境建议主动注销居留许可，证件到期自动失效虽无罚款，但会提升下次来华签证的审核严格程度。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_01','V534','阮明',1,'警官，我毕业直接回国不再来华，需要注销居留许可吗？','jǐng guān， wǒ bì yè zhí jiē huí guó bù zài lái huá， xū yào zhù xiāo jū liú xǔ kě ma？','Anh công an ơi, em tốt nghiệp về nước luôn không quay lại Trung Quốc nữa, vậy có cần hủy thẻ cư trú không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_02','V534','辅警',2,'长期离境建议提前注销居留，避免休眠证件产生异常记录哈。','cháng qī lí jìng jiàn yì tí qián zhù xiāo jū liú， bì miǎn xiū mián zhèng jiàn chǎn shēng yì cháng jì lù hā。','Nếu rời đi lâu dài thì nên hủy cư trú trước đi, tránh để giấy tờ không dùng lại phát sinh ghi nhận bất thường đó.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_03','V534','阮明',3,'不主动注销，居留到期自动失效会不会留下负面记录？','bù zhǔ dòng zhù xiāo， jū liú dào qī zì dòng shī xiào huì bú huì liú xià fù miàn jì lù？','Nếu không chủ động hủy, để cư trú tự động hết hạn thì có để lại ghi nhận xấu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_04','V534','辅警',4,'到期自动失效无处罚，但下次申请来华签证会增加审核难度。','dào qī zì dòng shī xiào wú chǔ fá， dàn xià cì shēn qǐng lái huá qiān zhèng huì zēng jiā shěn hé nán dù。','Hết hạn tự động thì không bị phạt, nhưng lần sau xin visa sang Trung Quốc sẽ bị xét duyệt khó hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_05','V534','阮明',5,'注销居留只需要带护照，不用额外准备其他证明？','zhù xiāo jū liú zhǐ xū yào dài hù zhào， bù yòng é wài zhǔn bèi qí tā zhèng míng？','Hủy cư trú chỉ cần mang hộ chiếu thôi, không cần chuẩn bị thêm giấy tờ gì khác đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_06','V534','辅警',6,'携带毕业证、护照现场办理注销，当场打印注销回执。','xié dài bì yè zhèng、 hù zhào xiàn chǎng bàn lǐ zhù xiāo， dāng chǎng dǎ yìn zhù xiāo huí zhí。','Mang theo bằng tốt nghiệp, hộ chiếu đến làm trực tiếp, xong là in ngay biên nhận hủy cư trú tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_07','V534','阮明',7,'回国之后如果再来留学，凭注销回执办理新签证更顺畅？','huí guó zhī hòu rú guǒ zài lái liú xué， píng zhù xiāo huí zhí bàn lǐ xīn qiān zhèng gèng shùn chàng？','Sau khi về nước nếu em quay lại du học thì cầm biên nhận hủy cư trú này xin visa mới sẽ thuận lợi hơn phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_08','V534','辅警',8,'是的，完整注销记录有利于后续签证审核。','shì de， wán zhěng zhù xiāo jì lù yǒu lì yú hòu xù qiān zhèng shěn hé。','Đúng vậy, hồ sơ hủy cư trú đầy đủ sẽ có lợi cho việc xét duyệt visa sau này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_09','V534','阮明',9,'那我离校前提前来大厅办理居留注销手续。','nà wǒ lí xiào qián tí qián lái dà tīng bàn lǐ jū liú zhù xiāo shǒu xù。','Vậy trước khi rời trường em sẽ ra sảnh làm thủ tục hủy cư trú sớm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT535','SV6','毕业短期签证到期无法按时离境，申请延期缓冲',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V535','SIT535','P1','twist','chinh_thuc',NULL,'毕业生短期缓冲签证一般不可延期，仅航班取消、重病住院等不可抗力可短期延长停留期限，且需缴纳签证工本费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_01','V535','阮明',1,'您好，我的毕业短期停留签证即将到期，机票延误无法按时离境。','nín hǎo， wǒ de bì yè duǎn qī tíng liú qiān zhèng jí jiāng dào qī， jī piào yán wù wú fǎ àn shí lí jìng。','Chào anh chị, visa lưu trú ngắn hạn diện tốt nghiệp của tôi sắp hết hạn, nhưng chuyến bay bị hoãn nên không thể xuất cảnh đúng hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_02','V535','工作人员',2,'毕业短期签证原则上不予延期，仅突发客观事由可特殊审批。','bì yè duǎn qī qiān zhèng yuán zé shàng bù yǔ yán qī， jǐn tū fā kè guān shì yóu kě tè shū shěn pī。','Về nguyên tắc visa ngắn hạn diện tốt nghiệp không được gia hạn, chỉ những trường hợp khách quan đột xuất mới được xét duyệt đặc biệt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_03','V535','阮明',3,'国际航班大面积取消，航空公司开具了延误证明作为凭证。','guó jì háng bān dà miàn jī qǔ xiāo， háng kōng gōng sī kāi jù le yán wù zhèng míng zuò wéi píng zhèng。','Các chuyến bay quốc tế bị hủy trên diện rộng, hãng hàng không đã cấp giấy xác nhận hoãn chuyến làm bằng chứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_04','V535','工作人员',4,'航班延误属于客观特殊情况，最多给予十五天短期延期嘛。','háng bān yán wù shǔ yú kè guān tè shū qíng kuàng， zuì duō jǐ yǔ shí wǔ tiān duǎn qī yán qī ma。','Hoãn chuyến bay thuộc trường hợp khách quan đặc biệt, tối đa sẽ được gia hạn ngắn hạn mười lăm ngày thôi nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_05','V535','阮明',5,'十五天延期需要额外收取签证手续费，还是免费办理？','shí wǔ tiān yán qī xū yào é wài shōu qǔ qiān zhèng shǒu xù fèi， hái shì miǎn fèi bàn lǐ？','Gia hạn mười lăm ngày này có phải đóng thêm phí thủ tục visa không, hay là làm miễn phí ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_06','V535','工作人员',6,'短期延期统一收取标准签证工本费，无法免除费用。','duǎn qī yán qī tǒng yī shōu qǔ biāo zhǔn qiān zhèng gōng běn fèi， wú fǎ miǎn chú fèi yòng。','Gia hạn ngắn hạn vẫn thu phí làm chứng visa theo mức chuẩn, không thể miễn phí được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_07','V535','阮明',7,'递交航空公司延误证明、护照、白底照片即可受理对吗？','dì jiāo háng kōng gōng sī yán wù zhèng míng、 hù zhào、 bái dǐ zhào piān jí kě shòu lǐ duì ma？','Vậy tôi nộp giấy xác nhận hoãn chuyến của hãng hàng không, hộ chiếu, ảnh nền trắng là được tiếp nhận đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_08','V535','工作人员',8,'全部材料齐全，三个工作日完成延期审批制证。','quán bù cái liào qí quán， sān gè gōng zuò rì wán chéng yán qī shěn pī zhì zhèng。','Đầy đủ giấy tờ thì trong ba ngày làm việc sẽ hoàn tất xét duyệt và cấp chứng nhận gia hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_09','V535','阮明',9,'我携带航班延误证明，现在递交延期申请材料。','wǒ xié dài háng bān yán wù zhèng míng， xiàn zài dì jiāo yán qī shēn qǐng cái liào。','Tôi mang theo giấy xác nhận hoãn chuyến bay, bây giờ xin nộp hồ sơ xin gia hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT601','SF1','下载注册国际通用视频软件，和父母跨国视频通话',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V601','SIT601','P1','suon_se','tuy_y',NULL,'国内本土社交软件海外受限，留学生普遍使用国际通用通讯软件和境外家人联络。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_01','V601','阮明',1,'小林，我想装一款国外能用的视频软件跟爸妈通话，你知道哪款好用吗？','xiǎo lín， wǒ xiǎng zhuāng yī kuǎn guó wài néng yòng de shì pín ruǎn jiàn gēn bà mā tōng huà， nǐ zhī dào nǎ kuǎn hǎo yòng ma？','Tiểu Lâm ơi, tớ muốn cài một app video dùng được ở nước ngoài để gọi cho bố mẹ, cậu biết app nào dùng ngon không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_02','V601','小林',2,'这款APP国内外都能互通，下载之后用邮箱注册就行啦。','zhè kuǎn APP guó nèi wài dōu néng hù tōng， xià zài zhī hòu yòng yóu xiāng zhù cè jiù xíng la。','App này trong ngoài nước đều dùng liên thông được, tải về rồi đăng ký bằng email là xong ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_03','V601','阮明',3,'国内手机号注册的话，越南那边收得到验证码吗？','guó nèi shǒu jī hào zhù cè de huà， yuè nán nà biān shōu dé dào yàn zhèng mǎ ma？','Nếu đăng ký bằng số điện thoại trong nước thì bên Việt Nam có nhận được mã xác nhận không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_04','V601','小林',4,'手机号跨国有延迟，直接绑定邮箱登录最稳妥呢。','shǒu jī hào kuà guó yǒu yán chí， zhí jiē bǎng dìng yóu xiāng dēng lù zuì wěn tuǒ ne。','Số điện thoại xuyên quốc gia hay bị chậm lắm, gắn thẳng email để đăng nhập là chắc ăn nhất đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_05','V601','阮明',5,'注册完成后，直接搜索爸妈的账号就能发起视频吗？','zhù cè wán chéng hòu， zhí jiē sōu suǒ bà mā de zhàng hào jiù néng fā qǐ shì pín ma？','Đăng ký xong là chỉ cần tìm tài khoản của bố mẹ rồi gọi video luôn được hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_06','V601','小林',6,'没错，还能发照片、短视频，日常报平安很方便。','méi cuò， hái néng fā zhào piān、 duǎn shì pín， rì cháng bào píng ān hěn fāng biàn。','Đúng rồi, còn gửi được ảnh, video ngắn nữa, báo bình an hàng ngày tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_07','V601','阮明',7,'太好了，你教我一步步注册，今晚就能跟家里视频。','tài hǎo le， nǐ jiāo wǒ yí bù bù zhù cè， jīn wǎn jiù néng gēn jiā lǐ shì pín。','Tuyệt quá, cậu chỉ tớ đăng ký từng bước với, tối nay là gọi video về nhà được luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT602','SF1','宿舍WiFi卡顿，求助室友调试网络方便和家人打电话',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V602','SIT602','P1','twist','tuy_y',NULL,'高校宿舍晚八点至十点是网络使用高峰，多人同时联网会造成网速变慢、跨国视频卡顿。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_01','V602','阮明',1,'我一打开视频软件网络就卡顿，根本没法跟爸妈正常通话啊。','wǒ yī dǎ kāi shì pín ruǎn jiàn wǎng luò jiù kǎ dùn， gēn běn méi fǎ gēn bà mā zhèng cháng tōng huà a。','Tớ vừa mở app video lên là mạng giật liền, chẳng thể nào gọi bình thường với bố mẹ được cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_02','V602','小林',2,'是不是宿舍同时好几个人连WiFi，带宽被占满了？','shì bú shì sù shè tóng shí hǎo jǐ gè rén lián WiFi， dài kuān bèi zhàn mǎn le？','Có phải lúc đó ký túc xá có mấy người cùng dùng WiFi nên nghẽn băng thông không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_03','V602','阮明',3,'刚才隔壁宿舍也在刷视频，我切换手机流量试试还是卡嘛。','gāng cái gé bì sù shè yě zài shuā shì pín， wǒ qiè huàn shǒu jī liú liàng shì shì hái shì kǎ ma。','Vừa nãy phòng bên cạnh cũng xem video, tớ thử chuyển sang 4G thì vẫn giật ấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_04','V602','小林',4,'我教你断开自动连接的多余设备，路由器重启一下会流畅很多。','wǒ jiāo nǐ duàn kāi zì dòng lián jiē de duō yú shè bèi， lù yóu qì zhòng qǐ yī xià huì liú chàng hěn duō。','Để tớ chỉ cậu ngắt bớt mấy thiết bị tự kết nối thừa, rồi khởi động lại router là mượt hơn hẳn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_05','V602','阮明',5,'重启路由器之后，跨国视频延迟能降低多少？','chóng qǐ lù yóu qì zhī hòu， kuà guó shì pín yán chí néng jiàng dī duō shǎo？','Khởi động lại router xong thì độ trễ gọi video xuyên quốc gia giảm được bao nhiêu vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_06','V602','小林',6,'至少少一半卡顿，避开晚间八点上网高峰效果更好。','zhì shǎo shǎo yí bàn kǎ dùn， bì kāi wǎn jiān bā diǎn shàng wǎng gāo fēng xiào guǒ gèng hǎo。','Ít nhất giảm được một nửa tình trạng giật, mà tránh giờ cao điểm tám giờ tối thì càng mượt hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_07','V602','阮明',7,'我现在跟着你的步骤操作，等下再打视频电话。','wǒ xiàn zài gēn zhe nǐ de bù zhòu cāo zuò， děng xià zài dǎ shì pín diàn huà。','Giờ tớ làm theo các bước cậu chỉ đây, lát nữa gọi video lại thử.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT603','SF1','时差冲突，错过和父母固定视频时间，重新约定时段',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V603','SIT603','P1','suon_se','tuy_y',NULL,'跨国跨时区留学生和家人一般会约定固定通话时间，临时无法上线必须提前留言报平安，避免家人过度担忧。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_01','V603','阮明',1,'昨天上课拖堂，错过了和爸妈约定的视频时间，他们一直等我。','zuó tiān shàng kè tuō táng， cuò guò le hé bà mā yuē dìng de shì pín shí jiān， tā men yì zhí děng wǒ。','Hôm qua học kéo dài quá giờ, tớ lỡ mất giờ hẹn gọi video với bố mẹ, ông bà chờ mãi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_02','V603','苏雯',2,'越南和国内有一小时时差，你可以提前调整固定联络时段哦。','yuè nán hé guó nèi yǒu yī xiǎo shí shí chà， nǐ kě yǐ tí qián tiáo zhěng gù dìng lián luò shí duàn ó。','Việt Nam với Trung Quốc lệch nhau một tiếng, cậu điều chỉnh sớm giờ hẹn cố định đi nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_03','V603','阮明',3,'我这边晚上七点，越南就是傍晚六点，这个时间他们刚好下班。','wǒ zhè biān wǎn shàng qī diǎn， yuè nán jiù shì bàng wǎn liù diǎn， zhè ge shí jiān tā men gāng hǎo xià bān。','Bên này bảy giờ tối thì bên Việt Nam là sáu giờ chiều, đúng lúc bố mẹ tan làm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_04','V603','苏雯',4,'那你跟家里重新敲定这个时间，提前发消息提醒他们上线吧。','nà nǐ gēn jiā lǐ chóng xīn qiāo dìng zhè ge shí jiān， tí qián fā xiāo xī tí xǐng tā men shàng xiàn ba。','Vậy cậu chốt lại giờ này với gia đình, nhắn tin nhắc họ lên mạng trước nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_05','V603','阮明',5,'我昨天临时缺场，爸妈还以为我出了什么事，特别担心。','wǒ zuó tiān lín shí quē chǎng， bà mā hái yǐ wéi wǒ chū le shén me shì， tè bié dān xīn。','Hôm qua tớ tự dưng vắng mặt, bố mẹ tưởng tớ xảy ra chuyện gì, lo lắng lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_06','V603','苏雯',6,'下次如果有课，提前发文字留言告知家人，免得他们焦虑。','xià cì rú guǒ yǒu kè， tí qián fā wén zì liú yán gào zhī jiā rén， miǎn de tā men jiāo lǜ。','Lần sau nếu có giờ học thì nhắn tin báo trước cho gia đình, để họ khỏi lo lắng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_07','V603','阮明',7,'我记下了，今晚提前跟家里敲定新的视频时段。','wǒ jì xià le， jīn wǎn tí qián gēn jiā lǐ qiāo dìng xīn de shì pín shí duàn。','Tớ ghi nhớ rồi, tối nay sẽ chốt trước giờ gọi video mới với gia đình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT604','SF1','软件登录失败、账号被锁，找同学帮忙找回账号',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V604','SIT604','P1','that_bai_nhe','tuy_y',NULL,'公共网络存在安全风险，跨国通讯软件检测到异地登录会自动锁号，保护用户隐私与账号安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_01','V604','阮明',1,'糟糕，我的视频软件账号提示异常登录，直接被系统锁住了。','zāo gāo， wǒ de shì pín ruǎn jiàn zhàng hào tí shì yì cháng dēng lù， zhí jiē bèi xì tǒng suǒ zhù le。','Chết rồi, tài khoản app video của tớ báo đăng nhập bất thường, bị hệ thống khóa luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_02','V604','小林',2,'你是不是切换手机、频繁换WiFi登录，系统判定有风险？','nǐ shì bú shì qiè huàn shǒu jī、 pín fán huàn WiFi dēng lù， xì tǒng pàn dìng yǒu fēng xiǎn？','Có phải cậu đổi điện thoại, đổi WiFi liên tục nên hệ thống thấy đáng ngờ không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_03','V604','阮明',3,'昨天去图书馆连公共网络登录过，之后回家就登不上去嘛。','zuó tiān qù tú shū guǎn lián gōng gòng wǎng luò dēng lù guò， zhī hòu huí jiā jiù dēng bù shàng qù ma。','Hôm qua tớ ra thư viện dùng mạng công cộng để đăng nhập, xong về nhà là không vào được nữa ấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_04','V604','小林',4,'解锁需要邮箱收验证链接，你注册时绑定的邮箱还能正常使用吗？','jiě suǒ xū yào yóu xiāng shōu yàn zhèng liàn jiē， nǐ zhù cè shí bǎng dìng de yóu xiāng hái néng zhèng cháng shǐ yòng ma？','Mở khóa cần email nhận link xác nhận, email cậu đăng ký lúc trước còn dùng được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_05','V604','阮明',5,'邮箱密码我记混了，现在双重验证全部卡住没法操作。','yóu xiāng mì mǎ wǒ jì hùn le， xiàn zài shuāng chóng yàn zhèng quán bù kǎ zhù méi fǎ cāo zuò。','Tớ nhớ nhầm mật khẩu email rồi, giờ xác thực hai lớp bị kẹt cứng không thao tác được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_06','V604','小林',6,'只能先找回邮箱密码，才能解锁通讯软件账号，一步一步来。','zhǐ néng xiān zhǎo huí yóu xiāng mì mǎ， cái néng jiě suǒ tōng xùn ruǎn jiàn zhàng hào， yí bù yí bù lái。','Chỉ có cách tìm lại mật khẩu email trước, mới mở khóa được tài khoản app nhắn tin, làm từng bước một thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_07','V604','阮明',7,'麻烦你陪我操作，不然我今天完全联系不上家里人。','má fán nǐ péi wǒ cāo zuò， bù rán wǒ jīn tiān wán quán lián xì bù shàng jiā lǐ rén。','Phiền cậu ngồi cùng chỉ tớ với, không thì hôm nay tớ chẳng liên lạc được với gia đình luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT605','SF1','不会操作美颜、屏幕共享，请教室友教自己给家人展示校园',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V605','SIT605','P1','suon_se','tuy_y',NULL,'国际视频软件自带基础美颜、屏幕共享功能，留学生常用来实时展示校园、宿舍生活给海外亲人。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_01','V605','阮明',1,'我想给爸妈看看校园风景，不知道怎么打开屏幕共享功能啊。','wǒ xiǎng gěi bà mā kàn kàn xiào yuán fēng jǐng， bù zhī dào zěn me dǎ kāi píng mù gòng xiǎng gōng néng a。','Mình muốn cho bố mẹ xem cảnh trường học, mà chẳng biết bật tính năng chia sẻ màn hình kiểu gì cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_02','V605','小林',2,'视频通话界面下方有分享按钮，点一下就能同步实景画面呢。','shì pín tōng huà jiè miàn xià fāng yǒu fēn xiǎng àn niǔ， diǎn yī xià jiù néng tóng bù shí jǐng huà miàn ne。','Ở dưới màn hình gọi video có nút chia sẻ đó, bấm một cái là đồng bộ hình ảnh thực tế ngay.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_03','V605','阮明',3,'另外画面光线不好，有没有简单的美颜提亮功能？','lìng wài huà miàn guāng xiàn bù hǎo， yǒu méi yǒu jiǎn dān de měi yán tí liàng gōng néng？','Với lại ánh sáng không đẹp lắm, có cách làm đẹp hay tăng sáng đơn giản nào không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_04','V605','小林',4,'侧边工具栏有基础提亮滤镜，不用复杂调整，一键开启就行。','cè biān gōng jù lán yǒu jī chǔ tí liàng lǜ jìng， bù yòng fù zá tiáo zhěng， yī jiàn kāi qǐ jiù xíng。','Thanh công cụ bên cạnh có bộ lọc tăng sáng cơ bản, không cần chỉnh phức tạp đâu, bật một nút là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_05','V605','阮明',5,'共享画面的时候，手机里的照片相册也能同步展示给家人吗？','gòng xiǎng huà miàn de shí hòu， shǒu jī lǐ de zhào piān xiàng cè yě néng tóng bù zhǎn shì gěi jiā rén ma？','Lúc chia sẻ màn hình thì ảnh trong điện thoại cũng đồng bộ cho cả nhà xem được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_06','V605','小林',6,'可以，共享时切换相册，宿舍、教学楼照片都能直接看。','kě yǐ， gòng xiǎng shí qiè huàn xiàng cè， sù shè、 jiào xué lóu zhào piān dōu néng zhí jiē kàn。','Được chứ, lúc chia sẻ thì chuyển qua album ảnh, ảnh ký túc xá hay giảng đường đều xem trực tiếp được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_07','V605','阮明',7,'太实用了，今晚视频带爸妈逛一遍我们整个校园。','tài shí yòng le， jīn wǎn shì pín dài bà mā guàng yī biàn wǒ men zhěng gè xiào yuán。','Hay quá, tối nay gọi video dẫn bố mẹ đi dạo hết cả trường luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT606','SF1','境外手机号收不到软件验证码，改用邮箱登录联系家人',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V606','SIT606','P1','twist','ban_chinh_thuc',NULL,'境内外运营商短信互通存在延迟、丢失问题，跨国软件优先推荐邮箱作为备用验证渠道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_01','V606','阮明',1,'我更换新手机，软件登录要验证码，越南手机号一直收不到短信。','wǒ gēng huàn xīn shǒu jī， ruǎn jiàn dēng lù yào yàn zhèng mǎ， yuè nán shǒu jī hào yì zhí shōu bú dào duǎn xìn。','Mình đổi điện thoại mới, đăng nhập app cần mã xác nhận mà số điện thoại Việt Nam cứ không nhận được tin nhắn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_02','V606','苏雯',2,'跨国短信运营商通道不稳定，境外号码接收验证码延迟很常见。','kuà guó duǎn xìn yùn yíng shāng tōng dào bù wěn dìng， jìng wài hào mǎ jiē shōu yàn zhèng mǎ yán chí hěn cháng jiàn。','Kênh tin nhắn xuyên quốc gia của nhà mạng không ổn định lắm, số nước ngoài nhận mã xác nhận bị chậm là chuyện thường thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_03','V606','阮明',3,'那除了手机号验证，还有别的登录方式可以选择吗？','nà chú le shǒu jī hào yàn zhèng， hái yǒu bié de dēng lù fāng shì kě yǐ xuǎn zé ma？','Vậy ngoài xác nhận qua số điện thoại thì còn cách đăng nhập nào khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_04','V606','苏雯',4,'注册时绑定的电子邮箱是备用渠道，用邮件验证码就能登录哈。','zhù cè shí bǎng dìng de diàn zi yóu xiāng shì bèi yòng qú dào， yòng yóu jiàn yàn zhèng mǎ jiù néng dēng lù hā。','Hộp thư điện tử đã liên kết lúc đăng ký là kênh dự phòng đó, dùng mã xác nhận gửi qua email là đăng nhập được.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_05','V606','阮明',5,'我之前没留意邮箱验证功能，差点一整天没法联系父母。','wǒ zhī qián méi liú yì yóu xiāng yàn zhèng gōng néng， chà diǎn yī zhěng tiān méi fǎ lián xì fù mǔ。','Trước giờ mình không để ý tính năng xác nhận qua email, suýt nữa cả ngày không liên lạc được với bố mẹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_06','V606','苏雯',6,'之后记得把邮箱设为主要验证方式，避免跨国短信失效。','zhī hòu jì de bǎ yóu xiāng shè wéi zhǔ yào yàn zhèng fāng shì， bì miǎn kuà guó duǎn xìn shī xiào。','Sau này nhớ đặt email làm phương thức xác nhận chính, tránh trường hợp tin nhắn xuyên quốc gia bị lỗi nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_07','V606','阮明',7,'我现在操作邮箱验证，登录之后第一时间给家里报平安。','wǒ xiàn zài cāo zuò yóu xiāng yàn zhèng， dēng lù zhī hòu dì yī shí jiān gěi jiā lǐ bào píng ān。','Giờ mình xác nhận qua email luôn, đăng nhập xong là báo bình an cho gia đình ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT607','SF1','软件内存过大卡顿，清理缓存保证和家人稳定通话',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V607','SIT607','P1','suon_se','tuy_y',NULL,'长期使用通讯软件会产生大量缓存图片、视频碎片，占用手机内存，定期清理是国内年轻人通用的手机维护习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_01','V607','阮明',1,'这款视频软件存了很多聊天照片，手机越用越卡顿。','zhè kuǎn shì pín ruǎn jiàn cún le hěn duō liáo tiān zhào piān， shǒu jī yuè yòng yuè kǎ dùn。','App gọi video này lưu nhiều ảnh chat quá, điện thoại dùng càng lâu càng giật.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_02','V607','小林',2,'长期堆积缓存文件会拖慢运行速度，定期清理就流畅啦。','cháng qī duī jī huǎn cún wén jiàn huì tuō màn yùn xíng sù dù， dìng qī qīng lǐ jiù liú chàng la。','File cache tích lâu ngày sẽ làm chậm máy đó, dọn dẹp định kỳ là chạy mượt lại thôi mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_03','V607','阮明',3,'清理缓存会不会删掉我和家人之前保存的聊天照片？','qīng lǐ huǎn cún huì bú huì shān diào wǒ hé jiā rén zhī qián bǎo cún de liáo tiān zhào piān？','Dọn cache thì có xóa mất ảnh chat mình lưu với gia đình trước giờ không đấy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_04','V607','小林',4,'清理临时缓存不会删除相册原图，只会清除冗余临时数据呢。','qīng lǐ lín shí huǎn cún bú huì shān chú xiàng cè yuán tú， zhǐ huì qīng chú rǒng yú lín shí shù jù ne。','Dọn cache tạm thời không xóa ảnh gốc trong album đâu, chỉ xóa dữ liệu tạm dư thừa thôi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_05','V607','阮明',5,'清理完缓存，跨国视频的延迟、卡顿问题会明显好转吗？','qīng lǐ wán huǎn cún， kuà guó shì pín de yán chí、 kǎ dùn wèn tí huì míng xiǎn hǎo zhuǎn ma？','Dọn cache xong thì tình trạng giật, trễ khi gọi video xuyên quốc gia có đỡ hơn rõ rệt không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_06','V607','小林',6,'是的，手机存储空间充足，网络传输才不会被占用。','shì de， shǒu jī cún chǔ kōng jiān chōng zú， wǎng luò chuán shū cái bú huì bèi zhàn yòng。','Đúng vậy, bộ nhớ điện thoại thoải mái thì việc truyền dữ liệu mạng mới không bị ảnh hưởng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_07','V607','阮明',7,'我现在清理缓存，晚上跟家里长时间视频聊天。','wǒ xiàn zài qīng lǐ huǎn cún， wǎn shàng gēn jiā lǐ zhǎng shí jiān shì pín liáo tiān。','Giờ mình dọn cache liền, tối nay gọi video nói chuyện lâu với gia đình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT608','SF2','跟中国同学解释越南与国内时差，调整联系父母的时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V608','SIT608','P1','suon_se','tuy_y',NULL,'中国全境统一使用北京时间，无分时区；东南亚多国时区与中国存在1-2小时时差，留学生需要协调双方作息沟通。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_01','V608','阮明',1,'很多同学不清楚，越南时间比北京时间慢一小时呢。','hěn duō tóng xué bù qīng chǔ， yuè nán shí jiān bǐ běi jīng shí jiān màn yī xiǎo shí ne。','Nhiều bạn không biết đâu, giờ Việt Nam chậm hơn giờ Bắc Kinh một tiếng đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_02','V608','苏雯',2,'难怪你总是傍晚才跟家里打电话，原来是时差错开了作息。','nán guài nǐ zǒng shì bàng wǎn cái gēn jiā lǐ dǎ diàn huà， yuán lái shì shí chà cuò kāi le zuò xī。','Thảo nào cậu toàn gọi điện về nhà lúc chiều tối, hóa ra là do lệch múi giờ nên sinh hoạt khác nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_03','V608','阮明',3,'国内晚上八点，越南才七点，爸妈刚下班有空跟我聊天。','guó nèi wǎn shàng bā diǎn， yuè nán cái qī diǎn， bà mā gāng xià bān yǒu kòng gēn wǒ liáo tiān。','Trong nước tám giờ tối thì Việt Nam mới bảy giờ, bố mẹ mình vừa tan làm nên có thời gian nói chuyện với mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_04','V608','苏雯',4,'要是你晚上有晚自习，只能白天课间发文字消息联系家里？','yào shì nǐ wǎn shàng yǒu wǎn zì xí， zhǐ néng bái tiān kè jiān fā wén zì xiāo xī lián xì jiā lǐ？','Vậy nếu tối cậu có học phụ đạo thì chỉ còn cách nhắn tin liên lạc với gia đình vào giờ giải lao ban ngày thôi à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_05','V608','阮明',5,'对，白天我这边下午，越南中午，他们午休能看消息。','duì， bái tiān wǒ zhè biān xià wǔ， yuè nán zhōng wǔ， tā men wǔ xiū néng kàn xiāo xī。','Ừ, ban ngày bên mình là buổi chiều thì Việt Nam là buổi trưa, giờ nghỉ trưa bố mẹ xem tin nhắn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_06','V608','苏雯',6,'时差错开确实不方便，固定时段联系家人会省心很多。','shí chà cuò kāi què shí bù fāng biàn， gù dìng shí duàn lián xì jiā rén huì shěng xīn hěn duō。','Lệch múi giờ đúng là bất tiện thật, cố định khung giờ liên lạc với gia đình sẽ đỡ lo hơn nhiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_07','V608','阮明',7,'我已经把通话时间标注在备忘录，不会再错过。','wǒ yǐ jīng bǎ tōng huà shí jiān biāo zhù zài bèi wàng lù， bú huì zài cuò guò。','Mình ghi giờ gọi điện vào sổ ghi chú rồi, sẽ không bỏ lỡ nữa đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT609','SF2','生病不舒服，视频隐瞒病情，怕远方家人担心',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V609','SIT609','P1','twist','ban_chinh_thuc',NULL,'在外留学生生病时大多会下意识向家人隐瞒严重不适，不想让远方亲人担忧，是十分普遍的心理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_01','V609','阮明',1,'我发烧头晕，等下跟爸妈视频，不想让他们看出我不舒服。','wǒ fā shāo tóu yūn， děng xià gēn bà mā shì pín， bù xiǎng ràng tā men kàn chū wǒ bù shū fú。','Mình bị sốt với chóng mặt, lát nữa gọi video với bố mẹ, không muốn để họ nhận ra mình khó chịu trong người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_02','V609','小林',2,'你脸色很苍白，视频一开家人一眼就能察觉到不对劲嘛。','nǐ liǎn sè hěn cāng bái， shì pín yī kāi jiā rén yī yǎn jiù néng chá jué dào bú duì jìn ma。','Mặt cậu tái xanh thế này, vừa mở video là gia đình nhận ra ngay có gì không ổn thôi mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_03','V609','阮明',3,'他们离这么远，没办法过来照顾我，知道我生病只会干着急。','tā men lí zhè me yuǎn， méi bàn fǎ guò lái zhào gù wǒ， zhī dào wǒ shēng bìng zhǐ huì gān zháo jí。','Bố mẹ ở xa vậy, không thể qua chăm sóc mình được, biết mình bệnh chỉ càng thêm lo lắng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_04','V609','小林',4,'那你可以只发文字简单提一句轻微感冒，不用隐瞒全部情况。','nà nǐ kě yǐ zhǐ fā wén zì jiǎn dān tí yī jù qīng wēi gǎn mào， bù yòng yǐn mán quán bù qíng kuàng。','Vậy cậu có thể chỉ nhắn tin sơ qua là bị cảm nhẹ thôi, không cần giấu hết chuyện đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_05','V609','阮明',5,'我想等完全康复再细说，现在只说一切正常就好。','wǒ xiǎng děng wán quán kāng fù zài xì shuō， xiàn zài zhǐ shuō yī qiè zhèng cháng jiù hǎo。','Mình muốn đợi khỏi hẳn rồi kể chi tiết sau, giờ cứ nói là mọi thứ bình thường là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_06','V609','小林',6,'但如果病情加重没人陪同，家人不知情反而更危险。','dàn rú guǒ bìng qíng jiā zhòng méi rén péi tóng， jiā rén bù zhī qíng fǎn ér gèng wēi xiǎn。','Nhưng nếu bệnh nặng hơn mà không có ai bên cạnh, gia đình không biết thì lại càng nguy hiểm hơn đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_07','V609','阮明',7,'我会控制视频时长，尽量不提身体难受的地方。','wǒ huì kòng zhì shì pín shí cháng， jǐn liàng bù tí shēn tǐ nán shòu de dì fāng。','Mình sẽ hạn chế thời gian gọi video, cố gắng không nhắc đến chỗ nào khó chịu trong người.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT610','SF2','期末备考压力大，和家人倾诉焦虑，家人远程安抚',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V610','SIT610','P1','suon_se','ban_chinh_thuc',NULL,'国内家庭普遍重视学业，但父母更在意子女身心健康，子女倾诉学习压力时，家人优先安抚情绪而非一味要求成绩。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_01','V610','阮明',1,'妈，期末要考四门专业课，每天复习到凌晨，压力好大啊。','mā， qī mò yào kǎo sì mén zhuān yè kè， měi tiān fù xí dào líng chén， yā lì hǎo dà a。','Mẹ ơi, cuối kỳ này con phải thi bốn môn chuyên ngành, ngày nào cũng ôn đến tận khuya, áp lực lắm mẹ ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_02','V610','母亲',2,'不用逼自己太紧，劳逸结合，身体比成绩重要呢。','bù yòng bī zì jǐ tài jǐn， láo yì jié hé， shēn tǐ bǐ chéng jì zhòng yào ne。','Đừng ép mình quá sức như vậy, phải kết hợp nghỉ ngơi nữa, sức khỏe quan trọng hơn điểm số nhiều đó con.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_03','V610','阮明',3,'汉语写作难度很高，我怕期末分数太低影响签证续签。','hàn yǔ xiě zuò nán dù hěn gāo， wǒ pà qī mò fēn shù tài dī yǐng xiǎng qiān zhèng xù qiān。','Viết văn tiếng Trung khó quá, con sợ điểm cuối kỳ thấp quá sẽ ảnh hưởng đến việc gia hạn visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_04','V610','母亲',4,'尽力就好，我们不会要求你必须考高分，放平心态吧。','jìn lì jiù hǎo， wǒ men bú huì yāo qiú nǐ bì xū kǎo gāo fēn， fàng píng xīn tài ba。','Cố gắng hết sức là được rồi, bố mẹ không bắt con phải điểm cao đâu, cứ thoải mái tinh thần lên nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_05','V610','阮明',5,'身边同学进度都很快，我总担心自己跟不上大家。','shēn biān tóng xué jìn dù dōu hěn kuài， wǒ zǒng dān xīn zì jǐ gēn bù shàng dà jiā。','Các bạn xung quanh con ai cũng học nhanh, con cứ lo mình theo không kịp mọi người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_06','V610','母亲',6,'每天抽空休息半小时，有空多跟我们聊聊，释放压力。','měi tiān chōu kòng xiū xī bàn xiǎo shí， yǒu kòng duō gēn wǒ men liáo liáo， shì fàng yā lì。','Mỗi ngày tranh thủ nghỉ nửa tiếng, rảnh thì nói chuyện với bố mẹ nhiều hơn để xả bớt áp lực.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_07','V610','阮明',7,'听完您说的话，心里轻松不少，谢谢妈妈安慰我。','tīng wán nín shuō de huà， xīn lǐ qīng sōng bù shǎo， xiè xiè mā mā ān wèi wǒ。','Nghe mẹ nói xong con thấy nhẹ lòng hẳn, cảm ơn mẹ đã an ủi con.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT611','SF2','忘记每日给父母报平安，家人连续多天联系不上十分着急',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V611','SIT611','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生在外，国内家人习惯每日收到平安消息，多日失联极易引发家人恐慌，甚至直接联系学校老师求助。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_01','V611','阮明',1,'辅导员，我连续三天忙于备考，忘了给爸妈发消息报平安。','fǔ dǎo yuán， wǒ lián xù sān tiān máng yú bèi kǎo， wàng le gěi bà mā fā xiāo xī bào píng ān。','Thầy/cô ơi, ba ngày liền em bận ôn thi nên quên nhắn tin báo bình an cho bố mẹ mất rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_02','V611','辅导员',2,'你母亲昨天打电话到学院，一直联系不上你，特别慌乱。','nǐ mǔ qīn zuó tiān dǎ diàn huà dào xué yuàn， yì zhí lián xì bù shàng nǐ， tè bié huāng luàn。','Hôm qua mẹ em gọi điện đến khoa, liên lạc mãi không được với em, bà lo lắng lắm đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_03','V611','阮明',3,'我以为不回复一两天没关系，没想到家人会这么担心。','wǒ yǐ wéi bù huí fù yī liǎng tiān méi guān xì， méi xiǎng dào jiā rén huì zhè me dān xīn。','Em cứ nghĩ một hai ngày không trả lời thì không sao, không ngờ gia đình lại lo đến vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_04','V611','辅导员',4,'境外子女长期失联，父母很容易往危险的方向联想嘛。','jìng wài zǐ nǚ cháng qī shī lián， fù mǔ hěn róng yì wǎng wēi xiǎn de fāng xiàng lián xiǎng ma。','Con cái ở nước ngoài mất liên lạc lâu ngày thì bố mẹ rất dễ nghĩ theo hướng xấu đó em.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_05','V611','阮明',5,'我现在立刻打视频电话，好好跟家里解释这几天的情况。','wǒ xiàn zài lì kè dǎ shì pín diàn huà， hǎo hǎo gēn jiā lǐ jiě shì zhè jǐ tiān de qíng kuàng。','Em sẽ gọi video ngay bây giờ, giải thích rõ tình hình mấy ngày qua cho gia đình yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_06','V611','辅导员',6,'之后再忙也要抽一分钟发一句简短文字，让家人放心。','zhī hòu zài máng yě yào chōu yì fēn zhōng fā yī jù jiǎn duǎn wén zì， ràng jiā rén fàng xīn。','Sau này dù bận đến mấy cũng phải dành ra một phút nhắn vài chữ ngắn gọn, để gia đình an tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_07','V611','阮明',7,'我记住教训，以后每天固定简单留言报平安。','wǒ jì zhù jiào xùn， yǐ hòu měi tiān gù dìng jiǎn dān liú yán bào píng ān。','Em rút kinh nghiệm rồi, từ nay ngày nào cũng sẽ nhắn tin báo bình an đều đặn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT612','SF2','学校放长假规划出行，提前和父母商量行程并实时分享定位',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V612','SIT612','P1','suon_se','tuy_y',NULL,'子女独自外出旅行，中国父母普遍要求实时分享定位、每日报备行程，优先关注出行安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_01','V612','阮明',1,'妈，寒假我打算和同学去周边城市短途旅行，跟您商量一下。','mā， hán jià wǒ dǎ suàn hé tóng xué qù zhōu biān chéng shì duǎn tú lǚ xíng， gēn nín shāng liáng yī xià。','Mẹ ơi, kỳ nghỉ đông này con định cùng bạn đi du lịch ngắn ngày ở mấy thành phố lân cận, muốn bàn với mẹ một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_02','V612','母亲',2,'路途远不远，住宿安全吗，出门一定要实时共享定位给我们哦。','lù tú yuǎn bù yuǎn， zhù sù ān quán ma， chū mén yí dìng yào shí shí gòng xiǎng dìng wèi gěi wǒ men ó。','Đường đi có xa không, chỗ ở có an toàn không, ra ngoài nhớ chia sẻ định vị trực tiếp cho bố mẹ đấy nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_03','V612','阮明',3,'全程高铁出行，住正规连锁酒店，每天晚上同步行程定位。','quán chéng gāo tiě chū xíng， zhù zhèng guī lián suǒ jiǔ diàn， měi tiān wǎn shàng tóng bù xíng chéng dìng wèi。','Cả chuyến đi con đi tàu cao tốc, ở khách sạn chuỗi chính quy, tối nào cũng đồng bộ lịch trình với định vị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_04','V612','母亲',4,'每天晚上十点前发消息，告诉我们当天去了哪些地方吧。','měi tiān wǎn shàng shí diǎn qián fā xiāo xī， gào sù wǒ men dàng tiān qù le nǎ xiē dì fāng ba。','Trước mười giờ tối mỗi ngày nhắn tin cho bố mẹ biết hôm đó con đã đi những đâu nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_05','V612','阮明',5,'我每到一个景点都拍照片发给家里，不让你们担心。','wǒ měi dào yí gè jǐng diǎn dōu pāi zhào piān fā gěi jiā lǐ， bù ràng nǐ men dān xīn。','Đến điểm nào con cũng chụp ảnh gửi về nhà, để bố mẹ không phải lo đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_06','V612','母亲',6,'在外结伴出行，不要单独去偏僻人少的地方。','zài wài jié bàn chū xíng， bú yào dān dú qù piān pì rén shǎo de dì fāng。','Đi chơi ở ngoài thì phải đi cùng bạn bè, đừng đi một mình đến những chỗ hẻo lánh vắng người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_07','V612','阮明',7,'我会牢记您的叮嘱，出行全程和同学结伴行动。','wǒ huì láo jì nín de dīng zhǔ， chū xíng quán chéng hé tóng xué jié bàn xíng dòng。','Con sẽ ghi nhớ lời mẹ dặn, suốt chuyến đi sẽ luôn đi cùng bạn bè.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT613','SF2','深夜在图书馆自习，怕打扰家人休息只发文字消息不打视频',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V613','SIT613','P1','suon_se','tuy_y',NULL,'国人普遍重视夜间休息，深夜语音、视频通话会被视作打扰他人，非紧急情况只用文字留言沟通。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_01','V613','阮明',1,'现在国内已经深夜十一点，我不敢发起视频打扰爸妈休息。','xiàn zài guó nèi yǐ jīng shēn yè shí yì diǎn， wǒ bù gǎn fā qǐ shì pín dǎ rǎo bà mā xiū xī。','Giờ bên nhà đã là mười một giờ đêm rồi, con không dám gọi video sợ làm phiền bố mẹ nghỉ ngơi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_02','V613','苏雯',2,'时差叠加熬夜，一通视频会直接打断他们睡眠呢。','shí chà dié jiā áo yè， yí tòng shì pín huì zhí jiē dǎ duàn tā men shuì mián ne。','Lệch múi giờ mà lại cộng thêm thức khuya nữa, một cuộc gọi video là làm gián đoạn giấc ngủ của bố mẹ ngay đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_03','V613','阮明',3,'我简单发一段文字，说明我在图书馆自习，一切平安。','wǒ jiǎn dān fā yī duàn wén zì， shuō míng wǒ zài tú shū guǎn zì xí， yī qiè píng ān。','Con nhắn vài dòng chữ đơn giản thôi, báo là con đang tự học ở thư viện, mọi thứ vẫn ổn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_04','V613','苏雯',4,'文字留言他们明天一早醒来就能看到，不会被深夜来电惊扰。','wén zì liú yán tā men míng tiān yī zǎo xǐng lái jiù néng kàn dào， bú huì bèi shēn yè lái diàn jīng rǎo。','Nhắn tin thì sáng mai bố mẹ dậy là thấy ngay, khỏi bị cuộc gọi lúc nửa đêm làm giật mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_05','V613','阮明',5,'要是遇到急事，才会选择打电话联系家里。','yào shì yù dào jí shì， cái huì xuǎn zé dǎ diàn huà lián xì jiā lǐ。','Trừ khi có việc gấp thì con mới gọi điện thoại về nhà thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_06','V613','苏雯',6,'这样体贴家人作息，长辈心里也会觉得你懂事贴心。','zhè yàng tǐ tiē jiā rén zuò xī， zhǎng bèi xīn lǐ yě huì jué de nǐ dǒng shì tiē xīn。','Con biết nghĩ đến giờ giấc của gia đình như vậy, ông bà cũng sẽ thấy con hiểu chuyện và tinh tế đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_07','V613','阮明',7,'嗯，我简单编辑平安消息发送给父母。','ń， wǒ jiǎn dān biān jí píng ān xiāo xī fā sòng gěi fù mǔ。','Vâng, con soạn một tin báo bình an ngắn gọn gửi cho bố mẹ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT614','SF3','生活费不足，委婉跟父母说明开销，协商每月转账额度',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V614','SIT614','P1','suon_se','ban_chinh_thuc',NULL,'子女向家长说明生活费不足时，多委婉说明开销用途，家长一般会适度上调生活费，同时叮嘱合理消费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_01','V614','阮明',1,'爸，最近物价小幅上涨，食堂、生活用品开销比之前多一些。','bà， zuì jìn wù jià xiǎo fú shàng zhǎng， shí táng、 shēng huó yòng pǐn kāi xiāo bǐ zhī qián duō yī xiē。','Bố ơi, dạo này vật giá tăng nhẹ, chi phí ăn ở căng tin với đồ dùng sinh hoạt cũng nhiều hơn trước một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_02','V614','父亲',2,'每月给你的生活费不够支撑日常开销了是吗？','měi yuè gěi nǐ de shēng huó fèi bù gòu zhī chēng rì cháng kāi xiāo le shì ma？','Tiền sinh hoạt hàng tháng bố mẹ gửi không đủ trang trải chi tiêu hằng ngày đúng không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_03','V614','阮明',3,'除去吃饭、水电，还要买汉语教材，手头经常月底紧张呢。','chú qù chī fàn、 shuǐ diàn， hái yào mǎi hàn yǔ jiào cái， shǒu tóu jīng cháng yuè dǐ jǐn zhāng ne。','Trừ tiền ăn, tiền điện nước ra, còn phải mua giáo trình tiếng Trung nữa, nên đến cuối tháng con hay bị hụt tay ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_04','V614','父亲',4,'那我们每个月上调一部分汇款额度，保证你不用拮据生活。','nà wǒ men měi gè yuè shàng diào yī bù fèn huì kuǎn é dù， bǎo zhèng nǐ bù yòng jié jū shēng huó。','Vậy thì mỗi tháng bố mẹ sẽ tăng thêm một khoản chuyển khoản, để con không phải sống chật vật.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_05','V614','阮明',5,'我也会减少不必要的网购，合理控制日常消费。','wǒ yě huì jiǎn shǎo bù bì yào de wǎng gòu， hé lǐ kòng zhì rì cháng xiāo fèi。','Con cũng sẽ hạn chế mua sắm online không cần thiết, chi tiêu hợp lý hơn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_06','V614','父亲',6,'不用太节俭，该花的学习、生活开支不用省。','bù yòng tài jié jiǎn， gāi huā de xué xí、 shēng huó kāi zhī bù yòng shěng。','Không cần tiết kiệm quá đâu, khoản nào cần cho việc học và sinh hoạt thì cứ chi, không phải dè sẻn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_07','V614','阮明',7,'谢谢您体谅，我会做好消费规划，不乱花钱。','xiè xiè nín tǐ liàng， wǒ huì zuò hǎo xiāo fèi guī huà， bù luàn huā qián。','Con cảm ơn bố mẹ đã thông cảm, con sẽ lên kế hoạch chi tiêu cẩn thận, không tiêu xài lung tung ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT615','SF3','家人不会操作跨境汇款软件，一步步远程指导父母操作',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V615','SIT615','P1','twist','tuy_y',NULL,'中老年境外亲属不熟悉国内银行跨境汇款线上系统，留学生常通过屏幕共享远程手把手指导操作，避免操作失误转错账户。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_01','V615','阮明',1,'妈，跨境汇款手机软件操作不难，我开屏幕共享一步步教您。','mā， kuà jìng huì kuǎn shǒu jī ruǎn jiàn cāo zuò bù nán， wǒ kāi píng mù gòng xiǎng yí bù bù jiào nín。','Mẹ ơi, thao tác trên app chuyển tiền quốc tế không khó đâu, để con chia sẻ màn hình chỉ mẹ từng bước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_02','V615','母亲',2,'页面全是外文，我看不懂按钮，怕点错造成资金损失啊。','yè miàn quán shì wài wén， wǒ kàn bù dǒng àn niǔ， pà diǎn cuò zào chéng zī jīn sǔn shī a。','Giao diện toàn chữ nước ngoài, mẹ không hiểu nút nào với nút nào, sợ bấm nhầm mất tiền lắm à.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_03','V615','阮明',3,'我指给您看汇款、收款人信息输入的固定位置，不用点其他按钮嘛。','wǒ zhǐ gěi nín kàn huì kuǎn、 shōu kuǎn rén xìn xī shū rù de gù dìng wèi zhì， bù yòng diǎn qí tā àn niǔ ma。','Con chỉ cho mẹ mấy chỗ cố định để nhập tiền chuyển với thông tin người nhận thôi, mấy nút khác khỏi cần đụng vào mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_04','V615','母亲',4,'输入我的护照号码的时候，字母大小写需要严格区分吗？','shū rù wǒ de hù zhào hào mǎ de shí hòu， zì mǔ dà xiǎo xiě xū yào yán gé qū fēn ma？','Lúc nhập số hộ chiếu của mẹ, chữ hoa chữ thường có cần phân biệt kỹ không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_05','V615','阮明',5,'系统不区分大小写，但是姓名拼音必须和护照完全一致。','xì tǒng bù qū fēn dà xiǎo xiě， dàn shì xìng míng pīn yīn bì xū hé hù zhào wán quán yí zhì。','Hệ thống không phân biệt hoa thường đâu mẹ, nhưng tên phiên âm phải khớp y hệt với hộ chiếu đó ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_06','V615','母亲',6,'我操作到一半跳转验证页面，不知道怎么填写信息。','wǒ cāo zuò dào yí bàn tiào zhuǎn yàn zhèng yè miàn， bù zhī dào zěn me tián xiě xìn xī。','Mẹ làm được nửa chừng thì nó nhảy sang trang xác minh, mẹ không biết điền thông tin sao cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_07','V615','阮明',7,'您别退出页面，我放慢语速，逐项告诉你怎么填写。','nín bié tuì chū yè miàn， wǒ fàng màn yǔ sù， zhú xiàng gào sù nǐ zěn me tián xiě。','Mẹ đừng thoát trang đó, con nói chậm lại, chỉ mẹ điền từng mục một nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT616','SF3','转账手续费过高，和家人商量换更划算的汇款渠道',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V616','SIT616','P1','suon_se','ban_chinh_thuc',NULL,'不同跨境汇款渠道手续费标准差异大，大额资金线下银行电汇性价比更高，小额线上便捷但手续费占比更高。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_01','V616','阮明',1,'之前用的汇款渠道手续费比例很高，一笔钱扣不少手续费呢。','zhī qián yòng de huì kuǎn qú dào shǒu xù fèi bǐ lì hěn gāo， yī bǐ qián kòu bù shǎo shǒu xù fèi ne。','Kênh chuyển tiền trước giờ con dùng phí cao quá, mỗi lần chuyển bị trừ phí không ít đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_02','V616','父亲',2,'那有没有手续费更低、到账速度稳定的跨境汇款方式？','nà yǒu méi yǒu shǒu xù fèi gèng dī、 dào zhàng sù dù wěn dìng de kuà jìng huì kuǎn fāng shì？','Vậy có cách chuyển tiền quốc tế nào phí thấp hơn mà tốc độ nhận tiền vẫn ổn định không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_03','V616','阮明',3,'银行线下柜台跨境电汇手续费固定，大额汇款会划算很多。','yín háng xiàn xià guì tái kuà jìng diàn huì shǒu xù fèi gù dìng， dà é huì kuǎn huì huá suàn hěn duō。','Chuyển khoản quốc tế trực tiếp tại quầy ngân hàng thì phí cố định, nếu chuyển số tiền lớn sẽ tiết kiệm hơn nhiều ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_04','V616','父亲',4,'下次大额生活费，我直接去线下银行柜台办理汇款吧。','xià cì dà é shēng huó fèi， wǒ zhí jiē qù xiàn xià yín háng guì tái bàn lǐ huì kuǎn ba。','Lần sau chuyển sinh hoạt phí khoản lớn, bố sẽ ra thẳng quầy ngân hàng làm luôn.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_05','V616','阮明',5,'小额日常零花钱可以线上软件，大额走线下银行渠道。','xiǎo é rì cháng líng huā qián kě yǐ xiàn shàng ruǎn jiàn， dà é zǒu xiàn xià yín háng qú dào。','Còn tiền tiêu vặt hằng ngày, số nhỏ thì có thể dùng app online, số lớn thì đi qua kênh ngân hàng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_06','V616','父亲',6,'两种渠道分开使用，能省下不少手续费长期积累。','liǎng zhǒng qú dào fēn kāi shǐ yòng， néng shěng xià bù shǎo shǒu xù fèi cháng qī jī lěi。','Tách riêng hai kênh như vậy dùng dần cũng tiết kiệm được kha khá phí về lâu dài đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_07','V616','阮明',7,'好，我们分开渠道汇款，减少不必要的手续费损耗。','hǎo， wǒ men fēn kāi qú dào huì kuǎn， jiǎn shǎo bù bì yào de shǒu xù fèi sǔn hào。','Vâng, mình tách kênh chuyển tiền ra như vậy để giảm bớt hao phí không cần thiết ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT617','SF3','银行卡接收境外汇款被银行拦截，第一时间电话告知父母',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V617','SIT617','P1','twist','chinh_thuc',NULL,'国内银行对大额境外汇款有资金来源核查机制，留学生生活费汇款需携带护照线下申报，防止跨境资金违规流动。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_01','V617','阮明',1,'爸，您刚刚汇过来的生活费，被银行系统临时拦截了。','bà， nín gāng gāng huì guò lái de shēng huó fèi， bèi yín háng xì tǒng lín shí lán jié le。','Bố ơi, khoản sinh hoạt phí bố vừa chuyển bị hệ thống ngân hàng tạm giữ lại rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_02','V617','父亲',2,'怎么会拦截正常留学生生活费，是不是信息填写出错？','zěn me huì lán jié zhèng cháng liú xué shēng shēng huó fèi， shì bú shì xìn xī tián xiě chū cuò？','Sao lại giữ tiền sinh hoạt bình thường của du học sinh được, hay là điền sai thông tin gì rồi?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_03','V617','阮明',3,'银行需要我携带护照去柜台申报资金来源，才能入账嘛。','yín háng xū yào wǒ xié dài hù zhào qù guì tái shēn bào zī jīn lái yuán， cái néng rù zhàng ma。','Ngân hàng yêu cầu con mang hộ chiếu ra quầy khai báo nguồn gốc số tiền thì mới ghi có được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_04','V617','父亲',4,'那这笔资金会原路退回我的账户，还是暂时冻结等待申报？','nà zhè bǐ zī jīn huì yuán lù tuì huí wǒ de zhàng hù， hái shì zàn shí dòng jié děng dài shēn bào？','Vậy khoản tiền đó sẽ được hoàn trả về tài khoản của bố, hay là tạm thời bị đóng băng chờ khai báo?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_05','V617','阮明',5,'资金暂时冻结，今天办完申报手续，明天就能正常入账。','zī jīn zàn shí dòng jié， jīn tiān bàn wán shēn bào shǒu xù， míng tiān jiù néng zhèng cháng rù zhàng。','Tiền đang tạm bị đóng băng thôi ạ, hôm nay con làm xong thủ tục khai báo thì mai là vào tài khoản bình thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_06','V617','父亲',6,'我这边暂时不再追加汇款，等你确认资金到账再说。','wǒ zhè biān zàn shí bù zài zhuī jiā huì kuǎn， děng nǐ què rèn zī jīn dào zhàng zài shuō。','Vậy bố tạm thời sẽ không chuyển thêm nữa, đợi con xác nhận tiền vào tài khoản rồi tính tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_07','V617','阮明',7,'我办完银行手续第一时间给您回电话告知结果。','wǒ bàn wán yín háng shǒu xù dì yī shí jiān gěi nín huí diàn huà gào zhī jié guǒ。','Con làm xong thủ tục ngân hàng là gọi điện báo kết quả cho bố ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT618','SF3','想买电子产品，和家人沟通预算，协商分期添置',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V618','SIT618','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内家庭购置大额电子产品会综合考量子女备用资金，优先留存应急生活费，再规划数码产品采购预算。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_01','V618','阮明',1,'我旧手机卡顿严重，想更换一台新手机用于上课录课件。','wǒ jiù shǒu jī kǎ dùn yán zhòng， xiǎng gēng huàn yī tái xīn shǒu jī yòng yú shàng kè lù kè jiàn。','Điện thoại cũ của con giật lag nặng quá rồi, con muốn đổi máy mới để dùng quay bài giảng trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_02','V618','母亲',2,'新款机型总价偏高，一次性拿出全部资金压力比较大。','xīn kuǎn jī xíng zǒng jià piān gāo， yí cì xìng ná chū quán bù zī jīn yā lì bǐ jiào dà。','Mẫu máy mới giá khá cao, bỏ ra một lần toàn bộ số tiền thì áp lực lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_03','V618','阮明',3,'我平时兼职有少量收入，可以自己承担一半购机费用。','wǒ píng shí jiān zhí yǒu shǎo liàng shōu rù， kě yǐ zì jǐ chéng dān yí bàn gòu jī fèi yòng。','Con có làm thêm nên cũng có chút thu nhập, con có thể tự chi một nửa tiền mua máy ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_04','V618','父亲',4,'兼职收入要留存作应急备用金，不能全部拿来买电子产品嘛。','jiān zhí shōu rù yào liú cún zuò yìng jí bèi yòng jīn， bù néng quán bù ná lái mǎi diàn zi chǎn pǐn ma。','Tiền làm thêm phải giữ lại làm quỹ dự phòng khẩn cấp chứ, không thể dồn hết vào mua đồ điện tử được.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_05','V618','阮明',5,'那我们分两个月，分两次凑齐预算购置手机可以吗？','nà wǒ men fēn liǎng gè yuè， fēn liǎng cì còu qí yù suàn gòu zhì shǒu jī kě yǐ ma？','Vậy mình chia làm hai tháng, góp hai đợt cho đủ ngân sách mua máy được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_06','V618','母亲',6,'可以，先预留应急生活费，剩余资金再安排购置设备。','kě yǐ， xiān yù liú yìng jí shēng huó fèi， shèng yú zī jīn zài ān pái gòu zhì shè bèi。','Được, cứ để dành tiền sinh hoạt khẩn cấp trước, số còn lại rồi tính chuyện mua sắm thiết bị sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_07','V618','阮明',7,'我理解家里的顾虑，不急于一次性换新手机。','wǒ lǐ jiě jiā lǐ de gù lǜ， bù jí yú yí cì xìng huàn xīn shǒu jī。','Con hiểu những lo lắng của gia đình, con không vội đổi máy mới ngay đâu ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT619','SF4','中国传统节日，拍校园节日活动视频发给父母讲解习俗',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V619','SIT619','P1','suon_se','tuy_y',NULL,'中秋、春节是中国人核心团圆节日，留学生常会拍摄校园节日活动分享给海外家人，对比两国民俗差异。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_01','V619','阮明',1,'妈，今天校园举办中秋晚会，我拍一段视频发给您看看。','mā， jīn tiān xiào yuán jǔ bàn zhōng qiū wǎn huì， wǒ pāi yī duàn shì pín fā gěi nín kàn kàn。','Mẹ ơi, hôm nay trường tổ chức đêm hội Trung thu, con quay một đoạn video gửi mẹ xem nè.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_02','V619','母亲',2,'画面里大家都在吃月饼、赏月，这就是中国中秋习俗对吧？','huà miàn lǐ dà jiā dōu zài chī yuè bǐng、 shǎng yuè， zhè jiù shì zhōng guó zhōng qiū xí sú duì ba？','Trong hình mọi người đang ăn bánh trung thu, ngắm trăng, đó là phong tục Trung thu của Trung Quốc đúng không con?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_03','V619','阮明',3,'没错，中秋代表团圆，家家户户都会吃月饼、家人相聚呢。','méi cuò， zhōng qiū dài biǎo tuán yuán， jiā jiā hù hù dōu huì chī yuè bǐng、 jiā rén xiāng jù ne。','Đúng rồi mẹ, Trung thu tượng trưng cho đoàn viên, nhà nhà đều ăn bánh trung thu, người thân sum họp bên nhau đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_04','V619','母亲',4,'越南也有类似团圆节日，只是美食和庆祝方式不一样。','yuè nán yě yǒu lèi sì tuán yuán jié rì， zhǐ shì měi shí hé qìng zhù fāng shì bù yí yàng。','Việt Nam mình cũng có ngày lễ đoàn viên tương tự, chỉ là món ăn với cách đón lễ khác thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_05','V619','阮明',5,'我今晚分到一块月饼，等下拍照发给您看看样式。','wǒ jīn wǎn fēn dào yī kuài yuè bǐng， děng xià pāi zhào fā gěi nín kàn kàn yàng shì。','Tối nay con được chia một miếng bánh trung thu, lát nữa con chụp hình gửi mẹ xem kiểu dáng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_06','V619','母亲',6,'身在异国也能体验他国节日，多感受不同文化挺好。','shēn zài yì guó yě néng tǐ yàn tā guó jié rì， duō gǎn shòu bù tóng wén huà tǐng hǎo。','Ở nước ngoài mà vẫn được trải nghiệm lễ hội của người ta, cảm nhận văn hóa khác biệt như vậy cũng hay đó con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_07','V619','阮明',7,'之后过春节、端午，我都拍校园活动分享给家里。','zhī hòu guò chūn jié、 duān wǔ， wǒ dōu pāi xiào yuán huó dòng fēn xiǎng gěi jiā lǐ。','Sau này đến Tết, đến Tết Đoan Ngọ, con cũng sẽ quay hoạt động ở trường chia sẻ cho gia đình xem.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT620','SF4','越南传统节日无法回国，视频和家里亲友线上过节',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V620','SIT620','P1','suon_se','tuy_y',NULL,'跨国留学生无法回国过节时，全家会集体视频连线线上团圆，弥补不能线下相聚的遗憾。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_01','V620','阮明',1,'各位长辈，今年节日我没法回国，只能线上和大家一起过节啦。','gè wèi zhǎng bèi， jīn nián jié rì wǒ méi fǎ huí guó， zhǐ néng xiàn shàng hé dà jiā yì qǐ guò jié la。','Cả nhà ơi, năm nay con không về nước đón lễ được, chỉ có thể lên mạng đón lễ cùng mọi người thôi ạ.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_02','V620','亲戚长辈',2,'我们准备了节日特色饭菜，屏幕这边分一份给你看看。','wǒ men zhǔn bèi le jié rì tè sè fàn cài， píng mù zhè biān fēn yī fèn gěi nǐ kàn kàn。','Bọn cô chú chuẩn bị mấy món ăn đặc trưng ngày lễ rồi đây, để cho con xem qua màn hình một chút nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_03','V620','阮明',3,'我在食堂也点了相似风味菜品，也算同步过节了呢。','wǒ zài shí táng yě diǎn le xiāng sì fēng wèi cài pǐn， yě suàn tóng bù guò jié le ne。','Con ở căng tin cũng gọi món có hương vị gần giống vậy, coi như cũng đón lễ cùng lúc luôn ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_04','V620','亲戚长辈',4,'在外好好照顾自己，不用挂念家里的节日聚餐。','zài wài hǎo hǎo zhào gù zì jǐ， bù yòng guà niàn jiā lǐ de jié rì jù cān。','Ở bên đó nhớ chăm sóc bản thân cho tốt, đừng lo lắng chuyện tiệc lễ ở nhà nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_05','V620','阮明',5,'虽然相隔很远，视频连线也像坐在一张桌子吃饭。','suī rán xiāng gé hěn yuǎn， shì pín lián xiàn yě xiàng zuò zài yī zhāng zhuō zi chī fàn。','Tuy cách xa nhau nhưng gọi video thế này cũng giống như đang ngồi chung một bàn ăn vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_06','V620','亲戚长辈',6,'假期有空多视频，常跟家里说说日常校园生活。','jià qī yǒu kòng duō shì pín， cháng gēn jiā lǐ shuō shuō rì cháng xiào yuán shēng huó。','Rảnh trong dịp lễ thì gọi video nhiều vào, kể cho gia đình nghe chuyện học hành ở trường thường xuyên nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_07','V620','阮明',7,'好，每年传统节日我都会准时上线和大家团聚。','hǎo， měi nián chuán tǒng jié rì wǒ dōu huì zhǔn shí shàng xiàn hé dà jiā tuán jù。','Vâng, mỗi năm đến lễ truyền thống con đều sẽ lên mạng đúng giờ để sum họp cùng mọi người ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT621','SF4','拍食堂饭菜、宿舍环境视频，实时展示在华日常给家人',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V621','SIT621','P1','suon_se','tuy_y',NULL,'远在境外的父母十分关心子女居住、饮食环境，实时实景视频是最直观让家人安心的方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_01','V621','阮明',1,'爸，我现在共享画面，带您看看我的宿舍和学校食堂。','bà， wǒ xiàn zài gòng xiǎng huà miàn， dài nín kàn kàn wǒ de sù shè hé xué xiào shí táng。','Bố ơi, con đang chia sẻ màn hình nè, để con dẫn bố xem phòng ký túc xá với căn tin trường con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_02','V621','父亲',2,'宿舍整洁宽敞，食堂菜品种类看着很丰富，放心多了。','sù shè zhěng jié kuān chǎng， shí táng cài pǐn zhǒng lèi kàn zhe hěn fēng fù， fàng xīn duō le。','Ký túc xá gọn gàng rộng rãi, đồ ăn ở căn tin nhìn cũng phong phú đó, bố yên tâm hơn nhiều rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_03','V621','阮明',3,'每天三餐都在食堂解决，价格实惠，口味也能适应。','měi tiān sān cān dōu zài shí táng jiě jué， jià gé shí huì， kǒu wèi yě néng shì yìng。','Ngày nào ba bữa con cũng ăn ở căn tin luôn, giá cả phải chăng, khẩu vị cũng hợp dần được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_04','V621','父亲',4,'日常居住环境安全整洁，我们在家不用一直担心你的生活。','rì cháng jū zhù huán jìng ān quán zhěng jié， wǒ men zài jiā bù yòng yì zhí dān xīn nǐ de shēng huó。','Môi trường sống hàng ngày an toàn sạch sẽ vậy thì ở nhà bố mẹ khỏi phải lo lắng suốt về cuộc sống của con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_05','V621','阮明',5,'楼下还有超市、药店，日常生活用品采购很方便。','lóu xià hái yǒu chāo shì、 yào diàn， rì cháng shēng huó yòng pǐn cǎi gòu hěn fāng biàn。','Dưới lầu còn có siêu thị, nhà thuốc nữa, mua đồ dùng hàng ngày tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_06','V621','父亲',6,'多拍日常视频发给我们，直观知道你在校的生活状态。','duō pāi rì cháng shì pín fā gěi wǒ men， zhí guān zhī dào nǐ zài xiào de shēng huó zhuàng tài。','Con quay thêm video đời thường gửi cho bố mẹ nha, để bố mẹ biết trực tiếp con sống ở trường thế nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_07','V621','阮明',7,'之后每周固定拍一段校园日常视频发给家里。','zhī hòu měi zhōu gù dìng pāi yī duàn xiào yuán rì cháng shì pín fā gěi jiā lǐ。','Sau này mỗi tuần con sẽ cố định quay một đoạn video sinh hoạt ở trường gửi về nhà.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT622','SF4','教父母简单中文短句，方便以后来华出行沟通',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V622','SIT622','P1','twist','tuy_y',NULL,'不少外籍留学生父母计划来华探亲，子女会远程教授基础中文短句，方便线下出行、购物沟通。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_01','V622','阮明',1,'妈，我教您几句简单中文，以后来中国旅游能用得上。','mā， wǒ jiào nín jǐ jù jiǎn dān zhōng wén， yǐ hòu lái zhōng guó lǚ yóu néng yòng dé shàng。','Mẹ ơi, con dạy mẹ vài câu tiếng Trung đơn giản, sau này qua Trung Quốc du lịch dùng được đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_02','V622','母亲',2,'中文发音太难了，我记不住声调，读出来很奇怪啊。','zhōng wén fā yīn tài nán le， wǒ jì bú zhù shēng diào， dú chū lái hěn qí guài a。','Phát âm tiếng Trung khó quá à, mẹ nhớ không nổi thanh điệu, đọc ra nghe kỳ kỳ sao ấy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_03','V622','阮明',3,'不用纠结标准声调，简单短句能让店员听懂意思就行嘛。','bù yòng jiū jié biāo zhǔn shēng diào， jiǎn dān duǎn jù néng ràng diàn yuán tīng dǒng yì si jiù xíng ma。','Mẹ không cần lăn tăn thanh điệu chuẩn đâu, câu ngắn đơn giản mà nhân viên hiểu ý là được mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_04','V622','母亲',4,'比如点餐、问路这类基础句子，您一句一句慢速教我。','bǐ rú diǎn cān、 wèn lù zhè lèi jī chǔ jù zi， nín yī jù yī jù màn sù jiāo wǒ。','Kiểu như gọi món, hỏi đường ấy, con dạy mẹ từng câu chậm chậm nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_05','V622','阮明',5,'先学"多少钱""请问卫生间在哪里"两句最常用的。','xiān xué " duō shǎo qián "" qǐng wèn wèi shēng jiān zài nǎ lǐ " liǎng jù zuì cháng yòng de。','Học trước hai câu hay dùng nhất là ''bao nhiêu tiền'' với ''cho hỏi nhà vệ sinh ở đâu''.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_06','V622','母亲',6,'我反复跟读几遍，下次来华就能简单沟通不慌张。','wǒ fǎn fù gēn dú jǐ biàn， xià cì lái huá jiù néng jiǎn dān gōu tōng bù huāng zhāng。','Mẹ đọc lặp lại vài lần, lần sau qua Trung Quốc là giao tiếp đơn giản được, khỏi cuống.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_07','V622','阮明',7,'我每天视频花十分钟教您短句，慢慢积累就熟练了。','wǒ měi tiān shì pín huā shí fēn zhōng jiào nín duǎn jù， màn màn jī lěi jiù shú liàn le。','Mỗi ngày con gọi video mười phút dạy mẹ vài câu, từ từ tích lũy là quen thôi mà.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT623','SF4','父母好奇中国课堂，申请老师允许录制简短上课片段发给家人',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V623','SIT623','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂课件拥有教学版权，随意完整录制传播属于违规；仅无课件、不暴露他人肖像的短实景片段可适度拍摄。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_01','V623','阮明',1,'老师您好，我的父母十分好奇中国课堂，想申请录制一小段授课视频。','lǎo shī nín hǎo， wǒ de fù mǔ shí fēn hào qí zhōng guó kè táng， xiǎng shēn qǐng lù zhì yī xiǎo duàn shòu kè shì pín。','Chào cô ạ, bố mẹ em rất tò mò về lớp học ở Trung Quốc, em muốn xin phép quay một đoạn video buổi học ngắn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_02','V623','老师',2,'课堂内容涉及课件版权，完整整节课录制是不允许的。','kè táng nèi róng shè jí kè jiàn bǎn quán， wán zhěng zhěng jié kè lù zhì shì bù yǔn xǔ de。','Nội dung bài giảng liên quan đến bản quyền tài liệu, quay trọn vẹn cả tiết học thì không được phép.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_03','V623','阮明',3,'那只录制教室环境、课堂互动，不拍摄课件文字可以吗？','nà zhǐ lù zhì jiào shì huán jìng、 kè táng hù dòng， bù pāi shè kè jiàn wén zì kě yǐ ma？','Vậy em chỉ quay không gian lớp học, hoạt động tương tác, không quay chữ trên slide bài giảng có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_04','V623','老师',4,'无课件文字的实景互动片段可以短时间录制，时长控制在一分钟内嘛。','wú kè jiàn wén zì de shí jǐng hù dòng piàn duàn kě yǐ duǎn shí jiān lù zhì， shí cháng kòng zhì zài yì fēn zhōng nèi ma。','Đoạn tương tác thực tế không có chữ trên slide thì có thể quay trong thời gian ngắn, giới hạn trong vòng một phút thôi nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_05','V623','阮明',5,'一分钟短视频足够发给家人了解课堂氛围，不会泄露教学内容。','yì fēn zhōng duǎn shì pín zú gòu fā gěi jiā rén liǎo jiě kè táng fēn wéi， bú huì xiè lòu jiào xué nèi róng。','Một phút video ngắn cũng đủ để gửi cho gia đình biết không khí lớp học rồi ạ, sẽ không làm lộ nội dung giảng dạy đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_06','V623','老师',6,'录制时不要拍到其他同学清晰面部，保护同班同学隐私。','lù zhì shí bú yào pāi dào qí tā tóng xué qīng xī miàn bù， bǎo hù tóng bān tóng xué yǐn sī。','Khi quay đừng để lộ rõ mặt các bạn học khác, phải bảo vệ quyền riêng tư của các bạn cùng lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_07','V623','阮明',7,'我会避开其他同学镜头，只拍摄讲台与教室环境，感谢老师通融。','wǒ huì bì kāi qí tā tóng xué jìng tóu， zhǐ pāi shè jiǎng tái yǔ jiào shì huán jìng， gǎn xiè lǎo shī tōng róng。','Em sẽ tránh máy quay không hướng vào các bạn khác, chỉ quay bục giảng và không gian lớp học thôi, cảm ơn cô đã tạo điều kiện ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT624','SF5','护照丢失，第一时间视频联系家人说明情况寻求建议',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V624','SIT624','P1','suon_se','chinh_thuc',NULL,'留学生丢失护照属于重大紧急事件，第一时间同步家人，家人会协助梳理资金、证件补办相关方案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_01','V624','阮明',1,'爸妈，我今天出门逛街不慎丢失护照，现在在派出所报案。','bà mā， wǒ jīn tiān chū mén guàng jiē bù shèn diū shī hù zhào， xiàn zài zài pài chū suǒ bào àn。','Bố mẹ ơi, hôm nay con đi dạo phố lỡ làm mất hộ chiếu, hiện con đang trình báo ở đồn công an.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_02','V624','母亲',2,'怎么这么不小心，补办证件流程复杂，资金、证件都有麻烦。','zěn me zhè me bù xiǎo xīn， bǔ bàn zhèng jiàn liú chéng fù zá， zī jīn、 zhèng jiàn dōu yǒu má fán。','Sao lại bất cẩn như vậy, thủ tục làm lại giấy tờ phức tạp lắm, cả tiền bạc lẫn giấy tờ đều rắc rối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_03','V624','阮明',3,'民警告知我先开遗失回执，再分别去出入境、大使馆补办呢。','mín jǐng gào zhī wǒ xiān kāi yí shī huí zhí， zài fēn bié qù chū rù jìng、 dà shǐ guǎn bǔ bàn ne。','Công an bảo con làm biên nhận mất trước, rồi lần lượt đến cục xuất nhập cảnh và đại sứ quán để làm lại ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_04','V624','父亲',4,'需要加急汇款给你吗，补办护照、临时通行证明会产生费用？','xū yào jiā jí huì kuǎn gěi nǐ ma， bǔ bàn hù zhào、 lín shí tōng xíng zhèng míng huì chǎn shēng fèi yòng？','Có cần bố mẹ chuyển tiền gấp cho con không, làm lại hộ chiếu, giấy thông hành tạm thời chắc phát sinh chi phí đấy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_05','V624','阮明',5,'暂时不用，校内还有备用生活费，足够支付全部手续工本费。','zàn shí bù yòng， xiào nèi hái yǒu bèi yòng shēng huó fèi， zú gòu zhī fù quán bù shǒu xù gōng běn fèi。','Tạm thời chưa cần đâu ạ, trong trường con còn tiền sinh hoạt dự phòng, đủ trang trải hết các khoản lệ phí thủ tục rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_06','V624','母亲',6,'全程保留所有报案单据，每一步办理完及时跟我们同步进度。','quán chéng bǎo liú suǒ yǒu bào àn dān jù， měi yī bù bàn lǐ wán jí shí gēn wǒ men tóng bù jìn dù。','Con nhớ giữ lại toàn bộ biên nhận trình báo, làm xong bước nào thì báo tiến độ cho bố mẹ ngay bước đó nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_07','V624','阮明',7,'我每办完一项手续立刻视频同步情况，不让你们一直焦虑。','wǒ měi bàn wán yī xiàng shǒu xù lì kè shì pín tóng bù qíng kuàng， bù ràng nǐ men yì zhí jiāo lǜ。','Con làm xong thủ tục nào là gọi video báo ngay tình hình cho bố mẹ, không để bố mẹ phải lo lắng suốt đâu ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT625','SF5','轻微摔伤生病，先简单文字报平安，再视频细说伤情',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V625','SIT625','P1','twist','ban_chinh_thuc',NULL,'遇到轻微意外，留学生习惯先发简短文字稳住家人情绪，再短时间视频说明具体情况，防止家人瞬间恐慌。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_01','V625','阮明',1,'（文字）妈，下楼不小心轻微摔伤，无大碍，先跟您报平安。','（wén zì） mā， xià lóu bù xiǎo xīn qīng wēi shuāi shāng， wú dà ài， xiān gēn nín bào píng ān。','(Nhắn tin) Mẹ ơi, con xuống cầu thang lỡ bị trầy nhẹ, không sao nghiêm trọng đâu, con báo bình an trước với mẹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_02','V625','母亲',2,'看到消息立刻很担心，方便开视频让我看看伤口情况吗？','kàn dào xiāo xī lì kè hěn dān xīn， fāng biàn kāi shì pín ràng wǒ kàn kàn shāng kǒu qíng kuàng ma？','Thấy tin nhắn là mẹ lo ngay, mẹ mở video nhìn vết thương một chút được không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_03','V625','阮明',3,'刚处理完伤口，纱布包裹住，视频画面看着会让人揪心嘛。','gāng chǔ lǐ wán shāng kǒu， shā bù bāo guǒ zhù， shì pín huà miàn kàn zhe huì ràng rén jiū xīn ma。','Con vừa xử lý vết thương xong, quấn băng gạc vào rồi, hình video nhìn chắc mẹ xót lắm đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_04','V625','母亲',4,'就算轻微擦伤也要让我直观看看，判断需不需要去医院复查。','jiù suàn qīng wēi cā shāng yě yào ràng wǒ zhí guān kàn kàn， pàn duàn xū bù xū yào qù yī yuàn fù chá。','Dù chỉ trầy nhẹ thôi mẹ cũng phải nhìn tận mắt mới yên tâm, để xem có cần đi bệnh viện khám lại không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_05','V625','阮明',5,'那我简短开五分钟视频，只展示腿部擦伤，不细说难受感受。','nà wǒ jiǎn duǎn kāi wǔ fēn zhōng shì pín， zhǐ zhǎn shì tuǐ bù cā shāng， bù xì shuō nán shòu gǎn shòu。','Vậy con mở video ngắn năm phút, chỉ chiếu chỗ trầy ở chân thôi, con không kể chi tiết cảm giác đau đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_06','V625','母亲',6,'之后出门走路小心，上下楼梯放慢速度，避免再次受伤。','zhī hòu chū mén zǒu lù xiǎo xīn， shàng xià lóu tī fàng màn sù dù， bì miǎn zài cì shòu shāng。','Sau này ra đường đi lại cẩn thận nghe con, lên xuống cầu thang đi chậm lại, tránh bị thương lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_07','V625','阮明',7,'我会多加注意，之后受伤第一时间同步文字平安消息。','wǒ huì duō jiā zhù yì， zhī hòu shòu shāng dì yī shí jiān tóng bù wén zì píng ān xiāo xī。','Con sẽ chú ý hơn, sau này lỡ bị thương là con nhắn tin báo bình an ngay lập tức.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT626','SF5','签证续签材料资金不足，远程和父母沟通加急汇款',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V626','SIT626','P1','suon_se','chinh_thuc',NULL,'签证材料资金不达标会直接驳回续签申请，遇到资金缺口家人会优先选择加急汇款渠道，不计较高额手续费保障证件办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_01','V626','阮明',1,'爸，下周就要递交居留续签材料，活期存款余额还差一部分标准。','bà， xià zhōu jiù yào dì jiāo jū liú xù qiān cái liào， huó qī cún kuǎn yú é hái chà yī bù fèn biāo zhǔn。','Bố ơi, tuần sau là con phải nộp hồ sơ gia hạn cư trú rồi, số dư tài khoản thanh toán còn thiếu một phần theo tiêu chuẩn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_02','V626','父亲',2,'还差多少，我今天立刻走加急跨境电汇给你补足流水。','hái chà duō shǎo， wǒ jīn tiān lì kè zǒu jiā jí kuà jìng diàn huì gěi nǐ bǔ zú liú shuǐ。','Còn thiếu bao nhiêu, hôm nay bố chuyển khoản quốc tế khẩn cho con bù đủ ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_03','V626','阮明',3,'还差四千元，加急汇款隔天就能到账，刚好赶上办理日期。','hái chà sì qiān yuán， jiā jí huì kuǎn gé tiān jiù néng dào zhàng， gāng hǎo gǎn shàng bàn lǐ rì qī。','Còn thiếu bốn nghìn tệ ạ, chuyển gấp thì hôm sau tới liền, kịp đúng ngày làm hồ sơ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_04','V626','父亲',4,'加急渠道手续费更高，但是能保证不耽误你的签证办理。','jiā jí qú dào shǒu xù fèi gèng gāo， dàn shì néng bǎo zhèng bù dān wù nǐ de qiān zhèng bàn lǐ。','Chuyển gấp thì phí cao hơn, nhưng chắc chắn không làm chậm trễ việc xin visa của con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_05','V626','阮明',5,'我计算好金额，等资金到账次日立刻打印银行流水。','wǒ jì suàn hǎo jīn é， děng zī jīn dào zhàng cì rì lì kè dǎ yìn yín háng liú shuǐ。','Con tính sẵn số tiền rồi, tiền vừa vào tài khoản là ngày hôm sau con in sao kê ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_06','V626','父亲',6,'收到汇款短信第一时间告知我，确认入账再去大厅办手续。','shōu dào huì kuǎn duǎn xìn dì yī shí jiān gào zhī wǒ， què rèn rù zhàng zài qù dà tīng bàn shǒu xù。','Nhận được tin nhắn báo chuyển tiền là báo bố biết ngay nhé, xác nhận tiền vào tài khoản rồi mới ra sảnh làm thủ tục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_07','V626','阮明',7,'感谢您加急处理汇款，避免签证断签影响在校学习。','gǎn xiè nín jiā jí chǔ lǐ huì kuǎn， bì miǎn qiān zhèng duàn qiān yǐng xiǎng zài xiào xué xí。','Cảm ơn bố đã chuyển tiền gấp giúp con, để tránh việc gián đoạn visa ảnh hưởng đến việc học ở trường.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT627','SF5','航班延误、行程变动，立刻发消息同步家人避免担忧',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V627','SIT627','P1','suon_se','tuy_y',NULL,'出行航班延误、取消属于高频突发变动，国内家长十分在意行程实时动态，子女必须第一时间同步变动消息。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_01','V627','阮明',1,'妈，我原定今天返程航班大面积延误，起飞推迟六个小时。','mā， wǒ yuán dìng jīn tiān fǎn chéng háng bān dà miàn jī yán wù， qǐ fēi tuī chí liù gè xiǎo shí。','Mẹ ơi, chuyến bay về nước hôm nay của con bị hoãn trên diện rộng, giờ cất cánh trễ mất sáu tiếng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_02','V627','母亲',2,'还好你及时发消息，我一直在盯着航班时刻表担心你落地太晚。','hái hǎo nǐ jí shí fā xiāo xī， wǒ yì zhí zài dīng zhe háng bān shí kè biǎo dān xīn nǐ luò dì tài wǎn。','May mà con báo tin kịp thời, mẹ cứ dán mắt vào bảng giờ bay lo con hạ cánh trễ quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_03','V627','阮明',3,'机场安排临时休息区域，提供简餐，不会让我长时间干等。','jī chǎng ān pái lín shí xiū xī qū yù， tí gōng jiǎn cān， bú huì ràng wǒ zhǎng shí jiān gàn děng。','Sân bay có bố trí khu nghỉ tạm, có cả suất ăn nhẹ, nên con không phải ngồi chờ suông cả buổi đâu mẹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_04','V627','母亲',4,'落地到达目的地之后，第一时间给我发一条平安消息吧。','luò dì dào dá mù dì dì zhī hòu， dì yī shí jiān gěi wǒ fā yī tiáo píng ān xiāo xī ba。','Hạ cánh đến nơi rồi thì nhắn ngay cho mẹ một tin báo bình an nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_05','V627','阮明',5,'落地取完行李、坐上交通车辆，立刻同步文字报平安。','luò dì qǔ wán xíng lǐ、 zuò shàng jiāo tōng chē liàng， lì kè tóng bù wén zì bào píng ān。','Con lấy hành lý xong, lên xe đến nơi là con nhắn tin báo bình an ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_06','V627','母亲',6,'路途奔波注意休息，不用硬撑着长时间跟我们视频。','lù tú bēn bō zhù yì xiū xī， bù yòng yìng chēng zhe zhǎng shí jiān gēn wǒ men shì pín。','Đường xa vất vả nhớ nghỉ ngơi, không cần cố gọi video lâu với bố mẹ đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_07','V627','阮明',7,'我会随时同步航班动态，不让您一直悬着心。','wǒ huì suí shí tóng bù háng bān dòng tài， bù ràng nín yì zhí xuán zhe xīn。','Con sẽ cập nhật tình hình chuyến bay liên tục, không để mẹ phải thấp thỏm lo lắng suốt đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT628','SF6','和父母商量寒暑假回国机票时间，对比价格选择合适航班',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V628','SIT628','P1','twist','tuy_y',NULL,'家长选购国际机票会同时考量票价、落地时段、夜间出行安全，不会单纯选择最低价航班。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_01','V628','阮明',1,'寒暑假有两档回国机票，早一点的班次价格贵三成，晚班性价比更高。','hán shǔ jià yǒu liǎng dàng huí guó jī piào， zǎo yì diǎn de bān cì jià gé guì sān chéng， wǎn bān xìng jià bǐ gèng gāo。','Dịp hè đông có hai khung giờ vé máy bay về nước, chuyến sớm hơn giá đắt hơn ba phần mười, chuyến muộn thì đáng đồng tiền hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_02','V628','母亲',2,'晚班抵达越南是深夜，独自打车回家安全方面我们不放心嘛。','wǎn bān dǐ dá yuè nán shì shēn yè， dú zì dǎ chē huí jiā ān quán fāng miàn wǒ men bù fàng xīn ma。','Chuyến muộn về tới Việt Nam là nửa đêm rồi, con tự bắt taxi về nhà một mình bố mẹ không yên tâm về khoản an toàn đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_03','V628','阮明',3,'深夜机场有正规接驳大巴直达市区，比单独打车安全很多。','shēn yè jī chǎng yǒu zhèng guī jiē bó dà bā zhí dá shì qū， bǐ dān dú dǎ chē ān quán hěn duō。','Nửa đêm sân bay vẫn có xe buýt trung chuyển chính quy chạy thẳng vào trung tâm mà, an toàn hơn tự đi taxi một mình nhiều lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_04','V628','父亲',4,'差价不小，如果接驳交通稳妥，可以选择平价晚班航班。','chā jià bù xiǎo， rú guǒ jiē bó jiāo tōng wěn tuǒ， kě yǐ xuǎn zé píng jià wǎn bān háng bān。','Chênh lệch giá cũng kha khá, nếu xe trung chuyển ổn thì có thể chọn chuyến bay muộn giá mềm hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_05','V628','阮明',5,'我查询了机场大巴运营时间，深夜落地仍有专线班车运行。','wǒ chá xún le jī chǎng dà bā yùn yíng shí jiān， shēn yè luò dì réng yǒu zhuān xiàn bān chē yùn xíng。','Con tra rồi, giờ chạy của xe buýt sân bay, nửa đêm hạ cánh vẫn còn tuyến xe chuyên chạy đó ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_06','V628','母亲',6,'那我们折中选择午间航班，价格适中、落地时间也安全。','nà wǒ men zhé zhōng xuǎn zé wǔ jiān háng bān， jià gé shì zhōng、 luò dì shí jiān yě ān quán。','Vậy thì mình chọn dung hòa chuyến bay giữa trưa, giá vừa phải mà giờ hạ cánh cũng an toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_07','V628','阮明',7,'我对比三个航班价格与落地时段，把最优方案发给你们确认。','wǒ duì bǐ sān gè háng bān jià gé yǔ luò dì shí duàn， bǎ zuì yōu fāng àn fā gěi nǐ men què rèn。','Con so sánh giá và giờ hạ cánh của ba chuyến bay rồi, gửi phương án tốt nhất cho bố mẹ xác nhận nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT629','SF6','讨论毕业后规划（留华深造/回国工作），和家人交换想法',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V629','SIT629','P1','suon_se','ban_chinh_thuc',NULL,'中国家庭在子女升学、就业选择上，大多会先倾听子女自身意愿，共同商量长远规划，不强行安排人生道路。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_01','V629','阮明',1,'毕业有两条路线，留在中国读硕士，或者直接回国找相关工作。','bì yè yǒu liǎng tiáo lù xiàn， liú zài zhōng guó dú shuò shì， huò zhě zhí jiē huí guó zhǎo xiāng guān gōng zuò。','Sau khi tốt nghiệp con có hai hướng: ở lại Trung Quốc học thạc sĩ, hoặc về nước tìm việc liên quan luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_02','V629','父亲',2,'留在国内深造汉语专业，未来就业选择会更广阔一些。','liú zài guó nèi shēn zào hàn yǔ zhuān yè， wèi lái jiù yè xuǎn zé huì gèng guǎng kuò yī xiē。','Ở lại trong nước học sâu chuyên ngành tiếng Trung thì sau này cơ hội việc làm sẽ rộng mở hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_03','V629','阮明',3,'回国本地外贸行业也有对口岗位，离家近方便照顾你们。','huí guó běn dì wài mào háng yè yě yǒu duì kǒu gǎng wèi， lí jiā jìn fāng biàn zhào gù nǐ men。','Về nước thì ngành ngoại thương ở địa phương cũng có vị trí phù hợp, lại gần nhà tiện chăm sóc bố mẹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_04','V629','母亲',4,'我们尊重你的个人发展意愿，不会强迫你固定选择一条路。','wǒ men zūn zhòng nǐ de gè rén fā zhǎn yì yuàn， bú huì qiǎng pò nǐ gù dìng xuǎn zé yī tiáo lù。','Bố mẹ tôn trọng nguyện vọng phát triển cá nhân của con, không ép con phải chọn cố định một hướng đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_05','V629','阮明',5,'我先实习半年，感受两边行业环境，再确定最终发展方向。','wǒ xiān shí xí bàn nián， gǎn shòu liǎng biān háng yè huán jìng， zài què dìng zuì zhōng fā zhǎn fāng xiàng。','Con sẽ thực tập trước sáu tháng, trải nghiệm môi trường ngành ở cả hai bên rồi mới quyết định hướng đi cuối cùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_06','V629','父亲',6,'实习期间每月同步你的感受，我们一起分析利弊再做决定。','shí xí qī jiān měi yuè tóng bù nǐ de gǎn shòu， wǒ men yì qǐ fēn xī lì bì zài zuò jué dìng。','Trong thời gian thực tập, mỗi tháng con cập nhật cảm nhận cho bố mẹ, cả nhà cùng phân tích được mất rồi hẵng quyết định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_07','V629','阮明',7,'谢谢爸妈尊重我的规划，有想法第一时间和你们沟通。','xiè xiè bà mā zūn zhòng wǒ de guī huà， yǒu xiǎng fǎ dì yī shí jiān hé nǐ men gōu tōng。','Con cảm ơn bố mẹ đã tôn trọng kế hoạch của con, có ý gì con sẽ trao đổi với bố mẹ ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT630','SF6','签证有效期快到期，视频和父母说明续办流程、所需资金',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V630','SIT630','P1','twist','chinh_thuc',NULL,'居留续签存在固定办理周期，证件上交期间无法出行，留学生需要提前和家人沟通资金、时间安排，预留充足缓冲时间。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_01','V630','阮明',1,'我的学生居留许可还有三十天到期，现在开始准备续签全套材料。','wǒ de xué shēng jū liú xǔ kě hái yǒu sān shí tiān dào qī， xiàn zài kāi shǐ zhǔn bèi xù qiān quán tào cái liào。','Giấy phép cư trú diện du học của con còn ba mươi ngày nữa là hết hạn, giờ con bắt đầu chuẩn bị đầy đủ hồ sơ gia hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_02','V630','父亲',2,'续签需要额外支付手续费，存款流水也有最低余额要求对吧？','xù qiān xū yào é wài zhī fù shǒu xù fèi， cún kuǎn liú shuǐ yě yǒu zuì dī yú é yāo qiú duì ba？','Gia hạn phải trả thêm phí thủ tục, sao kê tiền gửi cũng có yêu cầu số dư tối thiểu đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_03','V630','阮明',3,'工本费金额不高，但是活期流水需要稳定一万元以上留存三个月嘛。','gōng běn fèi jīn é bù gāo， dàn shì huó qī liú shuǐ xū yào wěn dìng yī wàn yuán yǐ shàng liú cún sān gè yuè ma。','Phí làm hồ sơ không nhiều, nhưng số dư tài khoản vãng lai phải duy trì ổn định trên mười nghìn tệ trong ba tháng cơ ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_04','V630','父亲',4,'卡里流动资金不足的话，提前一周告诉我，我提前汇款补足。','kǎ lǐ liú dòng zī jīn bù zú de huà， tí qián yī zhōu gào sù wǒ， wǒ tí qián huì kuǎn bǔ zú。','Nếu trong tài khoản không đủ tiền lưu động thì báo trước một tuần cho bố, bố chuyển khoản bổ sung trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_05','V630','阮明',5,'材料齐全七个工作日办结，办理期间护照要上交出入境大厅。','cái liào qí quán qī gè gōng zuò rì bàn jié， bàn lǐ qī jiān hù zhào yào shàng jiāo chū rù jìng dà tīng。','Hồ sơ đầy đủ thì bảy ngày làm việc là xong, trong thời gian xử lý phải nộp hộ chiếu cho phòng xuất nhập cảnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_06','V630','父亲',6,'上交护照期间出行不方便，记得提前办好临时出行证明。','shàng jiāo hù zhào qī jiān chū xíng bù fāng biàn， jì de tí qián bàn hǎo lín shí chū xíng zhèng míng。','Nộp hộ chiếu thì đi lại sẽ bất tiện, con nhớ làm giấy tờ đi lại tạm thời trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_07','V630','阮明',7,'我会把控办理时间，预留缓冲期，不会出现签证断签的情况。','wǒ huì bǎ kòng bàn lǐ shí jiān， yù liú huǎn chōng qī， bú huì chū xiàn qiān zhèng duàn qiān de qíng kuàng。','Con sẽ tính toán thời gian làm hồ sơ, để dư thời gian đệm, sẽ không để xảy ra tình trạng đứt hạn visa đâu ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT701','SSH1','入住新生宿舍，向宿管领取钥匙、核对宿舍物品清单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V701','SIT701','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍入住必须现场核验室内设施并签字登记，人为损坏物品退房会从住宿押金扣除维修费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_01','V701','阮明',1,'阿姨您好，今天办理入住，麻烦给我宿舍钥匙和门禁卡吧。','ā yí nín hǎo， jīn tiān bàn lǐ rù zhù， má fán gěi wǒ sù shè yào shi hé mén jìn kǎ ba。','Cô ơi, hôm nay em làm thủ tục nhận phòng, phiền cô đưa em chìa khóa phòng với thẻ ra vào nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_02','V701','宿管阿姨',2,'先出示你的录取证件，我们一起进屋核对屋内家具清单哦。','xiān chū shì nǐ de lù qǔ zhèng jiàn， wǒ men yì qǐ jìn wū hé duì wū nèi jiā jù qīng dān ó。','Em đưa giấy báo nhập học trước đi, rồi cô cháu mình vào phòng kiểm tra danh sách đồ đạc trong phòng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_03','V701','阮明',3,'清单上写书桌、衣柜、椅子、空调，我需要逐一检查完好度吗？','qīng dān shàng xiě shū zhuō、 yī guì、 yǐ zi、 kōng tiáo， wǒ xū yào zhú yī jiǎn chá wán hǎo dù ma？','Danh sách ghi có bàn học, tủ quần áo, ghế, điều hòa, em cần kiểm tra từng món xem còn nguyên vẹn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_04','V701','宿管阿姨',4,'对，有划痕、损坏当场标注，退房时就不会扣押金了。','duì， yǒu huà hén、 sǔn huài dāng chǎng biāo zhù， tuì fáng shí jiù bú huì kòu yā jīn le。','Đúng rồi, có vết xước hay hư hỏng thì ghi chú luôn tại chỗ, để lúc trả phòng khỏi bị trừ tiền cọc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_05','V701','阮明',5,'墙面很干净，家电都能正常使用，没有破损地方。','qiáng miàn hěn gān jìng， jiā diàn dōu néng zhèng cháng shǐ yòng， méi yǒu pò sǔn dì fāng。','Tường rất sạch, các thiết bị điện đều dùng bình thường, không có chỗ nào hư hỏng cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_06','V701','宿管阿姨',6,'确认无误就在物品清单签字，钥匙一共两把收好。','què rèn wú wù jiù zài wù pǐn qīng dān qiān zì， yào shi yī gòng liǎng bǎ shōu hǎo。','Xác nhận không có vấn đề gì thì ký vào danh sách đồ đạc, chìa khóa tổng cộng hai chiếc em giữ cẩn thận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_07','V701','阮明',7,'好的，清单我签字，后续宿舍有问题再来找您报修。','hǎo de， qīng dān wǒ qiān zì， hòu xù sù shè yǒu wèn tí zài lái zhǎo nín bào xiū。','Vâng ạ, em ký vào danh sách, sau này phòng có vấn đề gì em lại đến báo cô sửa nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT702','SSH1','宿舍空调故障不制冷，报修物业上门检修',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V702','SIT702','P1','twist','tuy_y',NULL,'校内宿舍家电基础检修、滤网清洗免费，制冷剂、配件更换属于耗材，会统一登记收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_01','V702','阮明',1,'师傅，我宿舍空调吹出来全是热风，完全没法制冷啊。','shī fù， wǒ sù shè kōng tiáo chuī chū lái quán shì rè fēng， wán quán méi fǎ zhì lěng a。','Chú ơi, điều hòa phòng em thổi ra toàn gió nóng, không mát tí nào luôn.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_02','V702','维修师傅',2,'我先开机检测，大概率滤网积灰堵塞，也可能缺制冷剂。','wǒ xiān kāi jī jiǎn cè， dà gài lǜ lǜ wǎng jī huī dǔ sè， yě kě néng quē zhì lěng jì。','Để chú bật máy kiểm tra trước, khả năng cao là lưới lọc bám bụi bị nghẹt, cũng có thể thiếu ga.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_03','V702','阮明',3,'上周还正常使用，昨晚突然出故障，没有人为磕碰损坏嘛。','shàng zhōu hái zhèng cháng shǐ yòng， zuó wǎn tū rán chū gù zhàng， méi yǒu rén wéi kē pèng sǔn huài ma。','Tuần trước vẫn dùng bình thường, tối qua tự nhiên hỏng, không ai va chạm làm hỏng gì cả đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_04','V702','维修师傅',4,'滤网我拆下来清洗，如果缺氟就要登记预约次日加制冷剂。','lǜ wǎng wǒ chāi xià lái qīng xǐ， rú guǒ quē fú jiù yào dēng jì yù yuē cì rì jiā zhì lěng jì。','Chú tháo lưới lọc ra rửa trước, nếu thiếu ga thì phải đăng ký hẹn hôm sau đến bơm ga.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_05','V702','阮明',5,'清洗滤网免费吗，加制冷剂需要我额外支付费用？','qīng xǐ lǜ wǎng miǎn fèi ma， jiā zhì lěng jì xū yào wǒ é wài zhī fù fèi yòng？','Rửa lưới lọc có miễn phí không ạ, bơm ga thì em có phải trả thêm phí không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_06','V702','维修师傅',6,'日常清洗免费，制冷剂损耗需要统一走后勤耗材计费。','rì cháng qīng xǐ miǎn fèi， zhì lěng jì sǔn hào xū yào tǒng yī zǒu hòu qín hào cái jì fèi。','Vệ sinh định kỳ thì miễn phí, còn hao ga thì phải tính chung vào chi phí vật tư hậu cần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_07','V702','阮明',7,'先清洗滤网看看效果，不够制冷再预约加氟。','xiān qīng xǐ lǜ wǎng kàn kàn xiào guǒ， bù gòu zhì lěng zài yù yuē jiā fú。','Vậy rửa lưới lọc trước xem hiệu quả thế nào, không đủ mát thì mình hẹn bơm ga sau nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT703','SSH1','宿舍断电跳闸，找宿管排查电路、恢复供电',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V703','SIT703','P1','that_bai_nhe','tuy_y',NULL,'高校宿舍限制大功率电器，多设备同时使用极易触发过载保护跳闸，违规电器引发故障需学生承担维修费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_01','V703','阮明',1,'阿姨，我宿舍突然全屋断电，插座和顶灯全都没电了。','ā yí， wǒ sù shè tū rán quán wū duàn diàn， chā zuò hé dǐng dēng quán dōu méi diàn le。','Cô ơi, phòng em tự nhiên mất điện cả phòng, ổ cắm với đèn trần đều không có điện luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_02','V703','宿管阿姨',2,'是不是同时使用吹风机、电煮锅大功率电器跳闸？','shì bú shì tóng shí shǐ yòng chuī fēng jī、 diàn zhǔ guō dà gōng lǜ diàn qì tiào zhá？','Có phải cùng lúc dùng máy sấy tóc, nồi nấu điện công suất lớn nên nhảy át không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_03','V703','阮明',3,'我只用电脑和台灯，没有违规大功率电器，不清楚原因。','wǒ zhǐ yòng diàn nǎo hé tái dēng， méi yǒu wéi guī dà gōng lǜ diàn qì， bù qīng chǔ yuán yīn。','Em chỉ dùng máy tính với đèn bàn thôi, không dùng thiết bị công suất lớn trái quy định, em cũng không rõ nguyên nhân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_04','V703','宿管阿姨',4,'宿舍总闸在楼道配电箱，我去合闸，如果再次跳闸就要断电检修线路。','sù shè zǒng zhá zài lóu dào pèi diàn xiāng， wǒ qù hé zhá， rú guǒ zài cì tiào zhá jiù yào duàn diàn jiǎn xiū xiàn lù。','Cầu dao tổng của phòng ở tủ điện hành lang, cô đi đóng lại, nếu nhảy lại lần nữa thì phải cắt điện kiểm tra đường dây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_05','V703','阮明',5,'合闸之后要是反复断电，今晚没法开灯学习怎么办？','hé zhá zhī hòu yào shì fǎn fù duàn diàn， jīn wǎn méi fǎ kāi dēng xué xí zěn me bàn？','Đóng lại rồi mà cứ mất điện liên tục thì tối nay em không bật đèn học bài được, làm sao đây ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_06','V703','宿管阿姨',6,'反复跳闸说明线路隐患，今晚临时安排隔壁空宿舍让你自习。','fǎn fù tiào zhá shuō míng xiàn lù yǐn huàn， jīn wǎn lín shí ān pái gé bì kōng sù shè ràng nǐ zì xí。','Nhảy át liên tục là dấu hiệu đường dây có vấn đề tiềm ẩn, tối nay cô sắp xếp tạm cho em sang phòng trống bên cạnh học bài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_07','V703','阮明',7,'麻烦您先合闸恢复供电，我之后不用多余电器避免跳闸。','má fán nín xiān hé zhá huī fù gōng diàn， wǒ zhī hòu bù yòng duō yú diàn qì bì miǎn tiào zhá。','Phiền cô đóng lại cầu dao để có điện trước đã, sau này em sẽ không dùng thêm thiết bị điện để tránh nhảy át nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT704','SSH1','宿舍楼道公共热水机不出热水，咨询宿管使用规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V704','SIT704','P1','suon_se','tuy_y',NULL,'校园公共热水设备统一定时启停，夜间停止加热节约水电，是国内高校通用管理方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_01','V704','阮明',1,'阿姨，楼道热水机按了出水键，一直没有热水流出呢。','ā yí， lóu dào rè shuǐ jī àn le chū shuǐ jiàn， yì zhí méi yǒu rè shuǐ liú chū ne。','Cô ơi, máy nước nóng ở hành lang em bấm nút xả nước rồi mà mãi không thấy nước nóng chảy ra.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_02','V704','宿管阿姨',2,'机器有定时加热时段，早上六点到晚上十一点才有热水哦。','jī qì yǒu dìng shí jiā rè shí duàn， zǎo shàng liù diǎn dào wǎn shàng shí yì diǎn cái yǒu rè shuǐ ó。','Máy có khung giờ hẹn giờ đun đó, từ sáu giờ sáng đến mười một giờ tối mới có nước nóng thôi.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_03','V704','阮明',3,'现在十一点半，刚好过了加热时段，难怪不出热水。','xiàn zài shí yì diǎn bàn， gāng hǎo guò le jiā rè shí duàn， nán guài bù chū rè shuǐ。','Giờ là mười một giờ rưỡi, vừa qua khung giờ đun nước nóng, thảo nào không có nước nóng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_04','V704','宿管阿姨',4,'如果中途停水，机器缺水也会暂停出水，明天一早恢复。','rú guǒ zhōng tú tíng shuǐ， jī qì quē shuǐ yě huì zàn tíng chū shuǐ， míng tiān yī zǎo huī fù。','Nếu giữa chừng mất nước thì máy thiếu nước cũng sẽ tạm ngừng xả, sáng mai sẽ có lại bình thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_05','V704','阮明',5,'那我只能明天早上再来接热水洗漱、泡热水杯。','nà wǒ zhǐ néng míng tiān zǎo shàng zài lái jiē rè shuǐ xǐ shù、 pào rè shuǐ bēi。','Vậy thì mai sáng em mới lấy nước nóng để rửa mặt, pha cốc nước nóng được rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_06','V704','宿管阿姨',6,'尽量避开晚间高峰，八点左右热水出水最稳定。','jǐn liàng bì kāi wǎn jiān gāo fēng， bā diǎn zuǒ yòu rè shuǐ chū shuǐ zuì wěn dìng。','Cố gắng tránh giờ cao điểm buổi tối, khoảng tám giờ nước nóng ra ổn định nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_07','V704','阮明',7,'我记好热水供应时间，不再错过取水时段。','wǒ jì hǎo rè shuǐ gōng yìng shí jiān， bù zài cuò guò qǔ shuǐ shí duàn。','Em ghi nhớ giờ có nước nóng rồi, sẽ không bỏ lỡ giờ lấy nước nữa đâu ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT705','SSH1','想加装简易收纳架，询问宿管宿舍墙面能否打孔粘贴',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V705','SIT705','P1','twist','ban_chinh_thuc',NULL,'学生宿舍墙面严禁打孔、钉钉子，保护墙体完整，避免退房产生墙面修补扣款。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_01','V705','阮明',1,'阿姨，我想买墙上收纳架，能不能在墙面打孔固定？','ā yí， wǒ xiǎng mǎi qiáng shàng shōu nà jià， néng bù néng zài qiáng miàn dǎ kǒng gù dìng？','Cô ơi, em muốn mua giá treo đồ gắn tường, có được khoan tường để cố định không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_02','V705','宿管阿姨',2,'宿舍墙体不能打孔，打孔留下孔洞退房要扣修补押金。','sù shè qiáng tǐ bù néng dǎ kǒng， dǎ kǒng liú xià kǒng dòng tuì fáng yào kòu xiū bǔ yā jīn。','Tường phòng không được khoan đâu, khoan để lại lỗ thì lúc trả phòng sẽ bị trừ tiền cọc sửa chữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_03','V705','阮明',3,'那无痕粘钩、免钉粘贴式置物架可以使用吗？','nà wú hén zhān gōu、 miǎn dīng zhān tiē shì zhì wù jià kě yǐ shǐ yòng ma？','Vậy dùng móc dán không để lại vết, kiểu giá đồ dán không cần đinh thì có được dùng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_04','V705','宿管阿姨',4,'无痕粘胶可以，但退房必须完整撕掉，不能残留胶印嘛。','wú hén zhān jiāo kě yǐ， dàn tuì fáng bì xū wán zhěng sī diào， bù néng cán liú jiāo yìn ma。','Keo dán không để lại vết thì được, nhưng lúc trả phòng phải bóc sạch hoàn toàn, không được để lại vết keo đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_05','V705','阮明',5,'如果粘胶撕掉留有痕迹，会收取墙面清洁费对吗？','rú guǒ zhān jiāo sī diào liú yǒu hén jì， huì shōu qǔ qiáng miàn qīng jié fèi duì ma？','Nếu bóc keo dán mà vẫn còn để lại vết thì có bị thu phí vệ sinh tường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_06','V705','宿管阿姨',6,'少量胶印擦拭干净即可，大面积顽固污渍才收费。','shǎo liàng jiāo yìn cā shì gān jìng jí kě， dà miàn jī wán gù wū zì cái shōu fèi。','Vết keo ít thì lau sạch là được, chỉ có vết bẩn cứng đầu diện rộng mới bị tính phí thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_07','V705','阮明',7,'我只买免钉粘贴款收纳架，不破坏墙面墙体。','wǒ zhǐ mǎi miǎn dīng zhān tiē kuǎn shōu nà jià， bù pò huài qiáng miàn qiáng tǐ。','Vậy em chỉ mua loại giá dán không cần đinh thôi, không làm hỏng tường đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT706','SSH1','室友作息差异，协商关灯、安静学习的作息时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V706','SIT706','P1','suon_se','tuy_y',NULL,'多人宿舍室友作息不同是普遍情况，国内学生一般会互相协商灯光、噪音、休息时间，彼此迁就包容。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_01','V706','阮明',1,'小林，我习惯十一点关灯休息，你晚上复习灯光会影响我睡觉。','xiǎo lín， wǒ xí guàn shí yì diǎn guān dēng xiū xī， nǐ wǎn shàng fù xí dēng guāng huì yǐng xiǎng wǒ shuì jiào。','Tiểu Lâm, tớ quen tắt đèn nghỉ lúc mười một giờ, đèn cậu bật ôn bài buổi tối làm ảnh hưởng giấc ngủ của tớ đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_02','V706','小林',2,'我专业课作业多，经常要学到十二点，咱们折中调整一下吧。','wǒ zhuān yè kè zuò yè duō， jīng cháng yào xué dào shí èr diǎn， zán men zhé zhōng tiáo zhěng yī xià ba。','Bài vở chuyên ngành của tớ nhiều lắm, thường phải học đến mười hai giờ, thôi mình thỏa hiệp điều chỉnh lại chút nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_03','V706','阮明',3,'那你用桌面小台灯，十一点后关掉头顶大灯可以吗？','nà nǐ yòng zhuō miàn xiǎo tái dēng， shí yì diǎn hòu guān diào tóu dǐng dà dēng kě yǐ ma？','Vậy cậu dùng đèn bàn nhỏ, sau mười một giờ tắt đèn trần đi được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_04','V706','小林',4,'没问题，我搭配静音鼠标，不发出敲击键盘噪音打扰你。','méi wèn tí， wǒ dā pèi jìng yīn shǔ biāo， bù fā chū qiāo jī jiàn pán zào yīn dǎ rǎo nǐ。','Được chứ, tớ dùng thêm chuột êm, không gõ bàn phím lạch cạch làm phiền cậu đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_05','V706','阮明',5,'早上七点我会早起洗漱，我动作轻一点不吵醒你休息。','zǎo shàng qī diǎn wǒ huì zǎo qǐ xǐ shù， wǒ dòng zuò qīng yì diǎn bù chǎo xǐng nǐ xiū xī。','Sáng bảy giờ tớ sẽ dậy sớm rửa mặt, tớ sẽ nhẹ nhàng để không đánh thức cậu dậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_06','V706','小林',6,'互相体谅作息，宿舍居住才能舒服不产生矛盾。','hù xiāng tǐ liàng zuò xī， sù shè jū zhù cái néng shū fú bù chǎn shēng máo dùn。','Hai đứa thông cảm giờ giấc của nhau thì ở chung phòng mới thoải mái, không xảy ra mâu thuẫn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_07','V706','阮明',7,'太好了，咱们就按这个作息约定长期配合。','tài hǎo le， zán men jiù àn zhè ge zuò xī yuē dìng cháng qī pèi hé。','Tuyệt quá, vậy mình cứ theo thỏa thuận giờ giấc này mà phối hợp lâu dài nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT707','SSH1','宿舍晾晒衣物空间不足，咨询楼顶晾晒区开放时段',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V707','SIT707','P1','twist','tuy_y',NULL,'楼顶露天晾晒区夜间关闭，防止衣物夜间受潮、丢失，同时避免高空坠物安全隐患。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_01','V707','阮明',1,'阿姨，阳台晾衣杆挂满衣服，没有位置晾晒刚洗的床单。','ā yí， yáng tái liàng yī gān guà mǎn yī fú， méi yǒu wèi zhì liàng shài gāng xǐ de chuáng dān。','Cô ơi, sào phơi ngoài ban công treo kín đồ rồi, không còn chỗ phơi ga giường mới giặt nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_02','V707','宿管阿姨',2,'宿舍楼顶有公共晾晒区，但是只白天七点到十八点开放。','sù shè lóu dǐng yǒu gōng gòng liàng shài qū， dàn shì zhǐ bái tiān qī diǎn dào shí bā diǎn kāi fàng。','Trên sân thượng ký túc xá có khu phơi chung, nhưng chỉ mở ban ngày từ bảy giờ đến mười tám giờ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_03','V707','阮明',3,'现在傍晚六点半，马上到关闭时间，今天还能上楼顶晾衣服吗？','xiàn zài bàng wǎn liù diǎn bàn， mǎ shàng dào guān bì shí jiān， jīn tiān hái néng shàng lóu dǐng liàng yī fú ma？','Bây giờ sáu rưỡi chiều rồi, sắp đến giờ đóng cửa, hôm nay còn lên sân thượng phơi đồ được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_04','V707','宿管阿姨',4,'十八点保洁会收回露天衣物，晚一点容易夜间受潮发霉嘛。','shí bā diǎn bǎo jié huì shōu huí lù tiān yī wù， wǎn yì diǎn róng yì yè jiān shòu cháo fā méi ma。','Mười tám giờ là bảo vệ vệ sinh thu đồ ngoài trời về rồi, phơi muộn dễ bị ẩm mốc qua đêm lắm.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_05','V707','阮明',5,'那我明天一早七点上楼顶，抢占晾晒位置晒大件被褥。','nà wǒ míng tiān yī zǎo qī diǎn shàng lóu dǐng， qiǎng zhàn liàng shài wèi zhì shài dà jiàn bèi rù。','Vậy mai em dậy sớm bảy giờ lên sân thượng giành chỗ phơi mấy cái chăn đệm to.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_06','V707','宿管阿姨',6,'楼顶风大，记得带夹子固定衣物，防止被风吹落丢失。','lóu dǐng fēng dà， jì de dài jiā zi gù dìng yī wù， fáng zhǐ bèi fēng chuī luò diū shī。','Trên sân thượng gió lớn lắm, nhớ mang kẹp cố định quần áo, không thì gió thổi bay mất đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_07','V707','阮明',7,'好，我明天提前上楼晾晒大件床上用品。','hǎo， wǒ míng tiān tí qián shàng lóu liàng shài dà jiàn chuáng shàng yòng pǐn。','Dạ, mai em lên sớm phơi mấy món đồ giường chiếu to.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT708','SSH1','宿舍公共垃圾桶满溢，询问保洁阿姨清运时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V708','SIT708','P1','suon_se','tuy_y',NULL,'国内校园推行垃圾分类，楼道垃圾桶定时清运，满溢时可使用楼下备用分类垃圾桶。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_01','V708','阮明',1,'阿姨，楼道垃圾桶全部装满垃圾，没法再投放废弃物了。','ā yí， lóu dào lā jī tǒng quán bù zhuāng mǎn lā jī， méi fǎ zài tóu fàng fèi qì wù le。','Cô ơi, thùng rác ở hành lang đầy ắp rồi, không còn chỗ bỏ rác nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_02','V708','保洁李阿姨',2,'我每天上午九点、下午四点各清运一次垃圾哈。','wǒ měi tiān shàng wǔ jiǔ diǎn、 xià wǔ sì diǎn gè qīng yùn yī cì lā jī hā。','Cô dọn rác mỗi ngày hai lần, chín giờ sáng với bốn giờ chiều nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_03','V708','阮明',3,'现在下午两点，还要等两小时才能清空垃圾桶吗？','xiàn zài xià wǔ liǎng diǎn， hái yào děng liǎng xiǎo shí cái néng qīng kōng lā jī tǒng ma？','Giờ mới hai giờ chiều, vậy phải đợi thêm hai tiếng nữa mới dọn được thùng rác hả cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_04','V708','保洁李阿姨',4,'楼下门口有备用分类垃圾桶，可以暂时投放垃圾。','lóu xià mén kǒu yǒu bèi yòng fēn lèi lā jī tǒng， kě yǐ zàn shí tóu fàng lā jī。','Ở cửa tầng dưới có thùng rác phân loại dự phòng, con có thể bỏ rác tạm ở đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_05','V708','阮明',5,'我先把垃圾带到楼下备用桶，等您四点再来清运。','wǒ xiān bǎ lā jī dài dào lóu xià bèi yòng tǒng， děng nín sì diǎn zài lái qīng yùn。','Vậy con mang rác xuống thùng dự phòng dưới đó trước, đợi bốn giờ cô lên dọn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_06','V708','保洁李阿姨',6,'垃圾分类记得分开投放，纸类、塑料不要混在一起。','lā jī fēn lèi jì de fēn kāi tóu fàng， zhǐ lèi、 sù liào bú yào hùn zài yì qǐ。','Nhớ phân loại rác cho rõ ràng nhé, giấy với nhựa đừng để lẫn vào nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_07','V708','阮明',7,'我会做好垃圾分类投放，不给您增加分拣工作量。','wǒ huì zuò hǎo lā jī fēn lèi tóu fàng， bù gěi nín zēng jiā fēn jiǎn gōng zuò liàng。','Con sẽ phân loại rác cẩn thận, không để cô mất công phân loại lại đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT709','SSH1','宿舍门禁卡丢失，到宿管处挂失补办门禁卡',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V709','SIT709','P1','that_bai_nhe','ban_chinh_thuc',NULL,'宿舍门禁卡丢失必须第一时间挂失锁卡，保障宿舍财物安全；补办卡片统一收取工本费，制卡设备故障会发放临时通行凭证。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_01','V709','阮明',1,'阿姨，我的宿舍门禁卡昨天外出弄丢了，前来挂失补办。','ā yí， wǒ de sù shè mén jìn kǎ zuó tiān wài chū nòng diū le， qián lái guà shī bǔ bàn。','Cô ơi, thẻ ra vào ký túc xá của em hôm qua đi ra ngoài làm mất rồi, em đến báo mất và xin làm lại ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_02','V709','宿管阿姨',2,'先登记挂失，旧卡立刻锁死，防止别人开门进入宿舍。','xiān dēng jì guà shī， jiù kǎ lì kè suǒ sǐ， fáng zhǐ bié rén kāi mén jìn rù sù shè。','Trước tiên đăng ký báo mất, thẻ cũ sẽ bị khóa ngay để tránh người khác mở cửa vào phòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_03','V709','阮明',3,'补办新门禁卡需要支付工本费吗，当场就能拿到卡片？','bǔ bàn xīn mén jìn kǎ xū yào zhī fù gōng běn fèi ma， dāng chǎng jiù néng ná dào kǎ piàn？','Làm lại thẻ mới có phải đóng phí làm thẻ không ạ, và có thể nhận thẻ ngay không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_04','V709','宿管阿姨',4,'补办一张门禁卡二十元工本费，制卡机器今天故障维修嘛。','bǔ bàn yī zhāng mén jìn kǎ èr shí yuán gōng běn fèi， zhì kǎ jī qì jīn tiān gù zhàng wéi xiū ma。','Làm lại một thẻ mất hai mươi tệ phí làm thẻ, nhưng máy làm thẻ hôm nay đang hỏng phải sửa mất rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_05','V709','阮明',5,'那今天拿不到新卡，晚上怎么刷卡回宿舍休息？','nà jīn tiān ná bú dào xīn kǎ， wǎn shàng zěn me shuā kǎ huí sù shè xiū xī？','Vậy hôm nay em chưa lấy được thẻ mới, tối nay làm sao quẹt thẻ về phòng nghỉ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_06','V709','宿管阿姨',6,'我给你开具临时纸质通行条，今晚凭纸条进出楼栋。','wǒ gěi nǐ kāi jù lín shí zhǐ zhì tōng xíng tiáo， jīn wǎn píng zhǐ tiáo jìn chū lóu dòng。','Cô sẽ cấp cho em một tờ giấy thông hành tạm thời, tối nay em cầm giấy này ra vào tòa nhà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_07','V709','阮明',7,'明天机器修好我再来缴费领新门禁卡。','míng tiān jī qì xiū hǎo wǒ zài lái jiǎo fèi lǐng xīn mén jìn kǎ。','Vậy mai máy sửa xong em sẽ quay lại đóng phí nhận thẻ mới ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT710','SSH1','校外租房看房，和房东核对家具家电完好情况',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V710','SIT710','P1','suon_se','ban_chinh_thuc',NULL,'校外租房入住前必须逐项核对房屋设施并书面记录原有损坏，避免退租时房东以破损为由克扣押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_01','V710','阮明',1,'刘哥，我们一起核对屋内家电、家具，记录破损地方吧。','liú gē， wǒ men yì qǐ hé duì wū nèi jiā diàn、 jiā jù， jì lù pò sǔn dì fāng ba。','Anh Lưu ơi, mình cùng kiểm tra điện gia dụng, đồ đạc trong phòng rồi ghi lại chỗ nào hư hỏng nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_02','V710','房东',2,'冰箱、洗衣机、空调全部试机，有问题当场写进租房合同。','bīng xiāng、 xǐ yī jī、 kōng tiáo quán bù shì jī， yǒu wèn tí dāng chǎng xiě jìn zū fáng hé tóng。','Tủ lạnh, máy giặt, điều hòa đều thử máy hết, có vấn đề gì ghi luôn vào hợp đồng thuê nhà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_03','V710','阮明',3,'衣柜门板有一道小划痕，墙面墙角轻微掉皮，我标注下来。','yī guì mén bǎn yǒu yī dào xiǎo huà hén， qiáng miàn qiáng jiǎo qīng wēi diào pí， wǒ biāo zhù xià lái。','Cánh tủ quần áo có một vết xước nhỏ, góc tường bị bong tróc nhẹ, tôi ghi chú lại đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_04','V710','房东',4,'这些原有轻微损伤全部备注，退房不会扣你的押金。','zhè xiē yuán yǒu qīng wēi sǔn shāng quán bù bèi zhù， tuì fáng bú huì kòu nǐ de yā jīn。','Những hư hỏng nhỏ có sẵn này đều được ghi chú hết, khi trả nhà sẽ không bị trừ tiền cọc đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_05','V710','阮明',5,'水电表初始读数也一起记录，避免结算时产生争议。','shuǐ diàn biǎo chū shǐ dú shù yě yì qǐ jì lù， bì miǎn jié suàn shí chǎn shēng zhēng yì。','Chỉ số điện nước ban đầu cũng nên ghi lại luôn, để tránh phát sinh tranh cãi khi thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_06','V710','房东',6,'没问题，所有物品、读数核对完，我们签署纸质租房合同。','méi wèn tí， suǒ yǒu wù pǐn、 dú shù hé duì wán， wǒ men qiān shǔ zhǐ zhì zū fáng hé tóng。','Không vấn đề gì, kiểm tra xong hết đồ đạc và chỉ số rồi thì mình ký hợp đồng giấy luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_07','V710','阮明',7,'全部设备正常使用，破损全部登记，可以签约入住。','quán bù shè bèi zhèng cháng shǐ yòng， pò sǔn quán bù dēng jì， kě yǐ qiān yuē rù zhù。','Tất cả thiết bị đều dùng bình thường, hư hỏng đã ghi nhận hết, có thể ký hợp đồng chuyển vào ở rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT711','SSH2','食堂充值机无法读卡，找食堂工作人员处理饭卡故障',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V711','SIT711','P1','twist','tuy_y',NULL,'校园饭卡内置磁条，手机、钥匙长期放在一起容易消磁失效，消磁卡片无法修复只能补办。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_01','V711','阮明',1,'你好，校园饭卡放到充值机，机器完全识别不出卡片啊。','nǐ hǎo， xiào yuán fàn kǎ fàng dào chōng zhí jī， jī qì wán quán shí bié bù chū kǎ piàn a。','Chào chị, em đưa thẻ ăn của trường vào máy nạp tiền mà máy không nhận diện được thẻ luôn.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_02','V711','工作人员',2,'是不是卡片弯折、消磁了，放到读卡窗口多试两次。','shì bú shì kǎ piàn wān zhé、 xiāo cí le， fàng dào dú kǎ chuāng kǒu duō shì liǎng cì。','Không biết có phải thẻ bị cong hay bị mất từ không, em đặt vào khe đọc thẻ thử thêm vài lần xem.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_03','V711','阮明',3,'反复摆放五次都无反应，昨天还正常充值用餐嘛。','fǎn fù bǎi fàng wǔ cì dōu wú fǎn yìng， zuó tiān hái zhèng cháng chōng zhí yòng cān ma。','Em thử đi thử lại năm lần rồi vẫn không được, hôm qua còn nạp tiền dùng bình thường mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_04','V711','工作人员',4,'卡片消磁只能补办新卡，旧卡余额可以转移到新卡里。','kǎ piàn xiāo cí zhǐ néng bǔ bàn xīn kǎ， jiù kǎ yú é kě yǐ zhuǎn yí dào xīn kǎ lǐ。','Thẻ bị mất từ rồi thì chỉ có cách làm thẻ mới thôi, số dư trong thẻ cũ có thể chuyển sang thẻ mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_05','V711','阮明',5,'补办饭卡需要携带什么证件，多久能拿到新卡片？','bǔ bàn fàn kǎ xū yào xié dài shén me zhèng jiàn， duō jiǔ néng ná dào xīn kǎ piàn？','Làm lại thẻ ăn cần mang giấy tờ gì ạ, và mất bao lâu thì lấy được thẻ mới ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_06','V711','工作人员',6,'带护照、学生证，十分钟制卡完成，当场转移余额。','dài hù zhào、 xué shēng zhèng， shí fēn zhōng zhì kǎ wán chéng， dāng chǎng zhuǎn yí yú é。','Mang hộ chiếu với thẻ sinh viên, mười phút là làm xong thẻ, chuyển số dư luôn tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_07','V711','阮明',7,'我现在回宿舍拿证件，过来补办饭卡转移余额。','wǒ xiàn zài huí sù shè ná zhèng jiàn， guò lái bǔ bàn fàn kǎ zhuǎn yí yú é。','Vậy giờ em về phòng lấy giấy tờ, rồi quay lại làm thẻ ăn và chuyển số dư ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT712','SSH2','丢失校园饭卡，挂失冻结余额、补办新饭卡',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V712','SIT712','P1','suon_se','ban_chinh_thuc',NULL,'饭卡丢失第一时间挂失可保护卡内余额，挂失后旧卡永久失效，余额完整迁移至新卡片。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_01','V712','阮明',1,'您好，我的校园饭卡丢失，麻烦先帮我挂失冻结余额。','nín hǎo， wǒ de xiào yuán fàn kǎ diū shī， má fán xiān bāng wǒ guà shī dòng jié yú é。','Chào chị, em bị mất thẻ ăn của trường, phiền chị giúp em báo mất khóa số dư lại trước ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_02','V712','工作人员',2,'报你的姓名、学号，系统马上锁定旧卡，无法刷卡消费。','bào nǐ de xìng míng、 xué hào， xì tǒng mǎ shàng suǒ dìng jiù kǎ， wú fǎ shuā kǎ xiāo fèi。','Cho tôi tên với mã số sinh viên của em, hệ thống sẽ khóa thẻ cũ ngay, không quẹt thanh toán được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_03','V712','阮明',3,'卡里还有一百二十元余额，挂失后能完整转移到新卡吗？','kǎ lǐ hái yǒu yì bǎi èr shí yuán yú é， guà shī hòu néng wán zhěng zhuǎn yí dào xīn kǎ ma？','Trong thẻ còn một trăm hai mươi tệ, báo mất xong có chuyển được đầy đủ sang thẻ mới không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_04','V712','工作人员',4,'全部余额无损转移，仅收取十元新卡工本费。','quán bù yú é wú sǔn zhuǎn yí， jǐn shōu qǔ shí yuán xīn kǎ gōng běn fèi。','Toàn bộ số dư sẽ được chuyển nguyên vẹn, chỉ thu mười tệ phí làm thẻ mới thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_05','V712','阮明',5,'挂失之后如果有人捡到旧卡，也不能刷卡消费了对吧？','guà shī zhī hòu rú guǒ yǒu rén jiǎn dào jiù kǎ， yě bù néng shuā kǎ xiāo fèi le duì ba？','Sau khi báo mất, nếu có ai nhặt được thẻ cũ thì cũng không quẹt tiêu được nữa đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_06','V712','工作人员',6,'没错，挂失永久锁死旧卡，捡到也无法使用。','méi cuò， guà shī yǒng jiǔ suǒ sǐ jiù kǎ， jiǎn dào yě wú fǎ shǐ yòng。','Đúng vậy, báo mất là khóa vĩnh viễn thẻ cũ luôn, có nhặt được cũng không dùng được đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_07','V712','阮明',7,'我现在补办新卡，今晚就能正常去食堂吃饭。','wǒ xiàn zài bǔ bàn xīn kǎ， jīn wǎn jiù néng zhèng cháng qù shí táng chī fàn。','Vậy giờ em làm lại thẻ mới, tối nay là có thể ra căng tin ăn cơm bình thường rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT713','SSH2','食堂错打不喜欢的菜品，询问能否免费更换菜品',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V713','SIT713','P1','twist','tuy_y',NULL,'食堂菜品盛出后无法回收更换，防止交叉污染、食品安全问题，点餐提前告知忌口是更稳妥的方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_01','V713','阮明',1,'阿姨，我不爱吃青椒，刚刚窗口误打了青椒炒肉，能换一份别的菜吗？','ā yí， wǒ bù ài chī qīng jiāo， gāng gāng chuāng kǒu wù dǎ le qīng jiāo chǎo ròu， néng huàn yī fèn bié de cài ma？','Cô ơi, em không ăn được ớt chuông, lúc nãy quầy múc nhầm món thịt xào ớt chuông, đổi giúp em món khác được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_02','V713','打菜阿姨',2,'已经盛到餐盘里的菜品，没法回收更换，会影响食品安全嘛。','yǐ jīng shèng dào cān pán lǐ de cài pǐn， méi fǎ huí shōu gēng huàn， huì yǐng xiǎng shí pǐn ān quán ma。','Món đã múc vào khay rồi thì không thu hồi đổi lại được đâu, làm vậy ảnh hưởng an toàn thực phẩm lắm.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_03','V713','阮明',3,'我一口都没动，只是拿到手才发现里面全是青椒。','wǒ yī kǒu dōu méi dòng， zhǐ shì ná dào shǒu cái fā xiàn lǐ miàn quán shì qīng jiāo。','Em chưa động đũa miếng nào cả, chỉ là vừa cầm lên mới phát hiện toàn ớt chuông thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_04','V713','打菜阿姨',4,'未食用也不能退回，下次排队提前跟我说避开青椒菜品。','wèi shí yòng yě bù néng tuì huí， xià cì pái duì tí qián gēn wǒ shuō bì kāi qīng jiāo cài pǐn。','Chưa ăn cũng không trả lại được, lần sau xếp hàng thì nói trước với cô để tránh món có ớt chuông nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_05','V713','阮明',5,'那只能下次点餐提前说明忌口，这份我打包送给同学。','nà zhǐ néng xià cì diǎn cān tí qián shuō míng jì kǒu， zhè fèn wǒ dǎ bāo sòng gěi tóng xué。','Vậy thôi lần sau gọi món em sẽ nói trước là kiêng gì, phần này em gói đem cho bạn ăn vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_06','V713','打菜阿姨',6,'下次点餐提前告知忌口食材，我给你单独打别的菜品。','xià cì diǎn cān tí qián gào zhī jì kǒu shí cái， wǒ gěi nǐ dān dú dǎ bié de cài pǐn。','Lần sau gọi món cứ nói trước nguyên liệu mình kiêng ăn, cô sẽ múc riêng cho em món khác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_07','V713','阮明',7,'我记住了，下次打菜提前说明不吃的食材。','wǒ jì zhù le， xià cì dǎ cài tí qián shuō míng bù chī de shí cái。','Em nhớ rồi ạ, lần sau múc đồ ăn em sẽ nói trước những thứ em không ăn được.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT714','SSH2','校园奶茶店点单，询问甜度、冰度可选标准',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V714','SIT714','P1','suon_se','tuy_y',NULL,'国内奶茶饮品可自由调整甜度、冰量，基础小料大多免费添加，是茶饮店通用服务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_01','V714','阮明',1,'你好，一杯原味奶茶，甜度和冰度有几种选择呢？','nǐ hǎo， yī bēi yuán wèi nǎi chá， tián dù hé bīng dù yǒu jǐ zhǒng xuǎn zé ne？','Chào chị, cho em một ly trà sữa nguyên vị, độ ngọt với độ đá có mấy mức để chọn vậy chị?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_02','V714','店员',2,'甜度分无糖、三分糖、五分糖、七分糖、全糖五档哦。','tián dù fēn wú táng、 sān fēn táng、 wǔ fēn táng、 qī fēn táng、 quán táng wǔ dàng ó。','Độ ngọt có năm mức: không đường, ba phần đường, năm phần đường, bảy phần đường với đường đầy đủ nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_03','V714','阮明',3,'冰度常温、少冰、正常冰、去冰，全部都能选吗？','bīng dù cháng wēn、 shǎo bīng、 zhèng cháng bīng、 qù bīng， quán bù dōu néng xuǎn ma？','Độ đá thì nhiệt độ thường, ít đá, đá bình thường, không đá, đều chọn được hết đúng không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_04','V714','店员',4,'是的，任意搭配，另外可以免费加珍珠、椰果两种小料。','shì de， rèn yì dā pèi， lìng wài kě yǐ miǎn fèi jiā zhēn zhū、 yē guǒ liǎng zhǒng xiǎo liào。','Đúng rồi, kết hợp thoải mái, với lại được miễn phí thêm trân châu với thạch dừa hai loại topping.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_05','V714','阮明',5,'那五分糖、少冰，再加一份珍珠，麻烦帮我制作。','nà wǔ fēn táng、 shǎo bīng， zài jiā yī fèn zhēn zhū， má fán bāng wǒ zhì zuò。','Vậy cho em năm phần đường, ít đá, thêm một phần trân châu, phiền chị làm giúp em nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_06','V714','店员',6,'好的，一共八元，扫码付款后在取餐口等候就行。','hǎo de， yī gòng bā yuán， sǎo mǎ fù kuǎn hòu zài qǔ cān kǒu děng hòu jiù xíng。','Được rồi, tổng cộng tám tệ, quét mã thanh toán xong thì đợi ở quầy lấy đồ nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_07','V714','阮明',7,'好，我扫码支付，在这里等奶茶做好。','hǎo， wǒ sǎo mǎ zhī fù， zài zhè lǐ děng nǎi chá zuò hǎo。','Dạ, em quét mã thanh toán, em đứng đây đợi trà sữa làm xong.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT715','SSH2','自带饭盒去食堂打包饭菜，咨询打包收费规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V715','SIT715','P1','suon_se','tuy_y',NULL,'国内倡导减少一次性塑料用品，自带饭盒打包可免收餐盒打包费，是校园食堂环保规定。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_01','V715','阮明',1,'您好，我自带饭盒打包饭菜，还要额外收取打包费吗？','nín hǎo， wǒ zì dài fàn hé dǎ bāo fàn cài， hái yào é wài shōu qǔ dǎ bāo fèi ma？','Chào chị, em tự mang hộp cơm để đóng gói cơm canh, vậy có tính thêm phí đóng gói không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_02','V715','工作人员',2,'自带容器不使用食堂一次性餐盒，免收打包费哈。','zì dài róng qì bù shǐ yòng shí táng yí cì xìng cān hé， miǎn shōu dǎ bāo fèi hā。','Tự mang hộp riêng, không dùng hộp dùng một lần của căn tin thì miễn phí đóng gói nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_03','V715','阮明',3,'要是忘记带饭盒，用食堂塑料盒打包多少钱一份？','yào shì wàng jì dài fàn hé， yòng shí táng sù liào hé dǎ bāo duō shǎo qián yī fèn？','Nếu lỡ quên mang hộp cơm, dùng hộp nhựa của căn tin thì bao nhiêu tiền một suất vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_04','V715','工作人员',4,'一次性餐盒一元一个，筷子、塑料袋免费提供。','yí cì xìng cān hé yī yuán yí gè， kuài zi、 sù liào dài miǎn fèi tí gōng。','Hộp dùng một lần một đồng một cái, đũa với túi nilon thì cho miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_05','V715','阮明',5,'我以后每天带饭盒，既省钱也更环保。','wǒ yǐ hòu měi tiān dài fàn hé， jì shěng qián yě gèng huán bǎo。','Vậy từ giờ em mang hộp cơm theo mỗi ngày, vừa tiết kiệm vừa đỡ hại môi trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_06','V715','工作人员',6,'自带餐具打包我们十分鼓励，减少塑料垃圾。','zì dài cān jù dǎ bāo wǒ men shí fēn gǔ lì， jiǎn shǎo sù liào lā jī。','Tự mang hộp đến đóng gói là tụi chị khuyến khích lắm, giảm được rác nhựa mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_07','V715','阮明',7,'好，我每天自备饭盒来食堂打包饭菜。','hǎo， wǒ měi tiān zì bèi fàn hé lái shí táng dǎ bāo fàn cài。','Được rồi, từ nay em tự chuẩn bị hộp cơm mang đến căn tin đóng gói đồ ăn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT716','SSH2','食堂高峰期排队久，和同学交流错峰就餐时段',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V716','SIT716','P1','suon_se','tuy_y',NULL,'国内高校十二点是下课就餐最高峰，提前或延后半小时就餐可大幅缩短排队时长。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_01','V716','阮明',1,'中午十二点食堂人挤人，排队二十分钟才能打到饭啊。','zhōng wǔ shí èr diǎn shí táng rén jǐ rén， pái duì èr shí fēn zhōng cái néng dǎ dào fàn a。','Trưa mười hai giờ căn tin đông nghẹt người, xếp hàng hai chục phút mới lấy được đồ ăn đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_02','V716','苏雯',2,'可以十一点四十提前下课去食堂，几乎不用排队呢。','kě yǐ shí yì diǎn sì shí tí qián xià kè qù shí táng， jī hū bù yòng pái duì ne。','Cậu có thể tan học sớm lúc mười một giờ bốn mươi rồi ra căn tin, hầu như khỏi xếp hàng luôn đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_03','V716','阮明',3,'要是上午有课走不开，下午一点再去是不是人很少？','yào shì shàng wǔ yǒu kè zǒu bù kāi， xià wǔ yì diǎn zài qù shì bú shì rén hěn shǎo？','Nhưng nếu sáng có tiết không đi được, thì một giờ chiều mới ra thì có ít người không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_04','V716','苏雯',4,'一点大部分学生吃完回宿舍，窗口菜品选择也还算多。','yì diǎn dà bù fèn xué shēng chī wán huí sù shè， chuāng kǒu cài pǐn xuǎn zé yě hái suàn duō。','Một giờ thì phần lớn sinh viên ăn xong về ký túc xá rồi, mấy quầy đồ ăn cũng còn khá nhiều lựa chọn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_05','V716','阮明',5,'那我分两种时段，早下课就提前去，晚下课一点再就餐。','nà wǒ fēn liǎng zhǒng shí duàn， zǎo xià kè jiù tí qián qù， wǎn xià kè yì diǎn zài jiù cān。','Vậy thì mình chia hai khung giờ, hôm nào tan sớm thì đi trước, tan muộn thì một giờ mới ăn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_06','V716','苏雯',6,'避开十二点整的高峰，能节省很多排队等待时间。','bì kāi shí èr diǎn zhěng de gāo fēng， néng jié shěng hěn duō pái duì děng dài shí jiān。','Tránh đúng giờ cao điểm mười hai giờ là đỡ mất thời gian xếp hàng chờ lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_07','V716','阮明',7,'我之后错开高峰，不用长时间排队等餐。','wǒ zhī hòu cuò kāi gāo fēng， bù yòng zhǎng shí jiān pái duì děng cān。','Sau này mình tránh giờ cao điểm ra, khỏi phải xếp hàng chờ ăn lâu nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT717','SSH2','咨询食堂清真窗口开放时间、菜品范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V717','SIT717','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有独立清真餐窗口，厨具、食材完全隔离，满足有饮食禁忌的学生就餐需求。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_01','V717','阮明',1,'您好，想咨询食堂清真窗口每日开放时段有哪些？','nín hǎo， xiǎng zī xún shí táng qīng zhēn chuāng kǒu měi rì kāi fàng shí duàn yǒu nǎ xiē？','Chào anh/chị, em muốn hỏi quầy đồ Hồi ở căn tin mở cửa vào những khung giờ nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_02','V717','工作人员',2,'早七点至八点半早餐，十一点到十三点午餐，十七点半至十九点晚餐哦。','zǎo qī diǎn zhì bā diǎn bàn zǎo cān， shí yì diǎn dào shí sān diǎn wǔ cān， shí qī diǎn bàn zhì shí jiǔ diǎn wǎn cān ó。','Bảy giờ đến tám rưỡi sáng là bữa sáng, mười một giờ đến mười ba giờ là bữa trưa, mười bảy rưỡi đến mười chín giờ là bữa tối nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_03','V717','阮明',3,'清真窗口只供应牛羊肉、素食，完全不出现猪肉菜品对吧？','qīng zhēn chuāng kǒu zhǐ gōng yìng niú yáng ròu、 sù shí， wán quán bù chū xiàn zhū ròu cài pǐn duì ba？','Quầy đồ Hồi chỉ phục vụ thịt bò, thịt cừu và đồ chay, hoàn toàn không có món thịt heo đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_04','V717','工作人员',4,'没错，厨具、操作台独立分开，杜绝混炒普通菜品。','méi cuò， chú jù、 cāo zuò tái dú lì fēn kāi， dù jué hùn chǎo pǔ tōng cài pǐn。','Đúng vậy, dụng cụ nấu nướng và bàn chế biến được tách riêng hẳn, không xào chung với món thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_05','V717','阮明',5,'明天早上我早点过来，去清真窗口吃早餐。','míng tiān zǎo shàng wǒ zǎo diǎn guò lái， qù qīng zhēn chuāng kǒu chī zǎo cān。','Vậy mai sáng em sẽ đến sớm hơn, ra quầy đồ Hồi ăn sáng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_06','V717','工作人员',6,'窗口每日定时供应，太晚抵达会菜品售罄。','chuāng kǒu měi rì dìng shí gōng yìng， tài wǎn dǐ dá huì cài pǐn shòu qìng。','Quầy phục vụ theo giờ cố định mỗi ngày, đến trễ quá là hết món đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_07','V717','阮明',7,'我把控好时间，在窗口开放时段内就餐。','wǒ bǎ kòng hǎo shí jiān， zài chuāng kǒu kāi fàng shí duàn nèi jiù cān。','Em sẽ canh giờ cho chuẩn, ăn trong khung giờ quầy còn mở cửa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT718','SSH2','餐后忘记归还食堂餐盘，被工作人员提醒规范就餐',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V718','SIT718','P1','that_bai_nhe','tuy_y',NULL,'校园食堂餐盘、汤碗属于公共耗材，禁止带出就餐区域，餐后统一送至店内回收处是通用就餐规范。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_01','V718','阮明',1,'阿姨不好意思，吃完饭后我把餐盘直接带出食堂了，现在送回来。','ā yí bù hǎo yì sī， chī wán fàn hòu wǒ bǎ cān pán zhí jiē dài chū shí táng le， xiàn zài sòng huí lái。','Cô ơi con xin lỗi, ăn xong con lỡ mang khay đi luôn ra khỏi căn tin, giờ con mang trả lại đây ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_02','V718','保洁李阿姨',2,'食堂规定餐盘必须在店内回收台归还，不能带出就餐区嘛。','shí táng guī dìng cān pán bì xū zài diàn nèi huí shōu tái guī huán， bù néng dài chū jiù cān qū ma。','Quy định của căn tin là khay phải trả lại đúng chỗ thu gom trong này, không được mang ra khỏi khu ăn uống đâu nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_03','V718','阮明',3,'刚才着急赶课，一时忘记食堂就餐规定，下次一定注意。','gāng cái zháo jí gǎn kè， yī shí wàng jì shí táng jiù cān guī dìng， xià cì yí dìng zhù yì。','Lúc nãy con vội đi học nên quên mất quy định, lần sau con nhớ kỹ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_04','V718','保洁李阿姨',4,'餐盘餐具外流容易丢失、破损，增加食堂耗材成本。','cān pán cān jù wài liú róng yì diū shī、 pò sǔn， zēng jiā shí táng hào cái chéng běn。','Khay với dụng cụ ăn bị mang ra ngoài dễ thất lạc, hư hỏng lắm, làm tăng chi phí đồ dùng của căn tin đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_05','V718','阮明',5,'我之后吃完立刻送到回收台，绝不带出食堂大门。','wǒ zhī hòu chī wán lì kè sòng dào huí shōu tái， jué bù dài chū shí táng dà mén。','Sau này con ăn xong là mang trả ngay chỗ thu gom liền, tuyệt đối không mang ra khỏi cổng căn tin nữa ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_06','V718','保洁李阿姨',6,'记住规则就好，下次不用再特意送回来。','jì zhù guī zé jiù hǎo， xià cì bù yòng zài tè yì sòng huí lái。','Nhớ quy định vậy là được rồi, lần sau khỏi phải đặc biệt mang trả lại như vầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_07','V718','阮明',7,'十分抱歉给您增加额外工作，我严格遵守食堂规定。','shí fēn bào qiàn gěi nín zēng jiā é wài gōng zuò， wǒ yán gé zūn shǒu shí táng guī dìng。','Con xin lỗi vì làm phiền cô thêm việc, con sẽ tuân thủ đúng quy định của căn tin ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT719','SSH3','图书馆办理借阅证，学习图书借还、逾期罚款规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V719','SIT719','P1','suon_se','ban_chinh_thuc',NULL,'国内高校图书馆图书超期会收取每日罚金，逾期过久会暂停借阅权限，直至缴清罚款。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_01','V719','阮明',1,'老师您好，我是新生留学生，前来办理图书馆借阅证件。','lǎo shī nín hǎo， wǒ shì xīn shēng liú xué shēng， qián lái bàn lǐ tú shū guǎn jiè yuè zhèng jiàn。','Chào thầy/cô, em là sinh viên quốc tế mới nhập học, em đến làm thẻ thư viện ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_02','V719','馆员王老师',2,'出示学生证、护照，登记信息后绑定校园卡就能借书哦。','chū shì xué shēng zhèng、 hù zhào， dēng jì xìn xī hòu bǎng dìng xiào yuán kǎ jiù néng jiè shū ó。','Em xuất trình thẻ sinh viên và hộ chiếu, đăng ký thông tin rồi liên kết với thẻ trường là mượn sách được nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_03','V719','阮明',3,'单次最多能借几本书，最长借阅期限是多少天？','dān cì zuì duō néng jiè jǐ běn shū， zuì zhǎng jiè yuè qī xiàn shì duō shǎo tiān？','Mỗi lần được mượn tối đa bao nhiêu cuốn ạ, và thời hạn mượn lâu nhất là bao nhiêu ngày ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_04','V719','馆员王老师',4,'一次六本，三十天借阅期，可线上续借一次延长十五天。','yī cì liù běn， sān shí tiān jiè yuè qī， kě xiàn shàng xù jiè yī cì yán cháng shí wǔ tiān。','Mỗi lần sáu cuốn, hạn mượn ba mươi ngày, có thể gia hạn trực tuyến một lần thêm mười lăm ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_05','V719','阮明',5,'超过三十天未续借，每天会产生多少逾期罚款呢？','chāo guò sān shí tiān wèi xù jiè， měi tiān huì chǎn shēng duō shǎo yú qī fá kuǎn ne？','Nếu quá ba mươi ngày mà chưa gia hạn thì mỗi ngày bị phạt trễ hạn bao nhiêu tiền vậy ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_06','V719','馆员王老师',6,'每本书每日零点一元罚款，超期越久费用累加越高。','měi běn shū měi rì líng diǎn yī yuán fá kuǎn， chāo qī yuè jiǔ fèi yòng lěi jiā yuè gāo。','Mỗi cuốn sách phạt không phẩy một đồng một ngày, càng trễ lâu thì tiền phạt càng cộng dồn nhiều lên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_07','V719','阮明',7,'我会按时续借或者归还，避免产生逾期罚金。','wǒ huì àn shí xù jiè huò zhě guī huán， bì miǎn chǎn shēng yú qī fá jīn。','Em sẽ gia hạn hoặc trả sách đúng hạn, để tránh phát sinh tiền phạt trễ hạn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT720','SSH3','图书馆自习座位被占，咨询管理员占座管理规定',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V720','SIT720','P1','twist','ban_chinh_thuc',NULL,'图书馆严禁用书、水杯长期霸占自习座位，临时离开超过一小时管理员会清理占位物品，保障座位公平使用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_01','V720','阮明',1,'您好，这个自习座位放着书本一整天没人，我可以坐这里吗？','nín hǎo， zhè ge zì xí zuò wèi fàng zhe shū běn yī zhěng tiān méi rén， wǒ kě yǐ zuò zhè lǐ ma？','Chào anh/chị, chỗ tự học này để sách nguyên cả ngày mà không thấy ai ngồi, em ngồi đây được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_02','V720','管理员',2,'图书馆禁止长期占座，离开超过一小时物品会统一清收。','tú shū guǎn jìn zhǐ cháng qī zhàn zuò， lí kāi chāo guò yī xiǎo shí wù pǐn huì tǒng yī qīng shōu。','Thư viện cấm giữ chỗ lâu dài, rời khỏi quá một tiếng là đồ đạc sẽ bị thu gom hết đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_03','V720','阮明',3,'书本、水杯全都留在桌面，座位空了整整一下午嘛。','shū běn、 shuǐ bēi quán dōu liú zài zhuō miàn， zuò wèi kōng le zhěng zhěng yī xià wǔ ma。','Sách vở, ly nước để nguyên trên bàn, chỗ ngồi trống nguyên cả buổi chiều luôn mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_04','V720','管理员',4,'我先把占位物品收到失物存放区，你可以正常使用这个座位。','wǒ xiān bǎ zhàn wèi wù pǐn shōu dào shī wù cún fàng qū， nǐ kě yǐ zhèng cháng shǐ yòng zhè ge zuò wèi。','Vậy để tôi thu đồ giữ chỗ đưa vào khu lưu giữ đồ thất lạc trước, em cứ sử dụng chỗ này bình thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_05','V720','阮明',5,'那物品主人回来，去哪里领取自己的书本、水杯？','nà wù pǐn zhǔ rén huí lái， qù nǎ lǐ lǐng qǔ zì jǐ de shū běn、 shuǐ bēi？','Vậy chủ nhân đồ đạc quay lại thì đến đâu để nhận lại sách vở, ly nước của họ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_06','V720','管理员',6,'一楼服务台报姓名、物品特征就能取回存放物品。','yī lóu fú wù tái bào xìng míng、 wù pǐn tè zhēng jiù néng qǔ huí cún fàng wù pǐn。','Ra quầy phục vụ ở tầng một, báo tên và đặc điểm đồ vật là lấy lại được thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_07','V720','阮明',7,'我以后临时离开自习室，随身带走全部私人物品。','wǒ yǐ hòu lín shí lí kāi zì xí shì， suí shēn dài zǒu quán bù sī rén wù pǐn。','Sau này em rời phòng tự học một lát cũng sẽ mang theo hết đồ cá nhân của mình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT721','SSH3','图书馆电脑无法登录校园内网，求助值班管理员',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V721','SIT721','P1','suon_se','tuy_y',NULL,'校园内网会定期服务器维护，维护期间图书馆电脑无法访问校内论文数据库，属于常规网络维护安排。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_01','V721','阮明',1,'你好，图书馆台式机输入学号，一直登录不上校园内网啊。','nǐ hǎo， tú shū guǎn tái shì jī shū rù xué hào， yì zhí dēng lù bù shàng xiào yuán nèi wǎng a。','Chào anh/chị, máy tính bàn ở thư viện em nhập mã số sinh viên vào mà cứ không đăng nhập được mạng nội bộ trường luôn á.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_02','V721','管理员',2,'是不是校园网账号欠费停机，或者密码输入错误呢？','shì bú shì xiào yuán wǎng zhàng hào qiàn fèi tíng jī， huò zhě mì mǎ shū rù cuò wù ne？','Có phải tài khoản mạng trường bị khóa do chưa đóng phí, hay là em gõ sai mật khẩu không?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_03','V721','阮明',3,'昨天还正常登录查阅文献，没有修改过账号密码。','zuó tiān hái zhèng cháng dēng lù chá yuè wén xiàn， méi yǒu xiū gǎi guò zhàng hào mì mǎ。','Hôm qua em vẫn đăng nhập tra tài liệu bình thường mà, cũng không có đổi mật khẩu tài khoản gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_04','V721','管理员',4,'今天校内服务器临时维护，部分电脑网络不稳定。','jīn tiān xiào nèi fú wù qì lín shí wéi hù， bù fèn diàn nǎo wǎng luò bù wěn dìng。','Hôm nay máy chủ trong trường đang bảo trì tạm thời, nên một số máy mạng không ổn định đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_05','V721','阮明',5,'那大概多久恢复内网访问，我需要查阅专业论文。','nà dà gài duō jiǔ huī fù nèi wǎng fǎng wèn， wǒ xū yào chá yuè zhuān yè lùn wén。','Vậy khoảng bao lâu thì truy cập lại được mạng nội bộ ạ, em đang cần tra luận văn chuyên ngành gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_06','V721','管理员',6,'预计四十分钟维护结束，你可以先用手机流量临时查资料。','yù jì sì shí fēn zhōng wéi hù jié shù， nǐ kě yǐ xiān yòng shǒu jī liú liàng lín shí chá zī liào。','Dự kiến khoảng bốn mươi phút nữa là bảo trì xong, em có thể tạm dùng dữ liệu di động để tra trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_07','V721','阮明',7,'我先等服务器维护完成，再使用电脑下载文献。','wǒ xiān děng fú wù qì wéi hù wán chéng， zài shǐ yòng diàn nǎo xià zài wén xiàn。','Vậy em đợi máy chủ bảo trì xong rồi mới dùng máy tính để tải tài liệu vậy.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT722','SSH3','借阅书籍超期，咨询罚款标准、补缴流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V722','SIT722','P1','that_bai_nhe','ban_chinh_thuc',NULL,'图书逾期罚金必须线下结清，未缴清罚款会永久限制图书借阅、数据库使用权限。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_01','V722','阮明',1,'老师，我借阅的两本专业书忘记续借，已经超期八天了。','lǎo shī， wǒ jiè yuè de liǎng běn zhuān yè shū wàng jì xù jiè， yǐ jīng chāo qī bā tiān le。','Thầy/cô ơi, em mượn hai cuốn sách chuyên ngành mà quên gia hạn, giờ trễ hạn tám ngày rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_02','V722','馆员王老师',2,'先把图书归还，系统自动核算每日逾期罚款金额。','xiān bǎ tú shū guī huán， xì tǒng zì dòng hé suàn měi rì yú qī fá kuǎn jīn é。','Em cứ trả sách trước đã, hệ thống sẽ tự tính số tiền phạt trễ hạn theo từng ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_03','V722','阮明',3,'两本书分开计算罚金，还是合并统一收取费用？','liǎng běn shū fēn kāi jì suàn fá jīn， hái shì hé bìng tǒng yī shōu qǔ fèi yòng？','Hai cuốn sách tính tiền phạt riêng hay là gộp chung lại thu một lần vậy ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_04','V722','馆员王老师',4,'每本单独计费，两本书八天一共十六元逾期罚金嘛。','měi běn dān dú jì fèi， liǎng běn shū bā tiān yī gòng shí liù yuán yú qī fá jīn ma。','Mỗi cuốn tính riêng, hai cuốn tám ngày cộng lại là mười sáu đồng tiền phạt đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_05','V722','阮明',5,'罚金只能线下在图书馆服务台扫码缴纳，不能线上支付吗？','fá jīn zhǐ néng xiàn xià zài tú shū guǎn fú wù tái sǎo mǎ jiǎo nà， bù néng xiàn shàng zhī fù ma？','Tiền phạt chỉ có thể quét mã đóng trực tiếp tại quầy thư viện thôi ạ, không thanh toán online được sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_06','V722','馆员王老师',6,'仅支持线下现场缴费，缴清罚金才能恢复借阅权限。','jǐn zhī chí xiàn xià xiàn chǎng jiǎo fèi， jiǎo qīng fá jīn cái néng huī fù jiè yuè quán xiàn。','Chỉ hỗ trợ đóng phạt trực tiếp tại chỗ thôi, đóng xong tiền phạt mới được khôi phục quyền mượn sách.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_07','V722','阮明',7,'我现在扫码缴纳罚金，之后一定记好续借日期。','wǒ xiàn zài sǎo mǎ jiǎo nà fá jīn， zhī hòu yí dìng jì hǎo xù jiè rì qī。','Vậy giờ em quét mã đóng tiền phạt luôn, sau này em sẽ nhớ kỹ ngày gia hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT723','SSH3','图书馆打印复印设备卡纸，找工作人员维修',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V723','SIT723','P1','suon_se','tuy_y',NULL,'自助打印设备卡纸禁止用户自行拆机拉扯纸张，容易造成硬件损坏，需工作人员专业处理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_01','V723','阮明',1,'你好，自助复印机打印到一半卡纸，纸张卡在机器里面了。','nǐ hǎo， zì zhù fù yìn jī dǎ yìn dào yí bàn kǎ zhǐ， zhǐ zhāng kǎ zài jī qì lǐ miàn le。','Chào anh, máy photo tự phục vụ đang in dở thì kẹt giấy, giấy bị kẹt trong máy rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_02','V723','运维工作人员',2,'别手动拉扯纸张，容易损坏打印机内部齿轮。','bié shǒu dòng lā chě zhǐ zhāng， róng yì sǔn huài dǎ yìn jī nèi bù chǐ lún。','Đừng tự ý kéo giấy ra nhé, dễ làm hỏng bánh răng bên trong máy in lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_03','V723','阮明',3,'我只是按了停止键，没有强行拽取卡住的打印纸。','wǒ zhǐ shì àn le tíng zhǐ jiàn， méi yǒu qiáng xíng zhuāi qǔ kǎ zhù de dǎ yìn zhǐ。','Em chỉ bấm nút dừng thôi, không cố kéo tờ giấy bị kẹt đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_04','V723','运维工作人员',4,'我打开机盖取出卡纸，清理之后就能恢复打印啦。','wǒ dǎ kāi jī gài qǔ chū kǎ zhǐ， qīng lǐ zhī hòu jiù néng huī fù dǎ yìn la。','Để anh mở nắp máy lấy giấy kẹt ra, dọn xong là in lại được ngay thôi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_05','V723','阮明',5,'刚才已经扣取打印费用，卡纸没有完整出纸会返还余额吗？','gāng cái yǐ jīng kòu qǔ dǎ yìn fèi yòng， kǎ zhǐ méi yǒu wán zhěng chū zhǐ huì fǎn huán yú é ma？','Nãy tiền in đã bị trừ rồi, mà giấy kẹt không ra hết thì có được hoàn lại không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_06','V723','运维工作人员',6,'单次卡纸未出纸，系统自动退还本次打印扣费。','dān cì kǎ zhǐ wèi chū zhǐ， xì tǒng zì dòng tuì huán běn cì dǎ yìn kòu fèi。','Một lần kẹt giấy không ra được là hệ thống tự động hoàn lại tiền in lần đó luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_07','V723','阮明',7,'麻烦您检修机器，我等下继续打印复习资料。','má fán nín jiǎn xiū jī qì， wǒ děng xià jì xù dǎ yìn fù xí zī liào。','Phiền anh kiểm tra sửa máy giúp em, lát nữa em in tiếp tài liệu ôn tập.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT724','SSH3','自习到闭馆时间，咨询夜间留校自习申请渠道',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V724','SIT724','P1','twist','ban_chinh_thuc',NULL,'图书馆夜间统一闭馆安保巡查，国内高校单独设置通宵自习教室满足期末备考学生需求。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_01','V724','阮明',1,'距离期末考还有两周，图书馆九点闭馆太早，想夜间留校自习。','jù lí qī mò kǎo hái yǒu liǎng zhōu， tú shū guǎn jiǔ diǎn bì guǎn tài zǎo， xiǎng yè jiān liú xiào zì xí。','Còn hai tuần nữa là thi cuối kỳ rồi, thư viện đóng cửa lúc chín giờ sớm quá, em muốn ở lại trường tự học ban đêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_02','V724','管理员',2,'图书馆晚间九点统一闭馆，不允许学生留在馆内过夜自习。','tú shū guǎn wǎn jiān jiǔ diǎn tǒng yī bì guǎn， bù yǔn xǔ xué shēng liú zài guǎn nèi guò yè zì xí。','Thư viện đóng cửa cố định lúc chín giờ tối, không cho phép sinh viên ở lại trong thư viện qua đêm tự học.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_03','V724','阮明',3,'有没有专门通宵自习教室，或者申请延长图书馆开放时间？','yǒu méi yǒu zhuān mén tōng xiāo zì xí jiào shì， huò zhě shēn qǐng yán cháng tú shū guǎn kāi fàng shí jiān？','Vậy có phòng tự học thông đêm riêng nào không, hay có thể xin gia hạn giờ mở cửa thư viện không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_04','V724','管理员',4,'教学楼有两间通宵自习室，图书馆无延时开放审批通道嘛。','jiào xué lóu yǒu liǎng jiān tōng xiāo zì xí shì， tú shū guǎn wú yán shí kāi fàng shěn pī tōng dào ma。','Ở tòa nhà giảng đường có hai phòng tự học thông đêm, còn thư viện thì không có kênh xin gia hạn giờ mở cửa đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_05','V724','阮明',5,'教学楼通宵教室晚上十一点之后还能正常开灯自习吗？','jiào xué lóu tōng xiāo jiào shì wǎn shàng shí yì diǎn zhī hòu hái néng zhèng cháng kāi dēng zì xí ma？','Phòng tự học thông đêm ở giảng đường sau mười một giờ đêm vẫn bật đèn học bình thường được chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_06','V724','管理员',6,'全天供电，门禁可刷校园卡二十四小时自由进出。','quán tiān gōng diàn， mén jìn kě shuā xiào yuán kǎ èr shí sì xiǎo shí zì yóu jìn chū。','Cấp điện cả ngày, cửa ra vào quẹt thẻ sinh viên là ra vào tự do hai mươi bốn giờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_07','V724','阮明',7,'今晚开始转移到教学楼通宵教室复习备考。','jīn wǎn kāi shǐ zhuǎn yí dào jiào xué lóu tōng xiāo jiào shì fù xí bèi kǎo。','Vậy từ tối nay em chuyển sang phòng tự học thông đêm ở giảng đường để ôn thi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT725','SSH3','借阅外文专业参考书，咨询馆员查找馆藏方法',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V725','SIT725','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆外文藏书单独分区管理，为保护原版书籍，不开放学生自行入内取阅，由馆员统一调取。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_01','V725','阮明',1,'老师，我需要越南语原版专业参考书，不知道怎么检索馆藏。','lǎo shī， wǒ xū yào yuè nán yǔ yuán bǎn zhuān yè cān kǎo shū， bù zhī dào zěn me jiǎn suǒ guǎn cáng。','Thưa cô, em cần tìm sách tham khảo chuyên ngành bản gốc tiếng Việt, mà không biết tra cứu tài liệu thư viện thế nào ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_02','V725','馆员王老师',2,'图书馆检索系统左上角切换外文分类，输入语种关键词即可。','tú shū guǎn jiǎn suǒ xì tǒng zuǒ shàng jiǎo qiè huàn wài wén fēn lèi， shū rù yǔ zhǒng guān jiàn cí jí kě。','Ở góc trên bên trái hệ thống tra cứu của thư viện có mục chuyển sang phân loại sách ngoại văn, chỉ cần nhập từ khóa ngôn ngữ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_03','V725','阮明',3,'检索出来显示在三楼外文馆藏区，需要凭借阅证入内取书对吧？','jiǎn suǒ chū lái xiǎn shì zài sān lóu wài wén guǎn cáng qū， xū yào píng jiè yuè zhèng rù nèi qǔ shū duì ba？','Tra ra thì thấy hiển thị ở khu sách ngoại văn tầng ba, chắc phải có thẻ mượn sách mới vào lấy được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_04','V725','馆员王老师',4,'外文图书区域不对外开放自由取书，报书名由我调取。','wài wén tú shū qū yù bú duì wài kāi fàng zì yóu qǔ shū， bào shū míng yóu wǒ diào qǔ。','Khu sách ngoại văn không mở cho tự do vào lấy sách đâu, em báo tên sách để cô lấy giúp cho.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_05','V725','阮明',5,'那我把书籍编号发给您，麻烦帮忙调取这本参考书。','nà wǒ bǎ shū jí biān hào fā gěi nín， má fán bāng máng diào qǔ zhè běn cān kǎo shū。','Vậy em gửi cô mã số sách nhé, phiền cô giúp em lấy cuốn tham khảo này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_06','V725','馆员王老师',6,'十分钟内找到书籍，你在服务台等候领取。','shí fēn zhōng nèi zhǎo dào shū jí， nǐ zài fú wù tái děng hòu lǐng qǔ。','Trong mười phút là tìm được sách, em ra bàn phục vụ đợi nhận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_07','V725','阮明',7,'好，我在这里等候，感谢协助查找外文藏书。','hǎo， wǒ zài zhè lǐ děng hòu， gǎn xiè xié zhù chá zhǎo wài wén cáng shū。','Dạ, em đợi ở đây, cảm ơn cô đã giúp tìm sách ngoại văn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT726','SSH4','办理校园统一公交优惠学生卡，提交证件材料',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V726','SIT726','P1','suon_se','ban_chinh_thuc',NULL,'国内在校学生可办理公交学生卡，市内通勤公交享受半价优惠，长途客运不参与学生折扣政策。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_01','V726','阮明',1,'老师您好，想办理公交学生优惠卡，出门乘坐公交半价乘车。','lǎo shī nín hǎo， xiǎng bàn lǐ gōng jiāo xué shēng yōu huì kǎ， chū mén chéng zuò gōng jiāo bàn jià chéng chē。','Chào thầy, em muốn làm thẻ ưu đãi xe buýt cho sinh viên, để đi xe buýt được giảm nửa giá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_02','V726','办事老师',2,'准备好护照、学生证、一寸证件照，填写办卡申请表哦。','zhǔn bèi hǎo hù zhào、 xué shēng zhèng、 yī cùn zhèng jiàn zhào， tián xiě bàn kǎ shēn qǐng biǎo ó。','Em chuẩn bị hộ chiếu, thẻ sinh viên, ảnh thẻ một inch, rồi điền vào đơn đăng ký làm thẻ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_03','V726','阮明',3,'办好公交卡，全市所有公交线路都能享受学生折扣吗？','bàn hǎo gōng jiāo kǎ， quán shì suǒ yǒu gōng jiāo xiàn lù dōu néng xiǎng shòu xué shēng zhé kòu ma？','Làm thẻ xe buýt xong thì tất cả các tuyến xe buýt trong thành phố đều được hưởng ưu đãi sinh viên phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_04','V726','办事老师',4,'市内常规公交全部半价，长途城际公交不适用优惠。','shì nèi cháng guī gōng jiāo quán bù bàn jià， cháng tú chéng jì gōng jiāo bù shì yòng yōu huì。','Xe buýt thường trong nội thành thì đều giảm nửa giá, còn xe buýt liên tỉnh đường dài thì không áp dụng ưu đãi nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_05','V726','阮明',5,'公交卡丢失可以挂失转移余额，和校园饭卡规则一样？','gōng jiāo kǎ diū shī kě yǐ guà shī zhuǎn yí yú é， hé xiào yuán fàn kǎ guī zé yī yàng？','Thẻ xe buýt bị mất thì có thể báo mất và chuyển số dư sang, giống quy định thẻ ăn của trường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_06','V726','办事老师',6,'没错，携带证件到服务中心挂失补办，余额完整保留。','méi cuò， xié dài zhèng jiàn dào fú wù zhōng xīn guà shī bǔ bàn， yú é wán zhěng bǎo liú。','Đúng vậy, mang giấy tờ đến trung tâm dịch vụ báo mất làm lại là được, số dư vẫn giữ nguyên đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_07','V726','阮明',7,'我备齐材料，今天办理学生公交优惠卡。','wǒ bèi qí cái liào， jīn tiān bàn lǐ xué shēng gōng jiāo yōu huì kǎ。','Em chuẩn bị đủ giấy tờ rồi, hôm nay em làm thẻ ưu đãi xe buýt sinh viên luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT727','SSH4','共享单车扫码失败、车辆故障，咨询换车流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V727','SIT727','P1','twist','tuy_y',NULL,'共享单车故障车辆免费换车，短时间内切换新车不重复收取起步费用，是平台通用售后规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_01','V727','阮明',1,'师傅，这辆单车扫码开锁一直失败，页面提示车辆故障啊。','shī fù， zhè liàng dān chē sǎo mǎ kāi suǒ yì zhí shī bài， yè miàn tí shì chē liàng gù zhàng a。','Anh ơi, cái xe đạp này quét mã mở khóa mãi không được, trên màn hình báo xe bị hỏng đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_02','V727','运维员',2,'故障车辆后台锁定无法解锁，直接在APP点更换车辆按钮。','gù zhàng chē liàng hòu tái suǒ dìng wú fǎ jiě suǒ， zhí jiē zài APP diǎn gēng huàn chē liàng àn niǔ。','Xe hỏng thì hệ thống đã khóa lại không mở được nữa đâu, em bấm nút đổi xe khác ngay trên app ấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_03','V727','阮明',3,'换车会不会重复收取骑行起步费，两辆车分开计费吗？','huàn chē huì bú huì chóng fù shōu qǔ qí xíng qǐ bù fèi， liǎng liàng chē fēn kāi jì fèi ma？','Đổi xe thì có bị tính phí mở chuyến hai lần không, hai xe có tính tiền riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_04','V727','运维员',4,'故障换车十分钟内切换新车，不会二次扣费，自动取消订单嘛。','gù zhàng huàn chē shí fēn zhōng nèi qiè huàn xīn chē， bú huì èr cì kòu fèi， zì dòng qǔ xiāo dìng dān ma。','Đổi xe do hỏng trong vòng mười phút thì chuyển sang xe mới, không bị trừ tiền lần hai đâu, đơn cũ tự động hủy luôn mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_05','V727','阮明',5,'那我直接换旁边完好单车，不用手动结束当前订单？','nà wǒ zhí jiē huàn páng biān wán hǎo dān chē， bù yòng shǒu dòng jié shù dāng qián dìng dān？','Vậy em cứ đổi luôn sang chiếc xe còn nguyên bên cạnh, không cần tự kết thúc đơn hiện tại nữa hả anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_06','V727','运维员',6,'APP一键换车系统自动处理，不用额外操作订单。','APP yī jiàn huàn chē xì tǒng zì dòng chǔ lǐ， bù yòng é wài cāo zuò dìng dān。','App có nút đổi xe một chạm, hệ thống tự xử lý hết, không cần thao tác gì thêm với đơn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_07','V727','阮明',7,'我现在操作更换车辆，正常骑行前往教学楼。','wǒ xiàn zài cāo zuò gēng huàn chē liàng， zhèng cháng qí xíng qián wǎng jiào xué lóu。','Vậy giờ em đổi xe luôn nhé, rồi đạp bình thường đến giảng đường.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT728','SSH4','校内电动车限速规定，被安保提醒减速慢行',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V728','SIT728','P1','that_bai_nhe','tuy_y',NULL,'国内大学校园非机动车统一低速限速，保护步行学生安全，多次超速会暂扣车辆进行安全教育。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_01','V728','阮明',1,'保安大叔，怎么拦下我，是电动车行驶有违规地方吗？','bǎo ān dà shū， zěn me lán xià wǒ， shì diàn dòng chē háng shǐ yǒu wéi guī dì fāng ma？','Chú bảo vệ ơi, sao chú chặn cháu lại vậy, xe điện của cháu chạy có gì sai quy định ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_02','V728','安保大叔',2,'校内道路限速十五公里每小时，你车速过快存在安全隐患。','xiào nèi dào lù xiàn sù shí wǔ gōng lǐ měi xiǎo shí， nǐ chē sù guò kuài cún zài ān quán yǐn huàn。','Đường trong trường giới hạn tốc độ mười lăm ki-lô-mét một giờ, cháu chạy quá tốc độ là có nguy cơ mất an toàn đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_03','V728','阮明',3,'我赶去上课没留意限速标识，没有注意控制骑行速度嘛。','wǒ gǎn qù shàng kè méi liú yì xiàn sù biāo shí， méi yǒu zhù yì kòng zhì qí xíng sù dù ma。','Cháu vội đi học nên không để ý biển giới hạn tốc độ, không chú ý kiểm soát tốc độ chạy xe thôi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_04','V728','安保大叔',4,'校园行人多，电动车超速容易撞到散步、赶路的学生。','xiào yuán xíng rén duō， diàn dòng chē chāo sù róng yì zhuàng dào sàn bù、 gǎn lù de xué shēng。','Trong trường người đi bộ đông, xe điện chạy quá tốc độ rất dễ đâm phải học sinh đang đi dạo hay đang vội đi đâu đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_05','V728','阮明',5,'第一次超速提醒，会不会扣除校园通行积分或者罚款？','dì yī cì chāo sù tí xǐng， huì bú huì kòu chú xiào yuán tōng xíng jī fēn huò zhě fá kuǎn？','Lần đầu bị nhắc chạy quá tốc độ thì có bị trừ điểm ra vào trường hay bị phạt tiền không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_06','V728','安保大叔',6,'首次口头警告，多次超速会暂扣电动车半天教育。','shǒu cì kǒu tóu jǐng gào， duō cì chāo sù huì zàn kòu diàn dòng chē bàn tiān jiào yù。','Lần đầu chỉ nhắc nhở bằng lời thôi, chạy quá tốc độ nhiều lần thì sẽ bị tạm giữ xe điện nửa ngày để giáo dục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_07','V728','阮明',7,'之后在校内骑行放慢车速，严格遵守限速规定。','zhī hòu zài xiào nèi qí xíng fàng màn chē sù， yán gé zūn shǒu xiàn sù guī dìng。','Từ giờ cháu sẽ chạy chậm lại khi đi trong trường, tuân thủ nghiêm quy định giới hạn tốc độ ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT729','SSH4','快递驿站取件忘记取件码，凭护照核对身份取件',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V729','SIT729','P1','suon_se','tuy_y',NULL,'快递驿站可凭实名有效证件核对身份取件，不止局限于短信取件码，方便遗失短信的顾客。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_01','V729','阮明',1,'你好，我网购的快递到驿站，但是手机弄丢取件短信码了。','nǐ hǎo， wǒ wǎng gòu de kuài dì dào yì zhàn， dàn shì shǒu jī nòng diū qǔ jiàn duǎn xìn mǎ le。','Chào chị, em có đơn hàng online gửi về điểm nhận hàng, nhưng em lỡ mất tin nhắn mã lấy hàng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_02','V729','驿站店员',2,'报你的收件姓名、手机号，出示有效证件就能核对包裹。','bào nǐ de shōu jiàn xìng míng、 shǒu jī hào， chū shì yǒu xiào zhèng jiàn jiù néng hé duì bāo guǒ。','Em đọc tên người nhận, số điện thoại, rồi xuất trình giấy tờ hợp lệ là chị kiểm tra được kiện hàng ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_03','V729','阮明',3,'我出示留学生护照，上面有我的姓名拼音可以核对身份吗？','wǒ chū shì liú xué shēng hù zhào， shàng miàn yǒu wǒ de xìng míng pīn yīn kě yǐ hé duì shēn fèn ma？','Em xuất trình hộ chiếu du học sinh, trên đó có tên phiên âm của em, vậy có đối chiếu được danh tính không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_04','V729','驿站店员',4,'可以，姓名、手机号匹配无误就能直接找出快递包裹。','kě yǐ， xìng míng、 shǒu jī hào pǐ pèi wú wù jiù néng zhí jiē zhǎo chū kuài dì bāo guǒ。','Được chứ, tên và số điện thoại khớp là chị tìm ra kiện hàng cho em liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_05','V729','阮明',5,'麻烦帮我查找今天送达的小件包裹，是学习文具。','má fán bāng wǒ chá zhǎo jīn tiān sòng dá de xiǎo jiàn bāo guǒ， shì xué xí wén jù。','Phiền chị tìm giúp em kiện hàng nhỏ gửi đến hôm nay, là đồ dùng học tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_06','V729','驿站店员',6,'查到了，这个快递，你核对包裹面单信息再拿走。','chá dào le， zhè ge kuài dì， nǐ hé duì bāo guǒ miàn dān xìn xī zài ná zǒu。','Tìm ra rồi nè, đây là kiện hàng của em, em kiểm tra lại thông tin trên phiếu gửi rồi lấy nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_07','V729','阮明',7,'信息全部匹配，感谢不用取件码也能取件。','xìn xī quán bù pǐ pèi， gǎn xiè bù yòng qǔ jiàn mǎ yě néng qǔ jiàn。','Thông tin khớp hết rồi ạ, cảm ơn chị dù không có mã lấy hàng vẫn nhận được ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT730','SSH4','大件快递无法上楼，和驿站协商送货上门服务',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V730','SIT730','P1','twist','ban_chinh_thuc',NULL,'校园快递驿站以自取为主，大件重物单独上门配送会收取少量配送服务费，用于补贴人工运力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_01','V730','阮明',1,'我这个纸箱是被褥大件，楼梯没有电梯，自己搬不动上楼。','wǒ zhè ge zhǐ xiāng shì bèi rù dà jiàn， lóu tī méi yǒu diàn tī， zì jǐ bān bù dòng shàng lóu。','Cái thùng các-tông này của em là chăn đệm cỡ lớn, cầu thang không có thang máy, em tự bê lên không nổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_02','V730','驿站店员',2,'校园驿站规定小件自取，大件上门需要额外支付配送服务费。','xiào yuán yì zhàn guī dìng xiǎo jiàn zì qǔ， dà jiàn shàng mén xū yào é wài zhī fù pèi sòng fú wù fèi。','Điểm nhận hàng trong trường quy định hàng nhỏ tự lấy, còn hàng lớn giao tận nơi thì phải trả thêm phí giao hàng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_03','V730','阮明',3,'宿舍就在校内宿舍楼，距离驿站步行三分钟也要额外收费嘛？','sù shè jiù zài xiào nèi sù shè lóu， jù lí yì zhàn bù xíng sān fēn zhōng yě yào é wài shōu fèi ma？','Ký túc xá em ở ngay trong khuôn viên trường, cách điểm nhận hàng đi bộ có ba phút mà cũng phải trả thêm phí ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_04','V730','驿站店员',4,'配送人员批量派送楼栋，单独上门单件加收三元配送费嘛。','pèi sòng rén yuán pī liàng pài sòng lóu dòng， dān dú shàng mén dān jiàn jiā shōu sān yuán pèi sòng fèi ma。','Nhân viên giao hàng giao theo từng tòa nhà theo lô, còn giao riêng từng đơn thì tính thêm ba đồng phí giao hàng đấy ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_05','V730','阮明',5,'那我今天下午有空，能不能傍晚统一顺路送货上门？','nà wǒ jīn tiān xià wǔ yǒu kòng， néng bù néng bàng wǎn tǒng yī shùn lù sòng huò shàng mén？','Vậy chiều nay em rảnh, không biết chiều tối có thể giao tận nơi luôn một thể được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_06','V730','驿站店员',6,'傍晚六点批量配送，你留好宿舍房间号等候送货。','bàng wǎn liù diǎn pī liàng pèi sòng， nǐ liú hǎo sù shè fáng jiān hào děng hòu sòng huò。','Sáu giờ chiều giao hàng theo lô, em để sẵn số phòng ký túc xá rồi chờ nhận hàng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_07','V730','阮明',7,'我同意支付配送费，傍晚等工作人员送被褥上楼。','wǒ tóng yì zhī fù pèi sòng fèi， bàng wǎn děng gōng zuò rén yuán sòng bèi rù shàng lóu。','Em đồng ý trả phí giao hàng, chiều tối em chờ nhân viên mang chăn đệm lên phòng giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT731','SSH4','咨询校园医务室就诊流程、医保报销范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V731','SIT731','P1','suon_se','ban_chinh_thuc',NULL,'国内高校统一购买大学生医保，校内医务室基础诊疗、常用药品可按比例报销，大幅降低就医开支。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_01','V731','阮明',1,'护士您好，轻微咳嗽不舒服，想咨询医务室就诊流程。','hù shì nín hǎo， qīng wēi ké sòu bù shū fú， xiǎng zī xún yī wù shì jiù zhěn liú chéng。','Chào y tá, em bị ho nhẹ hơi khó chịu, muốn hỏi về quy trình khám ở phòng y tế ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_02','V731','护士',2,'携带校园医保凭证、学生证，一楼分诊台登记排队就诊哦。','xié dài xiào yuán yī bǎo píng zhèng、 xué shēng zhèng， yī lóu fēn zhěn tái dēng jì pái duì jiù zhěn ó。','Em mang theo thẻ bảo hiểm y tế trường và thẻ sinh viên, xuống quầy phân loại ở tầng một đăng ký rồi xếp hàng khám nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_03','V731','阮明',3,'校内医务室拿药可以直接医保报销，不用全额自费吗？','xiào nèi yī wù shì ná yào kě yǐ zhí jiē yī bǎo bào xiāo， bù yòng quán é zì fèi ma？','Lấy thuốc ở phòng y tế trong trường có thể dùng bảo hiểm thanh toán luôn không, hay phải tự trả hết ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_04','V731','护士',4,'基础感冒、消炎药品报销七成，美容、滋补类药品不参与报销。','jī chǔ gǎn mào、 xiāo yán yào pǐn bào xiāo qī chéng， měi róng、 zī bǔ lèi yào pǐn bù cān yù bào xiāo。','Thuốc cảm cơ bản, thuốc kháng viêm được bảo hiểm chi trả bảy mươi phần trăm, còn thuốc làm đẹp hay bồi bổ thì không nằm trong diện được hỗ trợ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_05','V731','阮明',5,'就诊之后如果需要输液，也是同样报销比例对吗？','jiù zhěn zhī hòu rú guǒ xū yào shū yè， yě shì tóng yàng bào xiāo bǐ lì duì ma？','Sau khi khám nếu cần truyền dịch thì tỷ lệ thanh toán bảo hiểm cũng như vậy đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_06','V731','护士',6,'普通诊疗、输液均纳入医保报销，仅自费耗材除外。','pǔ tōng zhěn liáo、 shū yè jūn nà rù yī bǎo bào xiāo， jǐn zì fèi hào cái chú wài。','Khám thông thường hay truyền dịch đều được tính vào bảo hiểm, chỉ có vật tư tự chọn thêm là phải tự trả thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_07','V731','阮明',7,'我带好证件，现在登记排队问诊拿药。','wǒ dài hǎo zhèng jiàn， xiàn zài dēng jì pái duì wèn zhěn ná yào。','Em mang đủ giấy tờ rồi, giờ em đi đăng ký xếp hàng khám và lấy thuốc.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT732','SSH5','宿舍线上缴纳水电费，系统缴费失败咨询后勤',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V732','SIT732','P1','twist','ban_chinh_thuc',NULL,'校园线上缴费系统夜间服务器负载高容易卡顿，水电欠费设有三天缓冲期，不会立刻断供。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_01','V732','阮明',1,'您好，线上小程序缴纳宿舍电费，提交支付一直提示缴费失败。','nín hǎo， xiàn shàng xiǎo chéng xù jiǎo nà sù shè diàn fèi， tí jiāo zhī fù yì zhí tí shì jiǎo fèi shī bài。','Chào chị, em nộp tiền điện ký túc xá qua ứng dụng nhưng cứ nộp là báo lỗi thanh toán ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_02','V732','后勤客服',2,'核对宿舍房间编号，近期是否输入错误楼栋号导致匹配失败？','hé duì sù shè fáng jiān biān hào， jìn qī shì fǒu shū rù cuò wù lóu dòng hào dǎo zhì pǐ pèi shī bài？','Em kiểm tra lại số phòng ký túc xá xem, gần đây có nhập nhầm số tòa nhà nên không khớp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_03','V732','阮明',3,'楼栋、房间号全部核对无误，银行卡扣款短信也没有收到嘛。','lóu dòng、 fáng jiān hào quán bù hé duì wú wù， yín háng kǎ kòu kuǎn duǎn xìn yě méi yǒu shōu dào ma。','Em kiểm tra kỹ cả tòa nhà lẫn số phòng rồi, đều đúng hết, mà tin nhắn trừ tiền từ thẻ ngân hàng cũng chẳng thấy gửi về gì cả.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_04','V732','后勤客服',4,'小程序晚间服务器拥堵，夜间零点至早八点系统不稳定。','xiǎo chéng xù wǎn jiān fú wù qì yōng dǔ， yè jiān líng diǎn zhì zǎo bā diǎn xì tǒng bù wěn dìng。','Buổi tối server của ứng dụng hay bị nghẽn, từ nửa đêm đến tám giờ sáng hệ thống không ổn định lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_05','V732','阮明',5,'那我明天上午再重新提交缴费，不会产生停水断电吧？','nà wǒ míng tiān shàng wǔ zài chóng xīn tí jiāo jiǎo fèi， bú huì chǎn shēng tíng shuǐ duàn diàn ba？','Vậy sáng mai em nộp lại, chắc không bị cắt nước cắt điện chứ ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_06','V732','后勤客服',6,'宿舍水电欠费缓冲三天，三天内缴费不会切断供应。','sù shè shuǐ diàn qiàn fèi huǎn chōng sān tiān， sān tiān nèi jiǎo fèi bú huì qiē duàn gōng yìng。','Ký túc xá có thời gian gia hạn ba ngày cho tiền điện nước còn thiếu, trong ba ngày đó nộp thì không bị cắt đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_07','V732','阮明',7,'明天一早完成缴费，避免宿舍水电临时关停。','míng tiān yī zǎo wán chéng jiǎo fèi， bì miǎn sù shè shuǐ diàn lín shí guān tíng。','Sáng mai em nộp tiền ngay, để tránh bị cắt điện nước bất ngờ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT733','SSH5','校园校园网账号欠费断网，线上续费恢复网络',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V733','SIT733','P1','suon_se','tuy_y',NULL,'校园内网按月计费，欠费立刻断网，校内图书馆、论文数据库均依托校园网访问。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_01','V733','阮明',1,'电脑显示校园网欠费停机，网页视频、学习软件全都打不开。','diàn nǎo xiǎn shì xiào yuán wǎng qiàn fèi tíng jī， wǎng yè shì pín、 xué xí ruǎn jiàn quán dōu dǎ bù kāi。','Máy tính báo mạng trường bị nợ cước nên ngắt kết nối rồi, xem video hay mở phần mềm học tập gì cũng không được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_02','V733','小林',2,'打开校园网小程序，输入学号就能线上充值续费啦。','dǎ kāi xiào yuán wǎng xiǎo chéng xù， shū rù xué hào jiù néng xiàn shàng chōng zhí xù fèi la。','Mở app mạng trường lên, nhập mã số sinh viên vào là nạp tiền gia hạn online được ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_03','V733','阮明',3,'包月套餐三十元，充值之后是立刻恢复网络吗？','bāo yuè tào cān sān shí yuán， chōng zhí zhī hòu shì lì kè huī fù wǎng luò ma？','Gói cước tháng ba mươi nghìn, nạp xong là mạng có lại liền luôn hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_04','V733','小林',4,'充值成功十秒内自动联网，不用重启电脑路由器。','chōng zhí chéng gōng shí miǎo nèi zì dòng lián wǎng， bù yòng chóng qǐ diàn nǎo lù yóu qì。','Nạp thành công là mười giây sau tự động có mạng, không cần khởi động lại máy tính hay router đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_05','V733','阮明',5,'要是忘记续费，断网之后校内论文数据库也没法访问？','yào shì wàng jì xù fèi， duàn wǎng zhī hòu xiào nèi lùn wén shù jù kù yě méi fǎ fǎng wèn？','Lỡ quên gia hạn, mất mạng rồi thì có vào được thư viện luận văn nội bộ trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_06','V733','小林',6,'没错，内网文献库依赖校园网，断网完全无法登录查阅。','méi cuò， nèi wǎng wén xiàn kù yī lài xiào yuán wǎng， duàn wǎng wán quán wú fǎ dēng lù chá yuè。','Đúng vậy, thư viện tài liệu nội bộ phụ thuộc vào mạng trường, mất mạng là không đăng nhập tra cứu được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_07','V733','阮明',7,'我现在线上充值续费，恢复网络继续写作业。','wǒ xiàn zài xiàn shàng chōng zhí xù fèi， huī fù wǎng luò jì xù xiě zuò yè。','Giờ tớ nạp tiền gia hạn liền, có mạng rồi làm bài tập tiếp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT734','SSH5','手机话费余额不足停机，便利店线下充值缴费',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V734','SIT734','P1','suon_se','tuy_y',NULL,'国内线下便利店可办理手机话费充值，适合线上支付故障、手机停机无法收验证码的情况。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_01','V734','阮明',1,'你好，手机停机没法收短信，能不能线下充值话费？','nǐ hǎo， shǒu jī tíng jī méi fǎ shōu duǎn xìn， néng bù néng xiàn xià chōng zhí huà fèi？','Chào chị, điện thoại em bị khóa máy không nhận được tin nhắn, giờ nạp tiền trực tiếp ở đây được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_02','V734','便利店店员',2,'支持五十、一百面额线下充值，输入手机号就能充值哈。','zhī chí wǔ shí、 yì bǎi miàn é xiàn xià chōng zhí， shū rù shǒu jī hào jiù néng chōng zhí hā。','Có mệnh giá năm mươi với một trăm nạp trực tiếp nè, cứ nhập số điện thoại vào là nạp được hà.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_03','V734','阮明',3,'充值成功之后，多久手机能恢复通话、短信功能？','chōng zhí chéng gōng zhī hòu， duō jiǔ shǒu jī néng huī fù tōng huà、 duǎn xìn gōng néng？','Nạp xong thì bao lâu máy mới gọi được, nhắn tin được lại vậy chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_04','V734','便利店店员',4,'充值到账两分钟内自动复机，不用重启手机。','chōng zhí dào zhàng liǎng fēn zhōng nèi zì dòng fù jī， bù yòng chóng qǐ shǒu jī。','Tiền nạp vào là trong hai phút tự động mở lại máy, khỏi cần khởi động lại điện thoại đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_05','V734','阮明',5,'那充值一百元，报我的手机号码给你。','nà chōng zhí yì bǎi yuán， bào wǒ de shǒu jī hào mǎ gěi nǐ。','Vậy chị nạp cho em một trăm nghìn nha, em đọc số điện thoại cho chị đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_06','V734','便利店店员',6,'充值完成，手机很快就能恢复正常通讯。','chōng zhí wán chéng， shǒu jī hěn kuài jiù néng huī fù zhèng cháng tōng xùn。','Nạp xong rồi đó, lát nữa là máy hoạt động bình thường lại ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_07','V734','阮明',7,'太好了，终于可以联系家人和同学。','tài hǎo le， zhōng yú kě yǐ lián xì jiā rén hé tóng xué。','Tuyệt quá, cuối cùng cũng liên lạc được với gia đình và bạn học rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT735','SSH5','干洗店送洗衣物，询问污渍清洗、取件时效',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V735','SIT735','P1','twist','tuy_y',NULL,'重度油污、陈年污渍无法保证完全洗净，干洗店会根据清洗效果调整收费，提前告知顾客预期。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_01','V735','阮明',1,'你好，这件外套沾了油污，送过来干洗能完全洗掉污渍吗？','nǐ hǎo， zhè jiàn wài tào zhān le yóu wū， sòng guò lái gān xǐ néng wán quán xǐ diào wū zì ma？','Chào anh, cái áo khoác này dính dầu mỡ, đem giặt khô có sạch hết vết bẩn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_02','V735','干洗店员',2,'大面积油污需要特殊去渍剂，不一定能彻底清除干净。','dà miàn jī yóu wū xū yào tè shū qù zì jì， bù yí dìng néng chè dǐ qīng chú gān jìng。','Vết dầu loang rộng thế này phải dùng chất tẩy chuyên dụng, chưa chắc là tẩy sạch hoàn toàn được đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_03','V735','阮明',3,'要是洗完还有残留油污，会收取全套干洗费用嘛？','yào shì xǐ wán hái yǒu cán liú yóu wū， huì shōu qǔ quán tào gān xǐ fèi yòng ma？','Nếu giặt xong mà vẫn còn vết dầu sót lại thì có tính đủ tiền giặt khô như bình thường không ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_04','V735','干洗店员',4,'尽力清洗，无法去除重度污渍仅收取基础洗护半价嘛。','jìn lì qīng xǐ， wú fǎ qù chú zhòng dù wū zì jǐn shōu qǔ jī chǔ xǐ hù bàn jià ma。','Bên anh sẽ cố hết sức giặt, còn nếu không tẩy được vết bẩn nặng thì chỉ tính nửa giá giặt cơ bản thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_05','V735','阮明',5,'正常洗护多久可以取件，三天后过来取来得及吗？','zhèng cháng xǐ hù duō jiǔ kě yǐ qǔ jiàn， sān tiān hòu guò lái qǔ lái de jí ma？','Giặt bình thường thì mấy hôm lấy được, ba hôm nữa em quay lại lấy có kịp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_06','V735','干洗店员',6,'标准洗护两天完工，三天来取完全没有问题。','biāo zhǔn xǐ hù liǎng tiān wán gōng， sān tiān lái qǔ wán quán méi yǒu wèn tí。','Giặt tiêu chuẩn hai ngày là xong rồi, ba ngày lấy thì thoải mái luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_07','V735','阮明',7,'那我把外套留在店里，后天下午前来取衣服。','nà wǒ bǎ wài tào liú zài diàn lǐ， hòu tiān xià wǔ qián lái qǔ yī fú。','Vậy em để áo lại đây, chiều mốt em quay lại lấy áo.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT736','SSH5','上门保洁预约，和保洁阿姨确认清洁范围与时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V736','SIT736','P1','suon_se','ban_chinh_thuc',NULL,'上门保洁分基础清扫、深度清洁两类服务，厨房重度油污清理属于额外增值服务，需要增加时长与费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_01','V736','阮明',1,'阿姨，我预约两小时全屋保洁，跟您确认清洁区域吧。','ā yí， wǒ yù yuē liǎng xiǎo shí quán wū bǎo jié， gēn nín què rèn qīng jié qū yù ba。','Cô ơi, con đặt dọn dẹp toàn bộ nhà hai tiếng, con trao đổi trước với cô về khu vực cần dọn nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_02','V736','保洁阿姨',2,'客厅、卧室、卫生间常规清扫，厨房油污深度清洗需要额外加时。','kè tīng、 wò shì、 wèi shēng jiān cháng guī qīng sǎo， chú fáng yóu wū shēn dù qīng xǐ xū yào é wài jiā shí。','Phòng khách, phòng ngủ, nhà vệ sinh thì lau dọn bình thường, còn bếp nếu dính dầu mỡ nhiều cần dọn kỹ thì phải tính thêm giờ đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_03','V736','阮明',3,'厨房简单擦拭台面即可，不用深度清理厚重油污。','chú fáng jiǎn dān cā shì tái miàn jí kě， bù yòng shēn dù qīng lǐ hòu zhòng yóu wū。','Bếp thì lau mặt bàn sơ qua thôi cô, không cần dọn kỹ vết dầu mỡ dày đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_04','V736','保洁阿姨',4,'两小时只做基础除尘拖地，不含重度厨房油污清理。','liǎng xiǎo shí zhǐ zuò jī chǔ chú chén tuō dì， bù hán zhòng dù chú fáng yóu wū qīng lǐ。','Hai tiếng cô chỉ làm được phần lau bụi và lau sàn cơ bản thôi, không bao gồm dọn dầu mỡ nặng trong bếp đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_05','V736','阮明',5,'本周六上午九点上门，我提前把桌面杂物收纳好。','běn zhōu liù shàng wǔ jiǔ diǎn shàng mén， wǒ tí qián bǎ zhuō miàn zá wù shōu nà hǎo。','Thứ Bảy tuần này chín giờ sáng cô đến nhé, con sẽ dọn dẹp đồ đạc lộn xộn trên bàn trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_06','V736','保洁阿姨',6,'到点准时上门，杂物收纳干净清洁效率更高。','dào diǎn zhǔn shí shàng mén， zá wù shōu nà gān jìng qīng jié xiào lǜ gèng gāo。','Đúng giờ cô sẽ đến, con dọn sẵn đồ đạc gọn gàng thì cô làm việc cũng nhanh và hiệu quả hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_07','V736','阮明',7,'我提前整理房间，方便阿姨快速完成全屋保洁。','wǒ tí qián zhěng lǐ fáng jiān， fāng biàn ā yí kuài sù wán chéng quán wū bǎo jié。','Con sẽ dọn phòng trước, để cô tiện làm sạch nhanh cho cả nhà luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT737','SSH6','报名校园羽毛球社团，咨询会费、活动固定时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V737','SIT737','P1','suon_se','tuy_y',NULL,'国内高校学生社团会费低廉，仅用于活动耗材、场地租赁，定期开展免费校内文体活动。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_01','V737','阮明',1,'学长，我想加入羽毛球社团，请问入社需要缴纳会费吗？','xué zhǎng， wǒ xiǎng jiā rù yǔ máo qiú shè tuán， qǐng wèn rù shè xū yào jiǎo nà huì fèi ma？','Anh ơi, em muốn tham gia câu lạc bộ cầu lông, không biết vào có phải đóng hội phí không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_02','V737','学长',2,'一年二十元会费，全部用于采购羽毛球、场地租赁哦。','yī nián èr shí yuán huì fèi， quán bù yòng yú cǎi gòu yǔ máo qiú、 chǎng dì zū lìn ó。','Một năm hai mươi nghìn hội phí thôi, dùng để mua cầu lông với thuê sân đó mà.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_03','V737','阮明',3,'社团固定活动周几开展，是校内体育馆场地吗？','shè tuán gù dìng huó dòng zhōu jǐ kāi zhǎn， shì xiào nèi tǐ yù guǎn chǎng dì ma？','Câu lạc bộ sinh hoạt cố định vào thứ mấy vậy anh, có phải ở nhà thi đấu trong trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_04','V737','学长',4,'每周四傍晚六点到八点，校内羽毛球馆专属场地。','měi zhōu sì bàng wǎn liù diǎn dào bā diǎn， xiào nèi yǔ máo qiú guǎn zhuān shǔ chǎng dì。','Mỗi thứ Năm chiều tối từ sáu đến tám giờ, sân riêng ở nhà thi đấu cầu lông trong trường luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_05','V737','阮明',5,'没有自带球拍，社团可以临时借用训练球拍吗？','méi yǒu zì dài qiú pāi， shè tuán kě yǐ lín shí jiè yòng xùn liàn qiú pāi ma？','Em chưa có vợt riêng, câu lạc bộ có cho mượn vợt tạm để tập không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_06','V737','学长',6,'新人可免费借用公用球拍，长期参与建议自备球拍。','xīn rén kě miǎn fèi jiè yòng gōng yòng qiú pāi， cháng qī cān yù jiàn yì zì bèi qiú pāi。','Thành viên mới thì được mượn vợt chung miễn phí, còn tham gia lâu dài thì nên tự sắm vợt riêng nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_07','V737','阮明',7,'我今天缴纳会费入社，周四准时参加社团活动。','wǒ jīn tiān jiǎo nà huì fèi rù shè， zhōu sì zhǔn shí cān jiā shè tuán huó dòng。','Vậy hôm nay em đóng hội phí vào luôn, thứ Năm em sẽ tham gia sinh hoạt đúng giờ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT738','SSH6','校园操场运动扭伤，前往医务室简单处理伤口',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V738','SIT738','P1','twist','ban_chinh_thuc',NULL,'校内医务室跌打损伤、消炎外敷药品均可医保报销，运动受伤可免费冷敷理疗处理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_01','V738','阮明',1,'护士，操场跑步崴到脚踝，现在肿胀疼痛没法正常走路。','hù shì， cāo chǎng pǎo bù wǎi dào jiǎo huái， xiàn zài zhǒng zhàng téng tòng méi fǎ zhèng cháng zǒu lù。','Y tá ơi, em chạy ở sân vận động bị trẹo mắt cá chân, giờ nó sưng đau không đi lại bình thường được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_02','V738','护士',2,'先坐下抬高腿部冷敷消肿，我给你开外用消炎药膏。','xiān zuò xià tái gāo tuǐ bù lěng fū xiāo zhǒng， wǒ gěi nǐ kāi wài yòng xiāo yán yào gāo。','Em ngồi xuống kê cao chân lên chườm lạnh cho giảm sưng, cô kê cho em ít thuốc bôi kháng viêm nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_03','V738','阮明',3,'冷敷需要持续多久，今晚还能正常下床行走吗？','lěng fū xū yào chí xù duō jiǔ， jīn wǎn hái néng zhèng cháng xià chuáng xíng zǒu ma？','Chườm lạnh cần bao lâu ạ, tối nay em còn đi lại xuống giường bình thường được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_04','V738','护士',4,'连续冷敷二十分钟，三天之内尽量减少走路、剧烈运动嘛。','lián xù lěng fū èr shí fēn zhōng， sān tiān zhī nèi jǐn liàng jiǎn shǎo zǒu lù、 jù liè yùn dòng ma。','Chườm lạnh liên tục hai mươi phút, trong ba ngày cố gắng hạn chế đi lại và vận động mạnh nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_05','V738','阮明',5,'药膏医保可以报销吗，还是需要全额自费购买？','yào gāo yī bǎo kě yǐ bào xiāo ma， hái shì xū yào quán é zì fèi gòu mǎi？','Thuốc bôi này bảo hiểm y tế có thanh toán không cô, hay em phải tự trả hết ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_06','V738','护士',6,'外用跌打药膏纳入学生医保，只需要自费三成费用。','wài yòng diē dǎ yào gāo nà rù xué shēng yī bǎo， zhǐ xū yào zì fèi sān chéng fèi yòng。','Thuốc bôi trị bong gân được tính vào bảo hiểm y tế sinh viên, em chỉ cần tự trả ba mươi phần trăm thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_07','V738','阮明',7,'我拿药之后回宿舍静养，不再剧烈运动加重扭伤。','wǒ ná yào zhī hòu huí sù shè jìng yǎng， bù zài jù liè yùn dòng jiā zhòng niǔ shāng。','Em lấy thuốc xong về ký túc xá nghỉ ngơi tĩnh dưỡng, không vận động mạnh để tránh nặng thêm vết trẹo.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT739','SSH6','咨询校园奖学金申请条件、提交材料截止日期',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V739','SIT739','P1','suon_se','chinh_thuc',NULL,'留学生奖学金对出勤率、期末分数有硬性门槛，逾期不接受补报，错过只能等待下一学年申报。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_01','V739','阮明',1,'老师您好，想咨询留学生校级奖学金的申请基础条件。','lǎo shī nín hǎo， xiǎng zī xún liú xué shēng xiào jí jiǎng xué jīn de shēn qǐng jī chǔ tiáo jiàn。','Chào cô ạ, em muốn hỏi về điều kiện cơ bản để xin học bổng cấp trường dành cho lưu học sinh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_02','V739','教务老师',2,'全年出勤率达标、期末平均分七十五分以上方可申报。','quán nián chū qín lǜ dá biāo、 qī mò píng jūn fēn qī shí wǔ fēn yǐ shàng fāng kě shēn bào。','Tỷ lệ chuyên cần cả năm phải đạt chuẩn và điểm trung bình học kỳ phải từ bảy mươi lăm điểm trở lên mới được đăng ký.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_03','V739','阮明',3,'申请需要提交成绩单、在校证明，截止提交日期是哪天？','shēn qǐng xū yào tí jiāo chéng jì dān、 zài xiào zhèng míng， jié zhǐ tí jiāo rì qī shì nǎ tiān？','Hồ sơ cần nộp bảng điểm và giấy xác nhận đang học, vậy hạn nộp là ngày nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_04','V739','教务老师',4,'本月二十五号下午五点关闭申报通道，逾期不予受理。','běn yuè èr shí wǔ hào xià wǔ wǔ diǎn guān bì shēn bào tōng dào， yú qī bù yǔ shòu lǐ。','Hệ thống đăng ký sẽ đóng vào năm giờ chiều ngày hai mươi lăm tháng này, nộp trễ sẽ không được xét.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_05','V739','阮明',5,'材料线上系统提交，还是纸质复印件线下上交学院？','cái liào xiàn shàng xì tǒng tí jiāo， hái shì zhǐ zhì fù yìn jiàn xiàn xià shàng jiāo xué yuàn？','Hồ sơ nộp qua hệ thống trực tuyến, hay phải nộp bản in trực tiếp cho khoa ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_06','V739','教务老师',6,'线上填报信息，纸质材料线下送至国际学院办公室。','xiàn shàng tián bào xìn xī， zhǐ zhì cái liào xiàn xià sòng zhì guó jì xué yuàn bàn gōng shì。','Thông tin khai báo trực tuyến, còn hồ sơ giấy thì nộp trực tiếp tại văn phòng Học viện Quốc tế.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_07','V739','阮明',7,'我这周整理好全部材料，提前完成奖学金申报。','wǒ zhè zhōu zhěng lǐ hǎo quán bù cái liào， tí qián wán chéng jiǎng xué jīn shēn bào。','Tuần này em sẽ chuẩn bị đầy đủ hồ sơ, hoàn thành đăng ký học bổng sớm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT740','SSH6','校内丢失水杯、雨伞，去失物招领处登记寻物',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V740','SIT740','P1','that_bai_nhe','tuy_y',NULL,'校园失物招领处仅短期保管遗失物品，超过一周无人认领会统一收纳，长期无人认领定期清理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_01','V740','阮明',1,'你好，我昨天操场丢失黑色水杯、折叠雨伞，前来登记寻物。','nǐ hǎo， wǒ zuó tiān cāo chǎng diū shī hēi sè shuǐ bēi、 zhé dié yǔ sǎn， qián lái dēng jì xún wù。','Chào bạn, hôm qua mình làm mất bình nước màu đen và ô gấp ở sân vận động, giờ đến đăng ký tìm đồ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_02','V740','工作人员',2,'登记物品外观、丢失地点、你的联系方式，有人上交会通知你。','dēng jì wù pǐn wài guān、 diū shī dì diǎn、 nǐ de lián xì fāng shì， yǒu rén shàng jiāo huì tōng zhī nǐ。','Bạn đăng ký hình dạng đồ vật, chỗ mất và số liên lạc của bạn, có ai nộp lại thì sẽ báo cho bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_03','V740','阮明',3,'水杯侧面印有越南文字标识，雨伞是深蓝色，特征很明显。','shuǐ bēi cè miàn yìn yǒu yuè nán wén zì biāo shí， yǔ sǎn shì shēn lán sè， tè zhēng hěn míng xiǎn。','Bình nước có in chữ tiếng Việt ở bên hông, còn ô thì màu xanh đậm, đặc điểm rất rõ ràng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_04','V740','工作人员',4,'今日上交失物清单没有匹配物品，大概率还未被捡拾上交嘛。','jīn rì shàng jiāo shī wù qīng dān méi yǒu pǐ pèi wù pǐn， dà gài lǜ hái wèi bèi jiǎn shí shàng jiāo ma。','Danh sách đồ thất lạc nộp hôm nay không có món nào khớp, chắc là chưa ai nhặt được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_05','V740','阮明',5,'要是之后有人送到招领处，麻烦打电话通知我过来领取。','yào shì zhī hòu yǒu rén sòng dào zhāo lǐng chù， má fán dǎ diàn huà tōng zhī wǒ guò lái lǐng qǔ。','Nếu sau này có ai mang đến chỗ tìm đồ, phiền bạn gọi điện báo mình đến lấy nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_06','V740','工作人员',6,'登记信息留存一周，一周无人认领物品统一清理存放。','dēng jì xìn xī liú cún yī zhōu， yī zhōu wú rén rèn lǐng wù pǐn tǒng yī qīng lǐ cún fàng。','Thông tin đăng ký sẽ lưu một tuần, sau một tuần không ai nhận thì đồ sẽ được gom lại cất chỗ khác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_07','V740','阮明',7,'我三天后再来招领处询问，看看有没有捡到我的物品。','wǒ sān tiān hòu zài lái zhāo lǐng chù xún wèn， kàn kàn yǒu méi yǒu jiǎn dào wǒ de wù pǐn。','Ba ngày nữa mình sẽ quay lại chỗ tìm đồ hỏi thử, xem có ai nhặt được đồ của mình không.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT801','SHT1','向同班同学借课件PPT，拷贝到自己电脑复习',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V801','SIT801','P1','suon_se','tuy_y',NULL,'国内课堂老师大多会课后分享电子课件，同学之间互相转发课件、笔记是很普遍的互助学习习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_01','V801','阮明',1,'苏雯，昨天专业课老师的课件我忘记拷贝，能发我一份PPT吗？','sū wén， zuó tiān zhuān yè kè lǎo shī de kè jiàn wǒ wàng jì kǎo bèi， néng fā wǒ yī fèn PPT ma？','Tô Văn ơi, hôm qua mình quên chép lại slide bài giảng của thầy môn chuyên ngành, gửi mình một bản PPT được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_02','V801','苏雯',2,'没问题，我把完整课件打包，微信文件传输发给你就行啦。','méi wèn tí， wǒ bǎ wán zhěng kè jiàn dǎ bāo， wēi xìn wén jiàn chuán shū fā gěi nǐ jiù xíng la。','Không vấn đề gì, mình nén nguyên bộ slide lại rồi gửi qua WeChat cho cậu là được mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_03','V801','阮明',3,'文件内存很大，微信会不会压缩模糊里面的表格内容？','wén jiàn nèi cún hěn dà， wēi xìn huì bú huì yā suō mó hú lǐ miàn de biǎo gé nèi róng？','File dung lượng lớn vậy, WeChat có bị nén làm mờ mấy cái bảng biểu trong đó không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_04','V801','苏雯',4,'我发原文件不压缩，要是打不开我再分享网盘链接给你呢。','wǒ fā yuán wén jiàn bù yā suō， yào shì dǎ bù kāi wǒ zài fēn xiǎng wǎng pán liàn jiē gěi nǐ ne。','Mình gửi file gốc không nén đâu, nếu mở không được thì mình gửi thêm link ổ đám mây cho cậu nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_05','V801','阮明',5,'太好了，我今晚对照课件梳理今天课堂没听懂的知识点。','tài hǎo le， wǒ jīn wǎn duì zhào kè jiàn shū lǐ jīn tiān kè táng méi tīng dǒng de zhī shí diǎn。','Tuyệt quá, tối nay mình sẽ đối chiếu slide để xem lại mấy chỗ hôm nay chưa hiểu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_06','V801','苏雯',6,'课件里标注了期末重点，复习的时候可以优先看标红部分。','kè jiàn lǐ biāo zhù le qī mò zhòng diǎn， fù xí de shí hòu kě yǐ yōu xiān kàn biāo hóng bù fèn。','Trong slide có đánh dấu trọng tâm cuối kỳ rồi, lúc ôn thì cứ ưu tiên xem phần bôi đỏ trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_07','V801','阮明',7,'太感谢你，有完整课件复习会轻松很多。','tài gǎn xiè nǐ， yǒu wán zhěng kè jiàn fù xí huì qīng sōng hěn duō。','Cảm ơn cậu nhiều lắm, có slide đầy đủ ôn bài sẽ nhẹ nhàng hơn nhiều.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT802','SHT1','询问老师课堂录音是否允许，方便课后复盘知识点',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V802','SIT802','P1','twist','ban_chinh_thuc',NULL,'课堂自用录音一般老师都会许可，但传播授课录音、课件属于侵犯教学版权，会被制止。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_01','V802','阮明',1,'李老师，我汉语听力反应慢一点，请问上课可以手机录音吗？','lǐ lǎo shī， wǒ hàn yǔ tīng lì fǎn yìng màn yì diǎn， qǐng wèn shàng kè kě yǐ shǒu jī lù yīn ma？','Cô Lý ơi, khả năng nghe tiếng Trung của em hơi chậm, cho em xin hỏi trong giờ em có được dùng điện thoại ghi âm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_02','V802','李老师',2,'单纯自己课后复习录音是可以的，但禁止转发、上传网络平台。','dān chún zì jǐ kè hòu fù xí lù yīn shì kě yǐ de， dàn jìn zhǐ zhuǎn fā、 shàng chuán wǎng luò píng tái。','Nếu chỉ để tự nghe lại ôn bài sau giờ học thì được, nhưng cấm chia sẻ hay đăng lên mạng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_03','V802','阮明',3,'我只自己私下复盘，绝对不会分享录音给其他同学或者发到网上。','wǒ zhǐ zì jǐ sī xià fù pán， jué duì bú huì fēn xiǎng lù yīn gěi qí tā tóng xué huò zhě fā dào wǎng shàng。','Em chỉ nghe lại riêng cho bản thân thôi, tuyệt đối không chia sẻ bản ghi âm cho bạn khác hay đăng lên mạng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_04','V802','李老师',4,'还有一点，录音不能遮挡其他同学，手机音量一定要完全静音嘛。','hái yǒu yì diǎn， lù yīn bù néng zhē dǎng qí tā tóng xué， shǒu jī yīn liàng yí dìng yào wán quán jìng yīn ma。','Còn một điều nữa, ghi âm không được che khuất các bạn khác, và điện thoại phải để chế độ im lặng hoàn toàn nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_05','V802','阮明',5,'我把手机调成飞行模式，只开启本地录音，不会弹出消息打扰课堂。','wǒ bǎ shǒu jī diào chéng fēi xíng mó shì， zhǐ kāi qǐ běn dì lù yīn， bú huì dàn chū xiāo xī dǎ rǎo kè táng。','Em sẽ để điện thoại ở chế độ máy bay, chỉ bật ghi âm nội bộ thôi, sẽ không có thông báo hiện lên làm phiền tiết học đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_06','V802','李老师',6,'如果后期有听不懂的地方，结合录音再来办公室问我也可以。','rú guǒ hòu qī yǒu tīng bù dǒng de dì fāng， jié hé lù yīn zài lái bàn gōng shì wèn wǒ yě kě yǐ。','Nếu sau này có chỗ nào không hiểu, em cứ kết hợp bản ghi âm rồi lên văn phòng hỏi cô cũng được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_07','V802','阮明',7,'谢谢您允许录音，课后我能反复梳理课堂难点。','xiè xiè nín yǔn xǔ lù yīn， kè hòu wǒ néng fǎn fù shū lǐ kè táng nán diǎn。','Em cảm ơn cô đã cho phép ghi âm, sau giờ học em có thể xem lại nhiều lần những chỗ khó hiểu trên lớp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT803','SHT1','课堂听不懂专业词汇，课后找同学一对一讲解',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V803','SIT803','P1','suon_se','tuy_y',NULL,'课后同学之间一对一拆解难点、互相讲题是高校主流互助学习方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_01','V803','阮明',1,'今天课上老师讲的几个贸易专业术语，我完全没理解含义啊。','jīn tiān kè shàng lǎo shī jiǎng de jǐ gè mào yì zhuān yè shù yǔ， wǒ wán quán méi lǐ jiě hán yì a。','Hôm nay trên lớp thầy giảng mấy thuật ngữ chuyên ngành ngoại thương, mình chẳng hiểu nghĩa gì cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_02','V803','苏雯',2,'这几个词是国内外贸常用词汇，我举简单例子给你拆解意思。','zhè jǐ gè cí shì guó nèi wài mào cháng yòng cí huì， wǒ jǔ jiǎn dān lì zi gěi nǐ chāi jiě yì si。','Mấy từ này là từ vựng ngoại thương thông dụng trong và ngoài nước đó, để mình lấy ví dụ đơn giản giải thích cho cậu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_03','V803','阮明',3,'每个词汇搭配例句讲一遍，我才能分清使用场景对吧？','měi gè cí huì dā pèi lì jù jiǎng yī biàn， wǒ cái néng fēn qīng shǐ yòng chǎng jǐng duì ba？','Mỗi từ đều phải kèm theo câu ví dụ giảng một lượt thì mình mới phân biệt được ngữ cảnh sử dụng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_04','V803','苏雯',4,'没错，我结合课本习题举例，方便你区分易混淆词汇。','méi cuò， wǒ jié hé kè běn xí tí jǔ lì， fāng biàn nǐ qū fēn yì hùn xiáo cí huì。','Đúng vậy, mình sẽ kết hợp bài tập trong sách để lấy ví dụ, cho cậu dễ phân biệt những từ dễ nhầm lẫn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_05','V803','阮明',5,'耽误你半小时休息时间，实在不好意思麻烦你。','dān wù nǐ bàn xiǎo shí xiū xī shí jiān， shí zài bù hǎo yì sī má fán nǐ。','Làm mất nửa tiếng nghỉ ngơi của cậu rồi, thật ngại quá đi mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_06','V803','苏雯',6,'互相讲题很正常，之后我有语言难题也会找你帮忙。','hù xiāng jiǎng tí hěn zhèng cháng， zhī hòu wǒ yǒu yǔ yán nán tí yě huì zhǎo nǐ bāng máng。','Giảng bài giúp nhau là chuyện bình thường mà, sau này mình gặp khó khăn về ngôn ngữ cũng sẽ nhờ cậu giúp lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_07','V803','阮明',7,'太感谢，听完讲解一下子清晰多了。','tài gǎn xiè， tīng wán jiǎng jiě yī xià zi qīng xī duō le。','Cảm ơn cậu nhiều lắm, nghe cậu giảng xong là mình hiểu rõ ngay luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT804','SHT1','咨询老师课程平时分构成：出勤、课堂发言、小测占比',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V804','SIT804','P1','suon_se','ban_chinh_thuc',NULL,'国内大学课程普遍实行平时分+期末试卷综合打分，不会仅凭一次期末成绩定总分，鼓励日常课堂参与。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_01','V804','阮明',1,'老师，想向您咨询这门课期末总评分数的分配标准。','lǎo shī， xiǎng xiàng nín zī xún zhè mén kè qī mò zǒng píng fēn shù de fēn pèi biāo zhǔn。','Thưa cô, em muốn hỏi cô về cách tính điểm tổng kết cuối kỳ của môn này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_02','V804','李老师',2,'总评由三部分组成：出勤20%、课堂发言与随堂小测30%、期末试卷50%哦。','zǒng píng yóu sān bù fèn zǔ chéng： chū qín 20%、 kè táng fā yán yǔ suí táng xiǎo cè 30%、 qī mò shì juàn 50% ó。','Điểm tổng kết gồm ba phần: chuyên cần hai mươi phần trăm, phát biểu trên lớp và kiểm tra nhỏ ba mươi phần trăm, bài thi cuối kỳ năm mươi phần trăm nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_03','V804','阮明',3,'随堂小测每节课都会有吗，缺课一次会直接扣掉出勤分？','suí táng xiǎo cè měi jié kè dōu huì yǒu ma， quē kè yī cì huì zhí jiē kòu diào chū qín fēn？','Vậy có kiểm tra nhỏ mỗi buổi học không ạ, nghỉ một buổi có bị trừ thẳng điểm chuyên cần không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_04','V804','李老师',4,'无故缺课单次扣5分，请假备案不扣分；小测每月一次，错过可补。','wú gù quē kè dān cì kòu 5 fēn， qǐng jià bèi àn bù kòu fēn； xiǎo cè měi yuè yī cì， cuò guò kě bǔ。','Nghỉ không phép sẽ bị trừ năm điểm mỗi lần, có xin phép và ghi nhận thì không bị trừ; kiểm tra nhỏ mỗi tháng một lần, lỡ nghỉ thì có thể kiểm tra bù.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_05','V804','阮明',5,'课堂发言只要主动回答问题，就能拿到对应的平时分吗？','kè táng fā yán zhǐ yào zhǔ dòng huí dá wèn tí， jiù néng ná dào duì yìng de píng shí fēn ma？','Chỉ cần chủ động phát biểu trả lời câu hỏi là được tính điểm chuyên cần tương ứng phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_06','V804','李老师',6,'主动思考作答、有完整观点，都会记录课堂表现分。','zhǔ dòng sī kǎo zuò dá、 yǒu wán zhěng guān diǎn， dōu huì jì lù kè táng biǎo xiàn fēn。','Chỉ cần chủ động suy nghĩ trả lời, có quan điểm rõ ràng, thì đều được ghi nhận vào điểm thể hiện trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_07','V804','阮明',7,'我清楚分值规则了，之后多主动参与课堂互动。','wǒ qīng chǔ fēn zhí guī zé le， zhī hòu duō zhǔ dòng cān yù kè táng hù dòng。','Em đã hiểu rõ quy tắc tính điểm rồi ạ, sau này em sẽ chủ động tham gia hoạt động trên lớp nhiều hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT805','SHT1','忘记带课本，和同桌共用一本书听课',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V805','SIT805','P1','twist','tuy_y',NULL,'课堂忘记带教材和同桌共用书本很常见，但不建议长期如此，会影响双方记笔记效率。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_01','V805','阮明',1,'糟糕，早上出门匆忙，把专业课课本落在宿舍了，能和你共用一本吗？','zāo gāo， zǎo shàng chū mén cōng máng， bǎ zhuān yè kè kè běn luò zài sù shè le， néng hé nǐ gòng yòng yī běn ma？','Chết rồi, sáng nay đi vội quá nên để quên sách chuyên ngành ở ký túc xá, cho mình dùng chung một cuốn với cậu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_02','V805','小林',2,'可以一起看，不过书本放在中间，记笔记会有点挤不方便。','kě yǐ yì qǐ kàn， bù guò shū běn fàng zài zhōng jiān， jì bǐ jì huì yǒu diǎn jǐ bù fāng biàn。','Xem chung cũng được, nhưng sách để ở giữa thì ghi chép sẽ hơi chật, bất tiện đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_03','V805','阮明',3,'我只对照书页听讲解，笔记先记在草稿纸上，下课再整理。','wǒ zhǐ duì zhào shū yè tīng jiǎng jiě， bǐ jì xiān jì zài cǎo gǎo zhǐ shàng， xià kè zài zhěng lǐ。','Mình chỉ nhìn theo trang sách để nghe giảng thôi, ghi chú thì mình ghi ra giấy nháp trước, hết giờ rồi sắp xếp lại sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_04','V805','小林',4,'老师等下要勾画重点段落，我们分开两边各自标注会不会混乱嘛。','lǎo shī děng xià yào gōu huà zhòng diǎn duàn luò， wǒ men fēn kāi liǎng biān gè zì biāo zhù huì bú huì hùn luàn ma。','Lát nữa thầy sẽ khoanh vùng đoạn trọng tâm, hai đứa mỗi bên tự đánh dấu riêng thì có bị loạn không nhỉ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_05','V805','阮明',5,'我手机拍课本页面，重点自己在照片上标记，不影响你看书。','wǒ shǒu jī pāi kè běn yè miàn， zhòng diǎn zì jǐ zài zhào piān shàng biāo jì， bù yǐng xiǎng nǐ kàn shū。','Mình chụp ảnh trang sách bằng điện thoại, trọng tâm thì tự đánh dấu trên ảnh, không ảnh hưởng gì đến việc cậu xem sách đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_06','V805','小林',6,'这样也行，有看不懂的段落随时指给我一起讨论。','zhè yàng yě xíng， yǒu kàn bù dǒng de duàn luò suí shí zhǐ gěi wǒ yì qǐ tǎo lùn。','Vậy cũng được, có đoạn nào không hiểu thì cứ chỉ cho mình để cùng bàn luận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_07','V805','阮明',7,'今天多亏你，不然整节课没法跟上老师进度。','jīn tiān duō kuī nǐ， bù rán zhěng jié kè méi fǎ gēn shàng lǎo shī jìn dù。','Hôm nay may nhờ có cậu, không thì cả tiết học mình chẳng theo kịp tiến độ của thầy đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT806','SHT1','上课手机静音没做到，被老师提醒课堂纪律',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V806','SIT806','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂严格管控手机声响，震动、响铃都会被老师提醒，多次违规会扣除课堂表现分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_01','V806','阮明',1,'老师对不起，刚刚手机消息突然响铃，打断您讲课了。','lǎo shī duì bù qǐ， gāng gāng shǒu jī xiāo xī tū rán xiǎng líng， dǎ duàn nín jiǎng kè le。','Thầy ơi em xin lỗi, vừa nãy điện thoại em bỗng nhiên đổ chuông, làm gián đoạn bài giảng của thầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_02','V806','李老师',2,'课堂要求所有手机必须完全静音或关机，你忘记调整设置了？','kè táng yāo qiú suǒ yǒu shǒu jī bì xū wán quán jìng yīn huò guān jī， nǐ wàng jì tiáo zhěng shè zhì le？','Trong giờ học yêu cầu tất cả điện thoại phải để im lặng hoàn toàn hoặc tắt máy, em quên chỉnh cài đặt à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_03','V806','阮明',3,'早上调了震动，没想到震动声响也很明显，干扰全班听课嘛。','zǎo shàng diào le zhèn dòng， méi xiǎng dào zhèn dòng shēng xiǎng yě hěn míng xiǎn， gān rǎo quán bān tīng kè ma。','Sáng em có chỉnh chế độ rung rồi, không ngờ tiếng rung cũng khá to, làm cả lớp bị phân tâm khi nghe giảng ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_04','V806','李老师',4,'一次警告不计入扣分，之后如果再出现声响会扣除课堂平时分。','yī cì jǐng gào bù jì rù kòu fēn， zhī hòu rú guǒ zài chū xiàn shēng xiǎng huì kòu chú kè táng píng shí fēn。','Lần này thầy cảnh cáo không tính vào điểm trừ, nhưng sau này nếu còn phát ra tiếng động thì sẽ bị trừ điểm chuyên cần trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_05','V806','阮明',5,'我现在直接关机，整节课不再开启手机接收消息。','wǒ xiàn zài zhí jiē guān jī， zhěng jié kè bù zài kāi qǐ shǒu jī jiē shōu xiāo xī。','Em tắt máy luôn bây giờ ạ, cả tiết học em sẽ không bật điện thoại nhận tin nhắn nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_06','V806','李老师',6,'课堂需要安静的听讲环境，还请遵守班级课堂规定。','kè táng xū yào ān jìng de tīng jiǎng huán jìng， hái qǐng zūn shǒu bān jí kè táng guī dìng。','Trong giờ học cần môi trường yên tĩnh để nghe giảng, mong em tuân thủ quy định của lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_07','V806','阮明',7,'我记住教训，之后课前一定检查手机静音状态。','wǒ jì zhù jiào xùn， zhī hòu kè qián yí dìng jiǎn chá shǒu jī jìng yīn zhuàng tài。','Em ghi nhớ bài học này rồi ạ, sau này trước giờ học em nhất định sẽ kiểm tra chế độ im lặng của điện thoại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT807','SHT1','咨询课程课外拓展阅读书目、图书馆馆藏位置',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V807','SIT807','P1','suon_se','ban_chinh_thuc',NULL,'大学专业课会配套拓展阅读书目，图书馆专业馆藏区集中存放对应书籍，支持学生课外自主拓展学习。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_01','V807','阮明',1,'老师，想提升专业水平，请问这门课配套拓展阅读书籍有哪些？','lǎo shī， xiǎng tí shēng zhuān yè shuǐ píng， qǐng wèn zhè mén kè pèi tào tuò zhǎn yuè dú shū jí yǒu nǎ xiē？','Thầy ơi, em muốn nâng cao trình độ chuyên môn, thầy cho em hỏi môn học này có những sách đọc thêm mở rộng nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_02','V807','李老师',2,'我列三本核心参考书，全部存放在图书馆三楼外文专业区哦。','wǒ liè sān běn hé xīn cān kǎo shū， quán bù cún fàng zài tú shū guǎn sān lóu wài wén zhuān yè qū ó。','Cô liệt kê ba cuốn sách tham khảo cốt lõi, tất cả đều để ở khu vực chuyên ngành ngoại văn tầng ba thư viện nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_03','V807','阮明',3,'这几本书可以外借带回家长期阅读，还是只能馆内阅览？','zhè jǐ běn shū kě yǐ wài jiè dài huí jiā zhǎng qī yuè dú， hái shì zhǐ néng guǎn nèi yuè lǎn？','Mấy cuốn này có thể mượn về nhà đọc lâu dài, hay chỉ được đọc tại chỗ trong thư viện thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_04','V807','李老师',4,'均可借阅三十天，线上系统还能办理续借延长阅读时间。','jūn kě jiè yuè sān shí tiān， xiàn shàng xì tǒng hái néng bàn lǐ xù jiè yán cháng yuè dú shí jiān。','Đều được mượn trong ba mươi ngày, hệ thống trực tuyến còn có thể gia hạn để kéo dài thời gian đọc nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_05','V807','阮明',5,'我记下书名，下课直接去图书馆检索借阅。','wǒ jì xià shū míng， xià kè zhí jiē qù tú shū guǎn jiǎn suǒ jiè yuè。','Em ghi lại tên sách rồi, tan học em ra thư viện tra cứu mượn luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_06','V807','李老师',6,'阅读完有疑问，随时来办公室和我交流书中观点。','yuè dú wán yǒu yí wèn， suí shí lái bàn gōng shì hé wǒ jiāo liú shū zhōng guān diǎn。','Đọc xong có gì thắc mắc thì cứ đến văn phòng trao đổi quan điểm trong sách với cô bất cứ lúc nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_07','V807','阮明',7,'感谢老师推荐书目，对我的专业学习帮助很大。','gǎn xiè lǎo shī tuī jiàn shū mù， duì wǒ de zhuān yè xué xí bāng zhù hěn dà。','Em cảm ơn cô đã giới thiệu sách, giúp ích rất nhiều cho việc học chuyên ngành của em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT808','SHT1','小组讨论时观点分歧，和组员温和协商统一思路',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V808','SIT808','P1','suon_se','tuy_y',NULL,'国内小组作业鼓励充分发表不同观点，通过讨论、分工、投票协商统一方案，不强行听从单一人员想法。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_01','V808','阮明',1,'我对小组报告案例选取有不同想法，和大家现在选定的方向不一样。','wǒ duì xiǎo zǔ bào gào àn lì xuǎn qǔ yǒu bù tóng xiǎng fǎ， hé dà jiā xiàn zài xuǎn dìng de fāng xiàng bù yí yàng。','Mình có ý khác về việc chọn tình huống cho bài báo cáo nhóm, khác với hướng mà mọi người đang chọn đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_02','V808','苏雯',2,'你说说你的思路，我们一起对比两个方案的优劣再做决定。','nǐ shuō shuō nǐ de sī lù， wǒ men yì qǐ duì bǐ liǎng gè fāng àn de yōu liè zài zuò jué dìng。','Cậu nói thử ý tưởng của cậu xem, tụi mình so sánh ưu nhược điểm của hai phương án rồi quyết định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_03','V808','阮明',3,'我选的案例数据更贴近留学生视角，更容易结合我们课堂所学。','wǒ xuǎn de àn lì shù jù gèng tiē jìn liú xué shēng shì jiǎo， gèng róng yì jié hé wǒ men kè táng suǒ xué。','Case mình chọn có dữ liệu sát với góc nhìn du học sinh hơn, dễ gắn với kiến thức tụi mình học trên lớp hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_04','V808','苏雯',4,'原有案例优势是资料充足，你的案例需要额外查找外文资料嘛。','yuán yǒu àn lì yōu shì shì zī liào chōng zú， nǐ de àn lì xū yào é wài chá zhǎo wài wén zī liào ma。','Ưu điểm của case cũ là tài liệu sẵn có nhiều, còn case của cậu thì phải tìm thêm tài liệu ngoại văn đó nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_05','V808','阮明',5,'我可以负责全部外文资料检索，分担小组搜集素材的工作量。','wǒ kě yǐ fù zé quán bù wài wén zī liào jiǎn suǒ， fēn dān xiǎo zǔ sōu jí sù cái de gōng zuò liàng。','Mình có thể phụ trách toàn bộ việc tra tài liệu ngoại văn, chia sẻ bớt khối lượng thu thập tư liệu cho nhóm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_06','V808','苏雯',6,'那我们投票，多数人认可你的方案就调整报告选题。','nà wǒ men tóu piào， duō shù rén rèn kě nǐ de fāng àn jiù tiáo zhěng bào gào xuǎn tí。','Vậy tụi mình biểu quyết đi, đa số đồng ý phương án của cậu thì đổi đề tài báo cáo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_07','V808','阮明',7,'谢谢大家愿意一起讨论，综合所有人想法完善作业。','xiè xiè dà jiā yuàn yì yì qǐ tǎo lùn， zōng hé suǒ yǒu rén xiǎng fǎ wán shàn zuò yè。','Cảm ơn mọi người sẵn lòng cùng bàn bạc, gộp ý kiến của tất cả mọi người để hoàn thiện bài tập.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT809','SHT1','询问老师课堂发言加分规则，主动争取平时分',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V809','SIT809','P1','suon_se','ban_chinh_thuc',NULL,'大学课堂鼓励学生主动发言提问，以此折算平时分，平衡期末试卷单一考核的局限性。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_01','V809','阮明',1,'老师，想咨询课堂发言加分的详细规则，我想多争取平时表现分。','lǎo shī， xiǎng zī xún kè táng fā yán jiā fēn de xiáng xì guī zé， wǒ xiǎng duō zhēng qǔ píng shí biǎo xiàn fēn。','Thầy ơi, em muốn hỏi kỹ quy định cộng điểm khi phát biểu trên lớp, em muốn cố gắng kiếm thêm điểm quá trình ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_02','V809','李老师',2,'主动举手回答、提出有价值疑问、上台简短分享，都能累加课堂分。','zhǔ dòng jǔ shǒu huí dá、 tí chū yǒu jià zhí yí wèn、 shàng tái jiǎn duǎn fēn xiǎng， dōu néng lěi jiā kè táng fēn。','Chủ động giơ tay trả lời, đặt câu hỏi có giá trị, lên bảng chia sẻ ngắn gọn, đều được cộng dồn điểm trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_03','V809','阮明',3,'每次发言加分分值相同，还是完整长篇回答分值更高？','měi cì fā yán jiā fēn fēn zhí xiāng tóng， hái shì wán zhěng cháng piān huí dá fēn zhí gèng gāo？','Mỗi lần phát biểu điểm cộng có bằng nhau không ạ, hay trả lời dài đầy đủ thì điểm cao hơn?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_04','V809','李老师',4,'不看长短，只要独立思考、贴合课堂主题，每次统一加2分。','bù kàn cháng duǎn， zhǐ yào dú lì sī kǎo、 tiē hé kè táng zhǔ tí， měi cì tǒng yī jiā 2 fēn。','Không tính dài ngắn, chỉ cần suy nghĩ độc lập, bám sát chủ đề bài học, mỗi lần đều cộng thống nhất 2 điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_05','V809','阮明',5,'每节课最多能几次发言，有没有单次课堂加分上限？','měi jié kè zuì duō néng jǐ cì fā yán， yǒu méi yǒu dān cì kè táng jiā fēn shàng xiàn？','Mỗi tiết học tối đa được phát biểu mấy lần ạ, có giới hạn điểm cộng cho một buổi học không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_06','V809','李老师',6,'无次数上限，只要不占用过多课堂时间均可主动发言。','wú cì shù shàng xiàn， zhǐ yào bù zhàn yòng guò duō kè táng shí jiān jūn kě zhǔ dòng fā yán。','Không giới hạn số lần, chỉ cần không chiếm quá nhiều thời gian lớp học thì đều có thể chủ động phát biểu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_07','V809','阮明',7,'之后每节课我主动思考提问、回答，积极参与课堂互动。','zhī hòu měi jié kè wǒ zhǔ dòng sī kǎo tí wèn、 huí dá， jī jí cān yù kè táng hù dòng。','Vậy từ nay mỗi tiết học em sẽ chủ động suy nghĩ, đặt câu hỏi, trả lời, tích cực tham gia tương tác trên lớp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT810','SHT2','论文引用格式不懂，请教专业课老师规范要求',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V810','SIT810','P1','twist','chinh_thuc',NULL,'国内高校毕业论文统一执行国家标准参考文献格式，自媒体网络内容认可度低，学术写作优先纸质期刊、专著。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_01','V810','阮明',1,'老师，毕业论文参考文献引用格式我始终把握不准，想向您请教标准。','lǎo shī， bì yè lùn wén cān kǎo wén xiàn yǐn yòng gé shì wǒ shǐ zhōng bǎ wò bù zhǔn， xiǎng xiàng nín qǐng jiào biāo zhǔn。','Thầy ơi, em vẫn không nắm chắc định dạng trích dẫn tài liệu tham khảo trong luận văn tốt nghiệp, em muốn xin thầy chỉ dẫn chuẩn quy định ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_02','V810','李老师',2,'校内统一使用GB/T7714国家标准格式，课件最后附完整范例。','xiào nèi tǒng yī shǐ yòng GB/T7714 guó jiā biāo zhǔn gé shì， kè jiàn zuì hòu fù wán zhěng fàn lì。','Trong trường thống nhất dùng định dạng chuẩn quốc gia GB/T7714, phần cuối slide bài giảng có kèm ví dụ đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_03','V810','阮明',3,'外文书籍、期刊、网页资料三种文献格式区分很大对吗？','wài wén shū jí、 qī kān、 wǎng yè zī liào sān zhǒng wén xiàn gé shì qū fēn hěn dà duì ma？','Ba loại tài liệu là sách ngoại văn, tạp chí và tư liệu trên mạng có định dạng khác nhau nhiều đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_04','V810','李老师',4,'网页自媒体资源不建议大量引用，书籍、正规期刊优先使用嘛。','wǎng yè zì méi tǐ zī yuán bù jiàn yì dà liàng yǐn yòng， shū jí、 zhèng guī qī kān yōu xiān shǐ yòng ma。','Tài nguyên từ các trang mạng xã hội thì không nên trích dẫn nhiều, nên ưu tiên dùng sách và tạp chí chính thống nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_05','V810','阮明',5,'我按照课件范例调整格式，修改完成后能麻烦您帮忙检查一遍吗？','wǒ àn zhào kè jiàn fàn lì tiáo zhěng gé shì， xiū gǎi wán chéng hòu néng má fán nín bāng máng jiǎn chá yī biàn ma？','Em sẽ chỉnh định dạng theo ví dụ trong slide bài giảng, chỉnh xong phiền thầy xem giúp em một lượt được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_06','V810','李老师',6,'初稿定稿前可以发我线上预览，指出格式错误再修改。','chū gǎo dìng gǎo qián kě yǐ fā wǒ xiàn shàng yù lǎn， zhǐ chū gé shì cuò wù zài xiū gǎi。','Trước khi hoàn thiện bản thảo cuối cùng có thể gửi cho thầy xem trước qua mạng, thầy sẽ chỉ ra lỗi định dạng để em sửa lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_07','V810','阮明',7,'谢谢您耐心指导引用规范，避免论文大量格式扣分。','xiè xiè nín nài xīn zhǐ dǎo yǐn yòng guī fàn， bì miǎn lùn wén dà liàng gé shì kòu fēn。','Em cảm ơn thầy đã kiên nhẫn hướng dẫn quy chuẩn trích dẫn, giúp em tránh bị trừ nhiều điểm vì lỗi định dạng trong luận văn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT811','SHT2','查重重复率超标，咨询老师降重修改方法',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V811','SIT811','P1','that_bai_nhe','ban_chinh_thuc',NULL,'高校毕业论文查重有硬性重复率阈值，复制粘贴原文会判定学术不端，必须自行转述降重。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_01','V811','阮明',1,'老师，我的初稿论文查重重复率超过30%，达不到学校合格标准。','lǎo shī， wǒ de chū gǎo lùn wén chá chóng chóng fù lǜ chāo guò 30%， dá bú dào xué xiào hé gé biāo zhǔn。','Thầy ơi, tỷ lệ trùng lặp bản thảo luận văn của em vượt quá 30%, không đạt chuẩn của trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_02','V811','李老师',2,'合格重复率要求控制在20%以内，超标需要大面积改写降重。','hé gé chóng fù lǜ yāo qiú kòng zhì zài 20% yǐ nèi， chāo biāo xū yào dà miàn jī gǎi xiě jiàng zhòng。','Yêu cầu tỷ lệ trùng lặp đạt chuẩn phải kiểm soát trong 20%, vượt quá thì cần chỉnh sửa viết lại trên diện rộng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_03','V811','阮明',3,'我只是直接摘抄文献句子，不清楚转述改写的技巧啊。','wǒ zhǐ shì zhí jiē zhāi chāo wén xiàn jù zi， bù qīng chǔ zhuǎn shù gǎi xiě de jì qiǎo a。','Em chỉ trực tiếp chép câu từ tài liệu thôi, em không rõ kỹ thuật diễn đạt lại bằng lời văn khác ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_04','V811','李老师',4,'不能简单替换同义词，要调整句子语序、拆分长句、补充自己的分析嘛。','bù néng jiǎn dān tì huàn tóng yì cí， yào tiáo zhěng jù zi yǔ xù、 chāi fēn cháng jù、 bǔ chōng zì jǐ de fēn xī ma。','Không thể chỉ đơn giản thay từ đồng nghĩa, phải điều chỉnh trật tự câu, tách câu dài ra, bổ sung phân tích của riêng mình nữa nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_05','V811','阮明',5,'图表数据、公式部分会不会计入重复率，需要重新绘制吗？','tú biǎo shù jù、 gōng shì bù fèn huì bú huì jì rù chóng fù lǜ， xū yào chóng xīn huì zhì ma？','Phần biểu đồ dữ liệu, công thức có bị tính vào tỷ lệ trùng lặp không ạ, có cần vẽ lại không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_06','V811','李老师',6,'通用公式不计入，文字分析段落必须全部重新转述改写。','tōng yòng gōng shì bù jì rù， wén zì fēn xī duàn luò bì xū quán bù chóng xīn zhuǎn shù gǎi xiě。','Công thức thông dụng thì không tính, còn đoạn phân tích văn bản thì bắt buộc phải viết lại toàn bộ bằng lời văn khác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_07','V811','阮明',7,'我按照您的方法逐段改写，修改完成后再次提交查重。','wǒ àn zhào nín de fāng fǎ zhú duàn gǎi xiě， xiū gǎi wán chéng hòu zài cì tí jiāo chá zhòng。','Em sẽ viết lại theo cách thầy hướng dẫn từng đoạn một, xong rồi nộp kiểm tra trùng lặp lại lần nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT812','SHT2','找不到外文参考文献，求助图书馆馆员检索外文数据库',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V812','SIT812','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆购买多语种外文数据库，仅校园内网、校园VPN可免费下载全文外文文献。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_01','V812','阮明',1,'老师，我写论文需要越南、东南亚相关外文文献，自己检索不到。','lǎo shī， wǒ xiě lùn wén xū yào yuè nán、 dōng nán yà xiāng guān wài wén wén xiàn， zì jǐ jiǎn suǒ bú dào。','Thầy ơi, em viết luận văn cần tài liệu ngoại văn liên quan đến Việt Nam, Đông Nam Á, mà em tự tìm không ra ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_02','V812','王馆员',2,'校内开通多国外文数据库，我带你进入外文检索专属页面。','xiào nèi kāi tōng duō guó wài wén shù jù kù， wǒ dài nǐ jìn rù wài wén jiǎn suǒ zhuān shǔ yè miàn。','Trường mình có mở nhiều cơ sở dữ liệu ngoại văn quốc tế, để cô dẫn em vào trang tra cứu ngoại văn chuyên dụng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_03','V812','阮明',3,'输入关键词只能检索中文文献，需要切换语种检索入口对吧？','shū rù guān jiàn cí zhǐ néng jiǎn suǒ zhōng wén wén xiàn， xū yào qiè huàn yǔ zhǒng jiǎn suǒ rù kǒu duì ba？','Nhập từ khóa chỉ tra được tài liệu tiếng Trung thôi ạ, phải chuyển sang cổng tra cứu ngôn ngữ khác đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_04','V812','王馆员',4,'没错，切换外文语种后，限定地区、出版年份缩小检索范围。','méi cuò， qiè huàn wài wén yǔ zhǒng hòu， xiàn dìng dì qū、 chū bǎn nián fèn suō xiǎo jiǎn suǒ fàn wéi。','Đúng rồi, sau khi chuyển sang ngôn ngữ nước ngoài, em có thể giới hạn khu vực, năm xuất bản để thu hẹp phạm vi tìm kiếm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_05','V812','阮明',5,'检索到的外文文献可以直接下载全文PDF吗？','jiǎn suǒ dào de wài wén wén xiàn kě yǐ zhí jiē xià zài quán wén PDF ma？','Tài liệu ngoại văn tra được có thể tải trực tiếp bản PDF đầy đủ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_06','V812','王馆员',6,'校内IP可免费下载，校外需要登录校园网VPN访问数据库。','xiào nèi IP kě miǎn fèi xià zài， xiào wài xū yào dēng lù xiào yuán wǎng VPN fǎng wèn shù jù kù。','IP trong trường được tải miễn phí, còn ở ngoài trường thì phải đăng nhập VPN mạng trường mới truy cập được cơ sở dữ liệu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_07','V812','阮明',7,'麻烦您带我操作一遍检索流程，之后我自己查找文献。','má fán nín dài wǒ cāo zuò yī biàn jiǎn suǒ liú chéng， zhī hòu wǒ zì jǐ chá zhǎo wén xiàn。','Phiền cô dẫn em thực hành thử quy trình tra cứu một lượt, sau đó em sẽ tự tìm tài liệu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT813','SHT2','打印论文装订格式错误，打印店重新调整排版',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V813','SIT813','P1','twist','tuy_y',NULL,'各学院毕业论文有统一打印排版模板，页眉、行距、页边距、装订线均有硬性规范，打印店常备模板供学生使用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_01','V813','阮明',1,'你好，刚打印的毕业论文装订不对，页码、页眉格式不符合学院要求。','nǐ hǎo， gāng dǎ yìn de bì yè lùn wén zhuāng dìng bú duì， yè mǎ、 yè méi gé shì bù fú hé xué yuàn yāo qiú。','Chào anh, luận văn tốt nghiệp em vừa in bị đóng gáy sai, định dạng số trang, đầu trang không đúng yêu cầu của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_02','V813','店员',2,'学院有统一排版模板，你刚才直接上传文档没有套用标准模板嘛。','xué yuàn yǒu tǒng yī pái bǎn mú bǎn， nǐ gāng cái zhí jiē shàng chuán wén dàng méi yǒu tào yòng biāo zhǔn mú bǎn ma。','Khoa có mẫu định dạng thống nhất, lúc nãy em tải tài liệu lên trực tiếp mà không áp dụng mẫu chuẩn đó nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_03','V813','阮明',3,'我不知道学校专用模板，直接用自己电脑里的格式导出打印了。','wǒ bù zhī dào xué xiào zhuān yòng mú bǎn， zhí jiē yòng zì jǐ diàn nǎo lǐ de gé shì dǎo chū dǎ yìn le。','Em không biết là trường có mẫu riêng, nên em cứ dùng định dạng trong máy tính của mình xuất ra in thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_04','V813','店员',4,'我现在套用学院官方模板重新调整，页眉、页码、行距全部统一修改。','wǒ xiàn zài tào yòng xué yuàn guān fāng mú bǎn chóng xīn tiáo zhěng， yè méi、 yè mǎ、 háng jù quán bù tǒng yī xiū gǎi。','Giờ anh áp mẫu chính thức của khoa vào chỉnh lại, đầu trang, số trang, giãn dòng đều sẽ chỉnh thống nhất hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_05','V813','阮明',5,'重新排版打印会额外收取一次打印费用吗？','chóng xīn pái bǎn dǎ yìn huì é wài shōu qǔ yī cì dǎ yìn fèi yòng ma？','Sắp xếp lại và in lại như vậy có bị tính thêm phí in lần nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_06','V813','店员',6,'格式调整失误首次免费重打，多次修改才会叠加收费。','gé shì tiáo zhěng shī wù shǒu cì miǎn fèi zhòng dǎ， duō cì xiū gǎi cái huì dié jiā shōu fèi。','Lỗi định dạng thì lần đầu in lại miễn phí, sửa nhiều lần mới bị cộng thêm phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_07','V813','阮明',7,'辛苦重新排版，调整完我检查无误再装订成册。','xīn kǔ chóng xīn pái bǎn， tiáo zhěng wán wǒ jiǎn chá wú wù zài zhuāng dìng chéng cè。','Cảm ơn anh đã chịu khó sắp xếp lại, chỉnh xong em kiểm tra không có lỗi thì sẽ đóng thành quyển.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT814','SHT2','小组论文有人拖延进度，和组员沟通制定截止时间表',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V814','SIT814','P1','suon_se','tuy_y',NULL,'国内小组作业普遍设置分段截止日期，避免临近交稿集体赶工、质量粗糙。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_01','V814','阮明',1,'距离小组论文提交只剩五天，有部分板块素材还没有收集完成。','jù lí xiǎo zǔ lùn wén tí jiāo zhǐ shèng wǔ tiān， yǒu bù fèn bǎn kuài sù cái hái méi yǒu shōu jí wán chéng。','Chỉ còn năm ngày nữa là đến hạn nộp luận văn nhóm rồi, mà một số phần tư liệu vẫn chưa thu thập xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_02','V814','苏雯',2,'有两位组员进度滞后，我们统一拆分每日任务，设置分段小截止期。','yǒu liǎng wèi zǔ yuán jìn dù zhì hòu， wǒ men tǒng yī chāi fēn měi rì rèn wù， shè zhì fēn duàn xiǎo jié zhǐ qī。','Có hai bạn trong nhóm bị chậm tiến độ, tụi mình thống nhất chia nhỏ công việc mỗi ngày, đặt các mốc hạn nhỏ theo từng giai đoạn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_03','V814','小林',3,'每天晚上八点群内同步当日完成内容，避免最后一天集中赶工。','měi tiān wǎn shàng bā diǎn qún nèi tóng bù dāng rì wán chéng nèi róng， bì miǎn zuì hòu yī tiān jí zhōng gǎn gōng。','Mỗi tối tám giờ mọi người cập nhật trong nhóm chat những gì đã hoàn thành trong ngày, tránh để dồn hết vào ngày cuối cùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_04','V814','阮明',4,'我负责外文文献翻译，最晚后天完成全部翻译素材交付。','wǒ fù zé wài wén wén xiàn fān yì， zuì wǎn hòu tiān wán chéng quán bù fān yì sù cái jiāo fù。','Mình phụ trách dịch tài liệu ngoại văn, chậm nhất là ngày kia mình sẽ giao đủ toàn bộ tư liệu dịch.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_05','V814','苏雯',5,'每人明确标注自己的分工与完成时间，逾期提前在群内说明困难。','měi rén míng què biāo zhù zì jǐ de fēn gōng yǔ wán chéng shí jiān， yú qī tí qián zài qún nèi shuō míng kùn nán。','Mỗi người ghi rõ phần việc và thời gian hoàn thành của mình, nếu trễ hạn thì báo trước khó khăn trong nhóm chat nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_06','V814','阮明',6,'如果有人遇到检索、写作难题，群内大家一起协助解决。','rú guǒ yǒu rén yù dào jiǎn suǒ、 xiě zuò nán tí， qún nèi dà jiā yì qǐ xié zhù jiě jué。','Nếu có ai gặp khó khăn khi tra cứu, viết bài thì cả nhóm cùng hỗ trợ giải quyết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_07','V814','小林',7,'按时间表分段推进，保证论文完整、高质量按时上交。','àn shí jiān biǎo fēn duàn tuī jìn， bǎo zhèng lùn wén wán zhěng、 gāo zhì liàng àn shí shàng jiāo。','Cứ theo lịch trình chia giai đoạn mà tiến hành, đảm bảo luận văn hoàn chỉnh, chất lượng và nộp đúng hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT815','SHT2','咨询论文致谢、摘要、关键词标准写作规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V815','SIT815','P1','suon_se','chinh_thuc',NULL,'国内本科毕业论文强制要求中文摘要+英文摘要、规范关键词、简短致谢，三部分有固定字数与格式标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_01','V815','阮明',1,'老师，想请教毕业论文摘要、关键词、致谢三段写作规范。','lǎo shī， xiǎng qǐng jiào bì yè lùn wén zhāi yào、 guān jiàn cí、 zhì xiè sān duàn xiě zuò guī fàn。','Thưa thầy, em muốn hỏi về quy chuẩn viết ba phần tóm tắt, từ khóa và lời cảm ơn trong luận văn tốt nghiệp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_02','V815','李老师',2,'摘要三百字以内，完整概括研究目的、方法、结论；关键词3-5个。','zhāi yào sān bǎi zì yǐ nèi， wán zhěng gài kuò yán jiū mù dì、 fāng fǎ、 jié lùn； guān jiàn cí 3-5 gè。','Tóm tắt trong khoảng ba trăm chữ, phải khái quát đầy đủ mục đích nghiên cứu, phương pháp và kết luận; từ khóa thì từ 3 đến 5 từ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_03','V815','阮明',3,'致谢部分可以感谢家人、同学、授课老师，篇幅有限制吗？','zhì xiè bù fèn kě yǐ gǎn xiè jiā rén、 tóng xué、 shòu kè lǎo shī， piān fú yǒu xiàn zhì ma？','Phần lời cảm ơn có thể cảm ơn gia đình, bạn học, thầy cô giảng dạy, độ dài có giới hạn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_04','V815','李老师',4,'致谢篇幅一页以内，简洁真诚即可，不用过度冗长抒情嘛。','zhì xiè piān fú yī yè yǐ nèi， jiǎn jié zhēn chéng jí kě， bù yòng guò dù rǒng cháng shū qíng ma。','Lời cảm ơn không quá một trang, viết ngắn gọn chân thành là được, không cần dài dòng cảm xúc quá đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_05','V815','阮明',5,'摘要需要中英文双语版本，翻译关键词也要对应准确？','zhāi yào xū yào zhōng yīng wén shuāng yǔ bǎn běn， fān yì guān jiàn cí yě yào duì yìng zhǔn què？','Tóm tắt cần có cả bản tiếng Việt lẫn tiếng Anh, phần dịch từ khóa cũng phải tương ứng chính xác đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_06','V815','李老师',6,'本科毕业论文摘要中英文对照，关键词逐词精准翻译。','běn kē bì yè lùn wén zhāi yào zhōng yīng wén duì zhào， guān jiàn cí zhú cí jīng zhǔn fān yì。','Tóm tắt luận văn tốt nghiệp đại học phải đối chiếu song ngữ, từ khóa dịch chính xác từng từ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_07','V815','阮明',7,'我按照规范撰写三段内容，初稿写完发给您检查。','wǒ àn zhào guī fàn zhuàn xiě sān duàn nèi róng， chū gǎo xiě wán fā gěi nín jiǎn chá。','Em sẽ viết ba phần này đúng theo quy chuẩn, viết xong bản nháp sẽ gửi thầy kiểm tra.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT816','SHT2','电脑崩溃丢失作业初稿，向老师说明情况申请延后上交',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V816','SIT816','P1','twist','ban_chinh_thuc',NULL,'学生设备故障丢失作业属于合理客观事由，多数老师会适度放宽提交期限，但会提醒养成云端备份文件的习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_01','V816','阮明',1,'老师不好意思，昨晚电脑系统崩溃，存储的课程论文初稿全部丢失。','lǎo shī bù hǎo yì sī， zuó wǎn diàn nǎo xì tǒng bēng kuì， cún chǔ de kè chéng lùn wén chū gǎo quán bù diū shī。','Thầy ơi, xin lỗi thầy, tối qua máy tính em bị sập hệ thống, bản nháp bài luận môn học lưu trong máy mất hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_02','V816','李老师',2,'有没有云端备份、U盘备份，能找回一部分写作内容吗？','yǒu méi yǒu yún duān bèi fèn、U pán bèi fèn， néng zhǎo huí yī bù fèn xiě zuò nèi róng ma？','Em có sao lưu trên mây hay USB không, có tìm lại được phần nào nội dung đã viết không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_03','V816','阮明',3,'没有及时云端同步，只保留少量手写草稿，完整电子版全部丢失嘛。','méi yǒu jí shí yún duān tóng bù， zhǐ bǎo liú shǎo liàng shǒu xiě cǎo gǎo， wán zhěng diàn zi bǎn quán bù diū shī ma。','Em chưa kịp đồng bộ lên mây, chỉ còn giữ được ít bản viết tay, còn bản điện tử đầy đủ thì mất sạch hết rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_04','V816','李老师',4,'正常截止时间今天下午，突发设备故障可以延后一天提交。','zhèng cháng jié zhǐ shí jiān jīn tiān xià wǔ， tū fā shè bèi gù zhàng kě yǐ yán hòu yī tiān tí jiāo。','Hạn nộp bình thường là chiều nay, nhưng do sự cố thiết bị đột xuất thì có thể lùi lại một ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_05','V816','阮明',5,'我今天通宵重新撰写，明天上午一定完整上交定稿。','wǒ jīn tiān tōng xiāo chóng xīn zhuàn xiě， míng tiān shàng wǔ yí dìng wán zhěng shàng jiāo dìng gǎo。','Em sẽ thức đêm nay viết lại từ đầu, sáng mai chắc chắn nộp bản hoàn chỉnh đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_06','V816','李老师',6,'下次重要作业记得云端备份，避免设备故障丢失全部文稿。','xià cì zhòng yào zuò yè jì de yún duān bèi fèn， bì miǎn shè bèi gù zhàng diū shī quán bù wén gǎo。','Lần sau làm bài quan trọng nhớ sao lưu lên mây, tránh để thiết bị hỏng mà mất hết bản thảo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_07','V816','阮明',7,'感谢老师通融延后提交，之后一定养成备份文件的习惯。','gǎn xiè lǎo shī tōng róng yán hòu tí jiāo， zhī hòu yí dìng yǎng chéng bèi fèn wén jiàn de xí guàn。','Em cảm ơn thầy đã thông cảm cho lùi hạn nộp, sau này em nhất định tập thói quen sao lưu file.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT817','SHT2','分不清直接引用、间接转述，找助教讲解论文写作规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V817','SIT817','P1','suon_se','tuy_y',NULL,'学术写作严格区分直接引用与间接转述，大段无标注摘抄会判定抄袭，大幅拉高查重重复率。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_01','V817','阮明',1,'学长，写论文分不清直接引用和间接转述，很容易查重超标。','xué zhǎng， xiě lùn wén fēn bù qīng zhí jiē yǐn yòng hé jiàn jiē zhuǎn shù， hěn róng yì chá zhòng chāo biāo。','Anh ơi, em viết luận văn cứ lẫn lộn giữa trích dẫn trực tiếp với thuật lại gián tiếp, rất dễ bị vượt tỷ lệ trùng lặp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_02','V817','张学长',2,'直接引用加引号标注页码，篇幅不能过长；转述改写句式无需引号。','zhí jiē yǐn yòng jiā yǐn hào biāo zhù yè mǎ， piān fú bù néng guò cháng； zhuǎn shù gǎi xiě jù shì wú xū yǐn hào。','Trích dẫn trực tiếp thì cho vào ngoặc kép và ghi số trang, không được dài quá; còn thuật lại thì đổi cách diễn đạt, không cần ngoặc kép.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_03','V817','阮明',3,'大段文献观点只能全部改写转述，不能连续直接摘抄原文对吧？','dà duàn wén xiàn guān diǎn zhǐ néng quán bù gǎi xiě zhuǎn shù， bù néng lián xù zhí jiē zhāi chāo yuán wén duì ba？','Vậy những đoạn quan điểm dài trong tài liệu chỉ có thể viết lại thuật lại hết, không được chép nguyên văn liên tục đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_04','V817','张学长',4,'单次直接引用不能超过三行，长观点必须拆分转述融合自己分析。','dān cì zhí jiē yǐn yòng bù néng chāo guò sān xíng， zhǎng guān diǎn bì xū chāi fēn zhuǎn shù róng hé zì jǐ fēn xī。','Đúng rồi, mỗi lần trích dẫn trực tiếp không được quá ba dòng, quan điểm dài thì bắt buộc phải tách ra thuật lại kết hợp với phân tích của mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_05','V817','阮明',5,'我拿一段自己写的文字，麻烦你标出哪里引用格式出错。','wǒ ná yī duàn zì jǐ xiě de wén zì， má fán nǐ biāo chū nǎ lǐ yǐn yòng gé shì chū cuò。','Em có một đoạn tự viết, phiền anh chỉ giúp em chỗ nào sai định dạng trích dẫn với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_06','V817','张学长',6,'没问题，逐句给你修改示范，方便你之后独立写作。','méi wèn tí， zhú jù gěi nǐ xiū gǎi shì fàn， fāng biàn nǐ zhī hòu dú lì xiě zuò。','Không vấn đề gì, anh sửa mẫu cho em từng câu một, để sau này em tự viết cho tiện.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_07','V817','阮明',7,'听完示范清晰很多，不会再出现引用违规问题。','tīng wán shì fàn qīng xī hěn duō， bú huì zài chū xiàn yǐn yòng wéi guī wèn tí。','Nghe anh giảng mẫu xong em thấy rõ ràng hơn nhiều, chắc không còn bị lỗi trích dẫn nữa đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT818','SHT2','询问期末课程论文字数下限、允许浮动范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V818','SIT818','P1','suon_se','ban_chinh_thuc',NULL,'课程论文、毕业论文有硬性最低正文字数要求，篇幅不足会被判定内容单薄，大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_01','V818','阮明',1,'老师，期末课程论文要求最低字数五千字，上下浮动多少算合格？','lǎo shī， qī mò kè chéng lùn wén yāo qiú zuì dī zì shù wǔ qiān zì， shàng xià fú dòng duō shǎo suàn hé gé？','Thầy ơi, bài luận cuối kỳ yêu cầu tối thiểu năm nghìn chữ, dao động lên xuống bao nhiêu thì vẫn đạt ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_02','V818','李老师',2,'正文五千字不含摘要参考文献，上下浮动五百字以内都可接受哦。','zhèng wén wǔ qiān zì bù hán zhāi yào cān kǎo wén xiàn， shàng xià fú dòng wǔ bǎi zì yǐ nèi dōu kě jiē shòu ó。','Phần thân bài năm nghìn chữ không tính tóm tắt và tài liệu tham khảo, dao động trong khoảng năm trăm chữ đều chấp nhận được nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_03','V818','阮明',3,'字数不足四千五，会直接扣除论文基础分数吗？','zì shù bù zú sì qiān wǔ， huì zhí jiē kòu chú lùn wén jī chǔ fēn shù ma？','Nếu thiếu chưa đến bốn nghìn năm trăm chữ thì có bị trừ thẳng điểm cơ bản của bài luận không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_04','V818','李老师',4,'低于四千五会判定内容单薄，基础分直接减半。','dī yú sì qiān wǔ huì pàn dìng nèi róng dān bó， jī chǔ fēn zhí jiē jiǎn bàn。','Dưới bốn nghìn năm trăm chữ sẽ bị coi là nội dung sơ sài, điểm cơ bản sẽ bị trừ đi một nửa luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_05','V818','阮明',5,'图表、注释文字算不算入正文字数统计？','tú biǎo、 zhù shì wén zì suàn bù suàn rù zhèng wén zì shù tǒng jì？','Vậy chữ trong biểu đồ, chú thích có được tính vào số chữ phần thân bài không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_06','V818','李老师',6,'图表说明、页下注释不计入，仅主体论述段落统计字数。','tú biǎo shuō míng、 yè xià zhù shì bù jì rù， jǐn zhǔ tǐ lùn shù duàn luò tǒng jì zì shù。','Chú thích biểu đồ và ghi chú cuối trang không được tính, chỉ tính số chữ ở các đoạn luận thuật chính thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_07','V818','阮明',7,'我控制正文五千字左右，保证内容完整不缺篇幅。','wǒ kòng zhì zhèng wén wǔ qiān zì zuǒ yòu， bǎo zhèng nèi róng wán zhěng bù quē piān fú。','Em sẽ cố gắng khống chế phần thân bài khoảng năm nghìn chữ, đảm bảo nội dung đầy đủ không thiếu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT819','SHT2','论文提交系统上传失败，咨询学院教务线上补交渠道',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V819','SIT819','P1','twist','ban_chinh_thuc',NULL,'课程、毕业论文线上提交系统有固定截止时间与文件格式、大小限制，超时通道自动关闭不再受理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_01','V819','阮明',1,'老师，论文线上提交系统上传文档一直提示失败，无法完成提交。','lǎo shī， lùn wén xiàn shàng tí jiāo xì tǒng shàng chuán wén dàng yì zhí tí shì shī bài， wú fǎ wán chéng tí jiāo。','Thầy ơi, em tải bài luận lên hệ thống nộp bài trực tuyến mãi mà cứ báo lỗi thất bại, không nộp được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_02','V819','教务老师',2,'大概率文档内存过大、格式不是PDF，系统仅支持PDF格式上传嘛。','dà gài lǜ wén dàng nèi cún guò dà、 gé shì bú shì PDF， xì tǒng jǐn zhī chí PDF gé shì shàng chuán ma。','Có thể là do file quá nặng, hoặc định dạng không phải PDF, hệ thống chỉ hỗ trợ nộp file PDF thôi đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_03','V819','阮明',3,'我原本是Word文档，直接转换PDF之后文件大小超系统限制。','wǒ yuán běn shì Word wén dàng， zhí jiē zhuǎn huàn PDF zhī hòu wén jiàn dà xiǎo chāo xì tǒng xiàn zhì。','Ban đầu em làm file Word, sau khi chuyển sang PDF thì dung lượng lại vượt quá giới hạn hệ thống cho phép.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_04','V819','教务老师',4,'压缩PDF文件降低分辨率，缩小内存后重新进入系统提交。','yā suō PDF wén jiàn jiàng dī fēn biàn lǜ， suō xiǎo nèi cún hòu chóng xīn jìn rù xì tǒng tí jiāo。','Em nén file PDF, giảm độ phân giải xuống, sau khi dung lượng nhỏ lại thì vào hệ thống nộp lại thử xem.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_05','V819','阮明',5,'今天是提交截止日，压缩完成后错过零点还能补交吗？','jīn tiān shì tí jiāo jié zhǐ rì， yā suō wán chéng hòu cuò guò líng diǎn hái néng bǔ jiāo ma？','Hôm nay là hạn chót nộp bài rồi, nếu nén xong mà lỡ qua 0 giờ thì có nộp bù được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_06','V819','教务老师',6,'系统零点关闭通道，今晚二十三点五十九分前必须上传成功。','xì tǒng líng diǎn guān bì tōng dào， jīn wǎn èr shí sān diǎn wǔ shí jiǔ fēn qián bì xū shàng chuán chéng gōng。','Hệ thống sẽ đóng cổng nộp bài lúc 0 giờ, bắt buộc phải tải lên thành công trước 23 giờ 59 phút tối nay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_07','V819','阮明',7,'我立刻压缩文档，赶在通道关闭前完成论文提交。','wǒ lì kè yā suō wén dàng， gǎn zài tōng dào guān bì qián wán chéng lùn wén tí jiāo。','Em sẽ nén file ngay bây giờ, cố gắng nộp xong bài luận trước khi cổng nộp đóng lại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT820','SHT3','想引用网络自媒体资料，咨询老师是否符合学术规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V820','SIT820','P1','that_bai_nhe','ban_chinh_thuc',NULL,'自媒体、短视频平台内容不具备学术权威性，高校论文不允许单独以此作为核心论证依据。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_01','V820','阮明',1,'老师，论文里想引用自媒体公众号文章的数据作为论据可以吗？','lǎo shī， lùn wén lǐ xiǎng yǐn yòng zì méi tǐ gōng zhòng hào wén zhāng de shù jù zuò wéi lùn jù kě yǐ ma？','Thầy ơi, trong bài luận em muốn trích dẫn số liệu từ một bài viết trên tài khoản mạng xã hội để làm luận cứ, có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_02','V820','李老师',2,'自媒体无正规学术审核，仅能作为辅助参考，不能当作核心论据。','zì méi tǐ wú zhèng guī xué shù shěn hé， jǐn néng zuò wéi fǔ zhù cān kǎo， bù néng dàng zuò hé xīn lùn jù。','Tài khoản mạng xã hội không qua thẩm định học thuật chính thức, chỉ dùng để tham khảo hỗ trợ thôi, không thể dùng làm luận cứ cốt lõi được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_03','V820','阮明',3,'如果数据来源只有自媒体，有没有办法合规写入论文内容？','rú guǒ shù jù lái yuán zhǐ yǒu zì méi tǐ， yǒu méi yǒu bàn fǎ hé guī xiě rù lùn wén nèi róng？','Nếu nguồn số liệu duy nhất chỉ có từ mạng xã hội thì có cách nào đưa vào bài luận cho hợp lệ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_04','V820','李老师',4,'必须搭配官方期刊、统计年鉴佐证，单独自媒体内容不予认可嘛。','bì xū dā pèi guān fāng qī kān、 tǒng jì nián jiàn zuǒ zhèng， dān dú zì méi tǐ nèi róng bù yǔ rèn kě ma。','Bắt buộc phải kèm theo tạp chí chính thống, niên giám thống kê để làm căn cứ, chỉ dùng riêng nội dung mạng xã hội thì không được công nhận đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_05','V820','阮明',5,'那我放弃自媒体素材，重新检索官方行业报告替换论据。','nà wǒ fàng qì zì méi tǐ sù cái， chóng xīn jiǎn suǒ guān fāng háng yè bào gào tì huàn lùn jù。','Vậy em bỏ tư liệu từ mạng xã hội, tìm lại các báo cáo ngành chính thức để thay thế luận cứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_06','V820','李老师',6,'学术论文优先采用官方、期刊、专著类权威文献资料。','xué shù lùn wén yōu xiān cǎi yòng guān fāng、 qī kān、 zhuān zhù lèi quán wēi wén xiàn zī liào。','Bài luận học thuật nên ưu tiên dùng tài liệu uy tín từ nguồn chính thống, tạp chí khoa học, chuyên khảo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_07','V820','阮明',7,'我重新查找正规数据源，保证论文引用符合学术标准。','wǒ chóng xīn chá zhǎo zhèng guī shù jù yuán， bǎo zhèng lùn wén yǐn yòng fú hé xué shù biāo zhǔn。','Em sẽ tìm lại nguồn số liệu chính quy, đảm bảo phần trích dẫn trong bài luận đúng chuẩn học thuật.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT821','SHT3','咨询老师期末复习重点、必考章节范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V821','SIT821','P1','suon_se','ban_chinh_thuc',NULL,'期末考前老师会划定大致复习范围，缩小复习体量，但不会直接透露原题，依靠学生自主背诵理解。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_01','V821','阮明',1,'老师，距离期末考还有两周，想咨询课程核心复习重点章节。','lǎo shī， jù lí qī mò kǎo hái yǒu liǎng zhōu， xiǎng zī xún kè chéng hé xīn fù xí zhòng diǎn zhāng jié。','Thầy ơi, còn hai tuần nữa là thi cuối kỳ, em muốn hỏi những chương trọng tâm cần ôn tập của môn học ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_02','V821','李老师',2,'课本中间四个单元是试卷主要考点，首尾单元仅少量选择题哦。','kè běn zhōng jiān sì gè dān yuán shì shì juàn zhǔ yào kǎo diǎn， shǒu wěi dān yuán jǐn shǎo liàng xuǎn zé tí ó。','Bốn đơn vị bài ở giữa sách giáo trình là trọng tâm chính của đề thi, hai đơn vị đầu và cuối chỉ có ít câu trắc nghiệm thôi.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_03','V821','阮明',3,'课后拓展阅读书目、课外补充案例会不会出大题？','kè hòu tuò zhǎn yuè dú shū mù、 kè wài bǔ chōng àn lì huì bú huì chū dà tí？','Vậy sách đọc thêm ngoài giờ hay các ví dụ bổ sung ngoài chương trình có ra trong câu hỏi lớn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_04','V821','李老师',4,'大题全部来自课内课本与课堂例题，课外内容仅少量选择填空。','dà tí quán bù lái zì kè nèi kè běn yǔ kè táng lì tí， kè wài nèi róng jǐn shǎo liàng xuǎn zé tián kòng。','Câu hỏi lớn đều lấy từ sách giáo trình và ví dụ trên lớp, phần ngoài chương trình chỉ có ít câu trắc nghiệm hoặc điền khuyết thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_05','V821','阮明',5,'名词解释、论述题分别对应课本哪一部分内容？','míng cí jiě shì、 lùn shù tí fēn bié duì yìng kè běn nǎ yī bù fèn nèi róng？','Câu giải thích thuật ngữ và câu luận thuật thì tương ứng với phần nào trong sách ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_06','V821','李老师',6,'名词解释每单元课后词汇，论述题是课堂反复讲解的核心观点。','míng cí jiě shì měi dān yuán kè hòu cí huì， lùn shù tí shì kè táng fǎn fù jiǎng jiě de hé xīn guān diǎn。','Giải thích thuật ngữ là từ vựng sau mỗi đơn vị bài học, còn câu luận thuật là những quan điểm cốt lõi được giảng đi giảng lại trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_07','V821','阮明',7,'我优先重点复习核心单元，针对性背诵大题考点。','wǒ yōu xiān zhòng diǎn fù xí hé xīn dān yuán， zhēn duì xìng bèi sòng dà tí kǎo diǎn。','Em sẽ ưu tiên ôn kỹ các đơn vị bài trọng tâm, học thuộc có trọng điểm những phần dễ ra câu hỏi lớn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT822','SHT3','错过随堂小测，询问老师能否安排补测',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V822','SIT822','P1','twist','ban_chinh_thuc',NULL,'因病、公事请假缺测可凭证明补测，无故缺考无补测机会，直接扣除对应平时分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_01','V822','阮明',1,'老师，上周随堂小测我生病请假，没能到场完成测试。','lǎo shī， shàng zhōu suí táng xiǎo cè wǒ shēng bìng qǐng jià， méi néng dào chǎng wán chéng cè shì。','Thầy ơi, tuần trước em bị ốm xin nghỉ nên không đến làm bài kiểm tra nhỏ trên lớp được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_02','V822','李老师',2,'有医院病假证明备案的学生，可以统一参加期末前集中补测。','yǒu yī yuàn bìng jià zhèng míng bèi àn de xué shēng， kě yǐ tǒng yī cān jiā qī mò qián jí zhōng bǔ cè。','Những em nào có giấy xác nhận nghỉ ốm của bệnh viện đăng ký đầy đủ thì có thể tham gia đợt kiểm tra bù tập trung trước kỳ thi cuối kỳ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_03','V822','阮明',3,'我保留完整医院病历单据，今天带来给您登记备案可以吗？','wǒ bǎo liú wán zhěng yī yuàn bìng lì dān jù， jīn tiān dài lái gěi nín dēng jì bèi àn kě yǐ ma？','Em còn giữ đầy đủ hồ sơ bệnh án của bệnh viện, hôm nay em mang đến nộp cho thầy đăng ký được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_04','V822','李老师',4,'病历登记截止本周四，周四之后不再受理补测报名嘛。','bìng lì dēng jì jié zhǐ běn zhōu sì， zhōu sì zhī hòu bù zài shòu lǐ bǔ cè bào míng ma。','Hạn đăng ký hồ sơ bệnh án là hết thứ Năm tuần này, sau thứ Năm thì không nhận đăng ký kiểm tra bù nữa đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_05','V822','阮明',5,'补测试卷难度、分值和正常随堂小测完全一致吗？','bǔ cè shì juàn nán dù、 fēn zhí hé zhèng cháng suí táng xiǎo cè wán quán yí zhì ma？','Đề kiểm tra bù có độ khó và thang điểm giống hệt bài kiểm tra nhỏ bình thường trên lớp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_06','V822','李老师',6,'题型、分值标准相同，只是作答时间缩短十分钟。','tí xíng、 fēn zhí biāo zhǔn xiāng tóng， zhǐ shì zuò dá shí jiān suō duǎn shí fēn zhōng。','Dạng đề và thang điểm giống nhau, chỉ có thời gian làm bài rút ngắn mười phút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_07','V822','阮明',7,'我今天上交病假单登记，按时参加统一补测。','wǒ jīn tiān shàng jiāo bìng jià dān dēng jì， àn shí cān jiā tǒng yī bǔ cè。','Hôm nay em sẽ nộp giấy nghỉ ốm để đăng ký, tham gia đúng giờ đợt kiểm tra bù tập trung.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT823','SHT3','期末挂科，咨询补考报名时间、复习范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V823','SIT823','P1','suon_se','chinh_thuc',NULL,'国内大学补考最高绩点60分，仅标记及格，无法参与奖学金评选，重修才能刷新分数。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_01','V823','阮明',1,'老师，这门专业课期末挂科，想咨询补考报名与复习范围。','lǎo shī， zhè mén zhuān yè kè qī mò guà kē， xiǎng zī xún bǔ kǎo bào míng yǔ fù xí fàn wéi。','Thưa thầy/cô, môn chuyên ngành này em bị rớt kỳ thi cuối kỳ, em muốn hỏi về thời gian đăng ký thi lại và phạm vi ôn tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_02','V823','教务老师',2,'开学第一周线上系统开放补考报名，逾期视为自动放弃补考。','kāi xué dì yī zhōu xiàn shàng xì tǒng kāi fàng bǔ kǎo bào míng， yú qī shì wèi zì dòng fàng qì bǔ kǎo。','Tuần đầu tiên của học kỳ mới, hệ thống trực tuyến sẽ mở đăng ký thi lại, quá hạn sẽ được xem như tự động từ bỏ quyền thi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_03','V823','阮明',3,'补考试卷考点和期末试卷范围一样，还是会更换全新章节？','bǔ kǎo shì juàn kǎo diǎn hé qī mò shì juàn fàn wéi yī yàng， hái shì huì gēng huàn quán xīn zhāng jié？','Đề thi lại có phạm vi kiến thức giống đề thi cuối kỳ không, hay sẽ đổi sang chương mới hoàn toàn ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_04','V823','教务老师',4,'考点范围完全相同，试卷题目全部重新出题，不会使用原卷。','kǎo diǎn fàn wéi wán quán xiāng tóng， shì juàn tí mù quán bù chóng xīn chū tí， bú huì shǐ yòng yuán juǎn。','Phạm vi kiến thức hoàn toàn giống nhau, nhưng đề thi sẽ được ra mới toàn bộ, không sử dụng lại đề cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_05','V823','阮明',5,'补考及格即可拿到学分，补考分数会直接替代期末成绩吗？','bǔ kǎo jí gé jí kě ná dào xué fēn， bǔ kǎo fēn shù huì zhí jiē tì dài qī mò chéng jì ma？','Chỉ cần thi lại đạt là được công nhận tín chỉ, vậy điểm thi lại có thay thế trực tiếp điểm cuối kỳ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_06','V823','教务老师',6,'补考最高记60分及格，无论考多高都不会计入高分。','bǔ kǎo zuì gāo jì 60 fēn jí gé， wú lùn kǎo duō gāo dōu bú huì jì rù gāo fēn。','Điểm thi lại cao nhất chỉ được ghi nhận là 60 điểm đạt, dù thi được điểm cao hơn cũng không được tính thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_07','V823','阮明',7,'我暑假完整复习课本核心内容，开学顺利通过补考。','wǒ shǔ jià wán zhěng fù xí kè běn hé xīn nèi róng， kāi xué shùn lì tōng guò bǔ kǎo。','Em sẽ ôn tập kỹ toàn bộ nội dung trọng tâm trong sách suốt hè, để đầu học kỳ mới thi lại đạt thuận lợi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT824','SHT3','补考仍未通过，咨询重修选课流程与缴费标准',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V824','SIT824','P1','that_bai_nhe','chinh_thuc',NULL,'补考不及格必须重修该门课程，按学分收取重修费用，全部考核达标才能拿到对应学分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_01','V824','阮明',1,'老师，补考依旧没有及格，想咨询课程重修办理流程。','lǎo shī， bǔ kǎo yī jiù méi yǒu jí gé， xiǎng zī xún kè chéng chóng xiū bàn lǐ liú chéng。','Thưa thầy/cô, em thi lại vẫn không đạt, em muốn hỏi về thủ tục đăng ký học lại môn này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_02','V824','教务老师',2,'下一学期选课周期，线上系统勾选重修课程，缴纳重修学分费。','xià yī xué qī xuǎn kè zhōu qī， xiàn shàng xì tǒng gōu xuǎn chóng xiū kè chéng， jiǎo nà chóng xiū xué fēn fèi。','Vào đợt đăng ký môn học của học kỳ sau, em chọn môn học lại trên hệ thống trực tuyến và đóng học phí tín chỉ học lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_03','V824','阮明',3,'重修需要全程跟班上课、完成全部平时作业与课堂小测吗？','chóng xiū xū yào quán chéng gēn bān shàng kè、 wán chéng quán bù píng shí zuò yè yǔ kè táng xiǎo cè ma？','Học lại có cần theo học đầy đủ cùng lớp, hoàn thành hết bài tập thường xuyên và các bài kiểm tra trên lớp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_04','V824','教务老师',4,'是的，重修完整复刻正常课程考核规则，出勤、作业、考试全部计分嘛。','shì de， chóng xiū wán zhěng fù kè zhèng cháng kè chéng kǎo hé guī zé， chū qín、 zuò yè、 kǎo shì quán bù jì fēn ma。','Đúng vậy, học lại áp dụng đầy đủ quy định đánh giá như môn học bình thường, điểm danh, bài tập, thi cử đều được tính điểm hết.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_05','V824','阮明',5,'一学分重修收费标准多少，一门完整课程一共几学分？','yī xué fēn chóng xiū shōu fèi biāo zhǔn duō shǎo， yī mén wán zhěng kè chéng yī gòng jǐ xué fēn？','Học phí học lại tính theo mỗi tín chỉ là bao nhiêu, và môn học này có tổng cộng bao nhiêu tín chỉ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_06','V824','教务老师',6,'每学分一百元，本课程四学分，一次性缴纳四百元重修费。','měi xué fēn yì bǎi yuán， běn kè chéng sì xué fēn， yí cì xìng jiǎo nà sì bǎi yuán chóng xiū fèi。','Mỗi tín chỉ là một trăm tệ, môn này có bốn tín chỉ, nên em phải đóng một lần bốn trăm tệ học phí học lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_07','V824','阮明',7,'我记下选课时间，下一学期按时报名重修认真学习。','wǒ jì xià xuǎn kè shí jiān， xià yī xué qī àn shí bào míng chóng xiū rèn zhēn xué xí。','Em sẽ ghi nhớ thời gian đăng ký môn học, đến học kỳ sau đăng ký học lại đúng hạn và học nghiêm túc ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT825','SHT3','询问考场允许携带的文具，禁止带入物品清单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V825','SIT825','P1','suon_se','ban_chinh_thuc',NULL,'国内标准化考场严格管控随身物品，电子设备、纸质资料一律禁止带入，草稿纸统一发放回收。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_01','V825','阮明',1,'老师，期末考场允许携带哪些文具，有物品禁止带入考场吗？','lǎo shī， qī mò kǎo chǎng yǔn xǔ xié dài nǎ xiē wén jù， yǒu wù pǐn jìn zhǐ dài rù kǎo chǎng ma？','Thầy ơi, phòng thi cuối kỳ cho mang những dụng cụ học tập nào, có vật gì bị cấm mang vào phòng thi không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_02','V825','李老师',2,'黑色签字笔、2B铅笔、橡皮、直尺可带入；手机、课本、草稿纸全部禁止哦。','hēi sè qiān zì bǐ、2B qiān bǐ、 xiàng pí、 zhí chǐ kě dài rù； shǒu jī、 kè běn、 cǎo gǎo zhǐ quán bù jìn zhǐ ó。','Bút bi mực đen, bút chì 2B, cục tẩy, thước kẻ thì được mang vào; còn điện thoại, sách giáo khoa, giấy nháp thì đều bị cấm hết đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_03','V825','阮明',3,'透明文件袋装文具可以，彩色帆布文具袋会不会不让带进考场？','tòu míng wén jiàn dài zhuāng wén jù kě yǐ， cǎi sè fān bù wén jù dài huì bú huì bù ràng dài jìn kǎo chǎng？','Đựng dụng cụ trong túi hồ sơ trong suốt thì được, còn túi vải bạt nhiều màu thì có bị cấm mang vào phòng thi không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_04','V825','李老师',4,'建议透明无图案文具袋，方便监考老师快速检查袋内物品。','jiàn yì tòu míng wú tú àn wén jù dài， fāng biàn jiān kǎo lǎo shī kuài sù jiǎn chá dài nèi wù pǐn。','Thầy khuyên em nên dùng túi đựng bút trong suốt, không họa tiết, để giám thị dễ kiểm tra đồ bên trong hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_05','V825','阮明',5,'考场会统一发放草稿纸，不需要自己携带白纸对吧？','kǎo chǎng huì tǒng yī fā fàng cǎo gǎo zhǐ， bù xū yào zì jǐ xié dài bái zhǐ duì ba？','Phòng thi sẽ phát giấy nháp chung, nên không cần tự mang giấy trắng theo đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_06','V825','李老师',6,'每场考试统一分发草稿纸，离场全部回收不允许带出考场。','měi chǎng kǎo shì tǒng yī fēn fā cǎo gǎo zhǐ， lí chǎng quán bù huí shōu bù yǔn xǔ dài chū kǎo chǎng。','Mỗi buổi thi đều phát giấy nháp chung, khi ra khỏi phòng phải nộp lại hết, không được mang ra ngoài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_07','V825','阮明',7,'我只准备规定文具，不带任何禁止物品进入考场。','wǒ zhǐ zhǔn bèi guī dìng wén jù， bù dài rèn hé jìn zhǐ wù pǐn jìn rù kǎo chǎng。','Em chỉ chuẩn bị đúng những dụng cụ được quy định thôi, không mang bất kỳ vật gì bị cấm vào phòng thi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT826','SHT3','复习资料丢失，找同学拷贝完整复习提纲',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V826','SIT826','P1','twist','tuy_y',NULL,'老师内部复习提纲属于班级专属学习材料，一般不允许跨班级大范围转发。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_01','V826','阮明',1,'我存复习提纲的U盘弄丢了，能不能把你的全套复习资料发我一份？','wǒ cún fù xí tí gāng de U pán nòng diū le， néng bù néng bǎ nǐ de quán tào fù xí zī liào fā wǒ yī fèn？','Tớ làm mất cái USB lưu đề cương ôn tập rồi, cậu gửi cho tớ trọn bộ tài liệu ôn của cậu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_02','V826','苏雯',2,'可以全部打包发给你，但是提纲内老师标注的内部例题不能转发给其他班级。','kě yǐ quán bù dǎ bāo fā gěi nǐ， dàn shì tí gāng nèi lǎo shī biāo zhù de nèi bù lì tí bù néng zhuǎn fā gěi qí tā bān jí。','Được, tớ gói hết gửi cho cậu, nhưng mấy bài ví dụ nội bộ mà thầy cô đánh dấu trong đề cương thì không được chuyển cho lớp khác nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_03','V826','阮明',3,'我只自己复习，绝不外传资料，这点你放心。','wǒ zhǐ zì jǐ fù xí， jué bù wài chuán zī liào， zhè diǎn nǐ fàng xīn。','Tớ chỉ tự ôn thôi, tuyệt đối không phát tán ra ngoài đâu, cậu cứ yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_04','V826','苏雯',4,'文件很大，微信传输容易卡顿，我分享网盘链接给你下载嘛。','wén jiàn hěn dà， wēi xìn chuán shū róng yì kǎ dùn， wǒ fēn xiǎng wǎng pán liàn jiē gěi nǐ xià zài ma。','File nặng lắm, gửi qua WeChat dễ bị đơ, để tớ chia sẻ link ổ đĩa mạng cho cậu tải nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_05','V826','阮明',5,'网盘下载完我立刻核对章节，补齐丢失的背诵提纲。','wǎng pán xià zài wán wǒ lì kè hé duì zhāng jié， bǔ qí diū shī de bèi sòng tí gāng。','Tải xong ở ổ đĩa mạng là tớ đối chiếu ngay từng chương, bổ sung lại phần đề cương học thuộc bị mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_06','V826','苏雯',6,'提纲划了必考背诵点，优先背诵标红大题内容。','tí gāng huà le bì kǎo bèi sòng diǎn， yōu xiān bèi sòng biāo hóng dà tí nèi róng。','Trong đề cương tớ đã đánh dấu mấy điểm chắc chắn thi rồi, cậu ưu tiên học thuộc mấy câu tô đỏ trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_07','V826','阮明',7,'太感谢，丢失资料差点耽误期末复习进度。','tài gǎn xiè， diū shī zī liào chà diǎn dān wù qī mò fù xí jìn dù。','Cảm ơn cậu nhiều lắm, suýt nữa mất tài liệu là trễ hết tiến độ ôn thi cuối kỳ của tớ rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT827','SHT4','咨询平时分过低，期末卷面需要多少分才能及格',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V827','SIT827','P1','suon_se','ban_chinh_thuc',NULL,'总评分数按固定比例加权计算，平时分偏低时需要更高期末卷面分数才能及格。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_01','V827','阮明',1,'老师，我出勤分、课堂小测得分不高，想问问期末卷面最低多少能总评及格。','lǎo shī， wǒ chū qín fēn、 kè táng xiǎo cè dé fēn bù gāo， xiǎng wèn wèn qī mò juàn miàn zuì dī duō shǎo néng zǒng píng jí gé。','Thầy ơi, điểm chuyên cần và điểm kiểm tra trên lớp của em không cao, em muốn hỏi điểm thi cuối kỳ tối thiểu bao nhiêu thì tổng kết mới đạt ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_02','V827','李老师',2,'平时分目前只有12分，期末试卷至少考76分，总评才能达到60分及格线。','píng shí fēn mù qián zhǐ yǒu 12 fēn， qī mò shì juàn zhì shǎo kǎo 76 fēn， zǒng píng cái néng dá dào 60 fēn jí gé xiàn。','Điểm quá trình của em hiện chỉ có 12 điểm, nên bài thi cuối kỳ phải đạt ít nhất 76 điểm thì tổng kết mới đạt mốc 60 điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_03','V827','阮明',3,'试卷满分一百分，76分难度偏高，我需要重点背诵全部大题吗？','shì juàn mǎn fēn yì bǎi fēn，76 fēn nán dù piān gāo， wǒ xū yào zhòng diǎn bèi sòng quán bù dà tí ma？','Đề thi tổng 100 điểm, mà 76 điểm thì hơi cao, vậy em có cần học thuộc trọng tâm hết các câu lớn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_04','V827','李老师',4,'论述、简答分值占比高，抓住大题就能拉高卷面总分。','lùn shù、 jiǎn dá fēn zhí zhàn bǐ gāo， zhuā zhù dà tí jiù néng lā gāo juàn miàn zǒng fēn。','Phần luận và trả lời ngắn chiếm điểm nhiều, em nắm chắc các câu lớn là kéo được tổng điểm bài thi lên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_05','V827','阮明',5,'选择题分值低，复习时可以适当减少选择背诵时间？','xuǎn zé tí fēn zhí dī， fù xí shí kě yǐ shì dàng jiǎn shǎo xuǎn zé bèi sòng shí jiān？','Câu trắc nghiệm chiếm điểm ít, vậy khi ôn em có thể giảm bớt thời gian học phần trắc nghiệm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_06','V827','李老师',6,'选择保证基础分，大题尽量拿满，平衡分配复习精力。','xuǎn zé bǎo zhèng jī chǔ fēn， dà tí jǐn liàng ná mǎn， píng héng fēn pèi fù xí jīng lì。','Trắc nghiệm thì cứ đảm bảo điểm cơ bản, còn câu lớn thì cố gắng lấy trọn điểm, phân bổ sức ôn tập cho cân đối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_07','V827','阮明',7,'我重点攻克主观大题，争取期末卷面达标顺利及格。','wǒ zhòng diǎn gōng kè zhǔ guān dà tí， zhēng qǔ qī mò juàn miàn dá biāo shùn lì jí gé。','Em sẽ tập trung chinh phục các câu tự luận lớn, cố gắng để bài thi cuối kỳ đạt chuẩn và qua môn thuận lợi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT828','SHT4','选课系统卡顿抢不到心仪选修课，咨询教务调剂方案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V828','SIT828','P1','twist','ban_chinh_thuc',NULL,'高校选修课名额有限，首轮选满只能等待学生退课产生空位，无人工扩容插队渠道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_01','V828','阮明',1,'老师，线上选课系统卡顿，我心仪的汉语文化选修课已经选满关闭。','lǎo shī， xiàn shàng xuǎn kè xì tǒng kǎ dùn， wǒ xīn yí de hàn yǔ wén huà xuǎn xiū kè yǐ jīng xuǎn mǎn guān bì。','Thầy ơi, hệ thống đăng ký môn học trực tuyến bị đơ, môn tự chọn văn hóa Hán ngữ mà em thích đã đủ chỉ tiêu và đóng đăng ký mất rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_02','V828','教务老师',2,'首轮选课结束后有一轮补选调剂通道，三天后系统重新开放空位。','shǒu lún xuǎn kè jié shù hòu yǒu yī lún bǔ xuǎn diào jì tōng dào， sān tiān hòu xì tǒng chóng xīn kāi fàng kōng wèi。','Sau khi đợt đăng ký đầu tiên kết thúc sẽ có một đợt đăng ký bổ sung, ba ngày sau hệ thống sẽ mở lại các suất trống.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_03','V828','阮明',3,'补选通道是随机释放退课空位，还是可以人工登记插队？','bǔ xuǎn tōng dào shì suí jī shì fàng tuì kè kòng wèi， hái shì kě yǐ rén gōng dēng jì chā duì？','Đợt đăng ký bổ sung là các suất trống sẽ được giải phóng ngẫu nhiên khi có người rút môn, hay có thể đăng ký thủ công để xếp trước ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_04','V828','教务老师',4,'无人工插队登记，只能等待其他学生退课后系统自动释放名额嘛。','wú rén gōng chā duì dēng jì， zhǐ néng děng dài qí tā xué shēng tuì kè hòu xì tǒng zì dòng shì fàng míng é ma。','Không có chuyện đăng ký thủ công để xếp trước đâu, chỉ có thể chờ sinh viên khác rút môn rồi hệ thống tự động giải phóng suất thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_05','V828','阮明',5,'如果补选依旧抢不到，有没有同类型替代选修课推荐？','rú guǒ bǔ xuǎn yī jiù qiǎng bú dào， yǒu méi yǒu tóng lèi xíng tì dài xuǎn xiū kè tuī jiàn？','Nếu đợt bổ sung vẫn không giành được suất, thầy có môn tự chọn nào cùng loại để thay thế không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_06','V828','教务老师',6,'有两门民俗类选修课内容相近，难度、学分完全一致。','yǒu liǎng mén mín sú lèi xuǎn xiū kè nèi róng xiāng jìn， nán dù、 xué fēn wán quán yí zhì。','Có hai môn tự chọn về văn hóa dân gian nội dung khá tương tự, độ khó và số tín chỉ hoàn toàn như nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_07','V828','阮明',7,'三天后准时登录系统补选，备选同步勾选民俗课程。','sān tiān hòu zhǔn shí dēng lù xì tǒng bǔ xuǎn， bèi xuǎn tóng bù gōu xuǎn mín sú kè chéng。','Ba ngày sau em sẽ đăng nhập hệ thống đúng giờ để đăng ký bổ sung, đồng thời chọn luôn môn văn hóa dân gian làm phương án dự phòng ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT829','SHT4','选错课程，咨询退课截止时间、退课学分规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V829','SIT829','P1','suon_se','ban_chinh_thuc',NULL,'开学初期设有免费退课窗口期，窗口期外放弃课程会判定弃考挂科，影响学籍学分记录。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_01','V829','阮明',1,'老师，我选课误选高阶汉语课程，自身基础跟不上，想办理退课。','lǎo shī， wǒ xuǎn kè wù xuǎn gāo jiē hàn yǔ kè chéng， zì shēn jī chǔ gēn bù shàng， xiǎng bàn lǐ tuì kè。','Thầy ơi, em đăng ký nhầm môn Hán ngữ nâng cao, nền tảng của em không theo kịp nên em muốn xin rút môn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_02','V829','教务老师',2,'开学第二周周五是免费退课截止日，退课后学分不计入本学期修读记录。','kāi xué dì èr zhōu zhōu wǔ shì miǎn fèi tuì kè jié zhǐ rì， tuì kè hòu xué fēn bù jì rù běn xué qī xiū dú jì lù。','Thứ Sáu tuần thứ hai của học kỳ mới là hạn chót rút môn miễn phí, sau khi rút thì tín chỉ đó sẽ không được tính vào bảng điểm học kỳ này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_03','V829','阮明',3,'超过截止日期再退课，会标记课程挂科记录在学籍系统吗？','chāo guò jié zhǐ rì qī zài tuì kè， huì biāo jì kè chéng guà kē jì lù zài xué jí xì tǒng ma？','Nếu quá hạn mới rút môn thì hệ thống học vụ có ghi nhận đó là rớt môn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_04','V829','教务老师',4,'逾期退课按弃考处理，直接记挂科，需要后续重修缴费。','yú qī tuì kè àn qì kǎo chǔ lǐ， zhí jiē jì guà kē， xū yào hòu xù chóng xiū jiǎo fèi。','Rút môn sau hạn sẽ bị xử lý như bỏ thi, ghi thẳng là rớt môn, sau này phải đăng ký học lại và đóng phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_05','V829','阮明',5,'今天周二，我现在线上提交退课申请，来得及免费撤销课程。','jīn tiān zhōu èr， wǒ xiàn zài xiàn shàng tí jiāo tuì kè shēn qǐng， lái de jí miǎn fèi chè xiāo kè chéng。','Hôm nay là thứ Ba, em nộp đơn xin rút môn trực tuyến ngay bây giờ là vẫn kịp hủy môn miễn phí ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_06','V829','教务老师',6,'线上申请提交后一小时内系统自动审核完成退课。','xiàn shàng shēn qǐng tí jiāo hòu yī xiǎo shí nèi xì tǒng zì dòng shěn hé wán chéng tuì kè。','Sau khi nộp đơn trực tuyến, trong vòng một tiếng hệ thống sẽ tự động duyệt và hoàn tất việc rút môn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_07','V829','阮明',7,'我立刻操作退课，重新选择适配我水平的基础选修课。','wǒ lì kè cāo zuò tuì kè， chóng xīn xuǎn zé shì pèi wǒ shuǐ píng de jī chǔ xuǎn xiū kè。','Em sẽ làm thủ tục rút môn ngay, rồi chọn lại môn tự chọn cơ bản phù hợp hơn với trình độ của mình ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT830','SHT4','申请开具在校在读证明用于签证、实习',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V830','SIT830','P1','suon_se','chinh_thuc',NULL,'学院加盖公章的在读证明属于官方学籍凭证，出入境、企业实习均认可其法律效力，复印件无公章无效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_01','V830','阮明',1,'老师，我需要官方在校在读证明，用于续签居留许可和校外实习备案。','lǎo shī， wǒ xū yào guān fāng zài xiào zài dú zhèng míng， yòng yú xù qiān jū liú xǔ kě hé xiào wài shí xí bèi àn。','Thưa thầy/cô, em cần giấy xác nhận đang học chính thức của nhà trường để gia hạn giấy phép cư trú và đăng ký thực tập ngoài trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_02','V830','教务老师',2,'填写纸质申请表，携带护照、学生证，当场打印加盖学院公章哦。','tián xiě zhǐ zhì shēn qǐng biǎo， xié dài hù zhào、 xué shēng zhèng， dāng chǎng dǎ yìn jiā gài xué yuàn gōng zhāng ó。','Em điền vào mẫu đơn giấy, mang theo hộ chiếu và thẻ sinh viên, giấy xác nhận sẽ được in và đóng dấu của khoa ngay tại chỗ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_03','V830','阮明',3,'证明可以一次性打印两份，签证、实习分开使用吗？','zhèng míng kě yǐ yí cì xìng dǎ yìn liǎng fèn， qiān zhèng、 shí xí fēn kāi shǐ yòng ma？','Giấy xác nhận có thể in một lần hai bản để dùng riêng cho visa và thực tập không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_04','V830','教务老师',4,'无份数限制，需要几份直接说明，全部同步盖章生效。','wú fèn shù xiàn zhì， xū yào jǐ fèn zhí jiē shuō míng， quán bù tóng bù gài zhāng shēng xiào。','Không giới hạn số bản, cần bao nhiêu bản em cứ nói, tất cả đều được đóng dấu có hiệu lực cùng lúc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_05','V830','阮明',5,'在读证明开具完成，当天就能直接拿去出入境大厅办理签证？','zài dú zhèng míng kāi jù wán chéng， dàng tiān jiù néng zhí jiē ná qù chū rù jìng dà tīng bàn lǐ qiān zhèng？','Giấy xác nhận đang học làm xong là ngay trong ngày em có thể mang đến phòng xuất nhập cảnh để làm visa luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_06','V830','教务老师',6,'盖红色公章的原件具备官方效力，可直接用于签证、实习备案。','gài hóng sè gōng zhāng de yuán jiàn jù bèi guān fāng xiào lì， kě zhí jiē yòng yú qiān zhèng、 shí xí bèi àn。','Bản gốc có đóng dấu đỏ chính thức thì có giá trị pháp lý, có thể dùng trực tiếp để làm visa hoặc đăng ký thực tập.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_07','V830','阮明',7,'我填好申请表，现在提交办理两份在读证明。','wǒ tián hǎo shēn qǐng biǎo， xiàn zài tí jiāo bàn lǐ liǎng fèn zài dú zhèng míng。','Em đã điền xong mẫu đơn, giờ em nộp để xin làm hai bản giấy xác nhận đang học ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT831','SHT4','咨询学分修读进度，还差多少学分满足毕业要求',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V831','SIT831','P1','twist','chinh_thuc',NULL,'本科有硬性毕业总学分底线，综测竞赛加分仅用于评优，不能抵扣必修、选修毕业学分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_01','V831','阮明',1,'老师，想核对我已修学分总数，还差多少学分才能达标毕业。','lǎo shī， xiǎng hé duì wǒ yǐ xiū xué fēn zǒng shù， hái chà duō shǎo xué fēn cái néng dá biāo bì yè。','Thưa thầy/cô, em muốn kiểm tra lại tổng số tín chỉ đã học, xem còn thiếu bao nhiêu tín chỉ nữa mới đủ điều kiện tốt nghiệp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_02','V831','教务老师',2,'毕业总学分要求140分，你目前只修满112分，还差28学分。','bì yè zǒng xué fēn yāo qiú 140 fēn， nǐ mù qián zhǐ xiū mǎn 112 fēn， hái chà 28 xué fēn。','Tổng số tín chỉ yêu cầu để tốt nghiệp là 140, hiện em mới tích lũy được 112, còn thiếu 28 tín chỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_03','V831','阮明',3,'剩余学分只能靠专业课、选修课补齐，没有其他加分渠道吗？','shèng yú xué fēn zhǐ néng kào zhuān yè kè、 xuǎn xiū kè bǔ qí， méi yǒu qí tā jiā fēn qú dào ma？','Số tín chỉ còn thiếu chỉ có thể bù bằng các môn chuyên ngành và môn tự chọn thôi ạ, không còn kênh cộng điểm nào khác sao ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_04','V831','教务老师',4,'竞赛、论文综测加分不抵扣毕业学分，仅用于奖学金评选嘛。','jìng sài、 lùn wén zōng cè jiā fēn bù dǐ kòu bì yè xué fēn， jǐn yòng yú jiǎng xué jīn píng xuǎn ma。','Điểm cộng từ các cuộc thi hay bài luận đánh giá tổng hợp không được quy đổi thành tín chỉ tốt nghiệp đâu, chỉ dùng để xét học bổng thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_05','V831','阮明',5,'剩余两个学期，平均每学期需要修十四分才能按时毕业？','shèng yú liǎng gè xué qī， píng jūn měi xué qī xū yào xiū shí sì fēn cái néng àn shí bì yè？','Vậy còn hai học kỳ nữa, trung bình mỗi kỳ em phải học đủ mười bốn tín chỉ mới tốt nghiệp đúng hạn được ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_06','V831','教务老师',6,'没错，每学期至少七门课程，不能大量少选学分课。','méi cuò， měi xué qī zhì shǎo qī mén kè chéng， bù néng dà liàng shǎo xuǎn xué fēn kè。','Đúng vậy, mỗi học kỳ ít nhất phải đăng ký bảy môn, không được đăng ký quá ít tín chỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_07','V831','阮明',7,'我之后每学期足额选课，保证按期修满毕业学分。','wǒ zhī hòu měi xué qī zú é xuǎn kè， bǎo zhèng àn qī xiū mǎn bì yè xué fēn。','Vậy từ giờ mỗi kỳ em sẽ đăng ký đủ số tín chỉ, đảm bảo hoàn thành đúng tiến độ tốt nghiệp ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT832','SHT4','咨询辅修专业报名条件、额外课时安排',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V832','SIT832','P1','suon_se','ban_chinh_thuc',NULL,'国内高校辅修专业面向成绩合格无挂科学生开设，授课集中周末，完成后发放独立辅修证明。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_01','V832','阮明',1,'老师，想报名外贸辅修专业，请问报名基础条件有哪些？','lǎo shī， xiǎng bào míng wài mào fǔ xiū zhuān yè， qǐng wèn bào míng jī chǔ tiáo jiàn yǒu nǎ xiē？','Thầy/cô ơi, em muốn đăng ký ngành phụ ngoại thương, cho em hỏi điều kiện đăng ký cơ bản là gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_02','V832','教务老师',2,'本专业平均分70分以上，无挂科记录，大二可提交辅修申请。','běn zhuān yè píng jūn fēn 70 fēn yǐ shàng， wú guà kē jì lù， dà èr kě tí jiāo fǔ xiū shēn qǐng。','Điểm trung bình chuyên ngành chính từ 70 trở lên, không có môn nào bị nợ, lên năm hai là có thể nộp đơn đăng ký học ngành phụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_03','V832','阮明',3,'辅修课程全部安排在周末，会不会和本专业课程冲突？','fǔ xiū kè chéng quán bù ān pái zài zhōu mò， huì bú huì hé běn zhuān yè kè chéng chōng tū？','Các môn ngành phụ đều xếp vào cuối tuần, vậy có bị trùng với lịch học chuyên ngành chính không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_04','V832','教务老师',4,'辅修统一周六全天授课，工作日无额外课时，不会冲突主修课。','fǔ xiū tǒng yī zhōu liù quán tiān shòu kè， gōng zuò rì wú é wài kè shí， bú huì chōng tū zhǔ xiū kè。','Ngành phụ học cố định cả ngày thứ Bảy, ngày thường không phát sinh thêm giờ học nên sẽ không trùng với môn chính đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_05','V832','阮明',5,'辅修完成后发放辅修证书，证书和主修毕业证一同发放吗？','fǔ xiū wán chéng hòu fā fàng fǔ xiū zhèng shū， zhèng shū hé zhǔ xiū bì yè zhèng yī tóng fā fàng ma？','Sau khi hoàn thành ngành phụ sẽ được cấp chứng chỉ, chứng chỉ này phát cùng lúc với bằng tốt nghiệp chính không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_06','V832','教务老师',6,'毕业时同步发放辅修结业证明，求职可作为专业补充凭证。','bì yè shí tóng bù fā fàng fǔ xiū jié yè zhèng míng， qiú zhí kě zuò wéi zhuān yè bǔ chōng píng zhèng。','Đến lúc tốt nghiệp sẽ cấp kèm giấy chứng nhận hoàn thành ngành phụ, có thể dùng làm giấy tờ bổ trợ chuyên môn khi xin việc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_07','V832','阮明',7,'我本学期稳住平均分，下学期申请报名外贸辅修。','wǒ běn xué qī wěn zhù píng jūn fēn， xià xué qī shēn qǐng bào míng wài mào fǔ xiū。','Vậy học kỳ này em sẽ giữ vững điểm trung bình, kỳ sau nộp đơn đăng ký ngành phụ ngoại thương.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT833','SHT4','教务系统个人信息拼音拼写错误，申请更正学籍信息',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V833','SIT833','P1','twist','chinh_thuc',NULL,'学籍姓名、国籍、证件号属于锁定核心信息，学生无法线上自行修改，必须线下提交证件佐证人工更正。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_01','V833','阮明',1,'老师，教务系统里我的姓名拼音拼写错误，和护照不一致影响办签证。','lǎo shī， jiào wù xì tǒng lǐ wǒ de xìng míng pīn yīn pīn xiě cuò wù， hé hù zhào bù yī zhì yǐng xiǎng bàn qiān zhèng。','Thưa thầy/cô, tên em bị viết sai phiên âm trên hệ thống giáo vụ, không khớp với hộ chiếu nên ảnh hưởng đến việc xin visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_02','V833','教务老师',2,'填写学籍信息变更申请表，附上护照原件复印件佐证正确拼写。','tián xiě xué jí xìn xī biàn gēng shēn qǐng biǎo， fù shàng hù zhào yuán jiàn fù yìn jiàn zuǒ zhèng zhèng què pīn xiě。','Em điền vào mẫu đơn xin thay đổi thông tin học tịch, kèm theo bản photo hộ chiếu gốc để đối chiếu cách viết đúng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_03','V833','阮明',3,'线上系统不能自行修改，必须线下纸质申请人工后台更正嘛。','xiàn shàng xì tǒng bù néng zì xíng xiū gǎi， bì xū xiàn xià zhǐ zhì shēn qǐng rén gōng hòu tái gēng zhèng ma。','Hệ thống online không thể tự chỉnh sửa được, bắt buộc phải nộp đơn giấy trực tiếp để được sửa thủ công phía sau hệ thống ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_04','V833','教务老师',4,'学籍核心姓名属于锁定信息，仅教务管理员有权限后台修改。','xué jí hé xīn xìng míng shǔ yú suǒ dìng xìn xī， jǐn jiào wù guǎn lǐ yuán yǒu quán xiàn hòu tái xiū gǎi。','Thông tin tên trong học tịch thuộc dữ liệu bị khóa, chỉ quản trị viên giáo vụ mới có quyền chỉnh sửa trên hệ thống thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_05','V833','阮明',5,'提交申请表之后，多久能同步更新全校教务系统信息？','tí jiāo shēn qǐng biǎo zhī hòu， duō jiǔ néng tóng bù gēng xīn quán xiào jiào wù xì tǒng xìn xī？','Sau khi nộp đơn, mất bao lâu thì thông tin sẽ được cập nhật đồng bộ trên toàn bộ hệ thống giáo vụ của trường ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_06','V833','教务老师',6,'三个工作日内完成修改，更新后打印成绩单姓名同步更正。','sān gè gōng zuò rì nèi wán chéng xiū gǎi， gēng xīn hòu dǎ yìn chéng jì dān xìng míng tóng bù gēng zhèng。','Trong vòng ba ngày làm việc sẽ hoàn tất chỉnh sửa, sau khi cập nhật thì tên trên bảng điểm in ra cũng sẽ được sửa đồng bộ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_07','V833','阮明',7,'我带好护照复印件，今天提交信息变更申请表。','wǒ dài hǎo hù zhào fù yìn jiàn， jīn tiān tí jiāo xìn xī biàn gēng shēn qǐng biǎo。','Vậy em sẽ mang theo bản photo hộ chiếu, nộp đơn xin thay đổi thông tin ngay hôm nay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT834','SHT5','打印官方成绩单用于升学，咨询打印盖章流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V834','SIT834','P1','suon_se','ban_chinh_thuc',NULL,'境外升学、签证使用的成绩单必须校内官方纸质打印+鲜红公章，自行截图打印无法律效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_01','V834','阮明',1,'老师，我准备升学深造，需要多份加盖公章的官方成绩单。','lǎo shī， wǒ zhǔn bèi shēng xué shēn zào， xū yào duō fèn jiā gài gōng zhāng de guān fāng chéng jì dān。','Thầy/cô ơi, em chuẩn bị học lên cao hơn nên cần vài bản bảng điểm chính thức có đóng dấu mộc ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_02','V834','教务老师',2,'线上系统预约打印，预约完成携带学生证线下领取盖章成绩单哦。','xiàn shàng xì tǒng yù yuē dǎ yìn， yù yuē wán chéng xié dài xué shēng zhèng xiàn xià lǐng qǔ gài zhāng chéng jì dān ó。','Em đặt lịch in trên hệ thống online, sau khi đặt xong thì mang thẻ sinh viên đến nhận bảng điểm đã đóng dấu trực tiếp nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_03','V834','阮明',3,'电子版成绩单截图自行打印，能不能加盖学院公章？','diàn zi bǎn chéng jì dān jié tú zì xíng dǎ yìn， néng bù néng jiā gài xué yuàn gōng zhāng？','Nếu em tự chụp màn hình bảng điểm điện tử rồi tự in ra thì có được đóng dấu của khoa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_04','V834','教务老师',4,'仅校内打印机输出的官方纸质成绩单可盖章，自行打印截图无效。','jǐn xiào nèi dǎ yìn jī shū chū de guān fāng zhǐ zhì chéng jì dān kě gài zhāng， zì xíng dǎ yìn jié tú wú xiào。','Chỉ những bảng điểm chính thức in từ máy in trong trường mới được đóng dấu, ảnh chụp màn hình tự in ra sẽ không có giá trị đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_05','V834','阮明',5,'一次最多能打印五份，每份都单独加盖红色公章吗？','yī cì zuì duō néng dǎ yìn wǔ fèn， měi fèn dōu dān dú jiā gài hóng sè gōng zhāng ma？','Một lần được in tối đa năm bản, mỗi bản đều được đóng dấu đỏ riêng lẻ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_06','V834','教务老师',6,'每份独立盖章，全部具备同等官方效力用于境外升学。','měi fèn dú lì gài zhāng， quán bù jù bèi tóng děng guān fāng xiào lì yòng yú jìng wài shēng xué。','Mỗi bản đều được đóng dấu riêng, tất cả đều có giá trị pháp lý như nhau để dùng cho việc học tiếp ở nước ngoài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_07','V834','阮明',7,'我线上预约打印五份成绩单，下午来办公室领取。','wǒ xiàn shàng yù yuē dǎ yìn wǔ fèn chéng jì dān， xià wǔ lái bàn gōng shì lǐng qǔ。','Vậy em sẽ đặt lịch in năm bản bảng điểm online, chiều nay ghé văn phòng nhận ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT835','SHT5','报名校内汉语辅导小班，咨询上课时段、收费标准',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V835','SIT835','P1','suon_se','ban_chinh_thuc',NULL,'校内留学生汉语辅导小班收费低廉，仅收取教材耗材费，用于针对性提升口语、听力薄弱学生。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_01','V835','阮明',1,'老师，我的汉语口语薄弱，想报名校内留学生汉语辅导小班。','lǎo shī， wǒ de hàn yǔ kǒu yǔ bó ruò， xiǎng bào míng xiào nèi liú xué shēng hàn yǔ fǔ dǎo xiǎo bān。','Thầy/cô ơi, khả năng nói tiếng Trung của em còn yếu, em muốn đăng ký lớp phụ đạo tiếng Trung nhỏ dành cho lưu học sinh trong trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_02','V835','辅导老师',2,'小班每周二、四傍晚两节课，一学期统一收取两百元辅导耗材费。','xiǎo bān měi zhōu èr、 sì bàng wǎn liǎng jié kè， yī xué qī tǒng yī shōu qǔ liǎng bǎi yuán fǔ dǎo hào cái fèi。','Lớp học vào chiều tối thứ Ba và thứ Năm hàng tuần, mỗi học kỳ thu chung 200 tệ tiền tài liệu học tập nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_03','V835','阮明',3,'班级人数多少，能保证每个人都有开口练习的机会吗？','bān jí rén shù duō shǎo， néng bǎo zhèng měi gè rén dōu yǒu kāi kǒu liàn xí de jī huì ma？','Mỗi lớp có bao nhiêu học viên ạ, có đảm bảo ai cũng có cơ hội được luyện nói không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_04','V835','辅导老师',4,'每班不超过十人，每节课轮流上台对话练习纠正发音。','měi bān bù chāo guò shí rén， měi jié kè lún liú shàng tái duì huà liàn xí jiū zhèng fā yīn。','Mỗi lớp không quá mười người, mỗi buổi học sẽ luân phiên lên thực hành hội thoại để chỉnh phát âm cho từng người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_05','V835','阮明',5,'零基础、中级、高级分班，我需要先参加分班测试吗？','líng jī chǔ、 zhōng jí、 gāo jí fēn bān， wǒ xū yào xiān cān jiā fēn bān cè shì ma？','Lớp có chia trình độ sơ cấp, trung cấp, cao cấp, vậy em có cần làm bài kiểm tra phân lớp trước không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_06','V835','辅导老师',6,'入学简单口语测试，匹配对应难度班级再缴费报名。','rù xué jiǎn dān kǒu yǔ cè shì， pǐ pèi duì yìng nán dù bān jí zài jiǎo fèi bào míng。','Có bài kiểm tra nói đơn giản khi nhập học, dựa vào đó xếp vào lớp phù hợp rồi mới đóng tiền đăng ký nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_07','V835','阮明',7,'我今天完成分班测试，合适就报名本学期汉语辅导小班。','wǒ jīn tiān wán chéng fèn bān cè shì， hé shì jiù bào míng běn xué qī hàn yǔ fǔ dǎo xiǎo bān。','Vậy hôm nay em sẽ làm bài kiểm tra phân lớp, nếu phù hợp thì đăng ký lớp phụ đạo tiếng Trung học kỳ này luôn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT836','SHT5','图书馆自习被隔壁同学交谈打扰，找管理员协调安静区域',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V836','SIT836','P1','twist','ban_chinh_thuc',NULL,'图书馆分静音自习区、小组研讨室，交谈讨论必须在专用研讨室，阅览区全程保持安静。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_01','V836','阮明',1,'您好，隔壁座位两位同学持续交谈，严重干扰周边自习同学复习。','nín hǎo， gé bì zuò wèi liǎng wèi tóng xué chí xù jiāo tán， yán zhòng gān rǎo zhōu biān zì xí tóng xué fù xí。','Chào anh/chị, hai bạn ngồi cạnh bên cứ nói chuyện liên tục, làm ảnh hưởng nghiêm trọng đến các bạn xung quanh đang ôn bài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_02','V836','管理员',2,'图书馆阅览区禁止大声交谈，我过去提醒两位同学保持安静。','tú shū guǎn yuè lǎn qū jìn zhǐ dà shēng jiāo tán， wǒ guò qù tí xǐng liǎng wèi tóng xué bǎo chí ān jìng。','Khu đọc sách của thư viện không cho phép nói chuyện lớn tiếng, tôi sẽ qua nhắc nhở hai bạn đó giữ trật tự nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_03','V836','阮明',3,'如果他们需要小组讨论，有没有专门的讨论室可以转移过去？','rú guǒ tā men xū yào xiǎo zǔ tǎo lùn， yǒu méi yǒu zhuān mén de tǎo lùn shì kě yǐ zhuǎn yí guò qù？','Nếu các bạn đó cần thảo luận nhóm thì có phòng thảo luận riêng để chuyển sang đó không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_04','V836','管理员',4,'一楼设有独立小组研讨室，交谈类学习活动统一安排在研讨室嘛。','yī lóu shè yǒu dú lì xiǎo zǔ yán tǎo shì， jiāo tán lèi xué xí huó dòng tǒng yī ān pái zài yán tǎo shì ma。','Tầng một có phòng thảo luận nhóm riêng, các hoạt động học tập cần trao đổi đều được sắp xếp vào phòng đó cả.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_05','V836','阮明',5,'我想要全程安静无交谈的区域，能不能调整我的自习座位？','wǒ xiǎng yào quán chéng ān jìng wú jiāo tán de qū yù， néng bù néng tiáo zhěng wǒ de zì xí zuò wèi？','Em muốn ngồi ở khu vực yên tĩnh hoàn toàn không có ai nói chuyện, có thể đổi chỗ ngồi tự học cho em được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_06','V836','管理员',6,'二楼深度自习区全程静音，我带你去空位落座不受打扰。','èr lóu shēn dù zì xí qū quán chéng jìng yīn， wǒ dài nǐ qù kòng wèi luò zuò bù shòu dǎ rǎo。','Khu tự học chuyên sâu ở tầng hai luôn giữ yên tĩnh tuyệt đối, tôi dẫn em qua đó tìm chỗ trống ngồi cho khỏi bị làm phiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_07','V836','阮明',7,'感谢协调安静自习区域，方便我专心复习期末内容。','gǎn xiè xié tiáo ān jìng zì xí qū yù， fāng biàn wǒ zhuān xīn fù xí qī mò nèi róng。','Cảm ơn anh/chị đã sắp xếp khu vực tự học yên tĩnh, giờ em có thể tập trung ôn thi cuối kỳ rồi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT837','SHT5','报名校内学术讲座，咨询签到、综测加分规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V837','SIT837','P1','suon_se','tuy_y',NULL,'国内高校综测体系包含学术讲座、竞赛加分，需全程到场完成签到流程才能录入加分记录。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_01','V837','阮明',1,'你好，我想报名本周外贸学术讲座，请问参与能综测加分吗？','nǐ hǎo， wǒ xiǎng bào míng běn zhōu wài mào xué shù jiǎng zuò， qǐng wèn cān yù néng zōng cè jiā fēn ma？','Chào anh, em muốn đăng ký buổi hội thảo học thuật ngoại thương tuần này, cho em hỏi tham gia có được cộng điểm đánh giá tổng hợp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_02','V837','干事',2,'现场签到、听完讲座提交简短心得，一次讲座加0.2综测分哦。','xiàn chǎng qiān dào、 tīng wán jiǎng zuò tí jiāo jiǎn duǎn xīn dé， yī cì jiǎng zuò jiā 0.2 zōng cè fēn ó。','Điểm danh tại chỗ, nghe xong nộp bài thu hoạch ngắn là được cộng 0,2 điểm đánh giá tổng hợp cho một buổi hội thảo đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_03','V837','阮明',3,'讲座时长两小时，中途提前离场还能正常计入加分吗？','jiǎng zuò shí cháng liǎng xiǎo shí， zhōng tú tí qián lí chǎng hái néng zhèng cháng jì rù jiā fēn ma？','Hội thảo kéo dài hai tiếng, nếu về sớm giữa chừng thì có được tính cộng điểm bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_04','V837','干事',4,'全程听完签到两次（入场、散场），中途离场不予记录加分。','quán chéng tīng wán qiān dào liǎng cì （rù chǎng、 sàn chǎng）， zhōng tú lí chǎng bù yǔ jì lù jiā fēn。','Phải nghe hết toàn bộ và điểm danh hai lần (lúc vào và lúc ra), về sớm giữa chừng sẽ không được ghi nhận cộng điểm đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_05','V837','阮明',5,'讲座名额有限，需要提前线上报名锁定席位吗？','jiǎng zuò míng é yǒu xiàn， xū yào tí qián xiàn shàng bào míng suǒ dìng xí wèi ma？','Số lượng chỗ có hạn, vậy em có cần đăng ký online trước để giữ chỗ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_06','V837','干事',6,'线上小程序提前预约，无预约现场有空位也可临时入场。','xiàn shàng xiǎo chéng xù tí qián yù yuē， wú yù yuē xiàn chǎng yǒu kòng wèi yě kě lín shí rù chǎng。','Đăng ký trước qua mini app online, nếu không đăng ký mà tại chỗ vẫn còn chỗ trống thì cũng có thể vào tạm được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_07','V837','阮明',7,'我线上预约席位，全程参与讲座完成签到拿综测加分。','wǒ xiàn shàng yù yuē xí wèi， quán chéng cān yù jiǎng zuò wán chéng qiān dào ná zōng cè jiā fēn。','Vậy em sẽ đăng ký giữ chỗ online, tham gia đầy đủ và điểm danh để lấy điểm cộng đánh giá tổng hợp ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT838','SHT5','和中国同学结成语言交换搭档，约定每周练习时段',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V838','SIT838','P1','suon_se','tuy_y',NULL,'高校留学生与本国学生结成语言交换搭档是普遍互助学习方式，双方互相教授母语，零成本提升口语能力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_01','V838','阮明',1,'我们结成语言交换搭档吧，我教你越南语，你帮我练习汉语。','wǒ men jié chéng yǔ yán jiāo huàn dā dàng ba， wǒ jiāo nǐ yuè nán yǔ， nǐ bāng wǒ liàn xí hàn yǔ。','Hay là mình kết đôi trao đổi ngôn ngữ đi, mình dạy cậu tiếng Việt, cậu giúp mình luyện tiếng Trung nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_02','V838','苏雯',2,'太好了，每周三傍晚两小时，一半时间汉语、一半越南语互换练习。','tài hǎo le， měi zhōu sān bàng wǎn liǎng xiǎo shí， yí bàn shí jiān hàn yǔ、 yí bàn yuè nán yǔ hù huàn liàn xí。','Hay quá, vậy mỗi tối thứ Tư hai tiếng, một nửa thời gian luyện tiếng Trung, một nửa luyện tiếng Việt luân phiên nhau nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_03','V838','阮明',3,'练习地点图书馆一楼研讨室，有白板方便写单词、句子讲解对吧？','liàn xí dì diǎn tú shū guǎn yī lóu yán tǎo shì， yǒu bái bǎn fāng biàn xiě dān cí、 jù zi jiǎng jiě duì ba？','Địa điểm luyện tập là phòng thảo luận tầng một thư viện, ở đó có bảng trắng để viết từ vựng, câu cú giải thích cho nhau đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_04','V838','苏雯',4,'研讨室安静，不会打扰其他人，还能书写词汇互相讲解。','yán tǎo shì ān jìng， bú huì dǎ rǎo qí tā rén， hái néng shū xiě cí huì hù xiāng jiǎng jiě。','Ừ, phòng thảo luận yên tĩnh, không làm phiền người khác, lại có thể viết từ vựng ra giải thích qua lại cho nhau nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_05','V838','阮明',5,'每次结束布置少量口语练习任务，下周见面复盘巩固。','měi cì jié shù bù zhì shǎo liàng kǒu yǔ liàn xí rèn wù， xià zhōu jiàn miàn fù pán gǒng gù。','Mỗi lần học xong mình giao một ít bài tập luyện nói, tuần sau gặp lại ôn lại cho chắc nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_06','V838','苏雯',6,'分工互补互相提升语言，长期坚持进步会很明显。','fēn gōng hù bǔ hù xiāng tí shēng yǔ yán， cháng qī jiān chí jìn bù huì hěn míng xiǎn。','Hai đứa bổ trợ cho nhau để cùng tiến bộ, kiên trì lâu dài chắc chắn sẽ thấy rõ sự tiến bộ luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_07','V838','阮明',7,'每周三固定时段见面语言交换，稳步提升双方外语水平。','měi zhōu sān gù dìng shí duàn jiàn miàn yǔ yán jiāo huàn， wěn bù tí shēng shuāng fāng wài yǔ shuǐ píng。','Vậy cố định mỗi thứ Tư hàng tuần gặp nhau trao đổi ngôn ngữ, từng bước nâng cao trình độ ngoại ngữ của cả hai nha.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT839','SHT5','咨询综测加分项目：讲座、竞赛、论文申报规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V839','SIT839','P1','suon_se','ban_chinh_thuc',NULL,'综测分数用于奖学金、评优评先，各类学术活动加分可叠加，但设置单学年加分上限。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_01','V839','阮明',1,'老师，想咨询留学生综合测评加分全部可申报项目细则。','lǎo shī， xiǎng zī xún liú xué shēng zōng hé cè píng jiā fēn quán bù kě shēn bào xiàng mù xì zé。','Thầy ơi, em muốn hỏi kỹ về các hạng mục có thể đăng ký để cộng điểm đánh giá tổng hợp cho sinh viên quốc tế ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_02','V839','教务老师',2,'分为学术讲座、学科竞赛、期刊论文、社会实践四大类加分。','fēn wéi xué shù jiǎng zuò、 xué kē jìng sài、 qī kān lùn wén、 shè huì shí jiàn sì dà lèi jiā fēn。','Chia thành bốn nhóm cộng điểm: hội thảo học thuật, thi học thuật, bài báo khoa học và thực hành xã hội.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_03','V839','阮明',3,'校级汉语竞赛拿奖，一次能加多少综测分数？','xiào jí hàn yǔ jìng sài ná jiǎng， yī cì néng jiā duō shǎo zōng cè fēn shù？','Nếu đạt giải trong cuộc thi tiếng Trung cấp trường thì được cộng bao nhiêu điểm đánh giá tổng hợp ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_04','V839','教务老师',4,'校级竞赛三等奖0.3分、二等奖0.5分、一等奖0.8分，逐级递增。','xiào jí jìng sài sān děng jiǎng 0.3 fēn、 èr děng jiǎng 0.5 fēn、 yì děng jiǎng 0.8 fēn， zhú jí dì zēng。','Giải ba cấp trường được 0,3 điểm, giải nhì 0,5 điểm, giải nhất 0,8 điểm, tăng dần theo thứ hạng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_05','V839','阮明',5,'发表普通校园期刊短文，论文加分和竞赛加分可以叠加吗？','fā biǎo pǔ tōng xiào yuán qī kān duǎn wén， lùn wén jiā fēn hé jìng sài jiā fēn kě yǐ dié jiā ma？','Nếu đăng bài viết ngắn trên tập san trường bình thường, thì điểm bài viết và điểm thi có được cộng dồn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_06','V839','教务老师',6,'全部项目加分可叠加，单学年综测加分上限两分。','quán bù xiàng mù jiā fēn kě dié jiā， dān xué nián zōng cè jiā fēn shàng xiàn liǎng fēn。','Tất cả các hạng mục đều được cộng dồn, nhưng mỗi năm học điểm cộng tối đa là hai điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_07','V839','阮明',7,'我多参与讲座、汉语竞赛，争取提升学年综测分数。','wǒ duō cān yù jiǎng zuò、 hàn yǔ jìng sài， zhēng qǔ tí shēng xué nián zōng cè fēn shù。','Vậy em sẽ tham gia nhiều hội thảo và thi tiếng Trung hơn, cố gắng nâng điểm đánh giá năm học lên.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT840','SHT5','报名校级汉语竞赛，咨询参赛材料、评比标准',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V840','SIT840','P1','twist','tuy_y',NULL,'留学生汉语竞赛综合考察发音、逻辑表达，禁止剪辑配音视频，保证真实口语水平比拼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_01','V840','阮明',1,'你好，我想报名校级留学生汉语竞赛，需要准备什么参赛材料？','nǐ hǎo， wǒ xiǎng bào míng xiào jí liú xué shēng hàn yǔ jìng sài， xū yào zhǔn bèi shén me cān sài cái liào？','Chào bạn, mình muốn đăng ký thi tiếng Trung cấp trường dành cho sinh viên quốc tế, cần chuẩn bị những gì vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_02','V840','干事',2,'线上提交一分钟汉语自我介绍视频，线下现场参与演讲答题环节。','xiàn shàng tí jiāo yì fēn zhōng hàn yǔ zì wǒ jiè shào shì pín， xiàn xià xiàn chǎng cān yù yǎn jiǎng dá tí huán jié。','Nộp online một video tự giới thiệu bằng tiếng Trung dài một phút, còn phần thi trực tiếp thì có phần thuyết trình và trả lời câu hỏi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_03','V840','阮明',3,'竞赛评分侧重发音标准，还是内容立意、流畅度综合评判？','jìng sài píng fēn cè zhòng fā yīn biāo zhǔn， hái shì nèi róng lì yì、 liú chàng dù zōng hé píng pàn？','Chấm điểm chủ yếu dựa vào phát âm chuẩn, hay là xét tổng hợp cả nội dung, ý tưởng lẫn độ trôi chảy vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_04','V840','干事',4,'发音40%、内容立意30%、表达流畅度30%，三项综合打分嘛。','fā yīn 40%、 nèi róng lì yì 30%、 biǎo dá liú chàng dù 30%， sān xiàng zōng hé dǎ fēn ma。','Phát âm 40%, nội dung ý tưởng 30%, độ trôi chảy 30%, tính điểm tổng hợp cả ba phần luôn mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_05','V840','阮明',5,'报名截止后天傍晚，我今天录制自我介绍视频线上提交。','bào míng jié zhǐ hòu tiān bàng wǎn， wǒ jīn tiān lù zhì zì wǒ jiè shào shì pín xiàn shàng tí jiāo。','Hạn đăng ký là chiều tối ngày kia, nên hôm nay mình quay video tự giới thiệu rồi nộp online luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_06','V840','干事',6,'视频不能后期剪辑配音，必须完整现场原声录制。','shì pín bù néng hòu qī jiǎn jí pèi yīn， bì xū wán zhěng xiàn chǎng yuán shēng lù zhì。','Video không được cắt dựng hay lồng tiếng hậu kỳ đâu nha, phải quay trực tiếp trọn vẹn bằng âm thanh thật.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_07','V840','阮明',7,'我无剪辑完整录制视频，按时提交参赛报名素材。','wǒ wú jiǎn jí wán zhěng lù zhì shì pín， àn shí tí jiāo cān sài bào míng sù cái。','Vậy mình sẽ quay trọn video không chỉnh sửa gì, rồi nộp đúng hạn hồ sơ dự thi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT901','SXH1','主动询问球场陌生人，加入临时羽毛球组队玩耍',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V901','SIT901','P1','suon_se','tuy_y',NULL,'国内校园运动场临时组队十分普遍，场地、球具费用当场AA分摊，陌生人共同运动很容易快速熟悉。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_01','V901','阮明',1,'你好，看你们还差一位队友，我可以加入一起打羽毛球吗？','nǐ hǎo， kàn nǐ men hái chà yī wèi duì yǒu， wǒ kě yǐ jiā rù yì qǐ dǎ yǔ máo qiú ma？','Chào bạn, thấy các bạn còn thiếu một người, mình tham gia đánh cầu lông cùng được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_02','V901','小杨',2,'没问题，正好缺人，你有自带球拍还是用球场公用拍？','méi wèn tí， zhèng hǎo quē rén， nǐ yǒu zì dài qiú pāi hái shì yòng qiú chǎng gōng yòng pāi？','Không vấn đề gì, đang thiếu người luôn đây, bạn mang vợt riêng hay dùng vợt của sân vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_03','V901','阮明',3,'我带了球拍，咱们打两小时，场地费四个人平分对吧？','wǒ dài le qiú pāi， zán men dǎ liǎng xiǎo shí， chǎng dì fèi sì gè rén píng fēn duì ba？','Mình mang vợt rồi, mình chơi hai tiếng nhé, tiền sân chia đều bốn người đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_04','V901','小杨',4,'对，打完现场AA转账，每个人摊下来很便宜的。','duì， dǎ wán xiàn chǎng AA zhuǎn zhàng， měi gè rén tān xià lái hěn pián yi de。','Đúng rồi, chơi xong chuyển khoản chia đều luôn tại chỗ, tính ra mỗi người rẻ lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_05','V901','阮明',5,'太好了，平时很少找到人一起打球，今天刚好赶上。','tài hǎo le， píng shí hěn shǎo zhǎo dào rén yì qǐ dǎ qiú， jīn tiān gāng hǎo gǎn shàng。','Hay quá, bình thường ít khi tìm được người chơi cùng, hôm nay đúng lúc gặp các bạn luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_06','V901','小杨',6,'每周四下午我们都会来球场，你有空可以常过来组队。','měi zhōu sì xià wǔ wǒ men dōu huì lái qiú chǎng， nǐ yǒu kòng kě yǐ cháng guò lái zǔ duì。','Thứ năm hàng tuần chiều nào tụi mình cũng ra sân, rảnh thì cứ qua chơi chung nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_07','V901','阮明',7,'记下时间，下周同一时间我再来球场找你们。','jì xià shí jiān， xià zhōu tóng yī shí jiān wǒ zài lái qiú chǎng zhǎo nǐ men。','Mình ghi nhớ giờ rồi, tuần sau cùng giờ này mình lại ra sân tìm các bạn nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT902','SXH1','观看校园文艺晚会，和身边陌生同学简单搭话交流观感',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V902','SIT902','P1','twist','tuy_y',NULL,'看演出时和邻座陌生人聊节目内容是自然破冰方式，国内学生不会觉得唐突。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_01','V902','阮明',1,'刚刚那个民族舞蹈节目编排真好看，你觉得怎么样？','gāng gāng nà ge mín zú wǔ dǎo jié mù biān pái zhēn hǎo kàn， nǐ jué de zěn me yàng？','Tiết mục múa dân tộc lúc nãy dàn dựng đẹp thật đấy, bạn thấy sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_02','V902','陈雨',2,'我也很喜欢，就是灯光有点暗，演员面部细节看不清呢。','wǒ yě hěn xǐ huān， jiù shì dēng guāng yǒu diǎn àn， yǎn yuán miàn bù xì jié kàn bù qīng ne。','Mình cũng thích lắm, chỉ tiếc ánh sáng hơi tối nên nhìn không rõ biểu cảm của diễn viên.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_03','V902','阮明',3,'后面还有留学生合唱节目，听说有东南亚语种的歌曲。','hòu miàn hái yǒu liú xué shēng hé chàng jié mù， tīng shuō yǒu dōng nán yà yǔ zhǒng de gē qǔ。','Phía sau còn có tiết mục hợp xướng của sinh viên quốc tế nữa, nghe nói có cả bài hát tiếng Đông Nam Á đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_04','V902','陈雨',4,'我特意留到最后看，可惜中场手机没电，没法拍照记录。','wǒ tè yì liú dào zuì hòu kàn， kě xī zhōng chǎng shǒu jī méi diàn， méi fǎ pāi zhào jì lù。','Mình cố tình ở lại xem đến cuối luôn, tiếc là giữa chừng điện thoại hết pin nên không chụp ảnh lưu lại được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_05','V902','阮明',5,'我的手机电量充足，等下节目结束可以分几张照片给你。','wǒ de shǒu jī diàn liàng chōng zú， děng xià jié mù jié shù kě yǐ fēn jǐ zhāng zhào piān gěi nǐ。','Điện thoại mình còn đầy pin nè, lát chương trình kết thúc mình gửi bạn vài tấm ảnh nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_06','V902','陈雨',6,'太感谢啦，晚会结束加个联系方式，方便你发图给我。','tài gǎn xiè la， wǎn huì jié shù jiā gè lián xì fāng shì， fāng biàn nǐ fā tú gěi wǒ。','Cảm ơn bạn nhiều nha, xong buổi lễ mình kết bạn với nhau để tiện gửi ảnh cho mình nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_07','V902','阮明',7,'好，散场之后我们互相加好友，分享晚会现场照片。','hǎo， sàn chǎng zhī hòu wǒ men hù xiāng jiā hǎo yǒu， fēn xiǎng wǎn huì xiàn chǎng zhào piān。','Ừ, tan buổi mình kết bạn với nhau, chia sẻ ảnh chụp tại chương trình cho nhau nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT903','SXH1','报名校内志愿公益活动，活动中结识不同专业同学',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V903','SIT903','P1','suon_se','ban_chinh_thuc',NULL,'校内志愿活动是跨专业社交主流渠道，国内学生普遍愿意通过公益活动拓展朋友圈。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_01','V903','阮明',1,'学姐你好，我想报名周末社区敬老志愿活动，需要什么流程？','xué jiě nǐ hǎo， wǒ xiǎng bào míng zhōu mò shè qū jìng lǎo zhì yuàn huó dòng， xū yào shén me liú chéng？','Chào chị, em muốn đăng ký tham gia hoạt động tình nguyện thăm người già ở khu dân cư cuối tuần, cần làm thủ tục gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_02','V903','学姐',2,'线上填报名表单，周六早上八点在校门口集合统一出发哦。','xiàn shàng tián bào míng biǎo dān， zhōu liù zǎo shàng bā diǎn zài xiào mén kǒu jí hé tǒng yī chū fā ó。','Em điền đơn đăng ký online, tám giờ sáng thứ bảy tập trung ở cổng trường rồi cùng xuất phát nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_03','V903','阮明',3,'活动都是不同学院的学生参加吗，会不会只有我们专业？','huó dòng dōu shì bù tóng xué yuàn de xué shēng cān jiā ma， huì bú huì zhǐ yǒu wǒ men zhuān yè？','Hoạt động có sinh viên từ nhiều khoa khác nhau tham gia không ạ, hay chỉ có mỗi khoa mình thôi?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_04','V903','学姐',4,'全校各专业都有人报名，正好能认识很多新朋友。','quán xiào gè zhuān yè dōu yǒu rén bào míng， zhèng hǎo néng rèn shí hěn duō xīn péng yǒu。','Sinh viên các khoa trong trường đều đăng ký hết, đúng dịp em quen được nhiều bạn mới đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_05','V903','阮明',5,'活动主要做哪些工作，我提前准备简单的小节目给老人。','huó dòng zhǔ yào zuò nǎ xiē gōng zuò， wǒ tí qián zhǔn bèi jiǎn dān de xiǎo jié mù gěi lǎo rén。','Hoạt động chủ yếu làm những việc gì ạ, em chuẩn bị trước một tiết mục nhỏ để biểu diễn cho các cụ xem.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_06','V903','学姐',6,'陪老人聊天、打扫房间，会才艺的话表演小段节目很受欢迎。','péi lǎo rén liáo tiān、 dǎ sǎo fáng jiān， huì cái yì de huà biǎo yǎn xiǎo duàn jié mù hěn shòu huān yíng。','Chủ yếu là trò chuyện với các cụ, dọn dẹp phòng ốc, ai có tài lẻ biểu diễn một đoạn nhỏ thì được yêu thích lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_07','V903','阮明',7,'我准备一段越南简单民谣，周末准时来参与志愿活动。','wǒ zhǔn bèi yī duàn yuè nán jiǎn dān mín yáo， zhōu mò zhǔn shí lái cān yù zhì yuàn huó dòng。','Em sẽ chuẩn bị một bài dân ca Việt Nam đơn giản, cuối tuần đến đúng giờ tham gia hoạt động tình nguyện ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT904','SXH1','约朋友周末去城市公园徒步、逛景区，协商出行路线预算',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V904','SIT904','P1','twist','tuy_y',NULL,'多人外出游玩会兼顾体力、预算、返程时间集体协商，所有公共开销统一AA是通用社交规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_01','V904','阮明',1,'这周末天气很好，我们约上几个朋友去郊外公园徒步好不好？','zhè zhōu mò tiān qì hěn hǎo， wǒ men yuē shàng jǐ gè péng yǒu qù jiāo wài gōng yuán tú bù hǎo bù hǎo？','Cuối tuần này thời tiết đẹp lắm, mình rủ thêm vài người bạn đi công viên ngoại ô đi bộ đường dài nhé?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_02','V904','苏雯',2,'可以，有两条路线，短途两小时、长途五小时，大家体力不一样。','kě yǐ， yǒu liǎng tiáo lù xiàn， duǎn tú liǎng xiǎo shí、 cháng tú wǔ xiǎo shí， dà jiā tǐ lì bù yí yàng。','Được đó, có hai lộ trình, đường ngắn hai tiếng, đường dài năm tiếng, mỗi người thể lực khác nhau mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_03','V904','阮明',3,'长途路程远，来回公交票价会高出不少，预算需要提前算清嘛。','cháng tú lù chéng yuǎn， lái huí gōng jiāo piào jià huì gāo chū bù shǎo， yù suàn xū yào tí qián suàn qīng ma。','Đường dài xa hơn, tiền xe buýt khứ hồi cũng cao hơn nhiều, ngân sách cần tính rõ trước nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_04','V904','苏雯',4,'那我们先问所有人意愿，多数人选短途就走轻松路线。','nà wǒ men xiān wèn suǒ yǒu rén yì yuàn， duō shù rén xuǎn duǎn tú jiù zǒu qīng sōng lù xiàn。','Vậy mình hỏi ý kiến mọi người trước, đa số chọn đường ngắn thì đi lộ trình nhẹ nhàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_05','V904','阮明',5,'零食、矿泉水我来采购，所有人AA分摊食材花费。','líng shí、 kuàng quán shuǐ wǒ lái cǎi gòu， suǒ yǒu rén AA fēn tān shí cái huā fèi。','Đồ ăn vặt với nước suối để mình lo mua, tất cả chia đều tiền đồ ăn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_06','V904','苏雯',6,'傍晚返程避开晚高峰，不会耽误晚上自习休息。','bàng wǎn fǎn chéng bì kāi wǎn gāo fēng， bú huì dān wù wǎn shàng zì xí xiū xī。','Chiều về tránh giờ cao điểm, để khỏi ảnh hưởng đến giờ tự học buổi tối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_07','V904','阮明',7,'我现在在群里征集大家意见，敲定最终出行方案。','wǒ xiàn zài zài qún lǐ zhēng jí dà jiā yì jiàn， qiāo dìng zuì zhōng chū xíng fāng àn。','Giờ mình đăng lên nhóm xin ý kiến mọi người, chốt phương án đi cuối cùng luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT905','SXH1','宿舍公共观影夜，和室友商量影片选择、零食分摊',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V905','SIT905','P1','suon_se','tuy_y',NULL,'宿舍集体活动零食、饮品费用均分，同时会考虑周边宿舍作息，控制活动结束时间避免噪音扰民。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_01','V905','阮明',1,'今晚没课，我们宿舍办观影夜，大家投票选一部电影看吧？','jīn wǎn méi kè， wǒ men sù shè bàn guān yǐng yè， dà jiā tóu piào xuǎn yī bù diàn yǐng kàn ba？','Tối nay không có tiết, phòng mình tổ chức xem phim chung nhé, mọi người bình chọn xem phim gì đi?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_02','V905','小林',2,'有人想看喜剧，有人想看纪实纪录片，很难统一口味。','yǒu rén xiǎng kàn xǐ jù， yǒu rén xiǎng kàn jì shí jì lù piàn， hěn nán tǒng yī kǒu wèi。','Có người muốn xem phim hài, có người muốn xem phim tài liệu, khó mà thống nhất khẩu vị lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_03','V905','阮明',3,'那分上下半场，先放喜剧，后半段看纪实短片兼顾所有人。','nà fēn shàng xià bàn chǎng， xiān fàng xǐ jù， hòu bàn duàn kàn jì shí duǎn piàn jiān gù suǒ yǒu rén。','Vậy chia làm hai hiệp, đầu tiên chiếu phim hài, nửa sau xem đoạn phim tài liệu ngắn cho hợp ý mọi người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_04','V905','小林',4,'零食饮料统一网购，下单之后四个人平均分摊费用。','líng shí yǐn liào tǒng yī wǎng gòu， xià dān zhī hòu sì gè rén píng jūn fēn tān fèi yòng。','Đồ ăn vặt với nước uống đặt online chung, xong thì bốn người chia đều tiền nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_05','V905','阮明',5,'我负责挑选影片，你统计大家想吃的零食清单。','wǒ fù zé tiāo xuǎn yǐng piàn， nǐ tǒng jì dà jiā xiǎng chī de líng shí qīng dān。','Mình phụ trách chọn phim, cậu thống kê danh sách đồ ăn vặt mọi người muốn ăn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_06','V905','小林',6,'熄灯前结束观影，不熬夜打扰隔壁宿舍休息。','xī dēng qián jié shù guān yǐng， bù áo yè dǎ rǎo gé bì sù shè xiū xī。','Kết thúc xem phim trước giờ tắt đèn, không thức khuya làm phiền phòng bên cạnh nghỉ ngơi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_07','V905','阮明',7,'安排妥当，今晚宿舍一起轻松放松一下。','ān pái tuǒ dàng， jīn wǎn sù shè yì qǐ qīng sōng fàng sōng yī xià。','Sắp xếp ổn thỏa rồi, tối nay cả phòng cùng thư giãn thoải mái một chút nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT906','SXH1','校内桌游局，询问新人参与规则、是否收取分摊费用',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V906','SIT906','P1','that_bai_nhe','tuy_y',NULL,'线下桌游聚会大多会点饮品，多数人默认统一分摊，若有饮食禁忌可单独结算，无需勉强跟随大众消费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_01','V906','阮明',1,'我第一次来桌游局，想问游戏规则和场地费用怎么算？','wǒ dì yī cì lái zhuō yóu jú， xiǎng wèn yóu xì guī zé hé chǎng dì fèi yòng zěn me suàn？','Đây là lần đầu mình đến chơi bàn cờ, cho mình hỏi luật chơi và tiền sân tính thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_02','V906','小周',2,'桌游社提供全部卡牌，活动室免费使用，只需要AA奶茶钱。','zhuō yóu shè tí gōng quán bù kǎ pái， huó dòng shì miǎn fèi shǐ yòng， zhǐ xū yào AA nǎi chá qián。','Câu lạc bộ bàn cờ cung cấp hết bài, phòng sinh hoạt dùng miễn phí, chỉ cần chia tiền trà sữa thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_03','V906','阮明',3,'奶茶可以不点，只参与游戏不用分摊饮品费用吗？','nǎi chá kě yǐ bù diǎn， zhǐ cān yù yóu xì bù yòng fēn tān yǐn pǐn fèi yòng ma？','Nếu mình không gọi trà sữa, chỉ tham gia chơi thôi thì không cần chia tiền đồ uống đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_04','V906','小周',4,'大家默认每人点一杯饮品，不点的话有点不合群嘛。','dà jiā mò rèn měi rén diǎn yī bēi yǐn pǐn， bù diǎn de huà yǒu diǎn bù hé qún ma。','Mọi người mặc định mỗi người gọi một ly đồ uống, không gọi thì hơi lạc lõng đó nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_05','V906','阮明',5,'我肠胃不适合喝甜饮，单独买矿泉水，只分摊矿泉水费用行吗？','wǒ cháng wèi bú shì hé hē tián yǐn， dān dú mǎi kuàng quán shuǐ， zhǐ fēn tān kuàng quán shuǐ fèi yòng xíng ma？','Dạ dày mình không hợp uống đồ ngọt, mình mua riêng nước suối, chỉ chia tiền nước suối thôi được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_06','V906','小周',6,'没问题，跟老板说清楚，只算自己饮用水的钱。','méi wèn tí， gēn lǎo bǎn shuō qīng chǔ， zhǐ suàn zì jǐ yǐn yòng shuǐ de qián。','Không vấn đề gì, cứ nói rõ với chủ quán, chỉ tính tiền nước uống của riêng mình thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_07','V906','阮明',7,'好，我先学习基础桌游规则，不勉强自己点奶茶。','hǎo， wǒ xiān xué xí jī chǔ zhuō yóu guī zé， bù miǎn qiǎng zì jǐ diǎn nǎi chá。','Dạ được, vậy mình học luật chơi cơ bản trước, không ép bản thân phải gọi trà sữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT907','SXH1','参加校园国际文化节，展示本国特色小吃与传统手工',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V907','SIT907','P1','suon_se','ban_chinh_thuc',NULL,'校园国际文化节鼓励各国留学生展示本土美食、手工艺，是跨文化交流、结交各国朋友的重要活动。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_01','V907','阮明',1,'老师，我报名文化节摊位，准备越南春卷和手工竹编展示可以吗？','lǎo shī， wǒ bào míng wén huà jié tān wèi， zhǔn bèi yuè nán chūn juǎn hé shǒu gōng zhú biān zhǎn shì kě yǐ ma？','Thầy ơi, em đăng ký gian hàng lễ hội văn hóa, chuẩn bị nem cuốn Việt Nam với trưng bày đan tre thủ công được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_02','V907','老师',2,'完全合适，每个国家摊位提供少量试吃，吸引其他同学参观哦。','wán quán hé shì， měi gè guó jiā tān wèi tí gōng shǎo liàng shì chī， xī yǐn qí tā tóng xué cān guān ó。','Hoàn toàn phù hợp, mỗi gian hàng quốc gia cho khách nếm thử một ít, để thu hút các bạn khác đến tham quan nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_03','V907','阮明',3,'食材采购费用学院有补贴，还是需要留学生自行承担？','shí cái cǎi gòu fèi yòng xué yuàn yǒu bǔ tiē， hái shì xū yào liú xué shēng zì xíng chéng dān？','Chi phí mua nguyên liệu là khoa tài trợ, hay du học sinh phải tự bỏ tiền túi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_04','V907','老师',4,'基础食材学院报销，额外精致配料由个人自愿准备。','jī chǔ shí cái xué yuàn bào xiāo， é wài jīng zhì pèi liào yóu gè rén zì yuàn zhǔn bèi。','Nguyên liệu cơ bản khoa sẽ hoàn lại, còn nguyên liệu tinh xảo thêm thì tự nguyện chuẩn bị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_05','V907','阮明',5,'我现场简单演示竹编手法，方便来往同学体验手工。','wǒ xiàn chǎng jiǎn dān yǎn shì zhú biān shǒu fǎ， fāng biàn lái wǎng tóng xué tǐ yàn shǒu gōng。','Em sẽ trình diễn trực tiếp cách đan tre đơn giản, để các bạn qua lại tiện trải nghiệm thủ công.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_06','V907','老师',6,'活动当天人流量很大，提前半小时到场布置摊位。','huó dòng dàng tiān rén liú liàng hěn dà， tí qián bàn xiǎo shí dào chǎng bù zhì tān wèi。','Hôm diễn ra hoạt động lượng người rất đông, em đến sớm nửa tiếng để dọn gian hàng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_07','V907','阮明',7,'我提前备好食材与手工材料，文化节准时布置摊位。','wǒ tí qián bèi hǎo shí cái yǔ shǒu gōng cái liào， wén huà jié zhǔn shí bù zhì tān wèi。','Em sẽ chuẩn bị sẵn nguyên liệu và đồ thủ công, đúng giờ lễ hội là dọn gian hàng ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT908','SXH2','多人聚餐AA结算，核对账单、分摊转账，有人忘记付款提醒对方',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V908','SIT908','P1','twist','tuy_y',NULL,'多人AA聚餐统一由一人代收款项，提醒未付款人时语气委婉，避免让对方产生被催促的尴尬。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_01','V908','阮明',1,'我把餐厅完整账单发到群里，所有人人均三十五元，核对一下。','wǒ bǎ cān tīng wán zhěng zhàng dān fā dào qún lǐ， suǒ yǒu rén rén jūn sān shí wǔ yuán， hé duì yī xià。','Mình gửi hóa đơn đầy đủ của nhà hàng lên nhóm rồi, mỗi người ba mươi lăm tệ, mọi người kiểm tra lại nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_02','V908','苏雯',2,'大部分人已经转账给我，只有两位同学还没有付款。','dà bù fèn rén yǐ jīng zhuǎn zhàng gěi wǒ， zhǐ yǒu liǎng wèi tóng xué hái méi yǒu fù kuǎn。','Phần lớn mọi người chuyển khoản cho mình rồi, chỉ còn hai bạn chưa thanh toán thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_03','V908','阮明',3,'可能他们忘记看群消息，我温和提醒一句，别让对方尴尬。','kě néng tā men wàng jì kàn qún xiāo xī， wǒ wēn hé tí xǐng yī jù， bié ràng duì fāng gān gà。','Chắc họ quên xem tin nhắn nhóm, để mình nhắc nhẹ một câu, đừng để họ ngại quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_04','V908','苏雯',4,'说得委婉一点，就说我统一收款后要给店家结账。','shuō dé wěi wǎn yì diǎn， jiù shuō wǒ tǒng yī shōu kuǎn hòu yào gěi diàn jiā jié zhàng。','Nói khéo léo một chút, cứ bảo là mình gom tiền xong rồi thanh toán cho quán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_05','V908','阮明',5,'各位，麻烦有空转一下聚餐分摊费，我今晚统一结清账单哈。','gè wèi， má fán yǒu kòng zhuǎn yī xià jù cān fēn tān fèi， wǒ jīn wǎn tǒng yī jié qīng zhàng dān hā。','Mọi người ơi, rảnh thì chuyển giúp mình khoản chia tiền ăn nhé, tối nay mình thanh toán hết hóa đơn luôn.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_06','V908','小林',6,'收到，我现在立刻转账，刚才自习完全没看手机。','shōu dào， wǒ xiàn zài lì kè zhuǎn zhàng， gāng cái zì xí wán quán méi kàn shǒu jī。','Nhận được rồi, mình chuyển ngay đây, nãy giờ tự học nên không để ý điện thoại chút nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_07','V908','阮明',7,'全部款项收齐，这次聚餐开销结算完毕。','quán bù kuǎn xiàng shōu qí， zhè cì jù cān kāi xiāo jié suàn wán bì。','Thu đủ hết tiền rồi, vậy là chốt xong khoản chi tiêu bữa ăn lần này.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT909','SXH2','朋友过节送小礼物，推辞几番后礼貌收下并回赠伴手礼',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V909','SIT909','P1','suon_se','tuy_y',NULL,'国内人情讲究礼尚往来，收到礼物会先礼貌推辞一次再收下，后续准备等价小伴手礼回赠对方。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_01','V909','阮明',1,'不用特意给我准备中秋月饼，太破费啦，我不好意思收下。','bù yòng tè yì gěi wǒ zhǔn bèi zhōng qiū yuè bǐng， tài pò fèi la， wǒ bù hǎo yì sī shōu xià。','Cậu không cần cố tình chuẩn bị bánh trung thu cho mình đâu, tốn kém quá, mình ngại nhận lắm.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_02','V909','苏雯',2,'只是一盒普通月饼，一点心意，你不用跟我客气。','zhǐ shì yī hé pǔ tōng yuè bǐng， yì diǎn xīn yì， nǐ bù yòng gēn wǒ kè qì。','Chỉ là một hộp bánh bình thường thôi mà, chút tấm lòng ấy, cậu đừng khách sáo với mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_03','V909','阮明',3,'那我收下这份心意，下周我把家里寄来的越南咖啡回送给你。','nà wǒ shōu xià zhè fèn xīn yì， xià zhōu wǒ bǎ jiā lǐ jì lái de yuè nán kā fēi huí sòng gěi nǐ。','Vậy mình nhận tấm lòng này nha, tuần sau mình gửi lại cậu ít cà phê Việt Nam nhà gửi sang.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_04','V909','苏雯',4,'不用专门回礼，大家朋友之间不用计较这么多。','bù yòng zhuān mén huí lǐ， dà jiā péng yǒu zhī jiān bù yòng jì jiào zhè me duō。','Không cần đáp lễ đâu, bạn bè với nhau tính toán chi li làm gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_05','V909','阮明',5,'礼尚往来是我们两国都有的习惯，一定要收下我的伴手礼。','lǐ shàng wǎng lái shì wǒ men liǎng guó dōu yǒu de xí guàn， yí dìng yào shōu xià wǒ de bàn shǒu lǐ。','Có đi có lại là phong tục cả hai nước mình đều có, cậu nhất định phải nhận quà của mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_06','V909','苏雯',6,'行，那我收下咖啡，下次过节我们简单小礼物互相分享。','xíng， nà wǒ shōu xià kā fēi， xià cì guò jié wǒ men jiǎn dān xiǎo lǐ wù hù xiāng fēn xiǎng。','Được rồi, vậy mình nhận cà phê nha, lần tới có dịp lễ mình lại tặng nhau món quà nhỏ đơn giản thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_07','V909','阮明',7,'好，之后节日互相送平价小特产，不用贵重礼品。','hǎo， zhī hòu jié rì hù xiāng sòng píng jià xiǎo tè chǎn， bù yòng guì zhòng lǐ pǐn。','Ừ, sau này lễ tết cứ tặng nhau đặc sản nhỏ giá bình dân thôi, không cần quà đắt tiền.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT910','SXH2','主动请客吃饭，拒绝朋友抢单，解释自己提前规划买单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V910','SIT910','P1','twist','tuy_y',NULL,'朋友之间答谢请客十分常见，对方抢单时会说明请客缘由，约定下次轮流做东，平衡人情往来。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_01','V910','阮明',1,'今天是我请你吃饭，别跟我抢买单，我早就计划好了。','jīn tiān shì wǒ qǐng nǐ chī fàn， bié gēn wǒ qiǎng mǎi dān， wǒ zǎo jiù jì huà hǎo le。','Hôm nay mình mời cậu ăn, đừng giành trả tiền với mình, mình đã tính trước rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_02','V910','苏雯',2,'不行，每次都是你请客，这次必须我来付钱。','bù xíng， měi cì dōu shì nǐ qǐng kè， zhè cì bì xū wǒ lái fù qián。','Không được đâu, lần nào cũng cậu mời, lần này nhất định để mình trả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_03','V910','阮明',3,'上次你帮我整理一整本汉语笔记，这次就当答谢你的帮忙嘛。','shàng cì nǐ bāng wǒ zhěng lǐ yī zhěng běn hàn yǔ bǐ jì， zhè cì jiù dāng dá xiè nǐ de bāng máng ma。','Lần trước cậu giúp mình chép cả cuốn vở tiếng Trung, coi như lần này mình cảm ơn cậu đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_04','V910','苏雯',4,'只是小事而已，不用专门请客花这么多钱。','zhǐ shì xiǎo shì ér yǐ， bù yòng zhuān mén qǐng kè huā zhè me duō qián。','Chuyện nhỏ có gì đâu, không cần cố tình mời ăn tốn kém vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_05','V910','阮明',5,'心意一定要收下，下次换你请客，我们轮流做东。','xīn yì yí dìng yào shōu xià， xià cì huàn nǐ qǐng kè， wǒ men lún liú zuò dōng。','Tấm lòng này cậu nhất định phải nhận, lần sau đổi lại cậu mời, mình thay phiên nhau làm chủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_06','V910','苏雯',6,'那好吧，下次吃饭不许再跟我抢账单。','nà hǎo ba， xià cì chī fàn bù xǔ zài gēn wǒ qiǎng zhàng dān。','Thôi được, lần sau ăn thì không được giành trả tiền với mình nữa đâu nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_07','V910','阮明',7,'没问题，下次聚餐全部由你买单。','méi wèn tí， xià cì jù cān quán bù yóu nǐ mǎi dān。','Không thành vấn đề, lần sau cả buổi ăn để cậu bao hết.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT911','SXH2','多人外出喝奶茶，提前说好各自付款，避免互相垫付混淆',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V911','SIT911','P1','suon_se','tuy_y',NULL,'小额饮品、小吃分开自行付款，是年轻人简化人情、避免垫付纠纷的通用社交方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_01','V911','阮明',1,'我们去奶茶店，大家各自扫码点单自己付款，免得之后算不清垫付。','wǒ men qù nǎi chá diàn， dà jiā gè zì sǎo mǎ diǎn dān zì jǐ fù kuǎn， miǎn de zhī hòu suàn bù qīng diàn fù。','Mình đi quán trà sữa nhé, mọi người tự quét mã gọi món và tự trả tiền, kẻo sau này tính vụ ứng tiền lại rối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_02','V911','小林',2,'有时候有人手机没电，临时垫付之后很容易忘记转账。','yǒu shí hòu yǒu rén shǒu jī méi diàn， lín shí diàn fù zhī hòu hěn róng yì wàng jì zhuǎn zhàng。','Có lúc điện thoại ai đó hết pin, tạm ứng tiền hộ xong lại dễ quên chuyển khoản lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_03','V911','阮明',3,'分开付款最省事，不用事后挨个核对转账记录。','fēn kāi fù kuǎn zuì shěng shì， bù yòng shì hòu āi gè hé duì zhuǎn zhàng jì lù。','Chia ra trả riêng là tiện nhất, khỏi phải sau này ngồi soát từng khoản chuyển khoản.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_04','V911','苏雯',4,'行，到店每个人自己下单，不用统一一个人买单。','xíng， dào diàn měi gè rén zì jǐ xià dān， bù yòng tǒng yī yí gè rén mǎi dān。','Được, đến quán mỗi người tự đặt món, không cần dồn về một người trả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_05','V911','阮明',5,'想喝什么直接点，不用顾虑饮品价格互相迁就。','xiǎng hē shén me zhí jiē diǎn， bù yòng gù lǜ yǐn pǐn jià gé hù xiāng qiān jiù。','Thích uống gì cứ gọi thoải mái, không cần ngại giá đồ uống mà nhường nhịn nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_06','V911','小林',6,'这个办法省心，避免一堆转账记录分不清谁欠谁。','zhè ge bàn fǎ shěng xīn， bì miǎn yī duī zhuǎn zhàng jì lù fēn bù qīng shuí qiàn shuí。','Cách này đỡ đau đầu, tránh đống chuyển khoản lằng nhằng chẳng biết ai nợ ai.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_07','V911','阮明',7,'那我们现在去奶茶店各自下单。','nà wǒ men xiàn zài qù nǎi chá diàn gè zì xià dān。','Vậy giờ mình đi quán trà sữa, mỗi người tự đặt món nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT912','SXH2','朋友生病住院，邀约同学一起买水果前去探望慰问',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V912','SIT912','P1','suon_se','ban_chinh_thuc',NULL,'国内探望病人有送礼禁忌，梨谐音"离"不宜赠送；多人结伴探望、控制时长，不打扰病人休养。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_01','V912','阮明',1,'听说小杨发烧住院，我们约几个朋友买水果去医院看望他吧？','tīng shuō xiǎo yáng fā shāo zhù yuàn， wǒ men yuē jǐ gè péng yǒu mǎi shuǐ guǒ qù yī yuàn kàn wàng tā ba？','Nghe nói Tiểu Dương bị sốt phải nhập viện, mình rủ mấy bạn mua trái cây vào bệnh viện thăm cậu ấy nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_02','V912','小林',2,'可以，医院适合送苹果、橙子这类温和水果，不要送梨。','kě yǐ， yī yuàn shì hé sòng píng guǒ、 chéng zi zhè lèi wēn hé shuǐ guǒ， bú yào sòng lí。','Được đấy, vào bệnh viện nên mang táo, cam loại quả nhẹ nhàng thôi, đừng mang lê.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_03','V912','阮明',3,'梨在中文谐音不吉利，探望病人确实不适合携带对吧？','lí zài zhōng wén xié yīn bù jí lì， tàn wàng bìng rén què shí bú shì hé xié dài duì ba？','Lê trong tiếng Trung đọc gần giống từ không may mắn, đi thăm người bệnh đúng là không nên mang phải không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_04','V912','小林',4,'没错，我们四个人凑钱买一箱鲜果，统一分摊费用。','méi cuò， wǒ men sì gè rén còu qián mǎi yī xiāng xiān guǒ， tǒng yī fēn tān fèi yòng。','Đúng vậy, bốn đứa mình góp tiền mua một thùng trái cây tươi, chia đều chi phí ra.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_05','V912','阮明',5,'下午没课，三点左右在医院楼下集合一起上楼探望。','xià wǔ méi kè， sān diǎn zuǒ yòu zài yī yuàn lóu xià jí hé yī qǐ shàng lóu tàn wàng。','Chiều nay không có tiết, khoảng ba giờ tập trung dưới sảnh bệnh viện rồi cùng lên thăm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_06','V912','小林',6,'探望时间控制半小时，不耽误病人休息恢复。','tàn wàng shí jiān kòng zhì bàn xiǎo shí， bù dān wù bìng rén xiū xī huī fù。','Thời gian thăm giới hạn nửa tiếng thôi, để không ảnh hưởng đến việc nghỉ ngơi hồi phục của người bệnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_07','V912','阮明',7,'我现在联系其他同学，敲定下午探望时间。','wǒ xiàn zài lián xì qí tā tóng xué， qiāo dìng xià wǔ tàn wàng shí jiān。','Giờ mình liên hệ mấy bạn khác, chốt giờ thăm buổi chiều luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT913','SXH2','节日邀请中国朋友来宿舍，亲手做越南特色饭菜招待',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V913','SIT913','P1','twist','tuy_y',NULL,'邀请好友到宿舍亲手做饭招待，代表十分重视这段友谊，是很真诚的社交待客方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_01','V913','阮明',1,'中秋宿舍不熄灯，你来我宿舍，我亲手做越南米粉招待你。','zhōng qiū sù shè bù xī dēng， nǐ lái wǒ sù shè， wǒ qīn shǒu zuò yuè nán mǐ fěn zhāo dài nǐ。','Trung thu này ký túc xá không tắt đèn, cậu qua phòng mình đi, mình đích thân nấu phở Việt Nam đãi cậu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_02','V913','苏雯',2,'太麻烦你了，买菜、做饭收拾要花很长时间。','tài má fán nǐ le， mǎi cài、 zuò fàn shōu shí yào huā hěn zhǎng shí jiān。','Phiền cậu quá, đi chợ, nấu ăn rồi dọn dẹp chắc mất nhiều thời gian lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_03','V913','阮明',3,'食材我已经提前网购备好，只需要简单蒸煮，不会很费力嘛。','shí cái wǒ yǐ jīng tí qián wǎng gòu bèi hǎo， zhǐ xū yào jiǎn dān zhēng zhǔ， bú huì hěn fèi lì ma。','Nguyên liệu mình đã đặt online chuẩn bị sẵn từ trước rồi, chỉ cần hấp luộc đơn giản thôi, không tốn công đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_04','V913','苏雯',4,'我带一盒月饼过去搭配晚餐，咱们两国小吃一起品尝。','wǒ dài yī hé yuè bǐng guò qù dā pèi wǎn cān， zán men liǎng guó xiǎo chī yì qǐ pǐn cháng。','Mình mang một hộp bánh trung thu qua ăn kèm bữa tối, để hai đứa cùng nếm món ngon của cả hai nước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_05','V913','阮明',5,'宿舍小电锅功率有限，菜品种类不多，你别嫌弃简单。','sù shè xiǎo diàn guō gōng lǜ yǒu xiàn， cài pǐn zhǒng lèi bù duō， nǐ bié xián qì jiǎn dān。','Nồi điện nhỏ trong ký túc xá công suất có hạn, món ăn không nhiều lắm, cậu đừng chê đơn giản nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_06','V913','苏雯',6,'亲手做的饭菜比外面餐厅更有心意，我很期待。','qīn shǒu zuò de fàn cài bǐ wài miàn cān tīng gèng yǒu xīn yì， wǒ hěn qī dài。','Đồ ăn tự tay làm còn có tình cảm hơn nhà hàng bên ngoài nhiều, mình mong lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_07','V913','阮明',7,'那晚上七点来宿舍，我们一起过节聊天。','nà wǎn shàng qī diǎn lái sù shè， wǒ men yì qǐ guò jié liáo tiān。','Vậy bảy giờ tối qua phòng mình nhé, hai đứa cùng đón lễ và trò chuyện.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT914','SXH2','收到朋友贵重礼物，担心人情过重，和对方沟通下次减少花销',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V914','SIT914','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友交往更推崇平价走心小礼物，贵重礼品容易让对方产生人情压力，双方会提前约定简化送礼开销。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_01','V914','阮明',1,'这条围巾价格太高，贵重礼物我收下心里很过意不去。','zhè tiáo wéi jīn jià gé tài gāo， guì zhòng lǐ wù wǒ shōu xià xīn lǐ hěn guò yì bù qù。','Cái khăn quàng này giá cao quá, món quà đắt tiền thế này mình nhận mà thấy áy náy trong lòng lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_02','V914','苏雯',2,'只是一份生日礼物，不用放在心上。','zhǐ shì yī fèn shēng rì lǐ wù， bù yòng fàng zài xīn shàng。','Chỉ là quà sinh nhật thôi mà, cậu đừng để bụng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_03','V914','阮明',3,'普通平价小特产就足够，这么贵重的礼物让我不知道怎么回礼。','pǔ tōng píng jià xiǎo tè chǎn jiù zú gòu， zhè me guì zhòng de lǐ wù ràng wǒ bù zhī dào zěn me huí lǐ。','Đặc sản bình dân nhỏ là đủ rồi, món quà đắt thế này khiến mình không biết đáp lễ thế nào cho phải.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_04','V914','苏雯',4,'朋友不用刻意计较礼物价值，不用非要等价回赠。','péng yǒu bù yòng kè yì jì jiào lǐ wù jià zhí， bù yòng fēi yào děng jià huí zèng。','Bạn bè không cần tính toán chi li giá trị món quà đâu, không cần phải đáp lại tương xứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_05','V914','阮明',5,'下次过节千万不要买高价礼品，不然我不敢再收你的礼物了。','xià cì guò jié qiān wàn bú yào mǎi gāo jià lǐ pǐn， bù rán wǒ bù gǎn zài shōu nǐ de lǐ wù le。','Lần sau lễ tết tuyệt đối đừng mua quà đắt tiền nữa, không thì mình không dám nhận quà của cậu nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_06','V914','苏雯',6,'好，之后只送零食、书签这类平价小物件。','hǎo， zhī hòu zhǐ sòng líng shí、 shū qiān zhè lèi píng jià xiǎo wù jiàn。','Được rồi, sau này chỉ tặng đồ ăn vặt, bookmark kiểu vật nhỏ giá bình dân thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_07','V914','阮明',7,'这样轻松相处，不用因为人情礼物有心理负担。','zhè yàng qīng sōng xiāng chǔ， bù yòng yīn wèi rén qíng lǐ wù yǒu xīn lǐ fù dān。','Vậy mới thoải mái khi ở cạnh nhau, không phải mang gánh nặng tâm lý vì quà cáp tình cảm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT915','SXH3','因中外饮食礼仪差异产生小尴尬，主动和朋友解释本国习惯',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V915','SIT915','P1','suon_se','tuy_y',NULL,'中外餐桌礼仪存在大量差异，出现小尴尬主动说明本国习惯，多数中国年轻人会包容理解，不会苛责。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_01','V915','阮明',1,'刚刚吃饭我直接端碗喝汤，是不是和国内餐桌礼仪不一样？','gāng gāng chī fàn wǒ zhí jiē duān wǎn hē tāng， shì bú shì hé guó nèi cān zhuō lǐ yí bù yí yàng？','Vừa nãy ăn cơm mình cầm bát húp canh luôn, có khác với phép tắc bàn ăn ở đây không nhỉ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_02','V915','苏雯',2,'这边习惯碗放在桌上喝汤，我还以为你不太适应菜品。','zhè biān xí guàn wǎn fàng zài zhuō shàng hē tāng， wǒ hái yǐ wéi nǐ bù tài shì yìng cài pǐn。','Ở đây quen để bát trên bàn rồi húp canh, mình còn tưởng bạn không hợp món ăn chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_03','V915','阮明',3,'越南日常吃饭都会端起碗，是从小养成的饮食习惯，没有失礼的意思。','yuè nán rì cháng chī fàn dōu huì duān qǐ wǎn， shì cóng xiǎo yǎng chéng de yǐn shí xí guàn， méi yǒu shī lǐ de yì si。','Ở Việt Nam ngày thường ăn cơm đều cầm bát lên, quen từ nhỏ rồi, không có ý gì thất lễ đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_04','V915','苏雯',4,'原来是两国礼仪差别，完全没关系，我能理解。','yuán lái shì liǎng guó lǐ yí chā bié， wán quán méi guān xì， wǒ néng lǐ jiě。','Thì ra là khác biệt phong tục hai nước thôi, chẳng sao cả, mình hiểu mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_05','V915','阮明',5,'下次聚餐我会注意入乡随俗，兼顾这边餐桌习惯。','xià cì jù cān wǒ huì zhù yì rù xiāng suí sú， jiān gù zhè biān cān zhuō xí guàn。','Lần sau ăn chung mình sẽ để ý nhập gia tùy tục, chú ý theo thói quen bàn ăn ở đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_06','V915','苏雯',6,'不用刻意改变自己，两国习俗不同很正常，不用拘谨。','bù yòng kè yì gǎi biàn zì jǐ， liǎng guó xí sú bù tóng hěn zhèng cháng， bù yòng jū jǐn。','Không cần cố ý thay đổi bản thân đâu, phong tục hai nước khác nhau là bình thường, đừng gò bó quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_07','V915','阮明',7,'谢谢你包容不同的饮食礼仪，不会让我觉得尴尬。','xiè xiè nǐ bāo róng bù tóng de yǐn shí lǐ yí， bú huì ràng wǒ jué de gān gà。','Cảm ơn bạn đã bao dung khác biệt trong văn hóa ăn uống, nhờ vậy mình không thấy ngại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT916','SXH3','说话直爽无意间冒犯中国同学，事后主动道歉、说明文化差异',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V916','SIT916','P1','twist','ban_chinh_thuc',NULL,'东南亚部分国家交流风格直白，和国内委婉含蓄的沟通方式有冲突，产生矛盾后主动解释文化差异并道歉，容易化解隔阂。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_01','V916','阮明',1,'昨天聊天我说话太直接，伤到你的感受，我郑重跟你道歉。','zuó tiān liáo tiān wǒ shuō huà tài zhí jiē， shāng dào nǐ de gǎn shòu， wǒ zhèng zhòng gēn nǐ dào qiàn。','Hôm qua nói chuyện tôi ăn nói quá thẳng thắn, làm bạn buồn lòng, tôi xin lỗi bạn nghiêm túc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_02','V916','小林',2,'当时听完心里有点不舒服，知道你不是恶意就没关系。','dāng shí tīng wán xīn lǐ yǒu diǎn bù shū fú， zhī dào nǐ bú shì è yì jiù méi guān xì。','Lúc đó nghe xong trong lòng cũng hơi khó chịu, nhưng biết bạn không cố ý thì không sao cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_03','V916','阮明',3,'越南日常交流说话更直白，我还没完全适应委婉的中文表达。','yuè nán rì cháng jiāo liú shuō huà gèng zhí bái， wǒ hái méi wán quán shì yìng wěi wǎn de zhōng wén biǎo dá。','Người Việt giao tiếp hằng ngày nói chuyện thẳng thắn hơn, tôi vẫn chưa quen hẳn cách nói chuyện tế nhị của người Trung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_04','V916','小林',4,'我明白文化差异，之后有不舒服我会直接跟你说。','wǒ míng bái wén huà chā yì， zhī hòu yǒu bù shū fú wǒ huì zhí jiē gēn nǐ shuō。','Tôi hiểu là do khác biệt văn hóa, sau này có gì không thoải mái tôi sẽ nói thẳng với bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_05','V916','阮明',5,'之后我说话多斟酌用词，学着更委婉温和地表达想法。','zhī hòu wǒ shuō huà duō zhēn zhuó yòng cí， xué zhe gèng wěi wǎn wēn hé dì biǎo dá xiǎng fǎ。','Sau này tôi sẽ cân nhắc lời nói kỹ hơn, tập nói chuyện tế nhị và nhẹ nhàng hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_06','V916','小林',6,'我们互相包容两国说话习惯，不用因为小事隔阂。','wǒ men hù xiāng bāo róng liǎng guó shuō huà xí guàn， bù yòng yīn wèi xiǎo shì gé hé。','Chúng ta cứ bao dung thói quen nói chuyện của hai nước, đừng vì chuyện nhỏ mà xa cách nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_07','V916','阮明',7,'非常感谢你愿意原谅我无心的冒犯。','fēi cháng gǎn xiè nǐ yuàn yì yuán liàng wǒ wú xīn de mào fàn。','Cảm ơn bạn rất nhiều vì đã sẵn lòng tha thứ cho sự vô ý xúc phạm của tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT917','SXH3','和中国朋友聊两国节日风俗，互相讲解本土传统习俗',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V917','SIT917','P1','suon_se','tuy_y',NULL,'聊节日、民俗是安全无冲突的跨文化社交话题，很容易拉近留学生与中国同学的距离。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_01','V917','阮明',1,'越南新年会摆很多鲜花祭祖，你们春节主要有哪些习俗？','yuè nán xīn nián huì bǎi hěn duō xiān huā jì zǔ， nǐ men chūn jié zhǔ yào yǒu nǎ xiē xí sú？','Tết Việt Nam hay bày nhiều hoa tươi cúng tổ tiên, Tết bên các bạn có những phong tục gì thế?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_02','V917','苏雯',2,'贴春联、包饺子、全家守岁，长辈还给晚辈发红包呢。','tiē chūn lián、 bāo jiǎo zi、 quán jiā shǒu suì， zhǎng bèi huán gěi wǎn bèi fā hóng bāo ne。','Dán câu đối, gói bánh chẻo, cả nhà thức đón giao thừa, người lớn còn lì xì cho con cháu nữa đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_03','V917','阮明',3,'我们也有压岁钱，只是发放的时间、包装和中国不一样。','wǒ men yě yǒu yā suì qián， zhǐ shì fā fàng de shí jiān、 bāo zhuāng hé zhōng guó bù yí yàng。','Bên mình cũng có lì xì, chỉ là thời điểm phát, cách gói khác với Trung Quốc thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_04','V917','苏雯',4,'中秋你们也会赏月吃月饼吗，还是有特色本土点心？','zhōng qiū nǐ men yě huì shǎng yuè chī yuè bǐng ma， hái shì yǒu tè sè běn tǔ diǎn xīn？','Trung Thu bên bạn có ngắm trăng ăn bánh trung thu không, hay có bánh đặc trưng riêng?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_05','V917','阮明',5,'我们有同类团圆节日，点心是糯米团子，风味完全不同。','wǒ men yǒu tóng lèi tuán yuán jié rì， diǎn xīn shì nuò mǐ tuán zi， fēng wèi wán quán bù tóng。','Bên mình có ngày đoàn viên tương tự, bánh đặc trưng là bánh trôi nếp, hương vị hoàn toàn khác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_06','V917','苏雯',6,'有空交换各自节日照片，直观看看两国节日场景。','yǒu kòng jiāo huàn gè zì jié rì zhào piān， zhí guān kàn kàn liǎng guó jié rì chǎng jǐng。','Lúc nào rảnh trao đổi ảnh ngày lễ của mỗi bên nhé, để xem trực tiếp không khí lễ hội hai nước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_07','V917','阮明',7,'好，多交流民俗，能更了解彼此国家文化。','hǎo， duō jiāo liú mín sú， néng gèng liǎo jiě bǐ cǐ guó jiā wén huà。','Ừ, trao đổi phong tục nhiều thêm, sẽ hiểu văn hóa của nhau hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT918','SXH3','不清楚国内送礼禁忌，请教同学哪些礼物不适合送给长辈朋友',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V918','SIT918','P1','suon_se','ban_chinh_thuc',NULL,'中文大量谐音送礼禁忌，钟表（送终）、梨（离）、伞（散）均为送礼避讳物品，留学生提前询问可避免失礼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_01','V918','阮明',1,'我想给中国长辈准备礼物，想问问有什么物品不能赠送？','wǒ xiǎng gěi zhōng guó zhǎng bèi zhǔn bèi lǐ wù， xiǎng wèn wèn yǒu shén me wù pǐn bù néng zèng sòng？','Tôi muốn chuẩn bị quà cho người lớn tuổi bên Trung Quốc, muốn hỏi có món gì không nên tặng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_02','V918','苏雯',2,'钟表、梨、雨伞这几类谐音不吉利，尽量避开哦。','zhōng biǎo、 lí、 yǔ sǎn zhè jǐ lèi xié yīn bù jí lì， jǐn liàng bì kāi ó。','Đồng hồ, lê, dù mấy thứ này phát âm gần giống từ không may mắn, nên tránh nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_03','V918','阮明',3,'送鲜花有没有讲究，白色、黄色花束适合探望长辈吗？','sòng xiān huā yǒu méi yǒu jiǎng jiū， bái sè、 huáng sè huā shù shì hé tàn wàng zhǎng bèi ma？','Tặng hoa tươi có kiêng kỵ gì không, hoa trắng, hoa vàng có hợp để thăm người lớn tuổi không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_04','V918','苏雯',4,'白黄鲜花多用于丧葬，看望长辈选红色、粉色鲜花更合适。','bái huáng xiān huā duō yòng yú sāng zàng， kàn wàng zhǎng bèi xuǎn hóng sè、 fěn sè xiān huā gèng hé shì。','Hoa trắng vàng thường dùng trong tang lễ, đi thăm người lớn tuổi thì chọn hoa đỏ, hoa hồng sẽ hợp hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_05','V918','阮明',5,'刀具也不能作为礼品赠送，代表分割分离的寓意对吧？','dāo jù yě bù néng zuò wéi lǐ pǐn zèng sòng， dài biǎo fēn gē fēn lí de yù yì duì ba？','Dao kéo cũng không được dùng làm quà, vì mang ý nghĩa chia cắt, chia ly đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_06','V918','苏雯',6,'没错，刀具寓意不好，食品、茶叶、丝巾是稳妥选择。','méi cuò， dāo jù yù yì bù hǎo， shí pǐn、 chá yè、 sī jīn shì wěn tuǒ xuǎn zé。','Đúng vậy, dao kéo ý nghĩa không tốt, thực phẩm, trà, khăn lụa là lựa chọn an toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_07','V918','阮明',7,'我记下所有禁忌，挑选稳妥礼品送给长辈。','wǒ jì xià suǒ yǒu jìn jì， tiāo xuǎn wěn tuǒ lǐ pǐn sòng gěi zhǎng bèi。','Tôi ghi nhớ hết những điều kiêng kỵ rồi, sẽ chọn quà an toàn để tặng người lớn tuổi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT919','SXH3','朋友调侃本国文化，温和表达自己的看法，避免争执',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V919','SIT919','P1','that_bai_nhe','tuy_y',NULL,'国内年轻人偶尔会随口开玩笑，但涉及他国文化、风俗时需把握分寸，温和表达不适能有效避免社交矛盾升级。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_01','V919','阮明',1,'你刚刚调侃越南饮食的话，听着我心里有点不舒服。','nǐ gāng gāng tiáo kǎn yuè nán yǐn shí de huà， tīng zhe wǒ xīn lǐ yǒu diǎn bù shū fú。','Câu bạn vừa trêu về ẩm thực Việt Nam ấy, nghe xong mình thấy hơi khó chịu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_02','V919','小林',2,'我只是随口开玩笑，没有贬低你国家的意思。','wǒ zhǐ shì suí kǒu kāi wán xiào， méi yǒu biǎn dī nǐ guó jiā de yì si。','Mình chỉ tiện miệng đùa thôi, không có ý coi thường đất nước bạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_03','V919','阮明',3,'每个国家饮食文化都值得尊重，玩笑最好不要拿本国特色调侃嘛。','měi gè guó jiā yǐn shí wén huà dōu zhí de zūn zhòng， wán xiào zuì hǎo bù yào ná běn guó tè sè diào kǎn ma。','Văn hóa ẩm thực nước nào cũng đáng được tôn trọng, đùa thì tốt nhất đừng đem đặc trưng của nước người ta ra trêu chọc chứ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_04','V919','小林',4,'我不清楚你会在意这个，之后我会注意说话分寸。','wǒ bù qīng chǔ nǐ huì zài yì zhè ge， zhī hòu wǒ huì zhù yì shuō huà fēn cùn。','Mình không biết bạn để ý chuyện này, sau này mình sẽ chú ý lời nói hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_05','V919','阮明',5,'我们可以客观对比两国美食，但不要用调侃、取笑的语气。','wǒ men kě yǐ kè guān duì bǐ liǎng guó měi shí， dàn bú yào yòng tiáo kǎn、 qǔ xiào de yǔ qì。','Chúng ta có thể khách quan so sánh ẩm thực hai nước, nhưng đừng dùng giọng điệu trêu chọc, chế giễu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_06','V919','小林',6,'我记住了，以后聊各国文化都会注意措辞。','wǒ jì zhù le， yǐ hòu liáo gè guó wén huà dōu huì zhù yì cuò cí。','Mình ghi nhớ rồi, sau này nói về văn hóa các nước sẽ chú ý câu chữ hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_07','V919','阮明',7,'谢谢你理解我的感受，我们继续友好聊天。','xiè xiè nǐ lǐ jiě wǒ de gǎn shòu， wǒ men jì xù yǒu hǎo liáo tiān。','Cảm ơn bạn đã hiểu cho cảm xúc của mình, mình tiếp tục nói chuyện vui vẻ với nhau nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT920','SXH3','线上聊天用词误会，线下见面澄清、化解线上尴尬',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V920','SIT920','P1','twist','ban_chinh_thuc',NULL,'纯文字线上聊天缺少语气表情，极易产生误会，国内朋友遇到分歧倾向线下当面澄清，高效化解尴尬。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_01','V920','阮明',1,'昨天线上聊天那句话我用词有误，让你误会我的意思了。','zuó tiān xiàn shàng liáo tiān nà jù huà wǒ yòng cí yǒu wù， ràng nǐ wù huì wǒ de yì si le。','Câu tôi nhắn hôm qua dùng từ không khéo, làm bạn hiểu lầm ý tôi rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_02','V920','苏雯',2,'文字看不到语气，我当时还以为你有点生气。','wén zì kàn bú dào yǔ qì， wǒ dāng shí hái yǐ wéi nǐ yǒu diǎn shēng qì。','Chữ viết không thấy được giọng điệu, lúc đó tôi còn tưởng bạn hơi giận đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_03','V920','阮明',3,'线上打字缺少表情，很容易曲解情绪，我今天当面跟你解释清楚。','xiàn shàng dǎ zì quē shǎo biǎo qíng， hěn róng yì qū jiě qíng xù， wǒ jīn tiān dāng miàn gēn nǐ jiě shì qīng chǔ。','Nhắn tin thiếu biểu cảm nên rất dễ hiểu sai cảm xúc, hôm nay tôi gặp trực tiếp giải thích rõ với bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_04','V920','苏雯',4,'线下聊开就没事了，之后重要事情尽量语音沟通。','xiàn xià liáo kāi jiù méi shì le， zhī hòu zhòng yào shì qíng jǐn liàng yǔ yīn gōu tōng。','Nói chuyện trực tiếp là xong ngay thôi, sau này chuyện quan trọng thì cứ gọi điện nói chuyện luôn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_05','V920','阮明',5,'文字容易产生误会，之后复杂想法直接语音或者见面聊。','wén zì róng yì chǎn shēng wù huì， zhī hòu fù zá xiǎng fǎ zhí jiē yǔ yīn huò zhě jiàn miàn liáo。','Nhắn tin dễ gây hiểu lầm, sau này suy nghĩ phức tạp thì gọi điện hoặc gặp trực tiếp nói chuyện luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_06','V920','苏雯',6,'没问题，线上简单小事文字，重要话题线下沟通。','méi wèn tí， xiàn shàng jiǎn dān xiǎo shì wén zì， zhòng yào huà tí xiàn xià gōu tōng。','Không vấn đề gì, chuyện nhỏ đơn giản thì nhắn tin, chuyện quan trọng thì gặp trực tiếp trao đổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_07','V920','阮明',7,'太好了，误会说开我们不会有隔阂。','tài hǎo le， wù huì shuō kāi wǒ men bú huì yǒu gé hé。','Tuyệt quá, hiểu lầm nói rõ ra rồi thì chúng ta sẽ không còn khoảng cách nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT921','SXH4','留学生微信群发起线下小型茶话会，统计参与人数、地点',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V921','SIT921','P1','suon_se','tuy_y',NULL,'留学生线上社群自发组织线下小型聚会十分普遍，饮品、零食自带或AA分摊，场地提前预留。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_01','V921','阮明',1,'本周六下午两点校内咖啡馆举办留学生茶话会，有意向的群里回复1。','běn zhōu liù xià wǔ liǎng diǎn xiào nèi kā fēi guǎn jǔ bàn liú xué shēng chá huà huì， yǒu yì xiàng de qún lǐ huí fù 1。','Chiều thứ Bảy tuần này lúc hai giờ, quán cà phê trong trường tổ chức buổi trà đàm cho du học sinh, bạn nào muốn tham gia thì trả lời 1 trong nhóm nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_02','V921','群友A',2,'咖啡馆座位有限，最多容纳十五个人，人数满了就截止报名吗？','kā fēi guǎn zuò wèi yǒu xiàn， zuì duō róng nà shí wǔ gè rén， rén shù mǎn le jiù jié zhǐ bào míng ma？','Quán cà phê chỗ ngồi có hạn, tối đa mười lăm người, đủ số là ngừng nhận đăng ký luôn hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_03','V921','阮明',3,'没错，先回复先预留位置，到场饮品全部AA自行点单。','méi cuò， xiān huí fù xiān yù liú wèi zhì， dào chǎng yǐn pǐn quán bù AA zì xíng diǎn dān。','Đúng vậy, ai trả lời trước thì giữ chỗ trước, đến nơi ai uống gì tự gọi và tự trả tiền phần mình nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_04','V921','群友B',4,'会分享各国零食吗，我可以带越南特色糖果过去。','huì fēn xiǎng gè guó líng shí ma， wǒ kě yǐ dài yuè nán tè sè táng guǒ guò qù。','Có chia sẻ đồ ăn vặt các nước không, mình có thể mang kẹo đặc sản Việt Nam qua đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_05','V921','阮明',5,'欢迎大家自带本国小零食交换品尝，丰富茶话会内容。','huān yíng dà jiā zì dài běn guó xiǎo líng shí jiāo huàn pǐn cháng， fēng fù chá huà huì nèi róng。','Rất hoan nghênh mọi người mang đồ ăn vặt nước mình đến trao đổi nếm thử, cho buổi trà đàm thêm phong phú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_06','V921','阮明',6,'我傍晚统计最终人数，提前跟咖啡馆预留区域。','wǒ bàng wǎn tǒng jì zuì zhōng rén shù， tí qián gēn kā fēi guǎn yù liú qū yù。','Chiều tối mình sẽ chốt số lượng người tham gia, rồi báo trước với quán cà phê để giữ khu vực.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_07','V921','群友C',7,'我报名参加，周六准时到场。','wǒ bào míng cān jiā， zhōu liù zhǔn shí dào chǎng。','Mình đăng ký tham gia nhé, thứ Bảy sẽ có mặt đúng giờ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT922','SXH4','和新朋友初次线下见面，挑选公共场所、确认往返交通',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V922','SIT922','P1','twist','ban_chinh_thuc',NULL,'初次线下见面优先校园周边公共场所，不单独前往偏僻地点，分别后互相报平安是国内年轻人通用社交安全习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_01','V922','阮明',1,'我们第一次线下见面，选学校正门连锁奶茶店可以吗？','wǒ men dì yī cì xiàn xià jiàn miàn， xuǎn xué xiào zhèng mén lián suǒ nǎi chá diàn kě yǐ ma？','Lần đầu gặp mặt trực tiếp, mình chọn quán trà sữa chuỗi ở cổng chính trường được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_02','V922','陈雨',2,'公共场所很安全，就是我下午有课，只能停留一小时。','gōng gòng chǎng suǒ hěn ān quán， jiù shì wǒ xià wǔ yǒu kè， zhǐ néng tíng liú yī xiǎo shí。','Nơi công cộng thì an toàn, chỉ là chiều mình có tiết học, chỉ ở lại được một tiếng thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_03','V922','阮明',3,'一小时足够简单聊天，结束我可以送你回教学楼。','yī xiǎo shí zú gòu jiǎn dān liáo tiān， jié shù wǒ kě yǐ sòng nǐ huí jiào xué lóu。','Một tiếng đủ để nói chuyện đơn giản rồi, xong mình có thể đưa bạn về tòa nhà học nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_04','V922','陈雨',4,'不用特意送我，校门口公交直达教学楼，交通很方便。','bù yòng tè yì sòng wǒ， xiào mén kǒu gōng jiāo zhí dá jiào xué lóu， jiāo tōng hěn fāng biàn。','Không cần đưa mình đâu, xe buýt ở cổng trường đi thẳng đến tòa nhà học, rất tiện luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_05','V922','阮明',5,'见面结束记得发消息告诉我平安抵达教室哈。','jiàn miàn jié shù jì de fā xiāo xī gào sù wǒ píng ān dǐ dá jiào shì hā。','Gặp xong nhớ nhắn tin báo mình biết là bạn về đến lớp an toàn nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_06','V922','陈雨',6,'好，周六下午三点奶茶店门口碰面。','hǎo， zhōu liù xià wǔ sān diǎn nǎi chá diàn mén kǒu pèng miàn。','Được, ba giờ chiều thứ Bảy gặp nhau trước cửa quán trà sữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_07','V922','阮明',7,'准时赴约，初次见面简单聊一聊各自专业。','zhǔn shí fù yuē， chū cì jiàn miàn jiǎn dān liáo yī liáo gè zì zhuān yè。','Đến đúng giờ nhé, lần đầu gặp mặt thì nói chuyện đơn giản về chuyên ngành của mỗi người thôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT923','SXH4','朋友频繁发消息打扰自习，委婉告知自己的作息学习时间',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V923','SIT923','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内学生重视自习、上课时间，会主动和朋友说明固定专注时段，委婉划定社交边界，对方一般都会体谅。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_01','V923','阮明',1,'不好意思，每天下午两点到五点我要专心自习，没法及时回复消息。','bù hǎo yì sī， měi tiān xià wǔ liǎng diǎn dào wǔ diǎn wǒ yào zhuān xīn zì xí， méi fǎ jí shí huí fù xiāo xī。','Xin lỗi cậu nhé, mỗi ngày từ hai giờ đến năm giờ chiều mình cần tập trung tự học, nên không thể trả lời tin nhắn ngay được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_02','V923','小杨',2,'我以为你随时有空，一有琐事就发消息打扰你了。','wǒ yǐ wéi nǐ suí shí yǒu kòng， yī yǒu suǒ shì jiù fā xiāo xī dǎ rǎo nǐ le。','Mình cứ tưởng lúc nào cậu cũng rảnh, nên có việc gì lặt vặt là nhắn làm phiền cậu luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_03','V923','阮明',3,'自习时段需要安静专注，其余晚上七点之后我可以随时聊天嘛。','zì xí shí duàn xū yào ān jìng zhuān zhù， qí yú wǎn shàng qī diǎn zhī hòu wǒ kě yǐ suí shí liáo tiān ma。','Khung giờ tự học thì cần yên tĩnh tập trung, còn sau bảy giờ tối là mình có thể trò chuyện thoải mái mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_04','V923','小杨',4,'我记住你的作息，非休息时间不会频繁发消息打断你学习。','wǒ jì zhù nǐ de zuò xī， fēi xiū xī shí jiān bú huì pín fán fā xiāo xī dǎ duàn nǐ xué xí。','Mình ghi nhớ giờ giấc của cậu rồi, ngoài giờ nghỉ ra thì sẽ không nhắn tin liên tục làm gián đoạn việc học của cậu nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_05','V923','阮明',5,'急事可以直接打电话，普通闲聊集中晚上再回复你。','jí shì kě yǐ zhí jiē dǎ diàn huà， pǔ tōng xián liáo jí zhōng wǎn shàng zài huí fù nǐ。','Việc gấp thì cứ gọi điện thẳng luôn, còn chuyện tán gẫu bình thường thì để tối mình trả lời tập trung một lần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_06','V923','小杨',6,'没问题，我调整发消息的时间，不耽误你复习功课。','méi wèn tí， wǒ tiáo zhěng fā xiāo xī de shí jiān， bù dān wù nǐ fù xí gōng kè。','Không sao, mình sẽ điều chỉnh lại giờ nhắn tin, không làm ảnh hưởng đến việc ôn bài của cậu đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_07','V923','阮明',7,'十分感谢理解，我们错开自习时段聊天互不影响。','shí fēn gǎn xiè lǐ jiě， wǒ men cuò kāi zì xí shí duàn liáo tiān hù bù yǐng xiǎng。','Cảm ơn cậu nhiều vì đã hiểu cho mình, tụi mình tránh khung giờ tự học ra để nói chuyện, khỏi ảnh hưởng nhau.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT924','SXH4','社交软件添加好友，简单自我介绍、说明结识契机',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V924','SIT924','P1','suon_se','tuy_y',NULL,'社交软件添加新朋友后，第一句主动自我介绍、说明相遇场景，是礼貌破冰的基础社交礼仪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_01','V924','阮明',1,'你好，我是阮明，越南留学生，刚才羽毛球球场跟你搭话的人。','nǐ hǎo， wǒ shì ruǎn míng， yuè nán liú xué shēng， gāng cái yǔ máo qiú qiú chǎng gēn nǐ dā huà de rén。','Chào cậu, mình là Nguyễn Minh, du học sinh Việt Nam, lúc nãy là người bắt chuyện với cậu ở sân cầu lông đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_02','V924','小周',2,'你好，刚才打球聊了两句，特意添加好友方便之后约球场。','nǐ hǎo， gāng cái dǎ qiú liáo le liǎng jù， tè yì tiān jiā hǎo yǒu fāng biàn zhī hòu yuē qiú chǎng。','Chào cậu, lúc nãy chơi cầu lông xong nói chuyện hợp quá, nên mình kết bạn luôn để sau này tiện hẹn sân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_03','V924','阮明',3,'平时周四下午有空打球，有空可以在微信提前约场地。','píng shí zhōu sì xià wǔ yǒu kòng dǎ qiú， yǒu kòng kě yǐ zài wēi xìn tí qián yuē chǎng dì。','Bình thường chiều thứ Năm mình hay rảnh để chơi cầu lông, khi nào rảnh thì cứ nhắn WeChat hẹn sân trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_04','V924','小周',4,'没问题，我大部分周四没课，随时可以组队。','méi wèn tí， wǒ dà bù fèn zhōu sì méi kè， suí shí kě yǐ zǔ duì。','Không thành vấn đề, phần lớn thứ Năm mình không có tiết, lúc nào cũng có thể rủ chơi cùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_05','V924','阮明',5,'我汉语还在练习，有表达不通顺的地方麻烦多包涵。','wǒ hàn yǔ hái zài liàn xí， yǒu biǎo dá bù tōng shùn de dì fāng má fán duō bāo hán。','Tiếng Trung của mình vẫn còn đang luyện, có chỗ nào diễn đạt chưa trôi chảy thì mong cậu thông cảm nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_06','V924','小周',6,'互相学习，你也可以教我几句越南日常用语。','hù xiāng xué xí， nǐ yě kě yǐ jiāo wǒ jǐ jù yuè nán rì cháng yòng yǔ。','Học hỏi lẫn nhau mà, cậu cũng có thể dạy mình vài câu tiếng Việt thông dụng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_07','V924','阮明',7,'之后球场碰面再详细聊天。','zhī hòu qiú chǎng pèng miàn zài xiáng xì liáo tiān。','Vậy lần sau gặp nhau ở sân rồi nói chuyện kỹ hơn nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT925','SXH4','多人出行计划出现分歧，投票协商统一游玩行程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V925','SIT925','P1','suon_se','tuy_y',NULL,'多人集体出行意见不统一时，普遍采用投票少数服从多数，落选一方配合集体安排，不单独搞分歧行程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_01','V925','阮明',1,'现在有两个游玩方案，爬山或者城市老街逛小店，大家投票选择。','xiàn zài yǒu liǎng gè yóu wán fāng àn， pá shān huò zhě chéng shì lǎo jiē guàng xiǎo diàn， dà jiā tóu piào xuǎn zé。','Giờ có hai phương án đi chơi nè, leo núi hoặc dạo phố cổ ghé mấy tiệm nhỏ, mọi người bỏ phiếu chọn đi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_02','V925','苏雯',2,'我倾向老街，爬山体力消耗太大，晚上还有作业要写。','wǒ qīng xiàng lǎo jiē， pá shān tǐ lì xiāo hào tài dà， wǎn shàng hái yǒu zuò yè yào xiě。','Mình thiên về phố cổ hơn, leo núi tốn sức quá, tối về còn phải làm bài tập nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_03','V925','小林',3,'我想爬山，老街商铺人太多拍照拥挤。','wǒ xiǎng pá shān， lǎo jiē shāng pù rén tài duō pāi zhào yōng jǐ。','Mình muốn leo núi, phố cổ đông người quá, chụp ảnh chen chúc lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_04','V925','阮明',4,'我们五个人举手表决，票数多的方案作为本周出行计划。','wǒ men wǔ gè rén jǔ shǒu biǎo jué， piào shù duō de fāng àn zuò wéi běn zhōu chū xíng jì huà。','Năm đứa mình giơ tay biểu quyết đi, phương án nào nhiều phiếu hơn thì làm kế hoạch đi chơi tuần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_05','V925','小林',5,'行，少数服从多数，选老街我也配合大家行程。','xíng， shǎo shù fú cóng duō shù， xuǎn lǎo jiē wǒ yě pèi hé dà jiā xíng chéng。','Được thôi, thiểu số phục tùng đa số, chọn phố cổ thì mình cũng theo lịch trình của mọi người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_06','V925','阮明',6,'敲定老街路线，提前查公交、小吃店攻略。','qiāo dìng lǎo jiē lù xiàn， tí qián chá gōng jiāo、 xiǎo chī diàn gōng lüè。','Vậy chốt đi phố cổ nha, để mình tra trước xe buýt với review mấy quán ăn vặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_07','V925','苏雯',7,'统一行程之后，所有人周末同步出发。','tǒng yī xíng chéng zhī hòu， suǒ yǒu rén zhōu mò tóng bù chū fā。','Chốt lịch trình xong thì cuối tuần mọi người cùng xuất phát nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT926','SXH4','线下聚会结束后，主动发消息平安到家，告知同行朋友',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V926','SIT926','P1','suon_se','tuy_y',NULL,'多人线下活动解散后，互相在群内报平安是通用习惯，确认所有人安全抵达住处，避免同伴失联让人担心。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_01','V926','阮明',1,'我已经平安回到宿舍，大家到家都报一声平安哈。','wǒ yǐ jīng píng ān huí dào sù shè， dà jiā dào jiā dōu bào yī shēng píng ān hā。','Mình về ký túc xá an toàn rồi nha, mọi người về đến nơi thì báo một tiếng cho yên tâm nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_02','V926','苏雯',2,'我刚到楼下，马上进宿舍，路上公交很顺畅。','wǒ gāng dào lóu xià， mǎ shàng jìn sù shè， lù shàng gōng jiāo hěn shùn chàng。','Mình vừa đến dưới tòa nhà, sắp vào ký túc xá rồi, đường đi xe buýt thuận lợi lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_03','V926','小林',3,'我还在步行回宿舍，十分钟左右到，一切顺利。','wǒ hái zài bù xíng huí sù shè， shí fēn zhōng zuǒ yòu dào， yī qiè shùn lì。','Mình còn đang đi bộ về ký túc xá, khoảng mười phút nữa là tới, mọi thứ đều ổn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_04','V926','阮明',4,'今晚聚会很开心，下次有空再约线下活动。','jīn wǎn jù huì hěn kāi xīn， xià cì yǒu kòng zài yuē xiàn xià huó dòng。','Tối nay tụ tập vui ghê, lần sau rảnh lại hẹn đi chơi tiếp nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_05','V926','苏雯',5,'好，下周看课表再商量下次聚会时间。','hǎo， xià zhōu kàn kè biǎo zài shāng liáng xià cì jù huì shí jiān。','Ừ, để tuần sau xem thời khóa biểu rồi bàn tiếp giờ tụ tập lần sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_06','V926','阮明',6,'大家早点休息，晚安。','dà jiā zǎo diǎn xiū xī， wǎn ān。','Mọi người nghỉ sớm nhé, chúc ngủ ngon.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT927','SXH5','社团换届竞选，为参选朋友加油，赛后安慰落选社员',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V927','SIT927','P1','twist','ban_chinh_thuc',NULL,'社团竞选落选后，身边朋友会主动安慰鼓励，国内社团氛围看重同伴支持，不会因竞选结果疏远关系。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_01','V927','阮明',1,'刚才竞选演讲你发挥特别好，可惜差几票没能当选部长。','gāng cái jìng xuǎn yǎn jiǎng nǐ fā huī tè bié hǎo， kě xī chà jǐ piào méi néng dāng xuǎn bù zhǎng。','Lúc nãy bài phát biểu tranh cử của cậu ổn lắm đó, tiếc là thiếu vài phiếu nên không trúng cử chủ nhiệm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_02','V927','小杨',2,'准备了很久还是落选，心里有点失落。','zhǔn bèi le hěn jiǔ hái shì luò xuǎn， xīn lǐ yǒu diǎn shī luò。','Chuẩn bị lâu vậy mà vẫn rớt, trong lòng cũng hơi buồn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_03','V927','阮明',3,'你的能力所有人都看得到，明年换届还有机会参选嘛。','nǐ de néng lì suǒ yǒu rén dōu kàn dé dào， míng nián huàn jiè hái yǒu jī huì cān xuǎn ma。','Năng lực của cậu ai cũng thấy rõ mà, năm sau bầu lại còn cơ hội ứng cử tiếp mà.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_04','V927','小杨',4,'下一年学业压力大，不一定有空参与社团管理。','xià yī nián xué yè yā lì dà， bù yí dìng yǒu kòng cān yù shè tuán guǎn lǐ。','Năm sau áp lực học hành nặng lắm, chưa chắc còn thời gian tham gia quản lý câu lạc bộ nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_05','V927','阮明',5,'就算不当部长，社团活动依旧可以正常参与组织工作。','jiù suàn bù dàng bù zhǎng， shè tuán huó dòng yī jiù kě yǐ zhèng cháng cān yù zǔ zhī gōng zuò。','Dù không làm chủ nhiệm thì cậu vẫn có thể tham gia tổ chức hoạt động câu lạc bộ bình thường mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_06','V927','小杨',6,'谢谢你过来为我加油，还特意过来安慰我。','xiè xiè nǐ guò lái wèi wǒ jiā yóu， hái tè yì guò lái ān wèi wǒ。','Cảm ơn cậu đã đến cổ vũ mình, còn đặc biệt qua an ủi mình nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_07','V927','阮明',7,'我们是朋友，开心、失落都可以一起分担。','wǒ men shì péng yǒu， kāi xīn、 shī luò dōu kě yǐ yì qǐ fēn dān。','Tụi mình là bạn bè mà, vui hay buồn gì cũng chia sẻ cùng nhau được hết.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT928','SXH5','新生向高年级学长学姐请教社交、校园生活避坑经验',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V928','SIT928','P1','suon_se','ban_chinh_thuc',NULL,'高校内新生主动向高年级学长学姐请教校园、社交经验是很普遍的行为，学长学姐一般都会耐心分享实用建议。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_01','V928','阮明',1,'学长，我刚入校不太熟悉校园社交，想请教一些避坑小经验。','xué zhǎng， wǒ gāng rù xiào bù tài shú xī xiào yuán shè jiāo， xiǎng qǐng jiào yī xiē bì kēng xiǎo jīng yàn。','Anh ơi, em mới vào trường chưa quen giao tiếp trong trường lắm, muốn xin anh vài kinh nghiệm tránh sai lầm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_02','V928','学长',2,'社团不用一次性报名五六个，选一两个真正感兴趣的深耕即可。','shè tuán bù yòng yí cì xìng bào míng wǔ liù gè， xuǎn yī liǎng gè zhēn zhèng gǎn xìng qù de shēn gēng jí kě。','Câu lạc bộ thì không cần đăng ký một lúc năm sáu cái đâu, chọn một hai cái mình thực sự thích rồi đầu tư kỹ vào là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_03','V928','阮明',3,'校外社交、兼职有哪些需要格外留意的陷阱？','xiào wài shè jiāo、 jiān zhí yǒu nǎ xiē xū yào gé wài liú yì de xiàn jǐng？','Giao tiếp bên ngoài, làm thêm thì có cái bẫy nào cần đặc biệt chú ý không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_04','V928','学长',4,'陌生线下兼职、陌生网友单独见面一定要选公共场所。','mò shēng xiàn xià jiān zhí、 mò shēng wǎng yǒu dān dú jiàn miàn yí dìng yào xuǎn gōng gòng chǎng suǒ。','Làm thêm ngoài đời với người lạ, hay gặp bạn quen qua mạng lần đầu, nhất định phải chọn nơi công cộng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_05','V928','阮明',5,'和本国、中国同学相处，有什么容易产生误会的文化细节？','hé běn guó、 zhōng guó tóng xué xiāng chǔ， yǒu shén me róng yì chǎn shēng wù huì de wén huà xì jié？','Vậy khi giao tiếp với bạn cùng nước và bạn Trung Quốc, có chi tiết văn hóa nào dễ gây hiểu lầm không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_06','V928','学长',6,'送礼、借钱、作息边界提前沟通清楚，能减少大部分矛盾。','sòng lǐ、 jiè qián、 zuò xī biān jiè tí qián gōu tōng qīng chǔ， néng jiǎn shǎo dà bù fèn máo dùn。','Chuyện tặng quà, mượn tiền, hay ranh giới giờ giấc sinh hoạt thì nên trao đổi rõ trước, vậy là giảm được phần lớn mâu thuẫn rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_07','V928','阮明',7,'记下您的建议，避免社交踩坑吃亏。','jì xià nín de jiàn yì， bì miǎn shè jiāo cǎi kēng chī kuī。','Em ghi nhớ lời khuyên của anh, để tránh vấp phải mấy chuyện thiệt thòi trong giao tiếp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT929','SXH5','班级集体短途出游，主动分担采购零食、清点人数的小事',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V929','SIT929','P1','suon_se','tuy_y',NULL,'班级集体活动大家主动分担琐碎工作，是体现集体意识、快速拉近同学关系的社交方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_01','V929','阮明',1,'班长，出游采购零食、清点人数的活我可以帮忙分担。','bān zhǎng， chū yóu cǎi gòu líng shí、 qīng diǎn rén shù de huó wǒ kě yǐ bāng máng fēn dān。','Lớp trưởng ơi, chuyện mua đồ ăn vặt với điểm danh sĩ số lúc đi chơi để mình phụ giúp cho.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_02','V929','班长',2,'太好了，全班三十人，清点人数很耗费精力。','tài hǎo le， quán bān sān shí rén， qīng diǎn rén shù hěn hào fèi jīng lì。','Tốt quá, cả lớp ba mươi người, điểm danh sĩ số tốn sức lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_03','V929','阮明',3,'我统计所有人忌口，采购零食避开辣椒、坚果过敏原。','wǒ tǒng jì suǒ yǒu rén jì kǒu， cǎi gòu líng shí bì kāi là jiāo、 jiān guǒ guò mǐn yuán。','Mình sẽ thống kê xem ai kiêng món gì, mua đồ ăn vặt thì tránh ớt với hạt gây dị ứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_04','V929','班长',4,'采购费用全班AA，我把预算清单发到班级群公示。','cǎi gòu fèi yòng quán bān AA， wǒ bǎ yù suàn qīng dān fā dào bān jí qún gōng shì。','Tiền mua đồ thì cả lớp chia đều nhé, mình sẽ đăng bảng dự trù chi phí lên nhóm lớp cho mọi người xem.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_05','V929','阮明',5,'集合时我站队伍末尾，确保没有人掉队遗漏。','jí hé shí wǒ zhàn duì wǔ mò wěi， què bǎo méi yǒu rén diào duì yí lòu。','Lúc tập trung thì mình đứng cuối hàng, để đảm bảo không ai bị lạc hay sót lại phía sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_06','V929','班长',6,'有你分担工作，集体出游组织轻松很多。','yǒu nǐ fēn dān gōng zuò， jí tǐ chū yóu zǔ zhī qīng sōng hěn duō。','Có cậu phụ giúp thế này, việc tổ chức đi chơi tập thể nhẹ nhàng hơn nhiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_07','V929','阮明',7,'班级集体活动大家互相搭把手，出行更顺利。','bān jí jí tǐ huó dòng dà jiā hù xiāng dā bǎ shǒu， chū xíng gèng shùn lì。','Hoạt động tập thể của lớp mà, mọi người cùng giúp đỡ nhau thì chuyến đi mới suôn sẻ hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT930','SXH5','社团线下团建，协调时间冲突无法到场，提前说明并托人转达祝福',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V930','SIT930','P1','that_bai_nhe','ban_chinh_thuc',NULL,'社团团建无法到场需要提前说明缘由，准备小礼物托人转交表达心意，体现重视社团集体、不失礼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_01','V930','阮明',1,'学姐，团建当天我有汉语等级考试，没办法到场参与活动。','xué jiě， tuán jiàn dàng tiān wǒ yǒu hàn yǔ děng jí kǎo shì， méi bàn fǎ dào chǎng cān yù huó dòng。','Chị ơi, hôm team building em có kỳ thi năng lực tiếng Trung, nên không thể tham gia được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_02','V930','学姐',2,'团建一年只有一次，错过这次集体聚餐有点可惜。','tuán jiàn yī nián zhǐ yǒu yī cì， cuò guò zhè cì jí tǐ jù cān yǒu diǎn kě xī。','Team building một năm chỉ có một lần thôi, bỏ lỡ bữa tiệc tập thể này thì cũng hơi tiếc thật.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_03','V930','阮明',3,'我提前买好社团小伴手礼，托到场的同学分给大家，转达我的祝福。','wǒ tí qián mǎi hǎo shè tuán xiǎo bàn shǒu lǐ， tuō dào chǎng de tóng xué fēn gěi dà jiā， zhuǎn dá wǒ de zhù fú。','Em đã mua sẵn quà lưu niệm nhỏ cho câu lạc bộ rồi, nhờ mấy bạn đến hôm đó chia giúp mọi người, gửi lời chúc của em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_04','V930','学姐',4,'心意我们收下，考试优先，学业比团建重要。','xīn yì wǒ men shōu xià， kǎo shì yōu xiān， xué yè bǐ tuán jiàn zhòng yào。','Tấm lòng của em chị nhận rồi, thi cử là quan trọng nhất, việc học phải ưu tiên hơn team building chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_05','V930','阮明',5,'下次社团小型聚会我一定到场，补上这次缺席。','xià cì shè tuán xiǎo xíng jù huì wǒ yí dìng dào chǎng， bǔ shàng zhè cì quē xí。','Lần tới có buổi họp mặt nhỏ của câu lạc bộ, em nhất định sẽ có mặt để bù lại lần vắng mặt này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_06','V930','学姐',6,'祝你等级考试顺利，不用惦记团建的事。','zhù nǐ děng jí kǎo shì shùn lì， bù yòng diàn jì tuán jiàn de shì。','Chúc em thi năng lực suôn sẻ nhé, đừng bận tâm chuyện team building nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_07','V930','阮明',7,'十分抱歉错过集体团建，麻烦学姐代为向大家致歉。','shí fēn bào qiàn cuò guò jí tǐ tuán jiàn， má fán xué jiě dài wéi xiàng dà jiā zhì qiàn。','Em thật sự xin lỗi vì đã bỏ lỡ buổi team building tập thể, phiền chị nói giúp lời xin lỗi của em với mọi người ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT931','SXH6','朋友频繁借大额现金，委婉说明自身开销，拒绝频繁借钱',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V931','SIT931','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友之间小额应急可互相周转，频繁大额借钱会明确划定边界委婉拒绝，避免金钱损耗友情。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_01','V931','阮明',1,'你最近频繁借大额生活费，我每月家里汇款固定，结余不多。','nǐ zuì jìn pín fán jiè dà é shēng huó fèi， wǒ měi yuè jiā lǐ huì kuǎn gù dìng， jié yú bù duō。','Dạo này cậu hay mượn tiền sinh hoạt số lượng lớn, mà mỗi tháng nhà mình chỉ gửi một khoản cố định, dư ra không nhiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_02','V931','小杨',2,'我临时手头周转不开，才一次次找你借钱应急。','wǒ lín shí shǒu tóu zhōu zhuǎn bù kāi， cái yī cì cì zhǎo nǐ jiè qián yìng jí。','Mình tạm thời xoay xở không kịp nên mới phải nhờ cậu cho mượn tiền để giải quyết gấp thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_03','V931','阮明',3,'小额应急可以帮忙，但大额资金我自身学费、教材开销压力大嘛。','xiǎo é yìng jí kě yǐ bāng máng， dàn dà é zī jīn wǒ zì shēn xué fèi、 jiào cái kāi xiāo yā lì dà ma。','Số tiền nhỏ để ứng phó thì mình giúp được, chứ số lớn thì bản thân mình cũng đang áp lực học phí, tài liệu học tập lắm.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_04','V931','小杨',4,'明白你的难处，之后我尽量自己规划开支不再频繁借钱。','míng bái nǐ de nán chǔ， zhī hòu wǒ jǐn liàng zì jǐ guī huà kāi zhī bù zài pín fán jiè qián。','Mình hiểu khó khăn của cậu, sau này mình sẽ cố tự sắp xếp chi tiêu, không mượn tiền thường xuyên nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_05','V931','阮明',5,'如果是紧急看病这种急事我一定尽力帮忙，日常消费没法长期出借。','rú guǒ shì jǐn jí kàn bìng zhè zhǒng jí shì wǒ yí dìng jìn lì bāng máng， rì cháng xiāo fèi méi fǎ cháng qī chū jiè。','Nếu là chuyện khẩn cấp như đi khám bệnh thì mình chắc chắn sẽ cố hết sức giúp, còn chi tiêu hàng ngày thì mình không thể cho mượn dài hạn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_06','V931','小杨',6,'我理解你的边界，不会再频繁向你借大额钱款。','wǒ lǐ jiě nǐ de biān jiè， bú huì zài pín fán xiàng nǐ jiè dà é qián kuǎn。','Mình hiểu giới hạn của cậu, sẽ không mượn số tiền lớn từ cậu thường xuyên nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_07','V931','阮明',7,'我们维持轻松的朋友关系，不用因为金钱产生隔阂。','wǒ men wéi chí qīng sōng de péng yǒu guān xì， bù yòng yīn wèi jīn qián chǎn shēng gé hé。','Mình cứ giữ tình bạn thoải mái như vậy, đừng vì chuyện tiền bạc mà sinh ra khoảng cách nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT932','SXH6','他人强行推销商品、邀约兼职，礼貌拉开距离明确拒绝',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V932','SIT932','P1','suon_se','ban_chinh_thuc',NULL,'校园内推销、兼职邀约十分常见，礼貌温和但态度明确拒绝，对方不会持续纠缠。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_01','V932','阮明',1,'不好意思，我没有购买护肤品、参与兼职的打算。','bù hǎo yì sī， wǒ méi yǒu gòu mǎi hù fū pǐn、 cān yù jiān zhí de dǎ suàn。','Xin lỗi, mình không có ý định mua mỹ phẩm dưỡng da hay làm thêm gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_02','V932','推销人员',2,'这款产品留学生用很合适，兼职还能赚取生活费。','zhè kuǎn chǎn pǐn liú xué shēng yòng hěn hé shì， jiān zhí hái néng zhuàn qǔ shēng huó fèi。','Sản phẩm này rất phù hợp với du học sinh, còn làm thêm thì có thể kiếm thêm tiền sinh hoạt đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_03','V932','阮明',3,'我课余全部用来复习汉语考试，没有时间做副业兼职嘛。','wǒ kè yú quán bù yòng lái fù xí hàn yǔ kǎo shì， méi yǒu shí jiān zuò fù yè jiān zhí ma。','Thời gian ngoài giờ học mình dành hết để ôn thi tiếng Trung, không có thời gian làm thêm việc phụ đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_04','V932','推销人员',4,'耽误五分钟简单了解一下，不会占用你太久时间。','dān wù wǔ fēn zhōng jiǎn dān liǎo jiě yī xià， bú huì zhàn yòng nǐ tài jiǔ shí jiān。','Chỉ mất năm phút để tìm hiểu sơ qua thôi, sẽ không chiếm nhiều thời gian của bạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_05','V932','阮明',5,'实在没有需求，我要赶回图书馆自习，先失陪了。','shí zài méi yǒu xū qiú， wǒ yào gǎn huí tú shū guǎn zì xí， xiān shī péi le。','Thật sự mình không có nhu cầu, mình phải về thư viện tự học gấp, xin phép đi trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_06','V932','推销人员',6,'好吧，不打扰你学习，有需要再联系我。','hǎo ba， bù dǎ rǎo nǐ xué xí， yǒu xū yào zài lián xì wǒ。','Được rồi, không làm phiền bạn học nữa, khi nào cần thì liên hệ mình nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_07','V932','阮明',7,'感谢介绍，我确实没有相关需求。','gǎn xiè jiè shào， wǒ què shí méi yǒu xiāng guān xū qiú。','Cảm ơn đã giới thiệu, nhưng mình thật sự không có nhu cầu này.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT933','SXH6','很久没联系的老友，主动发消息分享日常、维系友谊',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V933','SIT933','P1','suon_se','tuy_y',NULL,'国内友情不会因为许久不联络直接变淡，主动分享日常、约定线上聊天是维系远距离友谊常用方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_01','V933','阮明',1,'好久不见，最近刷到你朋友圈，想起之前我们一起打球的日子。','hǎo jiǔ bú jiàn， zuì jìn shuā dào nǐ péng yǒu quān， xiǎng qǐ zhī qián wǒ men yì qǐ dǎ qiú de rì zi。','Lâu rồi không gặp, dạo này lướt thấy story cậu, tự nhiên nhớ hồi mình hay đi đánh bóng chung ghê.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_02','V933','阿凯',2,'确实很久没聊天，你在中国留学生活还适应吗？','què shí hěn jiǔ méi liáo tiān， nǐ zài zhōng guó liú xué shēng huó hái shì yìng ma？','Ừ đúng là lâu lắm rồi không nói chuyện, cậu du học bên Trung Quốc sống ổn không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_03','V933','阮明',3,'一切顺利，汉语进步不少，拍了很多校园风景照片。','yī qiè shùn lì， hàn yǔ jìn bù bù shǎo， pāi le hěn duō xiào yuán fēng jǐng zhào piān。','Mọi thứ đều ổn, tiếng Trung tiến bộ nhiều, mình còn chụp cả đống ảnh cảnh trường nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_04','V933','阿凯',4,'有空周末线上视频，聊聊各自近期的学习生活。','yǒu kòng zhōu mò xiàn shàng shì pín， liáo liáo gè zì jìn qī de xué xí shēng huó。','Cuối tuần rảnh thì video call nói chuyện đi, kể cho nhau nghe chuyện học hành gần đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_05','V933','阮明',5,'这周日晚上七点我有空，准时线上跟你聊天叙旧。','zhè zhōu rì wǎn shàng qī diǎn wǒ yǒu kòng， zhǔn shí xiàn shàng gēn nǐ liáo tiān xù jiù。','Chủ nhật này bảy giờ tối mình rảnh, đúng giờ lên mạng buôn chuyện với cậu nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_06','V933','阿凯',6,'好，到时候线上碰面，多聊聊近况。','hǎo， dào shí hòu xiàn shàng pèng miàn， duō liáo liáo jìn kuàng。','Ok, lúc đó gặp online, tám chuyện gần đây nhiều vào nha.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_07','V933','阮明',7,'许久不联系也要偶尔分享日常，别慢慢疏远。','xǔ jiǔ bù lián xì yě yào ǒu ěr fēn xiǎng rì cháng， bié màn màn shū yuǎn。','Dù lâu không liên lạc thì thỉnh thoảng cũng phải chia sẻ chuyện thường ngày chứ, đừng để xa dần nhau nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT934','SXH6','朋友过度打探家庭、生活费隐私，温和转移话题守住边界',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V934','SIT934','P1','twist','tuy_y',NULL,'国内社交不会过度追问收入、家庭条件等隐私，若对方过度打探，温和转移话题是委婉守住边界的礼貌方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_01','V934','阮明',1,'生活费够用就行，我们换个话题聊聊周末去哪游玩吧。','shēng huó fèi gòu yòng jiù xíng， wǒ men huàn gè huà tí liáo liáo zhōu mò qù nǎ yóu wán ba。','Tiền sinh hoạt đủ xài là được rồi, đổi chủ đề đi, nói chuyện cuối tuần đi chơi đâu đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_02','V934','小周',2,'只是好奇问问，你家里每月给你汇多少越南盾？','zhǐ shì hào qí wèn wèn， nǐ jiā lǐ měi yuè gěi nǐ huì duō shǎo yuè nán dùn？','Tò mò hỏi vậy thôi, chứ nhà cậu mỗi tháng gửi cho cậu bao nhiêu tiền Việt vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_03','V934','阮明',3,'各国家庭收支习惯不一样，不太习惯细说家庭财务情况嘛。','gè guó jiā tíng shōu zhī xí guàn bù yí yàng， bù tài xí guàn xì shuō jiā tíng cái wù qíng kuàng ma。','Mỗi nước có thói quen chi tiêu gia đình khác nhau, mình không quen kể chi tiết chuyện tài chính nhà mình lắm.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_04','V934','小周',4,'抱歉，我不知道这是你的隐私，我之后不会再追问这类问题。','bào qiàn， wǒ bù zhī dào zhè shì nǐ de yǐn sī， wǒ zhī hòu bú huì zài zhuī wèn zhè lèi wèn tí。','Xin lỗi, mình không biết đây là chuyện riêng tư của cậu, sau này mình sẽ không hỏi mấy chuyện này nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_05','V934','阮明',5,'没关系，我们聊聊校园文艺晚会的节目更有意思。','méi guān xì， wǒ men liáo liáo xiào yuán wén yì wǎn huì de jié mù gèng yǒu yì si。','Không sao đâu, mình nói chuyện về mấy tiết mục văn nghệ của trường còn thú vị hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_06','V934','小周',6,'好，我们聊晚会，不聊私人家庭收支话题。','hǎo， wǒ men liáo wǎn huì， bù liáo sī rén jiā tíng shōu zhī huà tí。','Ừ, mình nói về đêm văn nghệ thôi, không đụng tới chuyện thu chi riêng tư nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_07','V934','阮明',7,'感谢理解，各自保留一点私人空间相处更舒服。','gǎn xiè lǐ jiě， gè zì bǎo liú yì diǎn sī rén kōng jiān xiāng chǔ gèng shū fú。','Cảm ơn cậu đã hiểu, ai cũng giữ chút không gian riêng thì chơi với nhau thoải mái hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT935','SXH6','毕业前夕和要好的朋友约定，回国后定期线上联络',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V935','SIT935','P1','suon_se','ban_chinh_thuc',NULL,'毕业分离时好友会主动约定长期联络方式，国内年轻人十分看重长久稳定的友谊，不会因异地轻易断联。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_01','V935','阮明',1,'等我毕业回越南，我们也要保持联系，不能慢慢断了往来。','děng wǒ bì yè huí yuè nán， wǒ men yě yào bǎo chí lián xì， bù néng màn màn duàn le wǎng lái。','Đợi mình tốt nghiệp về Việt Nam rồi, chúng ta cũng phải giữ liên lạc, không thể để dần dần mất kết nối được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_02','V935','苏雯',2,'放心，每月固定一次线上视频，分享各自工作、生活近况。','fàng xīn， měi yuè gù dìng yī cì xiàn shàng shì pín， fēn xiǎng gè zì gōng zuò、 shēng huó jìn kuàng。','Yên tâm đi, mỗi tháng cố định một lần video call, chia sẻ tình hình công việc, cuộc sống của nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_03','V935','阮明',3,'节假日互相寄本国小特产，线上聊天弥补不能线下见面的遗憾。','jié jià rì hù xiāng jì běn guó xiǎo tè chǎn， xiàn shàng liáo tiān mí bǔ bù néng xiàn xià jiàn miàn de yí hàn。','Ngày lễ thì gửi cho nhau chút đặc sản quê mình, rồi nói chuyện online để bù lại việc không gặp trực tiếp được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_04','V935','苏雯',4,'不管距离多远，我们的友谊不会因为回国分开变淡。','bù guǎn jù lí duō yuǎn， wǒ men de yǒu yì bú huì yīn wèi huí guó fēn kāi biàn dàn。','Dù khoảng cách xa đến đâu, tình bạn của chúng ta cũng sẽ không nhạt đi chỉ vì cậu về nước đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_05','V935','阮明',5,'回国之后时差一小时，提前约定双方都空闲的视频时段。','huí guó zhī hòu shí chà yī xiǎo shí， tí qián yuē dìng shuāng fāng dōu kòng xián de shì pín shí duàn。','Sau khi về nước lệch múi giờ một tiếng, nên hẹn trước khung giờ mà cả hai đều rảnh để video call.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_06','V935','苏雯',6,'我记好约定，毕业之后按时线上叙旧。','wǒ jì hǎo yuē dìng， bì yè zhī hòu àn shí xiàn shàng xù jiù。','Mình ghi nhớ hẹn rồi, sau khi tốt nghiệp sẽ đúng giờ lên mạng ôn lại chuyện xưa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_07','V935','阮明',7,'很幸运在校期间认识你，长久维持这份跨国友谊。','hěn xìng yùn zài xiào qī jiān rèn shí nǐ， cháng jiǔ wéi chí zhè fèn kuà guó yǒu yì。','Thật may mắn vì đã quen được cậu trong thời gian học ở trường, mong tình bạn xuyên quốc gia này sẽ bền lâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1001','SKC1','深夜高烧腹泻无校医，求助室友陪同去校外急诊',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1001','SIT1001','P1','twist','tuy_y',NULL,'国内多数高校校医仅白天值班，夜间急症只能前往社区24小时医院，室友之间临时垫付医药费是很常见的互助方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_01','V1001','阮明',1,'晓晓，你醒一下好不好，我难受得快撑不住啦。','xiǎo xiǎo， nǐ xǐng yī xià hǎo bù hǎo， wǒ nán shòu dé kuài chēng bú zhù la。','晓晓ơi, cậu dậy một chút được không, tớ khó chịu sắp chịu không nổi rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_02','V1001','林晓',2,'怎么了明哥？现在都凌晨两点了，你哪里不舒服啊？','zěn me le míng gē？ xiàn zài dōu líng chén liǎng diǎn le， nǐ nǎ lǐ bù shū fú a？','Sao vậy anh 明? Bây giờ hai giờ sáng rồi, anh khó chịu ở đâu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_03','V1001','阮明',3,'我突然发高烧，还一直拉肚子，浑身发软走不动路呢。','wǒ tū rán fā gāo shāo， hái yì zhí lā dù zi， hún shēn fā ruǎn zǒu bù dòng lù ne。','Tớ đột nhiên sốt cao, lại còn tiêu chảy liên tục, người mềm nhũn không đi nổi nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_04','V1001','林晓',4,'天呐，校医室早就关门了，要不我陪你去附近的24小时急诊吧？','tiān nà， xiào yī shì zǎo jiù guān mén le， yào bù wǒ péi nǐ qù fù jìn de 24 xiǎo shí jí zhěn ba？','Trời ơi, phòng y tế trường đóng cửa từ lâu rồi, hay để tớ đưa cậu đi phòng cấp cứu 24 giờ gần đây nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_05','V1001','阮明',5,'可以吗？可是我身上现金不多，手机支付也有点麻烦诶。','kě yǐ ma？ kě shì wǒ shēn shàng xiàn jīn bù duō， shǒu jī zhī fù yě yǒu diǎn má fán éi。','Được không? Nhưng tớ không mang nhiều tiền mặt, thanh toán qua điện thoại cũng hơi bất tiện.','AM12');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_06','V1001','林晓',6,'没事，我先帮你垫付医药费，之后你再转我就行，先看病要紧吧。','méi shì， wǒ xiān bāng nǐ diàn fù yī yào fèi， zhī hòu nǐ zài zhuǎn wǒ jiù xíng， xiān kàn bìng yào jǐn ba。','Không sao, để tớ ứng tiền viện phí trước, sau đó cậu chuyển lại cho tớ là được, giờ đi khám bệnh mới là quan trọng.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_07','V1001','阮明',7,'太谢谢你了，我现在站起来都头晕，得麻烦你扶我一下啦。','tài xiè xiè nǐ le， wǒ xiàn zài zhàn qǐ lái dōu tóu yūn， dé má fán nǐ fú wǒ yī xià la。','Cảm ơn cậu nhiều lắm, giờ tớ đứng dậy cũng thấy chóng mặt, phiền cậu đỡ tớ một tay nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_08','V1001','林晓',8,'别客气，快披上厚外套，外面夜里风很大，我们马上出门。','bié kè qì， kuài pī shàng hòu wài tào， wài miàn yè lǐ fēng hěn dà， wǒ men mǎ shàng chū mén。','Đừng khách sáo, mau khoác thêm áo ấm vào, ngoài trời đêm gió to lắm, mình đi ngay đây.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1002','SKC1','宿舍水管爆裂积水，紧急联系后勤抢修止损',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1002','SIT1002','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍后勤维修分时段报修，突发漏水这类险情可直接拨打应急专线，不用走线上预约流程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_01','V1002','阮明',1,'张师傅您好，我是3栋402宿舍的留学生阮明，出事了！','zhāng shī fù nín hǎo， wǒ shì 3 dòng 402 sù shè de liú xué shēng ruǎn míng， chū shì le！','Chào chú 张, cháu là 阮明, du học sinh phòng 402 tòa nhà 3, có chuyện rồi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_02','V1002','张师傅',2,'同学别慌，慢慢说，宿舍里面发生什么事啦？','tóng xué bié huāng， màn màn shuō， sù shè lǐ miàn fā shēng shén me shì la？','Em đừng hoảng, từ từ nói, trong phòng xảy ra chuyện gì vậy?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_03','V1002','阮明',3,'卫生间水龙头水管突然爆裂，地上全是积水，快漫到书桌了啊。','wèi shēng jiān shuǐ lóng tóu shuǐ guǎn tū rán bào liè， dì shàng quán shì jī shuǐ， kuài màn dào shū zhuō le a。','Ống nước vòi rửa trong nhà vệ sinh đột nhiên vỡ, nước tràn khắp sàn, sắp lan tới cả bàn học rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_04','V1002','张师傅',4,'我知道了，你先把卫生间总水阀关掉，防止水继续流出来吧。','wǒ zhī dào le， nǐ xiān bǎ wèi shēng jiān zǒng shuǐ fá guān diào， fáng zhǐ shuǐ jì xù liú chū lái ba。','Chú biết rồi, em khóa van nước tổng của nhà vệ sinh lại trước đã, để nước khỏi chảy tiếp ra ngoài.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_05','V1002','阮明',5,'我刚试过，总阀拧不动，完全关不上，积水越积越多呢。','wǒ gāng shì guò， zǒng fá níng bù dòng， wán quán guān bù shàng， jī shuǐ yuè jī yuè duō ne。','Cháu vừa thử rồi, van tổng vặn không được, khóa không nổi, nước cứ dâng lên mãi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_06','V1002','张师傅',6,'行，我现在带上工具十分钟就上楼，你先用拖把、脸盆先舀水控水。','xíng， wǒ xiàn zài dài shàng gōng jù shí fēn zhōng jiù shàng lóu， nǐ xiān yòng tuō bǎ、 liǎn pén xiān yǎo shuǐ kòng shuǐ。','Được, chú mang dụng cụ lên ngay, mười phút nữa lên đến nơi, em cứ dùng cây lau nhà, chậu để tát nước ra trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_07','V1002','阮明',7,'好的师傅，我马上清理积水，麻烦您尽快过来，怕泡坏地板。','hǎo de shī fù， wǒ mǎ shàng qīng lǐ jī shuǐ， má fán nín jǐn kuài guò lái， pà pào huài dì bǎn。','Vâng chú, cháu dọn nước ngay đây, phiền chú qua sớm giúp cháu, sợ ngâm hỏng sàn nhà mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_08','V1002','张师傅',8,'放心，我这边立刻出发，到宿舍楼下给你打电话。','fàng xīn， wǒ zhè biān lì kè chū fā， dào sù shè lóu xià gěi nǐ dǎ diàn huà。','Yên tâm đi, chú đi ngay bây giờ, tới dưới tòa nhà chú sẽ gọi điện cho em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1003','SKC1','就餐食物严重过敏无抗过敏药，同学送医急救',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1003','SIT1003','P1','twist','tuy_y',NULL,'国内医院急诊可先救治后补登记证件，留学生就诊出示居留许可即可登记。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_01','V1003','阮明',1,'小雨，我身上起了好多红疹，喘不上气，好像过敏了啊。','xiǎo yǔ， wǒ shēn shàng qǐ le hǎo duō hóng zhěn， chuǎn bù shàng qì， hǎo xiàng guò mǐn le a。','小雨 ơi, người tớ nổi đầy mẩn đỏ, khó thở nữa, hình như bị dị ứng rồi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_02','V1003','陈雨',2,'你中午吃什么东西了？宿舍有没有备抗过敏药呢？','nǐ zhōng wǔ chī shén me dōng xī le？ sù shè yǒu méi yǒu bèi kàng guò mǐn yào ne？','Trưa nay cậu ăn gì vậy? Trong phòng có sẵn thuốc chống dị ứng không?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_03','V1003','阮明',3,'中午食堂的海鲜小炒，我没带过敏药，喉咙越来越肿啦。','zhōng wǔ shí táng de hǎi xiān xiǎo chǎo， wǒ méi dài guò mǐn yào， hóu lóng yuè lái yuè zhǒng la。','Trưa nay tớ ăn món hải sản xào ở căng tin, tớ không mang thuốc dị ứng, họng sưng lên ngày càng to rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_04','V1003','陈雨',4,'情况不对劲，不能硬扛，我现在骑车带你去医院急诊吧。','qíng kuàng bú duì jìn， bù néng yìng káng， wǒ xiàn zài qí chē dài nǐ qù yī yuàn jí zhěn ba。','Tình hình không ổn rồi, không thể ráng chịu được, để tớ chở cậu bằng xe đạp đi cấp cứu bệnh viện ngay.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_05','V1003','阮明',5,'可是我身份证、居留卡都放在宿舍柜子里，没随身带诶。','kě shì wǒ shēn fèn zhèng、 jū liú kǎ dōu fàng zài sù shè guì zi lǐ， méi suí shēn dài éi。','Nhưng chứng minh thư, thẻ cư trú của tớ đều để trong tủ ở phòng, không mang theo người.','AM12');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_06','V1003','陈雨',6,'先去医院，我跟辅导员说明情况，等下回宿舍帮你取证件。','xiān qù yī yuàn， wǒ gēn fǔ dǎo yuán shuō míng qíng kuàng， děng xià huí sù shè bāng nǐ qǔ zhèng jiàn。','Đi bệnh viện trước đã, tớ sẽ nói rõ tình hình với cô chủ nhiệm, lát nữa quay về phòng lấy giấy tờ giúp cậu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_07','V1003','阮明',7,'真的太麻烦你了，我现在手脚都有点发麻，站不稳。','zhēn de tài má fán nǐ le， wǒ xiàn zài shǒu jiǎo dōu yǒu diǎn fā má， zhàn bù wěn。','Thật sự phiền cậu quá, giờ tay chân tớ hơi tê, đứng không vững nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_08','V1003','陈雨',8,'别说话，扶好我，我们现在立刻往校门口医院赶。','bié shuō huà， fú hǎo wǒ， wǒ men xiàn zài lì kè wǎng xiào mén kǒu yī yuàn gǎn。','Đừng nói nữa, bám chắc vào tớ, mình đi ngay đến bệnh viện ở cổng trường.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1004','SKC1','宿舍大功率电器短路冒烟断电，联系宿管排查隐患',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1004','SIT1004','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍严禁大功率电煮锅、电暖锅等电器，违规使用引发电路故障需自行承担维修损失。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_01','V1004','阮明',1,'李阿姨，我是5栋206的阮明，宿舍插座冒烟跳闸了！','lǐ ā yí， wǒ shì 5 dòng 206 de ruǎn míng， sù shè chā zuò mào yān tiào zhá le！','Cô 李 ơi, cháu là 阮明 ở phòng 206 tòa 5, ổ cắm phòng cháu bốc khói rồi nhảy aptomat luôn ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_02','V1004','李宿管',2,'你先别靠近插座，有没有用水去碰线路啊？','nǐ xiān bié kào jìn chā zuò， yǒu méi yǒu yòng shuǐ qù pèng xiàn lù a？','Em đừng lại gần ổ cắm, có dùng nước chạm vào dây điện không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_03','V1004','阮明',3,'没有，我第一时间拔掉了所有插头，房间现在完全断电了呢。','méi yǒu， wǒ dì yī shí jiān bá diào le suǒ yǒu chā tóu， fáng jiān xiàn zài wán quán duàn diàn le ne。','Không ạ, cháu rút hết tất cả phích cắm ngay lập tức, phòng bây giờ mất điện hoàn toàn rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_04','V1004','李宿管',4,'是什么电器在用的时候出问题的，大功率电煮锅吗？','shì shén me diàn qì zài yòng de shí hòu chū wèn tí de， dà gōng lǜ diàn zhǔ guō ma？','Là thiết bị điện nào gây ra sự cố vậy, nồi điện công suất lớn à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_05','V1004','阮明',5,'对，我刚煮完汤，一拔插头插座就冒出黑烟，吓死我了。','duì， wǒ gāng zhǔ wán tāng， yī bá chā tóu chā zuò jiù mào chū hēi yān， xià sǐ wǒ le。','Vâng, cháu vừa nấu xong nồi canh, vừa rút phích cắm là ổ điện bốc khói đen luôn, sợ chết đi được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_06','V1004','李宿管',6,'我马上带电工过来检查电路，你们宿舍近期先别使用大功率厨具。','wǒ mǎ shàng dài diàn gōng guò lái jiǎn chá diàn lù， nǐ men sù shè jìn qī xiān bié shǐ yòng dà gōng lǜ chú jù。','Cô sẽ dẫn thợ điện lên kiểm tra đường dây ngay, thời gian tới phòng các em tạm thời đừng dùng dụng cụ bếp công suất lớn nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_07','V1004','阮明',7,'好的阿姨，我不会再私自用电锅，等电工确认安全再说吧。','hǎo de ā yí， wǒ bú huì zài sī zì yòng diàn guō， děng diàn gōng què rèn ān quán zài shuō ba。','Vâng cô ạ, cháu sẽ không tự ý dùng nồi điện nữa đâu, để thợ điện xác nhận an toàn rồi tính tiếp ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_08','V1004','李宿管',8,'你们先在走廊稍等片刻，避免电路残留隐患伤到你们。','nǐ men xiān zài zǒu láng shāo děng piàn kè， bì miǎn diàn lù cán liú yǐn huàn shāng dào nǐ men。','Các em cứ đợi ở hành lang một lát, tránh để nguy cơ điện còn sót lại làm các em bị thương.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1005','SKC1','晾晒衣物坠落楼下险些砸伤路人，下楼道歉处理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1005','SIT1005','P1','that_bai_nhe','tuy_y',NULL,'国内居民楼、学生公寓高空坠物属于危险行为，一旦伤人需承担全部赔偿责任，物业会对违规住户通报批评。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_01','V1005','阮明',1,'阿姨实在对不起！刚才衣服从阳台掉下来，差点砸到您了吧？','ā yí shí zài duì bù qǐ！ gāng cái yī fú cóng yáng tái diào xià lái， chà diǎn zá dào nín le ba？','Cô ơi cháu xin lỗi thật đấy! Vừa nãy quần áo từ ban công rơi xuống, suýt trúng cô phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_02','V1005','王阿姨',2,'小伙子，你这衣服飘下来吓我一跳，还好我及时躲开了啊。','xiǎo huǒ zi， nǐ zhè yī fú piāo xià lái xià wǒ yī tiào， hái hǎo wǒ jí shí duǒ kāi le a。','Cậu trai này, quần áo bay xuống làm cô giật cả mình, may mà cô né kịp đấy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_03','V1005','阮明',3,'都怪我没把晾衣架固定牢，我现在马上捡起来，真的很抱歉呢。','dōu guài wǒ méi bǎ liàng yī jià gù dìng láo， wǒ xiàn zài mǎ shàng jiǎn qǐ lái， zhēn de hěn bào qiàn ne。','Đều tại cháu không cố định giá phơi đồ cho chắc, cháu nhặt lên ngay đây, thật sự xin lỗi cô ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_04','V1005','王阿姨',4,'下次一定要注意，楼下行人很多，砸到人后果可就严重啦。','xià cì yí dìng yào zhù yì， lóu xià xíng rén hěn duō， zá dào rén hòu guǒ kě jiù yán zhòng la。','Lần sau nhớ chú ý nhé, dưới này người qua lại đông lắm, lỡ trúng ai thì hậu quả nghiêm trọng đấy.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_05','V1005','阮明',5,'我记住了，以后晾晒一定加固，不会再发生这种事了。','wǒ jì zhù le， yǐ hòu liàng shài yí dìng jiā gù， bú huì zài fā shēng zhè zhǒng shì le。','Cháu nhớ rồi ạ, sau này phơi đồ cháu nhất định gia cố lại, sẽ không để xảy ra chuyện này nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_06','V1005','王阿姨',6,'光说没用，刚刚还有小朋友在楼下玩，万一砸伤孩子怎么办？','guāng shuō méi yòng， gāng gāng hái yǒu xiǎo péng yǒu zài lóu xià wán， wàn yī zá shāng hái zi zěn me bàn？','Nói suông thì có ích gì, vừa nãy còn có mấy đứa trẻ chơi ở dưới này, lỡ trúng con nít thì sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_07','V1005','阮明',7,'是我考虑不周，我这就上楼换更稳固的晾晒支架。','shì wǒ kǎo lǜ bù zhōu， wǒ zhè jiù shàng lóu huàn gèng wěn gù de liàng shài zhī jià。','Là cháu suy nghĩ chưa chu đáo, cháu lên phòng đổi ngay giá phơi đồ chắc chắn hơn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_08','V1005','王阿姨',8,'行，下次多留心，这次我就不跟宿管反映了。','xíng， xià cì duō liú xīn， zhè cì wǒ jiù bù gēn sù guǎn fǎn yìng le。','Được rồi, lần sau chú ý hơn nhé, lần này cô sẽ không phản ánh với ban quản lý ký túc xá đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1006','SKC1','夜间突发眩晕耳鸣无法行走，拨打校内24小时应急电话',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1006','SIT1006','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有24小时学生应急值班专线，仅限夜间突发身体、安全险情使用，日常小事不建议拨打。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_01','V1006','阮明',1,'您好，这里是留学生公寓6栋301，我是越南学生阮明，现在身体很不舒服。','nín hǎo， zhè lǐ shì liú xué shēng gōng yù 6 dòng 301， wǒ shì yuè nán xué shēng ruǎn míng， xiàn zài shēn tǐ hěn bù shū fú。','Xin chào, đây là phòng 301 tòa 6 khu ký túc du học sinh, em là sinh viên Việt Nam 阮明, hiện giờ em thấy rất khó chịu trong người.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_02','V1006','王老师',2,'同学你别着急，慢慢讲，你现在是什么症状呢？','tóng xué nǐ bié zháo jí， màn màn jiǎng， nǐ xiàn zài shì shén me zhèng zhuàng ne？','Em đừng lo lắng, từ từ nói, em đang có triệu chứng gì vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_03','V1006','阮明',3,'我突然严重耳鸣，天旋地转，根本没办法站起来走路啊。','wǒ tū rán yán zhòng ěr míng， tiān xuán dì zhuàn， gēn běn méi bàn fǎ zhàn qǐ lái zǒu lù a。','Em đột nhiên bị ù tai nặng, trời đất quay cuồng, hoàn toàn không đứng dậy đi lại được ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_04','V1006','王老师',4,'房间里现在有人陪同你吗，身边有没有热水、止痛药？','fáng jiān lǐ xiàn zài yǒu rén péi tóng nǐ ma， shēn biān yǒu méi yǒu rè shuǐ、 zhǐ tòng yào？','Trong phòng hiện có ai ở cùng em không, bên cạnh có nước ấm hay thuốc giảm đau không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_05','V1006','阮明',5,'室友今天回家了，只有我一个人在宿舍，什么药都没有呢。','shì yǒu jīn tiān huí jiā le， zhǐ yǒu wǒ yí gè rén zài sù shè， shén me yào dōu méi yǒu ne。','Bạn cùng phòng hôm nay về nhà rồi, chỉ có mình em trong phòng, không có thuốc gì cả ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_06','V1006','王老师',6,'我马上联系校应急医护人员上楼，你先靠在床边不要乱动。','wǒ mǎ shàng lián xì xiào yìng jí yī hù rén yuán shàng lóu， nǐ xiān kào zài chuáng biān bú yào luàn dòng。','Thầy liên hệ nhân viên y tế khẩn cấp của trường lên ngay, em cứ dựa vào cạnh giường, đừng cử động lung tung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_07','V1006','阮明',7,'麻烦您快一点，我现在闭上眼睛都还是不停头晕。','má fán nín kuài yì diǎn， wǒ xiàn zài bì shàng yǎn jīng dōu hái shì bù tíng tóu yūn。','Phiền thầy nhanh lên giúp em, giờ em nhắm mắt lại mà vẫn cứ chóng mặt không ngừng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_08','V1006','王老师',8,'五分钟内医护人员就到，保持电话畅通，有情况随时跟我说。','wǔ fēn zhōng nèi yī hù rén yuán jiù dào， bǎo chí diàn huà chàng tōng， yǒu qíng kuàng suí shí gēn wǒ shuō。','Trong vòng năm phút nhân viên y tế sẽ tới, giữ điện thoại thông suốt nhé, có gì cứ báo ngay cho thầy.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1007','SKC1','网约车司机恶意绕道加价，拨打平台客服紧急维权',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1007','SIT1007','P1','twist','chinh_thuc',NULL,'国内网约车全程平台计价，司机私下索要现金加价属于违规，乘客可直接留存录音、行程记录投诉全额退款。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_01','V1007','阮明',1,'您好，我要投诉刚才接单的网约车司机，存在恶意绕道加价行为。','nín hǎo， wǒ yào tóu sù gāng cái jiē dān de wǎng yuē chē sī jī， cún zài è yì rào dào jiā jià xíng wéi。','Xin chào, tôi muốn khiếu nại tài xế xe công nghệ vừa nhận chuyến, có hành vi cố ý đi vòng để tính thêm tiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_02','V1007','客服',2,'您好先生，请提供您的订单编号，我这边调取行程记录核对吧。','nín hǎo xiān shēng， qǐng tí gōng nín de dìng dān biān hào， wǒ zhè biān diào qǔ xíng chéng jì lù hé duì ba。','Chào anh, xin anh cung cấp mã đơn hàng, phía chúng tôi sẽ kiểm tra lại lịch trình di chuyển ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_03','V1007','阮明',3,'订单编号是724915，明明导航直达，司机故意绕远路还多收钱呢。','dìng dān biān hào shì 724915， míng míng dǎo háng zhí dá， sī jī gù yì rào yuǎn lù hái duō shōu qián ne。','Mã đơn là 724915, rõ ràng chỉ đường đi thẳng mà tài xế cố tình đi vòng đường xa rồi còn tính thêm tiền.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_04','V1007','客服',4,'我查看路线了，确实存在偏离导航的绕行路段，非常抱歉给您带来不好体验。','wǒ chá kàn lù xiàn le， què shí cún zài piān lí dǎo háng de rào xíng lù duàn， fēi cháng bào qiàn gěi nín dài lái bù hǎo tǐ yàn。','Tôi đã kiểm tra lộ trình rồi, đúng là có đoạn đường đi lệch khỏi chỉ dẫn, rất xin lỗi vì đã mang đến trải nghiệm không tốt cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_05','V1007','阮明',5,'司机还态度很差，直接跟我索要额外现金，不接受线上结算啊。','sī jī hái tài dù hěn chà， zhí jiē gēn wǒ suǒ yào é wài xiàn jīn， bù jiē shòu xiàn shàng jié suàn a。','Tài xế còn thái độ rất tệ, trực tiếp đòi tôi trả thêm tiền mặt, không chấp nhận thanh toán trực tuyến.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_06','V1007','客服',6,'我们会对司机进行处罚，多收取的费用会在1-3个工作日原路退还。','wǒ men huì duì sī jī jìn xíng chǔ fá， duō shōu qǔ de fèi yòng huì zài 1-3 gè gōng zuò rì yuán lù tuì huán。','Chúng tôi sẽ xử phạt tài xế, khoản tiền thu thêm sẽ được hoàn trả về đúng phương thức thanh toán trong 1-3 ngày làm việc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_07','V1007','阮明',7,'能不能尽快处理？我等下还要打车去学校，担心再遇到同类情况。','néng bù néng jǐn kuài chǔ lǐ？ wǒ děng xià hái yào dǎ chē qù xué xiào， dān xīn zài yù dào tóng lèi qíng kuàng。','Có thể xử lý nhanh giúp tôi không? Lát nữa tôi còn phải bắt xe đi học, sợ lại gặp tình huống tương tự.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_08','V1007','客服',8,'我这边加急标记您的投诉单，处理结果会以短信通知您的。','wǒ zhè biān jiā jí biāo jì nín de tóu sù dān， chǔ lǐ jié guǒ huì yǐ duǎn xìn tōng zhī nín de。','Tôi sẽ đánh dấu khẩn cấp đơn khiếu nại của anh, kết quả xử lý sẽ được thông báo qua tin nhắn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1008','SKC1','骑行共享单车摔倒扭伤，向路人求助简单伤口处理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1008','SIT1008','P1','suon_se','tuy_y',NULL,'国内很多年轻人会随身备简易消毒用品，路人遇到受伤行人大多愿意主动提供临时帮助。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_01','V1008','阮明',1,'不好意思打扰一下，我骑车摔倒擦伤膝盖，您有碘伏吗？','bù hǎo yì sī dǎ rǎo yī xià， wǒ qí chē shuāi dǎo cā shāng xī gài， nín yǒu diǎn fú ma？','Xin lỗi làm phiền một chút, tớ đi xe đạp bị ngã trầy đầu gối, cậu có cồn i-ốt không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_02','V1008','刘姑娘',2,'哎呀，你摔得看着挺疼的，我包里刚好有消毒湿巾和创可贴呢。','āi yā， nǐ shuāi dé kàn zhe tǐng téng de， wǒ bāo lǐ gāng hǎo yǒu xiāo dú shī jīn hé chuàng kě tiē ne。','Ôi, cậu ngã trông đau thế, trong túi tớ vừa hay có khăn khử trùng với băng cá nhân đây.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_03','V1008','阮明',3,'太感谢你了，刚才刹车打滑摔在路边，伤口一直在流血啊。','tài gǎn xiè nǐ le， gāng cái shā chē dǎ huá shuāi zài lù biān， shāng kǒu yì zhí zài liú xiě a。','Cảm ơn cậu nhiều lắm, vừa nãy phanh gấp bị trượt ngã bên đường, vết thương cứ chảy máu mãi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_04','V1008','刘姑娘',4,'你先坐在台阶上别动，我帮你清理一下伤口，别沾到灰尘吧。','nǐ xiān zuò zài tái jiē shàng bié dòng， wǒ bāng nǐ qīng lǐ yī xià shāng kǒu， bié zhān dào huī chén ba。','Cậu ngồi yên trên bậc thềm đi đừng cử động, để tớ lau vết thương giúp cậu, kẻo dính bụi bẩn vào.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_05','V1008','阮明',5,'好，麻烦你了，我自己没随身携带急救小物件，太疏忽了。','hǎo， má fán nǐ le， wǒ zì jǐ méi suí shēn xié dài jí jiù xiǎo wù jiàn， tài shū hū le。','Ừ, phiền cậu rồi, tớ không mang theo đồ sơ cứu bên người, đúng là sơ suất quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_06','V1008','刘姑娘',6,'下次骑车慢一点，雨天路面滑很容易摔倒，记得小心一点。','xià cì qí chē màn yì diǎn， yǔ tiān lù miàn huá hěn róng yì shuāi dǎo， jì de xiǎo xīn yì diǎn。','Lần sau đi xe chậm lại nhé, trời mưa đường trơn dễ ngã lắm, nhớ cẩn thận hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_07','V1008','阮明',7,'我记住啦，处理完我自己慢慢扶车回去，不耽误你赶路。','wǒ jì zhù la， chǔ lǐ wán wǒ zì jǐ màn màn fú chē huí qù， bù dān wù nǐ gǎn lù。','Tớ nhớ rồi, xử lý xong tớ tự dắt xe đi từ từ về, không làm chậm trễ việc của cậu đâu.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1009','SKC1','外出迷路手机没电关机，向商铺店员借手机联系好友',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1009','SIT1009','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内商铺店主出于防骗顾虑，大多不愿外借私人手机，街边共享充电宝是外出应急充电主流方案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_01','V1009','阮明',1,'老板您好，不好意思打扰，我的手机没电关机了，能借您手机打个电话吗？','lǎo bǎn nín hǎo， bù hǎo yì sī dǎ rǎo， wǒ de shǒu jī méi diàn guān jī le， néng jiè nín shǒu jī dǎ gè diàn huà ma？','Chào ông chủ, xin lỗi làm phiền, điện thoại tôi hết pin tắt máy rồi, ông cho tôi mượn điện thoại gọi một cuộc được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_02','V1009','赵老板',2,'借手机可以，你先说一下要联系谁，打多久电话呀？','jiè shǒu jī kě yǐ， nǐ xiān shuō yī xià yào lián xì shuí， dǎ duō jiǔ diàn huà ya？','Mượn điện thoại thì được, nhưng cậu nói trước xem định gọi cho ai, gọi bao lâu vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_03','V1009','阮明',3,'我和同学走散迷路了，就打两分钟，跟他说我现在的位置就行呢。','wǒ hé tóng xué zǒu sàn mí lù le， jiù dǎ liǎng fēn zhōng， gēn tā shuō wǒ xiàn zài de wèi zhì jiù xíng ne。','Tôi với bạn học đi lạc mất nhau rồi, chỉ gọi tầm hai phút thôi, báo cho bạn ấy biết vị trí của tôi bây giờ là được.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_04','V1009','赵老板',4,'现在陌生人借手机诈骗太多，我不太方便直接把手机给你啊。','xiàn zài mò shēng rén jiè shǒu jī zhà piàn tài duō， wǒ bù tài fāng biàn zhí jiē bǎ shǒu jī gěi nǐ a。','Giờ người lạ mượn điện thoại để lừa đảo nhiều lắm, tôi không tiện đưa thẳng điện thoại cho cậu đâu.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_05','V1009','阮明',5,'我是附近大学的留学生，可以出示我的居留卡给您看证明身份。','wǒ shì fù jìn dà xué de liú xué shēng， kě yǐ chū shì wǒ de jū liú kǎ gěi nín kàn zhèng míng shēn fèn。','Tôi là du học sinh trường đại học gần đây, tôi có thể đưa thẻ cư trú ra cho ông xem để chứng minh thân phận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_06','V1009','赵老板',6,'证件我也不方便仔细核对，你去对面便利店租借共享充电宝吧。','zhèng jiàn wǒ yě bù fāng biàn zǐ xì hé duì， nǐ qù duì miàn biàn lì diàn zū jiè gòng xiǎng chōng diàn bǎo ba。','Giấy tờ tôi cũng không tiện kiểm tra kỹ đâu, cậu qua cửa hàng tiện lợi đối diện thuê sạc dự phòng đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_07','V1009','阮明',7,'好吧，我现在就过去，真是麻烦您了。','hǎo ba， wǒ xiàn zài jiù guò qù， zhēn shì má fán nín le。','Thôi được, tôi qua đó ngay đây, thật sự làm phiền ông quá.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_08','V1009','赵老板',8,'理解一下，我们开店也怕遇到骗子，多多包涵哈。','lǐ jiě yī xià， wǒ men kāi diàn yě pà yù dào piàn zi， duō duō bāo hán hā。','Thông cảm cho tôi nhé, mở cửa hàng cũng sợ gặp phải kẻ lừa đảo, mong cậu bỏ qua giúp.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1010','SKC1','背包在商场被小偷顺手牵羊，前往附近派出所做笔录',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1010','SIT1010','P1','twist','chinh_thuc',NULL,'外国人丢失随身财物报案，需携带护照、居留许可，笔录信息会同步登记出入境系统。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_01','V1010','阮明',1,'警官您好，我要报案，我的背包在商场餐饮区被偷走了。','jǐng guān nín hǎo， wǒ yào bào àn， wǒ de bēi bāo zài shāng chǎng cān yǐn qū bèi tōu zǒu le。','Chào cán bộ, tôi muốn trình báo, ba lô của tôi bị mất trộm ở khu ẩm thực trong trung tâm thương mại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_02','V1010','周警官',2,'先坐下来，把你的姓名、国籍、居留证件信息跟我说一下。','xiān zuò xià lái， bǎ nǐ de xìng míng、 guó jí、 jū liú zhèng jiàn xìn xī gēn wǒ shuō yī xià。','Anh ngồi xuống trước đã, cho tôi biết họ tên, quốc tịch và thông tin giấy tờ cư trú của anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_03','V1010','阮明',3,'我叫阮明，越南留学生，包里有银行卡、耳机还有课堂笔记呢。','wǒ jiào ruǎn míng， yuè nán liú xué shēng， bāo lǐ yǒu yín háng kǎ、 ěr jī hái yǒu kè táng bǐ jì ne。','Tôi tên Nguyễn Minh, du học sinh Việt Nam, trong ba lô có thẻ ngân hàng, tai nghe và cả vở ghi bài trên lớp.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_04','V1010','周警官',4,'丢失的具体时间、商场楼层、座位位置，你仔细回忆清楚吧。','diū shī de jù tǐ shí jiān、 shāng chǎng lóu céng、 zuò wèi wèi zhì， nǐ zǐ xì huí yì qīng chǔ ba。','Anh nhớ lại kỹ giúp tôi thời gian cụ thể bị mất, tầng nào của trung tâm thương mại, và vị trí chỗ ngồi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_05','V1010','阮明',5,'大概四十分钟前，我去取餐转身几十秒，背包就不见了啊。','dà gài sì shí fēn zhōng qián， wǒ qù qǔ cān zhuǎn shēn jǐ shí miǎo， bēi bāo jiù bú jiàn le a。','Khoảng bốn mươi phút trước, tôi đi lấy đồ ăn quay lại chỉ vài chục giây thôi mà ba lô đã biến mất rồi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_06','V1010','周警官',6,'我们会调取监控录像，不过商场人流大，找回物品难度不小。','wǒ men huì diào qǔ jiān kòng lù xiàng， bù guò shāng chǎng rén liú dà， zhǎo huí wù pǐn nán dù bù xiǎo。','Chúng tôi sẽ trích xuất camera giám sát, nhưng trung tâm thương mại đông người qua lại, khả năng tìm lại đồ không cao đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_07','V1010','阮明',7,'我的银行卡还没挂失，能不能麻烦您告诉我挂失银行的电话？','wǒ de yín háng kǎ hái méi guà shī， néng bù néng má fán nín gào sù wǒ guà shī yín háng de diàn huà？','Thẻ ngân hàng của tôi vẫn chưa báo mất, phiền anh cho tôi xin số điện thoại báo mất của ngân hàng được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_08','V1010','周警官',8,'我写在纸条上给你，做完笔录尽快联系银行冻结卡片。','wǒ xiě zài zhǐ tiáo shàng gěi nǐ， zuò wán bǐ lù jǐn kuài lián xì yín háng dòng jié kǎ piàn。','Tôi ghi ra giấy cho anh đây, làm biên bản xong thì liên hệ ngân hàng khóa thẻ càng sớm càng tốt.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1011','SKC1','暴雨导致郊区公交全线停运，求助社区工作人员临时安置',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1011','SIT1011','P1','suon_se','ban_chinh_thuc',NULL,'国内社区服务中心对受极端天气滞留的路人提供免费临时休息、热水充电等便民服务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_01','V1011','阮明',1,'您好，外面暴雨所有公交都停了，我回不去学校，能临时待在这里吗？','nín hǎo， wài miàn bào yǔ suǒ yǒu gōng jiāo dōu tíng le， wǒ huí bù qù xué xiào， néng lín shí dài zài zhè lǐ ma？','Chào chị, ngoài kia mưa to quá xe buýt ngừng chạy hết rồi, tôi không về trường được, cho tôi tạm ở đây một lát được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_02','V1011','小吴',2,'同学别着急，先跟我说下你的学校地址，还有身上有没有雨具？','tóng xué bié zháo jí， xiān gēn wǒ shuō xià nǐ de xué xiào dì zhǐ， hái yǒu shēn shàng yǒu méi yǒu yǔ jù？','Em đừng lo, nói cho chị biết địa chỉ trường em trước đã, với lại người có mang theo áo mưa gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_03','V1011','阮明',3,'我是外国语大学留学生，出门没带伞，手机快没电没法打车呢。','wǒ shì wài guó yǔ dà xué liú xué shēng， chū mén méi dài sǎn， shǒu jī kuài méi diàn méi fǎ dǎ chē ne。','Em là du học sinh trường Đại học Ngoại ngữ, ra ngoài không mang ô, điện thoại thì sắp hết pin không gọi xe được nữa rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_04','V1011','小吴',4,'外面积水太深网约车也进不来，社区服务站可以临时休息到雨停。','wài miàn jī shuǐ tài shēn wǎng yuē chē yě jìn bù lái， shè qū fú wù zhàn kě yǐ lín shí xiū xī dào yǔ tíng。','Ngoài đó ngập nước sâu quá xe công nghệ cũng không vào được, em cứ nghỉ tạm ở trạm dịch vụ cộng đồng đến khi tạnh mưa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_05','V1011','阮明',5,'真的太感谢您了，我本来打算赶回去上晚自习，这下彻底赶不上啦。','zhēn de tài gǎn xiè nín le， wǒ běn lái dǎ suàn gǎn huí qù shàng wǎn zì xí， zhè xià chè dǐ gǎn bù shàng la。','Thật sự cảm ơn chị nhiều lắm, em định tranh thủ về học phụ đạo buổi tối mà giờ chắc trễ luôn rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_06','V1011','小吴',6,'我给你倒杯热水，你可以跟辅导员发消息说明下情况。','wǒ gěi nǐ dào bēi rè shuǐ， nǐ kě yǐ gēn fǔ dǎo yuán fā xiāo xī shuō míng xià qíng kuàng。','Chị rót cho em cốc nước nóng nhé, em nhắn tin báo tình hình cho giáo viên chủ nhiệm biết là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_07','V1011','阮明',7,'好，借您充电插座充会儿手机，等雨小一点我再想办法返校。','hǎo， jiè nín chōng diàn chā zuò chōng huì er shǒu jī， děng yǔ xiǎo yì diǎn wǒ zài xiǎng bàn fǎ fǎn xiào。','Dạ, em mượn ổ cắm sạc điện thoại một lát, đợi mưa nhỏ bớt em tính cách quay lại trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_08','V1011','小吴',8,'安心休息，暴雨天道路不安全，千万不要强行涉水外出。','ān xīn xiū xī， bào yǔ tiān dào lù bù ān quán， qiān wàn bú yào qiáng xíng shè shuǐ wài chū。','Cứ yên tâm nghỉ ngơi đi, trời mưa to thế này đường sá không an toàn đâu, tuyệt đối đừng cố lội nước ra ngoài.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1012','SKC1','街边小吃食物中毒集体腹痛，拨打市场监管热线投诉',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1012','SIT1012','P1','twist','chinh_thuc',NULL,'餐饮食物中毒维权需要保留消费凭证、医院诊断单据，监管部门会现场抽检食材，属实可要求商家全额赔偿医药费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_01','V1012','阮明',1,'您好，我要举报街边小吃摊，吃完东西之后我和两个同学都腹痛腹泻。','nín hǎo， wǒ yào jǔ bào jiē biān xiǎo chī tān， chī wán dōng xī zhī hòu wǒ hé liǎng gè tóng xué dōu fù tòng fù xiè。','Chào anh, tôi muốn khiếu nại quầy đồ ăn vặt ven đường, ăn xong tôi và hai bạn học đều bị đau bụng, tiêu chảy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_02','V1012','接线员',2,'麻烦告知小吃摊具体地址、摊位名称，还有你们就餐的时间吧。','má fán gào zhī xiǎo chī tān jù tǐ dì zhǐ、 tān wèi míng chēng， hái yǒu nǐ men jiù cān de shí jiān ba。','Phiền anh/chị cho biết địa chỉ cụ thể của quầy hàng, tên quầy, và thời gian các vị dùng bữa.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_03','V1012','阮明',3,'学校南门巷子里的无名炸串摊，今天傍晚六点左右我们一起消费的啊。','xué xiào nán mén xiàng zi lǐ de wú míng zhà chuàn tān， jīn tiān bàng wǎn liù diǎn zuǒ yòu wǒ men yì qǐ xiāo fèi de a。','Là quầy xiên chiên không tên trong hẻm cổng nam trường học, khoảng sáu giờ chiều nay chúng tôi cùng ăn ở đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_04','V1012','接线员',4,'你们现在身体状况怎么样，有没有去医院开具诊断证明呢？','nǐ men xiàn zài shēn tǐ zhuàng kuàng zěn me yàng， yǒu méi yǒu qù yī yuàn kāi jù zhěn duàn zhèng míng ne？','Hiện tại tình trạng sức khỏe của các vị thế nào, đã đến bệnh viện xin giấy chẩn đoán chưa ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_05','V1012','阮明',5,'刚从社区诊所出来，医生判定是不洁食物引发的肠胃不适。','gāng cóng shè qū zhěn suǒ chū lái， yī shēng pàn dìng shì bù jié shí wù yǐn fā de cháng wèi bù shì。','Vừa từ phòng khám cộng đồng ra, bác sĩ kết luận là do ăn phải thực phẩm không sạch gây rối loạn tiêu hóa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_06','V1012','接线员',6,'需要携带就诊单据、消费记录，工作日到辖区监管所现场登记。','xū yào xié dài jiù zhěn dān jù、 xiāo fèi jì lù， gōng zuò rì dào xiá qū jiān guǎn suǒ xiàn chǎng dēng jì。','Các vị cần mang theo hóa đơn khám bệnh, chứng từ chi tiêu, đến ngày làm việc thì ra cơ quan quản lý khu vực đăng ký trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_07','V1012','阮明',7,'我们下周才有空过去，这段时间摊位要是关门跑路怎么办？','wǒ men xià zhōu cái yǒu kòng guò qù， zhè duàn shí jiān tān wèi yào shì guān mén pǎo lù zěn me bàn？','Tuần sau chúng tôi mới có thời gian đến được, nếu trong lúc đó quầy hàng đóng cửa bỏ trốn thì phải làm sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_08','V1012','接线员',8,'我们会立刻安排工作人员上门核查，暂扣摊位食材留存证据。','wǒ men huì lì kè ān pái gōng zuò rén yuán shàng mén hé chá， zàn kòu tān wèi shí cái liú cún zhèng jù。','Chúng tôi sẽ lập tức cử người đến kiểm tra tận nơi, tạm giữ nguyên liệu của quầy hàng để lưu làm bằng chứng.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1013','SKC1','居留许可卡片断裂损毁，出入境大厅申请临时通行纸质证明',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1013','SIT1013','P1','suon_se','chinh_thuc',NULL,'外国人居留许可损毁、丢失均无法单独出行，临时纸质通行证明仅限国内短期交通出行使用，不能替代正式居留卡。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_01','V1013','阮明',1,'您好，我的外国人居留许可不小心折断了，没办法正常使用，想办临时通行证明。','nín hǎo， wǒ de wài guó rén jū liú xǔ kě bù xiǎo xīn zhé duàn le， méi bàn fǎ zhèng cháng shǐ yòng， xiǎng bàn lín shí tōng xíng zhèng míng。','Chào anh/chị, thẻ cư trú người nước ngoài của tôi không may bị gãy, không dùng được nữa, tôi muốn xin giấy chứng nhận tạm thời để đi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_02','V1013','刘柜员',2,'先出示你的护照，还有破损的居留卡，我先核验一下信息吧。','xiān chū shì nǐ de hù zhào， hái yǒu pò sǔn de jū liú kǎ， wǒ xiān hé yàn yī xià xìn xī ba。','Anh đưa hộ chiếu trước, với cả thẻ cư trú bị hỏng đó, để tôi kiểm tra thông tin đã.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_03','V1013','阮明',3,'卡片中间裂开，刷卡机识别不了，下周还要坐高铁外出办事呢。','kǎ piàn zhōng jiān liè kāi， shuā kǎ jī shí bié bù liǎo， xià zhōu hái yào zuò gāo tiě wài chū bàn shì ne。','Thẻ bị nứt ở giữa, máy quét không nhận được, mà tuần sau tôi còn phải đi tàu cao tốc để giải quyết việc nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_04','V1013','刘柜员',4,'破损居留卡属于失效证件，临时纸质证明有效期只有七天哦。','pò sǔn jū liú kǎ shǔ yú shī xiào zhèng jiàn， lín shí zhǐ zhì zhèng míng yǒu xiào qī zhǐ yǒu qī tiān ó。','Thẻ cư trú bị hỏng được xem là giấy tờ hết hiệu lực, giấy chứng nhận tạm thời chỉ có giá trị bảy ngày thôi ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_05','V1013','阮明',5,'七天足够我补办新卡了，请问办理需要额外准备什么材料吗？','qī tiān zú gòu wǒ bǔ bàn xīn kǎ le， qǐng wèn bàn lǐ xū yào é wài zhǔn bèi shén me cái liào ma？','Bảy ngày là đủ để tôi làm lại thẻ mới rồi, cho tôi hỏi làm thủ tục này cần chuẩn bị thêm giấy tờ gì không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_06','V1013','刘柜员',6,'准备一张一寸白底证件照，填写补办申请表，现场等待半小时就能取证。','zhǔn bèi yī zhāng yī cùn bái dǐ zhèng jiàn zhào， tián xiě bǔ bàn shēn qǐng biǎo， xiàn chǎng děng dài bàn xiǎo shí jiù néng qǔ zhèng。','Anh chuẩn bị một ảnh thẻ nền trắng cỡ 3x4, điền vào đơn xin cấp lại, ngồi chờ tại chỗ khoảng nửa tiếng là lấy được giấy chứng nhận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_07','V1013','阮明',7,'还好今天带齐证件过来，不然临时出行肯定会被拦下来。','hái hǎo jīn tiān dài qí zhèng jiàn guò lái， bù rán lín shí chū xíng kěn dìng huì bèi lán xià lái。','May mà hôm nay mang đầy đủ giấy tờ đến, không thì đi lại tạm thời kiểu này chắc chắn bị chặn lại mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_08','V1013','刘柜员',8,'拿好临时证明，这段时间出门一定要同时携带护照。','ná hǎo lín shí zhèng míng， zhè duàn shí jiān chū mén yí dìng yào tóng shí xié dài hù zhào。','Anh cầm giấy chứng nhận tạm thời cẩn thận, trong thời gian này ra ngoài nhớ phải mang theo hộ chiếu cùng lúc nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1014','SKC1','签证线上缴费扣款成功但系统未入账，联系出入境财务加急核对',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1014','SIT1014','P1','that_bai_nhe','chinh_thuc',NULL,'政务线上缴费存在银行、政务系统对账时差，窗口开具纸质临时凭证可临时规避审核拦截。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_01','V1014','阮明',1,'陈会计您好，我昨天线上续签签证缴费，银行卡已经扣款，系统却显示未缴费。','chén kuài jì nín hǎo， wǒ zuó tiān xiàn shàng xù qiān qiān zhèng jiǎo fèi， yín háng kǎ yǐ jīng kòu kuǎn， xì tǒng què xiǎn shì wèi jiǎo fèi。','Chào kế toán Trần, hôm qua tôi thanh toán gia hạn visa trực tuyến, thẻ ngân hàng đã bị trừ tiền rồi mà hệ thống lại hiển thị chưa thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_02','V1014','陈会计',2,'把你的缴费订单号、银行卡扣款截图发送到我办公邮箱吧。','bǎ nǐ de jiǎo fèi dìng dān hào、 yín háng kǎ kòu kuǎn jié tú fā sòng dào wǒ bàn gōng yóu xiāng ba。','Anh gửi mã đơn thanh toán, ảnh chụp màn hình trừ tiền của thẻ ngân hàng vào email văn phòng của tôi nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_03','V1014','阮明',3,'订单号896421，扣款截图我手机里存好了，现在就能转发给您啊。','dìng dān hào 896421， kòu kuǎn jié tú wǒ shǒu jī lǐ cún hǎo le， xiàn zài jiù néng zhuǎn fā gěi nín a。','Mã đơn là 896421, ảnh chụp trừ tiền tôi đã lưu sẵn trong điện thoại, bây giờ tôi chuyển cho chị ngay đây ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_04','V1014','陈会计',4,'这类跨银行延迟入账要等系统对账，最快也要明天才能更新状态。','zhè lèi kuà yín háng yán chí rù zhàng yào děng xì tǒng duì zhàng， zuì kuài yě yào míng tiān cái néng gēng xīn zhuàng tài。','Loại giao dịch trễ liên ngân hàng thế này phải đợi hệ thống đối soát, nhanh nhất cũng phải đến ngày mai mới cập nhật được trạng thái.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_05','V1014','阮明',5,'可是我后天就要办理续签审核，未缴费记录会直接驳回我的申请呢。','kě shì wǒ hòu tiān jiù yào bàn lǐ xù qiān shěn hé， wèi jiǎo fèi jì lù huì zhí jiē bó huí wǒ de shēn qǐng ne。','Nhưng ngày kia tôi đã phải làm thủ tục xét duyệt gia hạn rồi, nếu ghi nhận chưa thanh toán thì hồ sơ của tôi sẽ bị từ chối thẳng mất.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_06','V1014','陈会计',6,'我可以给你开具临时缴费凭证，窗口可凭凭证先受理你的材料。','wǒ kě yǐ gěi nǐ kāi jù lín shí jiǎo fèi píng zhèng， chuāng kǒu kě píng píng zhèng xiān shòu lǐ nǐ de cái liào。','Tôi có thể cấp cho anh giấy xác nhận thanh toán tạm thời, quầy có thể căn cứ vào giấy đó để tiếp nhận hồ sơ của anh trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_07','V1014','阮明',7,'太好了，那我现在立刻发送截图，麻烦您尽快核对处理。','tài hǎo le， nà wǒ xiàn zài lì kè fā sòng jié tú， má fán nín jǐn kuài hé duì chǔ lǐ。','Tuyệt quá, vậy tôi gửi ảnh chụp ngay bây giờ, phiền chị kiểm tra xử lý giúp càng sớm càng tốt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_08','V1014','陈会计',8,'我今天下班前完成对账，要是资金仍未同步，你明天再来一趟。','wǒ jīn tiān xià bān qián wán chéng duì zhàng， yào shì zī jīn réng wèi tóng bù， nǐ míng tiān zài lái yī tàng。','Hôm nay trước giờ tan làm tôi sẽ hoàn tất đối soát, nếu tiền vẫn chưa đồng bộ thì mai anh ghé lại một lần nữa nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1015','SKC1','论文截止日前电脑硬盘崩溃文件丢失，找授课老师申请延期并借用图书馆设备',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1015','SIT1015','P1','twist','ban_chinh_thuc',NULL,'国内高校论文延期需提交书面说明+客观事故证明，任课老师无权私自延期，必须上报教务审批。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_01','V1015','阮明',1,'周老师，不好意思打扰您，我电脑硬盘突然损坏，整篇毕业论文全部丢失了啊。','zhōu lǎo shī， bù hǎo yì sī dǎ rǎo nín， wǒ diàn nǎo yìng pán tū rán sǔn huài， zhěng piān bì yè lùn wén quán bù diū shī le a。','Thầy Chu, xin lỗi làm phiền thầy, ổ cứng máy tính em bỗng dưng hỏng, toàn bộ luận văn tốt nghiệp mất sạch rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_02','V1015','周教授',2,'怎么会这么不巧？距离提交截止日期只剩明天中午了呢。','zěn me huì zhè me bù qiǎo？ jù lí tí jiāo jié zhǐ rì qī zhǐ shèng míng tiān zhōng wǔ le ne。','Sao lại xui xẻo đúng lúc này chứ? Chỉ còn đến trưa mai là hạn nộp bài rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_03','V1015','阮明',3,'我没有备份文件，硬盘完全读不出来，维修店说很难恢复数据。','wǒ méi yǒu bèi fèn wén jiàn， yìng pán wán quán dú bù chū lái， wéi xiū diàn shuō hěn nán huī fù shù jù。','Em không có bản sao lưu, ổ cứng hoàn toàn không đọc được nữa, tiệm sửa máy nói rất khó khôi phục dữ liệu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_04','V1015','周教授',4,'我理解你的突发状况，但学院统一截止时间不能随便延后，流程很严格。','wǒ lǐ jiě nǐ de tū fā zhuàng kuàng， dàn xué yuàn tǒng yī jié zhǐ shí jiān bù néng suí biàn yán hòu， liú chéng hěn yán gé。','Thầy hiểu tình huống bất ngờ của em, nhưng thời hạn chung của khoa không thể tùy tiện lùi lại được, quy trình rất nghiêm ngặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_05','V1015','阮明',5,'我能不能申请三天延期？图书馆有备用电脑，我可以连夜重新写完初稿。','wǒ néng bù néng shēn qǐng sān tiān yán qī？ tú shū guǎn yǒu bèi yòng diàn nǎo， wǒ kě yǐ lián yè chóng xīn xiě wán chū gǎo。','Em xin gia hạn ba ngày được không ạ? Thư viện có máy tính dự phòng, em có thể thức đêm viết lại bản nháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_06','V1015','周教授',6,'你先写一份书面情况说明，附上电脑维修单据，我帮你向学院教务报备。','nǐ xiān xiě yī fèn shū miàn qíng kuàng shuō míng， fù shàng diàn nǎo wéi xiū dān jù， wǒ bāng nǐ xiàng xué yuàn jiào wù bào bèi。','Em viết trước một bản tường trình bằng văn bản, kèm theo biên nhận sửa máy, thầy sẽ giúp em báo cáo lên phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_07','V1015','阮明',7,'太感谢老师了，我现在就去图书馆借设备，通宵赶写论文。','tài gǎn xiè lǎo shī le， wǒ xiàn zài jiù qù tú shū guǎn jiè shè bèi， tōng xiāo gǎn xiě lùn wén。','Em cảm ơn thầy nhiều lắm ạ, em ra thư viện mượn máy ngay bây giờ, thức trắng đêm viết cho xong luận văn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_08','V1015','周教授',8,'尽力加快进度，教务那边最多只能批准三天缓冲期，别再拖延啦。','jìn lì jiā kuài jìn dù， jiào wù nà biān zuì duō zhǐ néng pī zhǔn sān tiān huǎn chōng qī， bié zài tuō yán la。','Cố gắng đẩy nhanh tiến độ nhé, bên phòng đào tạo cùng lắm chỉ có thể duyệt cho ba ngày gia hạn thôi, đừng để trễ nữa đấy.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1016','SKC1','出入境预约号当日失效，携带齐全材料现场窗口申请加急受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1016','SIT1016','P1','that_bai_nhe','ban_chinh_thuc',NULL,'出入境线上预约实行分时段限号制度，普通出行、学术活动不纳入紧急加急受理范围，仅重大医疗、亲属变故可走绿色通道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_01','V1016','阮明',1,'你好，我线上预约的今天办理签证续签，预约号显示失效了，材料全都带齐了。','nǐ hǎo， wǒ xiàn shàng yù yuē de jīn tiān bàn lǐ qiān zhèng xù qiān， yù yuē hào xiǎn shì shī xiào le， cái liào quán dōu dài qí le。','Chào chị, tôi đặt lịch trực tuyến hôm nay để làm thủ tục gia hạn visa, nhưng số thứ tự lại báo hết hiệu lực, giấy tờ tôi mang đầy đủ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_02','V1016','小徐',2,'预约号过期只能重新线上预约，线下窗口不接受无号业务办理哦。','yù yuē hào guò qī zhǐ néng chóng xīn xiàn shàng yù yuē， xiàn xià chuāng kǒu bù jiē shòu wú hào yè wù bàn lǐ ó。','Số đặt lịch hết hạn thì chỉ có thể đặt lại trực tuyến thôi, quầy trực tiếp không tiếp nhận hồ sơ không có số đâu ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_03','V1016','阮明',3,'我下周就要离校出差，根本没时间重新预约，能不能通融一下加急处理呢？','wǒ xià zhōu jiù yào lí xiào chū chāi， gēn běn méi shí jiān chóng xīn yù yuē， néng bù néng tōng róng yī xià jiā jí chǔ lǐ ne？','Tuần sau tôi phải rời trường đi công tác rồi, thực sự không có thời gian đặt lại lịch, chị có thể linh động xử lý gấp giúp tôi không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_04','V1016','小徐',4,'加急业务仅限紧急就医、亲属病危这类特殊情况，出行出差不符合加急标准。','jiā jí yè wù jǐn xiàn jǐn jí jiù yī、 qīn shǔ bìng wēi zhè lèi tè shū qíng kuàng， chū xíng chū chāi bù fú hé jiā jí biāo zhǔn。','Xử lý khẩn cấp chỉ áp dụng cho các trường hợp đặc biệt như cấp cứu y tế, người thân nguy kịch, đi công tác không thuộc diện được xử lý gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_05','V1016','阮明',5,'我是留学生，外出参加国际学术会议，会议邀请函我随身带来了啊。','wǒ shì liú xué shēng， wài chū cān jiā guó jì xué shù huì yì， huì yì yāo qǐng hán wǒ suí shēn dài lái le a。','Tôi là du học sinh, đi dự hội nghị học thuật quốc tế, thư mời hội nghị tôi mang theo đây ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_06','V1016','小徐',6,'我帮你咨询窗口主管，你先在这里等候几分钟，不要离开。','wǒ bāng nǐ zī xún chuāng kǒu zhǔ guǎn， nǐ xiān zài zhè lǐ děng hòu jǐ fēn zhōng， bú yào lí kāi。','Để tôi hỏi giúp anh bên quản lý quầy, anh cứ chờ ở đây vài phút, đừng đi đâu nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_07','V1016','阮明',7,'麻烦你多帮忙说说，错过会议对我的学业影响很大。','má fán nǐ duō bāng máng shuō shuō， cuò guò huì yì duì wǒ de xué yè yǐng xiǎng hěn dà。','Phiền chị giúp tôi nói thêm với, lỡ mất hội nghị thì ảnh hưởng lớn đến việc học của tôi lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_08','V1016','小徐',8,'主管回复了，依旧无法现场受理，只能明天重新抢预约号。','zhǔ guǎn huí fù le， yī jiù wú fǎ xiàn chǎng shòu lǐ， zhǐ néng míng tiān chóng xīn qiǎng yù yuē hào。','Quản lý đã trả lời rồi, vẫn không thể tiếp nhận trực tiếp được, chỉ có thể mai quay lại giành số đặt lịch lại thôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1017','SKC1','诈骗来电谎称家人重病要求汇款，冷静核实后联系学院反诈老师',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1017','SIT1017','P1','suon_se','ban_chinh_thuc',NULL,'国内高校会定期开展留学生反诈宣讲，遭遇疑似诈骗可直接联系国际学院辅导员，同步上报公安反诈平台。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_01','V1017','阮明',1,'郑老师，我刚刚接到一通陌生电话，说我母亲重病住院，急需我立刻转账过去。','zhèng lǎo shī， wǒ gāng gāng jiē dào yí tòng mò shēng diàn huà， shuō wǒ mǔ qīn zhòng bìng zhù yuàn， jí xū wǒ lì kè zhuǎn zhàng guò qù。','Thầy Trịnh ơi, em vừa nhận được một cuộc gọi lạ, nói là mẹ em bị bệnh nặng phải nhập viện, cần em chuyển tiền ngay lập tức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_02','V1017','郑老师',2,'你先别慌，有没有第一时间通过视频电话联系家里确认情况？','nǐ xiān bié huāng， yǒu méi yǒu dì yī shí jiān tōng guò shì pín diàn huà lián xì jiā lǐ què rèn qíng kuàng？','Em đừng hoảng, em đã gọi video ngay để xác nhận tình hình với gia đình chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_03','V1017','阮明',3,'我马上打视频给我妈妈，她身体好好的，根本没有生病这回事呢。','wǒ mǎ shàng dǎ shì pín gěi wǒ mā mā， tā shēn tǐ hǎo hǎo de， gēn běn méi yǒu shēng bìng zhè huí shì ne。','Em gọi video cho mẹ ngay, mẹ em vẫn khỏe re, làm gì có chuyện bệnh tật gì đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_04','V1017','郑老师',4,'这是典型跨境冒充亲属诈骗，很多留学生都接到过同类来电。','zhè shì diǎn xíng kuà jìng mào chōng qīn shǔ zhà piàn， hěn duō liú xué shēng dōu jiē dào guò tóng lèi lái diàn。','Đây là kiểu lừa đảo giả mạo người thân xuyên biên giới điển hình, nhiều du học sinh cũng từng nhận được cuộc gọi tương tự.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_05','V1017','阮明',5,'骗子还准确说出我的姓名和家乡信息，差点我就准备转账了，太吓人啦。','piàn zi hái zhǔn què shuō chū wǒ de xìng míng hé jiā xiāng xìn xī， chà diǎn wǒ jiù zhǔn bèi zhuǎn zhàng le， tài xià rén la。','Bọn lừa đảo còn nói đúng tên và thông tin quê quán của em, suýt nữa em đã chuyển tiền rồi, đáng sợ thật đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_06','V1017','郑老师',6,'把对方的来电号码发给我，学院统一上报反诈中心备案拦截。','bǎ duì fāng de lái diàn hào mǎ fā gěi wǒ， xué yuàn tǒng yī shàng bào fǎn zhà zhōng xīn bèi àn lán jié。','Em gửi số điện thoại của đối tượng đó cho thầy, nhà trường sẽ báo cáo lên trung tâm chống lừa đảo để ghi nhận và chặn số.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_07','V1017','阮明',7,'好，我现在转发号码，之后再有陌生要钱电话我都会先来问您。','hǎo， wǒ xiàn zài zhuǎn fā hào mǎ， zhī hòu zài yǒu mò shēng yào qián diàn huà wǒ dōu huì xiān lái wèn nín。','Dạ, em gửi số ngay đây, sau này có cuộc gọi lạ đòi tiền em sẽ hỏi thầy trước ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_08','V1017','郑老师',8,'记住，凡是催你立刻转账的陌生来电，一律不要相信，先核实家人。','jì zhù， fán shì cuī nǐ lì kè zhuǎn zhàng de mò shēng lái diàn， yī lǜ bú yào xiāng xìn， xiān hé shí jiā rén。','Nhớ nhé, hễ cuộc gọi lạ nào giục em chuyển tiền ngay thì đừng tin, phải xác minh với gia đình trước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1018','SKC1','校园学习账号被盗用登录，联系学校信息中心紧急冻结账号',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1018','SIT1018','P1','twist','ban_chinh_thuc',NULL,'国内高校校园账号绑定学籍、选课、图书馆借阅权限，被盗用可能泄露个人学籍信息，必须线下核验身份永久冻结。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_01','V1018','阮明',1,'您好，我的校园学习平台账号异地登录，应该是被盗用了，麻烦帮忙冻结账号吧。','nín hǎo， wǒ de xiào yuán xué xí píng tái zhàng hào yì dì dēng lù， yīng gāi shì bèi dào yòng le， má fán bāng máng dòng jié zhàng hào ba。','Chào anh, tài khoản nền tảng học tập của em bị đăng nhập từ nơi khác, chắc là bị đánh cắp rồi, phiền anh giúp em khóa tài khoản lại.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_02','V1018','小高',2,'请提供你的学号、实名姓名，我先查询账号登录记录看看。','qǐng tí gōng nǐ de xué hào、 shí míng xìng míng， wǒ xiān chá xún zhàng hào dēng lù jì lù kàn kàn。','Em cho anh xin mã số sinh viên và họ tên thật, để anh kiểm tra lịch sử đăng nhập tài khoản trước đã.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_03','V1018','阮明',3,'学号20230418，姓名阮明，系统提示今早凌晨在外地设备登录啊。','xué hào 20230418， xìng míng ruǎn míng， xì tǒng tí shì jīn zǎo líng chén zài wài dì shè bèi dēng lù a。','Mã số sinh viên 20230418, tên Nguyễn Minh, hệ thống báo là sáng sớm nay có thiết bị ở nơi khác đăng nhập đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_04','V1018','小高',4,'账号冻结需要核验身份，你要携带学生证线下到机房办理完整锁定手续。','zhàng hào dòng jié xū yào hé yàn shēn fèn， nǐ yào xié dài xué shēng zhèng xiàn xià dào jī fáng bàn lǐ wán zhěng suǒ dìng shǒu xù。','Việc khóa tài khoản cần xác minh danh tính, em phải mang thẻ sinh viên đến phòng máy trực tiếp để làm thủ tục khóa hoàn toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'我现在在教学楼上课走不开，能不能线上临时冻结，等下课再去机房？','wǒ xiàn zài zài jiào xué lóu shàng kè zǒu bù kāi， néng bù néng xiàn shàng lín shí dòng jié， děng xià kè zài qù jī fáng？','Em đang học trên giảng đường không đi được, anh có thể tạm khóa online trước không, chờ tan học em qua phòng máy sau?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'我可以先临时限制登录两小时，超时会自动解除，线下才能永久锁定。','wǒ kě yǐ xiān lín shí xiàn zhì dēng lù liǎng xiǎo shí， chāo shí huì zì dòng jiě chú， xiàn xià cái néng yǒng jiǔ suǒ dìng。','Anh có thể tạm giới hạn đăng nhập trong hai tiếng, quá giờ sẽ tự động mở lại, phải làm trực tiếp mới khóa vĩnh viễn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时足够我下课过去，麻烦您现在先帮我临时锁上账号。','liǎng xiǎo shí zú gòu wǒ xià kè guò qù， má fán nín xiàn zài xiān bāng wǒ lín shí suǒ shàng zhàng hào。','Hai tiếng là đủ để em tan học qua rồi, phiền anh khóa tạm tài khoản giúp em trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_08','V1018','小高',8,'已经临时限制登录了，尽快带证件过来重置密码完善安全验证。','yǐ jīng lín shí xiàn zhì dēng lù le， jǐn kuài dài zhèng jiàn guò lái zhòng zhì mì mǎ wán shàn ān quán yàn zhèng。','Đã tạm khóa đăng nhập rồi đó, em mang giấy tờ qua sớm để đặt lại mật khẩu và hoàn thiện xác thực bảo mật.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1019','SKC1','社交平台私人照片被恶意转发骚扰，到学校保卫处寻求介入处理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1019','SIT1019','P1','suon_se','chinh_thuc',NULL,'个人肖像被恶意转发骚扰属于侵权行为，学校保卫处可出具证明协助学生向社交平台申请删除内容、封禁侵权账号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_01','V1019','阮明',1,'李干事您好，有人保存我的私人生活照片，转发到社交平台私信骚扰我。','lǐ gàn shì nín hǎo， yǒu rén bǎo cún wǒ de sī rén shēng huó zhào piàn， zhuǎn fā dào shè jiāo píng tái sī xìn sāo rǎo wǒ。','Chào cán bộ Lý, có người lưu lại ảnh sinh hoạt riêng tư của tôi rồi chuyển tiếp qua tin nhắn riêng trên mạng xã hội để quấy rối tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_02','V1019','李干事',2,'你先把对方骚扰截图、转发照片的完整记录全部截图保存好。','nǐ xiān bǎ duì fāng sāo rǎo jié tú、 zhuǎn fā zhào piān de wán zhěng jì lù quán bù jié tú bǎo cún hǎo。','Em chụp màn hình lưu lại đầy đủ toàn bộ tin nhắn quấy rối và ảnh bị chuyển tiếp của đối tượng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_03','V1019','阮明',3,'所有聊天记录我都存好了，对方是校外人员，我不知道对方真实身份呢。','suǒ yǒu liáo tiān jì lù wǒ dōu cún hǎo le， duì fāng shì xiào wài rén yuán， wǒ bù zhī dào duì fāng zhēn shí shēn fèn ne。','Toàn bộ tin nhắn tôi đã lưu lại hết rồi, đối tượng đó là người ngoài trường, tôi không biết danh tính thật của họ là ai.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_04','V1019','李干事',4,'我们会出具学校证明，协助你联系平台客服调取对方注册信息。','wǒ men huì chū jù xué xiào zhèng míng， xié zhù nǐ lián xì píng tái kè fú diào qǔ duì fāng zhù cè xìn xī。','Nhà trường sẽ cấp giấy xác nhận, hỗ trợ em liên hệ với bộ phận chăm sóc khách hàng của nền tảng để tra thông tin đăng ký của đối tượng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_05','V1019','阮明',5,'对方持续发消息骚扰，严重影响我上课和休息，希望尽快制止。','duì fāng chí xù fā xiāo xī sāo rǎo， yán zhòng yǐng xiǎng wǒ shàng kè hé xiū xī， xī wàng jǐn kuài zhì zhǐ。','Đối tượng liên tục nhắn tin quấy rối, ảnh hưởng nghiêm trọng đến việc học và nghỉ ngơi của tôi, mong sớm can thiệp chấm dứt việc này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_06','V1019','李干事',6,'我先登记你的情况，今天就发函给平台要求下架相关照片。','wǒ xiān dēng jì nǐ de qíng kuàng， jīn tiān jiù fā hán gěi píng tái yāo qiú xià jià xiāng guān zhào piān。','Tôi sẽ ghi nhận trường hợp của em trước, hôm nay sẽ gửi công văn cho nền tảng yêu cầu gỡ bỏ những ảnh liên quan.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_07','V1019','阮明',7,'太感谢您了，我之前不知道学校保卫处可以处理网络骚扰问题。','tài gǎn xiè nín le， wǒ zhī qián bù zhī dào xué xiào bǎo wèi chù kě yǐ chǔ lǐ wǎng luò sāo rǎo wèn tí。','Tôi cảm ơn cán bộ rất nhiều, trước đây tôi không biết phòng bảo vệ nhà trường có thể xử lý cả vấn đề quấy rối trên mạng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_08','V1019','李干事',8,'校内师生遭遇网络侵权、骚扰都可以来报备，我们会配合平台维权。','xiào nèi shī shēng zāo yù wǎng luò qīn quán、 sāo rǎo dōu kě yǐ lái bào bèi， wǒ men huì pèi hé píng tái wéi quán。','Thầy cô và sinh viên trong trường nếu gặp phải xâm phạm quyền lợi hay quấy rối trên mạng đều có thể đến trình báo, chúng tôi sẽ phối hợp với nền tảng để bảo vệ quyền lợi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1020','SKC1','社团活动现场两名同学激烈争吵，上前劝解并通知社团负责人',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1020','SIT1020','P1','twist','tuy_y',NULL,'国内校园社团公共场合发生争吵会影响社团评优，负责人一般会分开双方私下调解，避免当众激化矛盾。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_01','V1020','阮明',1,'小宇，你快过来一下，策划部两位同学吵得特别凶，谁都不肯让步啊。','xiǎo yǔ， nǐ kuài guò lái yī xià， cè huà bù liǎng wèi tóng xué chǎo dé tè bié xiōng， shéi dōu bù kěn ràng bù a。','Tiểu Vũ ơi, cậu qua đây nhanh lên, hai bạn bên ban tổ chức đang cãi nhau dữ lắm, không ai chịu nhường ai cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_02','V1020','小宇',2,'怎么回事？活动现场还有这么多新生，吵起来影响太不好了吧。','zěn me huí shì？ huó dòng xiàn chǎng hái yǒu zhè me duō xīn shēng， chǎo qǐ lái yǐng xiǎng tài bù hǎo le ba。','Chuyện gì vậy? Ở hiện trường sự kiện còn bao nhiêu tân sinh viên, cãi nhau vậy ảnh hưởng không hay chút nào đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_03','V1020','阮明',3,'两人对活动预算分配意见不合，声音越来越大，周围同学都在围观。','liǎng rén duì huó dòng yù suàn fēn pèi yì jiàn bù hé， shēng yīn yuè lái yuè dà， zhōu wéi tóng xué dōu zài wéi guān。','Hai người bất đồng về việc phân bổ ngân sách hoạt động, càng nói càng to tiếng, xung quanh mọi người đứng xem đông lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_04','V1020','小宇',4,'你先把两人分开，分别带到两边休息室，别在大厅当众争执。','nǐ xiān bǎ liǎng rén fēn kāi， fēn bié dài dào liǎng biān xiū xī shì， bié zài dà tīng dāng zhòng zhēng zhí。','Cậu tách hai người ra trước đi, dẫn mỗi người vào một phòng nghỉ riêng, đừng để họ cãi nhau ngay giữa sảnh thế này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_05','V1020','阮明',5,'我劝了半天，两人情绪都很激动，根本不愿意冷静沟通呢。','wǒ quàn le bàn tiān， liǎng rén qíng xù dōu hěn jī dòng， gēn běn bù yuàn yì lěng jìng gōu tōng ne。','Mình khuyên mãi mà cả hai đều đang kích động lắm, chẳng chịu bình tĩnh nói chuyện gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_06','V1020','小宇',6,'我现在过去单独跟他们谈话，你帮忙安抚一下围观的新生。','wǒ xiàn zài guò qù dān dú gēn tā men tán huà， nǐ bāng máng ān fǔ yī xià wéi guān de xīn shēng。','Giờ mình qua nói chuyện riêng với từng người, cậu giúp trấn an mấy bạn tân sinh viên đang đứng xem nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_07','V1020','阮明',7,'没问题，我先转移大家注意力，避免场面变得更尴尬。','méi wèn tí， wǒ xiān zhuǎn yí dà jiā zhù yì lì， bì miǎn chǎng miàn biàn dé gèng gān gà。','Được, để mình hướng sự chú ý của mọi người đi chỗ khác, tránh tình hình thêm lúng túng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_08','V1020','小宇',8,'辛苦你了，社团有矛盾及时告诉我，别任由冲突发酵。','xīn kǔ nǐ le， shè tuán yǒu máo dùn jí shí gào sù wǒ， bié rèn yóu chōng tū fā jiào。','Cậu vất vả rồi, sau này câu lạc bộ có mâu thuẫn gì thì báo mình ngay, đừng để xung đột âm ỉ lâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1021','SKC1','自习室同学突发癫痫，疏散人群、联系校医、维持现场秩序',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1021','SIT1021','P1','suon_se','ban_chinh_thuc',NULL,'国内校园普及癫痫急救基础常识，发病时禁止强行束缚患者肢体，保持通风、清理周边硬物是基础急救方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_01','V1021','阮明',1,'思琪学姐，这边有位同学突然倒地抽搐，像是癫痫发作了！','sī qí xué jiě， zhè biān yǒu wèi tóng xué tū rán dǎo dì chōu chù， xiàng shì diān xián fā zuò le！','Chị Tư Kỳ ơi, ở đây có một bạn đột nhiên ngã xuống co giật, có vẻ như đang lên cơn động kinh!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_02','V1021','思琪',2,'大家先不要围过来，全部后退留出通风空间，别挤在这里啊。','dà jiā xiān bú yào wéi guò lái， quán bù hòu tuì liú chū tōng fēng kōng jiān， bié jǐ zài zhè lǐ a。','Mọi người đừng xúm lại, lùi ra hết để có chỗ thoáng khí, đừng chen chúc ở đây.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_03','V1021','阮明',3,'我已经把周围桌椅挪开，避免他磕碰受伤，现在要立刻联系校医吧？','wǒ yǐ jīng bǎ zhōu wéi zhuō yǐ nuó kāi， bì miǎn tā kē pèng shòu shāng， xiàn zài yào lì kè lián xì xiào yī ba？','Em đã dời bàn ghế xung quanh ra rồi để tránh bạn ấy va đập bị thương, giờ mình gọi ngay cho phòng y tế trường nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_04','V1021','思琪',4,'我马上拨打校医应急电话，你帮忙拿一件外套垫在他头下面。','wǒ mǎ shàng bō dǎ xiào yī yìng jí diàn huà， nǐ bāng máng ná yī jiàn wài tào diàn zài tā tóu xià miàn。','Chị gọi ngay số khẩn cấp của phòng y tế, em lấy giúp chị một cái áo khoác lót dưới đầu bạn ấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_05','V1021','阮明',5,'好，我按住他身边的桌椅，防止抽搐时撞到边角，现在意识不清醒呢。','hǎo， wǒ àn zhù tā shēn biān de zhuō yǐ， fáng zhǐ chōu chù shí zhuàng dào biān jiǎo， xiàn zài yì shí bù qīng xǐng ne。','Vâng, em giữ mấy cái bàn ghế bên cạnh bạn ấy để tránh lúc co giật va vào góc cạnh, giờ bạn ấy đang mất ý thức rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_06','V1021','思琪',6,'不要强行按压他的四肢，等校医过来再做专业处理，大家安静一点。','bú yào qiáng xíng àn yā tā de sì zhī， děng xiào yī guò lái zài zuò zhuān yè chǔ lǐ， dà jiā ān jìng yì diǎn。','Đừng cố giữ chặt tay chân bạn ấy, để bác sĩ trường đến xử lý chuyên môn, mọi người trật tự giúp chị một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_07','V1021','阮明',7,'我会维持秩序，不让围观同学上前触碰，等待医护人员到场。','wǒ huì wéi chí zhì xù， bù ràng wéi guān tóng xué shàng qián chù pèng， děng dài yī hù rén yuán dào chǎng。','Em sẽ giữ trật tự, không để các bạn đứng xem lại gần chạm vào, chờ nhân viên y tế đến.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_08','V1021','思琪',8,'多亏你及时发现，慌乱围观很容易给发病同学造成二次伤害。','duō kuī nǐ jí shí fā xiàn， huāng luàn wéi guān hěn róng yì gěi fā bìng tóng xué zào chéng èr cì shāng hài。','May mà em phát hiện kịp thời, chứ mọi người hoảng loạn xúm vào xem rất dễ khiến bạn ấy bị tổn thương thêm lần nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1022','SKC1','校外租房房东私自换锁不让进门，拨打社区民警协调房屋纠纷',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1022','SIT1022','P1','that_bai_nhe','chinh_thuc',NULL,'租房纠纷属于民事纠纷，民警仅负责现场调解，无权强制破门，双方无法达成一致需走法院民事诉讼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_01','V1022','阮明',1,'王警官您好，我租的房子房东私自更换门锁，不让我进屋拿个人物品。','wáng jǐng guān nín hǎo， wǒ zū de fáng zi fáng dōng sī zì gēng huàn mén suǒ， bù ràng wǒ jìn wū ná gè rén wù pǐn。','Chào đồng chí công an Vương, chủ nhà tôi thuê tự ý thay khóa cửa, không cho tôi vào lấy đồ đạc cá nhân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_02','V1022','王民警',2,'出示你的租房合同、身份证件，跟我说清楚房东换锁的原因吧。','chū shì nǐ de zū fáng hé tóng、 shēn fèn zhèng jiàn， gēn wǒ shuō qīng chǔ fáng dōng huàn suǒ de yuán yīn ba。','Anh/chị đưa hợp đồng thuê nhà và giấy tờ tùy thân, rồi nói rõ cho tôi lý do chủ nhà đổi khóa.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_03','V1022','阮明',3,'房租我按时足额缴纳，房东单方面想涨租，我没同意就直接换锁了啊。','fáng zū wǒ àn shí zú é jiǎo nà， fáng dōng dān fāng miàn xiǎng zhǎng zū， wǒ méi tóng yì jiù zhí jiē huàn suǒ le a。','Tiền thuê nhà tôi đóng đúng hạn đầy đủ, chủ nhà đơn phương muốn tăng giá thuê, tôi không đồng ý thì họ liền đổi khóa luôn.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_04','V1022','王民警',4,'私自换锁扣押租客私人物品属于违规，我现在联系房东到场调解。','sī zì huàn suǒ kòu yā zū kè sī rén wù pǐn shǔ yú wéi guī， wǒ xiàn zài lián xì fáng dōng dào chǎng tiáo jiě。','Việc tự ý đổi khóa và giữ đồ đạc cá nhân của người thuê là vi phạm, tôi sẽ liên hệ chủ nhà đến để hòa giải ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_05','V1022','阮明',5,'我的电脑、居留卡全都放在屋内，今晚没地方住，能不能先进屋拿东西？','wǒ de diàn nǎo、 jū liú kǎ quán dōu fàng zài wū nèi， jīn wǎn méi dì fāng zhù， néng bù néng xiān jìn wū ná dōng xī？','Máy tính, thẻ cư trú của tôi đều để trong nhà cả, tối nay tôi không có chỗ ở, có thể cho tôi vào lấy đồ trước được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_06','V1022','王民警',6,'调解需要双方到场，房东半小时后才能过来，暂时无法开门。','tiáo jiě xū yào shuāng fāng dào chǎng， fáng dōng bàn xiǎo shí hòu cái néng guò lái， zàn shí wú fǎ kāi mén。','Việc hòa giải cần cả hai bên có mặt, chủ nhà nửa tiếng nữa mới tới được, nên tạm thời chưa thể mở cửa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_07','V1022','阮明',7,'那我今晚只能临时住酒店，贵重证件都在房间里，实在不放心。','nà wǒ jīn wǎn zhǐ néng lín shí zhù jiǔ diàn， guì zhòng zhèng jiàn dōu zài fáng jiān lǐ， shí zài bù fàng xīn。','Vậy tối nay tôi đành tạm ở khách sạn, nhưng giấy tờ quan trọng đều ở trong phòng, tôi thực sự không yên tâm chút nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_08','V1022','王民警',8,'我全程在场调解，等房东到场后优先让你取出随身重要证件。','wǒ quán chéng zài chǎng tiáo jiě， děng fáng dōng dào chǎng hòu yōu xiān ràng nǐ qǔ chū suí shēn zhòng yào zhèng jiàn。','Tôi sẽ có mặt hòa giải từ đầu đến cuối, đợi chủ nhà đến sẽ ưu tiên cho anh/chị lấy giấy tờ quan trọng mang theo người trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1023','SKC1','校医院无法处理急症，拨打120同时同步告知国际学院辅导员',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1023','SIT1023','P1','suon_se','ban_chinh_thuc',NULL,'国内高校校医院仅处理轻症，重症统一转送综合医院，留学生可凭留学生医保报销部分急诊费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_01','V1023','阮明',1,'李导，我现在在校医院，医生说我的急症这里处理不了，已经拨打120送综合医院了。','lǐ dǎo， wǒ xiàn zài zài xiào yī yuàn， yī shēng shuō wǒ de jí zhèng zhè lǐ chǔ lǐ bù liǎo， yǐ jīng bō dǎ 120 sòng zōng hé yī yuàn le。','Cô Lý ơi, em đang ở phòng y tế trường, bác sĩ nói bệnh cấp của em ở đây không xử lý được, em đã gọi 120 để chuyển sang bệnh viện đa khoa rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_02','V1023','李辅导员',2,'是什么急症？救护车大概多久能到达校门口呢？','shì shén me jí zhèng？ jiù hù chē dà gài duō jiǔ néng dào dá xiào mén kǒu ne？','Là bệnh gì vậy? Xe cứu thương khoảng bao lâu nữa thì đến cổng trường?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_03','V1023','阮明',3,'急性肠胃炎伴随剧烈脱水，校医院缺少输液设备，救护车十分钟就到啦。','jí xìng cháng wèi yán bàn suí jù liè tuō shuǐ， xiào yī yuàn quē shǎo shū yè shè bèi， jiù hù chē shí fēn zhōng jiù dào la。','Viêm dạ dày ruột cấp kèm mất nước nặng, phòng y tế trường lại thiếu thiết bị truyền dịch, xe cứu thương mười phút nữa là tới rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_04','V1023','李辅导员',4,'我现在登记你的情况，等下会跟急诊医院说明你留学生身份。','wǒ xiàn zài dēng jì nǐ de qíng kuàng， děng xià huì gēn jí zhěn yī yuàn shuō míng nǐ liú xué shēng shēn fèn。','Cô ghi nhận tình hình của em ngay đây, lát nữa sẽ báo với bệnh viện cấp cứu về thân phận du học sinh của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_05','V1023','阮明',5,'我一个人等救护车，居留卡、学生证都随身带着，方便登记就诊。','wǒ yí gè rén děng jiù hù chē， jū liú kǎ、 xué shēng zhèng dōu suí shēn dài zhe， fāng biàn dēng jì jiù zhěn。','Em một mình chờ xe cứu thương, thẻ cư trú và thẻ sinh viên em mang theo người hết rồi, để tiện đăng ký khám.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_06','V1023','李辅导员',6,'我处理完手头工作就赶去医院，有任何不舒服随时给我打电话。','wǒ chǔ lǐ wán shǒu tóu gōng zuò jiù gǎn qù yī yuàn， yǒu rèn hé bù shū fú suí shí gěi wǒ dǎ diàn huà。','Cô xử lý xong việc đang làm là chạy đến bệnh viện ngay, có gì khó chịu thì gọi cho cô bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_07','V1023','阮明',7,'好，麻烦您了，就医缴费相关流程我不太清楚，到时候还要请教您。','hǎo， má fán nín le， jiù yī jiǎo fèi xiāng guān liú chéng wǒ bù tài qīng chǔ， dào shí hòu hái yào qǐng jiào nín。','Dạ vâng, phiền cô rồi ạ, quy trình khám chữa bệnh và đóng tiền em không rành lắm, lát nữa còn phải hỏi cô.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_08','V1023','李辅导员',8,'放心，留学生医保报销材料我之后会发给你，安心就医就好。','fàng xīn， liú xué shēng yī bǎo bào xiāo cái liào wǒ zhī hòu huì fā gěi nǐ， ān xīn jiù yī jiù hǎo。','Yên tâm đi, hồ sơ bảo hiểm y tế dành cho du học sinh để làm thủ tục hoàn tiền, cô sẽ gửi cho em sau, cứ yên tâm chữa bệnh trước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1024','SKC1','异地就医刷卡银行卡被风控冻结，紧急致电银行客服解锁',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1024','SIT1024','P1','twist','chinh_thuc',NULL,'国内银行卡异地大额消费易触发风控冻结，线上临时解锁额度有限，大额资金解冻必须线下网点核验身份。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_01','V1024','阮明',1,'您好，我现在在外地医院缴费，银行卡刷卡提示账户被风控冻结，急需解锁。','nín hǎo， wǒ xiàn zài zài wài dì yī yuàn jiǎo fèi， yín háng kǎ shuā kǎ tí shì zhàng hù bèi fēng kòng dòng jié， jí xū jiě suǒ。','Xin chào, tôi hiện đang đóng viện phí ở bệnh viện tại một tỉnh khác, thẻ ngân hàng khi quẹt báo tài khoản bị kiểm soát rủi ro và đóng băng, tôi cần mở khóa gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_02','V1024','客服',2,'请核实你的银行卡号、预留手机号、身份证/居留证件后四位。','qǐng hé shí nǐ de yín háng kǎ hào、 yù liú shǒu jī hào、 shēn fèn zhèng / jū liú zhèng jiàn hòu sì wèi。','Vui lòng cho tôi xác nhận số thẻ ngân hàng, số điện thoại đăng ký và bốn số cuối của chứng minh thư/thẻ cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_03','V1024','阮明',3,'卡号6217开头，预留手机号138XXXX2741，证件后四位3152，现在要付医药费啊。','kǎ hào 6217 kāi tóu， yù liú shǒu jī hào 138XXXX2741， zhèng jiàn hòu sì wèi 3152， xiàn zài yào fù yī yào fèi a。','Số thẻ bắt đầu bằng 6217, số điện thoại đăng ký là 138XXXX2741, bốn số cuối giấy tờ là 3152, tôi đang cần thanh toán tiền thuốc đây.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_04','V1024','客服',4,'系统检测到异地大额消费，自动触发风控保护，线上临时解锁有每日限额。','xì tǒng jiǎn cè dào yì dì dà é xiāo fèi， zì dòng chù fā fēng kòng bǎo hù， xiàn shàng lín shí jiě suǒ yǒu měi rì xiàn é。','Hệ thống phát hiện giao dịch số tiền lớn ở khu vực khác nên tự động kích hoạt bảo vệ rủi ro, việc mở khóa tạm thời trực tuyến có hạn mức mỗi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_05','V1024','阮明',5,'医药费需要两千多元，临时限额只有一千，根本不够支付诊疗费用呢。','yī yào fèi xū yào liǎng qiān duō yuán， lín shí xiàn é zhǐ yǒu yī qiān， gēn běn bù gòu zhī fù zhěn liáo fèi yòng ne。','Tiền thuốc cần hơn hai nghìn tệ, mà hạn mức tạm thời chỉ có một nghìn, không đủ để thanh toán tiền khám chữa bệnh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_06','V1024','客服',6,'线上解锁额度不足，需要你携带证件到线下网点办理全额解封。','xiàn shàng jiě suǒ é dù bù zú， xū yào nǐ xié dài zhèng jiàn dào xiàn xià wǎng diǎn bàn lǐ quán é jiě fēng。','Hạn mức mở khóa trực tuyến không đủ, anh/chị cần mang giấy tờ đến quầy giao dịch trực tiếp để mở khóa toàn bộ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_07','V1024','阮明',7,'我现在在医院没法出门，有没有别的办法临时提高支付额度？','wǒ xiàn zài zài yī yuàn méi fǎ chū mén， yǒu méi yǒu bié de bàn fǎ lín shí tí gāo zhī fù é dù？','Tôi đang ở bệnh viện không thể ra ngoài được, có cách nào khác để tạm thời nâng hạn mức thanh toán không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_08','V1024','客服',8,'实在抱歉，风控规则无法线上调整，建议你更换其他银行卡缴费。','shí zài bào qiàn， fēng kòng guī zé wú fǎ xiàn shàng diào zhěng， jiàn yì nǐ gēng huàn qí tā yín háng kǎ jiǎo fèi。','Thực sự xin lỗi, quy định kiểm soát rủi ro không thể điều chỉnh trực tuyến, đề nghị anh/chị dùng thẻ ngân hàng khác để thanh toán.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1025','SKC1','长途火车大面积晚点错过签证预约，向出入境窗口说明延误申请补受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1025','SIT1025','P1','that_bai_nhe','chinh_thuc',NULL,'政务大厅预约号严格分时段管控，交通延误仅可优先预约次日时段，无法直接当日插队办理业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_01','V1025','阮明',1,'吴主管您好，我原本今天预约办理签证续签，但是火车大面积晚点，错过了预约时段。','wú zhǔ guǎn nín hǎo， wǒ yuán běn jīn tiān yù yuē bàn lǐ qiān zhèng xù qiān， dàn shì huǒ chē dà miàn jī wǎn diǎn， cuò guò le yù yuē shí duàn。','Chào chị Ngô, tôi vốn định hôm nay đến làm thủ tục gia hạn visa theo lịch hẹn, nhưng tàu hỏa bị chậm trên diện rộng nên tôi lỡ mất khung giờ hẹn rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_02','V1025','吴主管',2,'先出示你的火车票晚点证明、预约回执，我先核实你的情况吧。','xiān chū shì nǐ de huǒ chē piào wǎn diǎn zhèng míng、 yù yuē huí zhí， wǒ xiān hé shí nǐ de qíng kuàng ba。','Anh/chị đưa giấy xác nhận tàu chậm và phiếu hẹn ra trước đã, để tôi kiểm tra tình hình của anh/chị.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_03','V1025','阮明',3,'铁路官方短信晚点通知我带来了，路上延误三个小时，赶到大厅已经过号了啊。','tiě lù guān fāng duǎn xìn wǎn diǎn tōng zhī wǒ dài lái le， lù shàng yán wù sān gè xiǎo shí， gǎn dào dà tīng yǐ jīng guò hào le a。','Tôi có mang theo tin nhắn thông báo tàu chậm chính thức của đường sắt đây, đường đi bị trễ mất ba tiếng, đến được sảnh thì đã quá số rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_04','V1025','吴主管',4,'每日预约名额系统固定，当日过号无特殊事由不能现场插队办理。','měi rì yù yuē míng é xì tǒng gù dìng， dāng rì guò hào wú tè shū shì yóu bù néng xiàn chǎng chā duì bàn lǐ。','Số lượng hẹn mỗi ngày là do hệ thống cố định, nếu trong ngày quá số mà không có lý do đặc biệt thì không thể chen vào xử lý trực tiếp được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_05','V1025','阮明',5,'我下周就要出境参加交换项目，错过今天只能再等一周预约，时间来不及。','wǒ xià zhōu jiù yào chū jìng cān jiā jiāo huàn xiàng mù， cuò guò jīn tiān zhǐ néng zài děng yī zhōu yù yuē， shí jiān lái bù jí。','Tuần sau tôi phải xuất cảnh để tham gia chương trình trao đổi rồi, nếu lỡ hôm nay thì chỉ còn cách chờ thêm một tuần nữa mới hẹn được, thời gian không kịp mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_06','V1025','吴主管',6,'火车晚点不属于法定加急事由，只能帮你优先预约明天最早时段号。','huǒ chē wǎn diǎn bù shǔ yú fǎ dìng jiā jí shì yóu， zhǐ néng bāng nǐ yōu xiān yù yuē míng tiān zuì zǎo shí duàn hào。','Tàu chậm không thuộc diện lý do khẩn cấp theo quy định, tôi chỉ có thể sắp xếp ưu tiên cho anh/chị lấy số sớm nhất vào ngày mai thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_07','V1025','阮明',7,'明天最早预约号是几点？我一定提前两小时到场，不会再迟到。','míng tiān zuì zǎo yù yuē hào shì jǐ diǎn？ wǒ yí dìng tí qián liǎng xiǎo shí dào chǎng， bú huì zài chí dào。','Số hẹn sớm nhất ngày mai là mấy giờ vậy ạ? Tôi chắc chắn sẽ đến sớm trước hai tiếng, sẽ không trễ nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_08','V1025','吴主管',8,'早上八点第一号，我给你做优先标记，明天直接凭身份证取号。','zǎo shàng bā diǎn dì yī hào， wǒ gěi nǐ zuò yōu xiān biāo jì， míng tiān zhí jiē píng shēn fèn zhèng qǔ hào。','Số một lúc tám giờ sáng, tôi sẽ đánh dấu ưu tiên cho anh/chị, ngày mai cứ mang chứng minh thư đến lấy số trực tiếp là được.',NULL);
